COLLDATA("abudawud","ur",[[1673,"جابر بن عبداللہ انصاری رضی اللہ عنہما کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے کہ ایک شخص انڈہ کے برابر سونا لے کر آیا اور بولا: اللہ کے رسول! مجھے یہ ایک کان میں سے ملا ہے، آپ اسے لے لیجئے، یہ صدقہ ہے اور اس کے علاوہ میں کسی اور چیز کا مالک نہیں، رسول اللہ صلی اللہ علیہ وسلم نے اس سے منہ پھیر لیا، وہ پھر آپ صلی اللہ علیہ وسلم کے پاس آپ کی دائیں جانب سے آیا اور ایسا ہی کہا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے منہ پھیر لیا، پھر وہ آپ صلی اللہ علیہ وسلم کے پاس آپ کی بائیں جانب سے آیا، رسول اللہ صلی اللہ علیہ وسلم نے پھر اس سے منہ پھیر لیا، پھر وہ آپ صلی اللہ علیہ وسلم کے پیچھے سے آیا آپ نے اسے لے کر پھینک دیا، اگر وہ اسے لگ جاتا تو اس کو چوٹ پہنچاتا یا زخمی کر دیتا، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں ایک اپنا سارا مال لے کر چلا آتا ہے اور کہتا ہے: یہ صدقہ ہے، پھر بیٹھ کر لوگوں کے سامنے ہاتھ پھیلاتا ہے، بہترین صدقہ وہ ہے جس کا مالک صدقہ دے کر مالدار رہے\"۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ انصاری رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں تھے کہ اچانک ایک آدمی آیا، اس کے پاس انڈے کے برابر سونا تھا، کہنے لگا: اے اللہ کے رسول! مجھے یہ ایک کان سے ملا ہے آپ صلی اللہ علیہ وسلم اسے لے لیجئے یہ صدقہ ہے، میرے پاس اس کے علاوہ اور کچھ نہیں ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منہ پھیر لیا، تو وہ آپ صلی اللہ علیہ وسلم کی دائیں جانب سے آیا اور پہلے کی طرح کہا۔ آپ صلی اللہ علیہ وسلم نے اس سے منہ پھیر لیا۔ تو وہ آپ صلی اللہ علیہ وسلم کی بائیں جانب سے آیا تو رسول اللہ صلی اللہ علیہ وسلم نے منہ پھیر لیا۔ پھر وہ آپ صلی اللہ علیہ وسلم کے پیچھے سے آیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے وہ سونا لے کر پھینک دیا۔ اگر وہ اسے لگتا تو اس سے اس کو چوٹ لگتی بلکہ وہ اسے زخمی کر دیتا۔ تب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی اپنا سب مال لے کر آ جاتا ہے اور کہتا ہے کہ یہ صدقہ ہے۔ پھر لوگوں سے مانگنے بیٹھ جاتا ہے۔ بہترین صدقہ وہی ہے جو اپنی ضرورت پوری کرنے کے بعد دیا جائے۔ “","f2":"اس روایت کا صرف آخری جملہ صحیح اور ثابت ہے۔ اور آئندہ حدیث 1676 میں آرہا ہے۔ اس لئے یہ واقعہ تو صحیح نہیں ہے۔لیکن اس میں رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب قول کا مفہوم ومعنی دوسرے دلائل سے ثابت ہے۔"}],[1674,"اس سند سے بھی ابن اسحاق سے اسی مفہوم کی حدیث اسی طریق سے مروی ہے البتہ اس میں اتنا اضافہ ہے: «خذ عنا مالك لا حاجة لنا به» \"اپنا مال ہم سے لے لو ہمیں اس کی ضرورت نہیں\"۔","ضعیف",{"u2":"ابن اسحٰق نے اپنی مذکورہ سند سے اور اسی کے ہم معنی بیان کیا۔ اس میں مزید یہ ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہم سے اپنا مال لے جاؤ ہمیں اس کی کوئی ضرورت نہیں۔ “ (نبی کریم صلی اللہ علیہ وسلم نے اسے قبول نہیں فرمایا۔)","f2":"ایسا صدقہ یا کوئی نیکی جو جذبات میں آکر کی جائے۔ مگر اس کے ظاہری اثرات اس کے کرنے والے کی برداشت سے باہر ہوں۔ کہ بعد میں اس پرافسوس کرنے لگے۔ یا وہ نیکی ہی اسے بُری لگنے لگے۔ تو یہ بہت بُری کیفیت ہے۔ انسان کو پہلے سوچ کر قدم اُٹھانا چاہیے۔ بالخصوص صدقات کے معاملہ میں اور کچھ نام نہاد صوفیاء میں یہ بات موجود ہے۔ کہ پہلے اپنا سب کچھ لنگر میں دے دیتے ہیں۔ پھر لوگوں سے بٹورنا شروع کردیتے ہیں۔ ولا حول ولا قوۃالا باللہ۔مگرایسے مخلصین جو اللہ پر کامل توکل رکھتے ہوں۔ انہیں کسی ملال کا اندیشہ نہ ہو تو ان کے لئے اپنا تمام مال صدقہ کردینے کی رخصت بھی ہے۔ جیسے کے اگلے باب میں آرہا ہے۔"}],[1675,"ابوسعید خدری رضی اللہ عنہ کہتے ہیں کہ ایک شخص مسجد میں داخل ہوا تو نبی اکرم صلی اللہ علیہ وسلم نے لوگوں کو حکم دیا کہ وہ کپڑے(بطور صدقہ) ڈال دیں، انہوں نے ڈال دیا، پھر آپ صلی اللہ علیہ وسلم نے اس شخص کے لیے ان میں سے دو کپڑوں (کے دیئے جانے)کا حکم دیا، پھر آپ صلی اللہ علیہ وسلم نے لوگوں کو صدقہ پر ابھارا تو وہ شخص دو میں سے ایک کپڑا ڈالنے لگا، آپ نے اسے ڈانٹا اور فرمایا:\"اپنے کپڑے لے لو ۱؎\"۔\n§وضاحت\n۱؎ : رسول اللہ صلی اللہ علیہ وسلم نے اس آدمی کا صدقہ قبول نہیں کیا کیونکہ اس کو صرف دو کپڑے ملے تھے اور وہ اس کی ضرورت سے زائد نہیں تھے۔","حسن",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی مسجد میں داخل ہوا تو نبی کریم صلی اللہ علیہ وسلم نے لوگوں کو حکم دیا کہ کپڑے دو (صدقہ کے طور پر) اور اس (آنے والے) کے بارے میں فرمایا کہ اسے دو کپڑے دے دو۔ آپ صلی اللہ علیہ وسلم نے پھر (دوبارہ) صدقے کی ترغیب دی تو اس شخص نے بھی اپنا ایک کپڑا پھینک دیا۔ آپ صلی اللہ علیہ وسلم نے اسے ڈانٹ کر فرمایا ” اپنا کپڑا اٹھا لو۔ “","f2":"اس کی وضاحت درج زیل حدیث میں ہے۔"}],[1676,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہترین صدقہ وہ ہے جو آدمی کو مالدار باقی رکھے یا (یوں فرمایا)وہ صدقہ ہے جسے دینے کے بعد مالک مالدار رہے اور صدقہ پہلے اسے دو جس کی تم کفالت کرتے ہو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ بہترین صدقہ وہ ہے جو غنا (لوگوں سے بے نیازی) کو باقی رہنے دے یا یہ کہ اس کیفیت میں صدقہ کیا جائے کہ خود محتاج اور ضرورت مند نہ ہو (بلکہ غنی ہو) اور ان سے شروع کرو جن کی کفالت کے تم ذمہ دار ہو۔ “","f2":"مطلب یہ ہے کہ صدقہ کرنے کے بعد اگر انسان خود ہی اپنی بنیادی ضروریات کے پورا کرنے کےلئے دوسروں کا محتاج ہوجائے تو ایسا صدقہ ناپسندیدہ ہے۔ اس لئے بہترین صدقہ اسے قرار دیا گیا ہے کہ وہ دینے کے بعد انسان دوسروں کا محتاج نہ ہو۔"}],[1677,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! کون سا صدقہ افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کم مال والے کا تکلیف اٹھا کر دینا اور پہلے ان لوگوں کو دو جن کا تم خرچ اٹھاتے ہو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے، انہوں نے پوچھا کہ اے اللہ کے رسول! کون سا صدقہ افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” کم مال والے کا محنت مشقت کر کے دینا اور شروع ان سے کرو جن کی کفالت کے تم ذمہ دار ہو۔ “","f2":"جو شخص کفاف کی حالت میں ہو کہ تازہ مذدوری کرکے لائے اور پھر اسی میں سے صدقہ بھی کرے۔ تو یہ اس کے اللہ والا ہونے کی عظیم دلیل ہے۔ ایسا شخص یقیناً کامل متوکل علی اللہ اور جنت کا حریص ہے۔ ایسا صدقہ اپنی ظاہری برکات بھی لاتا ہے۔ مگرساتھ ہی اس میں یہ تعلیم بھی ہے۔ کہ اپنے زیر کفالت افراد سے شروع کیاجائے۔ان پرخرچ کرنے کا دہرا ثواب ہے۔"}],[1678,"اسلم کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو کہتے سنا کہ ایک دن ہمیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ ہم صدقہ کریں، اتفاق سے اس وقت میرے پاس دولت تھی، میں نے کہا: اگر میں کسی دن ابوبکر رضی اللہ عنہ پر سبقت لے جا سکوں گا تو آج کا دن ہو گا، چنانچہ میں اپنا آدھا مال لے کر آیا، رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: \"اپنے گھر والوں کے لیے تم نے کیا چھوڑا ہے؟\"، میں نے کہا: اسی قدر یعنی آدھا مال، اور ابوبکر رضی اللہ عنہ اپنا سارا مال لے کر حاضر ہوئے، رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"اپنے گھر والوں کے لیے تم نے کیا چھوڑا ہے؟\"، انہوں نے کہا میں ان کے لیے اللہ اور اس کے رسول کو چھوڑ کر آیا ہوں۱؎، تب میں نے (دل میں) کہا: میں آپ سے کبھی بھی کسی معاملے میں نہیں بڑھ سکوں گا۔\n§وضاحت\n۱؎ : گذشتہ باب کی حدیثوں سے یہ ثابت ہوتا ہے کہ سارا مال اللہ کی راہ میں دینے سے اللہ کے رسول نے روکا ہے، جب کہ باب کی اس حدیث سے پتہ چلتا ہے کہ ابوبکر رضی اللہ عنہ نے اپنی پوری دولت اللہ کی راہ میں دے دی، اور یہ بات آپ کی فضیلت و بزرگی کا باعث بھی بنی، اس کا جواب یہ دیا جاتا ہے کہ ممانعت کا حکم ایسے لوگوں کے لئے ہے جن کے اعتماد اور توکل میں کمزوری ہو، اور وہ مال دینے کے بعد مفلسی سے گھبرائیں اور ندامت و شرمندگی محسوس کریں، لیکن اس کے برخلاف اگر کسی شخص کے اندر ابوبکر رضی اللہ عنہ جیسا جذبہ، اللہ کی ذات پر اعتماد و توکل ہو تو اس کے لئے اس کام میں کوئی حرج نہیں بلکہ باعث خیر و برکت ہو گا، ان شاء اللہ۔","حسن",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ہمیں صدقہ کرنے کا حکم دیا۔ اس موقع پر میرے پاس مال بھی تھا۔ چنانچہ میں نے (دل میں) کہا: اگر میں ابوبکر رضی اللہ عنہ سے سبقت لینا چاہوں تو آج لے سکتا ہوں۔ چنانچہ میں اپنا آدھا مال (آپ صلی اللہ علیہ وسلم کی خدمت میں) لے آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا ” تم نے اپنے گھر والوں کے لیے کیا باقی چھوڑا ہے؟ “ میں نے کہا: اسی قدر (چھوڑ آیا ہوں) اور پھر سیدنا ابوبکر رضی اللہ عنہ اپنا کل مال (آپ صلی اللہ علیہ وسلم کے پاس) لے آئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا ” تم نے اپنے گھر والوں کے لیے کیا باقی چھوڑا ہے؟ “ کہا: میں نے ان کے لیے اللہ اور اس کے رسول کو چھوڑا ہے۔ تب مجھے کہنا پڑا، میں کسی شے میں کبھی بھی ان سے نہیں بڑھ سکتا۔","f2":"-1جو حضرات متوکل اور دل کے غنی ہوں۔ کہ کل مال صدقہ کرنے کی وجہ سے آنے والے فقر کو بخوشی قبول اور برداشت کرسکتے ہوں۔ ان کو ایسے عمل کی رخصت ہے۔ ورنہ عام لوگوں کے لئے وہی حکم ہے۔ جو حدیث 16 76 اور اس کے فائدے میں بیان ہوا ہے۔ نیز اسی حدیث میں صاحبین کی فضیلت اور حضرت ابو بکر رضی اللہ تعالیٰ عنہ کی افضلیت کا بیان ہے۔2۔یہ حدیث نیکی کے کاموں میں مسابقت اور مقابلہ کرنے پر دلالت کرتی ہے۔"}],[1679,"سعد بن عبادہ انصاری خزرجی رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: کون سا صدقہ آپ کو زیادہ پسند ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پانی (کا صدقہ)\" ۱؎۔\n§وضاحت\n۱؎ : پانی کا صدقہ: مثلاً کنواں کھدوانا، نل لگوانا، مسافروں، مصلیوں اور دیگر ضرورت مندوں کے لئے پانی کی سبیل لگانا۔","حسن",{"u2":"سیدنا سعد (سعد بن عبادہ) رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آئے اور پوچھا کہ آپ کے نزدیک کون ساتھ صدقہ زیادہ پسندیدہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” پانی۔ “"}],[1680,"اس سند سے بھی سعد بن عبادہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے اسی جیسی حدیث مروی ہے۔","حسن",{"u2":"محمد بن عبدالرحیم اپنی سند سے سیدنا سعد بن عبادہ رضی اللہ عنہ سے، وہ نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالاحدیث کی مانند روایت کرتے ہیں۔"}],[1681,"سعد بن عبادہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! ام سعد (میری ماں) انتقال کر گئیں ہیں تو کون سا صدقہ افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پانی\"۔ راوی کہتے ہیں: چنانچہ سعد نے ایک کنواں کھدوایا اور کہا: یہ ام سعد ۱؎ کا ہے۔\n§وضاحت\n۱؎ : یعنی اس کا ثواب ام سعد رضی اللہ عنہا کے لئے ہے۔","حسن",{"u2":"سیدنا سعد بن عبادہ رضی اللہ عنہ سے منقول ہے انہوں نے کہا: اے اللہ کے رسول! (میری والدہ) ام سعد فوت ہو گئی ہیں تو کون سا صدقہ افضل ہے؟ (جو میں ان کی طرف سے کروں) آپ صلی اللہ علیہ وسلم نے فرمایا ” پانی “ چنانچہ انہوں نے ایک کنواں کھدوایا اور کہا کہ یہ (میری والدہ) ام سعد کی طرف سے ہے۔","f2":"مرنے والے کی طرف سے مذکورہ بالا انداز میں مالی صدقہ ایصال ثواب کی شاندار مشروع مثال ہے۔خود ساختہ رسموں ریتوں اور بدعات نے صاف ستھرے پاکیزہ دین کو دھند لاکر کے رکھدیا ہے۔ یہ احادیث پانی کے صدقے کی فضیلت بھی واضح کرتی ہیں۔کہ انسانوں جانوروں مسافروں اور نمازیوں وغیرہ کےلئے ضرورت کی جگہ پر اس کا اہتمام بڑے اجر کا کام ہے۔"}],[1682,"ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس مسلمان نے کسی مسلمان کو کپڑا پہنایا جب کہ وہ ننگا تھا تو اللہ اسے جنت کے سبز کپڑے پہنائے گا، اور جس مسلمان نے کسی مسلمان کو کھلایا جب کہ وہ بھوکا تھا تو اللہ اسے جنت کے پھل کھلائے گا اور جس مسلمان نے کسی مسلمان کو پانی پلایا جب کہ وہ پیاسا تھا تو اللہ اسے (جنت کی) مہر بند شراب پلائے گا\"۔","ضعیف",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جو مسلمان کسی مسلمان کو کپڑا پہنائے جبکہ وہ ننگا ہو تو اللہ تعالیٰ اسے جنت کی سبز پوشاک پہنائے گا۔ اور جس مسلمان نے کسی مسلمان کو کھلایا جبکہ وہ بھوکا ہو تو اللہ اسے جنت کے پھلوں سے کھلائے گا۔ اور جس مسلمان نے کسی مسلمان کو پلایا جبکہ وہ پیاسا ہو تو اللہ اسے جنت کی خالص شراب سے پلائے گا۔ “"}],[1683,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چالیس خصلتیں ہیں ان میں سب سے بہتر خصلت بکری کا عطیہ دینا ہے، جو کوئی بھی ان میں سے کسی (خصلت نیک کام) کو ثواب کی امید سے اور (اللہ کی طرف سے) اپنے سے کئے ہوئے وعدے کو سچ سمجھ کر کرے گا اللہ اسے اس کی وجہ سے جنت میں داخل کرے گا\"۔ ابوداؤد کہتے ہیں: مسدد کی حدیث میں یہ بھی ہے کہ حسان کہتے ہیں: ہم نے بکری عطیہ دینے کے علاوہ بقیہ خصلتوں اعمال صالحہ کو گنا جیسے سلام کا جواب دینا، چھینک کا جواب دینا اور راستے سے کوئی بھی تکلیف دہ چیز ہٹا دینا وغیرہ تو ہم پندرہ خصلتوں تک بھی نہیں پہنچ سکے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” چالیس خصلتوں میں سے سب سے اعلیٰ خصلت ” دودھ کی بکری “ ہدیہ کرنا ہے، جو کوئی بندہ ان کے ثواب کی امید اور ان پر کیے گئے وعدے کی تصدیق کی بنا پر کسی ایک پر بھی عمل کر لے تو اللہ اسے اس کے سبب جنت میں داخل فرمائے گا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ مسدد کی روایت میں حسان بن عطیہ نے کہا: ہم نے دودھ کی بکری کے ہدیہ کے علاوہ (دیگر اعمال مثلا) سلام اور چھینک کا جواب دینا اور راستے سے اذیت والی چیز دور کرنا، وغیرہ شمار کرنے کی کوشش کی مگر پندرہ خصلتوں تک بھی نہیں پہنچ سکے۔ (معلوم نہیں وہ کون کون سی ہیں۔)","f2":"1۔(المنیحۃ) یا (المنحۃ) اس جانور یا چیز کو کہاجاتا ہے۔ جو کسی کو بطورعطیہ دی جائے۔ اس کی دو صورتیں ہیں پہلی یہ کہ وہ جانور یا چیز کلی طور پر کسی کو دے دینا اور خود اس کی ملکیت سے دستبردار ہوجانادوسری چیز یہ ہے کہ وہ چیز اپنی ہی ملکیت میں رکھنا۔ اور عارضی طور پرکسی کو افادے کےلئے دے دینا۔اور پھر بعد میں واپس لے لینا۔عطیے(منحۃ) کی یہ دونوں صورتیں جائز ہیں۔اسی سے (منحۃ الورق) ہے۔ چاندی یعنی روپیہ پیسہ بطور قرض دینا۔(منحۃ اللبن)دودھ ہدیہ کرنا۔۔۔یعنی اونٹنی بکری یا گائے بھینس دودھ کے دنوں میں استفادے کےلئے دے دینا بڑی فضیلت کاکام ہے۔ ایسے ہی پھل کے دنوں میں کوئی پھلدار درخت کسی ضرورت مند کو دے دینا یا کاشت کےلئے زمین دے دینا۔استفادے کے بعد یہ چیز اصل مالک کو لوٹ آتی ہے۔2۔حدیث میں مذکور خصائل کے علاوہ ایمان کی شاخیں۔جمعہ کےروز ساعت قبولیت اور لیلۃ القدر وغیرہ کو مخفی رکھا گیا ہے۔ حکمت یہ ہے کہ مسلمان ان کی طلب وتلاش میں زیادہ سے زیادہ کوشش کرتے رہیں۔کہیں ان مخصوص اعمال ہی میں محصور ہوکر نہ رہ جایئں۔"}],[1684,"ابوموسی رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"امانت دار خازن جو حکم کے مطابق پورا پورا خوشی خوشی اس شخص کو دیتا ہے جس کے لیے حکم دیا گیا ہے تو وہ بھی صدقہ کرنے والوں میں سے ایک ہے\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ امانت دار خزانچی جو مالک کے حکم کے مطابق دل کی خوشی سے پورا پورا دے، یہاں تک کہ جس کے متعلق کہا گیا ہے اسے دیدے، وہ دو صدقہ کرنے والوں میں سے ایک ہے۔ (ایک اصل مالک جس نے دینے کا حکم دیا اور دوسرا یہ جس نے ادا کیا)۔","f2":"ایسے خازن کےلئے مسلمان ہونے کے علاوہ چار شرطیں زکر کی گئی ہیں۔مالک کی اجازت خوشی سے دینا۔پورا پورا دینا اسے دینا جس کے بارے میں حکمدیا گیا۔نیز یہ بھی معلوم ہواکہ صدقہ کرنے والے کو اصل مالک کی ہدایات پر پورا پورا عمل کرنا چاہیے۔بغیر معقول عذر کے ان میں تبدیلی نہیں کرنی چاہیے۔"}],[1685,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت اپنے شوہر کے گھر سے کسی فساد کی نیت کے بغیر خرچ کرے تو اسے اس کا ثواب ملے گا اور مال کمانے کا ثواب اس کے شوہر کو اور خازن کو بھی اسی کے مثل ثواب ملے گا اور ان میں سے کوئی کسی کے ثواب کو کم نہیں کرے گا\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بیوی جب اپنے شوہر کے گھر سے خرچ کرے (صدقہ دے) جبکہ اسراف کرنے والی نہ ہو تو اسے صدقہ کرنے کا اور اس کے شوہر کو ک لانے کا ثواب ہے اور اس کے خزانچی کو بھی اسی قدر ہے، ان میں سے کوئی بھی کسی کا اجر کم نہیں کرتا۔ “","f2":"شوہر کی صریح اجازت نہ بھی ہوتو اس کے مزاج زوق عادت اور عرف سے سمجھی جاسکتی ہے۔ اور اس کے برعکس جہاں شوہر دینا چاہتا ہو مگر بیوی بخیل ہو۔۔۔اس کا حال خود سمجھا جاسکتا ہے۔"}],[1686,"سعد رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے عورتوں سے بیعت کی تو ایک موٹی عورت جو قبیلہ مضر کی لگتی تھی کھڑی ہوئی اور بولی: اللہ کے نبی! ہم (عورتیں) تو اپنے باپ اور بیٹوں پر بوجھ ہوتی ہیں۔ ابوداؤد کہتے ہیں: میرے خیال میں «أزواجنا» کا لفظ کہا (یعنی اپنے شوہروں پر بوجھ ہوتی ہیں)، ہمارے لیے ان کے مالوں میں سے کیا کچھ حلال ہے (کہ ہم خرچ کریں) ؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \" «رطب» ہے تم اسے کھاؤ اور ہدیہ بھی کرو\"۔ ابوداؤد کہتے ہیں: «رطب» روٹی، ترکاری اور تر کھجوریں ہیں۔ ابوداؤد کہتے ہیں: اور ثوری نے بھی یونس سے اسے اسی طرح روایت کیا ہے۔","ضعیف",{"u2":"سیدنا سعد (بن ابی وقاص) رضی اللہ عنہ سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے عورتوں سے بیعت لی تو ایک باوقار (یا لمبے قد والی) عورت کھڑی ہوئی، گویا کہ وہ قبیلہ مضر سے تھی، کہنے لگی: اے اللہ کے نبی! ہم تو اپنے ماں باپ، اپنے بیٹوں، امام ابوداؤد رضی اللہ عنہ نے کہا میرا خیال ہے اس نے شوہروں کا ذکر بھی کیا، پر بوجھ ہیں تو ہمارے لیے ان کے مالوں میں سے کیا حلال ہے؟ آپ نے فرمایا (تر چیزیں کھاؤ اور ہدیہ بھی دو۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «رطب» ” تر “ سے مراد روٹی، ترکاری اور تازہ کھجور ہے۔ امام ابوداؤد رضی اللہ عنہ نے فرمایا ثوری نے بھی یونس سے ایسے ہی روایت کی ہے۔"}],[1687,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت اپنے شوہر کی کمائی میں سے اس کی اجازت کے بغیر خرچ کرے تو اسے اس (شوہر) کا آدھا ثواب ملے گا ۱؎\"۔\n§وضاحت\n۱؎ : یہ اس مقدار پر محمول ہو گا جس کی عرفاً وعادۃً شوہر کی طرف سے بیوی کو خرچ کرنے کی اجازت ہوتی ہے، اگرچہ اس کی طرف سے صریح اجازت اسے حاصل نہ ہو، رہا اس سے زیادہ مقدار کا معاملہ تو شوہر کی صریح اجازت کے بغیر وہ اسے خرچ نہیں کر سکتی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب عورت اپنے خاوند کی کمائی سے اس کے کہے بغیر صدقہ دے تو اسے اس کے شوہر کا آدھا ثواب ہے۔ “","f2":"1۔گھر کے مالیات کی ترتیب وتنسیق کہ آمد وخرچ کاتوازن برقرار رہے۔شوہر کے واجبات میں سے ہے۔ اس لئے عرف وعادت سے بڑھ کر صدقہ کرنے کےلئے اجازت حاصل کرنا ضروری ہے۔صدقہ کردینے کے بعد اگر شوہر راضی ہو تو بیوی کےلئے نصف اجر ہے۔2۔عرف وعادت سے مراد ہمسایوں کو معمول کا سالن کھانا پہنچانا یا سائل کو دینا ہے یابعض اتفاقی امور ہیں۔"}],[1688,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ان سے کسی نے پوچھا، عورت بھی اپنے شوہر کے گھر سے صدقہ دے سکتی ہے؟ انہوں نے کہا: نہیں، البتہ اپنے خرچ میں سے دے سکتی ہے اور ثواب دونوں (میاں بیوی) کو ملے گا اور اس کے لیے یہ درست نہیں کہ شوہر کے مال میں سے اس کی اجازت کے بغیر صدقہ دے۔ ابوداؤد کہتے ہیں: یہ حدیث ہمام کی (پچھلی) حدیث کی تضعیف کرتی ہے ۱؎۔\n§وضاحت\n۱؎ : یہ عبارت سنن ابوداود کے اکثر نسخوں میں نہیں ہے، ہمام بن منبہ کی روایت صحیح ہے، اس کی تخریج بخاری و مسلم نے کی ہے، اس میں کوئی علت بھی نہیں ہے، لہٰذا ابوداود کا یہ کہنا کیسے صحیح ہو سکتا ہے جب کہ عطا سے مروی ابوہریرہ رضی اللہ عنہ کی یہ روایت موقوف ہے، اور دونوں روایتوں کے درمیان تطبیق بھی ممکن ہے جیسا کہ نووی نے شرح مسلم میں ذکر کیا ہے۔","صحیح موقوف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ (سے پوچھا گیا کہ) کیا عورت اپنے شوہر کے گھر سے صدقہ دے (یا نہ دے)؟ انہوں نے کیا نہیں، اپنے حصے کے خرچ سے دے سکتی ہے، (جو شوہر نے اسے دیا ہو۔) اور اجر ان دونوں کے مابین ہو گا۔ اور اس کے لیے حلال نہیں کہ شوہر کے مال سے اس کی اجازت کے بغیر صدقہ کرے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ سیدنا ابوہریرہ رضی اللہ عنہ کا یہ فتویٰ گویا سابقہ حدیث ہمام کی تضعیف ہے۔","f2":"صاحب عون المعبود لکھتے ہیں۔ کہ امام ابودائود رحمۃ اللہ علیہ کایہ آخری مقولہ اکثر نسخوں میں نہیں ہے۔بلکہ کچھ میں ہے۔جبکہ مذکورہ بالا حدیث ہمام بن منبہ بالکل عمدہ صحیح حدیث ہے۔اسے امام بخاری رحمۃ اللہ علیہ و امام مسلم رحمۃ اللہ علیہ نے روایت کیا ہے۔(صحیح البخاری النفقات حدیث 5360۔وصحیح مسلم الذکاۃ حدیث 1026) اس حدیث کے ہوتے ہوئے ان کا اپنا فتویٰ (موقوف روایت) مرفوع صحیح حدیث کو کیونکر ضعیف کرسکتاہے۔ویسے مذکورہ حدیث اور ان کے اس فتوے میں توفیق وتطبیق بھی ممکن ہے۔ کہ بیوی کو شوہر کی صریح اجازت کے بغیر عرف سے بڑھ کر صدقہ کرنا حلال نہیں کیونکہ اس گھریلو اخراجات کا نظام متاثر ہوتا ہے۔اس لئے اس پر گناہ ہوگا اور مرفوع روایت کے مطابق۔۔۔عدم اجازت کی صورت میں آدھا ملےگا بشرط یہ کہ معروف حد کے اندر اندر ہو۔"}],[1689,"انس رضی اللہ عنہ کہتے ہیں جب «لن تنالوا البر حتى تنفقوا مما تحبون» کی آیت نازل ہوئی تو ابوطلحہ رضی اللہ عنہ نے کہا: اللہ کے رسول! میرا خیال ہے کہ ہمارا رب ہم سے ہمارے مال مانگ رہا ہے، میں آپ کو گواہ بناتا ہوں کہ میں نے اریحاء نامی اپنی زمین اسے دے دی، اس پر رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اسے اپنے قرابت داروں میں تقسیم کر دو\"، تو انہوں نے اسے حسان بن ثابت اور ابی بن کعب رضی اللہ عنہما کے درمیان تقسیم کر دیا۔ ابوداؤد کہتے ہیں: مجھے محمد بن عبداللہ انصاری سے یہ بات معلوم ہوئی کہ ابوطلحہ کا نام: زید بن سہل بن اسود بن حرام بن عمرو ابن زید مناۃ بن عدی بن عمرو بن مالک بن النجار ہے، اور حسان: ثابت بن منذر بن حرام کے بیٹے ہیں، اس طرح ابوطلحہ رضی اللہ عنہ اور حسان رضی اللہ عنہ کا سلسلہ نسب حرام پر مل جاتا ہے وہی دونوں کے تیسرے باپ (پردادا) ہیں، اور ابی رضی اللہ عنہ کا سلسلہ نسب اس طرح ہے: ابی بن کعب بن قیس بن عتیک بن زید بن معاویہ بن عمرو بن مالک بن نجار، اس طرح عمرو: حسان، ابوطلحہ اور ابی تینوں کو سمیٹ لیتے ہیں یعنی تینوں کے جد اعلی ہیں، انصاری (محمد بن عبداللہ) کہتے ہیں: ابی رضی اللہ عنہ اور ابوطلحہ رضی اللہ عنہ کے نسب میں چھ آباء کا فاصلہ ہے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ جب آیت کریمہ «الن تنالوا البر حتى تنفقوا م تحبون» نازل ہوئی تو سیدنا ابوطلحہ رضی اللہ عنہ نے کہا: اے اللہ کے رسول! میں سمجھتا ہوں کہ ہمارا رب ہم سے ہمارے مال مانگتا ہے تو آپ گواہ رہیں کہ میں نے اپنی اریحا والی زمین اللہ کے لیے دی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسے اپنے قرابت داروں میں تقسیم کر دو۔ “ چنانچہ انہوں نے اسے حسان بن ثابت اور ابی بن کعب میں تقسیم کر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ مجھے انصاری محمد بن عبداللہ سے یہ بات پہنچی ہے کہ سیدنا ابوطلحہ رضی اللہ عنہ کا نسب یوں ہے ابوطلحہ زید بن سہل بن اسود بن حرام بن عمرو بن زید مناۃ بن عدی بن عمرو بن مالک بن نجار۔ اور سیدنا حسان رضی اللہ عنہ کا نسب اس طرح ہے حنان بن ثابت بن منذر بن حرام۔ ابوطلحہ اور حسان دونوں تیسرے باپ یعنی (پردادا) حرام پر جمع ہوتے ہیں۔ اور ابی رضی اللہ عنہ کا نسب یہ ہے ابی بن کعب بن قیس بن عتیک بن زید بن معاویہ بن عمرو بن مالک بن نجار۔ عمرو (عمرو بن مالک) ان تینوں کو جمع کرتا ہے۔ یعنی حسان، ابوطلحہ اور ابی کو۔ انصاری نے وضاحت کی کہ ابی اور ابوطلحہ میں چھٹے باپ میں جا کر رشتہ جڑتا ہے۔","f2":"کہاں یہ جاہلیت کے چچا تائے کی اولاد آپس میں حریف گرانے جاتے ہوں۔اور کہاں یہ محبت والفت کہ پر دادا بلکہ چھٹے باپ کی اولاد اس قدرحسن سلوک۔۔۔کہ قیمتی زمین ان کے نام لگادی۔اللہ تعالیٰ نے سورہ انفال میں سچ فرمایا۔ هُوَ الَّذِي أَيَّدَكَ بِنَصْرِهِ وَبِالْمُؤْمِنِينَ ﴿٦٢﴾ وَأَلَّفَ بَيْنَ قُلُوبِهِمْ ۚ لَوْ أَنفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَّا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَـٰكِنَّ اللَّـهَ أَلَّفَ بَيْنَهُمْ ۚ إِنَّهُ عَزِيزٌ حَكِيمٌ (الانفال۔62۔63)"}],[1690,"ام المؤمنین میمونہ رضی اللہ عنہا کہتی ہیں کہ میری ایک لونڈی تھی، میں نے اسے آزاد کر دیا، میرے پاس نبی اکرم صلی اللہ علیہ وسلم تشریف لائے تو میں نے آپ کو اس کی خبر دی، اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی تمہیں اجر عطا کرے، لیکن اگر تو اس لونڈی کو اپنے ننھیال کے لوگوں کو دے دیتی تو یہ تیرے لیے بڑے اجر کی چیز ہوتی\"۔","صحیح",{"u2":"ام المؤمنین سیدہ میمونہ رضی اللہ عنہا ا سے روایت ہے وہ بیان کرتی ہیں کہ میری ایک لونڈی تھی، میں نے اسے آزاد کر دیا، پھر رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے، میں نے آپ کو بتایا تو آپ نے فرمایا ” اللہ تجھے جزا دے، تاہم تو اگر اسے اپنے مامووں کو دے دیتی تو تیرے لیے زیادہ ثواب ہوتا۔ “"}],[1691,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے صدقہ کا حکم دیا تو ایک شخص نے کہا: اللہ کے رسول! میرے پاس ایک دینار ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنے کام میں لے آؤ\"، تو اس نے کہا: میرے پاس ایک اور ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنے بیٹے کو دے دو\"، اس نے کہا: میرے پاس ایک اور ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنی بیوی کو دے دو\"، اس نے کہا: میرے پاس ایک اور ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنے خادم کو دے دو\"، اس نے کہا میرے پاس ایک اور ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اب تم زیادہ بہتر جانتے ہو (کہ کسے دیا جائے)\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے صدقہ کرنے کا حکم دیا تو ایک شخص نے کہا: اے اللہ کے رسول! میرے پاس ایک دینار ہے، آپ نے فرمایا ” اپنی جان پر صدقہ کر۔ “ کہنے لگا میرے پاس دوسرا ہے۔ فرمایا ” اپنے بچے پر صدقہ کر۔ “ کہنے لگا میرے پاس ایک اور ہے۔ فرمایا ” اپنی بیوی پر صدقہ کر۔ “ لفظ «زوجتك» یا«زوجك» فرمایا، کہنے لگا میرے پاس ایک اور ہے۔ فرمایا ” اپنے خادم پر صدقہ کر۔ “ کہنے لگا میرے پاس ایک اور ہے۔ فرمایا ” تو اس کے متعلق بہتر جانتا ہے۔ “ (کہ کہاں اور کس پر خرچ کرنا ہے)۔","f2":"1۔اپنے آپ پر اوراپنے عزیزوں پر خرچ کرنے کو نبی کریم صلی اللہ علیہ وسلم نے صدقہ سے تعبیر فرمایا ہے۔یعنی حسن نیت کی بنا پر ان لازمی اخراجات پر بھی انسان اللہ کے ہاں صدقے کاساثواب پاتا ہے۔2۔اوراس ترتیب میں اپنی جان کو اولیت اور اہمیت دی گئی ہے۔کیونکہ انسان کی اپنی صحت عمدہ اور قویٰ بحال ہوں گے۔تودوسروں کے لئے بھی کوئی محنت مشقت کرسکے گا۔3۔اہل خانہ کو بھی اشارہ ہے۔کہ کسب و مشقت کی بنا پر شوہر اور باپ کو اولیت اوراولویت حاصل ہے۔4۔اور یہی حکم اس خاتون کا ہوگا۔جس کے کندھوں پر گھر کا یا بچوں کا خرچہ آن پڑا ہو۔"}],[1692,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی کے گنہگار ہونے کے لیے یہ کافی ہے کہ وہ ان لوگوں کو جن کے اخراجات کی ذمہ داری اس کے اوپر ہے ضائع کر دے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی جن کی کفالت اس کے ذمہ ہو ان سے قطع تعلق کر کے نیکی کے دوسرے کاموں میں اپنا مال خرچ کرے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” انسان کے گناہ گار ہونے کے لیے یہ (عمل) کافی ہے کہ جن کے رزق و اخراجات کا یہ ذمہ دار ہو، انہیں ضائع کر دے۔“","f2":"یعنی اپنے بیوی بچے جن کے اخراجات اس کے زمے ہیں یا وہ افراد جو اس کے زیر کفالت ہوں۔مثلاً والدین یادیگر عزیز یا نوکر خادم اور اس کے زیر انتظام ادارے کے ملازمین جنھیں یہ تنخواہ دیتا ہو۔اس قسم کے متعلقین کو ان کے مالی حقوق نہ دینا یا کم دینا یا بلاوجہ تاخیر کر کے دینایا ان کو چھوڑ کر دوسروں پر صدقہ کرتے پھرنا اور ان کا خیال نہ رکھنا انہیں ضائع کرنے کے مترادف ہے۔اور گناہ ہے۔انسانوں کے علاوہ زیر ملکیت جانوروں اور پرندوں کے حقوق مارنے پر بھی یہی وعید ہے۔اس معنی ومفہوم کے ساتھ ساتھ اس سے مراد یہ بھی ہوسکتا ہے۔کہ انسان جس کی طرف سے اس کو رزق وخرچ مل رہا ہو اس کو ضائع کردے۔۔۔یعنی اگر وہ خدمت کا حقداار ہے۔تو اس کی خدمت نہ کرے۔مثلا ً بیوی کے لئے شوہر اور اولاد کےلئے باپ۔۔۔یا اس کا احسان مند نہ ہو۔ مثلا بھائی کے لئے بھائی یا خوامخواہ اس میں عیب جوئی کرتے رہنا۔کوئی تقصیر ہوجائے تو درگزر نہ کرنا وغیرہ کہ ان اسباب سے انسان کا وسیلہ رزق ختم ہوجائے یا الفت ومودت اور صلہ رحمی کےروابط ختم ہوجایئں۔ اور اسے ضائع کر بیٹھے تو یہ گناہ کی بات ہے۔رسول اللہ صلی اللہ علیہ وسلم فدا امی وابی کے اس قسم کے ارشادات آپ کے صاحب جوامع الکلم ہونے کی دلیل ہیں۔ (اللهم صل وبارك وسلم عليه)"}],[1693,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے لیے یہ بات باعث مسرت ہو کہ اس کے رزق میں اور عمر میں درازی ہو جائے تو اسے چاہیئے کہ وہ صلہ رحمی کرے (یعنی قرابت داروں کا خیال رکھے)\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جسے یہ بات اچھی لگتی ہو کہ اس کا رزق فراخ اور عمر طویل ہو تو اسے چاہیئے کہ اپنے عزیز و اقارب سے میل ملاپ رکھے۔ “","f2":"اللہ عزوجل کا علم اٹل ہے۔ اور ا س نے ہر ہر انسان کی عمر اورتقدیر بھی لکھی ہوئی ہے۔ مگر جیسا کہ علماء نے لکھا ہے کہ تقدیر کے دو پہلو ہیں۔ ایک وہ علم جو قطعی ہے۔اسے تقدیر مبرم کہتے ہیں۔اور اس میں کوئی تبدیلی نہیں ہوتی۔ دوسرا وہ جس میں اللہ نے بعض چیزوں کو بعض چیزوں کے ساتھ مشروط (معلق) رکھا ہے۔اس میں تبدیلی کی گنجائش ہوتی ہے۔مثلا فرشتوں کو بتایا جاتا ہے۔کہ اس کی عمر ساٹھ سال ہے۔ لیکن اگر وہ صلہ رحمی جیسے اعمال حسنہ کرے۔ تو اس کی عمر میں اتنا مذید اضافہ کردیا جائے۔مثلا اس کی عمر نوےسال کردی جائے۔ اسے تقدیر معلق کہتے ہیں۔ اور یہ بھی پہلے سے ہی اللہ کے علم میں ہوتی ہے۔ اگر بندہ یہ اعمال نہ کرے تو اضافہ نہیں کیا جاتا اور یہ بھی اللہ تعالیٰ کے علم میں ہوتا ہے۔"}],[1694,"عبدالرحمٰن بن عوف رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"اللہ تعالی نے فرمایا ہے: میں رحمن ہوں اور «رَحِم» (ناتا) ہی ہے جس کا نام میں نے اپنے نام سے مشتق کیا ہے، لہٰذا جو اسے جوڑے گا میں اسے جوڑوں گا اور جو اسے کاٹے گا، میں اسے کاٹ دوں گا\"۔","صحیح",{"u2":"سیدنا عبدالرحمٰن بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرماتے تھے ” اللہ تعالیٰ فرماتا ہے میں رحمن ہوں (بےانتہا رحم کرنے والا) اور یہ قرابت داریاں جسے کہ «رحم» کہتے ہیں، اس کا لفظ میں نے اپنے نام سے نکالا ہے، تو جو اپنے عزیز قرابت داروں سے میل جول رکھتا ہے (صلہ رحمی کرتا ہے) میں اس سے جڑتا ہوں اور جو اس کو کاٹتا اور توڑتا ہے میں اس سے کٹ جاتا ہوں۔ “"}],[1695,"اس سند سے بھی عبدالرحمٰن بن عوف رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث سنی ہے۔","صحیح",{"u2":"محمد بن متوکل عسقلانی کی سند سے مروی ہے کہ عبدالرحمٰن بن عوف رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔ اور مذکورہ بالا حدیث کے ہم معنی روایت کیا۔"}],[1696,"جبیر بن مطعم رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رشتہ ناتا توڑنے والا جنت میں نہیں جائے گا\"۔","صحیح",{"u2":"سیدنا جبیر بن مطعم رضی اللہ عنہ سے مروی ہے وہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” قطع رحمی کرنے والا جنت میں داخل نہیں ہو گا۔ “"}],[1697,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رشتہ ناتا جوڑنے والا وہ نہیں جو بدلے میں ناتا جوڑے بلکہ ناتا جوڑنے والا وہ ہے کہ جب ناتا توڑا جائے تو وہ اسے جوڑے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بدلے میں میل ملاپ کرنے والا صلہ رحمی کرنے والا نہیں ہے، بلکہ صلہ رحمی کرنے والا وہ ہے جو توڑے جانے والے رشتے کو جوڑے۔ “","f2":"محض ادلے بدلے میں اجر نہیں۔لیکن اگر للہ فی اللہ بدلہ دے۔تو ان شاء اللہ ماجور اور فضیلت کا کام ہے۔(هَلْ جَزَاءُ الْإِحْسَانِ إِلَّا الْإِحْسَانُ)(الرحمٰن۔60) اور صلہ رحمی پر جس اجر فضیلت کا وعدہ کیا گیا ہے۔وہ اس صورت میں ہے کہ جب بندہ جب بنیادی طور پر اللہ پر ایمان اور رسول اللہ صلی اللہ علیہ وسلم کی سنت پر عمل سے موصوف ہو۔"}],[1698,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا اور فرمایا: \"بخل و حرص سے بچو اس لیے کہ تم سے پہلے لوگ بخل و حرص کی وجہ سے ہلاک ہوئے، حرص نے لوگوں کو بخل کا حکم دیا تو وہ بخیل ہو گئے، بخیل نے انہیں ناتا توڑنے کو کہا تو لوگوں نے ناتا توڑ لیا اور اس نے انہیں فسق و فجور کا حکم دیا تو وہ فسق و فجور میں لگ گئے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا اور فرمایا ” اپنے آپ کو حرص و بخل سے بچاؤ تم سے پہلے کے لوگ اسی وجہ سے ہلاک ہوئے۔ (حرص نے) ان کو حکم دیا تو وہ بخل کرنے لگے، قطع رحمی کا حکم دیا تو قرابت توڑ لی اور بدکاری کا حکم دیا تو بدکاری کرنے لگے۔ “","f2":"عربی لغت میں (شُح) اس مرکب صفت کو کہتے ہیں۔جس میں حرص اور بُخل دونوں جمع ہیں۔اور یہ محض بخل سے زیادہ مذموم ہے۔کہ خرچ کے مقام پرخرچ نہ کرے۔بلکہ لینے کا حریص بنا رہے۔اور پھر عزیز تعلق داروں میں یہ کیفیت اور بھی قابل مذمت ہے۔"}],[1699,"اسماء بنت ابی بکر رضی اللہ عنہما کہتی ہیں میں نے عرض کیا: اللہ کے رسول! میرے پاس سوائے اس کے کچھ نہیں جو زبیر میرے لیے گھر میں لا دیں، کیا میں اس میں سے دوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"دو اور اسے بند کر کے نہ رکھو کہ تمہارا رزق بھی بند کر کے رکھ دیا جائے\"۔","صحیح",{"u2":"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا ا بیان کرتی ہیں کہ میں نے کہا: اے اللہ کے رسول! میرے پاس بس وہی ہوتا ہے جو (میرے شوہر) زبیر گھر میں لے آئیں۔ تو کیا میں اس سے دے دیا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا (اسماء!) دو اور باندھ باندھ کر مت رکھو، ورنہ تم پر بھی (تمہارا رزق) باندھ دیا جائے گا۔ “","f2":"یعنی گھر میں سے عام معمولات کے مطابق جیس کے خواتین گھر کی امین ہوتی اور اس کا انتظام چلاتی ہیں۔جو تھوڑا بہت میسر ہو صدقہ کردیا کرو۔۔۔اس کی بہت برکات ہیں۔جبکہ بخیلی ایک نحوست ہے۔ باندھ باندھ کر مت رکھو کا مطلب یہی ہے کہ بخل سے کام مت لو۔"}],[1700,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے کئی مسکینوں کا ذکر کیا (ابوداؤد کہتے ہیں: دوسروں کی روایت میں «عدة من صدقة» (کئی صدقوں کا ذکر ہے) تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"دو اور گنو مت کہ تمہیں بھی گن گن کر رزق دیا جائے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ انہوں نے کئی مساکین کو شمار کیا، یا کئی صدقات گنوائے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا ” (عائشہ!) دو اور گنو نہیں، ورنہ تمہیں بھی گن گن کر دیا جائے گا۔ “"}],[1701,"سوید بن غفلہ رضی اللہ عنہ کہتے ہیں کہ میں نے زید بن صوحان اور سلیمان بن ربیعہ کے ساتھ جہاد کیا، مجھے ایک کوڑا پڑا ملا، ان دونوں نے کہا: اسے پھینک دو، میں نے کہا: نہیں، بلکہ اگر اس کا مالک مل گیا تو میں اسے دے دوں گا اور اگر نہ ملا تو خود میں اپنے کام میں لاؤں گا، پھر میں نے حج کیا، میرا گزر مدینے سے ہوا، میں نے ابی بن کعب رضی اللہ عنہ سے پوچھا، تو انہوں نے بتایا کہ مجھے ایک تھیلی ملی تھی، اس میں سو (۱۰۰) دینار تھے، میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا آپ نے فرمایا: \"ایک سال تک اس کی پہچان کراؤ\"، چنانچہ میں ایک سال تک اس کی پہچان کراتا رہا، پھر آپ کے پاس آیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سال اور پہچان کراؤ\"، میں نے ایک سال اور پہچان کرائی، اس کے بعد پھر آپ کے پاس آیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سال پھر پہچان کراؤ\"، چنانچہ میں ایک سال پھر پہچان کراتا رہا، پھر آپ کے پاس آیا اور آپ صلی اللہ علیہ وسلم سے عرض کیا: مجھے کوئی نہ ملا جو اسے جانتا ہو، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی تعداد یاد رکھو اور اس کا بندھن اور اس کی تھیلی بھی، اگر اس کا مالک آ جائے (تو بہتر) ورنہ تم اسے اپنے کام میں لے لینا\"۔ شعبہ کہتے ہیں: مجھے نہیں معلوم کہ سلمہ نے «عرفها» تین بار کہا تھا یا ایک بار۔","صحیح",{"u2":"سیدنا سوید بن غفلہ رضی اللہ عنہ کہتے ہیں کہ میں ایک سفر میں سیدنا زید بن صوحان اور سلمان بن ربیعہ رضی اللہ عنہ کے ساتھ تھا، مجھے ایک چابک ملا (جو میں نے اٹھا لیا) تو ان دونوں نے مجھ سے کہا کہ اسے پھینک دے۔ میں نے کہا: نہیں۔ اگر اس کا مالک مجھے مل گیا تو (اسے دے دوں گا) ورنہ اس سے فائدہ اٹھاؤں گا۔ پھر میں حج کے لیے گیا اور مدینے بھی آیا تو میں نے سیدنا ابی بن کعب رضی اللہ عنہ سے سوال کیا، انہوں نے کہا: مجھے ایک تھیلی ملی تھی جس میں سو دینار تھے، تو میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا، آپ نے فرمایا ” ایک سال تک اس کا اعلان کرو۔ “ چنانچہ میں ایک سال تک اس کا اعلان کرتا رہا۔ پھر آپ کے پاس آیا، تو آپ نے فرمایا ” ایک سال (اور) اعلان کرو۔ “ میں نے ایک سال اور اس کا اعلان کیا۔ پھر آپ کی خدمت میں آیا، آپ نے فرمایا ” ایک سال (اور) اعلان کرو۔ “ میں نے ایک سال مزید اس کا اعلان کیا۔ پھر میں آپ کے پاس آیا اور عرض کیا کہ میں نے کوئی ایسا آدمی نہیں پایا جو اسے جانتا ہو۔ تو آپ نے فرمایا ” ان کی گنتی کو یاد رکھو، اس کی تھیلی اور سربند بھی۔ اگر اس کا مالک آ جائے تو بہتر، ورنہ ان سے فائدہ اٹھاؤ۔ “ (سلمہ بن کبیل نے) کہا: مجھے نہیں معلوم کہ ” اعلان کرنے کا حکم “ تین بار دیا یا ایک بار۔"}],[1702,"اس سند سے بھی شعبہ سے اسی مفہوم کی حدیث مروی ہے وہ کہتے ہیں: «عرفها حولا» تین بار کہا، البتہ مجھے یہ نہیں معلوم کہ آپ نے اسے ایک سال میں کرنے کے لیے کہا یا تین سال میں۔","صحیح",{"u2":"شعبہ نے مذکورہ بالا حدیث کے ہم معنی روایت کیا (اس میں ہے آپ صلی اللہ علیہ وسلم نے) فرمایا ” ایک سال تک اس کا اعلان کرو “ آپ نے یہ بات تین دفعہ کہی۔ (سلمہ بن کبیل نے) کہا: مجھے نہیں معلوم کہ اس کا مفہوم ایک سال میں تین بار اعلان کرنا تھا یا تین سال تک اعلان کرنا۔","f2":"راویوں کے اختلاف کی وجہ سے ‘ اعلان کرنے کی مدت میں بھی علماء کے درمیان اختلاف ہے ‘ تاہم کم از کم ایک سال تک اعلان کرنے پر سب کا اتفاق ہے۔"}],[1703,"حماد کہتے ہیں سلمہ بن کہیل نے ہم سے اسی سند سے اور اسی مفہوم کی حدیث بیان کی اس میں ہے: آپ صلی اللہ علیہ وسلم نے (لقطہٰ کی) پہچان کرانے کے سلسلے میں فرمایا: \"دو یا تین سال تک (اس کی پہچان کراؤ)\"، اور فرمایا: \"اس کی تعداد جان لو اور اس کی تھیلی اور اس کے سر بندھن کی پہچان کر لو\"، اس میں اتنا مزید ہے: \"اگر اس کا مالک آ جائے اور اس کی تعداد اور سر بندھن بتا دے تو اسے اس کے حوالے کر دو\"۔ ابوداؤد کہتے ہیں: «فعرف عددها» کا کلمہ اس حدیث میں سوائے حماد کے کسی اور نے نہیں ذکر کیا ہے۔","صحیح",{"u2":"سلمہ بن کہیل نے اپنی سند سے اسی کے ہم معنی بیان کیا اور اعلان کے بارے میں کہا: ” دو سال یا تین سال۔ “ اور فرمایا ” اس کی گنتی کر لو، اس کی تھیلی اور اس کا سر بند خوب یاد رکھو۔ “ مزید کہا ” پھر اگر اس کا مالک آ جائے اور اس کی گنتی بتا دے اور تھیلی کا سربند بھی تو اس کے حوالے کر دینا۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ الفاظ یعنی ” اگر وہ ان کی گنتی بتا دے “ صرف حماد کی روایت میں ہیں۔"}],[1704,"زید بن خالد جہنی رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے لقطہٰ (پڑی ہوئی چیز) کے بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سال تک اس کی پہچان کراؤ، پھر اس کی تھیلی اور سر بندھن کو پہچان لو، پھر اسے خرچ کر ڈالو، اب اگر اس کا مالک آ جائے تو اسے دے دو\"، اس نے کہا: اللہ کے رسول! گمشدہ بکری کو ہم کیا کریں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کو پکڑ لو، اس لیے کہ وہ یا تو تمہارے لیے ہے، یا تمہارے بھائی کے لیے، یا بھیڑیئے کے لیے\"، اس نے پوچھا: اللہ کے رسول! گمشدہ اونٹ کو ہم کیا کریں؟ تو رسول اللہ صلی اللہ علیہ وسلم غصہ ہو گئے یہاں تک کہ آپ کے رخسار سرخ ہو گئے یا آپ کا چہرہ سرخ ہو گیا اور فرمایا: \"تمہیں اس سے کیا سروکار؟ اس کا جوتا ۱؎ اور اس کا مشکیزہ اس کے ساتھ ہوتا ہے یہاں تک کہ اس کا مالک آ جائے\"۔\n§وضاحت\n۱؎ : جوتے سے مراد اونٹ کا پاؤں ہے، اور مشکیزہ سے اس کا پیٹ جس میں وہ کئی دن کی ضرورت کا پانی ایک ساتھ بھر لیتا ہے اور بار بار پانی پینے کی ضرورت نہیں محسوس کرتا، اسے بکری کی طرح بھیڑیے وغیرہ کا بھی خوف نہیں کہ وہ خود اپنا دفاع کر لیتا ہے، اس لئے اسے پکڑنے کی کوئی ضرورت نہیں۔","صحیح",{"u2":"سیدنا زید بن خالد جہنی رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے گری پڑی چیز کے متعلق سوال کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” ایک سال تک اس کا اعلان کرو۔ پھر اس کا سربند (بندھن) اور تھیلی (یا برتن جس میں وہ ہو) خوب یاد کر لو۔ اور اسے اپنے استعمال میں لے آؤ۔ اگر اس کا ملک آ جائے تو اسے دے دو۔ “ پھر اس نے کہا: اے اللہ کے رسول! گمشدہ بکری (کے بارے میں کیا ارشاد ہے؟) آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے لے لو۔ یہ تمہارے لیے ہے یا تمہارے بھائی کے لیے یا بھیڑیے کے لیے۔ “ کہنے لگا: اے اللہ کے رسول! اور گمشدہ اونٹ؟ اس پر آپ غصے میں آ گئے حتیٰ کہ آپ کے رخسار سرخ ہو گئے یا کہا کہ چہرہ سرخ ہو گیا۔ اور فرمایا ” تمہیں اس سے کیا غرض؟ اس کے ساتھ اس کا جوتا (پاوں) ہے اور مشکیزہ ہے۔ (اس کے پیٹ میں پانی ذخیرہ کرنے کی گنجائش اور صلاحیت ہے) یہاں تک کہ اس کا مالک آ جائے گا۔ “"}],[1705,"اس سند سے بھی مالک سے اسی طریق سے اسی مفہوم کی روایت مروی ہے البتہ اس میں اتنا اضافہ ہے کہ: \"وہ اپنی سیرابی کے لیے پانی پر آ جاتا ہے اور درخت کھا لیتا ہے\"، اس روایت میں گمشدہ بکری کے سلسلے میں «خذها» (اسے پکڑ لو) کا لفظ نہیں ہے، البتہ لقطہٰ کے سلسلے میں فرمایا: \"ایک سال تک اس کی تشہیر کرو، اگر اس کا مالک آ جائے تو بہتر ہے ورنہ تم خود اس کو استعمال کر لو\"، اس میں «استنفق»کا لفظ نہیں ہے۔ ابوداؤد کہتے ہیں: ثوری، سلیمان بن بلال اور حماد بن سلمہ نے اسے ربیعہ سے اسی طرح روایت کیا ہے لیکن ان لوگوں نے «خذها» کا لفظ نہیں کہا ہے۔","صحیح",{"u2":"جناب مالک نے اس حدیث کو اسی سند سے اسی کے ہم معنی روایت کیا۔ اور مزید کہا: ” (اس کے ساتھ) اس کا مشکیزہ ہے، وہ پانی پر پہنچ کر پانی پی لے گا اور جھاڑیاں کھا کر گزارہ کر لے گا۔ “ اور گمشدہ بکری کے سلسلے میں «خذها» ” اسے لے لو “ کے لفظ روایت نہیں کیے اور گری پڑی چیز «لقطة» کے بارے میں فرمایا ” ایک سال تک اس کا اعلان کرو۔ پھر اگر اس کا مالک آ جائے (تو بہتر) ورنہ تم جانو (یعنی اس کے مالک بن جاؤ) “ اور ” خرچ کر لینے “ کا ذکر نہیں کیا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اسے ثوری، سلیمان بن بلال اور حماد بن سلمہ نے ربیعہ سے اسی کے مثل روایت کیا اور انہوں نے «خذها» کا لفظ نہیں کہا۔","f2":"(1)بکری جیسا ضعیف جانور جو زیادہ بھوک پیاس برداشت نہیں کر سکتا اور درندوں وغیرہ سے دفاع نہیں کر سکتا اگر اسے قبضے میں نہ لیا جائے تو ضائع ہو جائے گا لہذا یہ کسی طرح مناسب نہیں کہ اسے چھوڑا جائے مگر اونٹ کامعاملہ اس سے مختلف ہے اس لیے جائز نہیں کہ انسان اس کو اپنے قبضے میں لے لے۔الایہ کہ اندیشہ ہو کہ فاسق یا چور ڈاکو وغیرہ اڑالے جائیں گے یا یہ از خود دشمنوں کے علاقے میں چلا جائے گا تو محفوظ کر لینا زیادہ بہتر ہے۔بشرطیکہ ظن غالب یہ ہو کہ یہ جانور کسی مسلمان ہی کا ہے۔والله اعلم .(2)اس روایت میں راویوں نے [خذها] اسے لے لو اور [استنفق] اس سے فائدہ اٹھاؤ کے الفاظ بیان نہیں کیے جبکہ یہ الفاظ صحیح بخاری میں موجود ہیں۔دیکھیے (صحیح البخاری اللقطة باب ضالة الغنم حدیث:2428)"}],[1706,"زید بن خالد جہنی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے لقطہٰ کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"تم ایک سال تک اس کی تشہیر کرو، اگر اس کا ڈھونڈنے والا آ جائے تو اسے اس کے حوالہ کر دو ورنہ اس کی تھیلی اور سر بندھن کی پہچان رکھو اور پھر اسے کھا جاؤ، اب اگر اس کا ڈھونڈھنے والا آ جائے تو اسے (اس کی قیمت) ادا کر دو\"۔","صحیح",{"u2":"سیدنا زید بن خالد جہنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے گری پڑی اشیاء کے متعلق پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” ایک سال تک اس کا اعلان کرو۔ اگر اس کا طلب کرنے والا آ جائے تو اس کو دے دو، ورنہ اس کی تھیلی (یا برتن) اور اس کا سربند یاد رکھو، پھر اسے کھا لو (اپنے استعمال میں لے آؤ) اس کے بعد اگر اس کا متلاشی آ جائے تو اس کے حوالے کر دو۔ “","f2":"یہ حکم گری پڑی چیز اٹھانے کے علاوہ بکری جیسے جانور کے بارے میں بھی ہے کہ اگر اسے کھا لیا گیا ہوتو اس کا مالک آنے پر اس کی قیمت یا بدل دینا واجب ہے۔"}],[1707,"زید بن خالد جہنی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے (لقطے کے متعلق) پوچھا گیا پھر راوی نے ربیعہ کی طرح حدیث ذکر کی اور کہا: لقطے کے بارے میں پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سال تک تم اس کی تشہیر کرو، اب اگر اس کا مالک آ جائے تو تم اسے اس کے حوالہ کر دو، اور اگر نہ آئے تو تم اس کے ظرف اور سر بندھن کو پہچان لو پھر اسے اپنے مال میں ملا لو، پھر اگر اس کا مالک آ جائے تو اسے اس کو دے دو\"۔","صحیح",{"u2":"سیدنا زید بن خالد جہنی رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا۔ اور ربیعہ کی حدیث کے مانند ذکر کیا۔ (سابقہ حدیث: 1704) کہا کہ آپ سے گری پڑی چیز کے متعلق سوال کیا گیا تو آپ نے فرمایا ” ایک سال تک اس کا اعلان کرو۔ پس اگر اس کا مالک آ جائے تو اس کے سپرد کر دو۔ نہیں تو اس کا بندھن اور برتن خوب یاد کر لو اور اسے اپنے مال میں شامل کر لو۔ پھر اگر اس کا مالک آ جائے تو اس کو دے دو۔ “"}],[1708,"یحیی بن سعید اور ربیعہ سے قتیبہ کی سند سے اسی مفہوم کی حدیث مروی ہے اس میں اتنا اضافہ ہے: \"اگر اس کا ڈھونڈنے والا آ جائے اور تھیلی اور گنتی کی پہچان بتائے تو اسے اس کو دے دو\"۔ اور حماد نے بھی عبیداللہ بن عمر سے، عبیداللہ نے عمرو بن شعیب نے «عن ابیہ عن جدہ» عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے اسی کے مثل مرفوعاً روایت کی ہے۔ ابوداؤد کہتے ہیں: یہ زیادتی جو حماد بن سلمہ نے سلمہ بن کہیل، یحیی بن سعید، عبیداللہ اور ربیعہ کی حدیث (یعنی حدیث نمبر: ۱۷۰۲ -۱۷۰۳) میں کی ہے: «إن جاء صاحبها فعرف عفاصها ووكاءها فادفعها إليه» یعنی: \"اگر اس کا مالک آ جائے اور اس کی تھیلی اور سر بندھن کی پہچان بتا دے تو اس کو دے دو\"، اس میں: «فعرف عفاصها ووكاءها» \"تھیلی اور سر بندھن کی پہچان بتا دے\" کا جملہ محفوظ نہیں ہے۔ اور عقبہ بن سوید کی حدیث میں بھی جسے انہوں نے اپنے والد سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے یعنی «عرفها سنة» (ایک سال تک اس کی تشہیر کرو) موجود ہے۔ اور عمر رضی اللہ عنہ کی حدیث میں بھی نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً مروی ہے کہ آپ نے فرمایا: «عرفها سنة» تم ایک سال تک اس کی تشہیر کرو ۱؎۔\n§وضاحت\n۱؎ : کسی روایت میں تین سال پہچان (شناخت) کراتے رہنے کا تذکرہ ہے، اور کسی میں ایک سال، یہ سامان اور حالات پر منحصر ہے، یا ایک سال بطور وجوب اور تین سال بطور استحباب و ورع، ان دونوں روایتوں کا اختلاف تضاد کا اختلاف نہیں کہ ایک کو ناسخ قرار دیا جائے اور دوسرے کو منسوخ (ملاحظہ ہو: فتح الباری)۔","صحیح",{"u2":"یحییٰ بن سعید اور ربیعہ سے قتیبہ کی سند سے اسی کے ہم معنی مروی ہے اس میں اضافہ ہے: ” اگر اس کا متلاشی آ جائے اور اس کی تھیلی (یا برتن) اور اس کی گنتی (وغیرہ علامات) بتا دے تو وہ چیز اس کے سپرد کر دو۔“\nاور حماد نے بھی عبیداللہ بن عمر سے، انہوں نے عمرو بن شعیب سے، انہوں (عمرو) نے اپنے والد (شعیب) سے، انہوں نے اپنے دادا (عبداللہ بن عمرو بن عاص) سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مثل روایت کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ حماد بن سلمہ کا یہ اضافہ، جو انہوں نے سلمہ بن کہیل، یحییٰ بن سعید، عبیداللہ بن عمر اور ربیعہ کی روایت میں ذکر کیا ہے یعنی &rdquo; اگر اس کا مالک آ جائے اور اس چیز کی تھیلی (یا برتن) اور اس کا سربند (علامات) بتا دے تو اسے اس کے حوالے کر دو۔ &ldquo; (اس سند کے ساتھ) یہ الفاظ محفوظ نہیں ہیں۔ یعنی &laquo;فعرف عفاصها ووكاءها&raquo; اور عقبہ بن سوید کی حدیث جو ان کے والد سے نبی کریم صلی اللہ علیہ وسلم سے مروی ہے کہ &rdquo; ایک سال تک اعلان کرو۔ &ldquo; نیز سیدنا عمر بن خطاب رضی اللہ عنہ کی حدیث میں بھی نبی کریم صلی اللہ علیہ وسلم سے مروی ہے کہ &rdquo; ایک سال تک اعلان کرو۔ &ldquo;"}],[1709,"عیاض بن حمار رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جسے لقطہٰ ملے تو وہ ایک یا دو معتبر آدمیوں کو گواہ بنا لے ۱؎ اور اسے نہ چھپائے اور نہ غائب کرے، اگر اس کے مالک کو پا جائے تو اسے واپس کر دے، ورنہ وہ اللہ عزوجل کا مال ہے جسے وہ چاہتا ہے دیتا ہے\"۔\n§وضاحت\n۱؎ : گواہ بنانا واجب نہیں بلکہ مستحب ہے، اس میں حکمت یہ ہے کہ مال کی چاہت میں آگے چل کر آدمی کی نیت کہیں بری نہ ہو جائے، اس بات کا بھی امکان ہے کہ وہ اچانک مر جائے اوراس کے ورثاء اسے میراث سمجھ لیں۔","صحیح",{"u2":"سیدنا عیاض بن حمار رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جسے کوئی گری پڑی چیز ملے تو اسے چاہیئے کہ ایک یا دو عادل گواہ بنا لے۔ اور چھپائے نہیں اور نہ غائب کرے، پھر اگر اس کے مالک کو پائے تو اسے لوٹا دے، ورنہ وہ اللہ کا مال ہے جسے چاہتا ہے عنایت فر دیتا ہے۔ “","f2":"گواہ بنانا نہ تو واجب ہے اور نہ ہر وقت ممکن ہی۔لیکن یہ انتہائی پسندیدہ صورت ہے تاکہ انسان شیطانی اکساہٹ سے محفوظ ہو جائے اور اس کے دل میں اس کے مالک بن جانے کا وسوسہ پیدا نہ ہو۔اس کے ذریعے سے کئی دوسری قباحتوں سے بھی بچا جاسکتا ہے جیسے اس کے ورثاء اس کو ادا کرنے سے انکار نہ کر سکیں یا کوئی شخص مال کی مقدار کےبارےمیں اس پر تہمت نہ لگا سکے۔"}],[1710,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے درخت پر لٹکتے ہوئے پھل کے بارے میں سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو حاجت مند اسے کھائے اور چھپا کر نہ لے جائے تو اس میں کوئی قباحت نہیں، اور جو اس میں سے کچھ چھپا کر لے جائے تو اس کا دو گنا جرمانہ دے اور سزا الگ ہو گی، اور جب میوہ پک کر سوکھنے کے لیے کھلیان میں ڈال دیا جائے اور اس میں سے کوئی اس قدر چرا کر لے جائے جس کی قیمت سپر (ڈھال) کی قیمت کے برابر ہو تو اس کا ہاتھ کاٹا جائے گا\"۔ اس کے بعد گمشدہ اونٹ اور بکری کا ذکر کیا جیسا کہ اوروں نے ذکر کیا ہے، اس میں ہے: \"آپ سے لقطے کے سلسلے میں پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: جو لقطہٰ گزر گاہ عام یا آباد گاؤں میں ملے تو ایک سال تک اس کی تشہیر کرو، اگر اس کا مالک آ جائے تو اسے دے دو اور اگر نہ آئے تو وہ تمہارا ہے اور جو لقطہٰ کسی اجڑے یا غیر آباد مقام پر ملے تو اس میں اور رکاز (جاہلیت کے دفینہ) میں پانچواں حصہ حاکم کو دینا ہو گا\"۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو بن العاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ (درختوں پر) لٹکتے پھل کا کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” جس کسی ضرورت مند نے اسے اپنے منہ سے کھا لیا ہو، اپنے پلو میں کچھ نہ باندھا ہو تو اس پر کچھ نہیں۔ لیکن جو وہاں سے کچھ لے کر نکلے تو اس پر دو گنا جرمانہ ہے اور سزا۔ اور جس نے اسے اس کے مخزن میں آ جانے کے بعد چرایا تو اگر وہ ڈھال کی قیمت کے برابر ہوا تو اس پر ہاتھ کٹے گا۔ “ اور گمشدہ بکری اور اونٹ کے بارے میں ویسے ہی بیان کیا جیسے کہ دوسرے راویوں نے ذکر کیا ہے۔ اور گری پڑی چیز کے بارے میں پوچھا گیا تو فرمایا ” جو تمہیں آباد رستوں اور بستیوں میں سے ملے تو اس کا ایک سال تک اعلان کرو۔ پس اگر اس کا ڈھونڈنے والا آ جائے تو اس کے حوالے کر دو، ورنہ وہ تمہاری ہے۔ اور جو کسی اجاڑ ویران جگہ سے ملے تو اس میں اور ایسے ہی کوئی دفینہ ملے، تو اس میں خمس ہے۔ “ (پانچواں حصہ زکٰوۃ ہے)۔"}],[1711,"اس طریق سے بھی عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے یہی حدیث مروی ہے البتہ اس میں ہے کہ گمشدہ بکری کے سلسلہ میں آپ نے فرمایا: \"اسے پکڑے رکھو\"۔","حسن",{"u2":"عمرو بن شعیب نے اپنی اسی (مذکورہ بالا) سند سے اس حدیث کو روایت کیا اور گمشدہ بکری کے بارے میں اس کے لفظ ہیں «فاجمعها» یعنی اسے اپنی بکریوں کے ساتھ ملا لو۔\nعمرو بن شعیب نے اپنی اسی (مذکورہ بالا) سند سے اس حدیث کو روایت کیا اور گمشدہ بکری کے بارے میں اس کے لفظ ہیں «فاجمعها» یعنی اسے اپنی بکریوں کے ساتھ ملا لو۔\nعمرو بن شعیب نے اپنی اسی (مذکورہ بالا) سند سے اس حدیث کو روایت کیا اور گمشدہ بکری کے بارے میں اس کے لفظ ہیں «فاجمعها» یعنی اسے اپنی بکریوں کے ساتھ ملا لو۔\nعمرو بن شعیب نے اپنی اسی (مذکورہ بالا) سند سے اس حدیث کو روایت کیا اور گمشدہ بکری کے بارے میں اس کے لفظ ہیں «فاجمعها» یعنی اسے اپنی بکریوں کے ساتھ ملا لو۔","f2":"یعنی اس کی حفاظت کرتے اور اعلان کرتے رہو جب مالک مل جائے تو اس کے حوالے کر دو۔"}],[1712,"اس طریق سے بھی عبداللہ بن عمرو رضی اللہ عنہما سے یہی حدیث مروی ہے اس میں ہے: \"گمشدہ بکری کے متعلق آپ صلی اللہ علیہ وسلم نے فرمایا: وہ بکری تمہاری ہے یا تمہارے بھائی کی یا بھیڑیئے کی، تو اسے پکڑے رکھو\"۔ اسی طرح ایوب اور یعقوب بن عطا نے عمرو بن شعیب سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے (مرسلاً) روایت کی ہے کہ آپ نے فرمایا: \"تو تم اسے پکڑے رکھو\"۔","حسن",{"u2":"عمرو بن شعیب نے اسی سند سے روایت کیا اور گمشدہ بکری کے سلسلے میں کہا ” یہ تیرے لیے ہے یا تیرے بھائی کے لیے یا بھیڑیے کے لیے، اسے لے لے اور بس۔ “ اور اسی طرح اس روایت میں ایوب اور یعقوب بن عطاء نے عمرو بن شعیب سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے «فخذها» کا لفظ بیان کیا ہے۔","f2":"محدث یہ بیان کرنا چاہتے ہیں کہ عمرو بن شعیب کے تین تلامذہ عبیداللہ بن اخنس ایوب اور یعقوب بن عطاء صرف لفظ [فخذها]بیان کرتے ہیں۔اس پر مزید کوئی اضافہ نہیں کرتے جیسے کہ مندرجہ ذیل روایت میں ابن اسحق نے [فاجمعها حتى ياتيها باغيها]ایک مفصل جملہ ذکر کیا ہے۔(عون المعبود)"}],[1713,"اس سند سے بھی عبداللہ بن عمرو رضی اللہ عنہما سے یہی حدیث مروی ہے اس میں ہے: \"گمشدہ بکری کے متعلق آپ صلی اللہ علیہ وسلم نے فرمایا: اسے پکڑے رکھو، یہاں تک کہ اس کا ڈھونڈھنے والا اس تک آ جائے\"۔","حسن",{"u2":"ابن اسحٰق، عمرو بن شعیب سے، وہ (عمرو) اپنے والد سے، وہ اپنے دادا (عبداللہ بن عمرو بن عاص رضی اللہ عنہ) سے، وہ نبی کریم صلی اللہ علیہ وسلم سے یہی روایت کرتے ہیں تو ان کے لفظ ہیں «فاجمعها حتى يأتيها باغيها» ” اس کو اپنے مال کے ساتھ ملا لے حتیٰ کہ اس کا متلاشی آ جائے۔ “"}],[1714,"ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ علی بن ابی طالب رضی اللہ عنہ کو ایک دینار ملا تو وہ اسے لے کر فاطمہ رضی اللہ عنہا کے پاس آئے، انہوں نے اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو آپ نے فرمایا: \"وہ اللہ عزوجل کا دیا ہوا رزق ہے\"، چنانچہ اس میں سے رسول اللہ صلی اللہ علیہ وسلم نے کھایا اور علی اور فاطمہ رضی اللہ عنہما نے کھایا، اس کے بعد ان کے پاس ایک عورت دینار ڈھونڈھتی ہوئی آئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"علی! دینار ادا کر دو\"۔","حسن",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ سیدنا علی بن ابی طالب رضی اللہ عنہ کو ایک دینار ملا۔ وہ اسے سیدہ فاطمہ رضی اللہ عنہا ا کے پاس لے آئے، سیدہ فاطمہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تو آپ نے فرمایا ” یہ اللہ عزوجل کا رزق ہے۔ “ چنانچہ رسول اللہ صلی اللہ علیہ وسلم سیدنا علی رضی اللہ عنہ اور سیدہ فاطمہ رضی اللہ عنہا ا نے اس سے کھا لیا۔ اس کے بعد آپ کے پاس ایک عورت آئی جو ایک دینار ڈھونڈتی پھر رہی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” علی! وہ دینار ادا کر دو۔ “"}],[1715,"علی رضی اللہ عنہ کہتے ہیں کہ انہیں ایک دینار پڑا ملا، جس سے انہوں نے آٹا خریدا، آٹے والے نے انہیں پہچان لیا، اور دینار واپس کر دیا تو علی رضی اللہ عنہ نے اسے واپس لے لیا اور اسے بھنا کر اس میں سے دو قیراط ۱؎ کا گوشت خریدا۔\n§وضاحت\n۱؎ : قیراط: دینار کا بیسواں حصہ۔","صحیح",{"u2":"بلال بن یحییٰ عبسی سیدنا علی رضی اللہ عنہ سے نقل کرتے ہیں کہ انہیں ایک دینار ملا، تو انہوں نے اس سے آٹا خریدا، آٹے والے نے سیدنا علی رضی اللہ عنہ کو پہچان لیا تو اس نے دینار ان کو واپس کر دیا۔ تو سیدنا علی رضی اللہ عنہ نے وہ لے لیا اور اس میں سے دو قیراط کاٹ کر ان کا گوشت خریدا۔"}],[1716,"ابوحازم کہتے ہیں کہ سہل بن سعد رضی اللہ عنہ نے ان سے بتایا کہ علی بن ابی طالب رضی اللہ عنہ فاطمہ رضی اللہ عنہا کے پاس آئے اور حسن اور حسین رضی اللہ عنہما رو رہے تھے، تو انہوں نے پوچھا: یہ دونوں کیوں رو رہے ہیں؟ فاطمہ نے کہا: بھوک (سے رو رہے ہیں)، علی رضی اللہ عنہ باہر نکلے تو بازار میں ایک دینار پڑا پایا، وہ فاطمہ رضی اللہ عنہا کے پاس آئے اور انہیں بتایا تو انہوں نے کہا: فلاں یہودی کے پاس جائیے اور ہمارے لیے آٹا لے لیجئے، چنانچہ وہ یہودی کے پاس گئے اور اس سے آٹا خریدا، تو یہودی نے پوچھا: تم اس کے داماد ہو جو کہتا ہے کہ وہ اللہ کا رسول ہے؟ وہ بولے: ہاں، اس نے کہا: اپنا دینار رکھ لو اور آٹا لے جاؤ، چنانچہ علی رضی اللہ عنہ آٹا لے کر فاطمہ رضی اللہ عنہا کے پاس آئے اور انہیں بتایا تو وہ بولیں: فلاں قصاب کے پاس جائیے اور ایک درہم کا گوشت لے آئیے، چنانچہ علی رضی اللہ عنہ گئے اور اس دینار کو ایک درہم کے بدلے گروی رکھ دیا اور ایک درہم کا گوشت لے آئے، فاطمہ رضی اللہ عنہا نے آٹا گوندھا، ہانڈی چڑھائی اور روٹی پکائی، اور اپنے والد (رسول اللہ صلی اللہ علیہ وسلم) کو بلا بھیجا، آپ تشریف لائے تو وہ بولیں: اللہ کے رسول! میں آپ سے واقعہ بیان کرتی ہوں اگر آپ اسے ہمارے لیے حلال سمجھیں تو ہم بھی کھائیں اور ہمارے ساتھ آپ بھی کھائیں، اس کا واقعہ ایسا اور ایسا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کا نام لے کر کھاؤ\"، ابھی وہ لوگ اپنی جگہ ہی پر تھے کہ اسی دوران ایک لڑکا اللہ اور اسلام کی قسم دے کر اپنے کھوئے ہوئے دینار کے متعلق پوچھ رہا تھا، رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا تو اسے بلایا گیا تو آپ صلی اللہ علیہ وسلم نے اس سے پوچھا تو اس نے کہا: بازار میں مجھ سے (میرا دینار) گر گیا تھا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"علی! قصاب کے پاس جاؤ اور اس سے کہو: اللہ کے رسول صلی اللہ علیہ وسلم تم سے کہہ رہے ہیں: دینار مجھے بھیج دو، تمہارا درہم میرے ذمے ہے\"، چنانچہ اس نے وہ دینار بھیج دیا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اس (لڑکے) کو دے دیا۔","حسن",{"u2":"جناب سہل بن سعد کا بیان ہے کہ سیدنا علی رضی اللہ عنہ سیدہ فاطمہ رضی اللہ عنہا ا کے ہاں (گھر میں) آئے تو (دیکھا کہ) حسن اور حسین رو رہے ہیں۔ پوچھا یہ کیوں رو رہے ہیں؟ کہا کہ بھوک کی وجہ سے رو رہے ہیں۔ پس علی رضی اللہ عنہ (گھر سے) نکل آئے تو (اتفاق سے) بازار میں انہیں ایک دینار پڑا مل گیا تو وہ سیدہ فاطمہ رضی اللہ عنہا ا کے پاس آئے اور بتایا (کہ اس طرح سے ملا ہے۔) انہوں نے کہا: فلاں یہودی کے پاس جائیں اور ہمارے لیے آٹا لے آئیں۔ چنانچہ وہ یہودی کے پاس آئے اور اس سے آٹا خریدا۔ یہودی نے کہا: بھلا آپ اس شخص کے داماد ہیں جو اپنے آپ کو رسول اللہ کہتا ہے؟ انہوں نے کہا: ہاں! تو اس نے کہا: دینار اپنے پاس رکھیں اور آٹا لے جائیں۔ سیدنا علی رضی اللہ عنہ وہاں سے چلے اور سیدہ فاطمہ رضی اللہ عنہا ا کے پاس (آٹا) لے آئے اور ساری بات بتائی۔ انہوں نے کہا: فلاں قصاب کے پاس جائیں اور ایک درہم کا گوشت لے آئیں۔ چنانچہ وہ گئے ‘ اپنا دینار اس کے پاس رہن رکھا اور ایک درہم کا گوشت لے آئے۔ سیدہ فاطمہ رضی اللہ عنہا ا نے آٹا گوندھا، ہنڈیا چولہے پر رکھی، روٹی پکائی اور اپنے والد صلی اللہ علیہ وسلم کو بلا بھیجا۔ وہ ان کے ہاں تشریف لے آئے۔ تو سیدہ فاطمہ رضی اللہ عنہا ا نے کہا: اے اللہ کے رسول! میں آپ کو بتاؤں اگر آپ اسے حلال فرمائیں تو ہم اسے کھائیں گے اور آپ بھی ہمارے ساتھ کھائیں گے اور اس کا حال اس اس طرح سے ہے۔ آپ صلی اللہ علیہ وسلم نے سن کر فرمایا ” اللہ کا نام لے کر کھاؤ۔ “ چنانچہ سب نے کھا لیا۔ ابھی وہ اپنی جگہ (دستر خوان ہی) پر بیٹھے تھے کہ ایک لڑکا، اللہ اور اسلام کا واسطہ دے کر اپنا گمشدہ دینار ڈھونڈتا پھر رہا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا اور اسے بلایا گیا۔ آپ نے اس سے پوچھا تو اس نے کہا: مجھے سے بازار میں (کہیں) گرا ہے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اے علی! اس قصاب کے پاس جاؤ اور اس سے کہو کہ اللہ کے رسول فرماتے ہیں: وہ دینا میرے ہاں بھیج دو اور تمہارا درہم میرے ذمے ہے۔ “ چنانچہ اس نے دینار بھیج دیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے اسے اس غلام کے حوالے کر دیا۔"}],[1717,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں لکڑی، کوڑے، رسی اور ان جیسی چیزوں کے بارے میں رخصت دی کہ اگر آدمی انہیں پڑا پائے تو اسے کام میں لائے۔ ابوداؤد کہتے ہیں: اسے نعمان بن عبدالسلام نے مغیرہ ابوسلمہ سے اسی طریق سے روایت کیا ہے اور اسے شبابہ نے مغیرہ بن مسلم سے انہوں نے ابو الزبیر سے ابوالزبیر نے جابر سے روایت کیا ہے، راوی کہتے ہیں: لوگوں نے نبی اکرم صلی اللہ علیہ وسلم کا ذکر نہیں کیا ہے یعنی اسے جابر رضی اللہ عنہ پر موقوف کہا ہے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے مروی ہے فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں چھڑی، رسی، کوڑا اور اس قسم کی چیزیں اٹھا لینے کی رخصت دی تھی کہ انسان ان سے فائدہ اُٹھا لے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اسے نعمان بن عبدالسلام نے مغیرہ (مغیرہ بن مسلم) ابوسلمہ سے اپنی سند سے روایت کیا ہے۔ اور شبابہ نے مغیرہ بن مسلم سے، انہوں نے ابولزابیر سے، انہوں نے جابر رضی اللہ عنہ سے روایت کیا ہے۔ (کہا کہ وہ لوگ چھڑی، کوڑا وغیرہ اٹھا لینے میں کوئی حرج نہ سمجھتے تھے) اور نبی کریم صلی اللہ علیہ وسلم کا ذکر نہیں کیا۔ (موقوف بیان کیا ہے)۔","f2":"ابوالزبیر مکی سے دو حضرات روایت کرتے ہیں۔ایک مغیرہ بن زیاد ان سے یہی متن امام ابوداؤد نے ذکر فرمایا ہے۔دوسرے مغیرہ بن مسلم ابومسلمہ کی بیان کردہ روایت میں رسول اللہ صلی اللہ علیہ وسلم کی بجائے صحابی کےحوالے سے یہی بات کہی گئی ہے۔(عون المعبود)یہ روایت سنداً ضعیف ہے لیکن امام بخاری رحمہ اللہ نے ایک باب قائم کیا ہے: باب اذا وجد خشبة فى البحر او سوطااو نحوه یعنی جب کوئی شخص سمندر میں بہتی ہوئی لکڑی پائے یا چابک یا اس جیسی (کوئی انتہائی کم قیمت)چیز اسےمل جائے۔اور نیچے وہ حدیث لائے ہیں جس سے سمندر میں بہتی ہوئی لکڑی ک ایندھن کے طور ‎پر لے جانے کا جواز ثابت ہوتا ہے۔حافظ ابن حجر رحمہ اللہ فرماتے ہیں کہ امام بخاری رحمہ اللہ نے اس حدیث سے استنباط کر کے چابک کو شامل کیا ہے۔(فتح الباری کتاب اللقطه باب مذکور)اس سے ثابت ہوا کہ امام ابوداؤد رحمہ اللہ کی بیان کردہ یہ حدیث اگرچہ سنداً ضعیف ہے لیکن اس میں جو حکم بیان کیا گیا وہ دیگر دلائل کی وجہ سے صحیح ہے۔"}],[1718,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"گمشدہ اونٹ اگر چھپا دیا جائے تو (چھپانے والے پر) اس کا جرمانہ ہو گا، اور اس کے ساتھ اتنا ہی اور ہو گا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” گمشدہ اونٹ پکڑنے والا اگر چھپا لے تو اس پر جرمانہ ہے اور (مزید) اس کے ساتھ اس کا مثل بھی۔ “","f2":"(1)گمشدہ قیمتی چیز اٹھا کر چھپا لینا حرام اور گناہ کا کام ہے۔ (2)اس حدیث کی روشنی میں ایسے مجرم پردوگنا جرمانہ ہے۔"}],[1719,"عبدالرحمٰن بن عثمان تیمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حاجی کے لقطے سے منع فرمایا۔ احمد کہتے ہیں: ابن وہب نے کہا: یعنی حاجی کے لقطے کے بارے میں کہ وہ اسے چھوڑ دے، یہاں تک کہ اس کا مالک اسے پا لے، ابن موہب نے«أخبرني عمرو» کے بجائے «عن عمرو» کہا ہے۔","صحیح",{"u2":"سیدنا عبدالرحٰمن بن عثمان تیمی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حاجیوں کی گری پڑی چیزیں اُٹھانے سے منع فرمایا ہے۔ احمد نے روایت کیا کہ ابن وہب نے کہا ” حاجی کی چیز پڑی رہنے دی جائے حتیٰ کہ اس کا مالک اسے پالے۔ “ ابن موہب نے (اپنی سند میں) «عن عمرو» کہا ہے۔ («أخبرني عمرو» نہیں کہا)۔","f2":"راجح یہی ہے کہ حاجیوں کی گری پڑی اشیاء نہ اٹھائی جائیں تاکہ اس شہر کی حرمت اپنے وسیع تر معانی میں قائم اور ثابت رہے تاہم اگر ضائع ہوجانے کا اندیشہ ہوتو رخصت ہے کہ اٹھا لی جائے۔جیسے کہ صحیحین میں حضرت ابو ہریرہ اور ابن عباس سے مرفوع احادیث میں آیا ہے۔دیکھیے: (صحیح البخاری اللقطة حدیث:2433 2434 وصحیح مسلم اللقطة حدیث:1724)اور خوب کثرت سے اعلان کرنا چاہیے۔ممکن ہے یہ چیز کسی آفاقی حاجی کی ہو۔نہ معلوم اسے دوبارہ یہاں آنا میسر بھی آتاہے یا نہیں۔علامہ ابن القیم رحمہ اللہ بھی یہی فرماتے ہیں کہ چونکہ حجاج بڑی جلدی اپنے علاقوں کو واپس چلے جاتے ہیں اس لیے پورے سال تک اس کا اعلان ممکن نہیں اس لیے بہتر یہی ہے کہ چیز نہ اٹھائی جائے اور اگر اٹھائی جائے تو بہت جلد اور بار بار اعلان کیا جائے۔"}],[1720,"منذر بن جریر کہتے ہیں میں جریر کے ساتھ بوازیج ۱؎ میں تھا کہ چرواہا گائیں لے کر آیا تو ان میں ایک گائے ایسی تھی جو ان کی گایوں میں سے نہیں تھی، جریر نے اس سے پوچھا: یہ کیسی گائے ہے؟ اس نے کہا: یہ گایوں میں آ کر مل گئی ہے، ہمیں نہیں معلوم کہ یہ کس کی ہے، جریر نے کہا: اسے نکالو، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"گمشدہ جانور کو کوئی گم راہ ہی اپنے پاس جگہ دیتا ہے\" ۲؎۔\n§وضاحت\n۱؎ : ’’بوازيج‘‘ : (عراق میں) نہر دجلہ کے قریب ایک شہر کا نام ہے۔ ۲؎ : مطلب یہ ہے کہ کسی گم شدہ جانور کو اپنا بنا لینے کے لئے اس کو پکڑ لے تو وہ گمراہ ہے، رہا وہ شخص جو اسے اس لئے پکڑے تا کہ اس کی پہچان کرا کر اسے اس کے مالک کے حوالہ کر دے تو اس میں کوئی حرج نہیں کیونکہ امام مسلم نے اپنی صحیح میں زید بن خالد جہنی رضی اللہ عنہ کی روایت نقل کی ہے جس کے الفاظ یہ ہیں: «من آوى ضالة فهو ضال ما لم يعرفها» اور نسائی کی روایت کے الفاظ یوں ہیں: «من أخذ لقطة فهو ضال ما لم يعرفها»جو آدمی گم شدہ چیز اپنے پاس رکھے وہ گمراہ ہے جب تک کہ وہ اس کی تشہیر نہ کرے۔","صحیح",{"u2":"منذر بن جریر کہتے ہیں کہ (میں اپنے والد) جریر (جریر بن عبداللہ البجلی رضی اللہ عنہ) کے ساتھ بو (ازیج) مقام ازیج میں تھا کہ چرواہا گائیں لے کر آیا۔ اور ان میں ایک گائے ان کی نہیں تھی۔ سیدنا جریر رضی اللہ عنہ نے پوچھا: یہ کیا ہے؟ اس نے کہا: بس گایوں کے ساتھ مل گئی ہے۔ ہمیں معلوم نہیں کہ کس کی ہے۔ تو سیدنا جریر رضی اللہ عنہ نے کہا: اسے علیحدہ کر دو۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے: ” گمشدہ چیز کو کوئی «ضال» گمراہ انسان ہی لیتا ہے۔ “","f2":"(1)گمشدہ چیز اپنے قبضے میں لےکر چھپا لینے والا یامالک بن بیٹھنے والا ضال اور گمراہ انسان ہے جبکہ اعلان کرنے والا ایسا نہیں ہوتا۔ممکن ہے کہ حضرت جریر کا خیال ہو کہ گائے اونٹ کی طرح ہے یہ جانور کھاپی کر گزارہ کر سکتا ہے اور چھوٹے موٹے درندے بھی اس پر حملہ آور نہیں ہو سکتے تواس لیے اس کا چھوڑ دینا بہتر ہوگا۔اس کامالک اس کو خود ہی ڈھونڈ لے گا۔(2) بوازیج الانبار بغداد کی بالائی جانب ایک علاقہ ہے جسے حضرت جریر نے فتح کیا تھا اور یہاں ان کے موالی رہتے تھے۔"}],[1721,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اقرع بن حابس رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! کیا حج ہر سال (فرض) ہے یا ایک بار؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"(ہر سال نہیں) بلکہ ایک بار ہے اور جو ایک سے زائد بار کرے تو وہ نفل ہے\" ۱؎۔ ابوداؤد کہتے ہیں: ابوسنان سے مراد ابوسنان دؤلی ہیں، اسی طرح عبدالجلیل بن حمید اور سلیمان بن کثیر نے زہری سے نقل کیا ہے، اور عقیل سے ابوسنان کے بجائے صرف سنان منقول ہے۔\n§وضاحت\n۱؎ : حج اسلام کا پانچواں بنیادی رکن ہے، جس کی فرضیت ۵ یا ۶ ہجری میں ہوئی۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ سیدنا اقرع بن حابس رضی اللہ عنہ سے نبی کریم صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کہ رسول! کیا حج ہر سال ہے یا ایک ہی بار؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں! ایک ہی بار ہے اور جو اس سے زیادہ کرے تو وہ نفل ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ راوی حدیث (ابوسنان) یہ ابوسنان الدؤلی ہیں۔ عبدالجلیل بن حمید اور سلیمان بن کثیر سبھی زہری سے (ابوسنان) ذکر کرتے ہیں۔ صرف عقیل ” سنان “ کہتے ہیں۔ (ابوسنان نہیں کہتے)۔"}],[1722,"ابوواقد لیثی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حجۃ الوداع میں اپنی ازواج مطہرات سے فرماتے سنا: \"یہی حج ہے پھر چٹائیوں کے پشت ہیں\" ۱؎۔\n§وضاحت\n۱؎ : یعنی اس کے بعد تمہیں گھروں میں ہی رہنا ہے تم پر کوئی اور حج واجب نہیں، مؤلف نے اس حدیث سے اس بات پر استدلال کیا ہے کہ حج زندگی میں صرف ایک بار فرض ہے۔","صحیح",{"u2":"سیدنا ابوواقد اللیثی رضی اللہ عنہ سے منقول ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم اپنی ازواج سے حجتہ الوداع میں فر رہے تھے ” حج بس یہ ہے، پھر (گھر کی) چٹائیوں کو لازم پکڑنا ہے۔ “","f2":"یہ دلیل ہے کہ حج ایک ہی بار فرض ہے۔علاوہ ازیں نفل ہے۔ تاہم حج وعمرہ بار بار کرنے کی ترغیب بھی آئی ہے۔آپ صلی اللہ علیہ وسلم کا فرمان ہے حج اور عمرہ باربار کرو بلاشبہ یہ فقیری اور گناہوں کو دور کرتے ہیں جیسے کہ بھٹی لوہے سونے اور چاندی کامیل کچیل دور کر دیتی ہے اور پاک صاف حج کا ثواب جنت کے علاوہ اور کچھ نہیں۔(جامع ترمذی المناسک حدیث:810 وسنن نسائی حدیث:2631)"}],[1723,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان عورت کے لیے یہ حلال نہیں کہ وہ ایک رات کی مسافت کا سفر کرے مگر اس حال میں کہ اس کے ساتھ اس کا کوئی محرم ہو\" ۱؎۔\n§وضاحت\n۱؎ : اس حدیث میں ایک رات کی قید اتفاقی ہے، مقصد یہ نہیں کہ اس سے کم کا سفر غیر محرم کے ساتھ جائز ہے، محرم شوہر ہے یا وہ شخص جس سے ہمیشہ کے لئے نکاح حرام ہو، مثلاً باپ ، دادا، نانا، بیٹا ، بھائی، چچا، ماموں، بھتیجا ، بھانجا ، داماد وغیرہ وغیرہ، یا رضاعت سے ثابت ہونے والے رشتہ دار۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کسی مسلمان خاتون کو اپنے کسی محرم کی معیت کے بغیر ایک رات کا سفر بھی حلال نہیں ہے۔ “","f2":"حدیث اپنے مفہوم میں بالکل واضح ہے کہ کوئی عورت ایک رات کا سفر بھی محرم کے بغیر نہیں کر سکتی خواہ یہ حج جیسا مبارک سفرہی کیوں نہ ہو۔ اگر بالفرض کسی خاتون کوکوئی سا بھی میسر نہ ہو تو وہ حج کےلیے لازمی استطاعت سے خارج ہے اور اس پر حج فرض نہ ہوگا۔تفصیلات کےلیے دیکھیے (نیل الاوطار:4/324)تاہم بعض علماء مخصوص حالات میں مخصوص شرائط کےساتھ عورت کو محرم کے بغیر حج کی اجازت دیتے ہیں۔مثلاً عمر ہ رسیدہ خاتون جس کی جوانی ڈھل چکی ہو وہ ایسے اعتماد قافلے کے ساتھ سفر حج اختیار کر سکتی ہے جس میں قابل اعتماد خواتین بھی ہوں۔(2)محرم وہ شخص ہے جس سے ہمیشہ کے لیے عورت کانکاح کرنا حرام ہو جیسے باپ دادا چچا تایا ماموں بھانجا بھتیجا بیٹا سسر وغیرہ۔"}],[1724,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ اور یوم آخرت پر ایمان رکھنے والی عورت کے لیے یہ حلال نہیں کہ وہ ایک دن اور ایک رات کا سفر کرے\"۔ پھر انہوں نے اسی مفہوم کی حدیث ذکر کی جو اوپر گزری۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جو عورت اللہ اور یوم آخرت پر ایمان رکھتی ہے، اس کیلئے حلال نہیں کہ ایک دن اور رات کا سفر کرے۔ “ اور مذکورہ بالا کے ہم معنی بیان کیا۔ (یعنی اس کا محرم کے بغیر سفر کرنا حرام ہے) نفیلی نے «عن مالك» کی بجائے تحدیث کی صراحت کرے ہوئے «حدثنا مالك» کہا ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ نفیلی اور قعنبی نے (سند میں سعید بن ابی سعید کے بعد) «عن أبيه» نہیں کہا۔ نیز ابن وہب اور عثمان بن عمر بھی جناب مالک سے ایسے ہی روایت کرتے ہیں جیسے کہ قعنبی نے کہا ہے۔ («عن أبيه» کے بغیر)۔","f2":"جناب سعید مقبری کو اپنے والد کے علاوہ حضرت ابوہریرہ سے بھی سماع حاصل ہے۔ اس لیے دونوں ہی سندیں صحیح ہیں۔(نووی)"}],[1725,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، پھر انہوں نے اسی جیسی روایت ذکر کی البتہ اس میں (دن رات کی مسافت کے بجائے) «بريدا» کہا ہے ۱؎۔\n§وضاحت\n۱؎ : «برید» : چار فرسخ کا ہوتا ہے، اور ایک فرسخ تین میل کا، اس طرح «برید» بارہ میل کا ہوا۔","شاذ",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور مذکورہ بالا حدیث کی مانند ذکر کیا، مگر «بريدا» کا لفظ کہا۔ (یعنی کسی مسلمان عورت کو اپنے محرم کے بغیر ایک برید کا سفر بھی حلال نہیں)۔","f2":"یہ برید والی روایت بعض ائمہ کے نزدیک شاذ ہے۔اور ایک [برید] چار فرسخ کا اور ایک فرسخ تین میل کا ہوتا ہے۔(برید بارہ میل کاہوا)جو علماء کےنزدیک آدھے دن کی مسافت ہوتی ہے۔ اس اعتبار سےان ائمہ کے نزدیک عورت کا بغیر محرم کے مختصر سفر کرنا جائز ہو گا جب کہ دوسرے ائمہ کے نزدیک مطلقاً عورت کا بغیر محرم کے سفر کرنا ناجائز ہو گا۔"}],[1726,"ابوسعید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی عورت کے لیے جو اللہ اور یوم آخرت پر ایمان رکھتی ہو یہ حلال نہیں کہ وہ تین یا اس سے زیادہ دنوں کی مسافت کا سفر کرے سوائے اس صورت کے کہ اس کے ساتھ اس کا باپ ہو یا اس کا بھائی یا اس کا شوہر یا اس کا بیٹا یا اس کا کوئی محرم ۱؎\"۔\n§وضاحت\n۱؎ : جیسے : نانا، دادا، چچا ، ماموں ، بھتیجا ، اور بھانجا وغیرہ جو سب کے سب سگے ہوں، یا رضاعی۔","صحیح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” وہ عورت جو اللہ اور آخرت پر ایمان رکھتی ہو اس کے لیے حلال نہیں کہ اپنے باپ، بھائی، خاوند، بیٹے یا کسی محرم کی معیت کے بغیر تین دن یا اس سے زیادہ کا سفر کرے۔ “"}],[1727,"عبداللہ بن عمر رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"عورت تین دن کا سفر نہ کرے مگر اس حال میں کہ اس کے ساتھ کوئی محرم ہو\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” عورت اپنے محرم کے بغیر تین دن کا (بھی) سفر نہ کرے۔ “","f2":"مذکورہ بالا دیگر احادیث میں وقت یا مسافت کی تحدید کا ذکر ایک اتفاقی بیان ہے جو مختلف اوقات میں مختلف سائلین کے بتایا گیا۔ اور ان سب کا مفہوم واضح ہے کہ مسلمان متقی خاتون کو اپنے محرم کی معیت کے بغیر سفر کرنا حرام ہے۔دور حاضر کے احوال و ظروف کیسے بھی ہوں شریعت کا قانون اٹل ہے۔مسلمان پر فرض ہے کہ اپنے آپ کے اس شریعت کاپابند بنائے نہ کہ حیل وحجت سے شریعت کو بدلنے کی کوشش کرے۔والله المستعان ."}],[1728,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما اپنی لونڈی کو جسے صفیہ کہا جاتا تھا اپنے ساتھ سواری پر بیٹھا کر مکہ لے جاتے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ وہ اپنی لونڈی کو اپنے ساتھ بٹھا کر لے جاتے تھے۔ اس کا نام صفیہ تھا۔ وہ ان کے ساتھ مکہ کا سفر کرتی تھی۔","f2":"مالک لونڈی کے لیے خاوند کے حکم میں ہوتا ہے۔"}],[1729,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسلام میں «صرورة» نہیں ہے\"۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسلام میں «صرورة» نہیں ہے۔ “ (کوئی شخص باوجود استطاعت کے حج کرنے سے اعراض کر لے)۔","f2":"عمر بن عطاء یعنی ابن ابی خوار ضعیف راوی ہے کئی ایک نے اس کو ضعیف کہا۔ [صرورة] (صاد کے فتحہ کے ساتھ،)کےایک معنی تو یہی ہیں جو ذکر ہوئے دوسرے معنی اس کے یہ بھی ہیں کہ کوئی راہیوں کے سے اندازمیں زندگی گزارے اور نکاح نہ کرے۔ یہ اسلام میں نہیں ہے۔"}],[1730,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ لوگ حج کو جاتے اور زاد راہ نہیں لے جاتے۔ ابومسعود رضی اللہ عنہ کہتے ہیں: اہل یمن یا اہل یمن میں سے کچھ لوگ حج کو جاتے اور زاد راہ نہیں لیتے اور کہتے: ہم متوکل (اللہ پر بھروسہ کرنے والے) ہیں تو اللہ نے آیت کریمہ«وتزودوا فإن خير الزاد التقوى» ۱؎ (زاد راہ ساتھ لے لو اس لیے کہ بہترین زاد راہ یہ ہے کہ آدمی سوال سے بچے) نازل فرمائی۔\n§وضاحت\n۱؎ : سورة البقرة: (۱۹۸)","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ لوگ حج کو آتے مگر زاد راہ ساتھ نہ لاتے تھے۔ ابومسعود نے کہا کہ اہل یمن یا کچھ اہل یمن حج کے لیے آتے مگر زاد راہ ساتھ نہ لاتے اور کہتے کہ ہم متوکل لوگ ہیں۔ پس اللہ تعالیٰ نے یہ آیت نازل فرمائی: «وتزودوا فإن خير الزاد التقوى» ” زاد راہ (یعنی اخراجات سفر) ساتھ لے کر چلو اس لیے کہ بہترین توشہ تقویٰ (سوال سے بچنا) ہے۔ “","f2":"اس آیت کریمہ میں اللہ عز وجل نے حکم دیا ہے کہ سفر میں کھانے پینے اور اقامت کے علاوہ دیگر تمام لوازم کے اخراجات لے کر آیا کرو۔ ان کے بغیر نکل کھڑے ہونا اور پھر لوگوں کی طرف دیکھنا یا سوال کرتے پھرنا اور اس کا نام توکل رکھنا بالکل غلط ہے۔ توکل کے مفہوم میں یہ ہے کہ مشروع اسباب اختیار کر لینے کے بعد اللہ تعالیٰ پر کامل اعتماد کیا جائے۔ تاہم کچھ احادیث سے یہ معنی ضرور ملتا ہے کہ اگر کوئی شخص اس انداز میں اسباب ترک کر دیتا ہےکہ اسباب یامخلوق کی طرف اس کی نظر قطعاً نہ جائے تو اسے بھی متوکل کہا گیا ہے مگر یہ ازحد مشکل مقام ہے۔"}],[1731,"عبداللہ بن عباس رضی اللہ عنہما سے روایت کرتے ہوئے راوی کہتے ہیں انہوں نے یہ آیت «ليس عليكم جناح أن تبتغوا فضلا من ربكم» ۱؎ \"تم پر اس میں کوئی گناہ نہیں ہے کہ تم اپنے رب کا فضل تلاش کرو\" پڑھی اور بتایا کہ عرب کے لوگ منی میں تجارت نہیں کرتے تھے تو انہیں عرفات سے واپسی پر منی میں تجارت کا حکم دیا گیا۔\n§وضاحت\n۱؎ : سورة البقرة: (۱۹۸)","صحیح",{"u2":"جناب مجاہد بیان کرتے ہیں کہ سیدنا عبداللہ بن عباس رضی اللہ عنہ نے آیت کریمہ «ليس عليكم جناح أن تبتغوا فضلا من ربكم» ” تم پر کوئی گناہ نہیں کہ اپنے رب کا فضل تلاش کرو۔ “ پڑھی اور فرمایا: کچھ لوگ منٰی میں تجارت نہ کرتے تھے تو انہیں حکم دیا گیا کہ جب عرفات سے واپس لوٹیں تو تجارت کر سکتے ہیں۔","f2":"(1)اس آیت کریمہ میں وضاحت ہے کہ احرام باندھ لینے کے بعد تجارت جیسے مشغلہ میں مشغول ہونا کہ فرائض اور واجبات بھی ادا ہونے رہیں کوئی حرج یا عیب کی بات نہیں۔ (2)اس مباح انداز سےزاد راہ حاصل کرناعین حلال ہے۔"}],[1732,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص حج کا ارادہ کرے تو اسے جلدی انجام دے لے ۱؎\"۔\n§وضاحت\n۱؎ : کیونکہ تاخیر کی صورت میں اسے مختلف رکاوٹوں کا سامنا کرنا پڑ سکتا ہے، اور وہ ایک فرض کا تارک ہو کر اس دنیا سے رخصت ہو گا۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو حج کرنا چاہے تو چاہیئے کہ جلد ہی کر لے۔ “","f2":"بیہقی کی روایت میں اضافہ ہے کہ نہ معلوم اسے کوئی بیماری آلے یا کوئی اورعارضہ پیش آجائے۔ (السنن الکبری للبیہقی:4/340)بہر حال اس حدیث میں دلیل ہے کہ استطاعت حاصل ہوتے ہی حج فوراً فرض ہو جاتاہے۔زندگی کا کیا اعتبار! نیز قیامت سے پہلے بیت اللہ کا حج موقوف ہو جائے گا اس لیے امن وامان کے حالات کو غنیمت جاننا چاہیے۔اور معقول عذر شرعی کےبغیر اس میں تاخیر نہیں کرنی چاہیے۔ البتہ ایک حدیث میں یہ گنجائش ملتی ہے کہ صاحب استطاعت اور صحت مند زیادہ سے زیادہ چار سال تک تاخیر کر سکتا ہے پانچویں سال اسے یہ فریضہ ضرور ادا کر لینا چاہیے۔ (صحیح الترغیب:2/42 رقم:1166)"}],[1733,"ابوامامہ تیمی کہتے ہیں کہ میں لوگوں کو سفر حج میں کرائے پر جانور دیتا تھا، لوگ کہتے تھے کہ تمہارا حج نہیں ہوتا، تو میں ابن عمر رضی اللہ عنہما سے ملا اور ان سے عرض کیا: ابوعبدالرحمٰن! میں حج میں لوگوں کو جانور کرائے پر دیتا ہوں اور لوگ مجھ سے کہتے ہیں تمہارا حج نہیں ہوتا، تو ابن عمر رضی اللہ عنہما نے کہا: کیا تم احرام نہیں باندھتے؟ تلبیہ نہیں کہتے؟ بیت اللہ کا طواف نہیں کرتے؟ عرفات جا کر نہیں لوٹتے؟ رمی جمار نہیں کرتے؟ میں نے کہا: کیوں نہیں، تو انہوں نے کہا: تمہارا حج درست ہے، ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں آیا اور اس نے آپ سے اسی طرح کا سوال کیا جو تم نے مجھ سے کیا تو آپ صلی اللہ علیہ وسلم نے سکوت فرمایا اور اسے کوئی جواب نہیں دیا یہاں تک کہ آیت کریمہ «ليس عليكم جناح أن تبتغوا فضلا من ربكم» \"تم پر کوئی گناہ نہیں اس میں کہ تم اپنے رب کا فضل ڈھونڈو\" نازل ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے اسے بلا بھیجا اور اسے یہ آیت پڑھ کر سنائی اور فرمایا: \"تمہارا حج درست ہے\"۔","صحیح",{"u2":"جناب ابوامامہ تیمی بیان کرتے ہیں کہ میں سفر میں کرائے کی سواریاں چلایا کرتا تھا تو بعض لوگوں نے مجھ سے کہا: ” تیرا حج نہیں ہے۔ “ میں سیدنا ابن عمر رضی اللہ عنہ سے ملا اور ان سے پوچھا کہ اے ابو عبدالرحمٰن! میں سفر حج میں کرائے پر سواریاں چلاتا ہوں اور کچھ لوگ مجھے کہتے ہیں کہ تیرا حج نہیں ہے۔ تو سیدنا ابن عمر رضی اللہ عنہ نے جواب دیا: کیا تم احرام نہیں باندھتے ہو اور تلبیہ نہیں پڑھتے ہو؟ کیا بیت اللہ کا طواف نہیں کرتے ہو؟ عرفات سے نہیں لوٹتے ہو؟ اور جمرات کو کنکریاں نہیں مارتے ہو؟ میں نے کہا: کیوں نہیں (سب کچھ کرتا ہوں) انہوں نے فرمایا: بلاشبہ تیرا حج (صحیح) ہے۔ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا تھا اور اس نے بالکل یہی سوال کیا تھا جیسے کہ تم نے مجھ سے کیا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم خاموش ہو رہے اور اس کو جواب نہیں دیا تھا حتیٰ کہ یہ آیت کریمہ نازل ہوئی «ليس عليكم جناح أن تبتغوا فضلا من ربكم» ” تم پر کوئی گناہ (اور حرج) نہیں کہ اپنے رب کا فضل تلاش کرو۔ “ رسول اللہ صلی اللہ علیہ وسلم نے اس کو بلا بھیجا اور اس پر یہ آیت پڑھی اور فرمایا: تیرا حج (صحیح) ہے۔"}],[1734,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ لوگ شروع شروع میں منی، عرفہ اور ذوالمجاز کے بازاروں اور حج کے موسم میں خرید و فروخت کیا کرتے تھے پھر انہیں حالت احرام میں خرید و فروخت کرنے میں تامل ہوا، تو اللہ نے «ليس عليكم جناح أن تبتغوا فضلا من ربكم» \"تم پر اس میں کوئی گناہ نہیں کہ تم اپنے رب کا فضل تلاش کرو\" نازل کیا یعنی حج کے موسم میں۔ عطا کہتے ہیں: مجھ سے عبید بن عمیر نے بیان کیا کہ وہ (ابن عباس) اسے «في مواسم الحج» اپنے مصحف میں پڑھا کرتے تھے ۱؎۔\n§وضاحت\n۱؎ : «في مواسم الحج» کا لفظ اس روایت کے مطابق ابن عباس رضی اللہ عنہما کے مصحف میں اس آیت کا ٹکڑا تھا، مگر یہ قرات شاذ ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ لوگ پہلے (قبل از اسلام) حج کے دنوں میں منٰی، عرفات، سوق ذی المجاز اور ایام حج میں خرید و فروخت کیا کرتے تھے۔ (اسلام لانے کے بعد) انہوں نے احرام باندھے ہوئے خرید و فروخت میں حرج سمجھا تو اللہ سبحانہ و تعالیٰ نے یہ آیت اتاری «ليس عليكم جناح أن تبتغوا فضلا من ربكم سورة البقرة آية 198 في مواسم الحج» ” تم پر کوئی حرج یا گناہ نہیں کہ ” ایام حج “ میں اللہ کا فضل تلاش کرو۔ “ عبید بن عمیر نے بیان کیا کہ وہ «في مواسم الحج» کے اضافہ کے ساتھ، مصحف میں پڑھا کرتے تھے۔","f2":"(1)سوق ذی المجاز عرفات کے قریب ایک منڈی کا نام تھا۔ بعض نے لکھا ہے کہ یہ منی کے قریب لگتی تھی۔ (2)مذکورہ قسم کی قراءت شاذ کہلاتی ہے جو تفسیر وتوضیح کا فائدہ دیتی ہے۔ اصل صحیح قراءت وہی ہے جوتواتر سے ثابت ہے۔(3)احرام باندھ لینے کےبعد امور تجارت میں مشغول ہونا حج کےلیے کوئی باعث نقص نہیں ہے۔"}],[1735,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ لوگ حج کے ابتدائی زمانے میں خرید و فروخت کرتے تھے پھر انہوں نے اسی مفہوم کی روایت ان کے قول «مواسم الحج» تک ذکر کیا۔","صحیح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے مروی ہے کہ لوگ پہلے زمانے میں حج کے دوران میں خرید و فروخت کیا کرتے تھے۔ اور مذکورہ بالا کے ہم معنی روایت کیا «مواسم الحج» تک۔"}],[1736,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مقام روحاء میں تھے کہ آپ کو کچھ سوار ملے، آپ صلی اللہ علیہ وسلم نے انہیں سلام کیا اور پوچھا: \"کون لوگ ہو؟\"، انہوں نے جواب دیا: ہم مسلمان ہیں، پھر ان لوگوں نے پوچھا: آپ کون ہو؟ لوگوں نے انہیں بتایا کہ آپ اللہ کے رسول صلی اللہ علیہ وسلم ہیں تو ایک عورت گھبرا گئی پھر اس نے اپنے بچے کا بازو پکڑا اور اسے اپنے محفے ۱؎ سے نکالا اور بولی: اللہ کے رسول! کیا اس کا بھی حج ہو جائے گا ۲؎؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، اور اجر تمہارے لیے ہے\"۔\n§وضاحت\n۱؎ : ہودج کی طرح عورتوں کی سواری پر ایک سیٹ ہوتی ہے جسے محفّہ کہتے ہیں۔ ۲؎ : اس حدیث سے معلوم ہوا کہ نابالغ کا حج صحیح ہے چونکہ اس کا ولی اس کی جانب سے کم سنی کی وجہ سے اعمال حج ادا کرتا ہے، اس لئے وہ ثواب کا مستحق ہو گا، واضح رہے اس سے حج کی فرضیت ساقط نہیں ہو گی، بلکہ بلوغت کے بعد استطاعت کی صورت میں اس پر حج فرض ہے، اور بچپن کا حج اس کے لئے نفل ہو گا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم مقام روحاء پر تھے کہ آپ کو ایک قافلے والے ملے۔ آپ نے انہیں سلام کہا اور پوچھا: کون لوگ ہو؟ انہوں نے کہا: ہم مسلمان ہیں۔ انہوں نے پوچھا: آپ کون لوگ ہیں؟ صحابہ رضی اللہ عنہم م نے کہا: یہ اللہ تعالیٰ کے رسول ہیں۔ تو ایک عورت نے جلدی سے اپنے بچے کو بازو سے پکڑا اور اپنے ہودج سے باہر نکالا اور بولی: اے اللہ کے رسول! کیا اس کے لیے حج ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہاں! اور تیرے لیے اجر ہے۔“","f2":"چھوٹے بچے اگر والدین یا سر پرستوں کے ساتھ ہوں توانہیں بھی اعمال حج میں شریک کیاجائے۔جہاں تک وہ از خود ساتھ دے سکیں بہتر ہے باقی والدین کروائیں۔ طواف اور سعی میں اٹھائیں۔ عرفات مزدلفہ میں ساتھ رکھیں۔ ان کی طرف سے کنکریاں ماریں وغیرہ۔ان ثواب والدین کے لیے ہے اور یہ کتنی بڑی نعمت اور فضیلت ہے کہ کم خرچ اور معمولی مشقت سےمزید حج کاثواب مل جائے۔ایک بچہ ہو تو ایک حج دو ہوں تو دو حج کا ثواب ملے گا علی ہذاالقیاس۔تاہم بلوغت کے بعد انہیں اپنا حج اسلام کرنا ہوگا۔"}],[1737,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل مدینہ کے لیے ذوالحلیفہ، اہل شام کے لیے جحفہ اور اہل نجد کے لیے قرن کو میقات ۱؎ مقرر کیا، اور مجھے یہ بات پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے اہل یمن کے لیے یلملم ۲؎ کو میقات مقرر کیا۔\n§وضاحت\n۱؎ : میقات اس مقام کو کہتے ہیں جہاں سے حاجی یا معتمر احرام باندھ کر حج یا عمرہ کی نیت کرتا ہے۔ ۲؎ : یلملم ایک پہاڑ ہے جو مکہ سے دو دن کے فاصلہ پر واقع ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل مدینہ کے لیے ذوالحلیفہ (موجودہ آبارعلی)، اہل شام کے لیے جحفہ اہل نجد کے لیے قرن المنازل کے مقامات متعین فرمائے تھے۔ اور مجھے یہ خبر بھی پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے اہل یمن کے لیے یلملم متعین کیا تھا۔"}],[1738,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے میقات مقرر کیا پھر ان دونوں نے اسی مفہوم کی حدیث ذکر کی، ان دونوں (راویوں میں سے) میں سے ایک نے کہا: \"اہل یمن کے لیے یلملم\"، اور دوسرے نے کہا: «ألملم» ، اس روایت میں اتنا اضافہ ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ ان لوگوں کی میقاتیں ہیں اور ان کے علاوہ لوگوں کی بھی جو ان جگہوں سے گزر کر آئیں اور حج و عمرہ کا ارادہ رکھتے ہوں، اور جو لوگ ان کے اندر رہتے ہوں\"۔ ابن طاؤس (اپنی روایت میں) کہتے ہیں: ان کی میقات وہ ہے جہاں سے وہ سفر شروع کریں یہاں تک کہ اہل مکہ مکہ ہی ۱؎ سے احرام باندھیں گے۔\n§وضاحت\n۱؎ : معلوم ہوا کہ حاجی یا معتمر اگر مکہ یا مذکورہ مواقیت کے اندر رہتا ہو تو اس کا حکم عام لوگوں سے مختلف ہے اس کے لئے میقات پر جانا ضروری نہیں بلکہ اپنے گھر سے نکلتے وقت ہی احرام باندھ لینا اس کے لئے کافی ہو گا۔","صحیح",{"u2":"حماد، عمرو بن دینار سے، وہ طاؤس سے، وہ ابن عباس رضی اللہ عنہ سے اور ابن طاؤس (عبداللہ) اپنے باپ طاؤس سے (وہ ابن عباس رضی اللہ عنہ سے) روایت کرتے ہیں کہ ان دونوں (عمرو بن دینار اور عبداللہ بن طاؤس) نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے میقات (مقامات احرام) مقرر فرمائے تھے۔ ان دونوں میں سے ایک نے کہا کہ اہل یمن کے لیے یلملم اور دوسرے نے کہا العلم۔ آپ نے فرمایا ” یہ مقامات ان (مذکورہ) جگہوں کے رہنے والوں کے لیے ہیں اور دوسری جگہوں کے ان لوگوں کے لیے بھی جو یہاں سے گزریں جو کہ حج اور عمرہ کی نیت رکھتے ہوں اور جو ان سے ورے (مکہ کی جانب) مقیم ہوں۔ “ ابن طاؤس نے کہا: وہ وہیں سے احرام باندھیں جہاں سے وہ سفر شروع کریں حتیٰ کہ اہل مکہ اپنے شہر اور گھر ہی سے احرام باندھ کر نکلیں۔","f2":"ان مقامات سے احرام باندھنا انہی لوگوں پر واجب ہے جو حج یا عمرہ کی نیت رکھتے ہوں دوسروں کے لیے نہیں ہے۔یلملم: بیت اللہ کے جنوب میں ایک مقام ہے جو یمن چین بنگلہ دیش افغانستان ہندوستان اور پاکستا ن کی طرف سے آنے والوں کی میقات ہے۔یہ مکہ مکرمہ سے 92کلومیٹر پر واقع ہے۔ ذوالحلیفه: مدینہ منورہ اور اس سے ملحقہ علاقوں کی طرف سے آنے والوں کی میقات۔ اس کاموجودہ نام آبار علی ہے۔مدینہ سے قریب تر اور مکہ سے تقریباً ساڑھے چار سو کلومیٹر کے فاصلے پر واقع ہے۔ جحفه: شام ترکی اور مصر کی جانب سے آنے والوں کی میقات۔ اب یہ بستی موجود نہین مگر قریب ہی رابغ نامی جگہ سے لوگ احرام باندھتے ہیں۔یہ مکہ سےشمال مغرب میں 187 کلومیٹر کے فاصلے پر واقع ہے۔ذات العرق: عراق وغیرہ کی طرف سے آنے والوں کی میقات۔ اب یہ بستی موجود نہین مگر قریب ہی الضریبہ نامی جگہ سے لوگ احرام باندھتے ہیں۔جسے خریبات بھی کہتے ہین۔یہ مکہ سے شمال مشرق میں 94 کلومیٹر کے فاصلے پر ہے۔قرن المنازل: اہل نجد اور عرفات کی طرف آنے والوں کی میقات۔اب یہ بستی موجود نہیں مگر قریب ہی السیل نامی جگہ سے احرام باندھا جاتاہے جو مکہ سے 94 کلومیٹر دور ہے"}],[1739,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل عراق کے لیے ذات عرق ۱؎ کو میقات مقرر کیا۔\n§وضاحت\n۱؎ : سنن ترمذی کی ایک روایت سے پتہ چلتا ہے کہ اہل عراق کے لئے ذات عرق کو میقات عمر رضی اللہ عنہ نے متعین کیا تھا، لیکن یہ روایت ضعیف ہے، علماء نے یہ بھی فرمایا ہے کہ عمر رضی اللہ عنہ کو یہ حدیث نہیں معلوم تھی، آپ نے اپنے اجتہاد سے یہ میقات مقرر کی جو نبی کریم صلی اللہ علیہ وسلم کی بتائی ہوئی میقات کے عین مطابق ہو گئی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے اہل عراق کے لیے ” ذات عرق “ کا مقام متعین فرمایا تھا (احرام کے لیے)۔"}],[1740,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل مشرق کے لیے عقیق کو میقات مقرر کیا۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل مشرق کے لیے مقام ” عقیق “ مقرر فرمایا تھا۔","f2":"اہل مشرق سےمراد مکہ سے مشرقی جانب کے علاقے ہیں یعنی عراق اور اس کے اطراف۔ اور عقیق نامی وادی ایک تو مدینہ کے قریب ہے دوسری یہی ہے جو ذات عرق کے قریب اور اس کے مقابل میں ہے اور یہاں یہی دورسری مراد ہے۔(مرعاۃ المفاتیح حدیث: 2554)"}],[1741,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو مسجد الاقصی سے مسجد الحرام تک حج اور عمرہ کا احرام باندھے تو اس کے اگلے اور پچھلے گناہ معاف کر دیئے جائیں گے، یا اس کے لیے جنت واجب ہو جائے گی\"، راوی عبداللہ کو شک ہے کہ انہوں نے دونوں میں سے کیا کہا۔ ابوداؤد کہتے ہیں: اللہ وکیع پر رحم فرمائے کہ انہوں نے بیت المقدس سے مکہ تک کے لیے احرام باندھا۔","ضعیف",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا بیان کرتی ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جس نے مسجد اقصیٰ سے مسجد الحرام تک حج یا عمرے کا احرام باندھا، اس کے اگلے پچھلے سب گناہ معاف کر دیے جائیں گے۔ یا فرمایا: اس کے لیے جنت واجب ہو گئی۔ “ عبداللہ (ابن عبدالرحمٰن بن یحنس) کو شک ہوا ہے کہ معلوم نہیں آپ صلی اللہ علیہ وسلم نے دونوں سے کون سی بات کہی تھی۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اللہ تعالیٰ وکیع پر رحمت فرمائے، انہوں نے بیت المقدس سے مکہ کے لیے احرام باندھا۔","f2":"سیدہ ام سلمہ رضی اللہ عنہا کی روایت سنداً اور متن میں بہت اختلاف ہے۔ (منذری وغیرہ) اگر چہ کئی ایک صحابہ و تابعین سے قبل از میقات احرام باندھناثابت ہے مگر رسول اللہ صلی اللہ علیہ وسلم کے صریح فرمان سے کہ ’’آپ نے یہ یہ منازل متعین فرمائے تھے۔ ‘‘ یہی ثابت ہے کہ ان مقامات سے احرام باندھنا ہی سنت نبویہ اور افضل عمل ہے۔ (تفصیل کے لیے دیکھیے: مرعاۃ المفاتیح، حدیث نمبر:2540)"}],[1742,"حارث بن عمرو سہمی رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ منی میں تھے یا عرفات میں، اور لوگوں نے آپ صلی اللہ علیہ وسلم کو گھیر رکھا تھا، تو اعراب (دیہاتی) آتے اور جب آپ کا چہرہ دیکھتے تو کہتے یہ برکت والا چہرہ ہے، آپ صلی اللہ علیہ وسلم نے اہل عراق کے لیے ذات عرق کو میقات مقرر کیا۔","حسن",{"u2":"جناب حارث بن عمرو سہمی رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جبکہ آپ منٰی یا عرفات میں تھے۔ لوگوں نے آپ صلی اللہ علیہ وسلم کو گھیر رکھا تھا۔ بدوی لوگ آپ صلی اللہ علیہ وسلم کے پاس آتے تھے، جب آپ صلی اللہ علیہ وسلم کا چہرہ انور دیکھتے تو کہتے: ” یہ تو مبارک چہرہ ہے۔ “ حارث بیان کرتے ہیں کہ آپ نے اہل عراق کے لیے مقام ” ذات عرق “ کو میقات مقرر فرمایا۔"}],[1743,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ اسماء بنت عمیس رضی اللہ عنہا (ابوبکر رضی اللہ عنہ کی بیوی) کو مقام شجرہ میں محمد بن ابی بکر رضی اللہ عنہ کی (ولادت کی) وجہ سے نفاس آیا تو رسول اللہ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ کو حکم دیا کہ (اسماء سے کہو کہ) وہ غسل کر لے پھر تلبیہ پکارے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ اسماء بنت عمیس رضی اللہ عنہا ا (زوجہ ابوبکر صدیق رضی اللہ عنہا) نے شجرہ کے مقام پر محمد بن ابی بکر رضی اللہ عنہ کو جنم دیا تو رسول اللہ صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ سے فرمایا ” اسے چاہیئے کہ غسل کر کے احرام باندھ لے۔ “","f2":"مقام شجرہ سےمراد ذوالحلیفہ یا البیداء ہے جو اہل مدینہ کی میقات ہے۔"}],[1744,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حائضہ اور نفاس والی عورتیں جب میقات پر آ جائیں تو غسل کریں، احرام باندھیں اور حج کے تمام مناسک ادا کریں سوائے بیت اللہ کے طواف کے ۱؎\"۔ ابومعمر نے اپنی حدیث میں «حتى تطهر» \"یہاں تک کہ پاک ہو جائیں\" کا اضافہ کیا۔ ابن عیسی نے عکرمہ اور مجاہد کا ذکر نہیں کیا، بلکہ یوں کہا: «عن عطاء عن ابن عباس» اور ابن عیسی نے «كلها» کا لفظ بھی نقل نہیں کیا بلکہ صرف «المناسك إلا الطواف بالبيت» \"مناسک پورے کریں بجز خانہ کعبہ کے طواف کے\" کہا۔\n§وضاحت\n۱؎ : حیض اور نفاس والی عورت حیض یا نفاس سے پاک ہونے کے بعد طواف قدوم اور طواف عمرہ کرے گی، طواف میں جو تاخیر ہوگی اس سے اس کے حج میں کوئی نقض واقع نہیں ہو گا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” حیض اور نفاس والی عورتیں جب میقات پر پہنچیں تو غسل کر کے احرام باندھ لیں اور حج کے تمام اعمال سر انجام دیں، سوائے بیت اللہ کے طواف کے۔ “ ابومعمر کی روایت میں ہے ” حتیٰ کہ وہ پاک ہو جائیں۔ “ محمد بن عیسیٰ کی روایت میں عکرمہ اور مجاہد کا ذکر نہیں ہے بلکہ (اس کی سند) ” عطاء عن ابن عباس “ ہے ایسے ہی ابن عیسیٰ کی روایت میں «كلها» کا لفظ نہیں آیا بلکہ یوں کہا «المناسك إلا الطواف بالبيت»۔","f2":"(1)حیض ونفاس والی عورتیں حج وعمر ہ کے لیے غسل کر کے احرام باندھیں تلبیہ پکاریں اور تسبیحات استغفار اور اذکار میں مشغول رہیں۔ سوائے بیت اللہ کے طواف کے ان پر اور کوئی پابندی نہیں۔(2)ایسے ہی کسی کو احتلام ہو جائے تو اس کے احرام میں کوئی خلل نہیں آتا۔"}],[1745,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو جب آپ احرام باندھتے تو احرام باندھنے سے پہلے اور احرام کھولنے کے بعد اس سے پہلے کہ آپ طواف کریں خوشبو لگایا کرتی تھی ۱؎۔\n§وضاحت\n۱؎ : حالت احرام میں کسی قسم کی خوشبو کا استعمال درست نہیں، لیکن اگر یہی خوشبو احرام باندھتے وقت لگائی جائے تو مستحب ہے ، چاہے یہ خوشبو بدن یا کپڑے میں احرام کے بعد بھی باقی رہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام باندھنے کے وقت، احرام سے پہلے خوشبو لگایا کرتی تھی اور ایسے ہی احرام کھولنے کے بعد، بیت اللہ کا طواف کرنے سے پہلے۔"}],[1746,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ گویا میں رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں مشک کی چمک دیکھ رہی ہوں اور آپ احرام باندھے ہوئے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے، فرماتی ہیں کہ گویا میں کستوری کی اس چمک کو دیکھ رہی ہوں جو رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں لگی ہوتی جب کہ آپ صلی اللہ علیہ وسلم احرام میں ہوتے۔","f2":"(1)اثنائے احرام خوشبو استعمال نہیں کی جا سکتی البتہ احرام کی تیاری کے وقت غسل کرتے اور لباس بدلتے ہوئے احرام سے پہلے پہلے خوشبولگالینا سنتاہے۔ایسے ہی دس ذوالحج کو طواف افاضہ کے موقع پر۔ (2)اس خوشبو کا رنگ او راثر حالت احرام میں باقی رہے تو کوئی حرج نہیں۔ (3)محرم کو چاہیے کہ حالت احرام میں غسل کے لیے ایسا صابن استعمال کرے جس میں عطریات شامل نہ ہوں۔"}],[1747,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو تلبیہ پڑھتے سنا اور آپ اپنے سر کی تلبید ۱؎ کئے ہوئے تھے۔\n§وضاحت\n۱؎ : ’’تلبيد‘‘: بالوں کو گوند وغیرہ سے جما لینے کو تلبید کہتے ہیں، تاکہ وہ گرد وغبار نیز بکھرنے سے محفوظ رہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تلبیہ پکارتے ہوئے سنا جب کہ آپ صلی اللہ علیہ وسلم اپنے سر کے بال جمائے ہوئے تھے۔","f2":"بال جب لمبے ہوں توانہیں سنبھالنا ایک مسئلہ ہوتا ہے لہٰذا احرام کی حالت میں انہیں زیادہ پراگندہ ہونے یا بہت زیادہ گرد و غبار سےبچانے کےلیے کسی مناسب چیز سے چپکا لیا جائے تو یہ سنت ہے اور اس کو تلبید کہتے ہیں۔"}],[1748,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے سر کے بال شہد سے جمائے۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے «عسل» کے ساتھ اپنے بال چپکائے ہوئے تھے۔","f2":"[عسل] عین اور سین غیر منقوط کے فتحہ کے ساتھ معروف معنی شہد ہے مگر ایک قسم کی گوندل کو بھی [عسل]کہاجاتا ہے۔لسان العرب میں ہے۔[العرب تسمي صمغ العرقط عسلا لحلاوته] اہل عرب عرفط کی گوند کو بھی عسل کہتے ہیں کیونکہ اس میں مٹھاس ہوتی ہے۔ اگر یہ کلمہ غین منقوط کے کسرہ اور سین کے سکون کے ساتھ ہو تو اس کےمعنی ہیں۔ ہر وہ چیز جس سے انسان بالعموم غسل کرتا ہے۔شارحین اس سے مراد خطمی لیتے ہیں۔"}],[1749,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حدیبیہ کے سال ہدی ۱؎ کے لیے جو اونٹ بھیجا ان میں ایک اونٹ ابوجہل کا ۲؎ تھا، اس کے سر میں چاندی کا چھلا پڑا تھا، ابن منہال کی روایت میں ہے کہ \"سونے کا چھلا تھا\"، نفیلی کی روایت میں اتنا اضافہ ہے کہ \"اس سے آپ صلی اللہ علیہ وسلم مشرکین کو غصہ دلا رہے تھے ۳؎\"۔\n§وضاحت\n۱؎ : ’’ہدی‘‘: حج میں ذبح کے لئے لے جانے والے جانور کو کہتے ہیں۔ ۲؎ : یہ اونٹ رسول اللہ صلی اللہ علیہ وسلم کو جنگ میں بطور غنیمت ملا تھا۔ ۳؎ : تاکہ یہ تأثر دیا جائے کہ مشرکین کے سردار کا اونٹ مسلمانوں کے قبضے میں ہے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم حدیبیہ کے سال قربانی کے جانور (ساتھ) لے گئے۔ رسول اللہ صلی اللہ علیہ وسلم کی ان قربانیوں میں ایک اونٹ وہ بھی تھا جو ابوجہل کا تھا۔ اس کی ناک میں چاندی کا چھلا پڑا ہوا تھا۔ ابن منہال نے کہا: سونے کا چھلا پڑا ہوا تھا۔ نفیلی نے اضافہ کیا کہ آپ اسے مشرکوں کو جلانے کے لیے لے گئے تھے۔ (کہ ان کے سردار کا اونٹ محمد صلی اللہ علیہ وسلم کے قبضے میں ہے۔)","f2":"(1) جانوروں کی نکیل وغیرہ میں تھوڑی بہت چاندی کا استعمال مباح ہے۔ (2) اسلام اور مسلمانوں کا اظہار وغلبہ اورکفر و کفار کو زیر کرنا اور انہیں ذلیل رکھنا دین حق کا مطلوب و مقصود ہے۔ اس سے کفار جلتے اور مسلمانو ں کے سینے ٹھنڈے ہوتے ہیں۔رسول اللہ صلی اللہ علیہ وسلم کا ابوجہل کے اونٹ کو بطور خاص قربانی کے لیے لے جانا اسی مقصد سے تھا۔ اور یہ مضمون سورہ توبہ ی کی آیت 14اور 15 میں بھی آیا ہے فرمایا: ﴿قـٰتِلوهُم يُعَذِّبهُمُ اللَّهُ بِأَيديكُم وَيُخزِهِم وَيَنصُر‌كُم عَلَيهِم وَيَشفِ صُدورَ‌ قَومٍ مُؤمِنينَ * وَيُذهِب غَيظَ قُلوبِهِم .................. ﴾ ان سے تم جنگ کرو اللہ تعالیٰ انہیں تمہارے ہاتھوں عذاب دے گا، انہیں ذلیل ورسوا کرے گا، تمہیں ان پر مدد دے گا اور مسلمانوں کے کلیجے ٹھنڈے کرے گا اور ان کے دل کا غم وغصہ دور کرے گا۔"}],[1750,"ام المؤمنین عائشہ رضی اللہ عنہا فرماتی ہیں کہ حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم نے اپنے آل ۱؎ کی طرف سے ایک گائے کی قربانی کی ۲؎۔\n§وضاحت\n۱؎ : یہاں آل سے مراد ازواج مطہرات رضی اللہ عنہن ہیں۔ ۲؎ : ایک گائے یا اونٹ میں سات آدمی کی شرکت ہو سکتی ہے، اس حج میں آپ صلی اللہ علیہ وسلم کے ساتھ سات ہی ازواج مطہرات ہوں گی، یا بخاری ومسلم کے لفظ «ضحى» (قربانی کی) سے پتہ چلتا ہے کہ آپ صلی اللہ علیہ وسلم نے بطور ہدی نہیں بلکہ بطور قربانی ذبح کیا، تو پورے گھر والوں کی طرف سے گائے ذبح کی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجتہ الوداع میں آل محمد کی طرف سے ایک گائے ذبح کی تھی۔","f2":"(1)اس حدیث میں آل محمد سے مراد نبی صلی اللہ علیہ وسلم کی ازواج مطہرات ہیں۔ (2)بیوی بچوں کی طرف سے شوہر قربانی کرے تو جائز ہے۔ (3) ان کی تعداد کتنی ہی ہو سب کی طرف سے ایک قربانی کافی ہوتی ہے۔ جبکہ بچے باپ کے ساتھ رہ رہے ہوں۔"}],[1751,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ان تمام ازواج مطہرات کی طرف سے جنہوں نے عمرہ کیا تھا (حجۃ الوداع کے موقعہ پر) ایک گائے ذبح کی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ازواج کی طرف سے، جنہوں نے عمرہ کیا تھا، ایک گائے ذبح کی تھی۔"}],[1752,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ذی الحلیفہ میں ظہر پڑھی پھر آپ نے ہدی کا اونٹ منگایا اور اس کے کوہان کے داہنی جانب اشعار ۱؎ کیا، پھر اس سے خون صاف کیا اور اس کی گردن میں دو جوتیاں پہنا دیں، پھر آپ صلی اللہ علیہ وسلم کی سواری لائی گئی جب آپ اس پر بیٹھ گئے اور وہ مقام بیداء میں آپ کو لے کر سیدھی کھڑی ہوئی تو آپ صلی اللہ علیہ وسلم نے حج کا تلبیہ پڑھا۔\n§وضاحت\n۱؎ : ہدی کے اونٹ کی کوہان پر داہنے جانب چیر کر خون نکالنے اور اسے اس کے آس پاس مل دینے کا نام اشعار ہے، یہ بھی ہدی کے جانوروں کی علامت اور پہچان ہے۔ ۲؎ : اشعار مسنون ہے، اس کا انکار صرف امام ابوحنیفہ نے کیا ہے، وہ کہتے ہیں : ’’ یہ مثلہ ہے جو درست نہیں ‘‘، لیکن صحیح یہ ہے کہ یہ مثلہ نہیں ہے ، مثلہ ناک کان وغیرہ کاٹنے کو کہتے ہیں، اشعار فصد یا حجامت کی طرح ہے، جو صحیح حدیث سے ثابت ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایات ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز ذوالحلیفہ مقام پر پڑھی۔ پھر آپ نے اپنی قربانی کی اونٹنی طلب کی اور اس کے کوہان کی دائیں جانب چیر لگایا اور اس کا خون وہیں چپڑ دیا اور اسی کے گلے میں دو جوتوں کا ہار بھی ڈال دیا۔ پھر آپ کی سواری لائی گئی۔ جب آپ اس پر بیٹھ گئے اور وہ آپ کو لے کر بیداء میدان کے قریب پہنچی تو آپ نے حج کا تلبیہ پکارا۔","f2":"(1)حرم کی طرف بھیجے جانے والے اونٹوں کے کوہانوں کی دائیں طرف معمولی سا چیر لگا کر اس کا خون اس پر چیڑ دنیا [اشعار] کہلاتا ہے۔اور یہ علامت ہوتی ہے کہ یہ جانور اللہ کے لیے ھدی ہے اور حرم کی طرف بھیجا جا رہا ہے۔یہ عمل سنت رسول صلی اللہ علیہ وسلم سے ثابت ہےمگر بکریوں کو [اشعار] نہیں کیا جاتا۔کچھ علماء گایوں میں بھی اشعار کے قائل ہیں۔ اس کے ساتھ قربانی کے جانوروں کے گلوں میں جوتوں کے ہار ڈالنا بھی مسنون عمل ہےاور اسے تقلید کہتے ہیں۔یہ اعمال قدیم زمانے سے چلے آرہے تھے جنہیں نبی صلی اللہ علیہ وسلم نے بحال رکھا۔ (2)بیداء ذوالحلیفہ کا وہ میدان ہے جو جانب جنوب میں تھا جس سے ہوکر مکہ کی راہ پر جاتے تھے۔"}],[1753,"اس سند سے بھی شعبہ سے یہی حدیث ابوالولید کے روایت کے مفہوم کی طرح مروی ہے البتہ اس میں یہ الفاظ ہیں: «ثم سلت الدم بيده» \"آپ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے خون صاف کیا\"۔ ابوداؤد کہتے ہیں: ہمام کی روایت میں «سلت الدم عنها بإصبعه»کے الفاظ ہیں۔ ابوداؤد کہتے ہیں کہ یہ حدیث صرف اہل بصرہ کی سنن میں سے ہے جو اس میں منفرد ہیں۔","صحیح",{"u2":"شعبہ نے یہ حدیث ابو الولید کے ہم معنی روایت کی، کہا کہ انگلی سے خون چپڑا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: یہ روایت اہل بصرہ کے تفردات میں سے ہے۔"}],[1754,"مسور بن مخرمہ رضی اللہ عنہما اور مروان دونوں سے روایت ہے، وہ دونوں کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم حدیبیہ کے سال نکلے جب آپ ذی الحلیفہ پہنچے تو ہدی ۱؎ کو قلادہ پہنایا اور اس کا اشعار کیا اور احرام باندھا۔\n§وضاحت\n۱؎ : ’’ ہدی ‘‘ اس جانور کو کہتے ہیں جو حج تمتع یا حج قران میں مکہ میں ذبح کیا جاتا ہے، نیز اس جانور کو بھی ’’ ہدی ‘‘ کہتے ہیں جس کو غیر حاجی حج کے موقع سے مکہ میں ذبح کرنے کے لئے بھیجتا ہے۔","صحیح",{"u2":"مسور بن مخرمہ اور مروان (بن حکم) بیان کرتے ہیں کہ تو آپ صلی اللہ علیہ وسلم نے قربانی کو قلاوہ پہنایا، اس کا اشعار کیا اور احرام باندھا۔"}],[1755,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بہت سی بکریاں قلادہ پہنا کر ہدی میں بھیجیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بکریاں بطور ہدی (حرم کی طرف) بھجوائیں اور ان کی گردنوں میں قلاوے ڈالے۔","f2":"حرم کو بھیجا جانے والا اصل مسنون ومشروع ہدیہ قربانی ہے۔اب بعض لاعلم اور جاہل لوگ کبوتروں کے لیے دانے بھجواتے ہیں یہ کوئی شرعی عمل نہیں ہے۔"}],[1756,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے ایک بختی اونٹ ہدی کیا پھر انہیں اس کی قیمت تین سو دینار دی گئی تو وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں آئے اور کہنے لگے: اللہ کے رسول! میں نے بختی اونٹ ہدی کیا اس کے بعد مجھے اس کی قیمت تین سو دینار مل رہی ہے، کیا میں اسے بیچ کر اس کی قیمت سے (ہدی کے لیے) ایک اونٹ خرید لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں اسی کو نحر کرو\"۔ ابوداؤد کہتے ہیں: یہ ممانعت (نہی) اس لیے تھی کہ وہ اس کا اشعار کر چکے تھے۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے ک عمر بن خطاب رضی اللہ عنہ نے ایک بختی اونٹ بطور ہدی (حرم کی طرف) بھجوایا۔ انہیں اس کے تین سو دینار پیش کیے گئے تو وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور پوچھا: اے اللہ کے رسول! میں نے ایک عمدہ اونٹ ہدی کیا ہے اور مجھے اس کے تین سو دینار دیے جا رہے ہیں تو کیا میں اسے بیچ کر اس کی قیمت کے دوسرے اونٹ لے لوں؟ آپ نے فرمایا ” نہیں، اسے ہی نحر (ذبح) کرو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: یہ اس لیے تھا کہ وہ اسے اشعار کر چکے تھے۔","f2":"جب قربانی یا ہدی کے لیے جانور خاص کر دیا گیا ہو تو اسے تبدیل کرنا درست نہیں ہے۔"}],[1757,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے اپنے ہاتھ سے رسول اللہ صلی اللہ علیہ وسلم کی ہدی کے لیے قلادے بٹے پھر آپ نے انہیں اشعار کیا اور قلادہ ۱؎ پہنایا پھر انہیں بیت اللہ کی طرف بھیج دیا اور خود مکہ میں مقیم رہے اور کوئی چیز جو آپ صلی اللہ علیہ وسلم کے لیے حلال تھی آپ پر حرام نہیں ہوئی ۲؎۔\n§وضاحت\n۱؎ : قربانی کے جانور کے گلے میں قلادہ یا رسی وغیرہ لٹکانے کا مقصد یہ ہوتا تھا کہ لوگ ان جانوروں کو اللہ کے گھر کے لئے خاص جان کر ان سے چھیڑ چھاڑ نہ کریں۔ ۲؎ : اس حدیث سے معلوم ہوا کہ مقیم کے لئے بھی ہدی بھیجنا درست ہے اور صرف ہدی بھیج دینے سے وہ محرم نہیں ہو گا، اور نہ اس پر کوئی چیز حرام ہو گی جو محرم پر ہوتی ہے، جب تک کہ وہ احرام کی نیت کر کے احرام پہن کر خود حج کو نہ جائے، اور بعض لوگوں کی رائے ہے کہ وہ بھی مثل محرم کے ہو گا اس کے لئے بھی ان تمام چیزوں سے اس وقت تک بچنا ضروری ہو گا جب تک کہ ہدی قربان نہ کردی جائے، لیکن صحیح جمہور کا مذہب ہی ہے، جیسا کہ اس حدیث سے ثابت ہو رہا ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے قربانی کے اونٹ کے ہار کی رسیاں اپنے ہاتھوں سے بٹیں، پھر آپ نے ان کا اشعار کیا اور ان کے گلے میں قلاوہ ڈالا، پھر اسے بیت اللہ کی جانب روانہ کر دیا اور خود مدینہ میں مقیم رہے تو جو چیزیں آپ کے لیے حلال تھیں (اسی طرح حلال ہی رہیں) کچھ بھی حرام نہ ہوا۔","f2":"کوئی شخص حرم کی طرف قربانی بھیجے اور خود نہ جائے تو وہ حلال ہی رہتا ہے۔ احرام کے کوئی احکام اس پر عائد نہیں ہوتے۔"}],[1758,"عروہ اور عمرہ بنت عبدالرحمٰن سے روایت ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ سے ہدی بھیجتے تو میں آپ کی ہدی کے قلادے بٹتی اس کے بعد آپ کسی چیز سے اجتناب نہیں کرتے جس سے محرم اجتناب کرتا ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ سے ھدی بھیجا کرتے تھے۔ میں ان کے قلاووں کی رسیاں بٹا کرتی تھی اور پھر آپ کسی چیز سے اجتناب نہ کرتے جس سے کہ محرم اجتناب کرتا ہے۔"}],[1759,"ام المؤمنین (عائشہ) رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہدی روانہ کئے تو میں نے اپنے ہاتھ سے اس اون سے ان کے قلادے بٹے جو ہمارے پاس تھی پھر آپ صلی اللہ علیہ وسلم نے حلال ہو کر ہم میں صبح کی آپ نے وہ تمام کام کئے جو ایک حلال(غیر مُحرم) آدمی اپنی بیوی سے کرتا ہے۔","صحیح",{"u2":"ام المؤمنین (سیدہ عائشہ رضی اللہ عنہا ا) نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہدی بھجوائی اور میں نے اون سے جو ہمارے ہاں تھی، اس کے قلاووں کی رسیاں بٹیں، پھر آپ ہمارے ہاں اسی طرح حلال ہی رہے۔ اپنے اہل کے پاس آتے جیسے کہ کوئی عام آدمی آتا ہے۔","f2":"در اصل ان احادیث میں اصحاب رائے کے اس قول کا جواب ہے کہ جب انسان ہدی بھیج دےاور اسے قلادہ بھی پہنا دے تواس پر احرام واجب ہوجاتاہے مگر حق یہی ہے جو ذکر ہوا کہ جب تک کوئی شخص عملاً احرام نہ باندھے محرم نہیں ہوتا اور نہ اس طرح احرام ہی واجب ہوتاہے۔"}],[1760,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا کہ وہ ہدی کا اونٹ ہانک کر لے جا رہا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر سوار ہو جاؤ\"، وہ بولا: یہ ہدی کا اونٹ ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر سوار ہو جاؤ، تمہارا برا ہو ۱؎\"، یہ آپ صلی اللہ علیہ وسلم نے دوسری یا تیسری بار میں فرمایا۔\n§وضاحت\n۱؎ : یہ آپ صلی اللہ علیہ وسلم نے بطور زجر و توبیخ کے فرمایا، کیوں کہ سواری کی اجازت آپ صلی اللہ علیہ وسلم پہلے دے چکے تھے، اور آپ کو یہ بھی معلوم تھا کہ یہ ہدی ہے، اس حدیث سے معلوم ہوا کہ ہدی کے جانور پر سواری درست ہے، بعض لوگوں نے کہا کہ بوقت ضرورت و حاجت جائز ہے، اور بعض لوگوں نے کہا کہ جب جی چاہے سوار ہو سکتا ہے، خواہ حاجت ہو یا نہ ہو، اور بعض نے سوار ہونے کو واجب کہا ہے، کیوں کہ اس میں زمانہ جاہلیت کے طریقہ کی مخالفت ہے، وہ لوگ ایسے جانوروں کی ان کے درجہ سے زیادہ قدر و منزلت کرتے تھے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا کہ وہ اپنی قربانی کا اونٹ ہانکے جا رہا تھا (اور خود پیدل چل رہا تھا) تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” اس پر سوار ہو جاؤ۔ “ اس نے کہا: یہ قربانی کے لیے ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس پر سوار ہو جاؤ، تم پر افسوس! “ آپ نے یہ (افسوس کا لفظ) دوسری یا تیسری بار میں فرمایا۔","f2":"تم پر افسوس کلمہ تو بیخ کہنے کی وجہ اس شخص کی کم فہمی تھی کہ نبی صلی اللہ علیہ وسلم دیکھ رہے ہیں اور انہیں معلوم ہے کہ یہ قربانی کا جانور ہے پھر بھی وہ انکار اور اصرار کرتا رہا۔ اسے چاہیے تھا کہ ارشاد نبوی کی بلا چون و چرا تعمیل کرتا۔"}],[1761,"ابوزبیر کہتے ہیں کہ میں نے جابر بن عبداللہ رضی اللہ عنہما سے ہدی پر سوار ہونے کے بارے میں پوچھا: تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے، جب تم اس کے لیے مجبور کر دئیے جاؤ تو اس پر سوار ہو جاؤ بھلائی کے ساتھ یہاں تک کہ تمہیں کوئی دوسری سواری مل جائے ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے امام ابوحنیفہ کے مذہب کی تائید ہوتی ہے، جنہوں نے سوار ہونے کے لئے حاجت و ضرورت کی قید لگائی ہے۔","صحیح",{"u2":"جناب ابو الزبیر کہتے ہیں کہ میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے قربانی کے جانور پر سواری کے متعلق پوچھا تو انہوں نے کیا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ فر رہے تھے ” جب تم مجبور ہو جاؤ تو (احسان کے ساتھ اور) معروف انداز سے اس پر سواری کرو حتیٰ کہ تمہیں کوئی اور سواری مل جائے۔ “","f2":"یعنی بوقت ضرورت انسان ہدی او ر قربانی کے جانور پر سواری کر لے تو کوئی حرج نہیں"}],[1762,"ناجیہ اسلمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ ہدی بھیجا اور فرمایا: \"اگر ان میں سے کوئی مرنے لگے تو اس کو نحر کر لینا پھر اس کی جوتی اسی کے خون میں رنگ کر اسے لوگوں کے واسطے چھوڑ دینا\"۔","صحیح",{"u2":"سیدنا ناجیہ اسلمی رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ہاتھ اپنی قربانی بھجوائی اور انہیں فرمایا ” اگر ان میں سے کوئی جانور ہلاک ہونے لگے تو اسے نحر کر دینا، اس کے جوتے کو اس کے خون سے رنگ دینا، پھر اسے لوگوں کے لیے چھوڑ دینا۔ “"}],[1763,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں اسلمی کو ہدی کے اٹھارہ اونٹ دے کر بھیجا تو انہوں نے کہا: اللہ کے رسول! اگر ان میں سے کوئی (چلنے سے) عاجز ہو جائے تو آپ کا کیا خیال ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اسے نحر کر دینا پھر اس کے جوتے کو اسی کے خون میں رنگ کر اس کی گردن کے ایک جانب چھاپ لگا دینا اور اس میں سے کچھ مت کھانا ۱؎ اور نہ ہی تمہارے ساتھ والوں میں سے کوئی کھائے، یا آپ صلی اللہ علیہ وسلم نے یوں فرمایا: «من أهل رفقتك» \"یعنی تمہارے رفقاء میں سے کوئی نہ کھائے\"۔ ابوداؤد کہتے ہیں: عبدالوارث کی حدیث میں «اضربها» کے بجائے «ثم اجعله على صفحتها» ہے۔ ابوداؤد کہتے ہیں: میں نے ابوسلمہ کو کہتے سنا: جب تم نے سند اور معنی درست کر لیا تو تمہیں کافی ہے۔\n§وضاحت\n۱؎ : تاکہ یہ الزام نہ آئے کہ ہدی کے جانور کو کھانا چاہتا تھا، اس لئے نحر (ذبح) کر ڈالا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فلاں اسلمی کو بھیجا اور اس کے ساتھ اٹھارہ اونٹ قربانی کے بھجوائے۔ وہ کہنے لگا: فرمائیے اگر ان میں سے کوئی اپنے پاؤں گھسیٹنے لگے (چلنے سے لاچار ہو جائے اور تھک جائے تو؟) آپ نے فرمایا ” اسے نحر کر دینا، اس کے جوتوں کو خون سے چپڑ کر اس کی کوہان پر نشان لگا دینا اور تم یا تمہارے ساتھیوں میں سے کوئی اس سے نہ کھائے۔ “ حدیث کے لفظ «من أصحابك» تھے یا «أهل رفقتك» تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث میں یہ جملہ «ولا تأكل منها أنت ولا أحد من أهل رفقتك» منفرد ہے اور عبدالوارث کی روایت میں «ثم اضربها» کی بجائے «اجعله على صفحتها» آیا ہے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ میں نے ابوسلمہ (موسیٰ بن اسمٰعیل المنقری) سے سنا، وہ کہتے تھے کہ جب تم نے حدیث کی سند اور اس کے معنی صحیح اور درست طور پر بیان کر دیے تو کافی ہے (الفاظ بدلنے سے کوئی فرق نہیں پڑتا یعنی روایت بالمعنی جائز ہے)۔","f2":"(1)ہدی کا جانور راستے میں لاچار ہو جائے یا ہلاک ہونے لگے تو اس کو وہیں نحر یا ذبح کر دیا جائے اس کے پائے اور کوہان پر خون سے نشان لگانا اس لیے ہے کہ عام لوگوں کو خبر رہے کہ ہدی کاجانور تھا۔ہدی لے جانے والے خود اس سے کچھ نہ کھائیں۔ (2)بالمعنی روایت کرنے اور اس کے جائز ہونے کی دوشرطیں ہیں ایک تو سند صحیح ہو دوسری یہ کہ وہ حدیث بھی صحیح المعنی ہو۔"}],[1764,"علی رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے اپنی ہدی کے اونٹوں کا نحر کیا تو اپنے ہاتھ سے تیس (۳۰) اونٹ نحر کئے پھر مجھے حکم دیا تو باقی سارے میں نے نحر کئے۔","منکر",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب اپنے اونٹ نحر کیے تو تیس اونٹ اپنے ہاتھ سے نحر کیے اور باقی کے متعلق مجھے حکم فرمایا اور میں نے انہیں نحر کیا۔","f2":"صحیح تر روایت یہ ہے کہ نبی علیہ الصلاۃ والسلام نے تریسٹھ اونٹ اپنے ہاتھ سےنحر کیے تھے اور باقی حضرت علی نے۔(صحیح مسلم الحج حدیث: 1218)"}],[1765,"عبداللہ بن قرط رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"اللہ تبارک و تعالی کے نزدیک سب سے عظیم دن یوم النحر ہے پھر یوم القر ہے ۱؎\"، اس دن رسول اللہ صلی اللہ علیہ وسلم کے سامنے پانچ یا چھ اونٹنیاں لائی گئیں، تو ان میں سے ہر ایک آگے بڑھنے لگی کہ آپ نحر کی ابتداء اس سے کریں جب وہ گر گئیں تو آپ نے آہستہ سے کچھ کہا جو میں نہ سمجھ سکا تو میں نے پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو چاہے اس میں سے گوشت کاٹ لے\"۔\n§وضاحت\n۱؎ : عیسی کہتے ہیں: ثور نے کہا: وہ دوسرا دن ہے، یعنی گیارہویں ذی الحجہ کا دن۔","صحیح",{"u2":"سیدنا عبداللہ بن قرط رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اللہ تبارک و تعالیٰ کے ہاں سب سے بڑھ کر عظمت والا دن یوم النحر (دس ذوالحجہ) اس کے بعد یوم القر (۱۱ ذوالحجہ) ہے۔ “ عیسیٰ نے ثور سے نقل کیا کہ یہ دوسرا دن ہوتا ہے۔ اور بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پانچ یا چھ اونٹنیاں لائی گئیں تو وہ آپ کے قریب ہونے لگیں کہ آپ اسی سے ابتدا کریں۔ جب وہ سب (نحر ہو گئیں اور) پہلووں کے بل گر پڑیں تو آپ نے آہستہ سے کچھ فرمایا جو میں نہ سمجھ سکا۔ میں نے (ساتھ والوں سے) پوچھا کہ آپ نے کیا فرمایا ہے؟ تو بتایا کہ ” جو چاہے (گوشت) کاٹ لے جائے۔“","f2":"(1)جانوروں کو بھی نبی صلی اللہ علیہ وسلم کی جلالت شان کا علم تھا اور وہ آپ کے ہاتھ سے نحر ہونے کو باعث شرف جانتے تھے۔(2) غیر معین کو ہدیہ کرنا بھی جائزہے۔(3) صحیح احادیث میں جمعہ کو[خیر یوم] یعنی بہترین دن قراردیاگیا ہے۔(صحیح مسلم الجمعة حدیث:854)اور اس حدیث میں یوم النحر کو اعظم الایام کہاگیا ہے۔ ان احادیث میں جمع وتطبیق یوں ہے کہ ہفتے کےایام میں جمعہ کا دن اور سال کےد نوں میں دسویں ذوالحجہ کا دن افضل ہے۔ اگر یوم النحر یوم الجمعہ کوہو تو دوفضلتیں جمع ہوگئیں اگر الگ الگ ہوں تو افضیلت یوم النحر کو ہوگی۔جیسے کہ اس حدیث میں آیا ہے۔(عون المعبود)"}],[1766,"عرفہ بن حارث کندی رضی اللہ عنہ کہتے ہیں میں حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم کے پاس تھا، ہدی کے اونٹ لائے گئے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابوالحسن (علی رضی اللہ عنہ کی کنیت ہے) کو بلاؤ\"، چنانچہ آپ کے پاس علی رضی اللہ عنہ کو بلا کر لایا گیا تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم برچھی کا نچلا سرا پکڑو\"، اور رسول اللہ صلی اللہ علیہ وسلم نے اوپر کا سرا پکڑا پھر اونٹوں کو نحر کیا جب فارغ ہو گئے تو اپنے خچر پر سوار ہوئے اور علی کو اپنے پیچھے سوار کر لیا۔","ضعیف",{"u2":"سیدنا عرفہ بن حارث کندی رضی اللہ عنہ کہتے ہیں کہ میں حجتہ الوداع میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر تھا کہ قربانی کی اونٹنیاں لائی گئیں۔ آپ نے فرمایا ” ابوالحسن (علی) کو بلاؤ۔ “ چنانچہ انہیں آپ کے لیے بلایا گیا، تو آپ نے ان سے فرمایا ” برچھے کو نیچے سے پکڑو۔ “ اور خود آپ نے اس کے اوپر سے پکڑا، پھر آپ دونوں نے اسے (اونٹنیوں کے نحر کرنے میں) چلایا۔ جب آپ فارغ ہو گئے تو اپنے خچر پر سوار ہوئے اور سیدنا علی رضی اللہ عنہ کو بھی اپنے ساتھ بٹھا لیا۔"}],[1767,"جابر رضی اللہ عنہ سے روایت ہے (ابن جریج کہتے ہیں: نیز مجھے عبدالرحمٰن بن سابط نے (مرسلاً) خبر دی ہے) کہ نبی اکرم صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام اونٹ کا بایاں پاؤں باندھ کر اور باقی پیروں پر کھڑا کر کے اسے نحر کرتے ۱؎۔\n§وضاحت\n۱؎ : اونٹ کو سینہ پر مار کر ذبح کرتے ہیں اس لیے نحر کا لفظ استعمال ہوا۔","صحیح",{"u2":"جناب ابوخالد احمر، ابن جریج سے، وہ ابو الزبیر سے اور وہ سیدنا جابر رضی اللہ عنہ سے روایت کرتے ہیں اور (ابن جریج نے کہا) مجھے عبدالرحمٰن بن سابط نے خبر دی کہ ” نبی کریم صلی اللہ علیہ وسلم اور آپ کے صحابہ اونٹ کو ” نحر “ کیا کرتے تھے جبکہ اس کا بایاں پاؤں بندھا ہوتا اور وہ باقی تین پاؤں پر کھڑا ہوتا۔ “","f2":"(1)جانور کو ذبح کرنے کےلیے اگر اس کے حلق پر چھری چلائی جائے تواسے اصطلاحا ً ذبح کرنا کہتے ہیں اور اگر لبہ (حلق کے نیچے ہنسلی کے قریب نرم جگہ)پر چلائی جائےتو اسے نحر کرنا کہتے ہیں۔اونٹ کو نحر کرنا افضل ہے اور بکر ی کو ذبح کرنا۔گائے کے لیے دونوں لفظ استعمال ہوئے ہیں مگر اس کےمعنی بالعموم ذبح کرنا ہی کیے جاتے ہیں جیسے کہ پیچھے احادیث 1750 اور 1751 میں گزرا ہے۔ (2)اس میں اونٹ کےنحر کرنے کا طریقہ بیان ہوا ہے۔اونٹ کو اس کے مطابق ہی نحر کرنے کی کوشش کرنی چاہیے۔"}],[1768,"یونس کہتے ہیں مجھے زیاد بن جبیر نے خبر دی ہے، وہ کہتے ہیں میں منی میں ابن عمر رضی اللہ عنہما کے ساتھ تھا کہ ان کا گزر ایک شخص کے پاس سے ہوا جو اپنا اونٹ بٹھا کر نحر کر رہا تھا انہوں نے کہا: کھڑا کر کے (بایاں پیر) باندھ کر نحر کرو، یہی محمد صلی اللہ علیہ وسلم کا طریقہ تھا۔","صحیح",{"u2":"جناب زیاد بن جبیر کہتے ہیں کہ میں منٰی میں سیدنا عبداللہ بن عمر رضی اللہ عنہ کے ساتھ تھا کہ وہ ایک آدمی کے پاس سے گزرے اور وہ اپنی اونٹنی کو نحر کرنا چاہ رہا تھا جبکہ وہ بیٹھی ہوئی تھی۔ تو سیدنا ابن عمر رضی اللہ عنہ نے فرمایا ” اسے کھڑی کرو، (ایک) پاؤں بندھا ہوا ہو، یہی محمد صلی اللہ علیہ وسلم کی سنت ہے۔ “","f2":"فرامین رسول صلی اللہ علیہ وسلم اورآپ کےافعال کی اتباع کامل ہی کا نام دین ہے۔ صحابہ کرام کی سیرتیں یہی بتاتی ہیں۔وہ ہمیشہ اس کے داعی رہے اور قیامت تک کے لیے یہی اٹل اصول ہے۔ صریح نصوص کےہوتے ہوئے رائے خیال رجحان اور فتویٰ کا کیا مقام!؟"}],[1769,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ میں آپ کے ہدی کے اونٹوں کے پاس کھڑا ہو کر ان کی کھالیں اور جھولیں تقسیم کروں اور مجھے حکم دیا کہ اس میں سے قصاب کو کچھ بھی نہ دوں اور فرمایا: اسے ہم اپنے پاس سے (اجرت) دیں گے۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا کہ میں آپ کے اونٹوں کے پاس کھڑا ہو جاؤں (جبکہ وہ نحر کیے جا رہے تھے) اور ان کے چمڑے اور جھول تقسیم کر دوں۔ قصاب کو ان میں سے کوئی شے نہ دوں۔ انہوں نے بتایا کہ قصاب کی مزدوری ہم اپنے پاس سے دیا کرتے تھے۔"}],[1770,"سعید بن جبیر رضی اللہ عنہ کہتے ہیں کہ میں نے عبداللہ بن عباس رضی اللہ عنہما سے کہا: ابوالعباس! مجھے تعجب ہے کہ کے صحابہ کرام رضی اللہ عنہم رسول اللہ صلی اللہ علیہ وسلم کے احرام باندھنے کے سلسلے میں اختلاف رکھتے ہیں کہ آپ نے احرام کب باندھا؟ تو انہوں نے کہا: اس بات کو لوگوں میں سب سے زیادہ میں جانتا ہوں، چونکہ رسول اللہ صلی اللہ علیہ وسلم نے ایک ہی حج کیا تھا اسی وجہ سے لوگوں نے اختلاف کیا ہے، رسول اللہ صلی اللہ علیہ وسلم حج کی نیت کر کے مدینہ سے نکلے، جب ذی الحلیفہ کی اپنی مسجد میں آپ نے اپنی دو رکعتیں ادا کیں تو اسی مجلس میں آپ صلی اللہ علیہ وسلم نے احرام باندھا اور دو رکعتوں سے فارغ ہونے کے بعد حج کا تلبیہ پڑھا، لوگوں نے اس کو سنا اور میں نے اس کو یاد رکھا، پھر آپ صلی اللہ علیہ وسلم سوار ہوئے جب آپ کی اونٹنی آپ کو لے کر سیدھی کھڑی ہو گئی تو آپ نے تلبیہ پڑھا، بعض لوگوں نے اس وقت آپ صلی اللہ علیہ وسلم کو تلبیہ پڑھتے ہوئے پایا، اور یہ اس وجہ سے کہ لوگ الگ الگ ٹکڑیوں میں آپ کے پاس آتے تھے، تو جب آپ صلی اللہ علیہ وسلم کی اونٹنی آپ کو لے کر اٹھی تو انہوں نے آپ کو تلبیہ پکارتے ہوئے سنا تو کہا: آپ نے تلبیہ اس وقت کہا ہے جب آپ کی اونٹنی آپ کو لے کر کھڑی ہوئی پھر رسول اللہ صلی اللہ علیہ وسلم چلے، جب مقام بیداء کی اونچائی پر چڑھے تو تلبیہ کہا تو بعض لوگوں نے اس وقت اسے سنا تو انہوں نے کہا کہ آپ صلی اللہ علیہ وسلم نے اسی وقت تلبیہ کہا ہے جب آپ بیداء کی اونچائی پر چڑھے حالانکہ اللہ کی قسم آپ نے وہیں تلبیہ کہا تھا جہاں آپ نے نماز پڑھی تھی، پھر آپ صلی اللہ علیہ وسلم نے اس وقت تلبیہ کہا جب اونٹنی آپ کو لے کر سیدھی ہوئی اور پھر آپ نے بیداء کی اونچائی چڑھتے وقت تلبیہ کہا۔ سعید کہتے ہیں: جس نے ابن عباس رضی اللہ عنہما کی بات کو لیا تو اس نے اس جگہ پر جہاں اس نے نماز پڑھی اپنی دونوں رکعتوں سے فارغ ہونے کے بعد تلبیہ کہا۔","ضعیف الإسناد",{"u2":"سیدنا سعید بن جبیر رضی اللہ عنہ کہتے ہیں کہ میں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے کہا: اے ابو العباس! مجھے تعجب ہے کہ اصحاب رسول، رسول اللہ صلی اللہ علیہ وسلم کے احرام کے بارے میں اختلاف کرتے ہیں کہ آپ نے کس وقت احرام باندھا تھا۔ انہوں نے کہا: میں اس بارے میں سب سے زیادہ باخبر ہوں۔ دراصل آپ نے چونکہ ایک ہی حج کیا ہے تو اس وجہ سے اختلاف ہوا ہے۔ آپ حج کی نیت سے روانہ ہوئے۔ جب آپ نے اپنی مسجد میں یعنی ذوالحلیفہ میں دو رکعتیں پڑھ لیں تو آپ نے اپنی اسی مجلس میں نیت فر لی اور ان دو رکعتوں سے فارغ ہونے کے بعد حج کا تلبیہ کہا۔ پس کچھ لوگوں نے اس وقت سن لیا اور اسے یاد رکھا۔ پھر آپ صلی اللہ علیہ وسلم اپنی سواری پر سوار ہو گئے۔ جب آپ کی اونٹنی آپ کو لے کر کھڑی ہوئی تو آپ نے تلبیہ کہا، کچھ لوگوں نے اس کو پایا۔ درحقیقت لوگ گروہ در گروہ آپ کے پاس آ رہے تھے تو جنہوں نے آپ کو اونٹنی پر بیٹھے ہوئے تلبیہ پکارتے سنا، انہوں نے یہی سمجھا کہ آپ نے اونٹنی پر بیٹھنے کے بعد، جب وہ کھڑی ہوئی ہے، تلبیہ کہا ہے۔ پھر رسول اللہ صلی اللہ علیہ وسلم چل دیے اور جب میدان بیداء کی بلندی پر پہنچے تو آپ نے تلبیہ کہا۔ کچھ لوگوں نے اس کو پایا تو انہوں نے کہا کہ آپ نے بیداء کی بلندی پر پہنچ کر تلبیہ کہا۔ (سعید نے کہا) قسم اللہ کی! آپ نے اپنی جائے نماز ہی پر تلبیہ کہا تھا۔ پھر جب آپ کی اونٹنی آپ کو لے کر کھڑی ہوئی تو تلبیہ کہا۔ اور جب میدان بیداء کی بلندی پر پہنچی تو آپ نے تلبیہ کہا۔ سعید بن جبیر نے کہا کہ جو لوگ سیدنا ابن عباس رضی اللہ عنہ کے بیان پر عمل پیرا ہیں وہ اپنی دو رکعتوں کے بعد جائے نماز ہی سے تلبیہ شروع کر دیتے ہیں۔","f2":"[اھل] کے معنی ہیں (اپنی آواز بلند کی) [لبیک اللهم لبیک] بآواز بلند پکارا_اوراحرام کےمعنی میں بھی استعمال ہوتا ہے۔خیال رہے یہ حدیث ضعیف ہے۔ شیخ البانی رحمہ اللہ نے بھی اسے الضعیفہ میں درج کیاہے۔ لیکن علامہ احمد شاکرنےاس حدیث کوصحیح قراردیا ہے_(2)اس روایت مین ذوالحلیفہ میں جو دورکعتیں پڑھنے کا ذکر ہے جس کے بعد آپ نے حج کے لیے تلبیہ پکارا اس سے مراد نماز ظہر کی دو رکعت (نماز قصر) ہے جیسا کہ صحیح مسلم (حدیث:1243،)اور سنن نسائی (حدیث:2756)میں صراحت ہے۔اس لیے اس کے آخر میں حضرت سعید بن جبیر کے قول سے احرام کے وقت دو رکعت پڑھنے کا اثبات مترشح ہو رہا ہے وہ صحیح نہیں۔ کیونکہ نبی صلی اللہ علیہ وسلم سے اس کا کوئی واضح ثبوت نہیں۔"}],[1771,"عبداللہ بن عمر رضی اللہ عنہا کہتے ہیں کہ یہی وہ بیداء کا مقام ہے جس کے بارے میں تم لوگ رسول اللہ صلی اللہ علیہ وسلم سے غلط بیان کرتے ہو کہ آپ نے تو مسجد یعنی ذی الحلیفہ کی مسجد کے پاس ہی سے تلبیہ کہا تھا۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا کہ تم لوگ اس میدان بیداء کے بارے میں رسول اللہ صلی اللہ علیہ وسلم کے متعلق غلط کہتے ہو۔ آپ صلی اللہ علیہ وسلم نے تو مسجد ہی کے پاس تلبیہ پکارنا شروع کر دیا تھا یعنی ذوالحلیفہ کی مسجد کے پاس سے۔","f2":"(1)حضرت عبداللہ بن عمر کامقصد اس بات کی نفی کرنا ہے جوبعض نے بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے تلبیہ بیداء کےمقام پر پکارا تھا بلکہ آپ نے اس کا آغاز مسجد ذوالحلیفہ ہی سے کر دیا تھا۔(2) رسول اللہ صلی اللہ علیہ وسلم کے دور میں ذوالحلیفہ کےمقام پر کوئی باقاعدہ مسجد نہ تھی۔ احادیث میں لغوی معنی مراد ہیں۔یعنی جس جگہ آپ نے نماز پڑھی یہاں اس وقت ایک درخت بھی تھا۔ باقاعدہ تعمیر بعد کےکسی دور میں ہوئی ہے۔"}],[1772,"عبید بن جریج سے روایت ہے کہ انہوں نے عبداللہ بن عمر رضی اللہ عنہما سے کہا: ابوعبدالرحمٰن! میں نے آپ کو چار کام ایسے کرتے دیکھا ہے جنہیں میں نے آپ کے اصحاب میں سے کسی کو کرتے نہیں دیکھا ہے؟ انہوں نے پوچھا: وہ کیا ہیں ابن جریج؟ وہ بولے: میں نے دیکھا کہ آپ صرف رکن یمانی اور حجر اسود کو چھوتے ہیں، اور دیکھا کہ آپ ایسی جوتیاں پہنتے ہیں جن کے چمڑے میں بال نہیں ہوتے، اور دیکھا آپ زرد خضاب لگاتے ہیں، اور دیکھا کہ جب آپ مکہ میں تھے تو لوگوں نے چاند دیکھتے ہی احرام باندھ لیا لیکن آپ نے یوم الترویہ (آٹھویں ذی الحجہ) کے آنے تک احرام نہیں باندھا، تو عبداللہ بن عمر رضی اللہ عنہما نے کہا: رہی رکن یمانی اور حجر اسود کی بات تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو صرف انہیں دو کو چھوتے دیکھا ہے، اور رہی بغیر بال کی جوتیوں کی بات تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسی جوتیاں پہنتے دیکھی ہیں جن میں بال نہیں تھے اور آپ ان میں وضو کرتے تھے، لہٰذا میں بھی انہی کو پہننا پسند کرتا ہوں، اور رہی زرد خضاب کی بات تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو زرد رنگ کا خضاب لگاتے دیکھا ہے، لہٰذا میں بھی اسی کو پسند کرتا ہوں، اور احرام کے بارے میں یہ ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس وقت تک لبیک پکارتے نہیں دیکھا جب تک کہ آپ کی سواری آپ کو لے کر چلنے کے لیے کھڑی نہ ہو جاتی۔","صحیح",{"u2":"سیدنا عبید بن جریج کہتے ہیں کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے کہا: اے ابو عبدالرحمٰن! میں آپ کو چار کام کرتے دیکھتا ہوں، آپ کا کوئی ساتھی یہ نہیں کرتا۔ انہوں نے کہا: اے ابن جریج! وہ کیا ہیں؟ انہوں نے کہا: میں نے آپ کو دیکھا ہے کہ آپ (دوران طواف میں) بیت اللہ کے صرف دو کونوں «يمانيين» (حجر اسود اور رکن یمانی) کو ہاتھ لگاتے ہیں اور آپ کو دیکھا ہے کہ آپ ایسے چمڑے کی جوتی پہنتے ہیں جس پر بال نہیں ہوتے۔ اور آپ کو دیکھا ہے کہ زرد رنگ استعمال کرتے ہیں۔ (کپڑوں میں یا بالوں میں بطور خضاب کے) اور میں نے آپ کو دیکھا ہے کہ جب آپ مکہ میں ہوں تو لوگ چاند دیکھتے ہی احرام باندھ لیتے ہیں مگر آپ آٹھویں ذوالحجہ کو احرام باندھتے ہیں۔ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے جواب دیا: جہاں تک (دوران طواف میں) ارکان کو چھونے کا تعلق ہے تو میں نے رسول اللہ صلی اللہ علیہ وسلم کہ دیکھا ہے کہ آپ صرف دونوں یمانی ارکان ہی کو چھوتے تھے۔ (حجر اسود اور رکن یمانی کو۔) اور بے بال چمڑے کے جوتے، تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ کا جوتا ایسے چمڑے کا ہوتا تھا جس پر بال نہ ہوتے تھے اور آپ اس میں وضو (بھی) کر لیا کرتے تھے تو میں ایسے ہی جوتے پہننا پسند کرتا ہوں۔ اور رہا زرد رنگ، تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ اس سے رنگتے تھے، لہٰذا میں بھی اس سے رنگنا پسند کرتا ہوں۔ رہا احرام اور تلبیہ، تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا کہ آپ اپنی سواری کے کھڑی ہونے سے پہلے تلبیہ پکارتے ہوں۔","f2":"حضرت عبد اللہ بن عمر نے اپنے ہر ہر عمل کو سنت رسول صلی اللہ علیہ وسلم کے تابع رکھا ہوا تھا۔اور یہی دین و شریعت ہے۔ اور آٹھویں ذوالحجہ کو احرام باندھنے کا عمل اور ان کا جواب اس قیاس واجتہاد پر مبنی ہے کہ نبی صلی اللہ علیہ وسلم میقات میں سفر حج شروع کرنے سے پہلے احرام یا تلبیہ پکارے تھے بلکہ بالکل آخری وقت میں کہتے جب اس سے چارہ نہ ہوتا۔"}],[1773,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں ظہر چار رکعت اور ذی الحلیفہ میں عصر دو رکعت ادا کی، پھر ذی الحلیفہ میں رات گزاری یہاں تک کہ صبح ہو گئی، جب آپ صلی اللہ علیہ وسلم اپنی سواری پر بیٹھے اور وہ آپ کو لے کر سیدھی ہو گئی تو آپ نے تلبیہ پڑھا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینے میں ظہر کی نماز چار رکعت ادا فرمائی اور ذوالحلیفہ میں عصر کی دو رکعتیں پڑھیں اور یہیں رات گزاری حتیٰ کہ صبح ہو گئی۔ پھر جب آپ اپنی سواری پر سوار ہوئے اور وہ آپ کو لے کر سیدھی کھڑی ہو گئی تو آپ نے تلبیہ پکارا۔","f2":"قصر نماز سفر شروع ہونے کے بعد ہی پڑھی جاتی ہے اور ذوالحلیفہ آپ کے سفرکی پہلی منزل تھی اور یہی اہل مدینہ کی میقات احرام ہے اور نبی صلی اللہ علیہ وسلم نے یہیں دوسرے دن ظہر کی نماز کے بعد احرام باندھا اور تلبیہ پکارنا شروع کیا۔ اس حدیث سے واضح ہے کہ نبی صلی اللہ علیہ وسلم نے احرام کی دورکعتیں نہیں پڑھیں۔اگلی روایت میں اس کی مزید وضاحت ہے۔"}],[1774,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ظہر پڑھی، پھر اپنی سواری پر بیٹھے جب بیداء کے پہاڑ پر چڑھے تو تلبیہ پڑھا۔","صحیح لغیرہ",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھی، پھر اپنی سواری پر سوار ہوئے اور جب میدان بیداء کے ریتلے ٹیلے کی بلندی پر پہنچے تو آپ نے تلبیہ پکارا۔"}],[1775,"عائشہ بنت سعد بن ابی وقاص کہتی ہیں کہ سعد بن ابی وقاص رضی اللہ عنہ کا کہنا ہے کہ اللہ کے نبی اکرم صلی اللہ علیہ وسلم جب فرع کا راستہ (جو مکہ کو جاتا ہے) اختیار کرتے تو جب آپ صلی اللہ علیہ وسلم کی سواری آپ کو لے کر سیدھی ہو جاتی تو آپ تلبیہ پڑھتے اور جب آپ احد کا راستہ اختیار کرتے تو بیداء کی پہاڑی پر چڑھتے وقت تلبیہ پڑھتے۔","ضعیف",{"u2":"جناب سعد بن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب «فرع» کی راہ اختیار کرتے تو اس وقت تلبیہ پکارنا شروع کرتے جب آپ کی سواری آپ کو لے کر سیدھی کھڑی ہو جاتی۔ اور جب احد کی راہ سے چلنے لگتے تو اس وقت تلبیہ کہتے جب بیداء کے ٹیلے پر چڑھتے۔"}],[1776,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ضباعہ بنت زبیر بن عبدالمطلب رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: اللہ کے رسول! میں حج میں شرط لگانا چاہتی ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، (لگا سکتی ہو)\"، انہوں نے کہا: تو میں کیسے کہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: کہو! «لبيك اللهم لبيك، ومحلي من الأرض حيث حبستني» \"حاضر ہوں اے اللہ حاضر ہوں، اور میرے احرام کھولنے کی جگہ وہی ہے جہاں تو مجھے روک دے\"۔","حسن صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ (ام حکیم) ضباعہ بنت الزبیر عبدالمطلب رضی اللہ عنہا ا رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور کہا: اے ا اللہ کے رسول! میں حج کا ارادہ رکھتی ہوں تو (کیا) شرط کر لوں؟ فرمایا ” ہاں! “ کہنے لگیں: تو کیسے کہوں؟ فرمایا ” کہو: «لبيك اللهم لبيك، ومحلي من الأرض حيث حبستني» میں راستے میں وہیں حلال ہو جاؤں گی جہاں تو مجھے روک لے گا۔ “","f2":"(1)سیدہ ضباعہ رسول اللہ صلی اللہ علیہ وسلم کی چچازاد بہن ہیں اور ان کی کنیت ام حکیم ہے۔ (2) اگر انسان کوکوئی ایسامرض لاحق ہو جوسفر اور اعمال حج کے لیے رکاوٹ بن سکتا ہو تو مندرجہ ذیل بالا اندازہ میں شرط کرکے احرام باندھ سکتا ہے اور جہاں رکاوٹ ہو جائے حلال ہو سکتاہے اور دوبارہ اس حج یاعمرے کی قضا لازم نہ ہوگی۔ تاہم صاحب استطاعت کے لیے قضا ضروری ہوگی۔واللہ اعلم۔(3) سیدہ ضباعہ بنت زبیر نے یہ شرط لگائی تھی مگر رکاوٹ پیش نہ آئی تھی اور انہون نے حج پورا کر لیا تھا۔"}],[1777,"ام المؤمنین عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کیا ۱؎۔\n§وضاحت\n۱؎ : حج کے مہینے میں میقات سے صرف حج کی نیت سے احرام باندھنے کو افراد کہتے ہیں، نبی کریم صلی اللہ علیہ وسلم کے بارے میں صحیح یہ ہے کہ آپ نے حج قِران کیا تھا، اس لئے کہ آپ صلی اللہ علیہ وسلم کے ساتھ ہدی کے جانور تھے، ورنہ صحابہ کرام رضی اللہ عنہم کو حکم دیا تھا کہ جن کے ساتھ ہدی کا جانور نہ ہو وہ عمرہ پورا کر کے احرام کھول دیں، یعنی حج قران کو حج تمتع میں بدل دیں، دیکھئے حدیث نمبر: (۷۹۵)۔","صحیح الإسناد",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا روایت کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کیا تھا۔","f2":"(1)حج کے لیے احرم اورنیت کے تین انداز مشروع ہیں:ایک یہ کہ انسان احرام باندھتے ہوئے صرف اور صرف حج کی نیت کرے۔ اس بصورت میں انسان اعمال حج مکمل ہونے تک احرام ہی میں رہتا ہے۔اسے حج افراد (ہمزہ کے کسرہ کے ساتھ) کہتے ہیں یعنی مفرد حج۔دوسری صورت یہ ہے کہ حج اور عمرہ کی اکٹھی نیت ہو۔ اس صورت میں حاجی پہلے عمر ہ کرتاہے اس کے بعد احرام کی حالت میں رہتا ہے یہاں تک کہ حج کے اعمال پورے کر لے۔ اس کو حج قران (قاف کی کسرہ کے ساتھ) کہتے ہیں یعنی حج اور عمرے کو ملا کر ادا کیا۔ تیسری صورت یہ ہے کہ حاجی پہلے عمرہ کی نیت سے احرام باندھے۔مکہ پہنچ کر عمرہ کےاعمال مکمل کرکے حلال ہوجائے اور پھر 8ذوالحجہ کو دوبارہ حج کے لیے احرام باندھے اور حج کے اعمال پورے کرے۔ اس نوعیت کو حج تمتع کہتے ہیں یعنی ایک ہی سفر میں حج کے ساتھ عمرے کا فائدہ بھی حاصل کر لیا۔سب سے افضل حج تمتع ہی ہے۔اگر قربانی ساتھ لے کر جائے تو قران ہو گا۔ او رحج افراد بھی ہر طرح سے جائز ہے۔(قربانی سمیت یا قربانی کے بغیر)رسول اللہ صلی اللہ علیہ وسلم کا حج قران تھا جبکہ صحابہ میں افراج والے بھی تھے اور تمتع والے بھی۔(2)اس معنی کی احادیث میں نبی صلی اللہ علیہ وسلم کے ابتدائے عمل کا بیان ہے۔ قران کی نیت آپ نے بعد میں فرمائی تھی۔کچھ محدثین اس طرح کہتے ہیں کہ آپ شروع ہی سے قارن تھے۔مگر چونکہ [قارن] کو اجازت ہوتی ہے کہ کسی وقت [لبیک بحجة] کسی وقت [لبیک تعمرۃ] اور کسی وقت [لبیک بحجة و عمرة] کہے اس لیے صحابہ کرام نے نبی صلی اللہ علیہ وسلم کی زبان سے جو سنا بیان کیا۔ اس میں تعارض والی کوئی بات نہیں۔(مرعاۃ المفاتیح –شرح حدیث:2569)"}],[1778,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب ذی الحجہ کا چاند نکلنے کو ہوا تو ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، جب آپ ذی الحلیفہ پہنچے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو حج کا احرام باندھنا چاہے وہ حج کا احرام باندھے، اور جو عمرہ کا احرام باندھنا چاہے وہ عمرہ کا باندھے\"۔ موسی نے وہیب والی روایت میں کہا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر میں ہدی نہ لے چلتا تو میں بھی عمرہ کا احرام باندھتا\"۔ اور حماد بن سلمہ کی حدیث میں ہے: \"رہا میں تو میں حج کا احرام باندھتا ہوں کیونکہ میرے ساتھ ہدی ہے\"۔ آگے دونوں راوی متفق ہیں (ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں) میں عمرے کا احرام باندھنے والوں میں تھی، آپ ابھی راستہ ہی میں تھے کہ مجھے حیض آ گیا، آپ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، میں رو رہی تھی، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیوں رو رہی ہو؟\"، میں نے عرض کیا: میری خواہش یہ ہو رہی ہے کہ میں اس سال نہ نکلتی (تو بہتر ہوتا)، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنا عمرہ چھوڑ دو، سر کھول لو اور کنگھی کر لو\"۔ موسی کی روایت میں ہے: \"اور حج کا احرام باندھ لو\"، اور سلیمان کی روایت میں ہے: \"اور وہ تمام کام کرو جو مسلمان اپنے حج میں کرتے ہیں\"۔ تو جب طواف زیارت کی رات ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن کو حکم دیا چنانچہ وہ انہیں مقام تنعیم لے کر گئے۔ موسی نے یہ اضافہ کیا ہے کہ انہوں نے اپنے اس عمرے کے عوض (جو ان سے چھوٹ گیا تھا) دوسرے عمرے کا احرام باندھا اور بیت اللہ کا طواف کیا، اس طرح اللہ نے ان کے عمرے اور حج دونوں کو پورا کر دیا۔ ہشام کہتے ہیں: اور اس میں ان پر اس سے کوئی ہدی لازم نہیں ہوئی۔ ابوداؤد کہتے ہیں: موسی نے حماد بن سلمہ کی حدیث میں یہ اضافہ کیا ہے کہ جب بطحاء ۱؎ کی رات آئی تو عائشہ رضی اللہ عنہا حیض سے پاک ہو گئیں۔\n§وضاحت\n۱؎ : بطحاء سے مراد منی ہے، یعنی قیام منی کے ایام کی کسی رات میں وہ پاک ہو گئیں، علامہ عینی کہتے ہیں کہ عائشہ رضی اللہ عنہا حیض تین ذی الحجہ بروز سنیچر مقام سرف میں شروع ہوا تھا، اور دسویں ذی الحجہ کو سنیچر کے روز پاک ہوئیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ذوالحجہ کا چاند آنے پر ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے۔ جب ذوالحلیفہ مقام پر آئے تو آپ نے فرمایا ” جو حج کا احرام باندھنا چاہتا ہے باندھا لے اور جو چاہے عمرے کی نیت کر لے۔ “ موسیٰ بن اسمٰعیل نے وہیب کی روایت میں بیان کیا کہ (آپ نے فرمایا) ” میں نے اگر قربانی ساتھ نہ لی ہوتی تو عمرے کا احرام باندھتا۔ “ اور حماد بن سلمہ کی روایت میں کہا: ” اور میں حج کا احرام باندھ رہا ہوں کیونکہ میرے ساتھ قربانی ہے۔ “ آگے روایت بیان کرنے میں سب راوی متفق ہیں۔ (عائشہ رضی اللہ عنہا ا کہتی ہیں کہ) میں ان افراد میں سے تھی جنہوں نے عمرے کا احرام باندھا، پھر راستے میں ایک جگہ مجھے حیض شروع ہو گیا۔ رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے اور میں رو رہی تھی۔ آپ نے پوچھا: کیوں رو رہی ہو؟ میں نے کہا: میں چاہتی ہوں کہ اس سال نہ آئی ہوتی (تو اچھا تھا۔) آپ نے فرمایا ” اپنا عمرہ چھوڑ دو، اپنے بال کھول لو اور کنگھی کر لو۔ “ موسیٰ نے کہا: ” اور حج کی نیت کر لو “ اور سلیمان نے کہا: ” اور اسی طرح کرو جیسے کہ مسلمان اپنے حج میں کرتے ہیں۔ “ الغرض جب (حج سے) واپسی کی رات آئی، تو رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن (ابن ابی بکر رضی اللہ عنہ یعنی عائشہ رضی اللہ عنہا ا کے بھائی) کو حکم دیا، تو وہ انہیں تنعیم لے گئے۔ موسیٰ نے مزید کہا: پس انہوں نے عمرے کا احرام باندھا۔ یعنی اپنے پہلے عمرے کے بدلے، پھر بیت اللہ کا طواف کیا۔ الغرض ا اللہ نے ان کا عمرہ اور حج پورا کرا دیا۔ ہشام کہتے ہیں اس صورت میں کوئی ہدی (فدیہ وغیرہ) نہ ہوا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ موسیٰ نے حماد بن سلمہ کی روایت میں مزید کہا: پھر جب بطحاء کی رات آئی (یعنی منٰی میں اقامت کی رات) تو سیدہ عائشہ رضی اللہ عنہا ا پاک ہو گئی تھیں۔","f2":"(1)سیدہ عائشہ رضی اللہ عنہا کو حیض کی کیفیت مکہ کے قریب وادی سرف میں لاحق ہوئی۔ (2)ایسی صورت میں عورت کو عمرے کی نیت کو حج میں بدل لینا چاہیے۔"}],[1779,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم لوگ حجۃ الوداع کے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے ہم میں کچھ ایسے لوگ تھے جنہوں نے عمرے کا احرام باندھا، اور کچھ ایسے تھے جنہوں نے حج و عمرہ دونوں کا احرام باندھا، اور کچھ ایسے تھے جنہوں نے صرف حج کا احرام باندھا، رسول اللہ صلی اللہ علیہ وسلم نے حج کا احرام باندھا، چنانچہ جن لوگوں نے حج کا یا حج اور عمرہ دونوں کا احرام باندھا تھا انہوں نے یوم النحر (یعنی دسویں ذی الحجہ) تک احرام نہیں کھولا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم حجتہ الوداع کے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے۔ ہم میں سے بعض نے عمرے کا احرام باندھا، بعض نے حج اور عمرے کا اور بعض نے صرف حج کا جب کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کا احرام باندھا تھا۔ تو جنہوں نے حج یا حج اور عمرے کا احرام باندھا تھا وہ قربانی کے دن (یوم الخر ‘ 10 ذوالحجہ) تک حلال نہ ہوئے۔"}],[1780,"اس سند سے بھی ابوالاسود سے اسی طریق سے اسی کے مثل مروی ہے البتہ اس میں اتنا اضافہ ہے: \"رہے وہ لوگ جنہوں نے صرف عمرے کا احرام باندھا تھا تو ان لوگوں نے (عمرہ کر کے) احرام کھول دیا\"۔","صحیح",{"u2":"مالک نے ابوالاسود سے اپنی سند سے اسی کے مثل بیان کیا اور یہ مزید کہا: اور جنہوں نے عمرے کا احرام باندھا تھا وہ حلال ہو گئے۔"}],[1781,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ حجۃ الوداع میں ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے تو ہم نے عمرے کا احرام باندھا پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے ساتھ ہدی ہو تو وہ عمرے کے ساتھ حج کا احرام باندھ لے پھر وہ حلال نہیں ہو گا جب تک کہ ان دونوں سے ایک ساتھ حلال نہ ہو جائے\"، چنانچہ میں مکہ آئی، میں حائضہ تھی، میں نے بیت اللہ کا طواف نہیں کیا اور نہ صفا و مروہ کے درمیان سعی کی، لہٰذا میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کی شکایت کی تو آپ نے فرمایا: \"اپنا سر کھول لو، کنگھی کر لو، حج کا احرام باندھ لو، اور عمرے کو ترک کر دو\"، میں نے ایسا ہی کیا، جب میں نے حج ادا کر لیا تو مجھے رسول اللہ صلی اللہ علیہ وسلم نے (میرے بھائی) عبدالرحمٰن بن ابی بکر کے ساتھ مقام تنعیم بھیجا (تو میں وہاں سے احرام باندھ کر آئی اور) میں نے عمرہ ادا کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تمہارے عمرے کی جگہ پر ہے\"، ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: چنانچہ جنہوں نے عمرے کا احرام باندھ رکھا تھا انہوں نے بیت اللہ کا طواف کیا اور صفا و مروہ کے درمیان سعی کی، پھر ان لوگوں نے احرام کھول دیا، پھر جب منی سے لوٹ کر آئے تو حج کا ایک اور طواف کیا، اور رہے وہ لوگ جنہوں نے حج و عمرہ دونوں کو جمع کیا تھا تو انہوں نے ایک ہی طواف کیا ۱؎۔ ابوداؤد کہتے ہیں: اسے ابراہیم بن سعد اور معمر نے ابن شہاب سے اسی طرح روایت کیا ہے انہوں نے ان لوگوں کے طواف کا جنہوں نے عمرہ کے طواف کا احرام باندھا، اور ان لوگوں کے طواف کا جنہوں نے حج اور عمرہ دونوں کا احرام باندھا ذکر نہیں کیا۔\n§وضاحت\n۱؎ : اسی طرح حج افراد کا احرام باندھنے والوں نے بھی ایک ہی طواف کیا، واضح رہے کہ مفرد ہو یا متمتع یا قارن سب کے لئے طوافِ زیارت فرض ہے، اور متمتع پر صفا و مروہ کی دو سعی واجب ہے، جب کہ قارن کے لئے صرف ایک سعی کافی ہے، خواہ طواف قدوم (یا عمرہ ) کے وقت کرلے یا طواف زیارت کے بعد، یہی مسئلہ مفرد حاجی کے لئے بھی ہے، واضح رہے کہ بعض حدیثوں میں ’’سعی‘‘ کے لئے بھی ’’ طواف ‘‘ کا لفظ وارد ہوا ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم حجتہ الوداع میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے۔ ہم نے عمرے کا احرام باندھا۔ پھر آپ نے فرمایا ” جس کے ساتھ ہدی ہے وہ عمرے کے ساتھ حج کا تلبیہ بھی کہے، اور وہ حلال نہیں ہو گا حتیٰ کہ ان دونوں سے فارغ ہو۔ “ سو میں مکہ آئی تو حیض کی کیفیت میں تھی۔ میں نے بیت اللہ کا طواف نہیں کیا اور نہ صفا مروہ کی سعی کی۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اس کی شکایت کی، تو آپ نے فرمایا ” اپنا سر کھول لو ‘ کنگھی کر لو اور حج کا احرام باندھ لو اور عمرہ چھوڑ دو۔ “ فرماتی ہیں: چنانچہ میں نے ایسے ہی کیا۔ پھر جب ہم نے حج پورا کر لیا تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے (میرے بھائی) عبدالرحمٰن بن ابی بکر رضی اللہ عنہ کے ساتھ تنعیم بھیجا اور میں نے عمرہ کیا۔ اور آپ نے فرمایا ” یہ تیرے اس عمرے کے بدلے ہے۔ “ وہ بیان کرتی ہیں کہ (مکہ پہنچنے کے بعد) جن لوگوں نے عمرے کا احرام باندھ رکھا تھا انہوں نے بیت اللہ کا طواف کیا اور صفا مروہ کی سعی کی اور پھر حلال ہو گئے۔ ان لوگوں نے منیٰ سے واپسی کے بعد حج کے لیے ایک اور طواف کیا (طواف افاضہ زیادہ) مگر جن لوگوں نے حج اور عمرے کا اکٹھے احرام باندھا تھا (حج قران کا) تو انہوں نے صرف ایک ہی طواف کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اسے ابراہیم بن سعد اور معمر نے ابن شہاب سے اسی کی مانند روایت کیا ہے۔ ان لوگوں نے عمرہ کا احرام باندھنے والوں یا حج اور عمرہ کا اکٹھا احرام باندھنے والوں کے طواف کا ذکر نہیں کیا۔","f2":"[قارن] کو رخصت ہے کہ دسویں تاریخ کو طواف (زیادہ /افاضہ) کے بعد صفا مروہ کی سعی نہ کرے بلکہ طواف قدوم کے ساتھ کی جانے والی سعی پر کفالت کرلے تو مباح ہے۔ [تمتع] والا دو طواف اور دو سعی کرنے کا پابند ہے۔ یعنی ایک بار عمرے کے لیے اور دوسری بار حج کے لیے۔"}],[1782,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم نے حج کا تلبیہ پڑھا یہاں تک کہ جب ہم مقام سرف میں پہنچے تو مجھے حیض آ گیا، رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور میں رو رہی تھی، آپ نے پوچھا: \"عائشہ! تم کیوں رو رہی ہو؟\"، میں نے کہا: مجھے حیض آ گیا کاش میں نے (امسال) حج کا ارادہ نہ کیا ہوتا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی ذات پاک ہے، یہ تو بس ایسی چیز ہے جو اللہ نے آدم کی بیٹیوں کے واسطے لکھ دی ہے\"، پھر فرمایا: \"تم حج کے تمام مناسک ادا کرو البتہ تم بیت اللہ کا طواف نہ کرو ۱؎\"پھر جب ہم مکہ میں داخل ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اسے عمرہ بنانا چاہے تو وہ اسے عمرہ بنا لے ۲؎ سوائے اس شخص کے جس کے ساتھ ہدی ہو\"، ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: اور رسول اللہ صلی اللہ علیہ وسلم نے یوم النحر (دسویں ذی الحجہ) کو اپنی ازواج مطہرات کی جانب سے گائے ذبح کی۔ جب بطحاء کی رات ہوئی اور عائشہ رضی اللہ عنہا حیض سے پاک ہو گئیں تو انہوں نے کہا: اللہ کے رسول! کیا میرے ساتھ والیاں حج و عمرہ دونوں کر کے لوٹیں گی اور میں صرف حج کر کے لوٹوں گی؟ تو رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن بن ابوبکر رضی اللہ عنہما کو حکم دیا وہ انہیں لے کر مقام تنعیم گئے پھر ام المؤمنین عائشہ رضی اللہ عنہا نے وہاں سے عمرہ کا تلبیہ پڑھا۔\n§وضاحت\n۱؎ : طواف ایک ایسی عبادت ہے جس میں طہارت شرط ہے اسی وجہ سے رسول اللہ صلی اللہ علیہ وسلم نے ام المؤمنین عائشہ رضی اللہ عنہا کو طواف سے روک دیا، طواف کے علاوہ حائضہ حج کے تمام ارکان ادا کرے گی۔ ۲؎ : جیسا کہ مذکور ہوا یہ جملہ جو اس روایت میں ہے صحیح نہیں ہے، صحیح جملہ یوں ہے: ’’تم اپنے حج کو عمرہ بنا ڈالو سوائے اس شخص۔۔۔ الخ‘‘","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم نے حج کا تلبیہ کہا حتیٰ کہ جب ہم (سرف) مقام سرف پر پہنچے تو مجھے حیض آ گیا۔ رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے تو میں رو رہی تھی۔ آپ نے پوچھا: ” عائشہ! کیوں رو رہی ہو؟ “ میں نے کہا: مجھے حیض آ گیا ہے۔ کاش! میں حج کے لیے نہ آئی ہوتی۔ آپ نے فرمایا ” سبحان اللہ! یہ تو ایسی چیز ہے جو اللہ نے آدم کی بیٹیوں پر لکھ دی ہے۔ “ تب آپ نے فرمایا ” حج کے تمام اعمال پورے کرو، صرف بیت اللہ کا طواف نہ کرنا۔ “ چنانچہ جب ہم مکہ میں داخل ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ” جو اپنے اس احرام کو عمرے کا بنانا چاہے بنا لے۔ سوائے اس کے جس کے پاس قربانی ہو۔ “ سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی کے دن اپنی ازواج کی طرف سے گائیں ذبح کیں اور جب بطحاء کی رات آئی اور عائشہ رضی اللہ عنہا ا پاک ہو گئیں تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اے اللہ کے رسول! کیا میرے ساتھ والی حج اور عمرہ کر کے جائیں گی اور میں صرف حج کے ساتھ لوٹوں گی؟ تو رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن بن ابی بکر رضی اللہ عنہ کو حکم دیا وہ اسے تنعیم لے گئے اور انہوں (سیدہ عائشہ رضی اللہ عنہا ا) نے عمرے کا تلبیہ کہا۔","f2":"(1)جس نے حج کا احرام باندھا ہو اور قربانی ساتھ نہ ہو تو اسے جائز ہے کہ اپنے احرام کو عمرے کا احرام بنا لے۔ (2) جوشخص مکہ میں ہوتے ہوئے عمرہ کرنا چاہے اسے قریب ترین میقات پر جاکر احرام باندھ کر آنا لازم ہے۔سیدہ عائشہ رضی اللہ عنہا کو تو ایک طبعی عارضہ لاحق ہوگیا جس کی وجہ سے ان کا عمرہ رہ گیاتھا جس کا ان کو قلق تھا اس کا ازالہ ان کو تنعیم سے احرام بندھوا کر کرا دیا گیا یوں ان عمرہ بھی ہو گیا۔یہ خصوصی رعایت صرف سیدہ عائشہ رضی اللہ عنہا کے لیے تھی جس سے وہ عورتیں تو فائدہ اٹھا سکتی ہیں جو سیدہ عائشہ رضی اللہ عنہا کی طرح وہاں جاکرحائضہ ہو جائیں۔لیکن عام لوگ جو مزید عمرہ کرنا چاہیں وہ تنعیم (مسجد عائشہ)جاکر وہاں سے احرام باندھ کر آ کر عمرہ نہیں کر سکتے (جیسا کہ اکثر لوگ ایسا کرتے ہیں۔) البتہ وہ ذوالحلیفہ قرن المنازل یا کسی بھی میقات سے احرام باندھ کرآئیں تو دوبارہ عمرہ کرنا صحیح ہو گا۔"}],[1783,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، ہمارے پیش نظر صرف حج تھا، جب ہم (مکہ)آئے تو ہم نے بیت اللہ کا طواف کیا، اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ جو اپنے ساتھ ہدی نہ لایا ہو وہ حلال ہو جائے ۱؎، چنانچہ وہ تمام لوگ حلال ہو گئے جو ہدی لے کر نہیں آئے تھے۔\n§وضاحت\n۱؎ : یعنی اپنا احرام کھول دے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، ہم صرف حج سمجھ رہے تھے۔ مگر جب ہم مکہ پہنچے اور بیت اللہ کا طواف کیا تو رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ جو شخص قربانی ساتھ نہیں لایا وہ حلال ہو جائے۔ چنانچہ وہ لوگ جو قربانیاں ساتھ نہیں لائے تھے ‘ حلال ہو گئے۔"}],[1784,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر مجھے پہلے یہ بات معلوم ہو گئی ہوتی جواب معلوم ہوئی ہے تو میں ہدی نہ لاتا\"، محمد بن یحیی ذہلی کہتے ہیں: میرا خیال ہے کہ آپ صلی اللہ علیہ وسلم نے کہا: \"اور میں ان لوگوں کے ساتھ حلال ہو جاتا جو عمرہ کے بعد حلال ہو گئے\"، آپ صلی اللہ علیہ وسلم نے چاہا کہ سب لوگوں کا معاملہ یکساں ہو ۱؎۔\n§وضاحت\n۱؎ : کہ جو حج کا احرام باندھ کر آئے اور ہدی ساتھ نہ لائے تو وہ طواف اور سعی کرکے احرام کھول دیں، نبی اکرم صلی اللہ علیہ وسلم نے حجۃ الوداع میں لوگوں کی آسانی کے لئے ایسا حکم فرمایا تاکہ اس سے مشرکین کی مخالفت ہو، بعض لوگوں کو اس میں تردد ہوا تو آپ صلی اللہ علیہ وسلم ان پر ناراض ہوئے، اس حدیث کی بنا پر بعض ائمہ کے یہاں حج تمتع ہی واجب اور افضل ہے، (ملاحظہ ہو: زاد المعاد)۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اگر مجھے اس بات کی خبر پہلے ہوتی جس کی بعد میں ہوئی ہے تو میں قربانی ساتھ لے کر نہ آتا۔ “ محمد بن یحییٰ نے کہا: میرا خیال ہے کہ شیخ نے یہ بھی کہا: ” اور میں عمرے کے بعد حلال ہونے والوں کے ساتھ حلال ہو جاتا۔ “ کہا: آپ کا ارادہ تھا کہ سب لوگ ایک ہی حال پر ہوں۔","f2":"دراصل جاہلیت میں لوگ حج کے ساتھ یا حج کے مہینوں میں عمرہ گناہ کا کام سمجھتے تھے تو اس پرانی روش کے بدلنے کے لیے یہ تاکیدی حکم دیا گیا تھا۔"}],[1785,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج افراد کا احرام باندھ کر آئے، ام المؤمنین عائشہ رضی اللہ عنہا عمرے کا احرام باندھ کر آئیں، جب وہ مقام سرف میں پہنچیں تو انہیں حیض آ گیا یہاں تک کہ جب ہم لوگ مکہ پہنچے تو ہم نے کعبۃ اللہ کا طواف کیا اور صفا و مروہ کے درمیان سعی کی، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم میں سے جن کے پاس ہدی نہ ہو وہ احرام کھول دیں، ہم نے کہا: کیا کیا چیزیں حلال ہوں گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہر چیز حلال ہے\"، چنانچہ ہم نے عورتوں سے صحبت کی، خوشبو لگائی، اپنے کپڑے پہنے حالانکہ عرفہ میں صرف چار راتیں باقی تھیں، پھر ہم نے یوم الترویہ (آٹھویں ذی الحجہ) کو احرام باندھا، پھر رسول اللہ صلی اللہ علیہ وسلم عائشہ رضی اللہ عنہا کے پاس آئے تو انہیں روتے پایا، پوچھا: \"کیا بات ہے؟\"، وہ بولیں: مجھے حیض آ گیا لوگوں نے احرام کھول دیا لیکن میں نے نہیں کھولا اور نہ میں بیت اللہ کا طواف ہی کر سکی ہوں، اب لوگ حج کے لیے جا رہے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ (حیض) ایسی چیز ہے جسے اللہ نے آدم کی بیٹیوں کے لیے لکھ دیا ہے لہٰذا تم غسل کر لو پھر حج کا احرام باندھ لو\"، چنانچہ انہوں نے ایسا ہی کیا، اور سارے ارکان ادا کئے جب حیض سے پاک ہو گئیں تو بیت اللہ کا طواف کیا، اور صفا و مروہ کی سعی کی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اب تم حج اور عمرہ دونوں سے حلال ہو گئیں\"، وہ بولیں: اللہ کے رسول! میرے دل میں خیال آتا ہے کہ میں بیت اللہ کا طواف (قدوم) نہیں کر سکی ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"عبدالرحمٰن! انہیں لے جاؤ، اور تنعیم سے عمرہ کرا لاؤ\"، یہ واقعہ حصبہ ۱؎ کی رات کا تھا۔\n§وضاحت\n۱؎ : یعنی ذی الحجہ کی چودہویں رات کو، جس رات کو محصب میں اترتے ہیں یا تیرہویں رات کو اگر بارہویں تاریخ کو منی سے واپسی ہو، محصب: ایّام تشریق کے بعد منی سے لوٹتے وقت راستے میں مکہ سے قریب ایک مقام کا نام ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے روایت ہے ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ صرف حج (حج افراد) کی نیت سے چلے اور سیدہ عائشہ رضی اللہ عنہا ا نے عمرے کا احرام باندھا حتیٰ کہ جب مقام سرف میں پہنچیں تو انہیں حیض آ گیا۔ پھر جب ہم مکہ آئے اور کعبے کا طواف کیا اور صفا مروہ کی سعی کر لی تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم میں سے جس جس کے پاس قربانی نہیں ہے وہ حلال ہو جائے۔ ہم نے کہا: حلال ہونا کیسا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” پوری طرح سے حلال ہونا “ چنانچہ ہم اپنی ازواج سے ہمبستر بھی ہوئے، خوشبوئیں لگائیں اور اپنے عام کپڑے پہن لیے۔ حالانکہ ہمارے اور عرفہ جانے کے درمیان صرف چار راتیں باقی تھیں۔ پھر ہم نے آٹھویں تاریخ کو احرام باندھا، رسول اللہ صلی اللہ علیہ وسلم، سیدہ عائشہ رضی اللہ عنہا ا کے ہاں آئے تو دیکھا کہ رو رہی ہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” تمہیں کیا ہوا ہے؟ “ کہنے لگیں کہ مجھے حیض آ گیا ہے۔ لوگ حلال ہوئے، میں حلال نہیں ہوئی، اور نہ بیت اللہ کا طواف کیا اور اب وہ حج کے لیے جا رہے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ معاملہ تو اللہ نے آدم کی بیٹیوں پر لکھ دیا ہے۔ تم غسل کر لو اور حج کے لیے احرام باندھ لو۔ “ چنانچہ انہوں نے ایسے ہی کیا اور حج کے تمام مقامات پر ٹھہریں حتیٰ کہ جب پاک ہو گئیں تو بیت اللہ کا طواف اور صفا مروہ کی سعی کی۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” تم اپنے حج اور عمرے سب سے حلال ہو گئی ہو۔ “ کہنے لگیں، اے اللہ کے رسول! میرے دل میں حسرت ہے کہ میں نے جب حج کیا تو (ابتداء میں) طواف نہیں کر سکی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے عبدالرحمٰن ان کو لے جاؤ اور تنعیم سے عمرہ کرا لاؤ۔ “ اور یہ حصبہ کی رات تھی۔ (یعنی ایام تشریق کے بعد جس رات مدینہ کی طرف واپسی کے لیے بطحاء میں پڑاؤ ڈالا گیا تھا)۔"}],[1786,"ابوالزبیر کہتے ہیں کہ انہوں نے جابر رضی اللہ عنہ کو کہتے سنا کہ نبی اکرم صلی اللہ علیہ وسلم ام المؤمنین عائشہ رضی اللہ عنہا کے پاس آئے آگے اسی قصہ کا کچھ حصہ مروی ہے، اس میں ہے کہ اپنے قول «وأهلي بالحج» \"یعنی حج کا احرام باندھ لو\" کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر حج کرو اور وہ تمام کام کرو جو ایک حاجی کرتا ہے البتہ تم بیت اللہ کا طواف نہ کرنا اور نماز نہ پڑھنا\"۔","صحیح",{"u2":"ابوالزبیر کہتے ہیں کہ انہوں نے جابر رضی اللہ عنہ سے سنا کہتے تھے کہ نبی کریم صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا ا کے ہاں آئے اور اس قصے کا کچھ حصہ بیان کیا، اور«أهلي بالحج» ” حج کے لیے احرام باندھ لو۔ “ کے بعد یہ فرمایا ” پھر حج کرو اور وہ سب کچھ کرو جیسے حاجی کرتا ہے۔ صرف بیت اللہ کا طواف نہ کرنا اور نماز نہ پڑھنا۔ “"}],[1787,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ صرف حج کا احرام باندھا اس میں کسی اور چیز کو شامل نہیں کیا، پھر ہم ذی الحجہ کی چار راتیں گزرنے کے بعد مکہ آئے تو ہم نے طواف کیا، سعی کی، پھر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں احرام کھولنے کا حکم دے دیا اور فرمایا: \"اگر میرے ساتھ ہدی نہ ہوتا تو میں بھی احرام کھول دیتا\"، پھر سراقہ بن مالک رضی اللہ عنہ کھڑے ہوئے اور بولے: اللہ کے رسول! یہ ہمارا متعہ (حج کا متعہ) اسی سال کے لیے ہے یا ہمیشہ کے لیے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(نہیں) بلکہ یہ ہمیشہ کے لیے ہے\" ۱؎۔ اوزاعی کہتے ہیں: میں نے عطا بن ابی رباح کو اسے بیان کرتے سنا تو میں اسے یاد نہیں کر سکا یہاں تک کہ میں ابن جریج سے ملا تو انہوں نے مجھے اسے یاد کرا دیا۔\n§وضاحت\n۱؎ : اس حدیث سے امام احمد کے اس قول کی تائید ہوتی ہے کہ جو حج کا احرام باندھ کر آئے اور ہدی ساتھ نہ لائے وہ طواف اور سعی کرکے احرام کھول سکتا ہے، یعنی حج کو عمرہ میں تبدیل کر سکتا ہے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خالص حج کا احرام باندھا۔ اس میں کسی چیز کا اختلاط نہ تھا۔ پھر ذوالحجہ کی چار راتیں گزر جانے کے بعد ہم مکہ پہنچے۔ ہم نے طواف اور سعی کی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حلال ہونے کا حکم دے دیا اور فرمایا ” اگر میرے ساتھ قربانی نہ ہوتی تو میں بھی حلال ہو جاتا۔ “ پھر سیدنا سراقہ بن مالک رضی اللہ عنہ کھڑے ہوئے اور پوچھا: اے اللہ کے رسول! ہمارا یہ تمتع (حج کے ساتھ عمرہ کرنا) اسی سال کے لیے ہے یا ہمیشہ ہمیشہ کے لیے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلکہ ہمیشہ ہمیشہ کے لیے ہے۔ “ اوزاعی کہتے ہیں کہ میں نے عطاء بن ابی رباح کو یہ حدیث بیان کرتے سنا مگر میں یاد نہ رکھ سکا حتیٰ کہ ابن جریج سے ملا تو انہوں نے مجھے یاد کرائی۔","f2":"حج کے دنوں میں یا حج کے ساتھ ہی عمرہ بغیر کسی اشکال کے جائز ہے جبکہ ایام جاہلیت میں اسے بہت بڑا گناہ سمجھا جاتا تھا۔"}],[1788,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام ذی الحجہ کی چار راتیں گزرنے کے بعد (مکہ) آئے، جب انہوں نے بیت اللہ کا طواف اور صفا و مروہ کی سعی کر لی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سب اسے عمرہ بنا لو سوائے ان لوگوں کے جن کے ساتھ ہدی ہو\"، پھر جب یوم الترویہ (آٹھواں ذی الحجہ) ہوا تو لوگوں نے حج کا احرام باندھا، جب یوم النحر (دسواں ذی الحجہ) ہوا تو وہ لوگ (مکہ) آئے اور انہوں نے بیت اللہ کا طواف کیا اور صفا و مروہ کے درمیان سعی نہیں کی ۱؎۔\n§وضاحت\n۱؎ : کیونکہ پہلی سعی کافی تھی البتہ جو شخص حج سے پہلے سعی نہ کر سکا ہو اس کو طواف زیارت کے بعد سعی کرنا ضروری ہو گا۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ۔ جب انہوں نے بیت اللہ کا طواف اور صفا مروہ کی سعی کر لی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسے عمرہ بنا لو ‘ سوائے اس کے جس کے ساتھ قربانی ہو۔ “ سو جب آٹھویں تاریخ آئی تو ان لوگوں نے حج کا احرام باندھا اور پھر قربانی والے دن (دس ذوالحجہ کو) یہ لوگ مکہ آئے اور بیت اللہ کا طواف کیا مگر صفا مروہ کی سعی نہیں کی۔"}],[1789,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ کرام نے حج کا احرام باندھا ان میں سے اس دن نبی اکرم صلی اللہ علیہ وسلم اور طلحہ رضی اللہ عنہ کے علاوہ کسی کے پاس ہدی کے جانور نہیں تھے اور علی رضی اللہ عنہ یمن سے ساتھ ہدی لے کر آئے تھے تو انہوں نے کہا: میں نے اسی کا احرام باندھا ہے جس کا رسول اللہ صلی اللہ علیہ وسلم نے باندھا ہے، اور نبی اکرم صلی اللہ علیہ وسلم نے صحابہ کو حکم دیا کہ وہ حج کو عمرہ میں بدل لیں یعنی وہ طواف کر لیں پھر بال کتروا لیں اور پھر احرام کھول دیں سوائے ان لوگوں کے جن کے ساتھ ہدی ہو، تو لوگوں نے عرض کیا: کیا ہم منی کو اس حال میں جائیں کہ ہمارے ذکر منی ٹپکا رہے ہوں، رسول اللہ صلی اللہ علیہ وسلم کو جب یہ معلوم ہوا تو آپ نے فرمایا: \"اگر مجھے پہلے سے یہ معلوم ہوتا جو اب معلوم ہوا ہے تو میں ہدی نہ لاتا، اور اگر میرے ساتھ ہدی نہ ہوتا تو میں بھی احرام کھول دیتا\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ نے حج کا احرام باندھا۔ اس دن نبی صلی اللہ علیہ وسلم اور طلحہ رضی اللہ عنہ کے علاوہ کسی کے پاس قربانی نہ تھی۔ اور علی رضی اللہ عنہ یمن سے آئے تھے اور وہ اپنے ساتھ قربانیاں لائے تھے۔ پس انہوں نے اس طرح نیت کی تھی: میں اسی طرح احرام باندھتا ہوں جیسے کہ رسول اللہ صلی اللہ علیہ وسلم نے احرام باندھا ہے۔ اور آپ نے اپنے صحابہ رضی اللہ عنہم م کو حکم دیا تھا کہ اپنے احرام کو عمرہ کا احرام بنا لیں ‘ طواف کریں (صفا مروہ کی سعی بھی کریں) پھر بال کٹوا کر حلال ہو جائیں ‘ سوائے اس کے جس کے ساتھ قربانی ہو۔ کچھ لوگوں نے کہا: تو کیا ہم منیٰ کو اس حالت میں جائیں گے کہ ہمارے اعضائے تناسل منی ٹپکا رہے ہوں گے؟ رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے فرمایا ” اگر مجھے یہ بات پہلے معلوم ہوتی جو بعد میں معلوم ہوئی تو میں قربانی ساتھ نہ لاتا اور اگر میرے ساتھ قربانی نہ ہوتی تو میں (بھی) حلال ہو جاتا۔ “","f2":"(1)صحابہ کرام خوب سمجھتے تھے کہ دین و شریعت رسول اللہ صلی اللہ علیہ وسلم کی اطاعت ا ور پیروی کانام ہے۔ اسی لیے حضرت علی نے احرام کی نیت میں یہ کہا کہ میرا احرام اور میری نیت وہی ہے جو رسول اللہ صلی اللہ علیہ وسلم کی ہے۔ (2)اور دوسری بات (کہ ہم منی کو اس حالت میں جائیں ......)کہنے کی وجہ یہ تھی کہ عبادت چونکہ انسان سے زہد و رغبت الی اللہ کا تقاضا کرتی ہے اور اعمال حج شروع ہونےمیں دو دن باقی تھے تو انہیں کامل حلت کچھ عجیب سی لگی۔ نیز رسول اللہ صلی اللہ علیہ وسلم خود بھی تو حلال نہیں ہوئے تھے۔ او روہ رسول اللہ صلی اللہ علیہ وسلم کی پیروی کے شائق تھے۔ لیکن رسول اللہ صلی اللہ علیہ وسلم نے اپنی مجبوری کی وضاحت کرکے صحابہ کرام کا اشکال دور فرما دیا۔"}],[1790,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"یہ عمرہ ہے، ہم نے اس سے فائدہ اٹھایا لہٰذا جس کے ساتھ ہدی نہ ہو وہ پوری طرح سے حلال ہو جائے، اور عمرہ حج میں قیامت تک کے لیے داخل ہو گیا ہے\"۔ ابوداؤد کہتے ہیں: یہ (مرفوع حدیث) منکر ہے، یہ ابن عباس کا قول ہے نہ کہ نبی اکرم صلی اللہ علیہ وسلم کا ۱؎۔\n§وضاحت\n۱؎ : ابوداود کا یہ قول صحیح نہیں ہے، اس کو کئی راویوں نے مرفوعا روایت کیا ہے جن میں امام احمد بن حنبل بھی ہیں (منذری)۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ عمرہ ہے ہم نے اس کا فائدہ حاصل کیا ہے، سو جس کے ساتھ قربانی نہ ہو وہ حلال ہو جائے، پوری طرح حلال ہونا۔ اور قیامت تک کے لیے عمرہ حج میں داخل ہو گیا ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں یہ روایت منکر ہے۔ یہ صرف ابن عباس رضی اللہ عنہ کا قول ہے۔","f2":"(1)امام ابن القیم فرماتے ہیں: امام ابو داؤد کا مذکورہ بالا حدیث کو منکر کہنا صحیح نہیں۔کیونکہ یہ مسئلہ صحیح احادیث سے ثابت ہے۔ یہ جرح در اصل اگلی حدیث (1791پر ہے۔ (عون المعبود) (2) چونکہ قبل از اسلام لوگ ایام حج میں عمرہ کرنا کبیرہ گناہ سمجھتے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ان کی ممانعت کرتے ہوئے شریعت اسلام کی بات تاکید کے ساتھ نافذ فرمائی۔"}],[1791,"عبداللہ بن عباس رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا: \"جب آدمی حج کا احرام باندھ کر مکہ آئے اور بیت اللہ کا طواف اور صفا و مروہ کی سعی کر لے تو وہ حلال ہو گیا اور یہ عمرہ ہے\"۔ ابوداؤد کہتے ہیں: اسے ابن جریج نے ایک شخص سے انہوں نے عطا سے روایت کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے صحابہ خالص حج کا احرام باندھ کر مکہ میں داخل ہوئے تو نبی کریم صلی اللہ علیہ وسلم نے اسے عمرہ سے بدل دیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جب آدمی نے حج کا احرام باندھا پھر مکہ آیا، بیت اللہ کا طواف کیا اور صفا مروہ کی سعی کر لی تو وہ حلال ہو گیا اور یہ عمرہ ہو گا۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں اس حدیث کو ابن جریج نے ایک شخص کے واسطے سے عطاء سے یوں روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم کے اصحاب صرف حج کا تلبیہ کہتے ہوئے (مکے میں) داخل ہوئے۔ پس نبی کریم صلی اللہ علیہ وسلم نے اس کو عمرہ بنا دیا۔"}],[1792,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے حج کا احرام باندھا جب آپ (مکہ) آئے تو آپ نے بیت اللہ کا طواف کیا اور صفا و مروہ کی سعی کی (ابن شوکر کی روایت میں ہے کہ) آپ صلی اللہ علیہ وسلم نے بال نہیں کتروائے (پھر ابن شوکر اور ابن منیع دونوں کی روایتیں متفق ہیں کہ) آپ صلی اللہ علیہ وسلم نے ہدی کی وجہ سے احرام نہیں کھولا، اور حکم دیا کہ جو ہدی لے کر نہ آیا ہو طواف اور سعی کر لے اور بال کتروا لے پھر احرام کھول دے، (ابن منیع کی حدیث میں اتنا اضافہ ہے) : یا سر منڈوا لے پھر احرام کھول دے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے حج کا تلبیہ کہا۔ جب مکہ تشریف لائے اور بیت اللہ کا طواف اور صفا مروہ کی سعی کر لی۔ ابن شوکر نے کہا، اور آپ نے اپنے بال نہیں کتروائے، پھر ابن شوکر اور احمد بن منیع دونوں نے کہا، اور آپ اپنی قربانی کی وجہ سے حلال نہیں ہوئے۔ (لیکن) جن لوگوں کے ساتھ قربانی نہیں تھی ‘ انہیں حکم دیا کہ طواف اور سعی کے بعد بال کتروا کر حلال ہو جائیں۔ ابن منیع کی روایت میں اضافہ ہے: یا بال منڈوا کر حلال ہو جائیں۔"}],[1793,"سعید بن مسیب سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے صحابہ کرام میں سے ایک شخص عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور اس نے ان کے پاس گواہی دی کہ اس نے رسول اللہ صلی اللہ علیہ وسلم کو مرض الموت میں حج سے پہلے عمرہ کرنے سے منع کرتے ہوئے سنا۔","ضعیف",{"u2":"سعید بن مسیب سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور گواہی دی کہ اس نے رسول اللہ صلی اللہ علیہ وسلم سے آپ صلی اللہ علیہ وسلم کے مرض الموت میں سنا ہے کہ آپ صلی اللہ علیہ وسلم حج سے پہلے عمرہ کرنے سے منع فرماتے تھے۔","f2":"امام منذری کہتے ہیں کہ سعید بن مسیب کا حضرت عمر سے سماع صحیح ثابت نہیں ہے۔ (عون) اس لیے یہ روایت صحیح نہیں۔لیکن ہمارے محقق شیخ زبیر علی نے اسے حسن قرار دیا ہے۔ اس اعتبار سے اس میں نہی استحباب کے لیے ہوگی اور اس سے مطلب یہ ہوگا کہ استطاعت ہونے پر پہلے حج کیا جائے کیونکہ وہ بڑا فریضہ ہے اور زیاد ہ اہم ہے۔ ورنہ خود نبی صلی اللہ علیہ وسلم سے ثابت ہے کہ آپ نے اپنے حج سے پہلے دوعمرے کیے تھے۔"}],[1794,"ابوشیخ ہنائی خیوان بن خلدہ (جو اہل بصرہ میں سے ہیں اور ابوموسی اشعری رضی اللہ عنہ کے شاگرد ہیں) سے روایت ہے کہ معاویہ بن ابی سفیان رضی اللہ عنہما نے نبی اکرم صلی اللہ علیہ وسلم کے صحابہ کرام سے کہا: کیا تمہیں معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں فلاں چیز سے روکا ہے اور چیتوں کی کھال پر سوار ہونے سے منع فرمایا ہے؟ لوگوں نے کہا: ہاں، پھر معاویہ نے پوچھا: تو کیا یہ بھی معلوم ہے کہ آپ صلی اللہ علیہ وسلم نے (قران) حج اور عمرہ دونوں کو ملانے سے منع فرمایا ہے؟ لوگوں نے کہا: رہی یہ بات تو ہم اسے نہیں جانتے، تو انہوں نے کہا: یہ بھی انہی (ممنوعات) میں سے ہے لیکن تم لوگ بھول گئے ۱؎۔\n§وضاحت\n۱؎ : قران بعض علماء کے نزدیک افضل ہے، پھر تمتع، پھر افراد، اور بعض کے نزدیک افراد سب سے افضل ہے، پھر قران پھر تمتع، اور صحیح قول یہ ہے کہ تمتع سب سے افضل ہے، امام ابن قیم اور علامہ البانی کے بقول تمتع کے سوا حج کی دونوں قسمیں (یعنی افراد اور قران) منسوخ ہیں، کیوں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا ’’ جو بات مجھے اب معلوم ہوئی ہے وہ اگر پہلے معلوم ہوتی تو میں بھی ہدی کے جانور لے کر نہیں آتا، (تاکہ میں بھی اپنے حج کو عمرہ بنا دیتا) ‘‘، تو اب امت کے لئے یہ پیغام ملا کہ آئندہ کوئی ہدی لے کر آئے ہی نہیں۔","ضعیف",{"u2":"سیدنا معاویہ بن ابی سفیان رضی اللہ عنہ نے اصحاب نبی کریم صلی اللہ علیہ وسلم سے کہا کیا آپ لوگ جانتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں فلاں کام سے منع فرمایا ہے اور چیتے کی کھال پر سوار ہونے (بیٹھنے) سے بھی منع فرمایا ہے؟ انہوں نے کہا: ہاں! انہوں نے کہا: آپ لوگ یہ بھی جانتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے حج اور عمرے کو ملانے سے بھی منع کیا ہے؟ انہوں نے کہا: نہیں، یہ بات ہم نہیں جانتے۔ معاویہ نے کہا: یہ ہے تو ان (ممنوعہ چیزوں) ہی کے ساتھ مگر آپ لوگ بھول رہے ہیں۔ “","f2":"یہ روایت باعتبار سند محل نظر ہے۔تاہم اگر صحیح بھی ہوتو حضرت معاویہ کے حج او رعمرہ ملانے کےمسئلے میں وہم ہوا ہے یا متعة سے استناہ ہوا ہے۔انہوں نے متعةو النساء کے ساتھ ساتھ متعة الحج کو بھی ممنوع سمجھ لیا ہے جیسے کہ نبی صلی اللہ علیہ وسلم کے بال کتروانے (تقصیر) کےبارے میں انہیں اشتباہ ہواہے کہ اسے حجۃ الوداع میں بیان کرتے ہیں حالانکہ یہ آپ کےعمرے کا واقعہ ہے۔ (افادات از ابن القیم)"}],[1795,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ لوگوں نے انہیں کہتے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حج و عمرہ دونوں کا تلبیہ پڑھتے سنا آپ فرما رہے تھے: «لبيك عمرة وحجا لبيك عمرة وحجا» ۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا کہ آپ صلی اللہ علیہ وسلم حج اور عمرے کا تلبیہ اکٹھے پڑھتے ہوئے کہہ رہے تھے۔ «لبيك عمرة وحجا، لبيك عمرة وحجا»۔","f2":"عبادات میں سے حج اور عمرہ ہی ایک ایسی عبادت ہے جس کی نیت پکار کر کہی جاتی ہے۔ باقی کسی عبادت میں لفظی نیت ثابت نہیں ہے۔"}],[1796,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے رات ذی الحلیفہ میں گزاری، یہاں تک کہ صبح ہو گئی پھر سوار ہوئے یہاں تک کہ جب سواری آپ کو لے کر بیداء پہنچی تو آپ صلی اللہ علیہ وسلم نے اللہ کی تحمید، تسبیح اور تکبیر بیان کی، پھر حج و عمرہ دونوں کا احرام باندھا، اور لوگوں نے بھی ان دونوں کا احرام باندھا، پھر جب ہم لوگ (مکہ) آئے تو آپ صلی اللہ علیہ وسلم نے لوگوں کو (احرام کھولنے کا) حکم دیا، انہوں نے احرام کھول دیا، یہاں تک کہ جب یوم الترویہ (آٹھویں ذی الحجہ) آیا تو لوگوں نے حج کا احرام باندھا اور رسول اللہ صلی اللہ علیہ وسلم نے سات اونٹنیاں کھڑی کر کے اپنے ہاتھ سے نحر کیں ۱؎۔ ابوداؤد کہتے ہیں: جو بات اس روایت میں منفرد ہے وہ یہ کہ انہوں نے (یعنی انس رضی اللہ عنہ نے) کہا کہ آپ صلی اللہ علیہ وسلم نے پہلے «الحمدلله، سبحان الله والله أكبر» کہا پھر حج کا تلبیہ پکارا۔\n§وضاحت\n۱؎ : اور باقی اونٹوں کو علی رضی اللہ عنہ نے ذبح (نحر) کیا، کل سو اونٹ تھے، جو ذبح کئے گئے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ذوالحلیفہ کے مقام پر رات گزاری حتیٰ کہ صبح ہو گئی۔ پھر آپ (ظہر کے بعد) اپنی سواری پر سوار ہوئے حتیٰ کہ جب وہ آپ کو لے کر میدان بیداء میں سیدھی کھڑی ہوئی تو آپ نے ا اللہ کی حمد ‘ تسبیح اور تکبیر پکاری۔ پھر حج اور عمرے کا تلبیہ کہا۔ اور لوگوں نے بھی ان دونوں کا تلبیہ کہا۔ پھر جب ہم مکہ پہنچے تو آپ نے لوگوں کو حکم دیا تو حلال ہو گئے۔ (ان لوگوں کو جن کے پاس قربانیاں نہیں تھیں) حتی کہ جب آٹھویں تاریخ آئی تو انہوں نے حج کا احرام باندھا اور رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے سات اونٹنیاں نحر کیں، اس حال میں کہ وہ کھڑی ہوئی تھیں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سیدنا انس رضی اللہ عنہ اس روایت میں اس بات میں منفرد ہیں کہ انہوں نے ” اللہ کی حمد، تسبیح اور تکبیر کہی، پھر حج کا تلبیہ کہا۔ “","f2":"ان احادیث کے بیانات میں تعارض نہیں بلکہ تنوع ہے۔ حضرات صحابہ سامعین وناظرین کو جو جو معلوم ہوا انہوں نے وہی بیان کر دیا۔گزشتہ احادیث میں ہے کہ آپ نے نماز ظہر کے بعد اپنے مصلے ہی پر تلبیہ کہا پھر سواری پر بیٹھ کر کہا پھر بیداء کی بلندی پر چڑھنے ہوئے کہا اور یہ سب برحق ہیں اور اس اثنا میں تسبیح وتکبیر بلاشبہ جائز بلکہ مطلوب عمل ہے۔"}],[1797,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ جس وقت رسول اللہ صلی اللہ علیہ وسلم نے علی رضی اللہ عنہ کو یمن کا امیر مقرر کر کے بھیجا، میں ان کے ساتھ تھا تو مجھے ان کے ساتھ (وہاں) کئی اوقیہ سونا ملا، جب آپ یمن سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو دیکھا کہ فاطمہ رضی اللہ عنہا رنگین کپڑے پہنے ہوئے ہیں، اور گھر میں خوشبو بکھیر رکھی ہے، وہ کہنے لگیں: آپ کو کیا ہو گیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام کو حکم دیا تو انہوں نے احرام کھول دیا ہے، علی رضی اللہ عنہ کہتے ہیں: میں نے فاطمہ سے کہا: میں نے وہ نیت کی ہے جو نبی اکرم صلی اللہ علیہ وسلم نے کی ہے، میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں آیا تو آپ نے مجھ سے پوچھا: \"تم نے کیا نیت کی ہے؟\"، میں نے کہا: میں نے وہی احرام باندھا ہے جو نبی اکرم صلی اللہ علیہ وسلم کا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تو ہدی ساتھ لایا ہوں اور میں نے قِران کیا ہے\"، پھر آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"تم سڑسٹھ (۶۷)۱؎ یا چھیاسٹھ (۶۶) اونٹ (میری طرف سے) نحر کرو اور تینتیس (۳۳) یا چونتیس (۳۴) اپنے لیے روک لو، اور ہر اونٹ میں سے ایک ایک ٹکڑا گوشت میرے لیے رکھ لو\"۔\n§وضاحت\n۱؎ : ابوداود کی روایت میں اسی طرح وارد ہے جو وہم سے خالی نہیں، قیاس یہ ہے کہ اس سے مراد یہ ہے کہ تم (۶۷) یا (۶۶) اونٹ میری طرف سے نحر کرو اور باقی اپنی طرف سے کرنے کے لئے روک لو، اس معنی کے اعتبار سے علی رضی اللہ عنہ سارے اونٹوں کے نحر کرنے والے ہوں گے، حالانکہ یہ ثابت شدہ امر ہے کہ ان میں سے اکثر کو خود رسول اللہ صلی اللہ علیہ وسلم نے اپنے ہاتھ سے نحر کیا تھا، لہٰذا ’’ تم نحر کرو ‘‘ کے معنی یہ ہوں گے کہ انہیں نحر کے لئے تیار کرو اور انہیں منحر میں لے چلو تاکہ میں اپنے ہاتھ سے انہیں نحر کروں۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو جب یمن کا والی بنا کر بھیجا تو میں ان کے ساتھ تھا۔ اس خدمت کے صلے میں مجھے چند اوقیہ (سونا) بھی ملا تھا۔ سیدنا علی رضی اللہ عنہ جب یمن سے واپسی کے بعد رسول اللہ صلی اللہ علیہ وسلم سے ملے تو وہ کہتے ہیں کہ میں نے فاطمہ رضی اللہ عنہا ا کو پایا کہ انہوں نے رنگین کپڑے پہنے ہیں اور اپنی منزل کو بھی انہوں نے معطر کر رکھا ہے۔ (سیدنا علی رضی اللہ عنہ کو تعجب ہوا) تو وہ بولیں: آپ حیران کیوں ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب کو حکم دیا ہے اور وہ حلال ہو گئے ہیں۔ وہ کہتے ہیں کہ میں نے فاطمہ رضی اللہ عنہا ا سے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم والے احرام کی نیت کر رکھی ہے۔ کہتے ہیں، چنانچہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو آپ صلی اللہ علیہ وسلم نے پوچھا ” تم نے (نیت) کیسے کی ہے؟ “ میں نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کے احرام والی نیت کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں اپنی قربانی ساتھ لایا ہوں اور قران کی نیت کی ہے۔ “ وہ بیان کرتے ہیں کہ پھر آپ صلی اللہ علیہ وسلم نے مجھے حکم فرمایا کہ سڑسٹھ یا چھیاسٹھ اونٹ نخر کرو اور تینتیس یا چونتیس اونٹ اپنے لیے لے لو اور ہر قربانی میں سے گوشت کا ایک ایک ٹکڑا میرے لیے لاؤ۔ “","f2":"(1)دین میں حجت رسو ل اللہ صلی اللہ علیہ وسلم ہی کا قول فعل ہے کسی اور کانہیں خواہ اس کا رشتہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کتنا ہی قربت کا کیوں نہ ہو۔ جیسے کہ فاطمہ رضی اللہ عنہا نے اپنے بارے میں واضح کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے فرمان ہی سے حلال ہوئی ہوں مگر ان کے شوہر رسول اللہ صلی اللہ علیہ وسلم کی اتباع میں حلال نہیں ہو سکے۔ (2) قربانیوں کے سلسلے میں صحیح تر یہ ہے کہ تریسٹھ قربانیاں نبی صلی اللہ علیہ وسلم نے اپنے ہاتھ سے کیں اور بقیہ حضرت علی کو فرمایا تھا اور انہوں نے کیں۔ (صحیح مسلم الحج باب حجۃ النبی صلی اللہ علیہ وسلم حدیث:1218)"}],[1798,"ابووائل کہتے ہیں کہ صبی بن معبد سے کہا: میں نے (حج و عمرہ) دونوں کا ایک ساتھ احرام باندھا تو عمر رضی اللہ عنہ نے کہا: تمہیں اپنے نبی کی سنت پر عمل کی توفیق ملی۔","صحیح",{"u2":"ابووائل بیان کرتے کہ جناب صبی بن معبد نے کہا میں نے حج اور عمرے دونوں کا اکٹھے ہی تلبیہ کہا ہے تو سیدنا عمر بن خطاب رضی اللہ عنہ نے کہا تمہیں اپنے نبی کریم صلی اللہ علیہ وسلم کے طریقے کی ہدایت ملی ہے۔"}],[1799,"ابووائل کہتے ہیں کہ صبی بن معبد نے عرض کیا کہ میں ایک نصرانی بدو تھا میں نے اسلام قبول کیا تو اپنے خاندان کے ایک شخص کے پاس آیا جسے ہذیم بن ثرملہ کہا جاتا تھا میں نے اس سے کہا: ارے میاں! میں جہاد کا حریص ہوں، لیکن میں سمجھتا ہوں کہ حج و عمرہ میرے اوپر فرض ہیں، تو میرے لیے کیسے ممکن ہے کہ میں دونوں کو ادا کر سکوں، اس نے کہا: دونوں کو جمع کر لو اور جو ہدی میسر ہو اسے ذبح کرو، تو میں نے ان دونوں کا احرام باندھ لیا، پھر جب میں مقام عذیب پر آیا تو میری ملاقات سلمان بن ربیعہ اور زید بن صوحان سے ہوئی اور میں دونوں کا تلبیہ پکار رہا تھا، تو ان میں سے ایک نے دوسرے سے کہا: یہ اپنے اونٹ سے زیادہ سمجھ دار نہیں، تو جیسے میرے اوپر پہاڑ ڈال دیا گیا ہو، یہاں تک کہ میں عمر بن خطاب رضی اللہ عنہ کے پاس آیا، میں نے ان سے عرض کیا: امیر المؤمنین! میں ایک نصرانی بدو تھا، میں نے اسلام قبول کیا، میں جہاد کا خواہشمند ہوں لیکن دیکھ رہا ہوں کہ مجھ پر حج اور عمرہ دونوں فرض ہیں، تو میں اپنی قوم کے ایک آدمی کے پاس آیا اس نے مجھے بتایا کہ تم ان دونوں کو جمع کر لو اور جو ہدی میسر ہو اسے ذبح کرو، چنانچہ میں نے دونوں کا ایک ساتھ احرام باندھا تو عمر رضی اللہ عنہ نے مجھ سے کہا: تمہیں اپنے نبی اکرم صلی اللہ علیہ وسلم کی سنت پر عمل کی توفیق ملی۔","صحیح",{"u2":"ابووائل کہتے ہیں کہ جناب صبی بن معبد نے کہا کہ میں ایک بدوی نصرانی آدمی تھا، مسلمان ہو گیا۔ پھر میں اپنے قبیلے کے ایک آدمی کے پاس آیا جس کا نام ہدیم بن ثرملہ تھا۔ میں نے اس سے کہا: ارے میاں! میں جہاد کا حریص ہوں مگر حج اور عمرہ بھی مجھ پر لازم ہو چکے ہیں تو اگر میں ان دونوں (حج اور عمرے) کو جمع کر لوں تو کیسا رہے گا؟ اس نے کہا: ان دونوں کو جمع کر لو اور جو میسر ہو قربانی کر لو۔ چنانچہ میں نے ان دونوں کی نیت سے تلبیہ کہا (اور احرام باندھا) جب میں عذیب مقام پر پہنچا تو مجھے سلمان بن ربیعہ اور زید بن صوحان ملے اور میں حج اور عمرے دونوں کا تلبیہ پکار رہا تھا۔ تو ان میں سے ایک نے دوسرے سے کہا: یہ اپنے اونٹ سے زیادہ سمجھ دار نہیں ہے! (بیوقوف ہے کہ حج اور عمرے کا اکٹھے تلبیہ پکار رہا ہے) صبی بیان کرتے ہیں کہ ان کی اس بات سے گویا مجھ پر پہاڑ ٹوٹ پڑا حتیٰ کہ میں عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور ان سے کہا: اے امیر المؤمنین! میں ایک بدوی نصرانی آدمی تھا اور مسلمان ہو گیا ہوں، جہاد پر جانے کا حریص ہوں مگر میں نے دیکھا کہ حج اور عمرہ بھی مجھ پر واجب ہو چکا ہے تو میں قوم کے ایک آدمی کے پاس آیا، اس نے مجھے کہا کہ حج اور عمرے کو اکٹھا کر لو اور جو میسر ہو قربانی کر لو۔ چنانچہ میں نے ان دونوں کا اکٹھے تلبیہ پکارا ہے۔ تو سیدنا عمر رضی اللہ عنہ نے مجھے فرمایا تمہیں تمہارے نبی کریم صلی اللہ علیہ وسلم کے طریقے کی ہدایت ملی ہے۔","f2":"(1)حج اور عمرے کا اکٹھے احرام باندھنا عین سنت ہے اور اس میں قربانی واجب ہے۔ (2)علم کے تغیر فتویٰ دینا بہت بری بات ہے۔اکثر اوقات اس کے برے نتائج سامنے آتے ہیں۔ اشتنباہ کے مواقع پر راسخ علمائے دین سے رابطہ کرنا چاہیے۔ (3) ایمان جب دل میں رچ بس جاتا ہے تو اس ک اثرات اعمال خیر کی صورت میں ظاہر ہوئے بغیر نہیں رہتے۔ اعمال میں کمی یا سستی اصل ایمان میں کمی کی علامت ہوتی ہے۔ ولاحول ولاقوةالا بالله ."}],[1800,"عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"آج رات میرے پاس میرے رب عزوجل کی جانب سے ایک آنے والا (جبرائیل) آیا (آپ اس وقت وادی عقیق ۱؎ میں تھے) اور کہنے لگا: اس مبارک وادی میں نماز پڑھو، اور کہا: عمرہ حج میں شامل ہے\"۔ ابوداؤد کہتے ہیں: ولید بن مسلم اور عمر بن عبدالواحد نے اس حدیث میں اوزاعی سے یہ جملہ «وقل عمرة في حجة» (کہو! عمرہ حج میں ہے) نقل کیا ہے۔ ابوداؤد کہتے ہیں: اسی طرح اس حدیث میں علی بن مبارک نے یحیی بن ابی کثیر سے «وقل عمرة في حجة» کا جملہ نقل ۲؎ کیا ہے۔\n§وضاحت\n۱؎ : ’’عقيق‘‘: مدینہ سے چار میل کی دوری پر ایک وادی ہے، اور اب شہر میں داخل ہے۔ ۲؎ : یہ جملہ احادیث میں تین طرح سے وارد ہوا ہے، مسکین کی روایت میں جسے انہوں نے اوزاعی سے روایت کیا ہے «قال عمرة في حجة» ماضی کے صیغہ کے ساتھ، اور ولید بن مسلم اور عبدالواحد کی روایت میں «وقل عمرة في حجة» امر کے صیغہ کے ساتھ، اور بخاری کی روایت میں «وقل عمرة في حجة» ہے «عمرة» اور «حجة» کے درمیان واو عاطفہ کے ساتھ۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے مجھ سے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا جبکہ آپ وادی عقیق میں تھے، آپ فر ہے تھے ” آج رات میرے پاس میرے رب عزوجل کی طرف سے ایک آنے والا آیا اور اس نے کہا ہے: اس مبارک وادی میں نماز پڑھو اور اس نے کہا کہ عمرہ حج میں داخل ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو ولید بن مسلم اور عمر بن عبدالواحد نے اوزاعی سے بیان کیا تو صرف اسی قدر کہا: «وقل عمرة في حجة» (کہہ دو کہ عمرہ حج میں داخل ہے۔ اور لفظ «قال» کی بجائے «وقل» کہا۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ایسے ہی علی بن مبارک نے یحییٰ بن ابی کثیر سے (بصیغئہ امر) «قل عمرة في حجة» بیان کیا ہے۔","f2":"وادی عقیق مدینہ کے قریب چار میل کے فاصلے پر واقع ہے اور ذوالحلیفہ سے ہو کر گزرتی ہے۔"}],[1801,"سبرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے یہاں تک کہ جب ہم عسفان میں پہنچے تو آپ سے سراقہ بن مالک مدلجی نے کہا: اللہ کے رسول! آج ایسا بیان فرمائیے جیسے ان لوگوں کو سمجھاتے ہیں جو ابھی پیدا ہوئے ہوں (بالکل واضح) تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے تمہارے لیے عمرہ کو تمہارے حج میں داخل کر دیا ہے لہٰذا جب تم مکہ آ جاؤ تو جو بیت اللہ کا طواف اور صفا و مروہ کی سعی کر لے تو وہ حلال ہو گیا سوائے اس کے جس کے ساتھ ہدی کا جانور ہو\"۔","صحیح",{"u2":"جناب ربیع بن سبرہ اپنے والد سے بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے حتیٰ کہ جب ہم مقام عسفان میں تھے تو سراقہ بن مالک مدلجی رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم سے کہا: اے ا اللہ کے رسول! ہمیں خوب واضح فر دیجئیے اور ہمیں ایسی قوم سمجھیے جو گویا آج ہی پیدا ہوئے ہوں۔ آپ نے فرمایا ” بلاشبہ ا اللہ تعالیٰ نے تمہارے اس حج میں عمرے کو داخل کر دیا ہے، سو جب تم مکہ پہنچو تو جس نے بیت اللہ کا طواف اور صفا مروہ کی سعی کر لی، پس وہ حلال ہو گیا الا یہ کہ اس کے ساتھ قربانی ہو۔ “","f2":"یعنی حج کے احرم کے ساتھ عمرہ بھی کیا جاسکتا ہے یعنی بصورت قران یا تمتع۔ جبکہ قبل از اسلام ایام حج میں عمرے کو کبیرہ گناہ تصور کیا جاتاتھا۔"}],[1802,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ معاویہ بن ابی سفیان رضی اللہ عنہما نے انہیں خبر دی، وہ کہتے ہیں: میں نے مروہ پر نبی اکرم صلی اللہ علیہ وسلم کے بال تیر کی دھار سے کاٹے، (یا یوں ہے) میں نے آپ کو دیکھا کہ مروہ پر تیر کے پیکان سے آپ کے بال کترے جا رہے ہیں ۱؎۔\n§وضاحت\n۱؎ : صحیح بخاری میں صرف اتنا ہے کہ ’’میں نے آپ صلی اللہ علیہ وسلم کے بال تیر کی دھار سے کاٹے‘‘، اس جملے سے کوئی اشکال نہیں پیدا ہوتا، مگر صحیح مسلم و دیگر کے الفاظ ’’مروہ پر‘‘ سے یہ اشکال پیدا ہوتا ہے کہ آپ صلی اللہ علیہ وسلم قارن تھے تو عمرہ کے بعد مروہ پر بال کاٹنے کا کیا مطلب؟ تو اس کا جواب یہ ہے کہ یہ معاملہ عمرہ جعرانہ کا ہے نہ کہ حجۃ الوداع کا، جیسا کہ علماء نے تصریح کی ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا معاویہ رضی اللہ عنہ نے انہیں بتایا کہ میں نے مروہ پر ایک تیر کے پھل سے نبی کریم صلی اللہ علیہ وسلم کے بال کاٹے تھے یا میں نے دیکھا کہ مروہ پر تیر کے پھل سے آپ صلی اللہ علیہ وسلم کے بال کاٹے گئے۔ ابوبکر بن خلاد نے «أخبره» کا لفظ استعمال نہیں کیا (بلکہ یوں کہا) «إن معاوية بن ابی سفیان...)"}],[1803,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ معاویہ رضی اللہ عنہ نے ان سے کہا: کیا تمہیں نہیں معلوم کہ میں نے مروہ پر رسول اللہ صلی اللہ علیہ وسلم کے بال ایک اعرابی کے تیر کی پیکان سے کترے۔ حسن کی روایت میں «لحجته» (آپ کے حج میں) ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا معاویہ رضی اللہ عنہ نے ان سے کہا: کیا تمہیں معلوم نہیں کہ میں نے مروہ پر ایک بدوی کے تیر (کے پھل) سے رسول اللہ صلی اللہ علیہ وسلم کے بال کاٹے تھے۔ حسن بن علی کی روایت میں اضافہ ہے ” حج کے موقع پر۔ “","f2":"(1)حضرت معاویہ نے یہ خدمت حج کے موقع پر نہیں بلکہ عمرہ جعرانہ کے موقع پر سر انجام دی تھی۔جیسے کہ سنن نسائی کی روایت میں [فی عمرتة] کی صراحت ہے۔ (سنن نسائی مناسک الحج حدیث:2990)اور حج کےموقع پر کی تعبیر یاتومجاز ہے یا وہم۔ واللہ اعلم . (2)عمرے میں صفا مروہ کی سعی کے بعد آدمی بال کتروا کر حلال ہوتا ہے۔ جبکہ عورتوں کو ایک پورا برابر بال کاٹنا کافی ہوتے ہیں۔"}],[1804,"مسلم قری سے روایت ہے کہ انہوں نے ابن عباس رضی اللہ عنہما کو کہتے سنا کہ نبی اکرم صلی اللہ علیہ وسلم نے عمرہ کا تلبیہ پکارا اور آپ کے صحابہ کرام نے حج کا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے عمرے کا تلبیہ پکارا اور آپ صلی اللہ علیہ وسلم کے اصحاب نے حج کا۔","f2":"حج قران کے لیے تلبیہ میں یہ جائز ہے کہ کسی وقت [لبیک بحجة] کہے۔"}],[1805,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع میں عمرے کو حج کے ساتھ ملا کر تمتع کیا تو آپ نے ہدی کے جانور تیار کئے، اور ذی الحلیفہ سے اپنے ساتھ لے کر گئے تو پہلے رسول اللہ صلی اللہ علیہ وسلم نے عمرے کا تلبیہ پکارا پھر حج کا (یعنی پہلے «لبيك بعمرة» کہا پھر «لبيك بحجة» کہا) ۱؎ اور رسول اللہ صلی اللہ علیہ وسلم کے ساتھ لوگوں نے بھی عمرے کو حج میں ملا کر تمتع کیا، تو لوگوں میں کچھ ایسے تھے جنہوں نے ہدی تیار کیا اور اسے لے گئے، اور بعض نے ہدی نہیں بھیجا، جب رسول اللہ صلی اللہ علیہ وسلم مکہ پہنچے تو لوگوں سے فرمایا: \"تم میں سے جو ہدی لے کر آیا ہو تو اس کے لیے (احرام کی وجہ سے) حرام ہوئی چیزوں میں سے کوئی چیز حلال نہیں جب تک کہ وہ اپنا حج مکمل نہ کر لے، اور تم لوگوں میں سے جو ہدی لے کر نہ آیا ہو تو اسے چاہیئے کہ بیت اللہ کا طواف کرے، صفا و مروہ کی سعی کرے، بال کتروائے اور حلال ہو جائے، پھر حج کا احرام باندھے اور ہدی دے جسے ہدی نہ مل سکے تو ایام حج میں تین روزے رکھے اور سات روزے اس وقت جب اپنے گھر والوں کے پاس لوٹ کر آ جائے\"، اور رسول اللہ صلی اللہ علیہ وسلم جب مکہ آئے تو آپ نے طواف کیا، سب سے پہلے آپ صلی اللہ علیہ وسلم نے حجر اسود کا استلام کیا، پھر پہلے تین پھیروں میں تیز چلے اور آخری چار پھیروں میں عام چال، بیت اللہ کے طواف سے فارغ ہو کر آپ صلی اللہ علیہ وسلم نے مقام ابراہیم پر دو رکعتیں پڑھیں، پھر سلام پھیرا اور پلٹے تو صفا پر آئے اور صفا و مروہ میں سات بار سعی کی، پھر (آپ کے لیے محرم ہونے کی وجہ سے) جو چیز حرام تھی وہ حلال نہ ہوئی یہاں تک کہ آپ صلی اللہ علیہ وسلم نے اپنا حج پورا کر لیا اور یوم النحر (دسویں ذی الحجہ) کو اپنا ہدی نحر کر دیا، پھر لوٹے اور بیت اللہ کا طواف (افاضہ) کیا پھر ہر حرام چیز آپ کے لیے حلال ہو گئی اور لوگوں میں سے جنہوں نے ہدی دی اور اسے ساتھ لے کر آئے تو انہوں نے بھی اسی طرح کیا جیسے رسول اللہ صلی اللہ علیہ وسلم نے کیا۔\n§وضاحت\n۱؎ : رسول اکرم صلی اللہ علیہ وسلم کے حج کے بارے میں صحابہ کرام رضی اللہ عنہم کے متعدد بیانات ہیں، ان کے درمیان تطبیق کا خلاصہ یہ ہے کہ آپ صلی اللہ علیہ وسلم نے شروع میں صرف حج کا احرام باندھا، پھر وحی آ گئی تو عمرہ کو بھی شامل کر لیا، اگر آپ صلی اللہ علیہ وسلم ہدی ساتھ لے کر نہیں گئے ہوتے تو پہلے عمرہ کرتے پھر حلال ہو کر حج کرتے (یعنی حج تمتع کرتے) جیسا کہ صحابہ کرام رضی اللہ عنہ کو حکم دیا تھا، خلاصہ یہ کہ آپ صلی اللہ علیہ وسلم نے حج قران کیا تھا جیسا کہ دسیوں صحابہ کا بیان ہے، اس تفصیل کے مطابق ابن عمر رضی اللہ عنہما کا یہ کہنا کہ ’’آپ صلی اللہ علیہ وسلم نے پہلے عمرہ کا احرام پھر حج کا احرام باندھا‘‘ خلاف واقعہ ہے جو ان کے اپنے علم کے مطابق ہے (ابتدائے امر کے مطابق ہے)، یا پھر ان کے بیان کی وہی تاویل ہے جو ترجمہ سے ظاہر ہے یعنی: یہاں تمتع سے مراد لغوی تمتع ہے نہ کہ اصطلاحی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حجتہ الوداع میں عمرے کو حج کے ساتھ ملا کر تمتع کیا۔ (تمتع کا لغوی معنی استفادہ ہے۔) آپ نے ذوالحلیفہ سے قربانی لی اور اپنے ساتھ لے گئے۔ ابتداء میں رسول اللہ صلی اللہ علیہ وسلم نے عمرے کا تلبیہ کہا اور پھر حج کا۔ اور لوگوں نے بھی آپ کے ساتھ عمرے کو حج کے ساتھ ملا کر تمتع کیا۔ لوگوں میں سے کچھ تو وہ تھے جو قربانیاں اپنے ساتھ لے گئے اور کچھ وہ تھے جو نہ لے گئے۔ جب رسول اللہ صلی اللہ علیہ وسلم مکہ پہنچے تو لوگوں سے فرمایا ” تم میں سے جو شخص قربانی لایا ہے اس کے لیے حرام ہونے والی کوئی شے حلال نہیں حتیٰ کہ اپنا حج مکمل کر لے۔ لیکن جو قربانی نہیں لایا ہے تو اسے چاہیئے کہ بیت اللہ کا طواف اور صفا مروہ کی سعی کرے اور اس کے بعد اپنے بال کتروا کر حلال ہو جائے۔ پھر اس کے بعد حج کا احرام باندھے اور قربانی دے۔ اور جو قربانی کی استطاعت نہ پائے تو وہ حج کے دونوں میں تین دن روزے رکھے اور مزید سات دن اپنے اہل میں واپس لوٹ کر رکھے۔ “ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے مکہ پہنچنے پر طواف کیا اور سب سے پہلے رکن (حجر اسود) کو بوسہ دیا۔ پھر طواف کے سات چکروں میں سے (پہلے) تین چکروں میں آہستہ آہستہ دوڑے اور باقی چار میں (عام رفتار سے) چلے۔ طواف کے بعد آپ نے مقام ابراہیم کے پاس دو رکعتیں پڑھیں، پھر سلام پھیرا۔ پھر آپ صفا کی طرف آئے اور صفا مروہ پر سات چکر لگائے۔ پھر آپ پر حرام ہونے والی چیزوں میں سے کوئی بھی چیز حلال نہ ہوئی۔ (اسی طرح احرام ہی میں رہے) حتیٰ کہ اپنا حج مکمل کیا۔ دسویں تاریخ کو قربانی کی اور طواف افاضہ کیا، پھر آپ کے لیے تمام چیزیں حلال ہو گئیں جو بحالت احرام، حرام تھیں۔ اور دیگر لوگوں نے بھی جو قربانیاں اپنے ساتھ لائے تھے اسی طرح کیا جیسے کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا۔","f2":"(1)حج کے لیے قران (قاف کے کسرہ کے ساتھ) اور تمتع کی اصطلاحات شروع میں اس طرح مشہور و معروف نہ تھیں جس طرح کہ بعد میں ہوئیں۔ یہی وجہ ہے کہ کچھ احادیث میں قران کے لیے تمتع کا لفظ بھی آیا ہے جیسے کہ مندرجہ ذیل بالاحدیث میں وارد ہوا ہے۔یہاں یہ لغوی معنی میں ہے۔یعنی فائدہ حاصل کرنا۔ چونکہ انہوں نے اپنے سفر حج میں عمرے کا فائدہ بھی حاصل کر لیا تھا اس لیے یہاں اسے لغوی طور پر تمتع سے تعبیر کر دیا ہے۔ ورنہ موجود اصطلاح کےاعتبار سے یہ حج تمتع نہیں ہے حج قران ہے۔(2)مکہ پہنچ کر سب سے پہلا کام بیت اللہ کا طواف ہوتا ہے۔ اس طواف کو طواف قدوم کہتے ہیں۔(3) طواف کی ابتدائی حجر اسود سے اور اس کے استلام سے ہوتی ہے اور اسی پر انتہا بھی۔ استلام کےمعنی ہیں ہاتھ لگانا یا چومنا ایک مکمل طواف میں سات چکر پورے کیے جاتے ہیں اور اس پہلے طواف (طواف قدوم)کے پہلے تین چکروں میں آہستہ آہستہ دو‎ڑنا مسنون ہے۔اسے [رمل] یا [خبب] کہتے ہیں۔مگر عورتیں اس سے مستثنی ہیں۔بعد والے کسی طواف میں رمل نہیں کیاجاتا۔(4) طواف کے بعد دو رکعتیں پڑھنا مسنون ہے۔مستحب یہ ہے کہ مقام ابراہیم کے پاس پڑھی جائیں۔ان کے بعد دوبارہ حجر اسود کو بوسہ دینا یا ہاتھ لگانا بھی مسنون عمل ہے جو صحیح حدیث سے ثابت ہے۔ خیال رہے کہ حجراسود کو بوسہ دینے کے لیے دھکم پیل ایک قبیح اور ناجائز حرکت ہے اور خواتین کے اندر گھسیں۔چاہیے کہ باوقار انداز سے اپنی باری کا انتظار کیا جائے یا پھر صرف ہاتھ لگا کر اشارہ کر کے آگے گزر جائے۔ (5)حج تمتع یا قران والے کے لیے قربانی واجب ہے۔اگر قربانی کی استطاعت نہ ہو تو دس روزے رکھے۔تین روزے ایام حج میں اور باقی سات اپنے اہل میں واپس آکر۔ایام حج سےمراد 9ذوالحجہ (یوم عرفات) سے پہلے یا پھر ایام تشریق ہیں۔ (تفسیر فتح القدیر) ب(6)حج تمتع والا یا عمرے والا بیت اللہ کے طواف اور صفا مروہ کی سعی کے بعد حجامت بنوا کر کامل طور پر حلال ہو جاتا ہے جبکہ حج افراد یا قران والا دسویں ذوالحج کو قربانی کرنے اور حجامت بنوانے کے بعد لباس تبدیل کر سکتا ہے اور خوشبو لگا سکتا ہے۔مگر بیوی سے قربت نہیں کر سکتا۔ہاں بیت اللہ کے طواف (طواف افاضہ یا طواف زیارت)کے بعد وہ کامل طورپر حلال ہو جاتا ہے۔(7) شیخ البانی  نے اس روایت کے الفاظ ابتدا میں رسول اللہ صلی اللہ علیہ وسلم نے عمرے کا تلبیہ کہا پھر حج کا کو شاذ قرار دیا ہے۔گویا صحیح بات یہ ہے کہ آپ نے پہلے حج کا تلبیہ کہا اور آ‎گے جاکر حج کے ساتھ عمرے کو بھی ملالیا۔ایسا ابتدا میں نہیں ہو ا بلکہ آگے جاکر ہوا۔ اس طرح دوسری روایات کے ساتھ مطابقت ہو جاتی ہے۔ (تفصیل کے لیے دیکھیے:زاد المعاد فتح الباری عون المعبود وغیرہ۔)"}],[1806,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ انہوں نے پوچھا: اللہ کے رسول! کیا وجہ ہے کہ لوگوں نے احرام کھول دیا لیکن آپ نے اپنے عمرے کا احرام نہیں کھولا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اپنے سر میں تلبید کی تھی اور ہدی کو قلادہ پہنایا تھا تو میں اس وقت تک حلال نہیں ہو سکتا جب تک کہ ہدی نحر نہ کر لوں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ حفصہ رضی اللہ عنہا ا سے مروی ہے انہوں نے کہا: اے اللہ کے رسول! لوگوں کا کیا حال ہے کہ حلال ہو گئے ہیں جبکہ آپ اپنے عمرے سے حلال نہیں ہوئے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں نے اپنے سر کے بال چپکا رکھے ہیں اور اپنی قربانی کو قلاوہ پہنایا ہوا ہے، سو میں اس وقت تک حلال نہیں ہو سکتا جب تک کہ قربانی نحر نہ کر لوں۔ “","f2":"چونکہ ازواج محترمات کی قربانیاں ان کے ساتھ نہیں تھی اس لیے وہ حلال ہو گئیں۔ اور رسول اللہ صلی اللہ علیہ وسلم محرم ہی رہے۔ (صحیح بخاری الحج حدیث:1561)"}],[1807,"سلیم بن اسود سے روایت ہے کہ ابوذر رضی اللہ عنہ ایسے شخص کے بارے میں جو حج کی نیت کرے پھر اسے عمرے سے فسخ کر دے کہا کرتے تھے: یہ صرف اسی قافلہ کے لیے (مخصوص) تھا جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا ۱؎۔\n§وضاحت\n۱؎ : یہ ابوذر رضی اللہ عنہ کا اپنا خیال تھا نہ کہ واقعہ، جیسا کہ پچھلی حدیثوں سے واضح ہے۔","صحیح",{"u2":"سیدنا ابوذر رضی اللہ عنہ اس شخص کے بارے میں کہا کرتے تھے جو حج کی نیت کرے پھر اسے فسخ کر کے عمرہ بنا دے، یہ صرف ان لوگوں کے لیے تھا جو رسول اللہ صلی اللہ علیہ وسلم کی معیت میں تھے۔","f2":"یہ حضرت ابوذر کا خیال تھا ورنہ اس میں کوئی حرج نہیں کہ انسان پہلے حج کی نیت سے احرام باندھے اور پھر اسے عمرے میں تبدیل کر لے۔ صحابہ کی ایک کثیر تعداد اس کی قائل ہے۔"}],[1808,"بلال بن حارث رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! حج کا (عمرے کے ذریعے) فسخ کرنا ہمارے لیے خاص ہے یا ہمارے بعد والوں کے لیے بھی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلکہ یہ تمہارے لیے خاص ہے\"۔","ضعیف",{"u2":"حارث بن بلال اپنے والد سے بیان کرتے ہیں کہ انہوں نے کہا: اے اللہ کے رسول! کیا حج کو فسخ کر دینا ہمارے لیے خاص ہے یا ہمارے بعد والوں کے لیے بھی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلکہ یہ تمہارے ہی لیے خاص ہے۔ “","f2":"یہ حدیث ضعیف ہے،اس لئے قابل استدلال نہیں۔"}],[1809,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ فضل بن عباس رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کے ساتھ پیچھے سوار تھے کہ قبیلہ خثعم کی ایک عورت آپ کے پاس فتوی پوچھنے آئی تو فضل اسے دیکھنے لگے اور وہ فضل کو دیکھنے لگی تو رسول اللہ صلی اللہ علیہ وسلم فضل کا منہ اس عورت کی طرف سے دوسری طرف پھیرنے لگے ۱؎، اس نے عرض کیا: اللہ کے رسول! اللہ تعالی کے اپنے بندوں پر (عائد کردہ)فریضہ حج نے میرے والد کو اس حالت میں پایا ہے کہ وہ بوڑھے ہو چکے ہیں، اونٹ پر نہیں بیٹھ سکتے کیا میں ان کی جانب سے حج کر لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"، اور یہ واقعہ حجۃ الوداع میں پیش آیا۔\n§وضاحت\n۱؎ : فضل بن عباس رضی اللہ عنہما خوبصورت اور جوان تھے اور وہ عورت بھی حسین تھی، اسی وجہ سے آپ صلی اللہ علیہ وسلم نے ان کا رخ دوسری طرف پھیر دیا۔","صحیح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ (ان کے بھائی) سیدنا فضل بن عباس رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سواری پر ان کے پیچھے بیٹھے ہوئے تھے کہ قبیلہ خشعم کی ایک عورت آپ صلی اللہ علیہ وسلم سے کچھ پوچھنے کو آئی تو فضل اسے دیکھنے لگے اور وہ انہیں دیکھنے لگی تو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا فضل کا چہرہ دوسری طرف پھیر دیا۔ اس عورت نے پوچھا: اے ا اللہ کے رسول! ا اللہ کا فریضہ حج اس کے بندوں میں، میرے والد کو اس حالت میں پہنچا ہے کہ وہ سواری پر ٹکنے کی سکت بھی نہیں رکھتے، تو کیا میں ان کی طرف سے حج کروں؟ آپ نے فرمایا ” ہاں “ اور یہ حجتہ الوداع کا واقعہ ہے۔","f2":"(1)جہاں کہیں کوئی خلاف شریعت عم ل(منکر) نظر آئے تو مسلمان کو چاہیے کہ بالفعل اس کو روکنے کی کوشش کرے جیسے رسول اللہ صلی اللہ علیہ وسلم نے حضرت فضل کا چہرہ پھیر کر انہیں غلط نظر سے منع فرمایا۔(2) جب کوئی شخص کسی ایسے مرض میں مبتلا ہوکہ شفا یابی بظاہر مشکل معلوم ہو تو اس کی طرف سے کوئی دوسرا شخص حج بدل کر سکتا ہے۔ لیکن اگر شفایابی کی امید ہوتو انتظار کیا جائے۔ (3)جب کوئی شخص از خود کسی کی طرف سے نائب بن جائے تو اس پر تکمیل حج لازم ہے۔(4) اس حدیث سے ثابت ہوتا ہے کہ عورت بوقت ضرورت غیر محرم مردوں کےساتھں بات چیت کر سکتی ہے۔(5)یہ حدیث [غض بصر] نگاہ نیچی رکھنے کے وجوب اور اجنبی عورت کی طرف دیکھنے کی حرمت پر دلالت کرتی ہے۔(6)عورت اپنے باپ کی طرف سے حج بدل کر سکتی ہے۔بشرطیکہ پہلے وہ اپناحج کر چکی ہو۔(7) ایک سواری پر دو آدمی بھی سوار ہو سکتے ہیں۔"}],[1810,"ابورزین رضی اللہ عنہ بنی عامر کے ایک فرد کہتے ہیں میں نے عرض کیا: اللہ کے رسول! میرے والد بہت بوڑھے ہیں جو نہ حج کی طاقت رکھتے ہیں نہ عمرہ کرنے کی اور نہ سواری پر سوار ہونے کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے والد کی جانب سے حج اور عمرہ کرو\"۔","صحیح",{"u2":"بنو عامر کے ایک شخص ابورزین نے بیان کیا کہ انہوں نے پوچھا تھا کہ اے اللہ کے رسول! میرے والد بہت بوڑھے ہیں اور حج عمرے کی طاقت نہیں رکھتے اور نہ سواری پر سوار ہو سکتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنے باپ کی طرف سے حج کرو اور عمرہ (بھی)۔ “","f2":"(1)ماں باپ سفر وغیرہ سے عاجز ہوں اور حج ان پر فرض ہوتا ہو تو اولاد کو چاہیے کہ ان کی طرف سے حج بدل کرے۔(2)اس حدیث سےیہ بھی استدلال کیا گیا ہے کہ حج کی طرح عمرہ بھی واجب ہے۔ امام احمد رحمہ اللہ سےمنقول ہے کہ عمرہ کے واجب ہونے میں اس سے بڑھ کر عمدہ اور صحیح حدیث کوئی اور نہیں ہے۔"}],[1811,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کو کہتے سنا: «لبيك عن شبرمة» \"حاضر ہوں شبرمہ کی طرف سے\" آپ صلی اللہ علیہ وسلم نے دریافت کیا: \"شبرمہ کون ہے؟\"، اس نے کہا: میرا بھائی یا میرا رشتے دار ہے، آپ صلی اللہ علیہ وسلم نے پوچھا: \"تم نے اپنا حج کر لیا ہے؟\"، اس نے جواب دیا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پہلے اپنا حج کرو پھر (آئندہ) شبرمہ کی طرف سے کرنا\"۔\n§وضاحت\n۱؎ : بعض علماء کے نزدیک حج بدل (دوسرے کی طرف سے حج کرنا) درست ہے، خواہ اپنی طرف سے حج نہ کر سکا ہو، بعض ائمہ کے نزدیک اگر وہ اپنی طرف سے حج نہیں کر سکا ہے تو دوسرے کی طرف سے حج بدل درست نہ ہو گا، اور یہی صحیح مذہب ہے، اس لئے کہ رسول اکرم صلی اللہ علیہ وسلم نے اس شخص کو جو «لبيك عن شبرمة» کہہ رہا تھا حکم دیا: «حج عن نفسك ثم حج عن شبرمة» : ’’پہلے اپنی طرف سے حج کرو پھر شبرمہ کی طرف سے حج کرو‘‘۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ایک شخص کو سنا کہ وہ کہہ رہا تھا «لبيك عن شبرمة» ” میں شبرمہ کی طرف سے حاضر ہوں۔ “ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا ” شبرمہ کون ہے؟ “ اس نے کہا کہ میرا بھائی ہے یا قریبی ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تم نے اپنی طرف سے حج کر لیا ہے؟ “ اس نے کہا، نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” (پہلے) اپنی طرف سے حج کرو، پھر شبرمہ کی طرف سے کرنا۔ “","f2":"(1) [شبرمه] شین اور را کے ضمہ کے ساتھ جب کہ باء ساکن اور میم مفتوح ہے۔ (2)حج بدل میں حاجی پہلےاپنا حج کر چکا ہو تو پھر وہ دوسرے کی طرف سے حج کر سکتا ہے ورنہ نہیں۔"}],[1812,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا تلبیہ یہ تھا: «لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك» \"حاضر ہوں اے اللہ! میں حاضر ہوں، تیرا کوئی شریک نہیں، میں حاضر ہوں، حمد و ستائش، نعمتیں اور فرماروائی تیری ہی ہے تیرا ان میں کوئی شریک نہیں\"۔ راوی کہتے ہیں: عبداللہ بن عمر تلبیہ میں اتنا مزید کہتے «لبيك لبيك لبيك وسعديك والخير بيديك والرغباء إليك والعمل» \"حاضر ہوں تیری خدمت میں، حاضر ہوں، حاضر ہوں، نیک بختی حاصل کرتا ہوں، خیر تیرے ہاتھ میں ہے، تیری ہی طرف رغبت اور عمل ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے تلبیہ کے الفاظ اس طرح تھے «لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك» ” حاضر ہوں میں، اے اللہ! حاضر ہوں۔ حاضر ہوں، تیرا کوئی شریک نہیں۔ میں حاضر ہوں۔ بیشک تمام تعریفیں اور نعمتیں تیری ہیں اور ملک بھی تیرا ہی ہے، تیرا کوئی شریک نہیں۔ “ نافع نے بیان کیا کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ اپنے تلبیہ میں اضافہ کرتے ہوئے یوں کہا کرتے تھے «لبيك لبيك لبيك وسعديك والخير بيديك والرغباء إليك والعمل» ” میں حاضر ہوں، میں حاضر ہوں، میں حاضر ہوں اور بہت سعادت مند ہوں۔ خیر اور بھلائی سب تیرے ہاتھوں میں ہے۔ ہماری سب رغبتیں اور سوال تیری طرف ہیں اور عمل بھی تیرے ہی لیے ہیں۔ “"}],[1813,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے احرام باندھا، پھر انہوں نے تلبیہ کا اسی طرح ذکر کیا جیسے ابن عمر کی حدیث میں ہے اور کہا: لوگ (اپنی طرف سے اللہ کی تعریف میں) «ذا المعارج» اور اس جیسے کلمات بڑھاتے اور نبی اکرم صلی اللہ علیہ وسلم سنتے تھے لیکن آپ ان سے کچھ نہیں فرماتے ۱؎۔\n§وضاحت\n۱؎ : نبی اکرم صلی اللہ علیہ وسلم کی یہ خاموشی اور سکوت تلبیہ کے مخصوص الفاظ پر اضافہ کے جواز کی دلیل ہے، اگرچہ افضل وہی ہے جو آپ صلی اللہ علیہ وسلم سے مرفوعاً ثابت ہے اور جس پر آپ صلی اللہ علیہ وسلم نے مداومت کی ہے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے احرام باندھا اور تلبیہ پڑھا۔ اور سیدنا ابن عمر رضی اللہ عنہ کی روایت کی مانند تلبیہ کے الفاظ بیان کیے۔ کہا کہ لوگ «ذا المعارج» اور اس طرح الفاظ زیادہ کرتے تھے۔ نبی کریم صلی اللہ علیہ وسلم انہیں سنتے اور انہیں کچھ نہ کہتے تھے («ذا المعارج» یعنی اے اللہ بلندیوں والے اور انعامات کے مالک!)۔","f2":"(1)حج اور عمرہ میں تلبیہ کہناسنت مؤکدہ ہے اگر کوئی اسے ترک کر دے گا تو سنت کے اجر و ثواب سےمحروم رہے گا۔جبکہ بعض ائمہ اسے واجب کہتے ہیں۔اسی لیے اس کے ترک پر ان کےنزدیک دم (قربانی)واجب ہے۔تاہم یہ دوسرا موقف صحیح نہیں لگتا اس لیے کہ ترک تلبیہ سے کسی رکن کاترک لازم نہیں آتا اس لیے اوکان حج کی ادائیگی تلبیے کے قائم مقام ہو جائے گی۔تلبیہ کے الفاظ میں افضل یہی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے اپنے الفاظ ہی پر اکتفا واقتصار کیا جائے کیونکہ آپ نے انہی ب‎پر مداو مت اختیار فرمائی ہے۔ تاہم اگر کوئی (صحیح المعنی الفاظ کا) اضافہ کرے تو بھی مباح ہے کیونکہ نبی صلی اللہ علیہ وسلم نے بعض صحابہ کو مختلف الفاظ سے تلبیہ پکارتے سناتو آپ خاموش رہے اور انکار نہیں فرمایا۔(عون المعبود) (2) یہ جلیل الشان کلمہ اللہ تبارک وتعالیٰ کی توحید کی تمام انواع پر مشتمل ہے۔یعنی توحید الوہیت توحید ربوبیت اورتوحید اسماء و صفات۔اور بندہ اس کے تکرار سےاپنی عبدیت کا اظہار کرتا ہے۔"}],[1814,"سائب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس جبرائیل آئے اور مجھے حکم دیا کہ میں اپنے صحابہ ۱؎ اور ساتھ والوں کو «الإهلال» یا فرمایا «التلبية» میں آواز بلند کرنے کا حکم دوں\" ۲؎۔\n§وضاحت\n۱؎ : اس سے پتہ چلا کہ مردوں کے لئے تلبیہ میں آواز بلند کرنا مستحب ہے، «أصحابي» کی قید سے اس حکم سے عورتیں خارج ہو گئی ہیں ان کے لئے بہتر یہی ہے کہ بلند آواز سے تلبیہ نہ پکاریں۔ ۲؎ : اہلال اور تلبیہ دونوں ایک ہی معنی میں ہے، راوی کو شک ہے کہ آپ صلی اللہ علیہ وسلم نے اہلال کہا یا تلبیہ، مراد یہ ہے کہ دونوں میں سے آپ صلی اللہ علیہ وسلم نے کوئی ایک ہی لفظ کہا۔","صحیح",{"u2":"جناب خلاد بن سائب انصاری اپنے والد سے نقل کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرے پاس جبرائیل علیہ السلام آئے اور مجھے حکم دیا کہ میں اپنے صحابہ اور دوسرے ساتھ والوں کو حکم دوں کہ تلبیہ کہنے میں اپنی آوازیں اونچی رکھیں۔ “ راوی کہتا ہے کہ آپ کے الفاظ «بالإهلال» تھے یا «بالتلبية» (معنی ایک ہی ہیں)۔","f2":"(1)اس حدیث سے ثابت ہوتا ہے کہ جبرئیل ﷩ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں وحی قرآن کے بغیر بھی حاضر ہواکرتے تھے اور اس وقت الحکمۃ کی وحی ہوتی لہٰذا حدیث رسول صلی اللہ علیہ وسلم بھی وحی [منزل من الله] اور واجب الاتباع ہے۔(2) عام محدثین نے اس حدیث سے یہ استدلال کیا ہے کہ تلبیہ کہنے میں آواز اونچی رکھنامستحب ہے مگر عورتیں اس سےمستثنی ہیں۔"}],[1815,"فضل بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تلبیہ پکارا یہاں تک کہ آپ نے جمرہ عقبہ کی رمی کر لی ۱؎۔\n§وضاحت\n۱؎ : «حتى رمى جمرة العقبة» سے احمد اور اسحاق نے استدلال کیا ہے کہ تلبیہ کہنا جمرہ عقبہ کی رمی پوری کر لینے کے بعد موقوف کیا جائے گا، لیکن صحیح بخاری اور صحیح مسلم کی روایت میں «لم يزل يلبي حتى بلغ الجمرة» کے الفاظ آئے ہیں جس سے جمہور علماء نے استدلال کیا ہے کہ جمرہ عقبہ کی رمی کی پہلی کنکری کے ساتھ ہی تلبیہ بند کر دیا جائے گا۔","صحیح",{"u2":"سیدنا فضل بن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (دسویں ذوالحجہ کو) جمرہ عقبہ کو کنکریاں مارنے تک تلبیہ کہتے رہے۔","f2":"تلبیہ احرام باندھنے کے وقت سے شروع ہو کر دسویں تاریخ جمرہ عقبہ کو کنکریاں مارنے تک ہی ہے جیسے کہ صحیحین کی روایت میں ہے: آپ صلی اللہ علیہ وسلم تلبیہ کہتے رہے حتی کہ جمرہ کے پاس پہنچ گئے۔ (صحیح البخاری الحج حدیث:1543 1544 و صحیح مسلم الحج حدیث:1281)"}],[1816,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ہم صبح کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منی سے عرفات کی طرف نکلے ہم میں سے کچھ لوگ تلبیہ پکار رہے تھے اور کچھ «الله أكبر» کہہ رہے تھے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے، کہتے ہیں کہ ہم (نویں تاریخ کو) صبح کے وقت منیٰ سے عرفات کی طرف روانہ ہوئے تو کچھ لوگ ہم میں سے تلبیہ پکار رہے تھے اور کچھ تکبیر۔","f2":"تلبیہ کےساتھ ساتھ تکبیر و تسبیح اور بعض مناسب دعائیں بھی مباح ہیں۔"}],[1817,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عمرہ کرنے والا حجر اسود کا استلام کرنے تک لبیک پکارے\" ۱؎۔ ابوداؤد کہتے ہیں: اسے عبدالملک بن ابی سلیمان اور ہمام نے عطاء سے، عطاء نے ابن عباس رضی اللہ عنہما سے موقوفاً روایت کیا ہے۔\n§وضاحت\n۱؎ : یہ حدیث سندا ضعیف ہے، مگر بہت سارے علماء کا یہی قول ہے، بعض لوگ کہتے ہیں: مکہ کے مکانات پر نظر پڑتے ہی تلبیہ بند کر دے، لیکن صحیح بات یہ ہے کہ خانہ کعبہ پر نظر پڑتے ہی تلبیہ بند کر دے، اور یہ دعا پڑھے: «اللهم أنت السلام ومنك السلام الخ» ۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم فرمایا ” عمرہ کرنے والا حجر اسود کو ہاتھ لگانے (یا بوسہ دینے) تک تلبیہ کہتا رہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو عبدالملک بن ابی سلیمان اور ہمام نے عطاء سے انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے موقوف روایت کیا ہے۔","f2":"یہ روایت مرفوع نہیں موقوف ہی صحیح ہےاو رحکم اور عمل اسی پر ہے کہ عمرہ میں حجر اسود کا استلام کرنے تک تلبیہ ہے اس کےبعد نہیں۔"}],[1818,"اسماء بنت ابی بکر رضی اللہ عنہما کہتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کو نکلے، جب ہم مقام عرج میں پہنچے تو رسول اللہ صلی اللہ علیہ وسلم اترے، ہم بھی اترے، ام المؤمنین عائشہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کے پہلو میں، اور میں اپنے والد کے پہلو میں بیٹھی۔ اس سفر میں ابوبکر رضی اللہ عنہ اور رسول اللہ صلی اللہ علیہ وسلم دونوں کے سامان اٹھانے کا اونٹ ایک ہی تھا جو ابوبکر رضی اللہ عنہ کے غلام کے پاس تھا، ابوبکر رضی اللہ عنہ اس انتظار میں بیٹھے کہ وہ غلام آئے جب وہ آیا تو اس کے ساتھ اونٹ نہ تھا، انہوں نے پوچھا: تیرا اونٹ کہاں ہے؟ اس نے جواب دیا کل رات وہ گم ہو گیا، ابوبکر رضی اللہ عنہ بولے: ایک ہی اونٹ تھا اور وہ بھی تو نے گم کر دیا، پھر وہ اسے مارنے لگے اور رسول اللہ صلی اللہ علیہ وسلم مسکرا رہے تھے اور فرما رہے تھے: \"دیکھو اس محرم کو کیا کر رہا ہے؟\" (ابن ابی رزمہ نے کہا) \"رسول اللہ صلی اللہ علیہ وسلم اس سے زیادہ کچھ نہیں فرما رہے تھے کہ دیکھو اس محرم کو کیا کر رہا ہے اور آپ مسکرا رہے تھے۔","حسن",{"u2":"دختر ابوبکر رضی اللہ عنہ سیدہ اسماء رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حج کے لیے نکلے۔ جب ہم مقام عرج پر پہنچے تو رسول اللہ صلی اللہ علیہ وسلم نے پڑاؤ کیا اور ہم بھی اتر پڑے۔ سیدہ عائشہ رضی اللہ عنہا ا رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھیں اور میں اپنے والد (سیدنا ابوبکر رضی اللہ عنہ) کے پاس بیٹھی۔ ابوبکر رضی اللہ عنہ اور رسول اللہ صلی اللہ علیہ وسلم کے سامان سفر کا جانور ایک ہی تھا جو سیدنا ابوبکر رضی اللہ عنہ کے ایک غلام کی تحویل میں تھا۔ سیدنا ابوبکر رضی اللہ عنہ بیٹھے اس کا انتظار کر رہے تھے کہ وہ آ جائے۔ چنانچہ جب وہ آیا تو وہ اونٹ اس کے ساتھ نہیں تھا۔ انہوں نے پوچھا: تیرا اونٹ کہاں ہے؟ اس نے کہا: وہ آج رات گم ہو گیا ہے۔ ابوبکر رضی اللہ عنہ نے کہا: صرف ایک اونٹ اور وہ بھی تو نے گم کر دیا؟ اور پھر اسے مارنے لگے اور رسول اللہ صلی اللہ علیہ وسلم مسکراتے رہے اور فرمانے لگے: ” دیکھو اس محرم کو، کیا کر رہا ہے؟ “ ابن ابی رزمہ کے الفاظ ہیں «ف يزيد رسول الله ***» یعنی رسول اللہ صلی اللہ علیہ وسلم نے اس سے زیادہ نہ کہا کہ ” دیکھو اس محرم کو کیا کر رہا ہے! “ اور مسکراتے رہے۔","f2":"(1)احرام کی حالت میں غلط طور پر جھگڑا کرنا ناجائز ہے اور حج کےعمل کو ناقص کر دیتا ہے البتہ کسی ماتحت کو اس کی نامعقولیت پر تادیب کرنے اور سزا دینے میں کوئی حرج نہیں۔اگر اس سے بھی پرہیز ہو تو زیادہ بہتر ہے۔(2)عرج:جیم کے فتح اور راء کے سکون کے ساتھ مدینہ سےمکہ کےراستے پر تقریباً 90 میل کی مسافت پر ایک بستی ہے۔"}],[1819,"یعلی بن امیہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ جعرانہ میں تھے، اس کے بدن پر خوشبو یا زردی کا نشان تھا اور وہ جبہ پہنے ہوئے تھا، پوچھا: اللہ کے رسول! آپ مجھے کس طرح عمرہ کرنے کا حکم دیتے ہیں؟ اتنے میں اللہ تعالی نے نبی اکرم صلی اللہ علیہ وسلم پر وحی نازل کی، جب وحی اتر چکی تو آپ نے فرمایا: \"عمرے کے بارے میں پوچھنے والا کہاں ہے؟\"فرمایا: \"خلوق کا نشان، یا زردی کا نشان دھو ڈالو، جبہ اتار دو، اور عمرے میں وہ سب کرو جو حج میں کرتے ہو\"۔","صحیح",{"u2":"جناب صفوان اپنے والد یعلیٰ بن امیہ رضی اللہ عنہ سے روایت کرتے ہیں کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جبکہ آپ مقام جعرانہ میں تھے اور اس آدمی پر خلوق خوشبو کا اثر تھا (جو کہ زغفران وغیرہ سے بنی ہوتی ہے) یا کہا زرد رنگ کی خوشبو تھی۔ اور وہ جبہ پہنے ہوئے تھا۔ اس نے کہا: اے ا اللہ کے رسول! آپ مجھے کیا ارشاد فرماتے ہیں کہ میں اپنے عمرے میں کیسے کروں؟ تو ا اللہ تبارک و تعالیٰ نے نبی کریم صلی اللہ علیہ وسلم پر وحی نازل فرمائی۔ جب آپ صلی اللہ علیہ وسلم سے یہ کیفیت دور ہوئی تو دریافت کیا: ” وہ عمرے کے متعلق پوچھنے والا کہاں ہے؟ “ آپ صلی اللہ علیہ وسلم نے اس نے فرمایا ” خلوق خوشبو دھو ڈالو۔ “ یا فرمایا ” زرد رنگ دھو ڈالو جبہ اتار دو اور اپنے عمرے میں وہی کچھ کرو جو تم اپنے حج میں کرتے ہو۔ “","f2":"(1) جعرانہ جیم کےکسرہ اورعین کےسکون کےساتھ یاجیم اور عین دونوں کے کسرہ اور راء مشدد کےساتھ۔مکہ سے مدینہ آنے والےراستے سے دائیں جانب کچھ دور ہٹ کر ایک منزل کا نام ہے۔یہاں آپ نے حنین کا مال غنیمت تقسیم فرمایت تھا یہیں سے احرام باندھ کر ایک عمرہ کیا تھا۔(2)احرام باندھتے وقت خوشبو لگانا جائز ہے خواہ بعدازاں اس کا اثر بھی باقی رہے۔مگر زعفران اورز ردرنگ یک خوشبو عام حالات میں بھی ممنوع ہے تو احرام میں احرم میں زیادہ ہی منع ہے۔(3)مرد کےلیے سلےہوئے لباس میں احرام نہیں صرف دو چادریں ہونی چاہئیں۔(4)لباس اتارتے ہوئے یا اتفاقاً سر پر کپڑا آپڑے تو اس میں کوئی حرج نہیں۔ (5) حج اور عمرے کے احرم کے احکام ایک ہی ہیں۔مزید یہ بھی ثابت ہوا کہ ممنوعات سے بچنا بھی ایک عمل ہوتا ہے۔ (6) شریعت سراسر منزل من اللہ اور وحی شدہ ہے۔ ﴿ وَما يَنطِقُ عَنِ الهَوىٰ* إِن هُوَ إِلّا وَحىٌ يوحىٰ﴾ (سورة النجم:3، 4)"}],[1820,"اس سند سے بھی یعلی سے یہی قصہ مروی ہے البتہ اس میں یہ ہے کہ اس سے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اپنا جبہ اتار دو\"، چنانچہ اس نے اپنے سر کی طرف سے اسے اتار دیا، اور پھر راوی نے پوری حدیث بیان کی۔","صحیح",{"u2":"سیدنا یعلیٰ بن امیہ رضی اللہ عنہ یہ قصہ روایت کرتے ہوئے کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اس سے فرمایا ” اپنا جبہ اتار دو۔ “ چنانچہ اس نے اسے اپنے سر کی طرف سے اتار دیا۔ اور حدیث بیان کی۔","f2":"شیخ البانی فرماتے ہیں کہ یہ روایت صحیح ہےالبتہ [من راسه] اس نےاسے اپنے سر کی طرف سے اتاراکے الفاظ منکر ہیں۔"}],[1821,"اس سند سے بھی یعلی بن منیہ ۱؎ سے یہی حدیث مروی ہے البتہ اس میں یہ الفاظ ہیں: «فأمره رسول الله صلی اللہ علیہ وسلم أن ينزعها نزعا ويغتسل مرتين أو ثلاثا» یعنی \"رسول اللہ صلی اللہ علیہ وسلم نے اسے حکم دیا کہ وہ اسے اتار دے اور غسل کرے دو بار یا تین بار آپ نے فرمایا \"پھر راوی نے پوری حدیث بیان کی۔\n§وضاحت\n۱؎ : منیہ یعلی کی والدہ ہیں ان کے والد کا نام امیّہ ہے۔","صحیح",{"u2":"سیدنا یعلیٰ ابن منیہ رضی اللہ عنہ نے یہ خبر روایت کی اس میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے حکم دیا کہ اسے اتار دو (جبہ کو) اور غسل کرو دو بار یا تین بار۔ اور حدیث بیان کی۔","f2":"(1) راوی حدیث وہی تعالیٰ ہیں جن کی روایات اوپر آئی ہیں۔ ان کےوالد کانام امیہ اور والدہ کا نام منیہ ہے۔(2)شریعت کا حکم جان لینے کے بعد اس میں پس وپیش کا کوئی مطلب نہیں۔ (3)بھولے سے مذکورہ غلطیوں پر فدیہ لازم نہیں آتا۔"}],[1822,"یعلی بن امیہ سے روایت ہے کہ ایک آدمی جعرانہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اس نے عمرہ کا احرام اور جبہ پہنے ہوئے تھا، اور اس کی داڑھی و سر کے بال زرد تھے، اور راوی نے یہی حدیث بیان کی۔","صحیح",{"u2":"جناب صفوان اپنے والد یعلیٰ بن امیہ رضی اللہ عنہ سے نقل کرتے ہیں کہ جعرانہ مقام پر ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا، اس نے عمرے کا احرام باندھا ہوا تھا، جبہ پہنے ہوئے تھا اور اس کی ڈاڑھی اور سر میں زرد رنگ کی خوشبو لگی ہوئی تھی۔ اور مذکورہ بالا حدیث بیان کی۔"}],[1823,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: محرم کون سے کپڑے پہنے؟ آپ نے فرمایا: \"نہ کرتا پہنے، نہ ٹوپی، نہ پائجامہ، نہ عمامہ (پگڑی)، نہ کوئی ایسا کپڑا جس میں ورس ۱؎ یا زعفران لگا ہو، اور نہ ہی موزے، سوائے اس شخص کے جسے جوتے میسر نہ ہوں، تو جسے جوتے میسر نہ ہوں وہ موزے ہی پہن لے، انہیں کاٹ ڈالے تاکہ وہ ٹخنوں سے نیچے ہو جائیں ۲؎\"۔\n§وضاحت\n۱؎ : ایک قسم کی خوشبو دار گھاس ہے جس سے کپڑے وغیرہ رنگے جاتے ہیں۔ ۲؎ : امام احمد کے نزدیک خف (چمڑے کا موزہ) کاٹنا ضروری نہیں ، دیگر ائمہ کے نزدیک کاٹنا ضروری ہے، دلیل ان کی یہی حدیث ہے، اور امام احمد کی دلیل ابن عباس رضی اللہ عنہما کی وہ حدیث ہے جس میں کاٹنے کا ذکر نہیں ہے، جب کہ وہ میدان عرفات کے موقع کی حدیث ہے، یعنی ابن عمر رضی اللہ عنہما کی اس حدیث کی ناسخ ہے، اور ورس اور زعفران سے منع اس لئے کیا گیا کہ اس میں خوشبو ہوتی ہے، یہی حکم ہر اس رنگ کا ہے جس میں خوشبو ہو۔","صحیح",{"u2":"جناب سالم اپنے والد (سیدنا عبداللہ بن عمر رضی اللہ عنہ) سے بیان کرتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ محرم کون سے کپڑے نہ پہنے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” قمیص، ٹوپی دار کرتا، شلوار، پگڑی یا ایسا کپڑا جس کو ورس یا زعفران لگا ہو نہ پہنے اور موزے بھی نہ پہنے، الا یہ کہ کسی کے پاس جوتے نہ ہوں۔ جس کے پاس جوتے نہ ہوں وہ موزے پہن لے مگر انہیں کاٹ لے حتیٰ کہ ٹخنوں سے نیچے ہو جائیں۔ “"}],[1824,"اس سند سے ابن عمر رضی اللہ عنہما سے اسی مفہوم کی حدیث مرفوعاً مروی ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی روایت کرتے ہیں۔","f2":"(1)عورت کے لیے احرام کی چادریں پہننا ضروری نہیں۔ بلکہ وہ شلوار قمیص اور دو پٹے اور پردے ہی میں احرام باندھے گی۔ البتہ خوشبو وہ بھی استعمال نہیں کر سکتی بالخصوص ورس اور زعفران۔اسی طرح دستانے بھی نہیں پہن سکتی۔البتہ جرابیں یا موزے نہ صرف یہ کہ وہ پہن سکتی ہیں بلکہ ان کا پہنا ان کے لیے بہتر ہے کیونکہ ان میں زیادہ پردہ ہے۔(2)مردوں کے لیے صحیح قول کےمطابق موزوں کا پہننا بھی جائز ہےخواہ وہ کٹے ہوئے نہ بھی ہوں۔جبکہ جمہور کی رائے یہ ہے کہ انہیں کاٹ لے لیکن صحیح بات یہ ہے کہ جب جوتے نہ ہوں تو موزوں کا کاٹنا لازم نہیں ہے کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے لوگوں کو عرفہ میں خطبہ دیتے ہوئے ارشاد فرمایا تھا: جس کے پاس جوتے نہ ہوں تو وہ موزے پہن لے اور جس کے پاس تہبند نہ ہو تو وہ شلوار پہن لے۔ (صحیح البخاری جزاء الصید حدیث:1841 وصحیح مسلم الحج حدیث:1178) اس حدیث میں آپ نے موزے کاٹنے کا حکم نہیں دیا تو اس سے معلوم ہوا کہ جس حدیث میں موزے کاٹنے کاحکم ہے وہ ابتدائے احرام کاتھا اور دوسرا حکم عرفہ کے دن کا ہے۔اس سے یہ بات ثابت ہوئی کہ کاٹنے کا حکم منسوخ ہے۔"}],[1825,"اس سند سے بھی ابن عمر رضی اللہ عنہما سے اسی مفہوم کی حدیث مرفوعاً مروی ہے، راوی نے البتہ اتنا اضافہ کیا ہے کہ محرم عورت منہ پر نہ نقاب ڈالے اور نہ دستانے پہنے ۱؎۔ ابوداؤد کہتے ہیں: حاتم بن اسماعیل اور یحیی بن ایوب نے اس حدیث کو موسی بن عقبہ سے، اور موسی نے نافع سے اسی طرح روایت کیا ہے جیسے لیث نے کہا ہے، اور اسے موسی بن طارق نے موسی بن عقبہ سے ابن عمر پر موقوفاً روایت کیا ہے، اور اسی طرح اسے عبیداللہ بن عمر اور مالک اور ایوب نے بھی موقوفاً روایت کیا ہے، اور ابراہیم بن سعید المدینی نے نافع سے نافع نے ابن عمر رضی اللہ عنہما سے اور ابن عمر نے نبی اکرم صلی اللہ علیہ وسلم سے مرفوعاً روایت کیا ہے کہ \"محرم عورت نہ تو منہ پر نقاب ڈالے اور نہ دستانے پہنے\"۔ ابوداؤد کہتے ہیں: ابراہیم بن سعید المدینی ایک شیخ ہیں جن کا تعلق اہل مدینہ سے ہے ان سے زیادہ احادیث مروی نہیں، یعنی وہ قلیل الحدیث ہیں۔\n§وضاحت\n۱؎ : احرام کی حالت میں عورتوں کو اپنے چہرے پر’ ’ نقاب ‘‘ لگانا منع ہے، مگر حدیث میں جس نقاب کا ذکر ہے وہ چہرے پر باندھا جاتا تھا، برصغیر ہند و پاک کے موجودہ برقعوں کا ’’ نقاب‘‘ چادر کے پلو کی طرح ہے جس کو ازواج مطہرات مردوں کے گزرنے کے وقت چہرے پر لٹکا لیا کرتی تھیں (دیکھئے حدیث نمبر: ۱۸۳۳)، اس لئے اس نقاب کو بوقت ضرورت عورتیں چہرے پر لٹکا سکتی ہیں، اور چوں کہ اس وقت حج میں ہر وقت اجنبی (غیر محرم) مردوں کا سامنا پڑتا ہے، اس لئے ہر وقت اس نقاب کو چہرے پر لٹکائے رکھ سکتی ہیں۔","صحیح",{"u2":"جناب نافع نے سیدنا ابن عمر رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی روایت کیا ہے اور مزید کہا ہے ” احرام والی عورت نقاب پہنے نہ دستانے پہنے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ حدیث حاتم بن اسمٰعیل اور یحییٰ بن ایوب نے موسیٰ بن عقبہ سے، انہوں نے نافع سے اسی طرح روایت کی ہے جیسے کہ لیث نے روایت کی ہے۔ مگر اس کو موسیٰ بن طارق نے موسیٰ بن عقبہ سے سیدنا ابن عمر رضی اللہ عنہ پر موقوفاً روایت کیا ہے۔ اور ایسے ہی عبیداللہ بن عمر، مالک اور ایوب نے بھی موقوفاً روایت کیا ہے جبکہ ابراہیم بن سعید مدنی نے نافع سے، انہوں نے ابن عمر رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کیا کہ ” احرام والی نقاب لگائے نہ دستانے پہنے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابراہیم بن سعید مدنی اہل مدینہ میں سے صرف ایک شیخ (عالم) ہیں کوئی زیادہ صاحب حدیث نہیں ہیں۔ (ان کی روایت آگے آ رہی ہے)۔","f2":"حدیث میں محرم عورت کے نقاب ڈالنے سےمنع کیا گیاہے۔ اس نقاب سے ایک خاص نقاب مراد ہے جو کہ ناک پر یا آنکھ کےنیچے باندھا جاتا ہے۔ اس سےمراد وہ نقاب نہیں ہے جو آج کل معروف ہے اور جسےچہرے کے پردے کےلیے استعمال کیاجاتا ہے۔ بعض لوگ اس سے موجودہ نقاب مراد لے کر محرم عورت کوچہرہ ڈھانپنے سے منع کرتے ہیں۔لیکن یہ بات صحیح نہیں۔ جس نقاب سےمنع کیا گیا ہے اس کا تعلق حجاب یا چہرے کے پردے سے نہیں یہ پردہ تواحرام کی حالت میں ہو یا غیر احرام کی ہر وقت ضروری ہے۔ محرم عورت کو ایک مخصوص قسم کےنقاب سے روکا گیا ہے جو کہ صرف ناک یاآنکھ کے نیچے باندھا جاتا ہے۔ جس سےمنع کر دیا گیا۔ اس ممانعت کا تعلق حجاب والے نقاب سے نہیں۔ اس لیے اس کا تو حکم حالت احرام میں بھی ہے۔ جیسا کہ موطا امام مالک میں روایت ہے فاطمہ بنت منذر بیان کرتی ہیں کہ ہم حالت احرام میں اپنے چہرے ڈھانپا کرتی تھیں اور اسماء بن ابی بکر صدیق رضی اللہ عنہ بھی ہمارے ساتھ ہوئی تھیں۔ (موطا امام مالک:1/328)نیز مستدرک حاکم میں بھی انہی سےروایت ہے کہ ہم مردوں سے اپنے چہروں کا پردہ کرتی تھیں۔(مستدرک حاکم:1/454) علاوہ ازین سیدہ عائشہ رضی اللہ عنہا سےمروی ہے کہ محرم عورت نہ نقاب ڈالے اور نہ گھونگھٹ نکالے البتہ سرکی طرف سے چہرے پر کپڑا لٹکالے۔ (السنن الکبری للبیہقی:5/47) ان تمام موقوف روایات سے معلوم ہواکہ آپ نے خاص قسم کے نقاب سےمنع کیا ہے نہ کہ بالکل ہی پردہ کرنے سےمنع کیا ہے۔اس لیے ہر خاتون کو چاہیے کہ وہ اس معاملے میں اپنے رب سے ڈرے اور فیشن ایبل اور ایسے تمام نقابون سے بچے جو بے حجابی کو فروغ دیتے ہوں۔"}],[1826,"عبداللہ بن عمر رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"محرم عورت نہ تو منہ پر نقاب ڈالے اور نہ دستانے پہنے\"۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” احرام والی عورت نہ نقاب لگائے اور نہ دستانے پہنے۔ “"}],[1827,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا کہ آپ نے عورتوں کو حالت احرام میں دستانے پہننے، نقاب اوڑھنے، اور ایسے کپڑے پہننے سے جن میں ورس یا زعفران لگا ہو منع فرمایا، البتہ ان کے علاوہ جو رنگین کپڑے چاہے پہنے جیسے زرد رنگ والے کپڑے، یا ریشمی کپڑے، یا زیور، یا پائجامہ، یا قمیص، یا کرتا، یا موزہ۔ ابوداؤد کہتے ہیں: اس حدیث کو عبدہ بن سلیمان اور محمد بن سلمہ نے ابن اسحاق سے ابن اسحاق نے نافع سے حدیث «وما مس الورس والزعفران من الثياب» تک روایت کیا ہے اور اس کے بعد کا ذکر ان دونوں نے نہیں کیا ہے۔","حسن صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ آپ نے عورتوں کو احرام میں دستانے پہننے اور نقاب لگانے سے منع فرمایا ہے۔ اور ایسے لباس سے بھی جسے ورس (ایک رنگ دار بوٹی) اور زعفران لگی ہو۔ ان کے علاوہ جو لباس اور رنگ چاہے پہن لے (یعنی) عصفر (زرد) رنگ ہو یا ریشم، یا زیور یا شلوار یا قمیص یا موزہ۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو عبدہ بن سلیمان اور محمد بن سلمہ، محمد بن اسحٰق سے اور وہ نافع سے روایت کرتے ہیں مگر صرف اس حصے تک (یعنی) «و مس الورس والزعفران من الثياب» بعد والا حصہ یہ دونوں روایت نہیں کرتے۔","f2":"امام ابوداؤد بیان کرنا چاہتے ہیں کہ اس روایت کے آخر میں مذکورہ تفصیل ذکر کرنے میں یعقوب کے والد ابراہیم بن سعد منفرد ہیں اور گویا یہ آخری حصہ حدیث میں درج ہے (بذل المجہود)جبکہ عصفر (زرد)رنگ کا استعمال اورموزوں کاپہننا (بلاعذر) صحیح تر احادیث میں منع آیا ہے۔"}],[1828,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما نے سردی محسوس کی تو انہوں نے کہا: نافع! میرے اوپر کپڑا ڈال دو، میں نے ان پر برنس ڈال دی، تو انہوں نے کہا: تم میرے اوپر یہ ڈال رہے ہو حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے محرم کو اس کے پہننے سے منع فرمایا ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ انہیں سردی لگی تو انہوں نے کہا: اے نافع! مجھ پر کوئی کپڑا ڈال دو۔ چنانچہ میں (نافع) نے ان پر ایک برنس (ایک قمیص جس کا ایک حصہ بطور ٹوپی استعمال ہوتا ہے) ڈال دی۔ تو وہ بولے مجھ پر یہ ڈال رہا ہے حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے محرم کو اس کے پہننے سے منع فرمایا ہے۔","f2":"بزنس باقاعدہ پہننا منع ہے ویسے اوڑھ لینے میں کوئی حرج نہیں مگر حضرت ابن عمر کا تقوی اور جذبہ اتباع رسول صلی اللہ علیہ وسلم اس قدر شدید تھا کہ انہوں نے اسے عام صورت میں بھی اوڑھنے سے گزیر کا اظہار فرمایا۔"}],[1829,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"پاجامہ وہ پہنے جسے ازار نہ ملے اور موزے وہ پہنے جسے جوتے نہ مل سکیں\"۔ (ابوداؤد کہتے ہیں یہ اہل مکہ کی حدیث ہے ۱؎ اس کا مرجع بصرہ میں جابر بن زید ہیں ۲؎ اور جس چیز کے ساتھ وہ منفرد ہیں وہ سراویل کا ذکر ہے اور اس میں موزے کے سلسلہ میں کاٹنے کا ذکر نہیں) ۔\n§وضاحت\n۱؎ : کیونکہ سلیمان بن حرب مکی ہیں اور مصنف نے انہیں سے روایت کی ہے۔ ۲؎ : کیونکہ اس سند کا محور جن پر یہ سند گھومتی ہے جابر بن زید ہیں اور وہ بصری ہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے ہوئے سنا ” جسے تہبند نہ ملے وہ شلوار پہن لے اور جس کے پاس جوتے نہ ہوں وہ موزے پہن لے۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: یہ اہل مکہ کی روایت ہے اور اس کا محور اہل بصرہ میں سے جابر بن زید رضی اللہ عنہ ہیں۔ اس روایت میں انفرادیت یہ ہے کہ اس میں «سراويل» (شلوار) کا ذکر ہے اور موزوں کے بارے میں کاٹنے کی ہدایت نہیں ہے۔","f2":"عذرکی صورت میں شلوار اور موزوں پہننا جائز ہے اور اس میں کوئی فدیہ وغیرہ لازم نہیں آتا۔موزون سے متعلق بحث حدیث 1823 کے فوائد میں گزر چکی ہے۔"}],[1830,"عائشہ بنت طلحہ کا بیان ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا نے ان سے بیان کیا ہے کہ وہ کہتی ہیں کہ ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ مکہ کی طرف نکلتے تو ہم اپنی پیشانی پر خوشبو کا لیپ لگاتے تھے جب پسینہ آتا تو وہ خوشبو ہم میں سے کسی کے منہ پر بہہ کر آ جاتی رسول اللہ صلی اللہ علیہ وسلم اس کو دیکھتے لیکن منع نہ کرتے ۱؎۔\n§وضاحت\n۱؎ : یہ خوشبو احرام سے پہلے کی ہوتی تھی اس لئے منع کرنے کی کوئی وجہ نہیں تھی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ ہم نبی کریم صلی اللہ علیہ وسلم کی معیت میں مکہ کو جاتیں تو احرام کے وقت اپنی پیشانیوں پر خوشبودار مرکب خوشبو کا ضماد کر لیا کرتی تھیں۔ جب پسینہ آتا تو وہ ہمارے چہروں پر بہہ آتا تھا، نبی کریم صلی اللہ علیہ وسلم اسے دیکھتے تو اس سے منع نہ فرماتے تھے۔","f2":"(1)احرام کےبعد کسی قسم کی خوشبو لگانا جائز نہیں البتہ احرام باندھتے وقت خوشبو لگانا مسنون ہے۔ اگر اس کا اثر بھی باقی رہے تو کوئی حرج نہیں۔ (2)اس حدیث سے عورتوں کے پاؤڈر قسم کی چیزوں کے لگانے کی بھی رخصت ثابت ہوتی ہے۔"}],[1831,"محمد بن اسحاق کہتے ہیں میں نے ابن شہاب سے ذکر کیا تو انہوں نے کہا: مجھ سے سالم بن عبداللہ نے بیان کیا ہے کہ عبداللہ بن عمر رضی اللہ عنہما ایسا ہی کرتے تھے یعنی محرم عورت کے موزوں کو کاٹ دیتے ۱؎، پھر ان سے صفیہ بنت ابی عبید نے بیان کیا کہ ان سے ام المؤمنین عائشہ رضی اللہ عنہا نے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے موزوں کے سلسلے میں عورتوں کو رخصت دی ہے تو انہوں نے اسے چھوڑ دیا۔\n§وضاحت\n۱؎ : اس باب کی پہلی روایت کے عموم سے ابن عمر رضی اللہ عنہما نے یہ سمجھا تھا کہ یہ حکم مرد اور عورت دونوں کو شامل ہے اسی لئے وہ محرم عورت کے موزوں کو کاٹ دیتے تھے، بعد میں جب انہوں نے عائشہ رضی اللہ عنہا والی روایت سنی تو اپنے اس فتوی سے رجوع کر لیا۔","حسن",{"u2":"جناب سلام بن عبداللہ اپنے والد سیدنا عبداللہ بن عمر رضی اللہ عنہ کے متعلق بیان کرتے ہیں کہ وہ احرام والی عورت کو کہا کرتے تھے کہ اپنے موذے کاٹ لے۔ پھر (ان کی زوجہ) صفیہ بنت ابی عبید نے انہیں بیان کیا کہ سیدہ عائشہ رضی اللہ عنہا ا نے اس کو بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے عورتوں کو موزے پہننے کی رخصت دی ہے۔ تو وہ اپنی بات سے رک گئے۔","f2":"(1)یہ رخصت عورتوں کےعلاوہ مردوں کے بھی حاصل ہے مگر بحالت عذر(2) محب رسول کے لیے ممکن ہی نہیں کہ اسے نبی صلی اللہ علیہ وسلم کی طرف سے کوئی ہدایت ملے اور پھر وہ اپنی رائے پر اصرار کرے۔"}],[1832,"براء رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے حدیبیہ والوں سے صلح کی تو آپ نے ان سے اس شرط پر مصالحت کی کہ مسلمان مکہ میں جلبان السلاح کے ساتھ ہی داخل ہوں گے ۱؎ تو میں نے ان سے پوچھا: «جلبان السلاح» کیا ہے؟ انہوں نے کہا: «جلبان السلاح» میان کا نام ہے اس چیز سمیت جو اس میں ہو۔\n§وضاحت\n۱؎ : یعنی ان کی تلواریں میان کے اندر ہی رہیں گی۔","صحیح",{"u2":"سیدنا براء رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے حدیبیہ والوں سے صلح کی تھی تو اس بات پر صلح کی تھی کہ یہ لوگ (مسلمان) مکہ میں اس حالت میں داخل ہوں گے کہ ان کے ہتھیار ان کے میانوں میں ہوں گے۔ (غالباً) شعبہ نے ابواسحٰق سے پوچھا کہ «جلبان السلاح» کیا ہوتا ہے؟ انہوں نے کہا چمڑے کا وہ تھیلا جس میں ہتھیار رکھا جاتا ہے۔","f2":"اللہ عزوجل محدثین کو کروٹ کروٹ اپنی رحمتوں سے نوازے کسی خوبصورت انداز میں ایک تاریخی واقعہ سے فقہی مسئلہ استنباط کیا ہے۔کہ محرم کے لئے جائز ہے کہ اپنے ہتھیار رکھے۔اس سے بڑھ کر اور کیا دلیل ہوگی ان کے فقیہ ہونے کی کتب ا حادیث کا تمام ذخیرہ اس طائفہ منصورہ کے فقیہ ہونے کی بین دلیل ہے۔"}],[1833,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ سوار ہمارے سامنے سے گزرتے اور ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ احرام باندھے ہوتے، جب سوار ہمارے سامنے آ جاتے تو ہم اپنے نقاب اپنے سر سے چہرے پر ڈال لیتے اور جب وہ گزر جاتے تو ہم اسے کھول لیتے۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ احرام سے ہوتی تھیں اور قافلے والے ہمارے سامنے سے گزرتے تو ہم اپنے پردے کی چادر کو سر سے چہرے پر لٹکا لیتیں۔ جب وہ گزر جاتے تو چہرہ کھول لیتی تھیں۔","f2":"یہ سند اگرچہ قدرے ضعیف ہے مگردیگر اثار سے مسئلہ اسی طرح ہے کہ عورت حالت احرام میں بھی اجنبیوں سے پردہ کرے۔موطا امام مالک میں ہے۔ فاطمہ بنت مندر بیان کرتی ہیں۔ کہ ہم حالت احرام میں اپنے چہرے ڈھانپا کرتی تھیں۔اور اسماء بنت ابی بکرصدیق رضی اللہ تعالیٰ عنہا بھی ہمارے ساتھ ہوتی تھیں۔(باب تخمیر المحرم وجھہ)نیز (ارواء الغلیل حدیث 1023)مگر موجودہ صورت حال پردے کے معاملے میں انتہائی پریشان کن ہے کہ حیاء وشرم گویا اٹھتی جارہی ہے۔الا ماشاء اللہ مزید تفصیل کےلئے حدیث نمبر 1825) کے فوائد ومسائل ملاحظہ ہوں۔"}],[1834,"ام حصین رضی اللہ عنہا کہتی ہیں کہ ہم نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ حجۃ الوداع کیا تو میں نے اسامہ اور بلال رضی اللہ عنہما کو دیکھا کہ ان میں سے ایک نبی اکرم صلی اللہ علیہ وسلم کی اونٹنی کی مہار پکڑے ہوئے تھے، اور دوسرے اپنا کپڑا اٹھائے تھے تاکہ وہ آپ پر دھوپ سے سایہ کر سکیں ۱؎ یہاں تک کہ آپ نے جمرہ عقبہ کی رمی کی۔\n§وضاحت\n۱؎ : محرم کے لیے ضروری ہے کہ وہ اپنا سر کھولے رکھے، لیکن اس کا مطلب یہ نہیں کہ وہ سخت دھوپ میں چھتری یا خیمہ سے فائدہ نہ اٹھائے، گاڑیوں میں سفر نہ کرے، یہ چیزیں اس کے سر سے چپکی اور متصل نہیں رہتی ہیں۔","صحیح",{"u2":"سیدہ ام الحصین رضی اللہ عنہا ا بیان کرتی ہیں کہ ہم نے نبی کریم صلی اللہ علیہ وسلم کی معیت میں حجۃ الوداع کیا۔ چنانچہ میں نے سیدنا اسامہ اور بلال رضی اللہ عنہ کو دیکھا کہ ان میں سے ایک رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی کی مہار پکڑے ہوئے تھا اور دوسرا آپ صلی اللہ علیہ وسلم کو گرمی سے بچانے کے لیے آپ صلی اللہ علیہ وسلم پر کپڑا بلند کیے ہوئے تھا (اور ان کی یہ خدمت اسی طرح رہی) حتیٰ کہ آپ صلی اللہ علیہ وسلم نے جمرہ عقبہ کو کنکریاں مار لیں۔","f2":"محرم خود کسی سایہ میں بیٹھے چھتری استعمال کرے۔یا کوئی دوسرا اس کو سایہ کردے سب صورتیں جائز ہیں۔ہاں پگڑی ٹوپی یا رومال وغیرہ نہیں باندھ سکتا۔"}],[1835,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے پچھنا لگوایا اور آپ حالت احرام میں تھے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے احرام کی حالت میں سینگی لگوائی تھی۔"}],[1836,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک بیماری کی وجہ سے جو آپ کو تھی اپنے سر میں پچھنا لگوایا اور آپ احرام باندھے ہوئے تھے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے احرام کی حالت میں اپنے سر میں ایک بیماری کی بنا پر سینگی لگوائی۔"}],[1837,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک درد کی وجہ سے جو آپ کو تھا اپنے قدم کی پشت پر پچھنا لگوایا، آپ احرام باندھے ہوئے تھے ۱؎۔ ابوداؤد کہتے ہیں: میں نے احمد کو کہتے سنا کہ ابن ابی عروبہ نے اسے مرسلاً روایت کیا ہے یعنی قتادہ سے۔\n§وضاحت\n۱؎ : اگر پچھنے (سینگی) لگانے میں بال اتروانا پڑے تو فدیہ لازم ہوگا، اسی لئے بعض علماء نے سرے سے محرم کے لئے پچھنا لگوانے کو مکروہ جانا ہے، ورنہ حقیقت میں حالت احرام میں پچھنا لگوانا مکروہ نہیں ہے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بحالت احرام اپنے پاؤں کی پشت پر، ایک تکلیف کی وجہ سے سینگی لگوائی۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے امام احمد سے سنا، وہ کہتے تھے کہ ابن ابی عروبہ نے اس روایت کو قتادہ سے مرسل بیان کیا۔ (یعنی جناب انس کا واسطہ ذکر نہیں کیا۔)","f2":"1۔سینگی لگوانا اور فصد کھلوانا اس دور کا معروف طریقہ علاج تھا۔ اور مذکورہ بالا احادیث میں دو مختلف واقعات کا بیان آیا ہے۔2۔اب بھی بوقت ضرورت اس سے فائدہ حاصل کیا جاسکتا ہے۔اورظاہر ہے کہ اس عمل میں بالوں کی جگہ سے بال کاٹے جاتے ہیں۔جلد پر چیرالگایا جاتا ہے۔پس اس میں کوئی حرج نہیں ہے۔تاہم کئی ایک فقہاء بال کاٹنے کی بنا پر فدیہ کے قائل ہیں۔نیز دانت نکلوانے یا کسی عمل جراحی کی صورت میں کوئی فدیہ لازم نہیں آتا۔3۔بیماری میں علاج کرانا سنت رسول صلی اللہ علیہ وسلم ہے۔"}],[1838,"نبیہ بن وہب کہتے ہیں کہ عمر بن عبیداللہ بن معمر کی دونوں آنکھیں دکھنے لگیں تو انہوں نے ابان بن عثمان کے پاس (پوچھنے کے لیے اپنا آدمی) بھیجا کہ وہ اپنی آنکھوں کا کیا علاج کریں؟ (سفیان کہتے ہیں: ابان ان دونوں حج کے امیر تھے) تو انہوں نے کہا: ان دونوں پر ایلوا کا لیپ لگا لو، کیونکہ میں نے عثمان سے سنا ہے وہ اسے رسول اللہ صلی اللہ علیہ وسلم سے نقل کر رہے تھے۔","صحیح",{"u2":"جناب نبیہ بن وہب رضی اللہ عنہ سے مروی ہے کہ عمر بن عبیداللہ بن معمر کی آنکھیں خراب ہو گئیں تو انہوں نے جناب ابان بن عثمان سے پوچھا کہ کیا کیا جائے؟ سفیان نے بتایا کہ یہ ان دنوں امیر حج تھے۔ انہوں نے جواب دیا کہ ایلوا کا لیپ کر لے۔ بیشک میں نے سیدنا عثمان رضی اللہ عنہ سے سنا تھا وہ یہ بات رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے۔"}],[1839,"اس سند سے بھی نبیہ بن وہب سے یہی حدیث مروی ہے۔","صحیح",{"u2":"عثمان بن ابی شیبہ نے اسے ہمیں اسماعیل بن ابراہیم سے، انہوں نے نافع سے، انہوں نے نبیہ بن وہب سے مذکورہ بالا روایت بیان کی۔","f2":"آنکھ میں وہ اڈالنے یا اس پر ضماد کرنے سے احرام میں کوئی خرابی نہیں آتی۔اسی طرح سادہ سُرمہ ڈالنا بھی جائز ہے۔جس میں خوشبو نہ ہو۔"}],[1840,"عبداللہ بن حنین سے روایت ہے کہ عبداللہ بن عباس رضی اللہ عنہما اور مسور بن مخرمہ رضی اللہ عنہما کے مابین مقام ابواء میں اختلاف ہو گیا، ابن عباس رضی اللہ عنہما نے کہا: محرم سر دھو سکتا ہے، مسور نے کہا: محرم سر نہیں دھو سکتا، تو عبداللہ بن عباس رضی اللہ عنہما نے انہیں (ابن حنین کو) ابوایوب انصاری رضی اللہ عنہ کے پاس بھیجا تو آپ نے انہیں دو لکڑیوں کے درمیان کپڑے کی آڑ لیے ہوئے نہاتے پایا، ابن حنین کہتے ہیں: میں نے سلام کیا تو انہوں نے پوچھا: کون؟ میں نے کہا: میں عبداللہ بن حنین ہوں، مجھے آپ کے پاس عبداللہ بن عباس رضی اللہ عنہما نے بھیجا ہے کہ میں آپ سے معلوم کروں کہ رسول اللہ صلی اللہ علیہ وسلم حالت احرام میں اپنے سر کو کیسے دھوتے تھے؟ ابوایوب رضی اللہ عنہ نے اپنا ہاتھ کپڑے پر رکھا اور اسے اس قدر جھکایا کہ مجھے ان کا سر نظر آنے لگا، پھر ایک آدمی سے جو ان پر پانی ڈال رہا تھا، کہا: پانی ڈالو تو اس نے ان کے سر پر پانی ڈالا، پھر ایوب نے اپنے ہاتھوں سے سر کو ملا، اور دونوں ہاتھوں کو آگے لائے اور پیچھے لے گئے اور بولے ایسا ہی میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے ۱؎۔\n§وضاحت\n۱؎ : حالت احرام میں صرف پانی سے سر کا دھونا جائز ہے کسی بھی ایسی چیز سے اجتناب ضروری ہے جس سے جؤوں کے مرنے کا خوف ہو اسی طرح سر دھلتے وقت بالوں کو اتنا زور سے نہ ملے کہ وہ گرنے لگیں۔","صحیح",{"u2":"عبداللہ بن حنین سے مروی ہے کہ سیدنا عبداللہ بن عباس اور مسور بن مخرمہ رضی اللہ عنہ ابواء مقام میں تھے کہ ان میں ایک مسئلے میں اختلاف ہو گیا۔ ابن عباس رضی اللہ عنہ نے کہا کہ محرم اپنا سر دھو سکتا ہے۔ مسور رضی اللہ عنہ نے کہا کہ محرم اپنا سر نہیں دھو سکتا۔ چنانچہ ابن عباس رضی اللہ عنہ نے اس کو (عبداللہ بن حنین کو) سیدنا ابوایوب انصاری رضی اللہ عنہ کے ہاں بھیج دیا تو اس نے ان کو پایا کہ وہ کنویں کی چرخی کی دو لکڑیوں کے پاس بیٹھے غسل کر رہے تھے اور ایک کپڑے سے پردہ کیے ہوئے تھے۔ کہتے ہیں کہ میں نے ان کو سلام کیا تو انہوں نے پوچھا: کون ہو؟ میں نے کہا: میں عبداللہ بن حنین ہوں۔ مجھے عبداللہ بن عباس رضی اللہ عنہ نے بھیجا ہے کہ آپ سے دریافت کروں کہ رسول اللہ صلی اللہ علیہ وسلم حالت احرام میں اپنا سر کیسے دھویا کرتے تھے؟ تو انہوں نے (ابوایوب رضی اللہ عنہ نے) اپنا ہاتھ (پردے والے) کپڑے پر رکھ کر اسے کچھ نیچا کیا حتیٰ کہ مجھے ان کا سر نظر آنے لگا۔ پھر انہوں نے ایک شخص سے جو ان پر پانی ڈال رہا تھا، کہا کہ پانی ڈالو۔ چنانچہ اس نے ان کے سر پر پانی ڈالا تو سیدنا ابوایوب نے اپنے سر کو دونوں ہاتھوں سے حرکت دی اور اپنے ہاتھوں کو آگے پیچھے کیا: پھر کہا: میں نے آپ صلی اللہ علیہ وسلم کو دیکھا تھا کہ آپ اسی طرح کرتے تھے۔","f2":"1۔اس حدیث سے ثابت ہوتا ہے کہ محرم نہاسکتاہے۔اور اپنا سر بھی دھوسکتا ہے۔یعنی حالت احرام میں غسل کرنے میں کوئی حرج نہیں۔خواہ غسل واجبی ہو یا ویسے ہی راحت کےلئے۔اور سرکے بالوں کو ملتے ہوئے جو بال فطری انداز میں گر جایئں ان کا کوئی حرج نہیں۔2۔تحقیق مسائل میں پختہ کار اور قابل اعتماد علماء کی طرف رجوع کرناچاہیے۔ (فَاسْأَلُوا أَهْلَ الذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ) کے یہی معنی ہیں۔مگر ان پر بھی لازم ہے کہ (بِالْبَيِّنَاتِ وَالزُّبُرِ) کی بنیاد پر بادلائل حق کو واضح کریں۔(دیکھئے تفسیر آیت مذکورہ سورۃ النحل آیت۔44۔43۔)3۔خبر واحد حجت ہے۔نیز اہل حق کا شیوہ ہے۔کہ وہ اختلاف کے وقت نص (قرآن اور حدیث) کی طرف رجوع کرتے ہیں۔4۔صحیح حدیث معلوم ہوجانے کے بعد اجتہاد اور قیاس کو ترک کرنا فرض ہے۔5۔وضو اور غسل کرنے والے کو سلام کہا جاسکتا ہے۔6۔نہانے میں دوسرے شخص سے مدد لی جاسکتی ہے۔7۔نہانے اور وضو کرنے کے دوران میں بوقت ضرورت بات چیت کرنا بھی جائز ہے۔واللہ اعلم۔"}],[1841,"نبیہ بن وہب جو بنی عبدالدار کے فرد ہیں سے روایت ہے کہ عمر بن عبیداللہ نے انہیں ابان بن عثمان بن عفان کے پاس بھیجا، ابان اس وقت امیر الحج تھے، وہ دونوں محرم تھے، وہ ان سے پوچھ رہے تھے کہ میں نے ارادہ کیا ہے کہ میں طلحہ بن عمر کا شیبہ بن جبیر کی بیٹی سے نکاح کر دوں، میں چاہتا ہوں کہ تم بھی اس میں شریک رہو، ابان نے اس پر انکار کیا اور کہا کہ میں نے اپنے والد عثمان بن عفان رضی اللہ عنہ کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"محرم نہ خود نکاح کرے اور نہ کسی دوسرے کا نکاح کرائے\"۔","صحیح",{"u2":"جناب عمر بن عبیداللہ نے جناب ابان بن عثمان بن عفان سے کہلا بھیجا جبکہ ابان ان دنوں امیر حج تھے اور یہ دونوں احرام کی حالت میں تھے کہ میرا پروگرام ہے کہ طلحہ بن عمر کا نکاح شیبہ بن جبیر کی صاحبزادی سے کر دوں۔ اور میں چاہتا ہوں کہ آپ بھی اس میں تشریف لائیں۔ تو جناب ابان نے اس سے انکار کر دیا اور کہا: میں نے اپنے والد سیدنا عثمان بن عفان رضی اللہ عنہ سے سنا ہے، وہ کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے ” محرم اپنا نکاح کرے نہ کسی دوسرے کا۔ “"}],[1842,"اس سند سے بھی عثمان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کہا پھر راوی نے اسی کے مثل ذکر کیا البتہ اس میں انہوں نے «ولا يخطب» (نہ شادی کا پیغام دے) کے لفظ کا اضافہ کیا ہے ۱؎۔\n§وضاحت\n۱؎ : احرام کی حالت میں نہ تو محرم خود اپنا نکاح کر سکتا ہے نہ ہی دوسرے کا نکاح کرا سکتا ہے، عثمان رضی اللہ عنہ کی یہ حدیث اس سلسلے میں قانون کی حیثیت رکھتی ہے، جس میں کسی اور بات کی کوئی گنجائش نہیں ہے، رہا ابن عباس رضی اللہ عنہما کا یہ بیان (جو حدیث نمبر: ۱۸۴۴ میں آرہا ہے) کہ آپ صلی اللہ علیہ وسلم نے میمونہ رضی اللہ عنہا سے حالت احرام میں نکاح کیا تو یہ ان کا وہم ہے (دیکھئے نمبر: ۱۸۴۵) ، خود ام المومنین میمونہ رضی اللہ عنہا اور ان کا نکاح کرانے والے ابورافع رضی اللہ عنہ کا بیان اس کے برعکس ہے کہ یہ نکاح مقام سرف میں حلال رہنے کی حالت میں ہوا، تو صاحب معاملہ کا بیان زیادہ معتبر ہوتا ہے، دراصل ابن عباس رضی اللہ عنہ نے مکہ نہ جا کر صرف ہدی (منی میں ذبح کیا جانے والا جانور) بھیج دینے کو بھی احرام سمجھا، حالاں کہ یہ احرام نہیں ہوتا، اور یہ نکاح اس حالت میں ہو رہا تھا کہ آپ صلی اللہ علیہ وسلم نے اشعار کرکے ہدی بھیج دی اور گھر رہ گئے، اور بقول عائشہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم نے اپنے اوپر احرام کی کوئی بات لاگو نہیں کی۔","صحیح",{"u2":"جناب ابان بن عثمان، سیدنا عثمان رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور مذکورہ بالا حدیث کے مثل ذکر کیا۔ اور مذید کہا: ” اور نہ شادی کا پیغام دے۔ “"}],[1843,"ام المؤمنین میمونہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے نکاح کیا، اور ہم اس وقت مقام سرف میں حلال تھے (یعنی احرام نہیں باندھے تھے) ۔","صحیح",{"u2":"ام المؤمنین سیدہ میمونہ رضی اللہ عنہا ا کے بھتیجے یزید بن اصم سیدہ میمونہ رضی اللہ عنہا ا سے روایت کرتے ہیں وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے مقام سرف میں نکاح کیا تھا اور ہم دونوں حلال تھے۔","f2":"حضرت میمونہ رضی اللہ تعالیٰ عنہا (بنت حارث الحلالیہ)کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کا نکاح سات ہجری میں عمرۃ القضاء کے موقع پر ہوا تھا۔ ان کے پہلے شوہر کا نام ابو رہم بن عبد العزی تھا۔حضرت جعفر بن ابی طالب رضی اللہ تعالیٰ عنہ نے اس نکاح کا پیغام بھیجا۔انہوں نے حضرت عباس رضی اللہ تعالیٰ عنہ سے اپنی ر ضا مندی کا اظہار کیا تو انہوں نے نکاح کردیا۔(الاصابہ)"}],[1844,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ام المؤمنین میمونہ رضی اللہ عنہا سے حالت احرام میں نکاح کیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ میمونہ رضی اللہ عنہا ا سے نکاح کیا جبکہ آپ صلی اللہ علیہ وسلم حالت احرام میں تھے۔"}],[1845,"سعید بن مسیب کہتے ہیں ام المؤمنین میمونہ رضی اللہ عنہا سے (نبی اکرم صلی اللہ علیہ وسلم کے) حالت احرام میں نکاح کے سلسلے میں ابن عباس رضی اللہ عنہما کو وہم ہوا ہے۔","صحیح",{"u2":"جناب سعید بن مسیب رضی اللہ عنہ کہتے ہیں کہ سیدنا ابن عباس رضی اللہ عنہ کو سیدہ میمونہ رضی اللہ عنہا ا کے نکاح کے معاملے میں وہم ہوا ہے کہ وہ احرام میں تھے۔","f2":"یہ آخری روایت اگرچہ سندا مقطوع ہے مگر مبنی بر حقیقت ہے کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ کو وہم ہوا ہے۔میمونہ رضی اللہ تعالیٰ عنہ صاحب واقعہ ہیں۔ ان کا اپنا بیان ہے کہ ہم دونوں حلال تھے اور اس وہم کی بنیاد غالباً یہ ہے کہ چونکہ احرام سے فارغ ہوتےہی یہ کام ہوگیا تھا۔اور حضرت ابن عباس رضی اللہ تعالیٰ عنہ ویسے بھی صغیر السن تھے۔اس لئے انہوں نے سمجھا کہ احرام ہی میں یہ نکاح ہوا تھا۔واللہ اعلم۔"}],[1846,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا کہ محرم کون کون سا جانور قتل کر سکتا ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ جانور ہیں جنہیں حل اور حرم دونوں جگہوں میں مارنے میں کوئی حرج نہیں: بچھو، چوہیا، چیل، کوا اور کاٹ کھانے والا کتا\"۔","صحیح",{"u2":"جناب سالم اپنے والد (سیدنا عبداللہ بن عمر رضی اللہ عنہ) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے سوال کیا گیا کہ محرم کون سے جانور قتل کر سکتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” پانچ جانوروں کے قتل میں کوئی گناہ نہیں ہے۔ حرم میں مارے یا اس سے باہر حل میں (اور حالت احرام میں مارے یا حلال ہوتے ہوئے) یعنی بچھو، کوا، چوہا، چیل اور کاٹنے والا کتا۔ “","f2":"بچھو پر اس جنس کے دیگر موذی جانور بھی قیاس کئے جاسکتے ہیں۔مثلا کنکھجورا اور بھڑ وغیرہ اور کانٹے والے کتے پر اس جنس کے دیگر جانور مثلاً شیر چیتا ریچھ اور بھیڑیا وغیرہ۔"}],[1847,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ جانور ایسے ہیں جنہیں حرم میں بھی مارنا حلال ہے: سانپ، بچھو، کوا، چیل، چوہیا، اور کاٹ کھانے والا کتا\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” پانچ قسم کے جانوروں کو حرم میں قتل کرنا حلال ہے، یعنی سانپ، بچھو، چیل، چوہا اور کاٹنے والا کتا۔ “"}],[1848,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا: محرم کون کون سا جانور مار سکتا ہے؟ آپ نے فرمایا: \"سانپ، بچھو، چوہیا کو (مار سکتا ہے) اور کوے کو بھگا دے، اسے مارے نہیں، اور کاٹ کھانے والے کتے، چیل اور حملہ کرنے والے درندے کو (مار سکتا ہے)\"۔","ضعیف",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا کہ محرم کون سے جانور قتل کر سکتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” سانپ، بچھو، چوہا، کوے کو پتھر مارے قتل نہ کرے، کاٹنے والا کتا، چیل اور ہر حملہ آور درندہ۔ “"}],[1849,"عبداللہ بن حارث سے روایت ہے (حارث طائف میں عثمان رضی اللہ عنہ کے خلیفہ تھے) وہ کہتے ہیں حارث نے عثمان رضی اللہ عنہ کے لیے کھانا تیار کیا، اس میں چکور ۱؎، نر چکور اور نیل گائے کا گوشت تھا، وہ کہتے ہیں: انہوں نے علی رضی اللہ عنہ کو بلا بھیجا چنانچہ قاصد ان کے پاس آیا تو دیکھا کہ وہ اپنے اونٹوں کے لیے چارہ تیار کر رہے ہیں، اور اپنے ہاتھ سے چارا جھاڑ رہے تھے جب وہ آئے تو لوگوں نے ان سے کہا: کھاؤ، تو وہ کہنے لگے: لوگوں کو کھلاؤ جو حلال ہوں (احرام نہ باندھے ہوں) میں تو محرم ہوں تو انہوں نے کہا: میں قبیلہ اشجع کے ان لوگوں سے جو اس وقت یہاں موجود ہیں قسم دے کر پوچھتا ہوں کہ کیا تم جانتے ہو کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک شخص نے نیل گائے کا پاؤں ہدیہ بھیجا تو آپ نے کھانے سے انکار کیا کیونکہ آپ حالت احرام میں تھے؟ لوگوں نے کہا: ہاں۲؎۔\n§وضاحت\n۱؎ : تیتر کے قسم کا ایک پہاڑی خوبصورت و خوش آواز پرندہ ہے، یہ چاندنی رات میں خوب چہچہاتا ہے اس لئے اسے چاند کا عاشق کہتے ہیں۔ ۲؎ : محرم کے لئے خشکی کا شکار کرنا یا کھانا دونوں ممنوع ہے، اسی طرح اگر کسی غیر محرم آدمی نے خشکی کا شکار خاص کر محرم کے لئے کیا ہو تو بھی محرم کو اس کا کھانا ممنوع ہے، البتہ اگر حلال آدمی نے شکار اپنے لئے کیا ہو اور کسی محرم نے اس میں اشارہ کنایہ تک سے بھی تعاون نہیں کیا ہو ، پھر اس میں سے کسی محرم کو ہدیہ پیش کیا ہو تو ایسے شکار کا کھانا جائز ہے، اس باب میں جتنی بھی روایات آئی ہیں ان سب کا یہی خلاصہ ہے، اور اس لحاظ سے ان میں کوئی تعارض نہیں ہے۔","صحیح",{"u2":"اسحٰق بن عبداللہ بن حارث اپنے والد سے بیان کرتے ہیں کہ جناب حارث سیدنا عثمان رضی اللہ عنہ کی جانب سے طائف کے گورنر تھے۔ انہوں نے سیدنا عثمان رضی اللہ عنہ کے لیے کھانے کا اہتمام کیا اور اس میں چکوروں، جنگلی چڑیوں اور نیل گائے کا گوشت تیار کروایا۔ اور سیدنا علی رضی اللہ عنہ کو بھی بلوا بھیجا۔ قاصد جب ان کے پاس پہنچا تو وہ اپنے اونٹوں کے لیے پتے جھاڑ رہے تھے۔ چنانچہ وہ اپنے ہاتھ (پتوں کے گرد غبار سے) جھاڑتے ہوئے تشریف لائے۔ صاحب ضیافت نے ان سے کہا: کھائیے! تو انہوں نے جواب دیا: یہ کھانا ایسے لوگوں کو دے دیں جو احرام میں نہ ہوں، ہم تو احرام میں ہیں۔ تب انہوں (سیدنا علی رضی اللہ عنہ نے کہا: میں قسم دے کر کہتا ہوں کہ قبیلہ اشجع میں سے کون یہاں ہے، کیا تم جانتے ہو کہ ایک شخص (حمار وحشی) نے رسول اللہ صلی اللہ علیہ وسلم کو حالت احرام میں نیل گائے کا گوشت ہدیہ کیا تھا، تو آپ نے اس کے کھانے سے انکار کر دیا تھا؟ ان لوگوں نے کہا: ہاں (یہ بات حق اور سچ ہے)۔","f2":"1۔صحابہ کرامرضوان اللہ عنہم اجمعین میں بالخصوص خلفائے اربعہ میں انتہائی اخوت و مودت کے تعلقات تھے۔1۔حضرت علی رضی اللہ تعالیٰ عنہ کو حق بات بتانے اور کہنے میں کوئی بھی چیز مانع نہ ہوئی۔نہ تعلق خاطر اور نہ دوسروں کے مناصب حکومت۔3۔قناعت کی جو تعلیم وتربیت رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب رضوان اللہ عنہم اجمعین کو دی تھی۔وہ تمام عمر اسی پر کار بند رہے۔4۔حضرت علی رضی اللہ تعالیٰ عنہ خود ہی اپنے خادم تھے۔5۔شکار جب اس نیت سے کیا گیا ہو کہ محرمین کی ضیافت کی جائے گی تو انہیں اس کا قبول کرناجائز نہیں۔"}],[1850,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ انہوں نے زید بن ارقم رضی اللہ عنہ سے کہا: زید بن ارقم! کیا تمہیں معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو شکار کا دست ہدیہ دیا گیا تو آپ نے اسے قبول نہیں کیا، اور فرمایا: \"ہم احرام باندھے ہوئے ہیں؟\"، انہوں نے جواب دیا: ہاں (معلوم ہے) ۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے انہوں نے کہا: اے زید بن ارقم! کیا تمہیں معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو ایک شکار کا عضو ہدیہ دیا گیا تھا تو آپ صلی اللہ علیہ وسلم نے اسے قبول نہیں کیا تھا اور فرمایا تھا “ ہم احرام میں ہیں؟ ” سیدنا زید رضی اللہ عنہ نے جواب دیا، ہاں!۔"}],[1851,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"خشکی کا شکار تمہارے لیے اس وقت حلال ہے جب تم خود اس کا شکار نہ کرو اور نہ تمہارے لیے اس کا شکار کیا جائے\"۔ ابوداؤد کہتے ہیں: جب دو روایتیں متعارض ہوں تو دیکھا جائے گا کہ صحابہ کرام رضی اللہ عنہم کا عمل کس کے موافق ہے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہتے تھے ” خشکی کا شکار تمہارے لیے حلال ہے بشرطیکہ تم نے اس کو شکار نہ کیا ہو یا تمہارے لیے شکار نہ کیا گیا ہو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم سے دو حدیثیں ایک دوسری کے برخلاف ملیں تو وہ حدیث لی جائے جس پر آپ صلی اللہ علیہ وسلم کے صحابہ نے عمل کیا ہو۔","f2":"یہ حدیث سندا تو صحیح نہیں۔مگر معنا درست ہے۔اور مسئلہ یہی ہے۔جیسے کہ صحیح بخاری میں ہے۔(کتاب جزاء الصید۔احادیث۔1825تا1821)اوراگلی حدیث میں بھی مروی ہے۔2۔امام ابودائود رحمۃ اللہ علیہ کابیان جب دو حدیثیں ایک دوسرے کے برخلاف ملیں الخ معلوم ہونا چاہیے کہ صحیح الاسناد احادیث میں جہاں تعارض محسوس ہوتا ہے ان میں یقیناً پہلے کا قول وعمل مسنوخ اور بعد والا ناسخ ہوتا ہے۔ اور تواریخ کا علم نہ ہوسکے۔تو دیگر وجو ہ ترجیحات کے ذریعے سے ایک کو راحج اور دوسرے کو مرجوح قرار دیا جائے گا۔اس قسم کی تحقیقات علمائے راسخین اور ان کی موثوق تالیفات ہی سے مل سکتی ہیں۔اس موضوع پر علمائے محدثین نے بہت محنت کی ہے۔مثلاً کتاب الاعتبار فی الناسخ والمنسوخ (للحاذی)۔الناسخ والمنسوخ (امام احمد رحمہ اللہ) تجرید الاحادیث المنسوخۃ ابن الجوزی۔بظاہر مختلف المعانی احادیث کے سلسلے میں یہ کتب قابل مراجعہ ہیں۔ اختلاف الحدیث (امام شافعی رحمہ اللہ) تاویل مختلف الحدیث (ابن قتیبہ عبد اللہ ب ن مسلم رحمہ اللہ اور۔مشکل الاثار (ابو جعفر احمد بن سلامہ الطحاوی) 3۔امام الائمہ ابو بکر بن خزیمہ رحمہ اللہ فر مایا کرتے تھے۔ کہ جس شخص کو دو صحیح حدیثوں میں تعارض اور تضاد محسوس ہوتا ہو وہ ہمارے پاس لے آئے ہم ان میں تطبیق دے دیں گے۔اللہ اکبر! یہ ہیں ہمارے اسلاف محدثین۔"}],[1852,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، مکہ کا راستہ طے کرنے کے بعد اپنے کچھ ساتھیوں کے ساتھ جو احرام باندھے ہوئے تھے وہ پیچھے رہ گئے، انہوں نے احرام نہیں باندھا تھا، پھر اچانک انہوں نے ایک نیل گائے دیکھا تو اپنے گھوڑے پر سوار ہوئے اور ساتھیوں سے کوڑا مانگا، انہوں نے انکار کیا، پھر ان سے برچھا مانگا تو انہوں نے پھر انکار کیا، پھر انہوں نے نیزہ خود لیا اور نیل گائے پر حملہ کر کے اسے مار ڈالا تو رسول اللہ صلی اللہ علیہ وسلم کے بعض ساتھیوں نے اس میں سے کھایا اور بعض نے انکار کیا، جب وہ رسول اللہ صلی اللہ علیہ وسلم سے جا کر ملے تو آپ سے اس بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ ایک کھانا تھا جو اللہ نے تمہیں کھلایا\"۔","صحیح",{"u2":"سیدنا ابوقتادہ انصاری رضی اللہ عنہ سے مروی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھے حتیٰ کہ مکہ کے راستے میں ایک جگہ وہ اپنے ساتھیوں کے ساتھ پیچھے رہ گئے جو کہ احرام میں تھے جب کہ یہ بغیر احرام کے تھے۔ ابوقتادہ رضی اللہ عنہ نے ایک نیل گائے کو دیکھا تو اپنے گھوڑے پر سوار ہو گئے اور ساتھیوں سے کہا: مجھے میرا کوڑا پکڑا دو۔ انہوں نے کوڑا دینے سے انکار کر دیا۔ پھر بھالا مانگا تو انہوں نے اس (کے دینے) سے بھی انکار کر دیا۔ آخر خود ہی اٹھایا اور اس نیل گائے کے پیچھے بھاگ گئے اور اسے مار لائے۔ تو کچھ اصحاب رسول صلی اللہ علیہ وسلم نے اس کا گوشت کھایا اور کچھ نے انکار کر دیا۔ پھر جب یہ حضرات رسول اللہ صلی اللہ علیہ وسلم سے جا ملے تو آپ سے اس کے بارے میں دریافت کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو رزق ہے جو اللہ نے تمہیں کھلایا ہے۔ “","f2":"-1احرام کی حالت میں کسی شکاری کوشکار کا اشارہ دینا یا اس سے کسی طرح کا تعاون کرنا بھی ناجائز ہے۔2۔جب کوئی شکاری صرف اپنے لئے شکار کرے تو محرمین کو اس سے کھا لینا جائز ہے۔3۔صحیح احادیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بھی اس کا بقیہ گوشت تناول فرمایا تھا۔(صحیح المسلم الحج۔حدیث 1197۔1196)"}],[1853,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ٹڈیاں سمندر کے شکار میں سے ہیں ۱؎\"۔\n§وضاحت\n۱؎ : یعنی جس طرح سمندر کا شکار محرم کے لئے جائز ہے اسی طرح ٹڈی کا شکار بھی جائز ہے (مگر یہ حدیث ضعیف ہے)۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ٹڈی سمندر کے شکار (کی قسم) میں سے ہے۔ “"}],[1854,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ہمیں ٹڈیوں کا ایک جھنڈ ملا، ہم میں سے ایک شخص انہیں اپنے کوڑے سے مار رہا تھا، اور وہ احرام باندھے ہوئے تھا تو اس سے کہا گیا کہ یہ درست نہیں، پھر رسول اللہ صلی اللہ علیہ وسلم سے اس کا ذکر کیا گیا تو آپ نے فرمایا: \"وہ تو سمندر کے شکار میں سے ہے\"۔ ابوداؤد کہتے ہیں: ابومہزم ضعیف ہیں اور دونوں روایتیں راوی کا وہم ہیں۔","ضعیف جدا",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں ایک ٹڈی دل مل گیا تو ہمارا ایک آدمی جو احرام میں تھا، ان کو اپنے کوڑے سے مارنے لگا، اسے کہا گیا کہ یہ کام درست نہیں ہے اور نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو سمندر کے شکار میں سے ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ (اس حدیث کا راوی) ابومہزم ضعیف ہے اور یہ دونوں حدیثیں وہم ہیں۔"}],[1855,"کعب رضی اللہ عنہ کہتے ہیں ٹڈیاں سمندر کے شکار میں سے ہیں۔","ضعیف",{"u2":"جناب کعب (کعب احبار رضی اللہ عنہ) سے منقول ہے کہ ٹڈی سمندر کے شکار میں سے ہے۔","f2":"ان میں سے پہلی روایت اور کعب احبار کے قول کو ہمارے فاضل محقق نے حسن قرار دیا ہے۔لیکن دیگر آئمہ کے نزدیک یہ تینوں روایات ضعیف ہیں۔میمون بن جابان کی توثیق مختلف فیہ ہے۔اس لئے ان کاضعیف ہونا ہی راحج ہے۔ خیال رہے کہ مشہور یہ ہے جیسا کہ موطا امام مالکرحمۃ اللہ علیہ میں کعب احبار رحمۃ اللہ علیہ کا یہ قول بیان کیا گیا ہے۔کہ ٹڈی د ر اصل مچھلیوں کی چھینک سے پیدا ہوتی ہے۔اورسال میں دو دفعہ ایسا ہوتا ہے۔ مگر حضرت عمر رضی اللہ تعالیٰ عنہ نے ان کی یہ بات تسلیم نہیں کی۔اور راحج یہی ہے کہ یہ زمین کابری جانور ہے اور اس کےشکار میں فدیہ ہے۔"}],[1856,"کعب بن عجرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم صلح حدیبیہ کے زمانے میں ان کے پاس سے گزرے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہیں تمہارے سر کی جوؤں نے ایذا دی ہے؟\" کہا: ہاں، اس پر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"سر منڈوا دو، پھر ایک بکری ذبح کرو، یا تین دن کے روزے رکھو، یا چھ مسکینوں کو تین صاع کھجور کھلاؤ ۱؎\"۔\n§وضاحت\n۱؎ : یہ حدیث آیت کریمہ «فَمَن كَانَ مِنكُم مَّرِيضاً أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ» (سورۃ بقرۃ: ۱۹۶) کی تفسیر ہے۔","صحیح",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ سے روایت ہے کہ حدیبیہ کے دنوں میں رسول اللہ صلی اللہ علیہ وسلم ان کے پاس سے گزرے اور فرمایا ” تمہارے سر کی جوؤں نے تمہیں ایذا دے رکھی ہے؟ “ انہوں نے کہا: ہاں! تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” سر منڈا لو اور پھر ایک بکری قربانی کر دو یا تین دن روزے رکھو یا تین صاع کھجور چھ مسکینوں میں تقسیم کر دو۔ “","f2":"1۔اعمال حج میں کیس تقصیر پرمشروع قربانی صدقہ یا روزہ رکھنا فدیہ کہلاتا ہے۔بمعنی عوض یا بدل 2۔ایک صاع چار مد کا ہوتا ہے۔اور ایک مد تقریباً 9 چھٹانک کا۔تین صاع چھ مسکینوں پر تقسیم کریں گے۔تو ہر مسکین کو دو مد (18چھٹا نک) ملیں گے۔ پس یہی فدیے کا حساب ہوا۔"}],[1857,"کعب بن عجرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: \"اگر تم چاہو تو ایک بکری ذبح کر دو اور اگر چاہو تو تین دن کے روزے رکھو، اور اگر چاہو تو تین صاع کھجور چھ مسکینوں کو کھلا دو\"۔","صحیح",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا ” چاہو تو قربانی دے دو، چاہو تو تین دن روزے رکھ لو اور اگر چاہو تو تین صاع کھجور چھ مسکینوں کو کھلا دو۔ “"}],[1858,"کعب بن عجرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم صلح حدیبیہ کے زمانے میں ان کے پاس سے گزرے، پھر انہوں نے یہی قصہ بیان کیا، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تمہارے ساتھ دم دینے کا جانور ہے؟\"، انہوں نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو تو تین دن کے روزے رکھو، یا چھ مسکینوں کو تین صاع کھجور کھلاؤ، اس طرح کہ ہر دو مسکین کو ایک صاع مل جائے\"۔","صحیح",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ کا بیان ہے کہ حدیبیہ کے دنوں میں رسول اللہ صلی اللہ علیہ وسلم ان کے پاس سے گزرے اور قصہ بیان کیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تمہارے پاس خون (فدیے کا جانور) ہے؟ “ انہوں نے کہا: نہیں! آپ صلی اللہ علیہ وسلم نے فرمایا ” تو تین دن روزے رکھو یا تین صاع کھجور چھ مسکینوں میں صدقہ کر دو۔ ہر دو مسکینوں کو ایک صاع دو۔ “"}],[1859,"کعب بن عجرہ رضی اللہ عنہ سے روایت ہے (اور انہیں سر میں (جوؤوں کی وجہ سے) تکلیف پہنچی تھی تو انہوں نے سر منڈوا دیا تھا)، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں ایک گائے قربان کرنے کا حکم دیا۔","ضعیف",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ سے مروی ہے۔ اور ان کی حالت یہ تھی کہ سر میں اذیت تھی (یعنی جوئیں پڑ گئی تھیں) تو انہوں نے اپنا سر منڈوا لیا تھا۔ پس نبی کریم صلی اللہ علیہ وسلم نے ان کو حکم دیا تھا کہ ایک گائے کی قربانی کریں۔","f2":"اس میں بقرۃ (ایک گائے) کا لفظ غیر محفوظ ہے۔"}],[1860,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ حدیبیہ کے سال میرے سر میں جوئیں پڑ گئیں، میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا یہاں تک کہ مجھے اپنی بینائی جانے کا خوف ہوا تو اللہ تعالی نے میرے سلسلے میں «فمن كان منكم مريضا أو به أذى من رأسه» کی آیت نازل فرمائی، تو رسول اللہ صلی اللہ علیہ وسلم نے مجھے بلایا اور مجھ سے فرمایا: \"تم اپنا سر منڈوا لو اور تین دن کے روزے رکھو، یا چھ مسکینوں کو ایک فرق ۱؎ منقٰی کھلاؤ، یا پھر ایک بکری ذبح کرو\" چنانچہ میں نے اپنا سر منڈوایا پھر ایک بکری کی قربانی دے دی۔\n§وضاحت\n۱؎ : ’’فرق‘‘: ایک پیمانہ ہے جس میں چار صاع کی گنجائش ہوتی ہے۔","حسن",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ بیان کرتے ہیں کہ میرے سر میں جوئیں پڑ گئیں۔ جبکہ میں حدیبیہ کے سال (اس سفر میں) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا۔ اور (سر کی اذیت اتنی شدید تھی کہ) مجھے اپنی نظر کا اندیشہ لگ گیا تھا۔ پس اللہ عزوجل نے میرے بارے میں یہ آیت اتاری «فمن كان منكم مريضا أو به أذى من رأسه» پس رسول اللہ صلی اللہ علیہ وسلم نے مجھے بلوایا اور فرمایا ” اپنا سر منڈا دو۔ تین روزے رکھو یا چھ مسکینوں کو ایک ٹوکرا کشمش کا کھلا دو یا ایک بکری قربانی کر دو۔ “ چنانچہ میں نے اپنا سر منڈوایا اور پھر قربانی کر دی۔","f2":"علامہ البانی رحمۃ اللہ علیہ فرماتے ہیں۔کہ اس روایت میں زہیب یعنی کشمش کا زکر منکر ہے صحیح بات کھجور ہی ہے۔ فرق تین صاع کا برتن یا ٹوکری ہوتی ہے۔"}],[1861,"اس سند سے بھی کعب بن عجرہ رضی اللہ عنہ سے یہی قصہ مروی ہے البتہ اس میں اتنا اضافہ ہے «أى ذلك فعلت أجزأ عنك» \"اس میں سے تو جو بھی کر لو گے تمہارے لیے کافی ہے\"۔","صحیح",{"u2":"سیدنا کعب بن عجرہ رضی اللہ عنہ سے اس قصے میں مروی ہے کہ (آپ صلی اللہ علیہ وسلم نے فرمایا) ” ان (تین کاموں) میں سے جو بھی کرو گے تم سے کفایت کرے گا۔ “","f2":"1۔قوم کے سربراہ اور کسی انجمن وجمیعت کے سربراہ کے لئے لازمی ہے کہ اپنے ساتھیوں کے شخصی احوال پر بھی نگاہ رکھے۔\nنگہ بلند سخن دلنواز جاں پرسوز یہی ہے رخت سفر میر کارواں کےلیے\nاس باب کی احادیث سورہ بقرہ کی آیت کریمہ (196) (فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ) کی تفسیر ہیں۔ اور جو تم میں سے بیمار ہو یا اس کے سر میں تکلیف ہو تو فدیہ دے یعنی روزے رکھے۔یا صدقہ کرے یا قربانی کرے۔"}],[1862,"حجاج بن عمرو انصاری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کی ہڈی ٹوٹ جائے، یا لنگڑا ہو جائے تو وہ حلال ہو گیا، اب اس پر اگلے سال حج ہو گا ۱؎\"۔ عکرمہ کہتے ہیں: میں نے ابن عباس رضی اللہ عنہما اور ابوہریرہ رضی اللہ عنہ سے اس کے بارے میں پوچھا تو ان دونوں نے کہا: انہوں نے سچ کہا۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ حج و عمرہ کی نیت سے گھر سے نکلنے والے کو اگر اچانک کوئی مرض لاحق ہو جائے تو وہ وہیں پر حلال ہو جائے گا، لیکن آئندہ سال اس کو حج کرنا ہو گا، اگر یہ حج فرض حج ہو تو۔","صحیح",{"u2":"سیدنا حجاج بن عمرو انصاری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کی ہڈی ٹوٹ جائے یا لنگڑا ہو جائے تو وہ حلال ہو گیا۔ (یعنی اس کے لیے حلال ہو جانا مباح ہے) اور آئندہ کے لیے اس پر حج ہے۔ “ جناب عکرمہ کہتے ہیں میں نے سیدنا ابن عباس رضی اللہ عنہ اور ابوہریرہ رضی اللہ عنہ سے اس بارے میں پوچھا، ان دونوں نے (حجاج کی روایت کی) تصدیق کی۔","f2":"آئندہ حج کے لئے آنافرض کی قضا تو فرض ہے۔اگر یہ حج نفل ہوتو بھی راحج یہی ہے کہ دوبارہ آئے اور یہی حکم عمرہ کا ہے۔اور ظاہر ہے کہ یہ احکام استطاعت اوروسائل ہی پر مبنی ہیں۔"}],[1863,"حجاج بن عمرو رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کی ہڈی ٹوٹ جائے یا لنگڑا ہو جائے یا بیمار ہو جائے\"، پھر راوی نے اسی مفہوم کی حدیث ذکر کی، سلمہ بن شبیب نے «عن معمر» کے بجائے «أنبأنا معمر» کہا ہے۔","صحیح",{"u2":"سیدنا حجاج بن عمرو نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جس کی ہڈی ٹوٹ جائے یا وہ لنگڑا ہو جائے یا بیمار پڑ جائے۔ “ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔ (امام ابوداؤد رضی اللہ عنہ کے شیخ) جناب سلمہ بن شبیب نے اپنی سند میں «أنبأنا» (یعنی ہم کو خبر دی) کا کلمہ استعمال کیا۔ (اس طرح انہوں نے اپنے شیخ سے سماع کی تصریح کر دی۔)","f2":"اس روایت میں بیماری کو ایک مستقل عذر شما ر کیا گیا ہے۔اور ظاہر ہے کہ بیماری کی نوعیت کے اعتبار سے اگر محرم کے لئے اعمال حج جاری رکھنا ممکن نہ ہوں تو حلال ہوسکتا ہے۔"}],[1864,"عمرو بن میمون کہتے ہیں کہ میں نے ابوحاضر حمیری سے سنا وہ میرے والد میمون بن مہران سے بیان کر رہے تھے کہ جس سال اہل شام مکہ میں عبداللہ بن زبیر رضی اللہ عنہما کا محاصرہ کئے ہوئے تھے میں عمرہ کے ارادے سے نکلا اور میری قوم کے کئی لوگوں نے میرے ساتھ ہدی کے جانور بھی بھیجے، جب ہم اہل شام (مکہ کے محاصرین) کے قریب پہنچے تو انہوں نے ہمیں حرم میں داخل ہونے سے روک دیا، چنانچہ میں نے اسی جگہ اپنی ہدی نحر کر دی اور احرام کھول دیا اور لوٹ آیا، جب دوسرا سال ہوا تو میں اپنا عمرہ قضاء کرنے کے لیے نکلا، چنانچہ میں ابن عباس رضی اللہ عنہما کے پاس آیا اور میں نے ان سے پوچھا، تو انہوں نے کہا کہ قضاء کے عمرہ میں حدیبیہ کے سال جس ہدی کی نحر کر لی تھی اس کا بدل دو کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب کو حکم دیا تھا کہ وہ عمرہ قضاء میں اس ہدی کا بدل دیں جو انہوں نے حدیبیہ کے سال نحر کی تھی۔","ضعیف",{"u2":"عمرو بن میمون کہتے ہیں کہ میں نے ابوحاضر حمیری کو سنا وہ میرے والد میمون بن مہران سے بیان کر رہے تھے کہ جس سال اہل شام نے مکہ میں ابن زبیر کا محاصرہ کیا تھا میں (ابوحاضر حمیری) عمرے کی غرض سے روانہ ہوا۔ میرے ساتھ قوم کے کچھ افراد نے اپنی قربانیاں بھی بھیجی تھیں۔ جب ہم اہل شام کے پاس پہنچے تو انہوں نے ہمیں حرم میں داخل ہونے سے روک دیا۔ چنانچہ میں نے قربانی اسی جگہ نحر کر دی اور پھر حلال ہو گیا اور واپس لوٹ آیا۔ پھر جب اگلا سال آیا اور میں اپنے عمرے کی قضا کے لیے چلا تو سیدنا ابن عباس رضی اللہ عنہ کے ہاں آیا اور ان سے پوچھا تو انہوں نے کہا: اپنی قربانی کا بدل بھی دو۔ بیشک رسول اللہ صلی اللہ علیہ وسلم نے عمرہ قضا میں اپنے صحابہ سے فرمایا تھا کہ حدیبیہ کے سال انہوں نے جو قربانیاں کی تھیں ان کے عوض قربانیاں بھی کریں۔","f2":"امام خطابی فرماتے ہیں۔کہ نفلی عمرے میں بدل ضروری نہیں۔البتہ واجب کئے ہوئے عمرے میں قربانی کا بدل ضروری ہوگا۔اور امام بہیقی رحمہ اللہ کہتے ہیں کہ جس طرح دوبارہ عمرہ کرنا مستحب ہے اس طرح قربانی کابدل بھی مستحب ہے۔(عون المعبود)"}],[1865,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما جب مکہ آتے تو ذی طوی میں رات گزارتے یہاں تک کہ صبح کرتے اور غسل فرماتے، پھر دن میں مکہ میں داخل ہوتے اور نبی اکرم صلی اللہ علیہ وسلم کے بارے میں بتاتے کہ آپ نے ایسے ہی کیا ہے ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ افضل یہ ہے کہ مکہ میں دن میں داخل ہو، مگر یہ قدرت اور امکان پر منحصر ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ وہ جب بھی مکہ آتے تو وادی ذی طویٰ میں رات گزارتے حتیٰ کہ صبح ہو جاتی اور غسل کرتے۔ پھر دن چڑھے مکہ میں داخل ہوتے۔ اور نبی کریم صلی اللہ علیہ وسلم کے متعلق بیان کرتے کہ آپ صلی اللہ علیہ وسلم نے ایسے ہی کیا تھا۔","f2":"یہ عمل ممکن ہوتو مستحب ہے جبکہ عمرہ جعرانہ میں نبی کریم صلی اللہ علیہ وسلم رات کے وقت تشریف لے گئے تھے۔"}],[1866,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم مکہ میں ثنیہ علیا (بلند گھاٹی) سے داخل ہوتے، (یحیی کی روایت میں اس طرح ہے کہ نبی اکرم صلی اللہ علیہ وسلم مکہ میں ثنیہ بطحاء کی جانب سے مقام کداء سے داخل ہوتے) اور ثنیہ سفلی (نشیبی گھاٹی) سے نکلتے۔ برمکی کی روایت میں اتنا زائد ہے یہ مکہ کی دو گھاٹیاں ہیں اور مسدد کی حدیث زیادہ کامل ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم مکہ میں بالائی جانب کی گھاٹی سے تشریف لایا کرتے تھے۔ مسدد اور ابن حنبل نے یحییٰ سے نقل کرتے ہوئے کہا کہ نبی کریم صلی اللہ علیہ وسلم بطحاء کی گھاٹی سے کداء کی جانب سے مکہ میں داخل ہوتے تھے اور زیریں جانب کی گھاٹی سے واپس جاتے تھے۔ برمکی (عبداللہ بن جعفر) نے مزید کہا کہ مکہ کی دو گھاٹیاں مراد ہیں۔ اور مسدد کی روایت زیادہ کامل ہے۔"}],[1867,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم شجرہ (جو ذی الحلیفہ میں تھا) کے راستے سے (مدینہ سے) نکلتے تھے اور معرس (مدینہ سے چھ میل پر ایک موضع ہے) کے راستہ سے (مدینہ میں) داخل ہوتے تھے ۱؎۔\n§وضاحت\n۱؎ : اس حدیث کی باب سے مناسبت یہ ہے کہ جب مکہ میں داخل ہونے اوراس سے نکلنے کی بات آئی تو مدینہ سے نکلنے اور داخل ہونے کی بابت بھی ایک حدیث باب میں ذکر کر دیا، اور اس سے یہ بھی مستنبط کرنا ہے کہ مدینہ ہی نہیں کسی بھی بستی میں داخل ہونے یا اس سے نکلنے کے راستے میں فرق کرنا چاہئے، جیسا کہ اس حدیث پر امام نووی نے صحیح مسلم میں باب باندھا ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم (مدینہ منورہ سے) نکلتے ہوئے شجرہ والی راہ اختیار فرماتے۔ (یعنی ذوالحلیفہ والی، جہاں اس زمانے میں ایک درخت بھی تھا۔) اور واپسی میں معرس والی جانب سے داخل ہوتے۔ (یعنی مدینہ میں)۔","f2":"اس حدیث کی باب سے مطابقت یوں ہے۔کہ امام مسلم رحمہ اللہ تعالیٰ نے اس حدیث اوراوپر والی حدیث کو عبدا للہ بن نمیر سے اسی سند سے بیان کرتے ہوئے ایک ہی روایت بنایا ہے۔جبکہ امام ابو دائود رحمۃ اللہ علیہ یا انکے شیخ عثمان نے اس کو قطع کرکے دوروایتیں بنا دیا ہے۔(بذل المجہود)"}],[1868,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے سال مکہ کے بلند مقام کداء ۱؎ کی جانب سے داخل ہوئے اور عمرہ کے وقت کُدی ۲؎ کی جانب سے داخل ہوئے اور عروہ دونوں ہی جانب سے داخل ہوتے تھے، البتہ اکثر کدی کی جانب سے داخل ہوتے اس لیے کہ یہ ان کے گھر سے قریب تھا۔\n§وضاحت\n۱؎ : ’’كداء‘‘ : مکہ مکرمہ کا وہ جانب جو مقبرۃ المعلی کی طرف ہے اور بلند ہے۔ ۲؎ : ’’كدى‘‘ : وہ جانب ہے جو باب العمرہ کی طرف نشیب میں ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم فتح کے سال مکہ میں اس کی بالائی جانب کداء کی طرف سے داخل ہوئے تھے۔ اور عمرہ میں کدی کی طرف (زیریں جانب) سے آئے تھے۔ اور جناب عروہ دونوں راہوں سے آتے تھے۔ (کبھی اس سے اور کبھی اس سے) اور یہ (عروہ) اکثر اوقات کدی کی طرف (زیریں طرف) سے داخل ہوتے تھے۔ اور یہ جانب ان کی منزل کے زیادہ قریب تھی۔"}],[1869,"ام المؤمنین عائشہ رضی اللہ عنہا فرماتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب مکہ میں داخل ہوتے تو اس کی بلندی کی طرف سے داخل ہوتے اور اس کے نشیب سے نکلتے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب مکہ میں داخل ہوتے تو اس کی بالائی جانب سے تشریف لاتے۔ (اسی راستے میں مکہ کا معروف قبرستان ہے اور اس طرف سے آنے میں آپ صلی اللہ علیہ وسلم کو آسانی تھی اور واپسی کے لیے) زیریں جانب سے نکلتے تھے۔ (اور یہی وہ راہ ہے جس میں آج کل مقام ” جرول “ آتا ہے)۔","f2":"آمد ورفت کے راستوں میں اختلاف کے اندر شاید وہی حکمت پنہاں ہے۔جو نماز عید اور عرفات کو جانے آنے میں فرق رکھنے میں ملحوظ ہے یعنی مقامات عبادت کی کثرت کہ انسان کو قیامت کے دن زمین کے ان حصوں کی شہادت خیر بھی حاصل ہوجائے۔(تیسر العلام شرح عمدۃ الاحکام)"}],[1870,"مہاجر مکی کہتے ہیں کہ جابر بن عبداللہ رضی اللہ عنہما سے اس شخص کے بارے میں پوچھا گیا کہ جو بیت اللہ کو دیکھ کر ہاتھ اٹھاتا ہو تو انہوں نے کہا: میں سوائے یہود کے کسی کو ایسا کرتے نہیں دیکھتا تھا، اور ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کیا، لیکن آپ ایسا نہیں کرتے تھے ۱؎۔\n§وضاحت\n۱؎ :صحیح احادیث اور آثار سے بیت اللہ پر نظر پڑتے وقت ہاتھ اٹھانا ثابت ہے۔","ضعیف",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے پوچھا گیا کہ آدمی بیت اللہ کو دیکھ کر ہاتھ اٹھائے (یا نہیں؟) انہوں نے کہا: میں نے یہودیوں کے علاوہ کسی کو ایسے کرتے ہوئے نہیں دیکھا۔ (وہ لوگ بیت المقدس کو دیکھ کر ہاتھ اٹھاتے ہیں) اور ہم نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حج کیا تو آپ صلی اللہ علیہ وسلم نے ایسے نہیں کیا تھا۔","f2":"اس حدیث کی سند میں مہاجر بن عکرمہ مکی ہے۔جو کہ مجہول ہے۔اوراس مسئلے میں وار روایات میں کوئی بھی ایسی قوی نہیں ہے۔ جس سے بیت اللہ کو دیکھ کر ہاتھ اُٹھانا مشروع ثابت ہوتا ہو۔ محض دعا کرنے کے بارے میں کچھ اخبار و آثار وارد ہیں۔(نیل الاوطار 42/5) ایک روایت بیان کی جاتی ہے کہ لاترفع الايدي الا في سبع مواطن)صرف سات مقامات ایسے ہیں۔ جہاں ہاتھ اُٹھائے جایئں۔۔۔اور ان میں ایک بیت اللہ کو دیکھ کر بھی ہے۔ از حد ضعیف اور ناقابل حجت ہے۔(نصب الرایہ کتاب الصلاۃ 389/1۔حدیث 38)"}],[1871,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب مکہ میں داخل ہوئے تو بیت اللہ کا طواف کیا اور مقام ابراہیم کے پیچھے دو رکعتیں پڑھیں (یعنی فتح مکہ کے روز) ۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب مکہ میں داخل ہوئے تو بیت اللہ کا طواف کیا اور مقام ابراہیم کے پیچھے دو رکعتیں پڑھیں، یعنی فتح مکہ والے دن۔","f2":"بیت اللہ کو دیکھ کر رفع الیدین (ہاتھوں کااُٹھانا) ثابت ہوتا تو زکر کیا جاتا معلوم ہوا کہ نہیں ہے۔"}],[1872,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم آئے اور مکہ میں داخل ہوئے تو پہلے رسول اللہ صلی اللہ علیہ وسلم حجر اسود کے پاس آئے اور اس کا بوسہ لیا، پھر بیت اللہ کا طواف کیا، پھر صفا کی طرف آئے اور اس پر چڑھے جہاں سے بیت اللہ کو دیکھ رہے تھے، پھر اپنے دونوں ہاتھ اٹھا کر اللہ تعالی کا ذکر کرنے لگے اور اس کا ذکر کرتے رہے اور اس سے دعا کرتے رہے جتنی دیر تک اللہ نے چاہا، راوی کہتے ہیں: اور انصار آپ کے نیچے تھے، ہاشم کہتے ہیں: پھر آپ صلی اللہ علیہ وسلم نے دعا کی اور اللہ کی حمد بیان کی اور جو دعا کرنا چاہتے تھے کی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، پس مکہ میں داخل ہوئے، پھر حجر اسود کی طرف تشریف لائے، اسے بوسہ دیا۔ پھر بیت اللہ کا طواف کیا، پھر صفا کی جانب آئے اور اس کے اوپر چڑھ گئے جہاں سے بیت اللہ آپ کو نظر آ رہا تھا، پھر آپ نے اپنے دونوں ہاتھ اٹھا لیے اور اللہ کا ذکر کرتے رہے جس قدر کہ اللہ نے چاہا اور دعا کرتے رہے۔ اور انصار آپ کے ساتھ تھے۔ راوی حدیث ہاشم نے کہا: دعا فرمائی، اللہ کی حمد کی اور جو چاہا دعا کی۔","f2":"صفا اور مروہ پر چڑھ کر بیت اللہ کی جانب رخ کرکے ہاتھ اُٹھا کر دعا کرنا مسنون عمل ہے۔اور یہ ہاتھ اٹھانا بیت اللہ کو دیکھنے کی بناء پر نہیں بلکہ دعا کےلئے ہوتا ہے۔"}],[1873,"عمر رضی اللہ عنہ سے روایت ہے کہ وہ حجر اسود کے پاس آئے اور اسے چوما، اور کہا: میں جانتا ہوں تو ایک پتھر ہے نہ نفع پہنچا سکتا ہے نہ نقصان اور اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو تجھے چومتے نہ دیکھا ہوتا تو میں تجھے نہ چومتا ۱؎۔\n§وضاحت\n۱؎ : حجر اسود کے سلسلے میں طواف کرنے والے شخص کو اختیار ہے کہ تین باتوں چومنا، چھونا ہاتھ یا چھڑی سے، ( اشارہ کرنا) میں سے جو ممکن ہو کرلے ہر ایک کافی ہے۔","صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ وہ حجر اسود کے پاس آئے اور اس کو بوسہ دیا، پھر کہا: بلاشبہ میں جانتا ہوں کہ تو محض ایک پتھر ہی ہے، نفع دے سکتا ہے نہ نقصان اگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہ دیکھا ہوتا کہ انہوں نے تجھے بوسہ دیا تھا تو میں تجھے بوسہ نہ دیتا۔","f2":"1۔رسول اللہ صلی اللہ علیہ وسلم کے طریق (یعنی سنت مطہرہ) کا اتباع ہر حال میں مشروع اور واجب ہے۔خواہ اس کے اسباب اور علل معلوم ہوں یا نہ ہوں۔اسے کسی علت یا سبب پر مبنی قرار نہیں دیا جاسکتا اگر کوئی حکمت سمجھ میں آجائے تو فبہا ورنہ اس پرعمل بہرحال لازم ہے۔2۔حضرت عمر رضی اللہ تعالیٰ عنہ کی یہ توضیح ان نو مسلم لوگوں کےلئے تھی۔ جن کو یہ وہم ہوسکتا تھا کہ شاید یہ پتھر کوئی موثر پتھر ہے۔اس لئے اس کو چوما جارہا ہے۔3۔یہ حدیث حضرت عمر فاروق رضی اللہ تعالیٰ عنہ کے اتباع امام اعظم حضرت محمد رسول اللہ صلی اللہ علیہ وسلم پر شدید حریص ہونے کی واضح دلیل ہے۔4۔کوئی بھی پتھر شجر اور قبر وغیرہ کسی قسم کے نفع یا نقصان کاہرگز ہرگز کوئی اختیار نہیں رکھتے۔5۔ یہ حدیث دلیل ہے کہ صحابہ کرامرضوان اللہ عنہم اجمعین اپنے ایمان اور عقیدہ توحید اور جذبہ اتباع سنت میں از حد کامل تھے۔6۔شرعی دلیل کے بغیر کسی چیز کو احتراماً چومنا چاٹنا مکروہ ہے۔"}],[1874,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بیت اللہ کے کسی رکن کو چھوتے نہیں دیکھا سوائے حجر اسود اور رکن یمانی کے ۱؎۔\n§وضاحت\n۱؎ : رسول اللہ صلی اللہ علیہ وسلم کے عمل سے رکن یمانی کے سلسلے میں یہ ثابت ہے کہ آپ صلی اللہ علیہ وسلم اسے اپنے ہاتھ سے چھوتے تھے، اس کا چومنا یا اس کی طرف چھڑی یا ہاتھ سے اشارہ کرنا ثابت نہیں ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم بیت اللہ کے صرف دو یمانی ارکان ہی کو ہاتھ لگاتے تھے۔","f2":"یہاں رکن بمعنی کو نہ ہے۔کعبہ میں حجر اسود اور اس کے ساتھ والے کونے کو یمن کی جانب ہونے کی بنا پر یمانی ارکان کہا جاتا ہے۔اور دوسرے دوشامی کہلاتے ہیں۔ یمانی ارکان حضرت ابراہیم علیہ السلام کی اصل بنیادوں پر قائم ہیں۔اور شامی ارکان اپنی اصل بنیادوں پر نہیں ہیں۔"}],[1875,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہیں ام المؤمنین عائشہ رضی اللہ عنہا کا یہ قول معلوم ہوا کہ حطیم کا ایک حصہ بیت اللہ میں شامل ہے، تو ابن عمر رضی اللہ عنہما نے کہا: اللہ کی قسم! میرا گمان ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا نے اسے ضرور رسول اللہ صلی اللہ علیہ وسلم سے سنا ہو گا، میں سمجھتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان (رکن عراقی اور رکن شامی) کا استلام بھی اسی لیے چھوڑا ہو گا کہ یہ بیت اللہ کی اصلی بنیادوں پر نہ تھے اور اسی وجہ سے لوگ حطیم ۱؎ کے پیچھے سے طواف کرتے تھے۔\n§وضاحت\n۱؎ : چونکہ حطیم (کعبے کا ایک طرف چھوٹا ہوا حصہ ہے جو گول دائرے میں دیوار سے گھیر دیا گیا ہے) بھی بیت اللہ کا ایک حصہ ہے، اس لئے طواف اس کے باہر سے کرنا چاہئے، اگر کوئی طواف میں حطیم کو چھوڑ دے تو طواف درست نہ ہو گا۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ کو سیدہ عائشہ رضی اللہ عنہا ا کا یہ بیان بتایا گیا کہ حجر (حاء کے کسرہ کے ساتھ، یعنی حطیم) کا کچھ حصہ بیت اللہ میں سے ہے، تو انہوں نے کہا: قسم اللہ کی! میرا خیال ہے کہ سیدہ عائشہ رضی اللہ عنہا ا نے اگر یہ بات رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے تو میں سمجھتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم نے بھی ان (شامی) ارکان کا استلام (مس کرنا) صرف اسی لیے ترک فرمایا تھا کہ یہ بیت اللہ کی اصل بنیادوں پر نہیں ہیں۔ اور لوگ بھی حجر (حطیم) کے باہر سے اسی بنا پر طواف کرتے ہیں۔","f2":"اگر حجر اور حطیم کے اندر کی طرف سے طواف کیاجائے تو پورے بیت اللہ کاطواف نہ ہوگا۔اس لئے اس کا طواف باہر سے کرنا ضروری ہے۔"}],[1876,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رکن یمانی اور حجر اسود کا استلام کسی بھی چکر میں ترک نہیں کرتے تھے، راوی کہتے ہیں اور عبداللہ بن عمر بھی ایسا ہی کرتے تھے۔","حسن",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم طواف کے کسی چکر میں بھی رکن یمانی اور حجر اسود کا استلام (یعنی اسے مس کرنا) نہ چھوڑتے تھے۔ (نافع نے) کہا: اور سیدنا عبداللہ بن عمر رضی اللہ عنہ بھی ایسے ہی کیا کرتے تھے۔","f2":"حجر اسود کو چومنا یا ہاتھ لگا کر ہاتھ کوچومنا ہوتا ہے۔اور رکن یمانی کو صرف ہاتھ لگانا سنت ہے۔نہ کہ ہاتھ چومنا ازدحام یا کسی اور رکاوٹ کی بنا پر حجر اسود کو ہاتھ یا چھڑی سے مس کرکے اس ہاتھ یا چھڑی کو بوسہ دیا جائے یا صرف ہاتھ کا اشارہ بھی کافی ہوجاتا ہے۔ مگر رکن یمانی تک پہنچنا مشکل ہو تو ویسے ہی گزرجائے مزید کسی عمل کی ضرورت نہیں۔"}],[1877,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر اونٹ پر سوار ہو کر طواف کیا، آپ چھڑی سے حجر اسود کا استلام کر رہے تھے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع میں اونٹ پر سوار ہو کر طواف کیا۔ آپ صلی اللہ علیہ وسلم اپنے عصا سے رکن (حجر اسود) کو مس کرتے تھے۔","f2":"1۔اس سے مرُاد طواف قدوم ہے۔ امام صاحب رحمہ اللہ کی تبویب سے یہ اشارہ ملتا ہے کہ آپ اسے واجب سمجھتے ہیں۔جیسے کہ امام مالک رحمۃ اللہ علیہ اور بعض احناف کا قول ہے (عون المعبود)2۔صحیح حدیث میں نبی کریم صلی اللہ علیہ وسلم سے ثابت ہے۔کہ آپ اپنے عصا سے حجراسود کو مس کر کے اس عصا کوبوسہ بھی دیتے تھے۔(صحیح مسلم۔الحج۔حدیث 1275)3۔آپ صلی اللہ علیہ وسلم کے سوار ہوکر طواف کرنے کی حکمت یہ تھی کے لوگ آپ کے عمل کا بخوبی مشاہدہ کرلیں۔روایات میں یہ صراحت نہیں ہے کہ کونسا طواف تھا تاہم غالبا ً یہ طواف افاضہ تھا۔(بذل المجہود)کیونکہ طواف قدوم میں آپ صلی اللہ علیہ وسلم نے رمل کیا تھا۔جو پیدل کے سوا ممکن نہیں ہوتا اس حدیث سے بھی معلوم ہوا کہ پالکی یا پیے والی کرسی میں بیٹھے ہوئے کو طواف کرایا جائے تو اس کا طواف صحیح ہے۔4۔جن جانوروں کا گوشت کھایا جاتا ہے۔ان کے پیشاب کے چھینٹوں سے کپڑے ناپاک نہیں ہوتے۔"}],[1878,"صفیہ بنت شیبہ رضی اللہ عنہا کہتی ہیں کہ فتح مکہ کے سال رسول اللہ صلی اللہ علیہ وسلم کو جب مکہ میں اطمینان ہوا تو آپ نے اونٹ پر سوار ہو کر طواف کیا، آپ صلی اللہ علیہ وسلم اپنے ہاتھ کی چھڑی سے حجر اسود کا استلام کر رہے تھے، اور میں آپ کو دیکھ رہی تھی۔","حسن",{"u2":"سیدہ صفیہ بنت شیبہ رضی اللہ عنہا ا بیان کرتی ہیں کہ فتح مکہ کے سال جب رسول اللہ صلی اللہ علیہ وسلم کو مکہ میں اطمینان حاصل ہو گیا تو آپ صلی اللہ علیہ وسلم نے اپنے اونٹ پر (سوار ہو کر) طواف کیا۔ کہتی ہیں کہ میں آپ صلی اللہ علیہ وسلم کو دیکھ رہ تھی کہ آپ صلی اللہ علیہ وسلم اپنے عصا سے رکن (حجر اسود) کا استلام فرماتے تھے۔"}],[1879,"ابوطفیل رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو اپنی سواری پر بیٹھ کر بیت اللہ کا طواف کرتے دیکھا، آپ حجر اسود کا استلام اپنی چھڑی سے کرتے پھر اسے چوم لیتے، (محمد بن رافع کی روایت میں اتنا زیادہ ہے) پھر آپ صلی اللہ علیہ وسلم صفا و مروہ کی طرف نکلے اور اپنی سواری پر بیٹھ کر سعی کے سات چکر لگائے۔","صحیح",{"u2":"سیدنا ابوالطفیل (عامر بن واثلہ) رضی اللہ عنہ کہتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا آپ صلی اللہ علیہ وسلم اپنی سواری پر سوار بیت اللہ کا طواف کر رہے تھے۔ اپنے عصا سے رکن (حجر اسود) کا استلام کرتے تھے اور پھر اسے بوسہ دیتے تھے۔ محمد بن رافع نے مزید کہا: پھر آپ صلی اللہ علیہ وسلم صفا مروہ کی طرف تشریف لے گئے اور اپنی سواری پر ان کے مابین سات چکر لگائے۔"}],[1880,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے حجۃ الوداع میں اپنی سواری پر بیٹھ ہو کر بیت اللہ کا طواف کیا، اور صفا و مروہ کی سعی کی، تاکہ آپ صلی اللہ علیہ وسلم بلندی پر ہوں، اور لوگ آپ کو دیکھ سکیں، اور آپ سے پوچھ سکیں، کیونکہ لوگوں نے آپ کو گھیر رکھا تھا۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے حجۃ الوداع میں اپنی سواری پر سوار ہو کر بیت اللہ کا طواف کیا اور صفا مروہ کی سعی کی تاکہ لوگ آپ صلی اللہ علیہ وسلم کو دیکھ لیں اور آپ صلی اللہ علیہ وسلم ان سے بلند رہیں اور وہ آپ صلی اللہ علیہ وسلم سے (مسائل) دریافت کر سکیں کیونکہ لوگوں نے آپ صلی اللہ علیہ وسلم کو گھیر رکھا تھا۔"}],[1881,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مکہ آئے آپ کو کچھ تکلیف تھی چنانچہ آپ نے اپنی سواری پر بیٹھ کر طواف کیا ۱؎، جب آپ صلی اللہ علیہ وسلم حجر اسود کے پاس آتے تو چھڑی سے اس کا استلام کرتے، جب آپ طواف سے فارغ ہو گئے تو اونٹ کو بٹھا دیا اور (طواف کی) دو رکعتیں پڑھیں۔\n§وضاحت\n۱؎ : اس حدیث کی بخاری نے (حج ۷۴ میں) خالدالحذاء کے طریق سے روایت کی ہے مگر اس میں «وهو يشتكي» (تکلیف تھی) کا لفظ نہیں ہے، خالد ثقہ ہیں جب کہ یزید ضعیف ہیں، اسی لئے امام بخاری نے ان کی روایت نہیں لی ہے، مگر تبویب سے اشارہ اسی طرف کیا ہے، بہرحال سواری پر طواف کے متعدد اسباب ہو سکتے ہیں بلا سبب افضل نہیں ہے، خصوصا مسجد اور مطاف بن جانے کے بعد اب یہ ممکن نہیں رہا، نیز دیکھئے حاشیہ حدیث نمبر (۱۸۸۲)۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکہ مکرمہ تشریف لائے تو آپ صلی اللہ علیہ وسلم کی طبیعت ناساز تھی چنانچہ آپ صلی اللہ علیہ وسلم نے اپنی سواری پر (سوار ہو کر) طواف کیا۔ آپ صلی اللہ علیہ وسلم جب بھی حجر اسود کے پاس آتے تو اپنے عصا سے اس کو مس کرتے۔ پس جب آپ صلی اللہ علیہ وسلم اپنے طواف سے فارغ ہو گئے تو آپ صلی اللہ علیہ وسلم نے (اپنی اونٹنی کو) بٹھا دیا اور دو رکعتیں ادا کیں۔"}],[1882,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے شکایت کی کہ میں بیمار ہوں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سوار ہو کر لوگوں کے پیچھے طواف کر لو ۱؎\"، تو میں نے طواف کیا اور آپ خانہ کعبہ کے پہلو میں اس وقت نماز پڑھ رہے تھے، اور «الطور * وكتاب مسطور» کی تلاوت فرما رہے تھے۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ بیماری اور کمزوری کی حالت میں سوار ہو کر طواف کرنا درست ہے، اور آج کل سواری پر طواف چوں کہ ناممکن ہے اس لئے اس کی جگہ پر مخصوص لوگ حجاج کو چارپائی پر بٹھا کر طواف کراتے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا سے روایت ہے وہ کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کہا کہ میری طبیعت خراب ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا ” سواری پر بیٹھ کر لوگوں کے پیچھے سے طواف کر لو۔ “ کہتی ہیں: چنانچہ میں نے طواف کیا اور رسول اللہ صلی اللہ علیہ وسلم اس وقت بیت اللہ کے پہلو میں نماز پڑھا رہے تھے اور آپ صلی اللہ علیہ وسلم «والطور وكتاب مسطور» کی قرآت فر رہے تھے۔میں نے رسول اللہ صلی اللہ علیہ وسلم سے کہا کہ میری طبیعت خراب ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا ” سواری پر بیٹھ کر لوگوں کے پیچھے سے طواف کر لو۔ “ کہتی ہیں: چنانچہ میں نے طواف کیا اور رسول اللہ صلی اللہ علیہ وسلم اس وقت بیت اللہ کے پہلو میں نماز پڑھا رہے تھے اور آپ صلی اللہ علیہ وسلم «والطور وكتاب مسطور» کی قرآت فر رہے تھے۔","f2":"سواری پر طواف کرنا رسول اللہ صلی اللہ علیہ وسلم کی خصوصیت نہ تھی بلکہ ہر صاحب عذر کو اس کی رخصت حاصل ہے۔2۔طواف میں عورتوں کو حتیٰ الامکان اختلاط سے بچنا چاہیے۔3۔عورتوں کو مردوں کی جماعت میں شریک ہونا واجب نہیں ہے۔"}],[1883,"یعلی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ہری چادر میں اضطباع کر کے طواف کیا ۱؎۔\n§وضاحت\n۱؎ : اضطباع کی شکل یہ ہے کہ محرم چادر کو دائیں بغل کے نیچے سے گزار کر بائیں کندھے پر ڈال دے اور دایاں کندھا ننگا رکھے، اور یہ صرف پہلے طواف میں ہے۔","حسن",{"u2":"سیدنا یعلیٰ بن امیہ رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے طواف کیا جبکہ آپ صلی اللہ علیہ وسلم اضطباع کیے ہوئے تھے اور چادر سبز رنگ کی تھی۔","f2":"1۔احرام کے لئے ضروری نہیں کہ چادرسفید ہی ہو دوسرے رنگ کے کپڑے میں بھی جائز ہی ہے۔ صرف زرد رنگ ناپسندیدہ ہے۔ جب کہ سفید اور افضل اور مستحب ہے۔2۔طواف شروع کرتے ہوئے اپنے اوپر کی چادر کو دایئں بغل کے نیچے سے نکال کربایئں کندھے پر ڈال لینا اضطباع کہلاتا ہے۔ یہ عمل صرف طواف قدوم میں ثابت ہے۔ جس میں رمل کیا جاتا ہے خیال رہے کہ اضطباع صرف طواف قدوم میں کرنا ہے۔اس کی مشروعیت کا مقصود رمل کی طرح قوت کا اظہار تھا۔اس کے بعدنماز اور دیگر اعمال میں اضطباع نہیں کیا جاتا۔"}],[1884,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ نے جعرانہ سے عمرہ کا احرام باندھا تو بیت اللہ کے طواف میں رمل ۱؎ کیا اور اپنی چادروں کو اپنی بغلوں کے نیچے سے نکال کر اپنے بائیں کندھوں پر ڈالا۔\n§وضاحت\n۱؎ : اکڑ کر مونڈھے ہلاتے ہوئے چلنا جیسے سپاہی جنگ کے لئے چلتا ہے، اور یہ صرف پہلے تین چکروں میں ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ نے مقام جعرانہ سے (احرام باندھ کر) عمرہ کیا، تو بیت اللہ میں انہوں نے رمل کیا اور اپنی چادروں کو اپنی بغلوں کے نیچے سے بائیں کندھوں پر ڈال لیا۔","f2":"جعرانہ ایک مقام کانام ہے۔اس کو کئی طرح پڑھا گیا ہے۔ان میں سے ایک یہ ہے کہ جیم اور عین دونوں مکسور جب کہ رامشد ومفتوح ہے یہ طائف کی جانب سے میقات احرام ہے۔نبی کریم صلی اللہ علیہ وسلم کا یہ عمرہ غزوہ حنین وطائف کے بعد ماہ زوالعقدہ سن آٹھ ہجری میں ہوا تھا۔"}],[1885,"ابوطفیل کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما سے کہا: آپ کی قوم سمجھتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیت اللہ کے طواف میں رمل کیا اور یہ سنت ہے، انہوں نے کہا: لوگوں نے سچ کہا اور جھوٹ اور غلط بھی، میں نے دریافت کیا: لوگوں نے کیا سچ کہا اور کیا جھوٹ اور غلط؟ فرمایا: انہوں نے یہ سچ کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے رمل کیا لیکن یہ جھوٹ اور غلط کہا کہ رمل سنت ہے (واقعہ یہ ہے) کہ قریش نے حدیبیہ کے موقع پر کہا کہ محمد اور اس کے ساتھیوں کو چھوڑ دو وہ اونٹ کی موت خود ہی مر جائیں گے، پھر جب ان لوگوں نے آپ صلی اللہ علیہ وسلم سے اس شرط پر مصالحت کر لی کہ آپ آئندہ سال آ کر حج کریں اور مکہ میں تین دن قیام کریں تو رسول اللہ صلی اللہ علیہ وسلم آئے اور مشرکین بھی قعیقعان کی طرف سے آئے، آپ صلی اللہ علیہ وسلم نے اپنے اصحاب سے فرمایا: \"تین پھیروں میں رمل کرو\"، اور یہ سنت نہیں ہے ۱؎، میں نے کہا: آپ کی قوم سمجھتی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صفا و مروہ کے درمیان اونٹ پر سوار ہو کر سعی کی اور یہ سنت ہے، وہ بولے: انہوں نے سچ کہا اور جھوٹ اور غلط بھی، میں نے دریافت کیا: کیا سچ کہا اور کیا جھوٹ؟ وہ بولے: یہ سچ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صفا و مروہ کے درمیان اپنے اونٹ پر سوار ہو کر سعی کی لیکن یہ جھوٹ اور غلط ہے کہ یہ سنت ہے، دراصل لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے نہ جا رہے تھے اور نہ سرک رہے تھے، تو آپ صلی اللہ علیہ وسلم نے اونٹ پر سوار ہو کر سعی کی تاکہ لوگ آپ کی بات سنیں اور لوگ آپ کو دیکھیں اور ان کے ہاتھ آپ تک نہ پہنچ سکیں۔\n§وضاحت\n۱؎ : مراد ایسی سنت نہیں ہے جسے آپ صلی اللہ علیہ وسلم نے تقرب کے لئے بطور عبادت کی ہو، بلکہ مسلمانوں کو یہ حکم آپ صلی اللہ علیہ وسلم نے اس لئے دیا تھا تاکہ وہ کافروں کے سامنے اپنے طاقتور اور توانا ہونے کا مظاہرہ کر سکیں، کیونکہ وہ اس غلط فہمی میں مبتلا تھے کہ مدینہ کے بخار نے انہیں کمزور کر رکھا ہے، لیکن بہرحال اب یہ طواف کی سنتوں میں سے ہے جس کے ترک پر دم نہیں۔","صحیح",{"u2":"سیدنا ابوالطفیل رضی اللہ عنہ کہتے ہیں کہ میں نے سیدنا ابن عباس رضی اللہ عنہ سے کہا: آپ کی قوم کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بیت اللہ میں رمل کیا تھا اور یہ کہ یہ سنت ہے۔ تو وہ بولے کہ انہوں نے سچ کہا ہے اور کچھ غلط۔ میں نے کہا: (کیا مطلب) کیا سچ کہا اور کیا غلط؟ فرمایا: یہ تو سچ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمل کیا تھا، مگر سنت کہنا غلط ہے۔ درحقیقت قریش نے حدیبیہ کے زمانے میں کہا تھا کہ محمد (صلی اللہ علیہ وسلم) اور ان کے اصحاب کو چھوڑ دو حتیٰ کہ وہ خود ہی جانوروں کی موت مر جائیں گے۔ (جیسے اونٹوں کی ناکوں میں کیڑے پڑ جاتے ہیں اور پھر وہ ہلاک ہو جاتے ہیں۔) پھر جب انہوں نے آپ صلی اللہ علیہ وسلم سے صلح کر لی کہ یہ لوگ اگلے سال آئیں اور مکہ میں تین دن ٹھہریں، چنانچہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو مشرکین کوہ قعیقعان کی جانب (سے دیکھ رہے) تھے۔ تب آپ صلی اللہ علیہ وسلم نے اپنے اصحاب سے فرمایا ” بیت اللہ کے گرد تین چکر رمل کرو۔“ (یعنی کندھے ہلا ہلا کر آہستہ آہستہ دوڑو) اور یہ کوئی سنت نہیں ہے۔ میں نے کہا: آپ کی قوم کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صفا اور مروہ کی سعی اونٹ پر سوار ہو کر کی تھی اور یہ بھی سنت ہے۔ تو وہ بولے کہ انہوں نے سچ کہا ہے اور کچھ غلط۔ میں نے کہا: کیا سچ ہے اور کیا غلط؟ فرمایا: سچ یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صفا اور مروہ کی سعی اونٹ پر کی تھی مگر یہ سنت ہو، غلط ہے۔ (دراصل) لوگوں کو رسول اللہ صلی اللہ علیہ وسلم سے دور نہ کیا جاتا تھا اور نہ ہٹایا جاتا تھا (جب کہ وہ آپ صلی اللہ علیہ وسلم پر ہجوم کیے ہوئے تھے) تو آپ صلی اللہ علیہ وسلم نے اونٹ پر سوار ہو کر سعی کی تاکہ وہ آپ صلی اللہ علیہ وسلم کی بات سن سکیں، آپ صلی اللہ علیہ وسلم کو دیکھ سکیں اور ان کے ہاتھ آپ صلی اللہ علیہ وسلم تک نہ پہنچ پائیں۔","f2":"-1طواف قدوم میں پہلے تین چکروں میں کندھے ہلا ہلاکر آہستہ آہستہ دوڑنارمل کہلاتا ہے۔اور یہ ثابت شدہ سنت ہے۔طواف قدوم کے بعد کسی اور طواف میں یہ عمل ثابت نہیں۔ نیز عورتوں کےلئے رمل نہیں ہے۔2۔رمل مشروع ہونے کی اصل بنا یہی ہے۔ جو حضرت ابن عباس رضی اللہ تعالیٰ عنہ کی روایات میں بیان ہوئی ہے۔ مگر یہ کہنا کہ یہ سنت نہیں ہے۔محل نظر ہے یہ ان کا اپنا خیال ہے۔ اورشاید اس سے ان کی مُراد سنت واجبہ کی نفی ہے۔اورحقیقت بھی یہی ہے کہ یہ عمل مسنون ومستحب ہے۔ اگر کسی سے یہ رہ جائے تو آخر کے چار چکروں میں اس کا تدارک کرناجائز نہیں ہے۔(نیل الاوطار)اگر یہ عمل وقتی ہوتا تو بعد کے عمروں اور حجۃ الوداع میں اس پر عمل نہ کیاجاتا۔عمرہ قضا سن 7 ہجری میں ہوا ہے۔جس میں رمل کی ابتداء ہوئی تھی۔ پھر سن آٹھ ہجری میں عمرہ جعرانہ میں بھی صحابہ کرامرضوان اللہ عنہم اجمعین نے رمل کیا۔اور یہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ ہی کی روایت ہے۔جواوپر گزری ہے۔(حدیث 1884) بعد ازاں دس ہجری میں حجۃ الوداع میں بھی یہ عمل ثابت ہے۔اور سواری پر سوار ہوکرطواف وسعی بلاشبہ عذر پر ہی مبنی ہے۔ کہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چمٹے ہوئے تھے۔دور نہ ہوتے تھے اور ان کو زور سے دور کرنا اور ہٹانا نبی کریم صلی اللہ علیہ وسلم کو پسند نہ تھا تو آپ سوار ہوگئے تاکہ آپ انہیں مناسک حج کی تعلیم دے سکیں۔ مسائل سمجھا سکیں اور لوگ بھی آپ کے عمل کامشاہدہ کرسکیں۔"}],[1886,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مکہ آئے اور لوگوں کو مدینہ کے بخار نے کمزور کر دیا تھا، تو مشرکین نے کہا: تمہارے پاس وہ لوگ آ رہے ہیں جنہیں بخار نے ضعیف بنا دیا ہے، اور انہیں بڑی تباہی اٹھانی پڑی ہے، تو اللہ تعالی نے اپنے نبی اکرم صلی اللہ علیہ وسلم کو ان کی اس گفتگو سے مطلع کر دیا، تو آپ نے حکم دیا کہ لوگ (طواف کعبہ کے) پہلے تین پھیروں میں رمل کریں اور رکن یمانی اور حجر اسود کے درمیان عام چال چلیں، تو جب مشرکین نے انہیں رمل کرتے دیکھا تو کہنے لگے: یہی وہ لوگ ہیں جن کے متعلق تم لوگوں نے یہ کہا تھا کہ انہیں بخار نے کمزور کر دیا ہے، یہ لوگ تو ہم لوگوں سے زیادہ تندرست ہیں۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: آپ صلی اللہ علیہ وسلم نے انہیں تمام پھیروں میں رمل نہ کرنے کا حکم صرف ان پر نرمی اور شفقت کی وجہ سے دیا تھا ۱؎۔\n§وضاحت\n۱؎ : کیونکہ فی الواقع یہ لوگ کمزور اور دبلے پتلے تھے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم مکہ میں تشریف لائے جبکہ ان لوگوں کو یثرب (مدینہ کا سابقہ نام) کے بخار نے کمزور کر دیا تھا تو مشرکین نے کہا: تمہارے پاس ایک ایسی قوم آ رہی ہے جسے بخار نے نڈھال کر دیا ہے اور انہیں اس سے بڑی اذیت پہنچی ہے۔ اللہ تعالیٰ نے مشرکین کی اس بات سے جو انہوں نے کہی، اپنے نبی کریم صلی اللہ علیہ وسلم کو مطلع فر دیا۔ پس آپ نے انہیں حکم دیا کہ تین چکروں میں رمل کریں اور رکن یمانی اور حجر اسود کے درمیان عام رفتار سے چلیں۔ سو جب انہوں نے ان لوگوں کہ رمل کرتے دیکھا (کہ بڑی پھرتی سے طواف کر رہے ہیں) تو کہنے لگے: انہی لوگوں کے بارے میں تم کہتے ہو کہ ان کو بخار نے کمزور کر دیا ہے، یہ تو ہم سے زیادہ طاقتور ہیں۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا: آپ صلی اللہ علیہ وسلم نے صحابہ پر شفقت فرماتے ہوئے طواف کے سب چکروں میں رمل کا حکم نہیں دیا تھا۔","f2":"کفر وکفار کو زیر رکھنے اور ان پرمسلمانوں کارعب اور دبدبہ قائم رکھنے کے لئے مختلف مناسب مواقع پراپنے شباب وقوت کا اظہار ومظاہرہ کرنا شرعا مطلوب ہے۔"}],[1887,"اسلم کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو کہتے سنا: اب رمل اور مونڈھے کھولنے کی کیا ضرورت ہے؟ اب تو اللہ نے اسلام کو مضبوط کر دیا ہے اور کفر اور اہل کفر کا خاتمہ کر دیا ہے، اس کے باوجود ہم ان باتوں کو نہیں چھوڑیں گے جو رسول اللہ صلی اللہ علیہ وسلم کے وقت میں کیا کرتے تھے ۱؎۔\n§وضاحت\n۱؎ : معلوم ہوا کہ شرع کی جس بات کی علت و حکمت سمجھ میں نہ آئے اس کو علی حالہ چھوڑ دینا چاہئے، کیونکہ ایسی صورت میں سب سے بڑی حکمت یہ ہے کہ یہ اللہ کے رسول کی اتباع ہے۔","حسن صحیح",{"u2":"جناب اسلم عدوی کہتے ہیں کہ میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے سنا فرماتے تھے: آج یہ کندھے ہلا ہلا کر دوڑنا اور ان کا ننگا کرنا کیوں ہے؟ (اس کی کوئی ضرورت تو نہیں ہے) حالانکہ اللہ تعالیٰ نے اسلام کو قوی اور مضبوط بنا دیا ہے اور کفر و کفار کو یہاں سے نکال باہر کیا ہے۔ اس کے باوجود ہم یہ عمل نہیں چھوڑ سکتے جو رسول اللہ صلی اللہ علیہ وسلم کے دور میں کیا کرتے تھے۔","f2":"اس حدیث سے جناب امیر المومنین خلیفہ ثانی عمرفاروق رضی اللہ تعالیٰ عنہ کی عظیم منکبت ار سنت رسول صلی اللہ علیہ وسلم کے ساتھ والہانہ لگائواورعقیدت ثابت ہوتی ہے۔وللہ درۃ2۔بعض اعمال شرعیہ کی اصل بنا خواہ کوئی وقتی اسباب بھی ہوں۔ مگر چونکہ رسول اللہ صلی اللہ علیہ وسلم نے تعلیم فرمائی ہے۔ اس لئے ہمیں ان کاکرنا لازم ہے۔خواہ اب وہ اسباب موجود ہوں یانہ ہوں۔مثلا یہی رمل کا عمل یا جمعہ کے روز کاغسل ہے۔ کے ابتداء محض نظافت کی بنا ءپر مشروع کیا گیا تھا لیکن اب واجب یامستحب ہے۔"}],[1888,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیت اللہ کا طواف کرنا اور صفا و مروہ کے درمیان سعی کرنا اور کنکریاں مارنا، یہ سب اللہ کی یاد قائم کرنے کے لیے مقرر کئے گئے ہیں\"۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بیت اللہ کا طواف، صفا مروہ کی سعی اور جمرات کو کنکریاں مارنا، یہ سب اللہ کا ذکر قائم کرنے کے لیے ہیں۔ “"}],[1889,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اضطباع کیا، پھر استلام کیا، اور تکبیر بلند کی، پھر تین پھیروں میں رمل کیا، جب لوگ (یعنی صحابہ کرام رضی اللہ عنہم) رکن یمانی پر پہنچتے اور قریش کی نظروں سے غائب ہو جاتے تو عام چال چلتے پھر جب ان کے سامنے آتے تو رمل کرتے، قریش کہتے تھے: گویا یہ ہرن ہیں، ابن عباس رضی اللہ عنہما کہتے ہیں: تو یہ فعل سنت ہو گیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اضطباع کیا۔ (اپنی چادر کو اپنی دائیں بغل کے نیچے سے نکال کر بائیں کندھے پر ڈال لیا۔) پھر (حجر اسود کا) استلام کیا اور «الله اكبر» کہا۔ پھر تین چکروں میں رمل کیا۔ صحابہ جب رکن یمانی کے پاس پہنچتے اور قریش کی نظروں سے اوجھل ہو جاتے تو عام رفتار سے چلنے لگتے۔ پھر جب ان کے سامنے آتے تو آہستہ آہستہ دوڑنے لگتے۔ قریش کہنے لگے: یہ تو گویا ہرن ہیں۔ سیدنا ابن عباس رضی اللہ عنہ نے کہا (تب سے) یہ سنت ہے۔"}],[1890,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ نے جعرانہ سے عمرہ کا احرام باندھا تو بیت اللہ کے تین پھیروں میں رمل کیا اور چار میں عام چال چلی۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ نے جعرانہ سے عمرہ کیا تو انہوں نے بیت اللہ میں رمل کیا اور (آخری) چار چکروں میں عام رفتار سے چلے۔"}],[1891,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما نے حجر اسود سے حجر اسود تک رمل کیا، اور بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسا کیا ہے۔","صحیح",{"u2":"نافع بیان کرتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہ نے حجر اسود سے حجر اسود تک رمل کیا۔ (یعنی پورے چکر میں) اور ذکر کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ عمل کیا تھا۔","f2":"حضرت عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ کی اس حدیث اور حضرت عبد اللہ بن عباس رضی اللہ تعالیٰ عنہ سے مروی مذکورہ بالا حدیث میں جمع اور تطبیق یہ ہے۔ کہ حضرت ابن عباس رضی اللہ تعالیٰ عنہ کا یہ بیان عمرۃ القضا ء کے متعلق ہے۔جو ہجرت کے ساتویں سال فتح مکہ سے قبل کیا گیا تھا۔اسوقت رمل حجر اسودسے رکن یمانی تک کیا گیا تھا۔رکن یمانی اور حجر اسود کے درمیان رمل نہیں کیاگیا تھا۔ جب کہ سیدنا عبد اللہ ابن عمر رضی اللہ تعالیٰ عنہ کی حدیث میں جوکچھ بیان ہوا ہے۔ یہ حجۃ الوداع کاواقعہ ہے۔ لہذا یہ بعد والی حدیث ابن عباس رضی اللہ تعالیٰ عنہ کی پہلی والی حدیث کی ناسخ ہے۔ مزید براں عمرۃ القضا اور حجۃ الوداع کے موقع پر کئے جانے والے دونوں رمل میں ایک بہت بڑا اور بنیادی فرق ہے۔ وہ یہ کہ عمرۃ القضا میں صرف مشرکین کو دکھانے اور اپنے آپ کو ان کی سوچ کے برعکس طاقتورظاہر کرنے کے لئے رمل کیا گیا تھا۔ حالانکہ اس وقت مسلمان جسمانی طور پر کمزور تھے۔ جب کہ حجۃ الوداع کے موقع پر ایسی کوئی بات نہیں تھی۔اس موقع پر مشرکین کوکچھ دکھانا مقصود تھا نہ نہ اپنی طاقت کا اظہار ہی بلکہ اس وقت صرف اور صرف رسول اللہ صلی اللہ علیہ وسلم کااتباع کرتے ہوئے رمل کیا گیا تھا۔اس لئے حجر اسودسے لے کر حجر اسود تک یعنی پورے چکر میں رمل کیا گیا۔واللہ اعلم۔"}],[1892,"عبداللہ بن سائب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دونوں رکن (یعنی رکن یمانی اور حجر اسود) کے درمیان«ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار» (سورۃ البقرہ: ۹۶) کہتے سنا، \"اے ہمارے رب! ہمیں دنیا میں بھلائی عطا فرما، اور آخرت میں بھی، اور ہمیں جہنم کے عذاب سے بچا لے\"۔","حسن",{"u2":"سیدنا عبداللہ بن سائب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا آپ صلی اللہ علیہ وسلم رکن یمانی اور حجر اسود کے مابین یہ دعا پڑھ رہے تھے &lt;قرآن&gt; &laquo;ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار&raquo; &lt;/قرآن&gt; &rdquo; اے ہمارے رب ہمیں دنیا میں خیر و بھلائی عنایت فر اور آخرت میں بھی خیر و بھلائی دے اور ہمیں آگ کے عذاب سے محفوظ رکھ۔","f2":"طواف میں رسول اللہ صلی اللہ علیہ وسلم سے یہی دعا صحیح ثابت ہے۔علاوہ ازیں جو چاہے دعا کرسکتا ہے مگر ہر چکر کے لئے الگ الگ مخصوص دعا نہیں ہے۔"}],[1893,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم آتے ہی سب سے پہلے جب حج و عمرہ کا طواف کرتے تو آپ تین پھیروں میں دوڑ کر چلتے اور باقی چار میں معمولی چال چلتے، پھر دو رکعتیں پڑھتے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حج اور عمرہ میں (مکہ میں) آتے ہی جو پہلا طواف (طواف قدوم) کرتے تو اس کے تین چکروں میں (آہستہ آہستہ) دوڑتے اور چار میں عام رفتار سے چلتے، پھر دو رکعتیں ادا کرتے۔"}],[1894,"جبیر بن مطعم رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس گھر (کعبہ) کا طواف کرنے اور نماز پڑھنے سے کسی کو مت روکو، رات اور دن کے جس حصہ میں بھی وہ کرنا چاہے کرنے دو\"۔ فضل کی روایت کے میں ہے: «إن رسول الله صلی اللہ علیہ وسلم قال يا بني عبد مناف لا تمنعوا أحدا» \"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اے بنی عبد مناف! کسی کو مت روکو\"۔","صحیح",{"u2":"سیدنا جبیر بن مطعم رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” کسی کو منع مت کرو جس وقت بھی کوئی اس گھر کا طواف کرنا چاہے اور نماز پڑھنا چاہے (تو پڑھنے دو۔) دن ہو یا رات، خواہ کوئی وقت ہو۔ “ فضل بن یعقوب نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے (خطاب کرتے ہوئے فرمایا) ” اے بنی عبدمناف! کسی کو منع مت کرو۔ “","f2":"چونکہ صحیح احادیث میں ایک عام حکم وارد ہے۔کہ نماز فجر کے بعد نماز نہیں حتیٰ کہ سورج خوب اچھی طرح واضح ہوجائے اور عصر کے بعد نماز نہیں حتیٰ کے سورج غروب ہوجائے۔(صحیح البخاری۔مواقیت الصلاۃ حدیث 586 وصحیح مسلم صلاۃ المسافرین حدیث 827) اس لئے یہ فرمان اس کا مخصص ہے کہ بیت اللہ میں عصر کے بعد اور اسی طرح فجر کے بعدطواف جائز ہے۔چنانچہ اس کے بعد ان ممنوعہ اوقات میں طواف کی رکعتیں بھی جائز ہوں گی۔"}],[1895,"ابوزبیر کہتے ہیں کہ میں نے جابر بن عبداللہ رضی اللہ عنہما کو کہتے سنا کہ نبی اکرم صلی اللہ علیہ وسلم اور آپ کے صحابہ نے (جنہوں نے قران کیا تھا) صفا اور مروہ کے درمیان صرف ایک ہی سعی کی اپنے پہلے طواف کے وقت۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم اور آپ صلی اللہ علیہ وسلم کے صحابہ نے صفا اور مروہ کے مابین ایک ہی بار سعی کی تھی۔ یعنی پہلی بار طواف قدوم یا طواف عمرہ کے ساتھ۔","f2":"قارن یعنی وہ شخص جس نے عمرے اور حج کا اکھٹے احرام باندھا ہو۔"}],[1896,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے اصحاب نے جو آپ کے ساتھ تھے، اس وقت تک طواف نہیں کیا جب تک کہ ان لوگوں نے رمی جمار نہیں کر لیا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ اصحاب رسول اللہ صلی اللہ علیہ وسلم جو آپ صلی اللہ علیہ وسلم کے ساتھ تھے انہوں نے جمرہ کو کنکریاں مارنے کے بعد ہی طواف کیا تھا۔","f2":"یہ روایت گزشتہ حدیث (1781) کا ایک حصہ ہے۔اور اس سے مُراد بیت اللہ کاطواف ہے۔جوقرآن والوں نے کیا تھا۔"}],[1897,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"بیت اللہ کا تمہارا طواف اور صفا و مروہ کی سعی حج و عمرہ دونوں کے لیے کافی ہے\"۔ شافعی کہتے ہیں: سفیان نے اس روایت کو کبھی عطاء سے اور انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے روایت کیا ہے، اور کبھی عطاء سے مرسلاً روایت کیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عائشہ رضی اللہ عنہا سے فرمایا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا تھا ” تیرا بیت اللہ کا طواف اور صفا مروہ کی سعی، تیرے حج اور عمرے (دونوں) کو کافی ہے۔ “ امام شافعی رضی اللہ عنہ نے کہا کہ سفیان (بن عیینہ) کبھی سند یوں بیان کرتے «عن عطاء، عن عائشة» اور کبھی یوں کہتے «عن عطاء، أن النبي صلى الله عليه وسلم قال لعائشة»۔","f2":"حضرت عائشہ رضی اللہ تعالیٰ عنہا نے شروع میں عمرے کا احرام باندھا تھا مگر حیض کے عارضے کی بنا پر رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا کہ اپنے عمرے کو چھوڑ کراب حج کی نیت کرلو اور حج کے اعمال ادا کرلو۔اس طرح وہ قارن ہوگئیں۔اور پھر انہوں نے دسویں زی الحجہ کو جو طواف افاضہ (زیارہ) اورسعی کی اسے ہی نبی کریم صلی اللہ علیہ وسلم نے عمرے اور حج دونوں کے لئے کافی قرار دے دیا۔"}],[1898,"عبدالرحمٰن بن صفوان رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ فتح کیا تو میں نے کہا: میں اپنے کپڑے پہنوں گا(میرا گھر راستے میں تھا) پھر میں دیکھوں گا کہ رسول اللہ صلی اللہ علیہ وسلم کیا کرتے ہیں، تو میں گیا تو نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ اور آپ کے صحابہ کعبۃ اللہ کے اندر سے نکل چکے ہیں اور سب لوگ بیت اللہ کے دروازے سے لے کر حطیم تک کعبہ سے چمٹے ہوئے ہیں، انہوں نے اپنے رخسار بیت اللہ سے لگا دئیے ہیں اور رسول اللہ صلی اللہ علیہ وسلم ان سب کے بیچ میں ہیں۔\n§وضاحت\n۱؎ : ’’ملتزم‘‘: کعبہ کا وہ حصہ جو حجر اسود اور کعبہ کے دروازے کے درمیان واقع ہے، لوگ اس سے چمٹ کر دعا مانگتے ہیں۔","ضعیف",{"u2":"سیدنا عبدالرحمٰن بن صفوان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جب مکہ فتح کیا تو میں نے کہا: میں اپنے کپڑے ضرور پہنوں گا، میرا گھر راستے ہی پر تھا اور بالضرور دیکھوں گا کہ رسول اللہ صلی اللہ علیہ وسلم کیسے کرتے ہیں۔ چنانچہ میں چلا اور نبی کریم صلی اللہ علیہ وسلم کو دیکھا کہ آپ اور آپ کے صحابہ کعبہ کے اندر سے نکل چکے تھے اور دروازے سے حطیم تک بیت اللہ کے ساتھ چمٹے ہوئے تھے۔ انہوں نے اپنے رخسار کعبے کے ساتھ لگائے ہوئے تھے اور رسول اللہ صلی اللہ علیہ وسلم ان کے درمیان میں تھے۔","f2":"بیت اللہ کے دروازے اور حجر اسود کے درمیان بیت اللہ کی دیوار سے چمٹنے کی جگہ کوملتزم کہتے ہیں۔"}],[1899,"شعیب بن محمد بن عبداللہ بن عمرو بن العاص کہتے ہیں کہ میں نے عبداللہ بن عمرو رضی اللہ عنہما کے ساتھ طواف کیا، جب ہم لوگ کعبہ کے پیچھے آئے تو میں نے کہا: کیا آپ پناہ نہیں مانگیں گے؟ اس پر انہوں نے کہا: ہم پناہ مانگتے ہیں اللہ کی آگ سے، پھر وہ آگے بڑھتے رہے یہاں تک کہ انہوں نے حجر اسود کا استلام کیا، اور حجر اسود اور کعبہ کے دروازے کے درمیان کھڑے رہے اور اپنا سینہ، اپنے دونوں ہاتھ اپنی دونوں ہتھیلیاں اس طرح رکھیں اور انہوں نے انہیں پوری طرح پھیلایا، پھر بولے: اسی طرح میں نے رسول اللہ صلی اللہ علیہ وسلم کو کرتے دیکھا ہے ۱؎۔\n§وضاحت\n۱؎ : یعنی آپ صلی اللہ علیہ وسلم ملتزم سے چمٹے ہوئے تھے۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد (شعیب بن محمد بن عبداللہ بن عمرو) سے بیان کرتے ہیں کہ میں نے سیدنا عبداللہ بن عمرو رضی اللہ عنہ کے ساتھ طواف کیا۔ جب ہم کعبہ کے پیچھے کی جانب آئے تو میں نے کہا: کیا آپ تعوذ نہیں کرتے۔ انہوں نے کہا: ہم اللہ کی پناہ چاہتے ہیں دوزخ سے۔ پھر چلتے آئے حتیٰ کہ حجر اسود کا استلام کیا اور حجر اسود اور دروازے کے درمیان رک گئے پھر اپنا سینہ اور چہرہ اس پر رکھا، اپنے کلائیوں اور ہاتھوں کو اس طرح کیا اور انہیں خوب پھیلایا۔ (یعنی پھیلا کر دکھایا) پھر کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس طرح کرتے دیکھا ہے۔","f2":"یہ سند ضعیف ہے۔مگر حضرت ابن عباس رضی اللہ تعالیٰ عنہ عروہ بن زبیر اوردیگر صحابہ کرام رضوان اللہ عنہم اجمعین کے عمل سے صحیح ثابت ہے۔اس طرح یہ روایت درجہ حسن تک پہنچ جاتی ہے۔(مناسک الحج والعمرۃ ص 22 ازعلامہ البانی رحمۃ اللہ علیہ)"}],[1900,"عبداللہ بن سائب کہتے ہیں کہ وہ ابن عباس رضی اللہ عنہما کو لے کر جاتے (جب ان کی بینائی ختم ہو گئی) اور ان کو اس تیسرے کونے کے پاس کھڑا کر دیتے جو اس رکن کعبہ کے قریب ہے جو حجر اسود کے قریب ہے اور دروازے سے ملا ہوا ہے تو ابن عباس رضی اللہ عنہما ان سے کہتے: کیا تمہیں معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم اس جگہ نماز پڑھتے تھے؟ وہ کہتے: ہاں، تو ابن عباس رضی اللہ عنہما کھڑے ہوتے اور نماز پڑھتے۔","ضعیف",{"u2":"جناب محمد بن عبداللہ بن سائب اپنے والد (عبداللہ بن سائب سے بیان کرتے ہیں کہ وہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کا ہاتھ پکڑ کر چلتے تھے (جبکہ وہ نابینا ہو چکے تھے) اور انہیں تیسرے کونے کے پاس کھڑا کر دیتے تھے جو کہ حجر اسود کے ساتھ دروازہ کعبہ کے پاس ہے تو سیدنا ابن عباس رضی اللہ عنہ اسے کہتے ” کیا خبر دی گئی ہے تمہیں کہ رسول اللہ صلی اللہ علیہ وسلم یہاں نماز پڑھا کرتے تھے؟ “ تو وہ کہتے کہ ہاں! پھر وہ کھڑے ہو جاتے اور نماز پڑھتے۔","f2":"سند اس روایت کی بھی ضعیف ہے۔ مگر دیگر روایات کی روشنی میں صحابہ رضوان اللہ عنہم اجمعین سے یہ عمل ثابت ہے۔اورصحیح ہے۔"}],[1901,"عروہ بن زبیر کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے کہا اور میں ان دنوں کم سن تھا: مجھے اللہ تعالی کے ارشاد «إن الصفا والمروة من شعائر الله» کے سلسلہ میں بتائیے، میں سمجھتا ہوں کہ اگر کوئی ان کے درمیان سعی نہ کرے تو اس پر کوئی گناہ نہیں، عائشہ رضی اللہ عنہا نے جواب دیا: \"ہرگز نہیں، اگر ایسا ہوتا جیسا تم کہہ رہے ہو تو اللہ کا قول «فلا جناح عليه أن يطوف بهما» کے بجائے «فلا جناح عليه أن لا يطوف بهما» \"تو اس پر ان کی سعی نہ کرنے میں کوئی گناہ نہیں\" ہوتا، یہ آیت دراصل انصار کے بارے میں اتری، وہ مناۃ (یعنی زمانہ جاہلیت کا بت) کے لیے حج کرتے تھے اور مناۃ قدید ۱؎ کے سامنے تھا، وہ لوگ صفا و مروہ کے بیچ سعی کرنا برا سمجھتے تھے، جب اسلام آیا تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں پوچھا، اس وقت اللہ تعالی نے یہ آیت نازل فرمائی: «إن الصفا والمروة من شعائر الله» ۲؎\"۔\n§وضاحت\n۱؎ : ’’مناة قديد‘‘ : مکہ اور مدینہ کے درمیان ایک دیہات کا نام ہے۔ ۲؎ : بلاشبہ صفا اور مروہ اللہ کی نشانیوں میں سے ہیں ( سورة البقرة : ۱۵۸)","صحیح",{"u2":"جناب عروہ (بن زبیر) کہتے ہیں کہ میں نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے کہا: اور میں ان دنوں نوعمر تھا: فرمائیے اللہ تعالیٰ کے فرمان &lt;قرآن&gt; &laquo;إن الصفا والمروة من شعائر الله&raquo; &lt;/قرآن&gt; سے میں یہ سمجھتا ہوں کہ اگر کوئی ان کے درمیان سعی نہ کرتے تو اس پر کوئی حرج نہیں! عائشہ رضی اللہ عنہا ا نے فرمایا: ہرگز نہیں، اگر بات ایسے ہوتی جیسے تم کہہ رہے ہو تو آیت کریمہ یوں ہوتی &laquo;فلا جناح عليه أن لا يطوف بهما&raquo; &rdquo; اگر وہ ان کی سعی نہ کرے تو اس پر کوئی گناہ نہیں۔ &ldquo; دراصل یہ آیت انصار کے بارے میں نازل ہوئی تھی۔ یہ لوگ منات (بت) کے قصد سے احرام باندھا کرتے تھے اور یہ بت مقام قدید کے بالمقابل نصب تھا۔ اور پھر یہ لوگ صفا مروہ کی سعی میں حرج سمجھتے تھے۔ جب اسلام آیا تو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں سوال کیا تو اللہ عزوجل نے یہ آیت نازل فرمائی &lt;قرآن&gt; &laquo;إن الصفا والمروة من شعائر الله&raquo; &lt;/قرآن&gt;۔","f2":"قرآن مجید کو محض لغت کی بنیاد پر سمجھنے کی کوشش کرنا اور احادیث صحیحہ سے اعراض کرنا بہت بڑی جہالت ہے قرآن مجید کا وہی فہم معتبر ہے۔اور اسلام کی حقیقی تعبیر وہی ہے۔جو سلف صالحین (صحابہ کرامرضوان اللہ عنہم اجمعین)نے کی ہے۔ شان نزول جو صحیح احادیث و اسانید سے ثابت ہیں۔ ان سے استفادہ کرنا بھی از حد ضروری ہے۔جیسے کہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے وضاحت فرمائی۔"}],[1902,"عبداللہ بن ابی اوفی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عمرہ کیا تو بیت اللہ کا طواف کیا اور مقام ابراہیم کے پیچھے دو رکعت نماز پڑھی، آپ کے ساتھ کچھ ایسے لوگ تھے جو آپ کو آڑ میں لیے ہوئے تھے، تو عبداللہ رضی اللہ عنہ سے پوچھا گیا: کیا رسول اللہ صلی اللہ علیہ وسلم کعبہ میں داخل ہوئے؟ انہوں نے جواب دیا: نہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن ابی اوفی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عمرہ کیا تو بیت اللہ کا طواف کیا اور مقام (ابراہیم) کے پیچھے دو رکعتیں پڑھیں۔ اور آپ صلی اللہ علیہ وسلم کے ساتھ وہ لوگ تھے جنہوں نے آپ کو لوگوں سے بچایا ہوا تھا۔ عبداللہ رضی اللہ عنہ سے پوچھا گیا، کیا رسول اللہ صلی اللہ علیہ وسلم کعبہ میں داخل ہوئے تھے؟ انہوں نے کہا: نہیں۔","f2":"یہ سن سات ہجری عمرہ قضا کا واقعہ ہے۔ اور آپ اس بار کعبہ کے اندر داخل نہیں ہوئے تھے۔"}],[1903,"اس سند سے بھی عبداللہ بن ابی اوفی رضی اللہ عنہ سے یہی حدیث مروی ہے البتہ اس میں اتنا اضافہ ہے: پھر آپ صفا و مروہ آئے اور ان کے درمیان سات بار سعی کی، پھر اپنا سر منڈایا۔","صحیح",{"u2":"اسمعیل بن ابی خالد کہتے ہیں میں نے سیدنا عبداللہ بن ابی اوفی رضی اللہ عنہ سے یہ حدیث سنی۔ اور یہ مزید کہا: پھر آپ صفا مروہ کی طرف آئے اور ان کے درمیان سات چکر لگائے پھر اپنا سر منڈایا۔","f2":"علامہ البانی رحمہ اللہ کہتے ہیں۔کہ اس حدیث میں سر منڈانے کا بیان صحیح نہیں اس عمرے میں آپ کابال کتروانا ثابت ہے۔"}],[1904,"کثیر بن جمہان سے روایت ہے کہ صفا و مروہ کے درمیان عبداللہ بن عمر رضی اللہ عنہما سے ایک شخص نے پوچھا: ابوعبدالرحمٰن! میں آپ کو (عام چال چلتے) دیکھتا ہوں جب کہ لوگ دوڑتے ہیں؟ انہوں نے کہا: اگر میں عام چال چلتا ہوں تو اس لیے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو عام چال چلتے دیکھا ہے اور اگر میں دوڑ کر کرتا ہوں تو اس لیے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سعی(دوڑتے) کرتے دیکھا ہے اور میں بہت بوڑھا شخص ہوں۔","صحیح",{"u2":"کثیر بن جمہان سے روایت ہے کہ ایک شخص نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے صفا اور مروہ کے درمیان پوچھا: اے ابوعبدالرحمٰن! میں آپ کو دیکھتا ہوں کہ آپ چل رہے ہیں جبکہ لوگ دوڑ رہے ہیں۔ (کیوں؟) انہوں نے کہا: اگر میں چلوں تو بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو چلتے ہوئے دیکھا ہے۔ اور اگر میں دوڑوں تو میں نے آپ صلی اللہ علیہ وسلم کو دوڑتے ہوئے دیکھا ہے، اور میں (اب) بوڑھا ہو گیا ہوں۔","f2":"یعنی صفا مروہ کے درمیان سعی کرنا (دوڑنا)چاہیے۔لیکن اگر کوئی بیماری یا شدید بڑھاپے کی وجہ سے دوڑ نہ سکے تو اس کے لئے چلنا بھی کفایت کرجائے گا۔واللہ اعلم۔"}],[1905,"جعفر بن محمد اپنے والد محمد (محمد باقر) سے روایت کرتے ہیں، وہ کہتے ہیں کہ ہم جابر بن عبداللہ رضی اللہ عنہما کے پاس آئے جب ہم ان کے پاس پہنچے تو انہوں نے آنے والوں کے بارے میں (ہر ایک سے) پوچھا یہاں تک کہ جب مجھ تک پہنچے تو میں نے کہا: میں محمد بن علی بن حسین ہوں، تو انہوں نے اپنا ہاتھ میرے سر کی طرف بڑھایا، اور میرے کرتے کے اوپر کی گھنڈی کھولی، پھر نیچے کی کھولی، اور پھر اپنی ہتھیلی میرے دونوں چھاتیوں کے بیچ میں رکھی، میں ان دنوں جوان تھا، پھر کہا: خوش آمدید، اے میرے بھتیجے! جو چاہو پوچھو، میں نے ان سے سوالات کئے، وہ نابینا ہو چکے تھے اور نماز کا وقت آ گیا، تو وہ ایک کپڑا اوڑھ کر کھڑے ہو گئے (یعنی ایک ایسا کپڑا جو دہرا کر کے سلا ہوا تھا)، جب اسے اپنے کندھے پر ڈالتے تو چھوٹا ہونے کی وجہ سے وہ کندھے سے گر جاتا، چنانچہ انہوں نے ہمیں نماز پڑھائی اور ان کی چادر ان کے بغل میں تپائی پر رکھی ہوئی تھی، میں نے عرض کیا: مجھے اللہ کے رسول کے حج کا حال بتائیے، پھر انہوں نے اپنے ہاتھ سے اشارہ کیا اور نو کی گرہ بنائی پھر بولے: رسول اللہ صلی اللہ علیہ وسلم نو سال تک (مدینہ میں) حج کئے بغیر رہے، پھر دسویں سال لوگوں میں اعلان کیا گیا کہ رسول اللہ صلی اللہ علیہ وسلم حج کو جانے والے ہیں، چنانچہ مدینہ میں لوگ کثرت سے آ گئے ۱؎، ہر ایک کی خواہش تھی کہ وہ آپ صلی اللہ علیہ وسلم کی اقتداء میں حج کرے، اور آپ ہی کی طرح سارے کام انجام دے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نکلے اور آپ کے ساتھ ہم بھی نکلے، ہم لوگ ذی الحلیفہ پہنچے تو اسماء بنت عمیس رضی اللہ عنہا کے یہاں محمد بن ابی بکر رضی اللہ عنہما کی ولادت ہوئی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھوایا: میں کیا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"تم غسل کر لو، اور کپڑے کا لنگوٹ باندھ لو، اور احرام پہن لو\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے (ذو الحلیفہ کی) مسجد میں نماز پڑھی، پھر قصواء (نامی اونٹنی) پر سوار ہوئے، یہاں تک کہ جب بیداء میں اونٹنی کو لے کر سیدھی ہو گئی (جابر رضی اللہ عنہ کہتے ہیں) تو میں نے تاحد نگاہ دیکھا کہ آپ صلی اللہ علیہ وسلم کے سامنے سوار بھی ہیں پیدل بھی، اسی طرح معاملہ دائیں جانب تھا، اسی طرح بائیں جانب، اور اسی طرح آپ کے پیچھے، اور رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان میں تھے ۱؎، آپ صلی اللہ علیہ وسلم پر قرآن نازل ہو رہا تھا، اور آپ صلی اللہ علیہ وسلم اس کا معنی سمجھتے تھے، چنانچہ جیسے آپ صلی اللہ علیہ وسلم کرتے ویسے ہی ہم بھی کرتے۔ آپ صلی اللہ علیہ وسلم نے توحید پر مشتمل تلبیہ: «لبيك اللهم لبيك لبيك لا شريك لك لبيك إن الحمد والنعمة لك والملك لا شريك لك» پکارا، اور لوگ وہی تلبیہ پکارتے رہے جسے آپ صلی اللہ علیہ وسلم پکارا کرتے تھے ۲؎، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں اس میں سے کسی بھی لفظ سے منع نہیں کیا، بلکہ آپ صلی اللہ علیہ وسلم اپنا تلبیہ ہی برابر کہتے رہے۔ ہماری نیت صرف حج کی تھی، ہمیں پتہ نہیں تھا کہ عمرہ بھی کرنا پڑے گا ۳؎، جب ہم آپ صلی اللہ علیہ وسلم کے ساتھ بیت اللہ پہنچے تو آپ صلی اللہ علیہ وسلم نے حجر اسود کا استلام کیا پھر تین پھیروں میں رمل کیا، اور چار پھیروں میں عام چال چلے، پھر مقام ابراہیم کے پاس آئے اور یہ آیت پڑھی: «واتخذوا من مقام إبراهيم مصلى» ۴؎، اور مقام ابراہیم کو اپنے اور بیت اللہ کے بیچ میں رکھا۔ (محمد بن جعفر) کہتے ہیں: میرے والد کہتے تھے (ابن نفیل اور عثمان کی روایت میں ہے) کہ میں یہی جانتا ہوں کہ جابر رضی اللہ عنہ نے اسے نبی اکرم صلی اللہ علیہ وسلم سے نقل کیا ہے (اور سلیمان کی روایت میں ہے) میں یہی جانتا ہوں کہ انہوں نے کہا: \"رسول صلی اللہ علیہ وسلم نے دونوں رکعتوں میں «قل هو الله أحد» اور «قل يا أيها الكافرون» پڑھا ۵؎، پھر بیت اللہ کی طرف لوٹے اور حجر اسود کا استلام کیا، اس کے بعد (مسجد کے) دروازے سے صفا کی طرف نکل گئے جب صفا سے قریب ہوئے تو «إن الصفا والمروة من شعائر الله» پڑھا اور فرمایا: \"ہم بھی وہیں سے شروع کریں گے جہاں سے اللہ تعالی نے شروع کیا ہے\"، چنانچہ آپ صلی اللہ علیہ وسلم نے صفا سے ابتداء کی اور اس پر چڑھے یہاں تک کہ بیت اللہ کو دیکھا، تو اللہ کی بڑائی اور وحدانیت بیان کی اور فرمایا: «لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شىء قدير لا إله إلا الله وحده أنجز وعده ونصر عبده وهزم الأحزاب وحده» پھر اس کے درمیان میں دعا مانگی اور اس طرح تین بار کہا، پھر مروہ کی طرف اتر کر آئے، جب آپ صلی اللہ علیہ وسلم کے قدم ڈھلکنے لگے تو آپ صلی اللہ علیہ وسلم نے بطن وادی ۶؎ میں رمل کیا یہاں تک کہ جب چڑھنے لگے تو عام چال چلے، یہاں تک کہ مروہ آئے تو وہاں بھی وہی کیا جو صفا پہ کیا تھا، جب طواف کا آخری پھیرا مروہ پہ ختم ہوا تو فرمایا: \"اگر مجھے پہلے سے معلوم ہوتا جو کہ بعد میں معلوم ہوا تو میں ہدی نہ لاتا اور میں اسے عمرہ بنا دیتا، لہٰذا تم میں سے جس کے ساتھ ہدی نہ ہو تو وہ حلال ہو جائے، اور اسے عمرہ بنا لے\"۔ سبھی لوگ حلال ہو گئے اور بال کتروا لیے سوائے نبی اکرم صلی اللہ علیہ وسلم اور ان لوگوں کے جن کے ساتھ ہدی تھی۔ پھر سراقہ بن جعشم رضی اللہ عنہ کھڑے ہوئے اور انہوں نے پوچھا: اللہ کے رسول! کیا یہ (عمرہ) صرف اسی سال کے لیے ہے یا ہمیشہ ہمیش کے لیے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے ایک ہاتھ کی انگلیاں دوسرے میں داخل کیں اور فرمایا: \"عمرہ حج میں اسی طرح داخل ہو گیا\"، اسے دو مرتبہ فرمایا: \"(صرف اسی سال کے لیے) نہیں، بلکہ ہمیشہ ہمیش کے لیے (صرف اسی سال کے لیے) نہیں، بلکہ ہمیشہ ہمیش کے لیے\"، اور علی رضی اللہ عنہ یمن سے نبی اکرم صلی اللہ علیہ وسلم کے ہدی کے اونٹ لے کر آئے تو فاطمہ رضی اللہ عنہا کو ان لوگوں میں سے پایا جنہوں نے احرام کھول ڈالا تھا، وہ رنگین کپڑے زیب تن کئے ہوئے تھیں، اور سرمہ لگا رکھا تھا، علی رضی اللہ عنہ کو یہ ناگوار لگا، وہ کہنے لگے: تمہیں کس نے اس کا حکم دیا تھا؟ وہ بولیں: میرے والد نے۔ علی رضی اللہ عنہ (اپنے ایام خلافت میں) عراق میں کہا کرتے تھے کہ میں ان کاموں سے جن کو فاطمہ نے کر رکھا تھا غصہ میں بھرا ہوا رسول اللہ صلی اللہ علیہ وسلم کے پاس پوچھنے کے لیے آیا جو فاطمہ نے آپ صلی اللہ علیہ وسلم کے متعلق بتائی تھی، اور جس پر میں نے ناگواری کا اظہار کیا تھا، تو انہوں نے کہا کہ مجھے میرے والد نے اس کا حکم دیا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس نے سچ کہا، اس نے سچ کہا، تم نے حج کی نیت کرتے وقت کیا کہا تھا؟\"، عرض کیا: میں نے یوں کہا تھا: \"اے اللہ! میں اسی کا احرام باندھتا ہوں جس کا تیرے رسول نے باندھا ہے\"، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے ساتھ تو ہدی ہے اب تم بھی احرام نہ کھولنا\"۔ جابر رضی اللہ عنہ کہتے ہیں: ہدی کے جانوروں کی مجموعی تعداد جو علی رضی اللہ عنہ یمن سے لے کر آئے تھے اور جو رسول اللہ صلی اللہ علیہ وسلم مدینہ سے لے کر آئے تھے کل سو (۱۰۰) تھی، چنانچہ تمام لوگوں نے احرام کھول دیا، اور بال کتروائے سوائے نبی اکرم صلی اللہ علیہ وسلم اور ان لوگوں کے جن کے ساتھ ہدی تھی۔ جابر رضی اللہ عنہ کہتے ہیں: جب یوم الترویہ (ذو الحجہ کا آٹھواں دن) آیا تو سب لوگوں نے منی کا رخ کیا اور حج کا احرام باندھا، رسول اللہ صلی اللہ علیہ وسلم بھی سوار ہوئے، اور منی پہنچ کر آپ صلی اللہ علیہ وسلم نے وہاں ظہر، عصر، مغرب، عشاء اور فجر کی نمازیں ادا کیں۔ پھر کچھ دیر ٹھہرے یہاں تک کہ سورج نکل آیا، آپ صلی اللہ علیہ وسلم نے اپنے لیے بالوں سے بنا ہوا ایک خیمہ کا حکم دیا، تو وادی نمرہ میں خیمہ لگایا گیا، پھر رسول اللہ صلی اللہ علیہ وسلم چلے، قریش کو اس بات میں شک نہیں تھا کہ رسول اللہ صلی اللہ علیہ وسلم مزدلفہ میں مشعر حرام ۷؎ کے پاس ٹھہریں گے جیسے جاہلیت میں قریش کیا کرتے تھے، لیکن رسول اللہ صلی اللہ علیہ وسلم آگے بڑھ گئے یہاں تک کہ عرفات جا پہنچے ۸؎ تو دیکھا کہ خیمہ نمرہ میں لگا دیا گیا ہے، آپ صلی اللہ علیہ وسلم وہاں اترے یہاں تک کہ جب سورج ڈھل گیا تو قصواء کو لانے کا حکم فرمایا، اس پر کجاوہ باندھا گیا، آپ صلی اللہ علیہ وسلم اس پر سوار ہوئے یہاں تک کہ وادی کے اندر آئے، تو لوگوں کو خطاب کیا اور فرمایا: \"تمہاری جانیں اور تمہارے مال تم پر ایسے ہی حرام ہیں جیسے تمہارا یہ دن، تمہارے اس مہینے، اور تمہارے اس شہر میں۔ سنو! جاہلیت کے زمانے کی ہر بات میرے قدموں تلے پامال ہو گئی (یعنی لغو اور باطل ہو گئی اور اس کا اعتبار نہ رہا) جاہلیت کے سارے خون معاف ہیں اور سب سے پہلا خون جسے میں معاف کرتا ہوں وہ ابن ربیعہ یا ربیعہ بن حارث بن عبدالمطلب کا ہے- وہ بنی سعد میں دودھ پی رہا تھا- اسے ہذیل کے لوگوں نے قتل کر دیا تھا (وہ نبی اکرم صلی اللہ علیہ وسلم کا چچا زاد بھائی تھا) اور جاہلیت کے تمام سود ختم ہیں سب سے پہلا سود جسے میں ختم کرتا ہوں وہ اپنا سود ہے یعنی عباس بن عبدالمطلب کا کیونکہ سود سبھی ختم ہیں خواہ وہ کسی کے بھی ہوں۔ اور عورتوں کے بارے میں اللہ سے ڈرو، اس لیے کہ تم نے انہیں اللہ کی امان کے ساتھ اپنے قبضہ میں لیا ہے، اور تم نے اللہ کے حکم سے ان کی شرمگاہوں کو حلال کیا ہے، ان پر تمہارا حق یہ ہے کہ وہ تمہارے بستر پر اس شخص کو نہ آنے دیں جسے تم ناپسند کرتے ہو، اب اگر وہ ایسا کریں تو انہیں بس اس قدر مارو کہ ہڈی نہ ٹوٹنے پائے، اور انہیں تم سے دستور کے مطابق کھانا لینے اور کپڑا لینے کا حق ہے۔ میں تمہارے درمیان ایسی چیز چھوڑے جاتا ہوں کہ اگر تم اسے مضبوطی سے پکڑے رہو گے تو اس کے بعد کبھی گمراہ نہ ہو گے، وہ اللہ کی کتاب ہے۔ (اچھا بتاؤ) تم سے قیامت کے روز میرے بارے میں سوال کیا جائے گا تو تمہارا جواب کیا ہو گا؟\" لوگوں نے کہا: ہم گواہی دیں گے کہ آپ صلی اللہ علیہ وسلم نے اللہ کا حکم پہنچا دیا، حق ادا کر دیا، اور نصیحت کی، پھر آپ صلی اللہ علیہ وسلم نے اپنی انگشت شہادت کو آسمان کی طرف اٹھایا، پھر لوگوں کی طرف جھکایا، اور فرمایا: \"اے اللہ! تو گواہ رہ، اے اللہ! تو گواہ رہ\"۔ پھر بلال رضی اللہ عنہ نے اذان دی اور اقامت کہی تو آپ صلی اللہ علیہ وسلم نے ظہر پڑھی اور انہوں نے پھر اقامت کہی تو آپ صلی اللہ علیہ وسلم نے عصر کی نماز پڑھی یہاں تک کہ میدان عرفات آئے تو اپنی اونٹنی قصواء کا پیٹ صخرات (بڑے پتھروں) کی جانب کیا، اور حبل المشاۃ کو اپنے سامنے کیا، اور قبلہ رخ ہوئے، اور شام تک ٹھہرے رہے یہاں تک کہ سورج ڈوب گیا اور سورج کی ٹکیہ غائب ہونے کے بعد زردی کچھ کم ہو گئی۔ آپ صلی اللہ علیہ وسلم نے اسامہ رضی اللہ عنہ کو اپنے پیچھے بٹھا لیا، پھر عرفات سے لوٹے، قصواء کی باگ آپ صلی اللہ علیہ وسلم نے کھینچ کر رکھی تھی یہاں تک کہ اس کا سر پالان کے سر سے چھو جایا کرتا تھا، آپ صلی اللہ علیہ وسلم اپنے داہنے ہاتھ کے اشارہ سے لوگوں سے کہہ رہے تھے کہ: \"لوگو! اطمینان سے چلو!، لوگو! اطمینان سے چلو!\"، جب آپ صلی اللہ علیہ وسلم کسی بلندی پر آتے تو باگ ڈھیلی چھوڑ دیتے تاکہ وہ چڑھ سکے یہاں تک کہ مزدلفہ پہنچے تو مغرب اور عشاء ایک اذان اور دو اقامتوں کے ساتھ ملا کر پڑھیں۔ عثمان کہتے ہیں: دونوں کے بیچ میں کوئی نفلی نماز نہیں پڑھی پھر سارے راوی متفق ہیں۔ پھر رسول اللہ صلی اللہ علیہ وسلم لیٹ گئے یہاں تک کہ فجر طلوع ہو گئی تو آپ صلی اللہ علیہ وسلم نے فجر پڑھی یہاں تک کہ صبح خوب اچھی طرح روشن ہو گئی، سلیمان کہتے ہیں (یہ نماز) آپ صلی اللہ علیہ وسلم نے ایک اذان اور ایک اقامت سے (پڑھی)، پھر سارے راوی متفق ہیں)، پھر آپ صلی اللہ علیہ وسلم قصواء پر سوار ہوئے یہاں تک کہ مشعر حرام کے پاس آئے، اس پر چڑھے، (عثمان اور سلیمان کہتے ہیں) پھر قبلہ رخ ہوئے اور اللہ کی تحمید، تکبیر اور تہلیل کی، (عثمان نے یہ اضافہ کیا کہ) آپ صلی اللہ علیہ وسلم نے توحید بیان کی۔ پھر آپ صلی اللہ علیہ وسلم وہاں ٹھہرے رہے یہاں تک کہ خوب روشنی ہو گئی اس کے بعد سورج طلوع ہونے سے پہلے آپ صلی اللہ علیہ وسلم وہاں سے چل پڑے، اور فضل بن عباس رضی اللہ عنہما کو اپنے پیچھے سوار کر لیا، وہ نہایت عمدہ بال والے گورے خوبصورت شخص تھے، جب رسول اللہ صلی اللہ علیہ وسلم چلے تو آپ کا گزر ایسی عورتوں پر ہوا جو ہودجوں میں بیٹھی ہوئی جا رہی تھیں، فضل ان کی طرف دیکھنے لگے، رسول اللہ صلی اللہ علیہ وسلم نے اپنا ہاتھ فضل کے چہرے پر رکھ دیا تو فضل نے اپنا چہرہ دوسری طرف پھیر لیا، آپ صلی اللہ علیہ وسلم نے بھی اپنا ہاتھ دوسری جانب موڑ دیا تو فضل نے اپنا رخ اور جانب موڑ لیا اور دیکھنے لگے، یہاں تک کہ جب وادی محسر میں آئے تو اپنی سواری کو ذرا حرکت دی (یعنی ذرا تیز چلایا) پھر درمیانی راستے ۹؎ سے چلے جو جمرہ عقبہ پہنچاتا ہے یہاں تک کہ جب اس جمرے کے پاس آئے جو درخت کے پاس ہے تو اسے سات کنکریاں ماریں، ہر کنکری پر تکبیر کہی، کنکری اتنی بڑی تھی کہ انگلی میں رکھ کر پھینک رہے تھے، آپ صلی اللہ علیہ وسلم نے وادی کے اندر سے کنکریاں ماریں پھر آپ صلی اللہ علیہ وسلم وہاں سے نحر کرنے کی جگہ کو آئے، اور اپنے ہاتھ سے (۶۳) اونٹنیاں نحر کیں، اور پھر علی رضی اللہ عنہ کو حکم دیا تو باقی انہوں نے نحر کیں، آپ صلی اللہ علیہ وسلم نے انہیں بھی اپنے ہدی میں شریک کر لیا (یعنی اپنے ہدی کے اونٹوں میں سے کچھ اونٹ انہیں بھی نحر کرنے کے لیے دے دیئے) پھر ہر اونٹ میں سے گوشت کا ایک ایک ٹکڑا لینے کا حکم دیا، تو وہ سب ٹکڑے ایک دیگ میں رکھ کر پکائے گئے (آپ صلی اللہ علیہ وسلم اور علی رضی اللہ عنہ) دونوں نے ان کا گوشت کھایا اور ان کا شوربہ پیا، (سلیمان کہتے ہیں) پھر آپ صلی اللہ علیہ وسلم سوار ہوئے اور بیت اللہ کی طرف چلے، آپ صلی اللہ علیہ وسلم نے مکہ میں ۱۰؎ ظہر پڑھی۔ پھر بنی عبدالمطلب کے پاس آئے، وہ لوگ آب زمزم پلا رہے تھے فرمایا: \"اے بنی عبدالمطلب! پانی کھینچو، اگر مجھے یہ اندیشہ نہ ہوتا کہ تمہارے سقایہ پر لوگ تم پر غالب آ جائیں گے ۱۱؎ تو میں بھی تمہارے ساتھ پانی کھینچتا، ان لوگوں نے ایک ڈول آپ صلی اللہ علیہ وسلم کو بھی دیا، آپ صلی اللہ علیہ وسلم نے اس میں سے پیا۔\n§وضاحت\n۱؎ : بعض لوگوں نے یہ تعداد (۹۰) ہزار لکھی ہے، اور بعض نے ایک لاکھ تیس ہزار کہا ہے۔ ۲؎ : زمانہ جاہلیت میں تلبیہ میں«لبيك اللهم لبيك لا شريك لك‘‘کے بعد’’إلا شريكًا هو لك تملكه» بڑھا کر کہا جاتا تھا۔ ۳؎ : یعنی عمرہ کا بالکل قصد نہیں تھا، یا عمرہ کو حج کے مہینوں میں جائز ہی نہیں سمجھتے تھے۔ ۴؎ : اور مقام ابراہیم کو مصلی بنالو (سورۃ البقرۃ :۱۲۵)۔ ۵؎ : پہلی رکعت میں «قل يا أيها الكافرون» پڑھی اور دوسری میں «قل هو الله أحد» ۔ ۶؎ : حرم مکی کی تعمیر جدید میں دو سبز نشان سے اس وادی کی حد مقرر کر دی گئی ہے، جن کو میلین اخضرین کہا جاتا ہے۔ ۷؎ : ’’مشعر حرام‘‘: مزدلفہ میں ایک مشہور پہاڑی کا نام ہے اسے قزح بھی کہا جاتا ہے۔ ۸؎ : زمانہ جاہلیت میں قریش مزدلفہ میں ٹھہر جاتے تھے ، عرفات نہیں جاتے تھے، اور باقی لوگ عرفات جاتے تھے ، ان کا خیال تھا کہ نبی اکرم صلی اللہ علیہ وسلم بھی قریش کی اتباع کریں گے، لیکن آپ صلی اللہ علیہ وسلم وہاں نہیں ٹھہرے اور عرفات چل دیئے۔ ۹؎ : اس کو طریق مازمین (دو پہاڑوں کا نام ہے) کہتے ہیں، عرفات سے اسی راستہ سے واپس ہونا سنت ہے، یہ اس راستہ کے علاوہ ہے جس سے رسولِ اکرم صلی اللہ علیہ وسلم عرفات گئے تھے، راستہ کی یہ تبدیلی نیک فال کے طور پر بھی ہے۔ ۱۰؎ : یہی راجح قول ہے اس کے برخلاف ایک روایت آتی ہے جس میں ظہر منی میں پڑھنے کا ذکر ہے، علماء نے دونوں میں تطبیق اس طرح دی ہے کہ آپ صلی اللہ علیہ وسلم نے زوال سے پہلے طواف افاضہ کیا پھر مکہ میں اول وقت پر ظہر پڑھی پھر منی واپس آئے تو وہاں بھی صحابہ کرام رضی اللہ عنہم کے ساتھ ظہر پڑھی، اور بعد والی نماز آپ صلی اللہ علیہ وسلم کی نفل ہو گئی۔ ۱۱؎ : آپ صلی اللہ علیہ وسلم کے کہنے کا مطلب یہ تھا کہ اگر میں بھی پانی نکالنے میں لگ جاؤں تو لوگ اس کو بھی حج کی ایک ذمہ داری سمجھ لیں گے، اور اس کے لئے بھیڑ لگائیں گے، پھر تم ڈر کی وجہ سے اس خدمت سے علاحدہ ہو جاؤ گے کیونکہ تم لوگوں سے نہیں لڑ سکو گے، اور وہ تم پر غالب آ جائیں گے۔","صحیح",{"u2":"سیدنا جعفر (صادق) بن محمد (جعفر صادق بن محمد بن علی بن حسین رضی اللہ عنہ) اپنے والد (محمد) سے بیان کرتے ہیں کہ ہم سیدنا جابر بن عبداللہ رضی اللہ عنہ کے ہاں گئے۔ جب ہم آپ کے پاس پہنچے تو انہوں نے سب لوگوں سے پوچھا (شناسائی حاصل کی) حتیٰ کہ میری باری آئی تو میں نے بتایا کہ میں محمد بن علی بن حسین ہوں۔ تو انہوں نے اپنا ہاتھ میرے سر کی طرف بڑھایا، پھر میرا اوپر والا بٹن کھولا، پھر نیچے والا کھولا، پھر اپنا ہاتھ میری چھاتیوں کے درمیان رکھا، اور میں ان دنوں جوان لڑکا تھا۔ انہوں نے کہا: خوش آمدید، بھتیجے! اپنے ہی گھر میں آئے ہو!۔ جو جی چاہتا ہے پوچھ لو، چنانچہ میں نے ان سے پوچھا جبکہ وہ نابینا ہو چکے تھے۔ اور نماز کا وقت ہو گیا تو وہ اپنے اسی چھوٹے سے کپڑے ہی کو لپیٹ کر کھڑے ہو گئے۔ اسے دہرا کر کے سیا گیا تھا۔ کپڑا اس قدر چھوٹا تھا کہ اسے جب بھی کندھے پر رکھتے، اس کے کنارے گر پڑتے تھے، انہوں نے ہم کو نماز پڑھائی حالانکہ آپ کی بڑی چادر آپ کے پہلو میں کھونٹی پر لگی ہوئی تھی۔ میں نے کہا: آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کے حج کے بارے میں بیان فرمائیں، تو انہوں نے اپنے ہاتھ سے نو کی گرہ بنائی پھر کہا کہ رسول اللہ صلی اللہ علیہ وسلم نو سال تک رکے رہے اور حج نہیں کیا، پھر دسویں سال لوگوں میں اعلان کیا کہ اللہ کے رسول حج کے لیے جانے والے ہیں، چنانچہ مدینہ میں بہت زیادہ لوگ آ گئے۔ ہر ایک اللہ کے رسول کی اقتداء اور آپ کے عمل کی پیروی کرنا چاہتا تھا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نکلے تو ہم بھی آپ صلی اللہ علیہ وسلم کے ساتھ تھے حتیٰ کہ مقام ذوالحلیفہ پر پہنچ گئے۔ یہاں اسماء بنت عمیس (زوجہ ابوبکر رضی اللہ عنہا ا) نے محمد بن ابی بکر رضی اللہ عنہ کو جنم دیا۔ پس انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی طرف پیغام بھیجا کہ میں کیسے کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” غسل کرو، کپڑے کا لنگوٹ باندھو اور احرام کی نیت کر لو۔ “ پھر رسول اللہ صلی اللہ علیہ وسلم نے مسجد میں نماز پڑھی، پھر (اپنی اونٹنی) قصواء پر سوار ہو گئے حتیٰ کہ وہ آپ صلی اللہ علیہ وسلم کو لے بیداء (میدان) کے سامنے کھڑی ہو گئی۔ جابر بیان کرتے ہیں: میں نے دیکھا تاحد نگاہ آپ صلی اللہ علیہ وسلم کے سامنے، دائیں، بائیں اور پیچھے لوگ ہی لوگ تھے۔ کچھ سوار اور کچھ پیدل۔ اور رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان میں تھے، آپ صلی اللہ علیہ وسلم پر قرآن اتر رہا تھا اور آپ صلی اللہ علیہ وسلم اس کا معنی و مفہوم اور طریقہ عمل بھی خوب جانتے تھے چنانچہ جو آپ صلی اللہ علیہ وسلم نے کیا ہم نے بھی ویسے ہی کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے کلمہ توحید پکارا: «لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك» ” حاضر ہوں میں اے اللہ! حاضر ہوں، میں حاضر ہوں۔ تیرا کوئی ساجھی نہیں، میں حاضر ہوں، بلاشبہ حمد تیری ہے، نعمتیں تیری ہیں اور ملک بھی تیرا ہے، تیرا کوئی شریک نہیں۔ “ اور لوگوں نے بھی یہی تلبیہ پکارا جو وہ پکارتے ہیں۔ آپ نے کسی کی تردید نہیں فرمائی۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے تلبیہ ہی کا التزام فرمایا۔ جابر رضی اللہ عنہ کہتے ہیں کہ ہماری نیت صرف حج کی تھی، ہم عمرہ نہیں جانتے تھے، حتیٰ کہ جب ہم آپ صلی اللہ علیہ وسلم کے ساتھ بیت اللہ میں پہنچ گئے۔ حجر اسود کا استلام کیا، تو تین چکروں میں رمل کیا۔ (آہستہ آہستہ دوڑے) اور چار میں عام رفتار سے چلے۔ پھر آپ مقام ابراہیم کی طرف آگے بڑھ گئے اور یہ آیت پڑھی «واتخذوا من مقام إبراهيم مصلى» “ اور مقام ابراہیم کو اپنی جائے نماز بنا لو۔ “ آپ صلی اللہ علیہ وسلم نے مقام ابراہیم کو اپنے اور بیت اللہ کے درمیان کیا (اور دو رکعتیں پڑھیں) جعفر رضی اللہ عنہ کہتے ہیں کہ میرے والد کہا کرتے تھے: جابر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم ہی سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان دو رکعتوں میں «قل هو الله أحد» اور «قل يا أيها الكافرون» پڑھی۔ اس کے بعد آپ صلی اللہ علیہ وسلم کعبہ کی طرف لوٹے اور حجر اسود کا بوسہ لیا۔ پھر باب صفا سے صفا پہاڑی کی طرف تشریف لے گئے۔ پس جب صفا کے قریب پہنچے تو یہ آیت پڑھی «إن الصفا والمروة من شعائر الله» ” صفا اور مروہ اللہ کی نشانیوں میں سے ہیں۔ “ (اور یہ بھی کہا) «نبدأ ب بدأ الله به» ” ہم اس سے ابتداء کرتے ہیں جس کا ذکر اللہ عزوجل نے پہلے فرمایا ہے۔ “ چنانچہ آپ صلی اللہ علیہ وسلم نے صفا سے ابتداء فرمائی اور اس پر چڑھ گئے حتیٰ کہ بیت اللہ نظر آنے لگا تو اللہ کی تکبیر و توحید بیان فرمائی اور کہا: «لا إله إلا الله وحده لا شريك له له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير، لا إله إلا الله وحده أنجز وعده ونصر عبده وهزم» ” ایک اللہ کے سوا اور کوئی معبود حقیقی نہیں۔ وہ اکیلا ہے اس کو کوئی ساجھی نہیں، سلطنت اس کی ہے، تعریف کا حقدار وہی ہے۔ وہی زندہ کرتا اور مارتا ہے، اور وہ ہر چیز پر پوری قدرت رکھتا ہے۔ ایک اللہ کے سوا اور کوئی معبود حقیقی نہیں، وہ اکیلا ہے۔ اس نے اپنا وعدہ پورا کر دکھایا۔ اپنے بندے کی مدد فرمائی اور تمام گروہوں کو اس اکیلے ہی نے پسپا کر دیا۔ “ پھر اس کے بعد دعا فرمائی۔ اور اس طرح تین بار (مذکورہ کلمات) کہے اور (ان کے درمیان میں) دعائیں کیں۔ پھر آپ مروہ کی جانب اتر آئے۔ جب آپ کے قدم وادی کے درمیان میں ٹک گئے تو آپ نے اس کے دامن میں دوڑ لگائی۔ حتیٰ کہ جب چڑھائی آئی تو چلنے لگے حتیٰ کہ مروہ پر پہنچ گئے۔ آپ نے مروہ پر بھی اسی طرح کیا جیسے کہ صفا پر کیا تھا۔ (وہی کلمات تین تین بار پڑھے اور ان کے درمیان میں دعائیں کیں) جب آپ کا آخری چکر مروہ پر ختم ہوا تو فرمایا ” اگر مجھے اپنے معاملے کا پہلے علم ہوتا جو بعد میں ہوا، تو میں قربانی ساتھ لے کر نہ چلتا اور میں اپنے اس طواف کو عمرہ بنا لیتا۔ پس تم لوگوں میں سے جس جس کے ساتھ قربانی نہیں ہے وہ حلال ہو جائے اور اپنے اس طواف کو عمرہ بنا لے۔ “ چنانچہ سب لوگ حلال ہو گئے اور انہوں نے اپنے بال کتروا لیے۔ سوائے نبی کریم صلی اللہ علیہ وسلم اور ان لوگوں کے جن کے ساتھ قربانیاں تھیں۔ سیدنا سراقہ (بن مالک) بن جعشم رضی اللہ عنہ کھڑے ہوئے اور کہا: اے اللہ کے رسول! (ہمارا یہ عمرہ) اس سال کے لیے ہے یا ہمیشہ کے لیے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنی انگلیاں ایک دوسری کے اندر داخل کر کے (اشارہ کرتے ہوئے) فرمایا ” عمرہ حج کے اندر اس طرح داخل ہو گیا ہے۔ “ آپ صلی اللہ علیہ وسلم نے دو دفعہ فرمایا ” (اس سال کے لیے) نہیں بلکہ ہمیشہ ہمیش کے لیے۔ نہیں بلکہ ہمیشہ ہمیش کے لیے۔ “ اور بیان کیا کہ سیدنا علی رضی اللہ عنہ یمن سے نبی کریم صلی اللہ علیہ وسلم کی قربانیاں لے کر آئے۔ انہوں نے (اپنی اہلیہ) سیدہ فاطمہ رضی اللہ عنہا ا کو دیکھا کہ وہ بھی ان لوگوں میں شامل ہیں جو حلال ہو چکے تھے۔ اس نے رنگین کپڑے پہن لیے تھے اور سرمہ لگایا تھا۔ سیدنا علی رضی اللہ عنہ نے اس پر ناگواری کا اظہار کیا۔ پوچھا کہ تمہیں ایسا کرنے کا کس نے کہا ہے؟ انہوں نے کہا: میرے ابا نے۔ سیدنا علی رضی اللہ عنہ جس زمانے میں عراق میں تھے، بیان کیا کرتے تھے کہ میں فاطمہ کے اس عمل پر جو اس نے کیا تھا اور نبی کریم صلی اللہ علیہ وسلم کی طرف منسوب کیا تھا، ناراض ہو کر رسول اللہ صلی اللہ علیہ وسلم سے پوچھنے کے لیے گیا۔ میں نے آپ صلی اللہ علیہ وسلم کو بتایا کہ مجھے اس (فاطمہ رضی اللہ عنہا ا) کا یہ کام ناگوار گزرا ہے اور وہ کہتی ہیں کہ میرے ابا نے مجھے حکم دیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” وہ سچ کہتی ہے، سچ کہتی ہے۔ (تم اپنے متعلق بتاؤ کہ) تم نے حج کی نیت کرتے وقت کیا کہا تھا؟ “ کہنے لگے کہ میں نے کہا تھا اے اللہ! میں وہی احرام باندھ رہا ہوں جس طرح کہ رسول اللہ صلی اللہ علیہ وسلم نے باندھا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میرے ساتھ تو قربانی ہے، چنانچہ تم بھی حلال نہ ہو۔ “ جابر رضی اللہ عنہ نے بیان کیا کہ وہ قربانیاں، جو علی رضی اللہ عنہ یمن سے لائے تھے اور جو خود رسول اللہ صلی اللہ علیہ وسلم مدینہ سے لائے تھے، ان کی کل تعداد ایک سو تھی۔ چنانچہ سب لوگ حلال ہو گئے اور اپنے بال کتروا لیے، سوائے نبی کریم صلی اللہ علیہ وسلم اور ان لوگوں کے جن کے ساتھ قربانیاں تھیں۔ پھر جب (ذوالحجہ کی) آٹھویں تاریخ آئی (یوم الترویہ) اور لوگ منٰی کی طرف جانے لگے تو انہوں نے حج کا احرام باندھا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم سوار ہو گئے اور منٰی جا کر ظہر، عصر، مغرب، عشاء اور صبح کی نمازیں پڑھیں۔ پھر آپ صلی اللہ علیہ وسلم تھوڑی دیر ٹھہرے حتیٰ کہ سورج نکل آیا۔ آپ صلی اللہ علیہ وسلم نے اپنے لیے بالوں کے بنے ہوئے خیمے کے متعلق حکم دیا اور وہ نمرہ میں لگا دیا گیا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم چلے اور قریش کو یقین تھا کہ نبی کریم صلی اللہ علیہ وسلم مزدلفہ میں مشعر الحرام کے پاس ہی رک جائیں گے جیسے کہ وہ (قریش) اسلام سے پہلے جاہلیت میں کیا کرتے تھے۔ مگر رسول اللہ صلی اللہ علیہ وسلم اس سے آگے بڑھ گئے حتیٰ کہ عرفات پہنچے۔ آپ صلی اللہ علیہ وسلم نے دیکھا کہ نمرہ میں خیمہ لگا ہوا ہے۔ آپ صلی اللہ علیہ وسلم وہاں اترے حتیٰ کہ جب سورج ڈھل گیا تو آپ صلی اللہ علیہ وسلم نے (اپنی اونٹنی) قصواء کے متعلق فرمایا تو اسے تیار کر دیا گیا۔ آپ صلی اللہ علیہ وسلم اس پر سوار ہوئے حتیٰ کہ وادی (عرنہ) کے دامن میں آ گئے اور لوگوں کو خطبہ دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تمہارے خون اور تمہارے مال تمہارے درمیان حرام ہیں جیسے کہ تمہارا یہ دن، تمہارا یہ مہینہ اور تمہارا یہ شہر حرمت والا ہے۔ خبردار! جاہلیت کے تمام امور میرے قدموں تلے روندے جا رہے ہیں۔ جاہلیت کے (سب) خون ختم کیے جاتے ہیں۔ اور سب سے پہلا، خون جو میں ختم کرتا ہوں وہ ہمارا اپنا خون ہے۔ “ ابن ربیعہ کا۔ (یہ امام ابوداؤد کے استاد) عثمان نے کہا: جب کہ (استاد) سلیمان نے کہا: ” ربیعہ بن حارث بن عبدالمطلب کا (خون ختم کرتا ہوں۔ “) ان کے بعض نے کہا: جو کہ بنی سعد میں دودھ پیتا بچہ تھا اور بنو ہذیل نے اسے قتل کر دیا تھا۔ ” جاہلیت کے (تمام) سود ختم کیے جاتے ہیں۔ اور سب سے پہلا سود جو میں ختم کر رہا ہوں وہ ہمارا اپنا سود۔ عباس بن عبدالمطلب کا سود ہے، یہ سب ختم ہے۔ عورتوں کے بارے میں اللہ سے ڈرو۔ تم نے اللہ کی امانت سے ان پر اختیار حاصل کیا ہے اور اللہ کے کلمہ سے ان کی عصمتوں کو حلال جانا ہے۔ اور ان عورتوں پر بھی واجب ہے کہ تمہارے حقوق کا لحاظ رکھیں۔ (اور وہ) یہ کہ تمہارے بستروں پر وہ کسی کو نہ آنے دیں، جن کا آنا تمہیں ناگوار ہو۔ (تمہارے گھروں میں تمہارے ناپسندیدہ افراد کو، مرد ہوں یا عورتیں نہ آنے دیں۔) اگر وہ ایسا کریں تو انہیں مارو، مگر زخمی کرنے والی مار نہ ہو۔ اور تم پر واجب ہے کہ ان کا نان و نفقہ اور لباس معروف انداز میں مہیا کرو۔ بلاشبہ میں تم میں وہ چیز چھوڑے جا رہا ہوں کہ اگر تم اسے مضبوطی سے تھامے رہے، تو گمراہ نہ ہو گے (اور وہ ہے) اللہ کی کتاب۔ تم لوگوں سے میرے بارے میں پوچھا جائے گا، تو کیا جواب دو گے؟ لوگوں نے کہا: ہم گواہی دیں گے کہ بلاشبہ آپ صلی اللہ علیہ وسلم نے (اللہ کا پیغام) پہنچا دیا۔ (پوری طرح) ادا کر دیا اور خیر خواہی (میں انتہا) کر دی۔ آپ صلی اللہ علیہ وسلم اپنی شہادت کی انگلی آسمان کی طرف اٹھاتے اور لوگوں کی طرف جھکاتے تھے اور کہتے تھے ” اے اللہ! گواہ رہنا۔ اے اللہ! گواہ رہنا۔ اے اللہ! گواہ رہنا۔ “ پھر سیدنا بلال رضی اللہ عنہ نے اذان کہی، پھر اقامت کہی تو آپ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی۔ انہوں نے پھر اقامت کہی تو آپ صلی اللہ علیہ وسلم نے عصر کی نماز پڑھائی۔ اور ان (دونوں نمازوں) کے درمیان کچھ نہیں پڑھا۔ (یعنی سنت یا نفل) پھر آپ صلی اللہ علیہ وسلم قصواء پر سوار ہو گئے حتی کہ مقام وقوف پر تشریف لائے۔ اپنی اونٹنی قصواء کا پیٹ پتھروں کی طرف کر دیا۔ (یعنی وہیں رکے رہے) اور جبل المشاۃ کو (جو کہ ریت کا بڑا ٹیلہ تھا اور لوگ اس کو پیدل ہی عبور کرتے تھے) اپنے سامنے کیا، قبلہ رخ ہوئے اور پھر وہیں رکے رہے حتی کہ سورج غروب ہو گیا اور ٹکیہ کے غائب ہو جانے کے بعد کچھ زردی بھی ختم ہو گئی۔ پھر آپ نے سیدنا اسامہ بن زید رضی اللہ عنہ کو اپنے پیچھے بٹھا لیا اور چل دیے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنی اونٹنی قصواء کی باگ اس سختی سے کھینچی ہوئی تھی کہ اس کا سر پالان کے سرے کو لگ رہا تھا اور آپ اپنے دائیں ہاتھ سے اشارہ کرتے ہوئے فر رہے تھے ” لوگو! سکون سے، لوگو! سکون سے۔ “ آپ جب کسی چڑھائی کے پاس آتے تو اونٹنی کی باگ قدرے ڈھیلی کر دیتے تاکہ (سہولت سے) چڑھ سکے۔ حتی کہ آپ مزدلفہ پہنچ گئے اور مغرب اور عشاء کی نمازیں ایک اذان اور دو اقامتوں کے ساتھ جمع کر کے پڑھیں۔ عثمان نے بیان کیا: آپ نے ان کے درمیان کوئی سنت نفل نہیں پڑھے۔ سب راویوں کا متفقہ بیان ہے کہ پھر رسول اللہ صلی اللہ علیہ وسلم لیٹ گئے حتی کہ فجر طلوع ہو گئی۔ جب صبح نمایاں ہو گئی تو آپ نے فجر کی نماز پڑھائی۔ (استاد) سلیمان کا بیان ہے کہ ایک اذان اور ایک اقامت کے ساتھ۔ (سب کا متفقہ بیان ہے) پھر آپ قصوا پر سوار ہوئے حتی کہ المشعر الحرام کے پاس آ گئے، پھر اس پر چڑھ گئے۔ عثمان اور سلیمان کا بیان ہے کہ آپ نے قبلہ کی طرف رخ کیا۔ اللہ کی حمد، تکبیر اور تہلیل بیان کی۔ عثمان نے اضافہ کیا: اور توحید بیان کی۔ اور پھر وہیں رکے رہے حتی کہ خوب سفیدی ہو گئی۔ پھر اللہ کے رسول وہاں سے چل دیے، سورج طلوع ہونے سے پہلے ہی۔ اور سیدنا فضل بن عباس رضی اللہ عنہ کو اپنے ساتھ سوار کر لیا۔ اور وہ قدرے گھنگریالے خوبصورت بالوں والے، گورے چٹے، حسین و جمیل جوان تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم وہاں سے روانہ ہوئے تو عورتیں بھی اپنے کجاووں میں بیٹھی وہاں سے گزریں۔ فضل رضی اللہ عنہ انہیں دیکھنے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے چہرے پر ہاتھ رکھ دیا۔ فضل رضی اللہ عنہ اپنا چہرہ کسی اور طرف پھیر کر دیکھنے لگے۔ حتی کہ آپ وادی محسر میں پہنچ گئے اور قدرے تیز چلے۔ پھر آپ درمیان والی راہ پر چل پڑے جو تمہیں جمرہ کبری تک پہنچاتی ہے حتی کہ آپ جمرہ کے پاس آ گئے جو کہ درخت کے پاس ہے۔ تو آپ نے اس کو سات کنکریاں ماریں جیسی کہ انگلیوں پر رکھ کر ماری جاتی ہیں۔ ہر کنکری کے ساتھ آپ «الله اكبر» کہتے تھے۔ آپ نے وادی کے دامن کی طرف سے کنکریاں ماریں۔ پھر رسول اللہ صلی اللہ علیہ وسلم قربان گاہ کی طرف تشریف لے گئے اور اپنے ہاتھ سے تریسٹھ اونٹنیاں نحر کیں اور بقیہ کے متعلق سیدنا علی رضی اللہ عنہ کو حکم دیا اور ان کو اپنی قربانی میں شریک بنایا۔ پھر آپ نے ہر قربانی سے ایک ایک ٹکڑا گوشت لینے کا حکم دیا۔ اسے دیگ میں ڈال کر پکایا تو آپ دونوں نے اس گوشت میں سے کھایا اور شوربا نوش فرمایا۔ سلیمان کا بیان ہے۔ پھر رسول اللہ صلی اللہ علیہ وسلم سوار ہوئے اور بیت اللہ کی طرف چل دیے اور مکہ آ کر ظہر کی نماز ادا فرمائی۔ پھر آپ بنی عبدالمطلب کے پاس آئے، وہ لوگ چاہ زمزم پر پانی پلا رہے تھے۔ آپ نے فرمایا ” اے بنی عبدالمطلب! پانی نکالو۔ اگر یہ اندیشہ نہ ہوتا کہ لوگ تمہارے اس پانی پلانے میں تم پر غالب آ جائیں گے تو میں بھی تمہارے ساتھ پانی نکالتا۔ “ سو انہوں نے نبی کریم صلی اللہ علیہ وسلم کو ایک ڈول دیا اور آپ نے اس سے پانی نوش فرمایا۔","f2":"1۔صحابہ کرامرضوان اللہ عنہم اجمعین کو اہل بیت نبوی صلی اللہ علیہ وسلم سے انتہائی محبت تھی۔اوراہل بیت سے محبت کرنا اور محبت رکھنا اہل الحدیث یعنی اہل السنۃ والجماعۃ کے ایمان کا حصہ ہے۔(اے اللہ!گواہ رہنا ہمیں تیرے نبی اور اس کی آل سے انتہائی پیار ہے۔رضوان اللہ علیھہم اجمعین۔ہمارا حشر انہی صالحین کے ساتھ فرما۔آمین) عقیدہ حب اہل بیت کی تفصیل کے لئے دیکھئے۔تفسیر ابن کثیر آیت کریمہ(قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَىٰ)(الشوریٰ۔23) 2۔اہل بیت کے افراد حصول علم نبوی صلی اللہ علیہ وسلم کے حریص اور شائق تھے۔اور وہ دیگر صحابہ کرام رضوان اللہ عنہم اجمعین کے ساتھ گہرے علمی روابط رکھتے تھے۔3۔ننگے سر نماز جائز ہے۔ مگر کندھوں کا ڈھانپنا ضروری ہے۔ الا یہ کہ کپڑ امیسر ہی نہ ہو۔ مگر ہمیشہ بطور عادت کے ننگے سر رہنا اور ننگے سر ہی نماز پڑھنا اسلامی روایات اور سلف کے طرز عمل کے خلاف ہے۔4۔رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حج کرنے والوں کی تعداد نوے ہزار اور ایک قول کے مطابق ایک لاکھ تیس ہزار تھی۔واللہ اعلم۔5۔دین کابنیادی ماخذ صرف اورصرف محمد رسول اللہ صلی اللہ علیہ وسلم ہیں۔6۔نفاس اور حیض والی خواتین غسل کرکے احرام باندھیں۔تلبیہ پکاریں۔عام ازکار میں مشغول رہیں۔ چونکہ ان ایام میں وہ نماز نہیں پڑھتیں۔مسجد میں داخل نہیں ہوسکتیں۔اس لئے وہ طواف بھی نہیں کرسکتیں۔7۔رسول اللہ صلی اللہ علیہ وسلم کی اونٹنی کے تین نام آئے ہیں۔قصواء۔عضباء۔اور جدعاء۔8۔سب سے افضل اور مستحب تلبیہ وہی ہے۔جو رسول اللہ صلی اللہ علیہ وسلم کا اختیار کردہ ہے۔کچھ اور کلمات بھی صحابہ کرامرضوان اللہ عنہم اجمعین سے وار د ہیں۔مثلا حضرت عمر رضی اللہ تعالیٰ عنہ کے الفاظ یوں تھے۔ (لبيك ذا النعماء والفضل الحسن لبيك مرهو يا منك ومرغوبا ً اليك حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے یہ منقول ہے۔ لبيك وسعديك والخير بيديك والرغباء اليك والعمل حضرت انس رضی اللہ تعالیٰ عنہ سے مروی ہے۔ لبيك حقا تعبدورقا 9۔حجر اسود کے بعد خانہ کعبہ کادروازہ ہے۔اور اس سے پہلے آنے والے کونے کےلئے الرکن کا لفظ بطور حکم استعمال ہوتا ہے۔اسے رکن یمانی بھی کہا جاتا ہے۔10۔طواف قدوم میں رمل ایک ثابت شدہ متواتر سنت ہے۔اس کی ابتداء اگرچہ کفار کے سامنے اپنی قوت جسمانی کے اظہار کے لئے تھی۔ اب وہ علت تو نہیں ہے۔صرف اتباع رسول صلی اللہ علیہ وسلم مقصود ومطلوب ہے۔ 11۔رکعات طواف مقام ابراہیم علیہ السلام کے پیچھے پڑھنی مستحب ہے۔ اگر یہاں نہ پڑھ سکے تو مسجد الحرام میں کہیں بھی پڑھ سکتا ہے۔12۔ رکعات طواف کے بعد پھر حجر اسود کا استلام سنت ہے۔13۔ صفا مروہ پر چڑھ کر کعبہ کی طرف رخ کرکےمسنون اذکار پڑھے جایئں خواہ کعبہ نظر آئے یا نہ آئے۔ 14۔آجکل دامن وادی کے حصہ کو نمایاں کرنے کے لئے سبز رنگ کے ستون لگادیئے گئے ہیں۔15۔رسول اللہ صلی اللہ علیہ وسلم علم غیب نہ جانتے تھے۔16۔یہ فسخ اب بھی مباح ہے۔یعنی اگر کوئی مفر د حج والا چاہے تو اپنے حج کے احرام کو عمرہ میں تبدیل کرسکتا ہے۔17۔اہل بیت نبوی صلی اللہ علیہ وسلم امور شریعت کے اسطرح پابند ہیں جیسے کہ امت کے دیگر افراد نیز شوہر کو حق حاصل ہے کہ شرعی امور کی مخالفت پر اہل خانہ پر ناراضی کا اظہار کرے۔اور شریعت کی بات منوائے۔ہر مسلمان کو چاہیے کہ اپنی صلاحیت کے مطابق تحقیق حق میں کوشش کرے۔اور حق کی بنیاد رسول اللہ صلی اللہ علیہ وسلم کاقول فعل اور توثیق (اقرار) ہے۔19۔آٹھویں زو الحج کو یوم الترویہ کا نام دینے کی وجہ یہ ہے کہ وہ لوگ اس دن اگلے دن کےلئے پانی لے لیتے تھے کیونکہ عرفات میں پانی نہیں ہوا کرتا تھا۔20۔چاہیے کہ یہ رات منیٰ میں گُزاری جائے۔یہ مستحب ہے واجب نہیں۔ سنت یہ ہے کہ طلوع آفتا ب کے بعد ہی عرفات کو روانہ ہوا جائے۔قریش اہل حرم ہونے کے زعم میں حدود حرم سے باہر نہ نکلتے تھے۔(عرفات حدودحرم سے باہر ہے۔)اور مزلفہ ہی میں وقوف کرتے تھے۔ بخلاف دیگر قبائل عرب کے وہ سب عرفات میں پہنچتے تھے۔رسول اللہ صلی اللہ علیہ وسلم نے امرشریعت واضح فرمایا کہ اس میں کسی کی کوئی خصوصیت نہیں۔قریش کے لئے بھی دوسرے لوگوں کیطرح عرفات میں جانا ضروری ہے۔(صحیح البخاری التفسیر حدیث 4520 وصحیح مسلم الحج حدیث 1219) 23۔محرم سائے میں اُٹھ بیٹھ سکتا ہے۔خیمے کا ہو یا چھتری کایا کوئی دوسرا مگر کپڑا سر پر نہ رکھے اور نہ لپیٹے۔24۔وادی عرنہ عرفات سے متصل ہے۔ مگر بقول جمہور عرفات کاحصہ نہیں ہے۔ ااور یہاں نماز ظہر سے پہلے دو خطبے ہوتے ہیں۔ اور دیگرایا م حج کے خطبے اگر کوئی ہوں تو ایک ایک ہی ہوتے ہیں۔25۔اولی االامر اور اصحاب مناصب کو چاہیے کہ حکم عام کی تنفیذ سے پہلے خود اور اپنے عزیز واقارب کو اس کا پابند بنایئں اس طرح قبولیت بڑھ جاتی ہے۔26۔کتاب اللہ سے تمسک اور اس کااعتصام (یعنی اس پر عمل)فرض کرتا ہے۔ کہ رسول اللہ صلی اللہ علیہ وسلم کی سنت ثابتہ پر عمل کیا جائے۔ اس کے بغیر تمسک بکتاب اللہ کا دعویٰ پورا ہی نہیں ہوسکتا۔بہت سی آیات میں یہ مضمون آیا ہے۔مثلا اللہ تعالیٰ نےفرمایا (قُلْ أَطِيعُوا اللَّـهَ وَالرَّسُولَ)(آل عمران۔32) او ر فرمایا (مَّن يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّـهَ)(النساء۔80) اور فرمایا۔ (وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا ۚ)(الحشر 7) 27۔عرفات میں ظہر اور عصر کی نماز جمع تقدیم اور قصر سے پڑھنا سنت ہے۔ اور اس موقع پر کوئی اور سنت نفل نہیں پڑھے جائیں گے۔28۔وقوف عرفات حج کا رکن رکین ہے۔اس کے بغیر حج نہیں۔عرفات کا سارا میدان موقف ہے۔کسی جگہ کی کوئی خصوصیت نہیں۔ اور اس وقوف کا وقت نویں تاریخ کے زوال سے لے کراگلے دن کی صبح صادق تک ہے۔اور وقوف کا معنی پائوں پر کھڑے ہونا نہیں۔بلکہ اس میدان میں رکنا ہے۔ خواہ کوئی کھڑا ہو بیٹھا ہو لیٹا ہو۔ مسنون یہ ہیں کہ غروب آفتاب کے بعد یہاں سے روانہ ہوا جائے۔29۔بے انتہا ازدھام کی وجہ سےنبی کریم صلی اللہ علیہ وسلم اپنی سواری کوسختی سے ضبط کیے ہوئے تھے۔30۔حیوانات کے ساتھ رحم شفقت اسلامی شرعی اخلاق کالازمی حصہ ہے۔31۔مزدلفہ میں مغرب اور عشاء کی نماز جمع تاخیر اور قصر سے پڑھنا مسنون ہے۔ اور اس رات میں کوئی نوافل اور تہجد نہیں32۔مشرکین مزدلفہ سے سورج طلوع ہونے کے بعد روانہ ہوتے تھے۔رسول اللہ صلی اللہ علیہ وسلم نے ان کی مخالفت کرتے ہوئے قبل ازطلوع روانگی اختیار فرمائی۔33۔رسول اللہ صلی اللہ علیہ وسلم کی تنبیہ کے بعد حضرت فضل رضی اللہ تعالیٰ عنہ کسی اور طرف دیکھنے لگے تھے۔34۔مشہور ہے کہ اصحاب الفیل کو اسی وادی محشر میں عذاب آیاتھا۔35۔دسویں تاریخ کو صرف ایک جمرہ (جمری کبریٰ) کوکنکریاں ماری جاتی ہیں۔اور بقیہ دنوں میں تینوں جمرات کوکنکریوں کے بارے میں ہے کہ چھوٹی چھوٹی ہوں۔(حصہ الخذف) (بالخاء المنقوط) کے معنی میں امام شافعی رحمہ اللہ کا قول ہے۔کہ طول و عرض میں انگلی کے پورے سے چھوٹی ہوتی ہے۔امام نووی رحمۃ اللہ علیہ لکھتے ہیں کہ کھجور کی گٹھلی کے برابر ہواور کچھ نے لوہے کے دانوں کے برابر کہا ہے۔بڑے بڑے پتھر یا جوتے مارنا کوئی شرعی عمل نہیں بلکہ ناجائز بات ہے۔ 36۔قربانی اپنے ہاتھ سے زبح کرنا یانحر کرنا افضل ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنی عمر شریف کے عدد سے قربانیاں کیں۔ دسویں تاریخ کے بعد مذید تین دن (ایام تشریق) بھی قربانی کے دن ہیں۔مگر رسول اللہ صلی اللہ علیہ وسلم کا اپنی تمام قربانیاں پہلے دن کرلینا اس کی افضلیت کی دلیل ہے۔37۔اپنی قربانی کا گوشت بھی کھانا چاہیے۔38۔دسویں تاریخ کا طواف حج کارکن ہے۔اسے طواف افاضہ یا طواف زیارہ بھی کہتے ہیں۔39۔حجاج کی خدمت انتہائی اجر وثواب کا عمل ہے۔اس میں ہر ممکن طریقے سے حصہ لینا چاہیے 40۔رسول اللہ صلی اللہ علیہ وسلم نے اس موقع پرکھڑے ہوکر پانی پیا تھا۔"}],[1906,"جعفر بن محمد اپنے والد محمد باقر سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے عرفات میں ظہر اور عصر ایک اذان سے پڑھی، ان کے درمیان کوئی نفل نہیں پڑھی، البتہ اقامت دو تھیں، اور مغرب و عشاء جمع (مزدلفہ) میں ایک اذان اور دو اقامتوں سے پڑھی، ان کے درمیان بھی کوئی نفل نہیں پڑھی۔ ابوداؤد کہتے ہیں: اس حدیث کو حاتم بن اسماعیل نے ایک لمبی حدیث میں مسنداً بیان کیا ہے اور حاتم بن اسماعیل کی طرح اسے محمد بن علی الجعفی نے جعفر سے، اور جعفر نے اپنے والد محمد سے، محمد نے جابر رضی اللہ عنہ سے روایت کیا ہے البتہ اس میں یہ الفاظ ہیں کہ \"آپ نے مغرب اور عشاء ایک اذان اور ایک اقامت سے پڑھی ۱؎\"۔\n§وضاحت\n۱؎ : اور یہ روایت سنداً و واقعۃً ضعیف ہے، صحیح یہی ہے کہ دونوں نماز ایک اذان اور دو اقامتوں سے ادا کیں۔","ضعیف",{"u2":"جناب جعفر (جعفر الصادق) رضی اللہ عنہ اپنے والد (محمد بن علی رضی اللہ عنہ) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے عرفات میں ظہر اور عصر کی نمازیں ایک اذان اور دو اقامتوں کے ساتھ پڑھی تھیں، اور ان کے مابین کوئی سنتیں (نفل) نہیں پڑھے تھے۔ اور مغرب اور عشاء کی نمازیں مزدلفہ میں ایک اذان اور دو اقامتوں کے ساتھ پڑھی تھیں، اور ان کے مابین کوئی سنتیں (نفل) نہیں پڑھے تھے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو حاتم بن اسمٰعیل نے اپنی طویل حدیث میں مسند بیان کیا ہے (جبکہ یہ سند مرسل ہے۔ حاتم نے سیدنا جابر رضی اللہ عنہ سے مسند بیان کی ہے) اور حاتم کی روایت کے مسند ہونے کی موافقت محمد بن علی الجعفی نے بھی کی ہے اور «جعفر، عن أبيه، عن جابر» کی سند سے روایت کی ہے۔ فرق اتنا ہے کہ جعفی نے کہا: «فصلى المغرب والعتمة بأذان وإقامة» آپ صلی اللہ علیہ وسلم نے مغرب اور عشاء ایک اذان اور ایک اقامت سے پڑھی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ مجھے امام احمد رضی اللہ عنہ نے کہا کہ حاتم نے اس طویل حدیث میں خطا کی ہے۔","f2":"یہ آخری مقولہ (قال ابو دائود قال لی احمد۔۔۔الخ) اس کے بارے میں صاحب عون المعبود اور بذل المجہود لکھتے ہیں۔کہ اکثر نسخے اس عبارت سے خالی ہیں۔اور بقول ان کے اس کلام کا امام ابو دائود اور امام احمد کی طرف منسوب ہونا محل نظر ہے۔کیونکہ حاتم بن اسماعیل کی روایت کو بہت سے ائمہ متقدمین و متاخرین نے صحیح کہا ہے۔کسی نے بھی اس کا وہم بیان نہیں کیا۔"}],[1907,"جابر رضی اللہ عنہ کہتے ہیں کہ پھر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تو یہاں (منی میں) نحر کیا ہے اور منی پورا کا پورا نحر کرنے کی جگہ ہے\"، اور عرفات میں وقوف کیا تو فرمایا: \"میں نے یہاں وقوف کیا ہے لیکن پورا میدان عرفات وقوف (ٹھہرنے) کی جگہ ہے\"، اور مزدلفہ میں وقوف تو فرمایا: \"میں یہاں ٹھہرا ہوں لیکن پورا مزدلفہ وقوف (ٹھہرنے) کی جگہ ہے\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے بیان ہے کہ پھر نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” میں نے یہاں نحر کیا ہے اور منیٰ سارے کا سارا قربان گاہ ہے۔ “ آپ صلی اللہ علیہ وسلم نے عرفات میں وقوف کیا۔ تو فرمایا ” میں نے یہاں وقوف کیا ہے اور سارا عرفات جائے وقوف ہے۔ “ آپ صلی اللہ علیہ وسلم نے مزدلفہ میں وقوف کیا اور فرمایا ” میں نے اس جگہ وقوف کیا ہے اور تمام مزدلفہ جائے وقوف ہے۔ “"}],[1908,"اس سند سے بھی جعفر سے یہی حدیث مروی ہے اس میں اتنا اضافہ ہے: «فانحروا في رحالكم» کہ تم لوگ اپنی قیام گاہوں میں نحر کرو۔","صحیح",{"u2":"حفص بن غیاث نے جناب جعفر (صادق) رضی اللہ عنہ سے ان کی سند سے روایت کیا تو مزید کہا: ” تو تم اپنے اپنے پڑاؤ پر نحر کرو۔ “"}],[1909,"اس سند سے بھی جابر رضی اللہ عنہ سے یہی حدیث مروی ہے البتہ اس میں یعقوب نے «واتخذوا من مقام إبراهيم مصلى» پڑھنے کے بعد یہ ادراج کیا ہے کہ \"آپ نے ان دونوں رکعتوں میں توحید (یعنی «قل هو الله أحد») اور «قل يا أيها الكافرون» پڑھیں\"، اور اس میں یہ ادراج بھی کیا کہ \"علی رضی اللہ عنہ نے کوفہ میں کہا\" یعقوب کہتے ہیں کہ میرے والد نے فرمایا: جابر رضی اللہ عنہ نے علی رضی اللہ عنہ کا یہ قول ذکر نہیں کیا: (میں نبی اکرم صلی اللہ علیہ وسلم کے پاس فاطمہ رضی اللہ عنہا کے خلاف غصہ دلانے چلا)، اور یعقوب نے فاطمہ رضی اللہ عنہا کا واقعہ ذکر کیا، میرے والد جعفر کا کہنا ہے کہ جابر رضی اللہ عنہ نے اس حرف یعنی «فذهبت محرشا» کا ذکر نہیں کیا ہے۔","صحیح",{"u2":"جناب جعفر (صادق) رضی اللہ عنہ نے بیان کیا کہ مجھے میرے والد (محمد باقر رضی اللہ عنہ) نے سیدنا جابر رضی اللہ عنہ سے بیان کیا۔ اور یہ حدیث بیان کی۔ اور اپنی حدیث پر «واتخذوا من مقام إبراهيم مصلى» کی جگہ یہ بات اپنی طرف سے بڑھائی کہ آپ نے ان رکعات میں توحید (یعنی) «قل هو الله أحد» اور «قل يا أيها الكافرون» کی تلاوت کی (یہ جملہ مدرج ہے۔) اور اس میں بیان کیا کہ سیدنا علی رضی اللہ عنہ نے یہ واقعہ کوفہ میں بیان کیا تھا۔ میرے والد (محمد بن علی رضی اللہ عنہ) نے کہا کہ جابر نے یہ لفظ بھی نہیں کہے تھے کہ ” میں غصے کے عالم میں جلدی سے گیا تھا۔“ اور فاطمہ رضی اللہ عنہا ا کا قصہ بیان کیا۔"}],[1910,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ قریش اور ان کے ہم مذہب لوگ مزدلفہ میں ہی ٹھہرتے تھے اور لوگ انہیں حمس یعنی بہادر و شجاع کہتے تھے جب کہ سارے عرب کے لوگ عرفات میں ٹھہرتے تھے، تو جب اسلام آیا تو اللہ تعالی نے اپنے نبی کریم صلی اللہ علیہ وسلم کو عرفات آنے اور وہاں ٹھہرنے پھر وہاں سے مزدلفہ لوٹنے کا حکم دیا اور یہی حکم اس آیت میں ہے: «ثم أفيضوا من حيث أفاض الناس» (سورۃ البقرہ: ۱۹۹) \"تم لوگ وہاں سے لوٹو جہاں سے سبھی لوگ لوٹتے ہیں - یعنی عرفات سے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ قریش اور ان کے اہل دین مزدلفہ میں وقوف کیا کرتے تھے اور اپنے آپ کو &rdquo; حمس &ldquo; کہلاتے تھے۔ جبکہ دیگر سب عرب عرفات میں وقوف کرتے تھے۔ بیان کرتی ہیں کہ جب اسلام آیا تو اللہ تعالیٰ نے اپنے نبی کریم صلی اللہ علیہ وسلم کو حکم دیا کہ عرفات میں آ کر وقوف کریں، پھر وہاں سے لوٹیں، چنانچہ یہی تفسیر ہے اللہ تعالیٰ کے اس فرمان کی &lt;قرآن&gt; &laquo;ثم أفيضوا من حيث أفاض الناس&raquo; &lt;/قرآن&gt; &rdquo; پھر لوٹو وہیں سے جہاں سے لوگ لوٹتے ہیں۔ &ldquo;","f2":"(الحمس۔احمس)کی جمع ہے۔معنی ہیں شجاع اور بہادر اور جاہلیت میں یہ قریش کنانہ اور ان کے متبعین کالقب تھا۔اس معنی میں کہ یہ اپنے دین میں بہت سخت تھے یا ممکن ہے۔(الحمساء) کی نسبت سے یہ لقب اختیار کیا ہو جو کہ کعبہ کا ایک نام ہے۔(تعلیق الشیخ محی الدین عبد الحمید نیز دیکھئے۔حدیث 1905۔فائدہ۔28-22)"}],[1911,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے یوم الترویہ (آٹھویں ذی الحجہ) کو ظہر اور یوم عرفہ (نویں ذی الحجہ) کو فجر منی میں پڑھی۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ترویہ کے روز (یعنی آٹھویں ذی الحجہ کو) ظہر کی نماز اور عرفہ کے روز (نویں ذی الحجہ کو) فجر کی نماز منیٰ میں پڑھی تھی۔"}],[1912,"عبدالعزیز بن رفیع کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ سے سوال کیا اور کہا: مجھے آپ وہ بتائیے جو رسول اللہ صلی اللہ علیہ وسلم سے آپ کو یاد ہو کہ آپ نے ظہر یوم الترویہ (آٹھویں ذی الحجہ) کو کہاں پڑھی؟ انہوں نے کہا: منی میں، میں نے عرض کیا تو لوٹنے کے دن آپ صلی اللہ علیہ وسلم نے عصر کہاں پڑھی؟ فرمایا: ابطح میں، پھر کہا: تم وہی کرو جو تمہارے امراء کریں ۱؎۔\n§وضاحت\n۱؎ : یعنی اس طرح کے چھوٹے چھوٹے مسئلوں میں امیر کی مخالفت نہ کرو کیوں کہ ان کی مخالفت بسا اوقات فتنوں اور فساد کا موجب ہوتی ہے ، خصوصاً جب کہ امراء ظالم ہوں ورنہ رسول اللہ صلی اللہ علیہ وسلم کی اتباع تو ہر حال میں بہتر ہے۔","صحیح",{"u2":"عبدالعزیز بن رفیع کہتے ہیں کہ میں نے سیدنا انس رضی اللہ عنہ سے کہا کہ مجھے وہ بات بتائیے جو آپ کو رسول اللہ صلی اللہ علیہ وسلم سے یاد ہو۔ ترویہ کے روز (آٹھویں ذی الحجہ کو) رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز کہاں پڑھی تھی؟ انہوں نے کہا: منیٰ میں۔ میں نے کہا: نفر والے دن (واپسی کے روز، 13 ذوالحجہ کو) آپ صلی اللہ علیہ وسلم نے عصر کی نماز کہاں پڑھی تھی؟ انہوں نے کہا: وادی ابطح (محصب) میں۔ پھر فرمایا ویسے ہی کرو جیسے کہ تمہارے امراء کرتے ہیں۔","f2":"حضرت انس رضی اللہ تعالیٰ عنہ کے کہنے کا مقصد یہ ہے کہ یہ مسائل واجب امور میں سے نہیں ہیں۔رسول اللہ صلی اللہ علیہ وسلم کا معمول اورسنت ہونے میں تو کوئی شبہ نہیں ہے۔ تاہم کسی عذر کے باعث ان پر عمل نہ ہوسکے تو کوئی حرج نہیں۔مباحات میں اولوالامر کی متابعت اور ان کی مخالفت سے احتراز کیا جائے۔"}],[1913,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم یوم عرفہ (نویں ذی الحجہ) کو فجر پڑھ کر منی سے چلے یہاں تک کہ عرفات آئے تو نمرہ میں اترے اور نمرہ عرفات میں امام کے اترنے کی جگہ ہے، جب ظہر کا وقت آنے کو ہوا تو رسول اللہ صلی اللہ علیہ وسلم (نمرہ سے) عین دوپہر میں چلے اور ظہر اور عصر کو جمع کیا، پھر لوگوں میں خطبہ دیا ۱؎ پھر چلے اور عرفات میں موقف میں وقوف کیا۔\n§وضاحت\n۱؎ : اس کے برخلاف جابر رضی اللہ عنہ کی ایک حدیث میں نماز سے پہلے خطبہ کا ذکر ہے، دونوں حدیثوں میں تطبیق یہ دی جاتی ہے کہ ابن عمر رضی اللہ عنہما کی اس حدیث کو عام نصیحت پر محمول کر لیا جائے، اور جابر رضی اللہ عنہ کی روایت کو عرفہ کے مسنون خطبہ پر، یا یہ کہا جائے کہ ابن عمر رضی اللہ عنہما والی روایت میں راوی کو وہم ہو گیا ہے، واللہ اعلم۔","حسن",{"u2":"سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عرفہ کے روز (نویں تاریخ کو) منیٰ میں صبح کی نماز پڑھائی، پھر عرفات کی طرف آئے اور وادی نمرہ میں پڑاؤ کیا۔ وہی مقام جہاں کہ عرفات میں امام اترتا ہے (ان کے دور کی بات ہے) حتیٰ کہ جب ظہر کا وقت ہوا تو رسول اللہ صلی اللہ علیہ وسلم دوپہر کو گرمی کے وقت ہی میں وہاں سے روانہ ہو گئے اور ظہر و عصر کی نماز جمع کر کے پڑھائی، پھر لوگوں کو خطبہ دیا، پھر وہاں سے چلے اور عرفات میں اپنے موقف پر جا کر وقوف فرمایا۔","f2":"صحیح تر روایات کے مطابق خطبہ عرفات نماز سے پہلے ہے۔(صحیح مسلم الحج حدیث 1218)"}],[1914,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ جب حجاج نے عبداللہ بن زبیر رضی اللہ عنہما کو قتل کیا تو ابن عمر رضی اللہ عنہما کے پاس(پوچھنے کے لیے آدمی) بھیجا کہ رسول اللہ صلی اللہ علیہ وسلم آج (یعنی عرفہ) کے دن (نماز اور خطبہ کے لیے) کس وقت نکلتے تھے؟ انہوں نے جواب دیا جب یہ وقت آئے گا تو ہم خود چلیں گے، پھر جب ابن عمر رضی اللہ عنہما نے چلنے کا ارادہ کیا تو لوگوں نے کہا: ابھی سورج ڈھلا نہیں، انہوں نے پوچھا: کیا اب ڈھل گیا؟ لوگوں نے کہا: ابھی نہیں ڈھلا، پھر جب لوگوں نے کہا کہ سورج \"ڈھل گیا\" تو وہ چلے۔","حسن",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نے بیان کیا کہ جب حجاج نے سیدنا (عبداللہ) ابن الزبیر رضی اللہ عنہ کو شہید کر دیا تو ابن عمر رضی اللہ عنہ سے پچھوا بھیجا کہ رسول اللہ صلی اللہ علیہ وسلم اس دن کس وقت یہاں سے چلتے تھے؟ انہوں نے کہا: جب وقت ہو جائے گا ہم چل پڑیں گے۔ پھر جب ابن عمر رضی اللہ عنہ نے چلنے کا ارادہ کیا تو ساتھی بولے: سورج نہیں ڈھلا ہے، پھر پوچھا: کیا ڈھل گیا ہے؟ انہوں نے کہا: نہیں ڈھلا ہے یا ڈھل گیا ہے پس جب انہوں نے کہا کہ ڈھل گیا ہے، تو وہ روانہ ہو گئے۔","f2":"اصحاب کرامرضوان اللہ عنہم اجمعین رسول اللہ صلی اللہ علیہ وسلم سے ثابت شدہ عمل کی کسی جزئی کو بھی غیر اہم نہیں سمجھتے تھے ان کی انتہائی کوشش ہوتی تھی کہ سب پر من وعن عمل کیاجائے۔"}],[1915,"بنی ضمرہ کے ایک آدمی اپنے والد یا اپنے چچا سے روایت کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو عرفات میں منبر پر (خطبہ دیتے) دیکھا۔","ضعیف",{"u2":"بنی ضمرہ کا ایک شخص اپنے والد یا چچا سے بیان کرتا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو عرفات کے روز منبر پر دیکھا تھا۔"}],[1916,"نبیط بن شریط رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو عرفات میں سرخ اونٹ پر کھڑے ہو کر خطبہ دیتے دیکھا۔","صحیح",{"u2":"سلمہ بن نبیط اپنے قبیلہ کے ایک شخص سے وہ اس کے والد نبیط رضی اللہ عنہ سے روایت کرتا ہے کہ اس نے نبی کریم صلی اللہ علیہ وسلم کو عرفات میں وقوف کیے ہوئے دیکھا۔ آپ صلی اللہ علیہ وسلم سرخ اونٹ پر خطبہ دے رہے تھے۔"}],[1917,"خالد بن عداء بن ہوذہ رضی اللہ عنہ کہتے ہیں عرفہ کے دن میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک اونٹ پر دونوں رکابوں کے درمیان کھڑے ہو کر لوگوں کو خطبہ ۱؎ دیتے دیکھا۔ ابوداؤد کہتے ہیں: اسے ابن العلاء نے وکیع سے اسی طرح روایت کیا ہے جیسے ہناد نے۔\n§وضاحت\n۱؎ : یہی صحیح ہے اور باب کی پہلی حدیث جس میں میدان عرفات میں منبر پر خطبہ دینے کا تذکرہ ہے وہ سند کے اعتبار سے کمزور ہے، واضح رہے کہ اس وقت وہاں منبر تھا ہی نہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم منبر پر خطبہ دیتے۔","صحیح",{"u2":"جناب خالد بن عداء بن ہوذہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے عرفہ کے روز رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم اپنے اونٹ پر اس کی رکابوں میں پاؤں ڈالے لوگوں کو خطبہ دے رہے تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن العلاء نے وکیع سے اسی طرح بیان کیا جیسے کہ ہناد نے کہا۔","f2":"امام ابو دائود رحمۃ اللہ علیہ کے اساتذہ ہنا وبن سری اور عثمان بن ابی شیبہ کا صحابی کے نام میں اختلاف ہواہے۔ عثمان بن ابی شیبہ عداء بن خالد بن ہوزہ کہتے ہیں۔ مگر ہناد نے خالد بن عداء کہا ہے۔امام صاحب نے ہناد کی تایئد میں ابن العلاء عن وکیع کی سند زکر فرمائی ہے۔جبکہ درج زیل سند میں عباس بن عبد العظیم کی روایت میں عداء بن خالد آیا ہے۔حافظ ابن حجر رحمہ اللہ نے تقریب التہذیب میں عداء بن خالد کی تصویب کی ہے۔واللہ اعلم۔"}],[1918,"اس سند سے بھی عداء بن خالد سے اسی مفہوم کی حدیث مروی ہے۔","صحیح",{"u2":"عبدالمجید ابوعمرو نے عداء بن خالد سے روایت کی اور مذکورہ بالا کے ہم معنی بیان کیا۔"}],[1919,"یزید بن شیبان کہتے ہیں ہمارے پاس ابن مربع انصاری آئے ہم عرفات میں تھے (وہ ایسی جگہ تھی جسے عمرو (عمرو بن عبداللہ) امام سے دور سمجھتے تھے)، انہوں نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کا بھیجا ہوا قاصد ہوں، آپ کا فرمان ہے کہ اپنے مشاعر (نشانیوں کی جگہوں) پر ٹھہرو ۱؎ اس لیے کہ تم اپنے والد ابراہیم کے وارث ہو۔\n§وضاحت\n۱؎ : مشاعر سے مراد مناسک حج کے مقامات اور قدیم مواقف ہیں، یعنی ان جگہوں پر تم بھی ٹھہرو کیونکہ ان جگہوں پر وقوف تمہارے باپ ابراہیم کے زمانہ ہی سے بطور وراثت چلا آ رہا ہے۔","صحیح",{"u2":"سیدنا یزید بن شیبان رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا ابن مربع انصاری رضی اللہ عنہ ہمارے پاس تشریف لائے جبکہ ہم عرفات میں ایسی جگہ وقوف کیے ہوئے تھے کہ عمرو بن عبداللہ اس کو امام کے موقف سے دور سمجھ رہے تھے (ابن مربع رضی اللہ عنہ نے) کہا: بیشک میں تمہاری طرف رسول اللہ صلی اللہ علیہ وسلم کا پیغامبر بن کے آیا ہوں۔ آپ نے تم لوگوں کو کہلا بھیجا ہے ” اپنے (انہی) مقامات پر وقوف کرو۔ بلاشبہ تم اپنے ابا ابراہیم (علیہ السلام) کی وراثت میں سے ایک وراثت پر ہو۔ “","f2":"میدان عرفات سارا ہی محل وقوف ہے۔"}],[1920,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عرفات سے لوٹے، آپ پر اطمینان اور سکینت طاری تھی، آپ صلی اللہ علیہ وسلم کے ردیف اسامہ رضی اللہ عنہ تھے، آپ نے فرمایا: \"لوگو! اطمینان و سکینت کو لازم پکڑو اس لیے کہ گھوڑوں اور اونٹوں کا دوڑانا کوئی نیکی نہیں ہے\"۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: میں نے انہیں (گھوڑوں اور اونٹوں کو) ہاتھ اٹھائے دوڑتے نہیں دیکھا یہاں تک کہ آپ صلی اللہ علیہ وسلم جمع (مزدلفہ) آئے، (وہب کی روایت میں اتنا زیادہ ہے) : پھر آپ صلی اللہ علیہ وسلم نے اپنے ساتھ فضل بن عباس رضی اللہ عنہما کو بٹھایا اور فرمایا: \"لوگو! گھوڑوں اور اونٹوں کو دوڑانا نیکی نہیں ہے تم اطمینان اور سکینت کو لازم پکڑو\"۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: پھر میں نے کسی اونٹ اور گھوڑے کو اپنے ہاتھ اٹھائے (دوڑتے) نہیں دیکھا یہاں تک کہ آپ صلی اللہ علیہ وسلم منی آئے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عرفات سے روانہ ہوئے تو بڑے آرام اور سکون سے چلے۔ اسامہ رضی اللہ عنہ آپ کے پیچھے بیٹھے ہوئے تھے۔ آپ نے فرمایا ” لوگو! آرام سے چلو، نیکی گھوڑے اور اونٹ دوڑانے میں نہیں۔ “ سو میں نے دیکھا کہ (کوئی بھی سواری) اپنے دونوں (اگلے) پاؤں اٹھا کر نہ دوڑ رہی تھی حتیٰ کہ آپ مزدلفہ پہنچ گئے۔ وہب نے مزید کہا: پھر آپ نے سیدنا فضل بن عباس رضی اللہ عنہ کو اپنے پیچھے بٹھا لیا اور فرمایا ” لوگو! نیکی گھوڑے اور اونٹ دوڑانے میں نہیں، سکون سے چلو۔ “ اور میں نے نہیں دیکھا کہ کوئی سواری اپنے دونوں پاؤں اٹھا کر چل رہی ہو۔ حتیٰ کہ آپ منیٰ میں آ گئے۔","f2":"نیکی اور خیر کے کاموں میں مسارعت ومسابقت بلاشبہ مطلوب ہے۔اللہ تعالیٰ کا فرمان ہے۔(وَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ)(آل عمران۔133) اورفرمایا (فَاسْتَبِقُوا الْخَيْرَاتِ)(البقرۃ۔148) مگراس کے یہ معنی نہیں کہ کام کو جلدی جلدی انجام دیں۔بلکہ ایسی صورت سے انجام دیں جو اسلامی وقار اور اسلامی شرف کے منافی اوردوسروں کے لئے اذیت کاباعث نہ ہو۔نمازکے لئے آنے کا بھی یہی ادب بتایا گیا ہے۔"}],[1921,"کریب کہتے ہیں کہ میں نے اسامہ بن زید رضی اللہ عنہما سے پوچھا: جس شام کو آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سوار ہو کر آئے تھے آپ نے کیا کیا کیا؟ وہ بولے: ہم اس گھاٹی میں آئے جہاں لوگ اپنے اونٹ رات کو قیام کے لیے بٹھاتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے اپنی اونٹنی بیٹھا دی، پھر پیشاب کیا، (زہیر نے یہ نہیں کہا کہ پانی بہایا) پھر آپ صلی اللہ علیہ وسلم نے وضو کا پانی منگایا اور وضو کیا، جس میں زیادہ مبالغہ نہیں کیا، میں نے عرض کیا: اللہ کے رسول! نماز، (پڑھی جائے) ؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"نماز آگے چل کر (پڑھیں گے)\"۔ اسامہ کہتے ہیں: پھر آپ صلی اللہ علیہ وسلم سوار ہوئے یہاں تک کہ مزدلفہ آئے، وہاں آپ نے مغرب پڑھی پھر لوگوں نے اپنی سواریاں اپنے ٹھکانوں پر بٹھائیں یہاں تک کہ عشاء کی اقامت ہوئی، آپ صلی اللہ علیہ وسلم نے عشاء پڑھی، پھر لوگوں نے اونٹوں سے اپنے بوجھ اتارے، (محمد کی روایت میں اتنا زیادہ ہے کہ کریب کہتے ہیں) پھر میں نے پوچھا: صبح ہوئی تو آپ لوگوں نے کیسے کیا؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم کے ساتھ فضل بن عباس رضی اللہ عنہما سوار ہوئے، اور میں پیدل قریش کے لوگوں کے ساتھ ساتھ چلا۔","صحیح",{"u2":"جناب کریب بیان کرتے ہیں کہ میں نے سیدنا اسامہ بن زید رضی اللہ عنہ سے کہا: مجھے یہ بتائیں کہ اس شام جب آپ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھے، آپ لوگوں نے کیسے کیا؟ انھوں نے بتایا کہ ہم اس گھاٹی میں آئے جس میں لوگ اپنی سواریاں بٹھاتے ہیں۔ وہ جگہ معرس کہلاتی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنی اونٹنی بٹھائی، پھر پیشاب کیا۔ اسامہ رضی اللہ عنہ نے «أهراق الماء» کے لفظ استعمال نہیں کیے۔ (یعنی ” پانی بہایا “ نہیں کہا) پھر آپ نے پانی طلب کیا اور وضو فرمایا جس میں کوئی مبالغہ نہ تھا۔ (یعنی ہلکا وضو کیا، اعضاء کو ایک دو بار دھویا) میں نے کہا: اے اللہ کے رسول! نماز؟ آپ نے فرمایا ” نماز تمہارے آگے ہے۔ “ (آگے چل کر پڑھیں گے) پھر آپ سوار ہو گئے حتیٰ کہ ہم مزدلفہ پہنچ گئے۔ پھر آپ نے مغرب کی نماز پڑھائی۔ پھر لوگوں نے سواریوں کو اپنے اپنے پڑاؤ پر بٹھایا مگر ان کے (پالان اور کجاوے) نہیں کھولے حتیٰ کہ عشاء کی اقامت کہلوائی اور نماز پڑھائی۔ پھر لوگوں نے (اپنی سواریوں کو) کھولا۔ محمد بن کثیر نے اپنی روایت میں مزید کہا: میں نے پوچھا: جب تم لوگوں نے صبح کی، تو کیسے کیا تھا؟ انہوں نے کہا: فضل رضی اللہ عنہ آپ کے پیچھے سوار ہوئے اور میں قریش کے ان افراد کے ساتھ پیدل چلا گیا جو دیگر لوگوں سے پہلے روانہ ہوئے تھے۔","f2":"مزدلفہ میں مغرب اورعشاء کی نمازیں جمع کرکے ہی پڑھی گئی تھیں۔دونوں نمازوں کے مابین سواریوں کو بٹھانا یا تو سواریوں پرشفقت کی غرض سے تھا یا یہ کہ کہیں وہ بکھر نہ جایئں۔ بہرحال یہ معمولی سا کام (جمع بین الصلواتین) کے منافی نہیں سمجھا جاسکتا۔"}],[1922,"علی رضی اللہ عنہ کہتے ہیں کہ پھر (ارکان عرفات سے فراغت کے بعد) آپ صلی اللہ علیہ وسلم نے اسامہ رضی اللہ عنہ کو پیچھے سوار کر لیا اور درمیانی چال سے اونٹ ہانکنے لگے، لوگ دائیں اور بائیں اپنے اونٹوں کو مار رہے تھے آپ ان کی طرف متوجہ نہیں ہوتے تھے اور فرماتے تھے: \"لوگو! اطمینان سے چلو\"، اور آپ صلی اللہ علیہ وسلم عرفات سے اس وقت لوٹے جب سورج ڈوب گیا۔","حسن",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے انہوں نے کہا: پھر آپ صلی اللہ علیہ وسلم نے اسامہ رضی اللہ عنہ کو اپنے پیچھے سوار کر لیا۔ پھر آپ صلی اللہ علیہ وسلم اپنی اونٹنی پر درمیانی چال (عنق) سے روانہ ہوئے اور لوگ دائیں بائیں اونٹوں کو پیٹ رہے تھے۔ آپ صلی اللہ علیہ وسلم ان کی طرف متوجہ نہ ہوتے تھے اور فر رہے تھے ” لوگو! سکون کے ساتھ! “ اور آپ صلی اللہ علیہ وسلم عرفات سے سورج غروب ہونے کے بعد روانہ ہوئے۔","f2":"سنن ابی دائود کے اکثر نسخوں میں (لايلتفت اليهم)کالفظ آیا ہے۔مگر بذل المجہود میں مولانا خلیل احمد صاحب سہارنپوری نے لکھا ہے۔کہ جامع ترمذی مسند احمد اور سنن بہیقی کی بعض اسانید میں لفظ لا موجود نہیں ہے اس طرح کوئی اشکال نہیں رہتا۔مگر مسند احمد کی سند میں (لايلتفت) ہی آیا ہے۔جبکہ علامہ البانی رحمۃ اللہ علیہ نے صحیح سنن ابی دائود میں اس کو غیر محفوظ لکھا ہے۔(لايلتفت) کالفظ ہی صحیح ہے۔یعنی آپ لوگوں کی طرف ملتفت ہو رہے تھے۔"}],[1923,"عروہ کہتے ہیں کہ میں بیٹھا ہوا تھا کہ اسامہ بن زید رضی اللہ عنہما سے سوال کیا گیا: رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع میں عرفات سے لوٹتے وقت کیسے چلتے تھے؟ فرمایا: تیز چال چلتے تھے، اور جب راستہ پا جاتے تو دوڑتے۔ ہشام کہتے ہیں: «نص» ، «عنق» سے بھی زیادہ تیز چال کو کہتے ہیں۔","صحیح",{"u2":"جناب عروہ رضی اللہ عنہ نے بیان کیا کہ سیدنا اسامہ بن زید رضی اللہ عنہ سے پوچھا گیا، اور میں (اس مجلس میں) بیٹھا تھا، کہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع میں جب عرفہ سے روانہ ہوئے تھے تو کس رفتار سے چلے تھے؟ انہوں نے کہا کہ آپ صلی اللہ علیہ وسلم درمیانی رفتار (عنق) سے چلے تھے۔ جب کوئی فراخی پاتے تو قدرے تیز ہو جاتے۔ ہشام نے کہا کہ «نص» والی رفتار «عنق» سے قدرے تیز تر ہوتی ہے۔","f2":"تابعین کرام اور صحابہ کرامرضوان اللہ عنہم اجمعین میں اس مسئلے کا مذاکرہ دلیل ہے۔خیر القرون کے یہ حضرات رسول اللہ صلی اللہ علیہ وسلم کے ایک ایک فعل کے امین اور اس کے قائل وفاعل تھے۔"}],[1924,"اسامہ رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پیچھے سواری پر تھا جب سورج ڈوب گیا تو آپ صلی اللہ علیہ وسلم عرفات سے لوٹے۔","حسن صحیح",{"u2":"سیدنا اسامہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کے پیچھے سوار تھا، جب سورج غروب ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم وہاں سے روانہ ہوئے (یعنی عرفات سے)۔"}],[1925,"عبداللہ بن عباس رضی اللہ عنہما کے غلام کریب کی روایت ہے کہ انہوں نے اسامہ بن زید رضی اللہ عنہما کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم عرفات سے لوٹے جب گھاٹی میں آئے تو اترے، پیشاب کیا اور وضو کیا لیکن بھرپور وضو نہیں کیا، میں نے آپ سے عرض کیا: نماز (کا وقت ہو گیا ہے) آپ صلی اللہ علیہ وسلم نے فرمایا: \"نماز آگے چل کر پڑھیں گے\"، پھر آپ سوار ہوئے جب مزدلفہ پہنچے تو اترے وضو کیا اور اچھی طرح سے وضو کیا، پھر نماز کی تکبیر کہی گئی تو آپ صلی اللہ علیہ وسلم نے مغرب پڑھی پھر ہر شخص نے اپنے اونٹ کو اپنے قیام گاہ میں بٹھایا پھر عشاء کی اقامت ہوئی تو آپ نے عشاء پڑھی اور درمیان میں کچھ نہیں پڑھا۔","صحیح",{"u2":"کریب مولیٰ عبداللہ بن عباس رضی اللہ عنہ نے سیدنا اسامہ بن زید رضی اللہ عنہ سے سنا وہ کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم عرفات سے روانہ ہوئے حتیٰ کہ جب گھاٹی میں پہنچے تو اترے، پیشاب کیا، پھر وضو کیا مگر اس میں مبالغہ نہیں تھا۔ میں نے عرض کیا: نماز؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نماز تمہارے آگے ہے۔ “ (یعنی آگے پڑھیں گے) پھر آپ صلی اللہ علیہ وسلم سوار ہو گئے۔ جب مزدلفہ پہنچے، تو اترے وضو کیا اور کامل وضو کیا۔ پھر نماز کی اقامت کہی گئی تو مغرب کی نماز پڑھائی، پھر ہر شخص نے اپنے اپنے اونٹ کو اپنے اپنے پڑاؤ میں بٹھایا، پھر عشاء کی اقامت کہی گئی تو آپ صلی اللہ علیہ وسلم نے نماز پڑھائی اور ان کے مابین کچھ نہیں پڑھا۔"}],[1926,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مغرب اور عشاء مزدلفہ میں ایک ساتھ پڑھی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مغرب اور عشاء کی نمازیں مزدلفہ میں اکٹھی کر کے پڑھیں۔"}],[1927,"اس سند سے بھی زہری سے اسی طریق سے اسی مفہوم کی حدیث مروی ہے البتہ اس میں ہے کہ ایک ہی اقامت سے دونوں کو جمع کیا۔ احمد کہتے ہیں: وکیع نے کہا: ہر نماز الگ الگ اقامت سے پڑھی۔","صحیح",{"u2":"زہری رضی اللہ عنہ نے اپنی سند سے مذکورہ بالا حدیث کے ہم معنی روایت کی اور کہا ایک ایک اقامت سے ان دونوں نمازوں کو جمع کیا۔ امام احمد رضی اللہ عنہ نے کہا: وکیع نے بیان کیا کہ آپ نے ہر نماز (الگ) اقامت سے پڑھی۔"}],[1928,"اس سند سے بھی زہری سے ابن حنبل کی سند سے انہوں نے حماد سے اسی مفہوم کی حدیث روایت کی ہے اس میں ہے: ہر نماز کے لیے ایک الگ اقامت کہی اور پہلی نماز کے لیے اذان نہیں دی اور نہ ان دونوں میں سے کسی کے بعد نفل پڑھی۔ مخلد کہتے ہیں: ان دونوں میں سے کسی نماز کے لیے اذان نہیں دی۔","صحیح",{"u2":"عثمان بن عمر رضی اللہ عنہ نے ابن ابی ذئب سے انہوں نے زہری سے یعنی امام احمد بن حنبل عن حماد کی سند سے اور اس کے ہم معنی بیان کیا کہ ہر نماز کے لیے ایک اقامت کہی۔ اور پہلی میں اذان نہیں دی اور نہ کسی کے بعد سنتیں پڑھیں۔ مخلد نے کہا: ان میں سے ایک کے لیے اذان نہیں دی۔","f2":"علامہ البانی رحمۃ اللہ علیہ کہتے ہیں۔کہ یہ روایت صحیح ہے۔البتہ(لم یناد۔۔۔) کے الفاظ صحیح نہیں ہیں۔اس لیے کہ ایک مرتبہ تو اذان دی گئی بنا بریں اذان کی نفی صحیح نہیں۔"}],[1929,"عبداللہ بن مالک کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کے ساتھ مغرب تین رکعت اور عشاء دو رکعت پڑھی، تو مالک بن حارث نے ان سے کہا: یہ کون سی نماز ہے؟ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ یہ دونوں اسی جگہ ایک تکبیر سے پڑھیں۔","صحیح",{"u2":"عبداللہ بن مالک (بن حارث) بیان کرتے ہیں کہ میں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ کے ساتھ نماز پڑھی۔ مغرب کی تین اور عشاء کی دو رکعتیں۔ مالک بن حارث نے ان سے کہا: یہ کس طرح کی نماز ہے؟ انہوں نے کہا: میں نے ان کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اس جگہ ایک ہی تکبیر کے ساتھ پڑھا ہے۔","f2":"اس حدیث میں ایک ہی تکبیر سے دو نمازوں کے پڑھنے کا زکر ہے۔جبکہ ہرنماز کے لئے الگ الگ سے اقامت کہناصحیح تر احادیث سے ثابت ہے۔(صحیح البخاری الحج حدیث۔1673)اسی حدیث کی بابت شیخ البانی کہتے ہیں۔کہ یہ روایت (لکل صلاۃ) (یعنی ہرنماز کےلئے الگ الگ تکبیر کہی) کی زیادتی کے ساتھ صحیح ہے۔"}],[1930,"سعید بن جبیر اور عبداللہ بن مالک سے روایت ہے وہ دونوں کہتے ہیں: ہم نے ابن عمر رضی اللہ عنہما کے ساتھ مزدلفہ میں مغرب و عشاء ایک اقامت سے پڑھیں، پھر راوی نے ابن کثیر کی حدیث کے ہم معنی حدیث ذکر کی۔","صحیح",{"u2":"سعید بن جبیر اور عبداللہ بن مالک دونوں سے روایت ہے کہ ہم نے ابن عمر رضی اللہ عنہ سے ساتھ مزدلفہ میں مغرب اور عشاء کی نمازیں ایک تکبیر کے ساتھ پڑھیں۔ اور محمد بن کثیر کی روایت کے ہم معنی بیان کیا۔","f2":"اس روایت میں بھی ایک تکبیر کے ساتھ دو نمازیں پڑھنے کازکر ہے۔جو کہ صحیح نہیں ہے شیخ البانی رحمۃ اللہ علیہ اس روایت کی بابت لکھتے ہیں کہ یہ روایت (لکل صلاۃ) (ہر نماز کے لئے الگ تکبیر کہی) کے اضافے کے ساتھ صحیح ہے۔"}],[1931,"سعید بن جبیر کہتے ہیں کہ ہم (عرفات سے) ابن عمر رضی اللہ عنہما کے ساتھ لوٹے، جب ہم جمع یعنی مزدلفہ پہنچے تو آپ نے ہمیں مغرب اور عشاء، تین رکعت مغرب کی اور دو رکعت عشاء کی ایک اقامت ۱؎ سے پڑھائی، جب ہم نماز سے فارغ ہوئے تو ابن عمر رضی اللہ عنہما نے ہم سے کہا: اسی طرح ہمیں رسول اللہ صلی اللہ علیہ وسلم نے اس جگہ پڑھائی تھی۔\n§وضاحت\n۱؎ : اس کے برخلاف جابر رضی اللہ عنہ کی ایک روایت صحیح مسلم میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک اذان اور دو تکبیر سے دونوں نمازیں ادا کیں اور یہی راجح ہے، واللہ اعلم۔","صحیح",{"u2":"سعید بن جبیر نے کہا کہ ہم سیدنا ابن عمر رضی اللہ عنہ کی معیت میں (عرفات سے) لوٹے۔ جب مزدلفہ پہنچے تو انہوں نے ہمیں مغرب اور عشاء کی نمازیں تین رکعتیں اور دو رکعتیں ایک تکبیر کے ساتھ پڑھائیں۔ جب فارغ ہوئے تو ابن عمر رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس جگہ ہمیں اسی طرح نماز پڑھائی تھی۔","f2":"اس میں بھی ایک اقامت کا زکر ہے۔جو درست نہیں ہے جیسا کہ گزشتہ حدیث میں گزرا ہے۔"}],[1932,"سلمہ بن کہیل کہتے ہیں میں نے سعید بن جبیر کو دیکھا انہوں نے مزدلفہ میں اقامت کہی پھر مغرب تین رکعت پڑھی اور عشاء دو رکعت، پھر آپ نے کہا: میں نے دیکھا کہ ابن عمر رضی اللہ عنہما نے اس مقام پر اسی طرح کیا اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس مقام پر اسی طرح کرتے دیکھا۔","صحیح",{"u2":"سلمہ بن کہیل نے کہا کہ میں نے جناب سعید بن جبیر رضی اللہ عنہ کو مزدلفہ میں دیکھا کہ انہوں نے اقامت کہی اور مغرب کی تین رکعتیں پڑھیں پھر عشاء کی دو رکعتیں پڑھیں۔ پھر کہا: میں سیدنا ابن عمر رضی اللہ عنہ کے ساتھ حاضر تھا انہوں نے اس جگہ اسی طرح کیا تھا اور انہوں نے بیان کیا تھا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا اور آپ صلی اللہ علیہ وسلم نے اس جگہ اسی طرح کیا تھا۔","f2":"اس حدیث میں بھی ایک تکبیر کازکر ہے۔جو کہ درست نہیں ہے۔دیکھئے گزشتہ احادیث کے فوائد۔"}],[1933,"سلیم بن اسود ابوالشعثاء محاربی کہتے ہیں کہ میں ابن عمر رضی اللہ عنہما کے ساتھ عرفات سے مزدلفہ آیا وہ تکبیر و تہلیل سے تھکتے نہ تھے، جب ہم مزدلفہ آ گئے تو انہوں نے اذان کہی اور اقامت، یا ایک شخص کو حکم دیا کہ وہ اذان اور اقامت کہے، پھر ہمیں مغرب تین رکعت پڑھائی، پھر ہماری طرف متوجہ ہوئے اور کہا: عشاء پڑھ لو چنانچہ ہمیں عشاء دو رکعت پڑھائی پھر کھانا منگوایا۔ اشعث کہتے ہیں: اور مجھے علاج بن عمرو نے میرے والد کی حدیث کے مثل حدیث کی خبر دی ہے جو انہوں نے ابن عمر رضی اللہ عنہما سے روایت کی ہے وہ کہتے ہیں: ابن عمر رضی اللہ عنہما سے لوگوں نے اس بارے میں پوچھا تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اسی طرح نماز پڑھی ہے۔","صحیح",{"u2":"اشعت بن سلیم اپنے والد سے بیان کرتے ہیں کہ میں سیدنا ابن عمر رضی اللہ عنہ کے ساتھ عرفات سے مزدلفہ آیا۔ انہوں نے اس دوران میں تکبیر اور تہلیل کو نہیں چھوڑا حتیٰ کہ ہم مزدلفہ پہنچ گئے۔ پھر اذان اور اقامت کہی یا کسی کو حکم دیا کہ اذان اور اقامت کہے ‘ پھر ہمیں مغرب کی تین رکعتیں پڑھائیں ‘ پھر ہماری طرف متوجہ ہوئے اور کہا: نماز (عشاء کی بھی) پس ہمیں عشاء کی نماز پڑھائی، دو رکعتیں۔ پھر اپنا رات کا کھانا طلب کیا۔ (اشعت بن سلیم نے) کہا: مجھے علاج بن عمرو نے اسی طرح بیان کیا جیسے کہ میرے والد (سلیم بن اسود) نے ابن عمر رضی اللہ عنہ سے روایت کیا۔ سیدنا ابن عمر رضی اللہ عنہ سے اس بارے میں پوچھا گیا تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایسے ہی پڑھی تھی۔","f2":"علامہ البانی رحمۃ اللہ علیہ اس روایت کی بابت لکھتے ہیں کہ (فقال الصلاۃ) (آپ ہماری طرف متوجہ ہوئے اور کہا نماز!)کے الفاظ شاذ ہیں۔البتہ(فاقام الصلاۃ) تکبیر کہلوائی کے الفاظ صحیح تر ہیں۔"}],[1934,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ہمیشہ وقت پر ہی نماز پڑھتے دیکھا سوائے مزدلفہ کے، مزدلفہ میں آپ صلی اللہ علیہ وسلم نے مغرب اور عشاء کو جمع کیا اور دوسرے دن فجر وقت معمول سے کچھ پہلے پڑھی ۱؎۔\n§وضاحت\n۱؎ : ترجمہ سے اس حدیث کا صحیح معنی واضح ہو گیا، بعض لوگوں کا یہ کہنا ہے کہ ’’ اس سے یہ ثابت ہوتا ہے کہ آپ صلی اللہ علیہ وسلم ہمیشہ غلس کے بعد اسفار میں نماز پڑھتے تھے صرف اس دن غلس میں پڑھی‘‘ ، لیکن دیگر صحیح روایات کی روشنی میں اس حدیث کا صحیح مطلب یہ ہے کہ: غلس ہی میں فوراً پڑھ لی، عام حالات کی طرح تھوڑا انتظار نہیں کیا۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کبھی نہیں دیکھا کہ آپ صلی اللہ علیہ وسلم نے کوئی نماز بے وقت پڑھی ہو۔ آپ صلی اللہ علیہ وسلم ہمیشہ وقت پر نماز پڑھتے تھے مگر مزدلفہ میں آپ صلی اللہ علیہ وسلم نے مغرب اور عشاء کو جمع کر کے پڑھا (تاخیر سے) اور اگلے دن کی فجر کی نماز اپنے وقت سے پہلے پڑھی۔","f2":"1۔یعنی فجر کی نماز بہت جلد پڑھائی۔جو کہ آپکے عام معمول کا وقت نہ تھا۔اور فضا میں بہت اندھیرا تھا مگر فجر صادق طلوع ہوچکی تھی۔2۔بعض فقہاء(حسن بصری ابراہیم نخعی۔امام ابو حنیفہ رحمۃ اللہ علیہ اور ان کےصاحبین رحمۃ اللہ علیہ کا اس حدیث سے استدلال ہے کہ سفر میں نمازیں جمع کرنا جائز نہیں۔سوائے عرفات اور مزدلفہ کے کیونکہ حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نبی صلی اللہ علیہ وسلم کے ساتھ ساتھ رہنے والے صحابی ہیں۔وہ کہتے ہیں کہ اس مقام کے علاوہ آپ صلی اللہ علیہ وسلم نے کبھی کوئی نماز بے وقت نہیں پڑھی۔سو جمع بین الصلاتین جائز نہیں۔جبکہ اصحاب الحدیث اور جمہور فقہاء جمع بین الصلاتین کے قائل وفائل ہیں۔ان کااستدلال رسول اللہ صلی اللہ علیہ وسلم کے قول وفعل سے ہے جیسے کہ گزشتہ ابواب صلواۃ السفر (حدیث 198 او ما بعدہ) کے مطالعہ سے واضح ہیں۔ حضرت عبدا للہ بن مسعود رضی اللہ تعالیٰ عنہ کی اس روایت میں نبی صلی اللہ علیہ وسلم کے عام معمولات اور نماز بروقت ادا کرنے کی پابندی کابیان ہے۔جو بصورت مفہوم زکر کیا گیا ہے جبکہ دیگر صریح فرامین اور آپ کے معمولات جمع بین الصلاتین کو ثابت کرتے ہیں۔تو جہاں کہیں احادیث کا مفہوم اور منطوق (ظاہر الفاظ) متعارض معلوم ہوتے ہوں وہاں منطوق کو مقدم کیا جاتا ہے۔"}],[1935,"علی رضی اللہ عنہ کہتے ہیں کہ (مزدلفہ میں) جب آپ نے یعنی نبی اکرم صلی اللہ علیہ وسلم نے صبح کی تو آپ قزح میں کھڑے ہوئے اور فرمایا: \"یہ قزح ہے اور یہ موقف (ٹھہرنے کی جگہ) ہے، اور مزدلفہ پورا موقف (ٹھہرنے کی جگہ) ہے، میں نے یہاں نحر کیا ہے اور منی پورا نحر کرنے کی جگہ ہے لہٰذا تم اپنے اپنے ٹھکانوں میں نحر کر لو\"۔","حسن صحیح",{"u2":"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ (مزدلفہ میں) جب نبی کریم صلی اللہ علیہ وسلم نے صبح کی اور جبل قزح پر وقوف کیا تو فرمایا ” یہ قزح ہے اور جائے وقوف ہے۔ اور مزدلفہ سارا ہی جائے وقوف ہے۔ میں نے اس جگہ قربانی کی ہے اور منیٰ سب ہی قربان گاہ ہے۔ سو اپنے اپنے پڑاؤ پر قربانیاں کرو۔ “"}],[1936,"جابر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں عرفات میں اس جگہ ٹھہرا ہوں لیکن عرفات پورا جائے وقوف ہے، میں مزدلفہ میں یہاں ٹھہرا ہوں لیکن مزدلفہ پورا جائے وقوف ہے، میں نے یہاں پر نحر کیا اور منی پورا جائے نحر ہے لہٰذا تم اپنے ٹھکانوں میں نحر کرو\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” میں نے عرفات میں اس جگہ پر وقوف کیا ہے اور عرفات سارے کا سارا جائے وقوف ہے۔ میں نے مزدلفہ میں اس جگہ پر وقوف کیا ہے اور مزدلفہ سارا ہی جائے وقوف ہے۔ اور میں نے اس جگہ قربانی کی ہے اور منیٰ سب ہی قربان گاہ ہے۔ پس تم اپنے اپنے پڑاؤ پر قربانیاں کرو۔ “"}],[1937,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پورا عرفات جائے وقوف ہے پورا منی جائے نحر ہے اور پورا مزدلفہ جائے وقوف ہے مکہ کے تمام راستے چلنے کی جگہیں ہیں اور ہر جگہ نحر درست ہے\"۔","حسن صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” عرفات سارا ہی مقام وقوف ہے اور منٰی سارا ہی قربان گاہ ہے اور مزدلفہ پورا ہی وقوف کی جگہ ہے۔ اور مکہ کے سب راستے (یہاں آنے کی) راہ ہیں اور قربان گاہ بھی۔ “","f2":"عرفات مزدلفہ اور منیٰ میں رسول اللہ صلی اللہ علیہ وسلم کے مقام ہائے وقوف معروف ہیں۔اگر بغیر کسی اذدھام واذیت دینے کے ان مقامات پر وقوف کا موقع مل جائے تو شرف ہے ورنہ ثواب سبھی جگہ برابر ہے۔اسی طرح مکے میں داخلے کے لئے کداء والی جانب افضل ہے ورنہ کہیں سے بھی آیا جاسکتا ہے۔اسی طرح قربانی کے لئے منیٰ افضل ہے۔"}],[1938,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ جاہلیت کے لوگ مزدلفہ سے نہیں لوٹتے تھے جب تک کہ سورج کو ثبیر ۱؎ پر نہ دیکھ لیتے، چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے ان کی مخالفت کی اور سورج نکلنے سے پہلے ہی (مزدلفہ سے) چل پڑے۔\n§وضاحت\n۱؎ : ’’ثبير‘‘: مزدلفہ میں ایک مشہور پہاڑی کا نام ہے۔","صحیح",{"u2":"عمر بن خطاب رضی اللہ عنہ نے بیان کیا کہ اہل جاہلیت (مزدلفہ سے) اس وقت تک روانہ نہیں ہوتے تھے جب تک کہ کوہ ثبیر پر سورج کو (طلوع ہوتا) نہ دیکھ لیتے۔ سو نبی کریم صلی اللہ علیہ وسلم نے ان کی مخالفت کی اور طلوع آفتاب سے پہلے ہی وہاں سے روانہ ہو لیے۔","f2":"مزدلفہ سے روانگی کا اصل وقت نمازفجر کے بعد سورج نکلنے سے پہلے ہے صرف ضعیفوں کے لئے رخصت ہے کہ وہ آدھی رات کے بعد جاسکتے ہیں۔"}],[1939,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں بھی ان لوگوں میں سے تھا جن کو رسول اللہ صلی اللہ علیہ وسلم نے اپنے گھر کے لوگوں میں سے کمزور جان کر مزدلفہ کی رات کو پہلے بھیج دیا تھا ۱؎۔\n§وضاحت\n۱؎ : اس سے معلوم ہوا کہ عورتوں اور بچوں کو مزدلفہ سے رات ہی میں منی روانہ کر دینا جائز ہے، تا کہ وہ بھیڑ بھاڑ سے پہلے کنکریاں مار کر فارغ ہو جائیں، لیکن سورج نکلنے سے پہلے کنکریاں نہ ماریں، جیسا کہ اگلی حدیث میں ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے اہل کے ان ضعیف افراد میں شامل تھا جن کو آپ صلی اللہ علیہ وسلم نے مزدلفہ کی رات قبل از وقت روانہ فر دیا تھا۔","f2":"خواتین بچے مریض بوڑھے اور کمزور افراد کے لیے رخصت ہے کہ وہ مزدلفہ سے فجر کی نماز سے پہلے ہی منی کو روانہ ہو جائیں۔"}],[1940,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالمطلب کی اولاد میں سے ہم چھوٹے بچوں کو گدھوں پر سوار کر کے مزدلفہ کی رات پہلے ہی روانہ کر دیا تھا، آپ صلی اللہ علیہ وسلم ہماری رانوں پر دھیرے سے مارتے تھے اور فرماتے تھے:\"اے میرے چھوٹے بچو! جمرہ پر کنکریاں نہ مارنا جب تک کہ آفتاب طلوع نہ ہو جائے\"۔ ابوداؤد کہتے ہیں: «لطح» کے معنی آہستہ مارنے کے ہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے مزدلفہ کی رات ہم بنی عبدالمطلب کے چھوٹے لڑکوں کو گدھوں پر سوار کر کے آگے بھیج دیا تھا۔ اس موقع پر آپ صلی اللہ علیہ وسلم ہماری رانوں پر آہستہ آہستہ مارتے ہوئے فر رہے تھے ” بچو! سورج طلوع ہونے سے پہلے جمرہ کو کنکریاں نہ مارنا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «اللطخ» کا معنی ہے ” نرم انداز میں مارنا۔ “"}],[1941,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے گھر کے کمزور اور ضعیف لوگوں کو اندھیرے ہی میں منی روانہ کر دیتے تھے اور انہیں حکم دیتے تھے کہ کنکریاں نہ مارنا جب تک کہ آفتاب نہ نکل آئے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے اہل کے ضعیف افراد کو اندھیرے ہی میں آگے روانہ فر دیا کرتے تھے۔ اور انہیں حکم دیتے تھے کہ سورج طلوع ہونے تک جمرہ کو کنکریاں نہ ماریں۔","f2":"دسویں تاریخ کو رمی جمرہ کامسنون وقت سورج طلوع ہونے کے بعد ہے۔"}],[1942,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ام سلمہ کو نحر کی رات (دسویں رات) کو (منی کی طرف)روانہ فرما دیا انہوں نے فجر سے پہلے کنکریاں مار لیں پھر مکہ جا کر طواف افاضہ کیا، اور یہ وہ دن تھا جس دن رسول اللہ صلی اللہ علیہ وسلم ان کے پاس رہا کرتے تھے ۱؎۔\n§وضاحت\n۱؎ : یعنی یہ ام المومنین ام سلمہ رضی اللہ عنہا کی باری کا دن تھا۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ ام سلمہ رضی اللہ عنہا ا کو نحر والی رات فجر سے پہلے ہی (منیٰ کی جانب) بھیج دیا۔ پس انہوں نے (طلوع) فجر سے پہلے ہی جمرہ کو کنکریاں مار لیں پھر وہ چلی گئیں اور طواف افاضہ کر لیا۔ اور یہ انہی کی باری کا دن تھا کہ رسول اللہ صلی اللہ علیہ وسلم ان کے ہاں تھے۔"}],[1943,"اسماء رضی اللہ عنہا سے روایت ہے کہ انہوں نے جمرہ کو کنکریاں ماریں، مخبر (راوی حدیث) کہتے ہیں: میں نے عرض کیا: ہم نے رات ہی کو جمرے کو کنکریاں مار لیں، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے عہد میں ایسا ہی کیا کرتے تھے۔","صحیح",{"u2":"ایک خبر دینے والے نے بیان کیا کہ سیدہ اسماء (بنت ابی بکر) رضی اللہ عنہ ا نے جمرہ کی رمی کی تو میں نے کہا: ہم نے تو رات میں رمی کی ہے۔ (کنکریاں ماری ہیں) انہوں نے جواب دیا کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم یہی کیا کرتے تھے۔","f2":"مذکورہ دونوں روایتوں میں سورج طلوع ہونے سے قبل کنکریاں مارنے کا ذکر ہے۔اس کی بابت صاحب عون لکھتے ہیں کہ یہ صرف عورتوں بچوں اور ان کے غلاموں کے لیے ہے جو ان کی خدمت کے لیے ہوں۔ ان کے علاوہ دس ذوالحجہ کو کسی کے لیے جائز نہیں کہ وہ طلوع فجر سے پہلے کنکریاں مارے جیسا کہ صحیح احادیث سے ثابت ہے۔واللہ اعلم ."}],[1944,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مزدلفہ سے اطمینان و سکون کے ساتھ لوٹے اور لوگوں کو حکم دیا کہ اتنی چھوٹی چھوٹی کنکریاں ماریں جو ہاتھ کی دونوں انگلیوں کے سروں کے درمیان آ سکیں اور وادی محسر میں آپ نے اپنی سواری کو تیز کیا۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم (مزدلفہ سے) روانہ ہوئے اور بڑے سکون اور آرام سے چلے۔ اور لوگوں کو حکم دیا کہ چھوٹی چھوٹی کنکریاں ماریں (مگر) وادی محسر میں سے تیزی سے نکلے تھے۔","f2":"وادی محشر میں اصحاب الفیل پر عذاب نازل ہوا تھا اور مقامات عذاب سے بڑی جلدی نکل جانا چاہیے"}],[1945,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نحر کے روز (دسویں ذی الحجہ کو) حجۃ الوداع میں جمرات کے درمیان کھڑے ہوئے اور لوگوں سے پوچھا: \"یہ کون سا دن ہے؟\"، لوگوں نے جواب دیا: یوم النحر، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہی حج اکبر کا دن ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی قرآن مجید میں جو «يوم الحج الأكبر» آیا ہے اس سے مراد یوم نحر ہی ہے، حج کو حج اکبر کہا جاتا ہے اور عمرہ کو حج اصغر، اور وہ جو عوام میں مشہور ہے کہ ’’ جمعہ کے دن یوم عرفہ پڑے تو حج اکبر ہے ‘‘ تو یہ بات بے دلیل اور بے اصل ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم اپنے حج میں قربانی والے دن جمرات کے درمیان کھڑے ہوئے اور پوچھا ” یہ کون سا دن ہے؟ “ لوگوں نے کہا: یہ قربانی کا دن ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ حج اکبر کا دن ہے۔ “"}],[1946,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ مجھے ابوبکر رضی اللہ عنہ نے یوم النحر کو منی ان لوگوں میں بھیجا جو پکار رہے تھے کہ اس سال کے بعد کوئی مشرک حج نہیں کرے گا اور نہ ہی کوئی ننگا بیت اللہ کا طواف کرے گا، اور حج ا کبر کا دن یوم النحر ہے اور حج اکبر سے مراد حج ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ سیدنا ابوبکر صدیق رضی اللہ عنہ نے مجھے ان لوگوں کے ساتھ بھیجا جنہوں نے قربانی کے روز منیٰ میں یہ اعلان کیا تھا کہ اس سال کے بعد کوئی مشرک حج کے لیے نہ آئے۔ اور کوئی شخص بے لباس ہو کر بیت اللہ کا طواف نہ کرے۔ اور قربانی کا دن (یوم النحر ہی) حج اکبر کا دن ہے۔ اور حج اکبر سے مراد حج ہے۔","f2":"(1)رسول اللہ صلی اللہ علیہ وسلم نے اپنے حج سے ایک سال پہلے نو ہجری میں حضرت ابوبکر کو امیر حج بنا کر روانہ فرمایا تھا اور اس موقع پر سورہ براءۃ (سورہ توبہ)کی آیات کے ذریعے سے کفار سے اعلان براءت کیا گیا تھا۔(2)مشرکین کو حرم میں داخلہ کی اجازت نہیں۔ انہیں طاقت کے ذریعے سے اس سے روکا جانا ضروری ہے۔(3)طواف کے لیے ستر واجب ہے۔(4)یوم النحر (قربانی کا دن)حج اکبر کا دن ہے۔ سورہ توبہ میں ہے ﴿وَأَذ‌ٰنٌ مِنَ اللَّهِ وَرَ‌سولِهِ إِلَى النّاسِ يَومَ الحَجِّ الأَكبَرِ‌ أَنَّ اللَّهَ بَر‌ىءٌ مِنَ المُشرِ‌كينَ ۙ وَرَ‌سولُهُ.......﴾(التوبه:3) اللہ اور اس کے رسول کی طرف سے لوگوں کو بڑے حج کے دن صاف اطلاع ہے کہ اللہ مشرکوں سے بیزار ہے، اور اس کا رسول بھی۔ (5)حج اکبر سےمراد حج ہے۔جبکہ کچھ روایات میں عمرہ کو حج اصغر سے تعبیر کیا گیا ہے۔ یہ احادیث عوام الناس میں مشہور اس قول کی تردید کرتی ہیں کہ جب یوم عرفہ اور یوم جمعہ جمع ہو جائیں تو وہ حج اکبر ہوتاہے۔ نہیں! بلکہ ہر حج خواہ وہ کسی بھی روز ہو حج اکبر ہی ہوتا ہے۔ جمعہ کے روز یوم عرفہ کا واقع ہونا ایک اتفاقی امر ہے اور اللہ کےہاں قبولیت میں کوئی فرق نہیں۔"}],[1947,"ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے حج میں خطبہ دیا تو فرمایا: \"زمانہ پلٹ کر ویسے ہی ہو گیا جیسے اس دن تھا جب اللہ نے آسمان اور زمین کی تخلیق فرمائی تھی، سال بارہ مہینے کا ہوتا ہے، ان میں سے چار مہینے حرام ہیں: تین لگاتار ہیں، ذی قعدہ، ذی الحجہ اور محرم اور ایک مضر کا رجب ہے ۱؎ جو جمادی الآخرہ اور شعبان کے بیچ میں ہے\"۔\n§وضاحت\n۱؎ : رجب کی نسبت قبیلہ مضر کی طرف اس لئے کی گئی ہے کہ یہ رجب کی حرمت کے سلسلہ میں زیادہ سخت تھے، اور دیگر عرب قبائل کے مقابلہ میں اس کی حرمت کا پاس و لحاظ زیادہ رکھتے تھے۔","صحیح",{"u2":"سیدنا ابوبکر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے حج میں خطبہ دیتے ہوئے ارشاد فرمایا ” بلاشبہ زمانہ اپنی اس (اصل) کیفیت پر گھوم آیا ہے (جس پر کہ اپنے پہلے روز تھا) جب کہ ا اللہ نے آسمانوں اور زمیں کو پیدا فرمایا تھا۔ سال کے بارہ مہینے ہیں، اور ان میں سے چار مہینے حرمت والے ہیں۔ تین مہینے متواتر ہیں، یعنی ذوالقعدہ، ذوالحجہ اور محرم اور چوتھا مضر کا رجب ہے جو جمادی اور شعبان کے درمیان ہوتا ہے۔ “","f2":"(1)اہل عرب میں قدیم سے یہ روایت چلی آتی تھی کہ ذوالقعدہ ذوالحجہ محرم اور رجب کےمہینوں کو حرمت والے مہینے جانتے تھے اور ان میں قتل و غارت اور عام دنگا فساد سےپرہیز کرتے تھے۔چنانچہ اسلام نے بھی ان کی حرمت کو بحال رکھا ہے مگر اس کایہ مفہوم نہیں کہ باقی مہینوں میں جو چاہے کیاجائے نہیں بلکہ ہمیشہ ہی اللہ کی حرمت کا پاس رکھنا فرض اورواجب ہے مگر ان مہینوں میں اور زیادہ اہتمام کیا جانا چاہیے۔سورہ توبہ میں ہے:﴿إِنَّ عِدَّةَ الشُّهورِ‌ عِندَ اللَّهِ اثنا عَشَرَ‌ شَهرً‌ا فى كِتـٰبِ اللَّهِ يَومَ خَلَقَ السَّمـٰو‌ٰتِ وَالأَر‌ضَ مِنها أَر‌بَعَةٌ حُرُ‌مٌ﴾ (التوبه:36) مہینوں کی گنتی اللہ کے نزدیک کتاب اللہ میں باره کی ہے، اسی دن سے جب سے آسمان وزمین کو اس نے پیدا کیا ہے اس میں سے چار حرمت وادب کے ہیں۔(2) زمانہ گھوم آیاہے اس میں اہل جاہلیت کی اس قبیح رسم کی طرف اشارہ ہے کہ وہ لوگ مہینوں کو آگے پیچھے کر دیتے تھے۔مثلاً محرم کوصفر کی جگہ مؤخر اور صفر کومقدم کر دیا اور اسے نسیء سےتعبیر کرتے تھے۔ اس طرح سال کی تاریخوں میں بہت خرابی پیدا ہوگئی تھی۔اورجس سال نبی صلی اللہ علیہ وسلم نے حج کیا اس سال اور تاریخ اپنے بالکل صحیح وقت پرآئی تھی۔قرآن کریم نے عمل نسیء کو کفریہ اعمال میں سے شمار کیا ہے اورآیندہ صحیح تاریخ کی حفاظت کی ترغیب دی ہے۔﴿انما النسىءزيادة فى الكفر .... الخ ﴾ (التوبه:37) (3)ماہ رجب کو قبیلہ مضر کی طرف اس لیے منسوب کیا گیاہے کہ وہ لوگ اس کابہت زیادہ احترام کرتے تھے۔"}],[1948,"اس سند سے بھی ابوبکرہ رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کی ہے۔ ابوداؤد کہتے ہیں: ابن عون نے اس حدیث میں ان کا نام لیا ہے اور یوں کہا ہے «عن عبدالرحمٰن بن أبي بكرة عن أبي بكرة» ۔","صحیح",{"u2":"محمد بن سیرین، ابن ابی بکرہ سے وہ (اپنے والد) ابوبکرہ رضی اللہ عنہ سے وہ نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی روایت کرتے ہیں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن عون نے نام لے کر کہا کہ عبدالرحمٰن بن ابی بکرہ (اپنے والد) ابوبکرہ رضی اللہ عنہ سے روایت کرتے ہیں۔"}],[1949,"عبدالرحمٰن بن یعمر دیلی رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ عرفات میں تھے، اتنے میں نجد والوں میں سے کچھ لوگ آئے، ان لوگوں نے ایک شخص کو حکم دیا تو اس نے آواز دی: اللہ کے رسول! حج کیوں کر ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا تو اس نے پکار کر کہا: \"حج عرفات میں وقوف ہے ۱؎ جو شخص مزدلفہ کی رات کو فجر سے پہلے(عرفات میں) آ جائے تو اس کا حج پورا ہو گیا، منی کے دن تین ہیں (گیارہ، بارہ اور تیرہ ذی الحجہ)، جو شخص دو ہی دن کے بعد چلا جائے تو اس پر کوئی گناہ نہیں اور جو تیسرے دن بھی رکا رہے اس پر کوئی گناہ نہیں\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو اپنے پیچھے بٹھا لیا وہ یہی پکارتا جاتا تھا۔ ابوداؤد کہتے ہیں: اور اسی طرح مہران نے سفیان سے «الحج الحج» دو بار نقل کیا ہے اور یحیی بن سعید قطان نے سفیان سے «الحج» ایک ہی بار نقل کیا ہے۔\n§وضاحت\n۱؎ : یعنی اصل حج عرفات میں وقوف ہے کیونکہ اس کے فوت ہو جانے سے حج فوت ہو جاتا ہے۔","صحیح",{"u2":"جناب عبدالرحمٰن بن یعمر الدیلی رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا جب کہ آپ میدان عرفات میں تھے۔ اسی دوران میں نجد کی طرف کے کچھ لوگ آئے اور انہوں نے ایک شخص کو کہا تو اس نے پکار کر کہا: اے ا اللہ کے رسول! حج کیسے ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے (بھی) ایک شخص کو حکم دیا اور اس نے پکار کر کہا: ” حج، حج عرفات کا دن ہے۔ جو شخص مزدلفہ کی رات میں فجر کی نماز سے پہلے پہلے یہاں آ گیا اس کا حج پورا ہو گیا۔ منیٰ کے دن تین ہیں۔ جو شخص دو دن بعد جلدی سے واپس ہو جائے اس پر کوئی گناہ نہیں اور جو تاخیر کرے (تیسرا دن بھی وقوف کرے) تو اس پر بھی کوئی گناہ نہیں۔ “ پھر آپ نے اپنے پیچھے ایک شخص کو سوار کرا لیا جو اس بات کی منادی کرنے لگا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ مہران نے سفیان سے ایسے ہی روایت کیا ہے «الحج الحج» (یعنی) دو بار۔ جبکہ یحییٰ بن سعید قطان نے سفیان سے یہ لفظ «الحج» ایک بار بیان کیا ہے۔","f2":"وقوف عرفات حج کا رکن ہے۔خواہ معمولی وت کے لیے ہی کیوں نہ ہو۔ اور اس وقت نو ذوالحجہ کوزوال کے وقت سےلے کر اگلے دن صبح صادق سے پہلے تک ہے۔ جس سے یہ وقوف فوت ہو جائے اس کا حج نہیں۔"}],[1950,"عروہ بن مضرس طائی رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا آپ موقف یعنی مزدلفہ میں تھے، میں نے عرض کیا: میں طی کے پہاڑوں سے آ رہا ہوں، میں نے اپنی اونٹنی کو تھکا مارا، اور خود کو بھی تھکا دیا، اللہ کی قسم راستے میں کوئی ایسا ٹیکرہ نہیں آیا جس پر میں ٹھہرا نہ ہوں، تو میرا حج درست ہوا یا نہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو ہمارے ساتھ اس نماز کو پا لے اور اس سے پہلے رات یا دن کو عرفات میں ٹھہر چکا ہو تو اس کا حج پورا ۱؎ ہو گیا، اس نے اپنا میل کچیل دور کر لیا ۲؎\"۔\n§وضاحت\n۱؎ : حدیث سے معلوم ہوا کہ عرفات میں ٹھہرنا ضروری ہے اور اس کا وقت (۹) ذی الحجہ کو سورج ڈھلنے سے لے کر دسویں تاریخ کے طلوع فجر تک ہے، ان دونوں وقتوں کے بیچ اگر تھوڑی دیر کے لئے بھی عرفات میں وقوف مل جائے تو اس کا حج ادا ہو جائے گا۔ ۲؎ : نسائی کی ایک روایت میں ہے «فقد قضى تفثه وتم حجه» ، یعنی حالت احرام میں پراگندہ رہنے کی مدت اس نے پوری کر لی، اب وہ اپنا سارا میل کچیل جو چھوڑ رکھا تھا دور کر سکتا ہے۔","صحیح",{"u2":"سیدنا عروہ بن مضرس طائی رضی اللہ عنہ بیان کرتے ہیں کہ میں مزدلفہ میں وقوف کے وقت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: اے ا اللہ کے رسول! میں قبیلہ طے کے دو پہاڑوں سے آیا ہوں۔ میں نے اپنی سواری کو ہلکان کیا ہے اور اپنے آپ کو بہت تھکایا ہے۔ قسم ا اللہ کی! میں نے کوئی ٹیلہ (یا پہاڑ) نہیں چھوڑا مگر اس پر وقوف کیا ہے۔ تو کیا میرا حج ہو گیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس نے ہمارے ساتھ یہ نماز (فجر) پا لی اور اس سے پہلے وہ رات یا دن میں عرفات میں حاضر ہو چکا ہے تو اس کا حج پورا ہو گیا اور اس نے اپنا میل کچیل دور کر لیا (اس نے مناسک حج پورے کر لیے۔ اب مابعد کے دیگر اعمال حج پورے کر کے اپنا احرام کھول دے) “۔"}],[1951,"عبدالرحمٰن بن معاذ سے روایت ہے وہ رسول صلی اللہ علیہ وسلم کے ایک صحابی سے روایت کرتے ہیں، وہ کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے منی میں لوگوں سے خطاب کیا، اور انہیں ان کے ٹھکانوں میں اتارا، آپ نے فرمایا: \"مہاجرین یہاں اتریں اور قبلہ کے دائیں جانب اشارہ کیا، اور انصار یہاں اتریں، اور قبلے کے بائیں جانب اشارہ کیا، پھر باقی لوگ ان کے اردگرد اتریں\"۔","صحیح",{"u2":"عبدالرحمٰن بن معاذ رضی اللہ عنہ ایک صحابی سے بیان کرتے ہیں انہوں نے کہا: نبی کریم صلی اللہ علیہ وسلم نے منٰی میں لوگوں کو خطبہ دیا اور انہیں اپنے اپنے مقامات پر اترنے کا ارشاد فرمایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” مہاجرین یہاں پڑاؤ کریں۔ “ اور قبلہ کی جانب دائیں طرف اشارہ فرمایا۔ ” اور انصار یہاں پڑاؤ کریں۔ “ اور قبلہ کی بائیں طرف اشارہ فرمایا۔ ” اور دیگر لوگ ان کے ارد گرد اتریں۔ “","f2":"یہ مقامات منی کی مسجد خیف سے قبلہ کی طرف دائیں اوربائیں مراد ہیں۔جیسے کہ آئندہ حدیث نمبر 1957میں آرہا ہے۔"}],[1952,"بنی بکر کے دو آدمی کہتے ہیں ہم نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ ایام تشریق کے بیچ والے دن (بارہویں ذی الحجہ کو) خطبہ دے رہے تھے اور ہم آپ کی اونٹنی کے پاس تھے، یہ وہی خطبہ تھا جسے رسول اللہ صلی اللہ علیہ وسلم نے منی میں دیا۔","صحیح",{"u2":"ابن ابی نجیح اپنے والد سے، وہ بنو بکر کے دو آدمیوں سے روایت کرتے ہیں انہوں نے بیان کیا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو ایام تشریق کے درمیانی دن میں خطبہ دیتے ہوئے دیکھا۔ ہم آپ صلی اللہ علیہ وسلم کی سواری کے قریب ہی تھے اور یہ رسول اللہ صلی اللہ علیہ وسلم کا وہ خطبہ تھا جو آپ صلی اللہ علیہ وسلم نے منٰی میں ارشاد فرمایا۔"}],[1953,"ربیعہ بن عبدالرحمٰن بن حصین کہتے ہیں مجھ سے میری دادی سراء بنت نبہان رضی اللہ عنہا نے بیان کیا اور وہ جاہلیت میں گھر کی مالکہ تھیں (جس میں اصنام ہوتے تھے)، وہ کہتی ہیں: ہمیں رسول اللہ صلی اللہ علیہ وسلم نے یوم الروس ۱؎ (ایام تشریق کے دوسرے دن بارہویں ذی الحجہ) کو خطاب کیا اور پوچھا: \"یہ کون سا دن ہے؟\"، ہم نے عرض کیا: اللہ اور اس کے رسول زیادہ جانتے ہیں، آپ نے فرمایا: \"کیا یہ ایام تشریق کا بیچ والا دن نہیں ہے\"۔ امام ابوداؤد رحمہ اللہ کہتے ہیں: ابوحرہ رقاشی کے چچا سے بھی اسی طرح روایت ہے کہ آپ صلی اللہ علیہ وسلم نے ایام تشریق کے بیچ والے دن خطبہ دیا۔\n§وضاحت\n۱؎ : بارہویں ذی الحجہ کو یوم الرؤوس کہا جاتا تھا کیونکہ لوگ اپنی قربانی کے جانوروں کے سر اسی دن کھاتے تھے۔","ضعیف",{"u2":"ربیعہ بن عبدالرحمٰن بن حصین اپنی دادی سراء بنت نبہان رضی اللہ عنہا ا سے بیان کرتے ہیں یہ خاتون قبل از اسلام ایک گھر کی نگران تھیں (جس میں بت ہوا کرتے تھے) وہ بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رؤوس والے دن ہمیں خطبہ دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ کون سا دن ہے؟ “ ہم نے کہا: اللہ اور اس کے رسول بہتر جانتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا یہ ایام تشریق کا درمیانی دن نہیں ہے؟ “ امام ابوداؤد رضی اللہ عنہ نے کہا: ابوحرہ رقاشی کے چچا نے بھی ایسے ہی روایت کیا ہے کہ آپ نے ایام تشریق کے درمیانی دن میں خطبہ دیا۔","f2":"(1) عید الاضحی ٰ (دس ذوالحجہ) کے بعد تین دنوں کو ایام تشریق کہتے ہیں۔ تشریق کے معنی ہیں، گوشت کے ٹکڑے کر کے دھوپ میں خشک کرنا۔ پہلا دن یوم القراء (نمعنی قرار) اور دوسرا دن یوم لرؤوس کہلاتا ہے۔ یعنی سریوں والا دن کہ وہ قربانیوں کی سریاں پکا کر کھاتے تھے۔ اور تیسرے دن کو یو م النفر (ورانگی کا دن) کہتے ہیں۔ (2) اس موقع پر امام حج کے لیے خطبہ دینا مستحب ہے جیسے کہ رسو ل اللہ صلی اللہ علیہ وسلم سے ثابت ہے۔ حسب موقع اہم اہم مسائل کی تذکیر کی جانی چاہیے۔"}],[1954,"ہرماس بن زیاد باہلی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا، آپ اپنی اونٹنی عضباء پر عید الاضحی کے دن منی میں لوگوں کو خطبہ دے رہے تھے۔","حسن",{"u2":"سیدنا ہرماس بن زیاد باہلی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم منٰی میں قربانی والے دن اپنی عضباء اونٹنی پر لوگوں کو خطبہ دے رہے تھے۔"}],[1955,"سلیم بن عامر کلاعی کہتے ہیں کہ میں نے ابوامامہ رضی اللہ عنہ کو کہتے سنا کہ میں نے منی میں یوم النحر کو رسول اللہ صلی اللہ علیہ وسلم کا خطبہ سنا ۱؎۔\n§وضاحت\n۱؎ : ہرماس بن زیاد اور ابو امامہ رضی اللہ عنہما وغیرہ کی روایتیں اس بات پر دلالت کرتی ہیں کہ یوم النحر کو خطبہ مشروع ہے، کچھ لوگوں کا کہنا ہے کہ یوم النحر کو خطبہ نہیں، اور یہ احادیث عام موعظت و نصیحت کے قبیل سے ہیں نہ کہ یہ خطبہ ہے جو حج کے شعائر میں سے ہے، ان روایات سے ان کے اس قول کی تردید ہوتی ہے کیونکہ ان احادیث کے رواۃ نے اسے خطبہ کا نام دیا ہے جیسے عرفات کے خطبہ کو خطبہ کہا گیا ہے۔","صحیح",{"u2":"سیدنا ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے منٰی میں قربانی والے دن رسول اللہ صلی اللہ علیہ وسلم کا خطبہ سنا۔"}],[1956,"رافع بن عمرو المزنی کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منی میں ایک سفید خچر پر سوار لوگوں کو خطبہ دیتے سنا جس وقت آفتاب بلند ہو چکا تھا اور علی رضی اللہ عنہ آپ کی طرف سے اسے لوگوں کو پہنچا ۱؎ رہے تھے اور دور والوں کو بتا رہے تھے، کچھ لوگ بیٹھے ہوئے تھے اور کچھ کھڑے تھے۔\n§وضاحت\n۱؎ : رسول اللہ صلی اللہ علیہ وسلم سے سن کر وہی کلمات بلند آواز سے دہرا رہے تھے تا کہ جو لوگ آپ صلی اللہ علیہ وسلم سے دور ہیں وہ بھی اسے سن لیں۔","صحیح",{"u2":"جناب رافع بن عمرو مزنی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم منٰی میں اپنے سفید خچر پر لوگوں کو خطبہ دے رہے تھے جبکہ دن اونچا آ چکا تھا اور سیدنا علی رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کی بات آگے پہنچا رہے تھے۔ لوگ کچھ بیٹھے تھے اور کچھ کھڑے تھے۔","f2":"(1) امام حج کا اس دن خطبہ دینا مستحب ہے۔ (2)آپ صلی اللہ علیہ وسلم نے ایک موقع پر اپنی انٹنی پر سے خطبہ دیا اور دوسرے موقع پر سفید خچر پر سے، اس میں تعارض نہیں ہے۔"}],[1957,"عبدالرحمٰن بن معاذ تمیمی رضی اللہ عنہ کہتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا، ہم منی میں تھے تو ہمارے کان کھول دئیے گئے آپ جو بھی فرماتے تھے ہم اسے سن لیتے تھے، ہم اپنے ٹھکانوں میں تھے، آپ صلی اللہ علیہ وسلم نے لوگوں کو ارکان حج سکھانا شروع کئے یہاں تک کہ جب آپ جمرات تک پہنچے تو آپ صلی اللہ علیہ وسلم نے اپنی شہادت کی دونوں انگلیوں کو رکھ کر اتنی چھوٹی چھوٹی کنکریاں ماریں جو انگلیوں کے درمیان آ سکتی تھیں پھر آپ صلی اللہ علیہ وسلم نے مہاجرین کو حکم دیا کہ وہ مسجد کے اگلے حصہ میں اتریں اور انصار کو حکم دیا کہ وہ لوگ مسجد کے پیچھے اتریں اس کے بعد سب لوگ اترے۔","صحیح",{"u2":"سیدنا عبدالرحمٰن بن معاذ تیمی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ دیا جبکہ ہم منیٰ میں تھے۔ پس (ا اللہ تبارک و تعالیٰ نے) ہمارے کان کھول دیے، ہم اپنے اپنے پڑاؤ پر تھے اور وہ سب کچھ سن رہے تھے جو آپ صلی اللہ علیہ وسلم فر رہے تھے۔ آپ ہمیں اعمال حج کی تعلیم فر رہے تھے حتیٰ کہ جمرات تک پہنچ گئے، تو آپ نے اپنی شہادت کی انگلیاں (اپنے کانوں میں) رکھیں اور فرمایا ” چھوٹی چھوٹی کنکریاں مارو “۔ آپ نے مہاجرین کو حکم دیا تو وہ مسجد (خیف) کے آگے کی طرف اترے۔ اور انصار کو حکم دیا تو وہ مسجد سے پیچھے کی طرف اترے۔ پھر دوسرے لوگ ان کے بعد اترے۔","f2":"(1) یہ نبی صلی اللہ علیہ وسلم کا معجزہ تھا کہ دور کے لوگوں نے اپنی اپنی جگہ پر آپ کا خطبہ سن لیا(2) شہادت کی انگلیاں رکھیں اس سے مراد یا تو یہ ہےکہ آپ نے آپنے کانوں میں رکھیں او ربلند آواز سے فرمایا۔ ابوداؤد کے ایک نسخہ سے اس معنی کی تائیدہوتی ہے اس میں[فی اذنیه)‎] کا اضافہ ہے۔ (نیل اوطار) یا ہو سکتا ہے کہ آپ نے انگوٹھوں کے درمیان اپنی انگلیاں رکھ کر اشار ہ فرمایا ہو کہ اس کی چھوٹی چھوٹی کنکریاں مارو۔ (بذل المجھول)"}],[1958,"حریز یا ابوحریز بیان کرتے ہیں کہ انہوں نے عبدالرحمٰن بن فروخ کو ابن عمر رضی اللہ عنہما سے پوچھتے ہوئے سنا، وہ کہہ رہے تھے کہ ہم لوگوں کا مال بیچتے ہیں تو کیا ہم میں سے کوئی منی کی راتوں میں مکہ میں جا کر مال کے پاس رہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم تو رات اور دن دونوں منی میں رہا کرتے تھے ۱؎۔\n§وضاحت\n۱؎ : اس لئے مکہ میں رات گزارنی خلاف سنت اور ناجائز ہے، بعض علماء کے یہاں صرف شدید ضرورت کے وقت اس کی اجازت ہے۔","ضعیف",{"u2":"عبدالرحمٰن بن فروخ نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا کہ ہم لوگوں کے ساتھ خرید و فروخت کرتے ہیں، تو ہم میں سے کوئی مکہ بھی آ جاتا ہے اور اپنے مال کے ساتھ رات گزارتا ہے تو انہوں نے جواب دیا کہ رسول اللہ صلی اللہ علیہ وسلم نے تو راتیں منٰی میں گزاری تھیں اور دن بھی۔"}],[1959,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عباس رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے حاجیوں کو پانی پلانے کی وجہ سے منی کی راتوں کو مکہ میں گزارنے کی اجازت مانگی تو آپ صلی اللہ علیہ وسلم نے انہیں اجازت دے دی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا عباس رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اجازت طلب کی تھی کہ لوگوں کو پانی پلانے کی غرض سے منٰی کی راتیں مکہ میں گزار لیں تو آپ صلی اللہ علیہ وسلم نے ان کو اجازت دے دی تھی۔","f2":"کوئی معقول شرعی عذر ہوتو معنی سےباہر رہ سکتا ہے، مثلاً حجاج کی خدمت، جانوروں کو چرانا یا مریض اور اس کی تیمارداری وغیرہ۔ اس قسم کے اعذار کے علاوہ منی ٰ میں رات گزارنا ضروری ہے۔"}],[1960,"عبدالرحمٰن بن یزید کہتے ہیں کہ عثمان رضی اللہ عنہ نے منی میں چار رکعتیں پڑھیں تو عبداللہ بن مسعود رضی اللہ عنہ نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم، ابوبکر اور عمر رضی اللہ عنہما کے ساتھ دو ہی رکعتیں پڑھیں (اور حفص کی روایت میں اتنا مزید ہے کہ) عثمان رضی اللہ عنہ کے ساتھ ان کی خلافت کے شروع میں، پھر وہ پوری پڑھنے لگے، (ایک روایت میں ابومعاویہ سے یہ ہے کہ) پھر تمہاری رائیں مختلف ہو گئیں، میری تو خواہش ہے کہ میرے لیے چار رکعتوں کے بجائے دو مقبول رکعتیں ہی ہوں۔ اعمش کہتے ہیں: مجھ سے معاویہ بن قرہ نے اپنے شیوخ کے واسطہ سے بیان کیا ہے کہ عبداللہ بن مسعود رضی اللہ عنہ نے چار رکعتیں پڑھیں، تو ان سے کہا گیا: آپ نے عثمان پر اعتراض کیا، پھر خود ہی چار پڑھنے لگے؟ تو انہوں نے کہا: اختلاف برا ہے۔","صحیح",{"u2":"جناب عبدالرحمٰن بن یزید نے بیان کیا کہ سیدنا عثمان رضی اللہ عنہ نے منیٰ میں چار رکعتیں پڑھیں تو عبداللہ بن مسعود رضی اللہ عنہ نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ ابوبکر رضی اللہ عنہ کے ساتھ اور عمر رضی اللہ عنہ کے ساتھ دو دو رکعتیں (قصر) پڑھی ہیں۔ (مسدد نے) حفص بن غیاث سے مزید یہ بھی کہا: اور عثمان رضی اللہ عنہ کے ساتھ بھی، کہ وہ ابتدائی دور خلافت میں (قصر کرتے رہے) پھر آخر میں وہ پوری پڑھنے لگے تھے۔ (مسدد نے) یہاں سے ابومعاویہ سے یہ اضافہ کیا کہ (ابن مسعود رضی اللہ عنہ نے کہا) پھر تمہاری راہیں مختلف ہو گئیں اور مجھے دو رکعتیں جو (ا اللہ کے ہاں) قبول ہو جائیں چار رکعتوں سے بہتر معلوم ہوتی ہیں۔ اعمش نے کہا: مجھے معاویہ بن قرہ نے اپنے بزرگوں (اساتذہ) سے بیان کیا کہ عبداللہ بن مسعود رضی اللہ عنہ نے بھی چار رکعتیں پڑھیں تو ان سے کہا گیا کہ آپ عثمان رضی اللہ عنہ پر عیب لگاتے ہیں پھر بھی چار پڑھتے ہیں؟ کہنے لگے اختلاف کرنا برا کام ہے۔","f2":"اس روایت میں حضرت عثمان کا یہ عمل منقول ہے کہ انہوں نے اپنی خلافت میں (ابتدائی چھ سال کے بعد) منی ٰ میں قصر کی بجائے پوری چار رکعت پڑھنی شروع کر دی تھیں۔ اس کی مختلف وجوہات بیان کی گئی ہیں، لیکن اصل بات یہ ہے کہ انہوں نے محض جواز کی بنیاد پر پوری نماز پڑھی تھی، اسی لیے پہلے چھ سال تک وہ قصر ہی کرتے رہے تھے۔ اور اسی جواز ہی کی وجہ سے حضرت عبد اللہ بن مسعود نے بھی حضرت عثمان کی متابعت میں پوری نماز پڑھ لی، اور اس میں اختلاف کرنے کو پسند نہیں کیا۔ حالانکہ وہ خود بیان کر رہے ہیں کہ اس سے قبل وہ قصر کرتے رہے۔ اگر پوری نماز پڑھنے کا جواز نہ ہوتا تو یقیناً اس سے اختلاف کرتے اور اختلاف کو برا کام نہ کہتے کیونکہ جس چیز کا جواز ہی نہ ہو اس سے تواختلاف کرنا ضروری ہے اس اختلاف کو تو کسی صورت میں برا کام نہیں کہا جا سکتا۔ تاہم مسافر کے لیے قصر اور اتمام دونوں باتوں کے جائز سمجھنے کے باوجود وہ ڈر تے تھے کہ حضرت عثمان کی متابعت میں انہوں نے جو چار رکعتیں پڑھی ہیں کہیں وہ عند اللہ نامقبول نہ ہوں اس لیے اللہ کی طرف سے اگر دورکعتیں بھی مقبول ہو جائیں تو بڑی بات ہے بے شک چاروں رکعتیں مقبول نہ ہوں۔ ان کی یہ بات خشیت الہی اور جذبہ اتباع سنت کی مظہر ہے جن سے صحابہ کرام متصف تھے۔"}],[1961,"زہری سے روایت ہے کہ عثمان رضی اللہ عنہ نے منی میں چار رکعتیں صرف اس لیے پڑھیں کہ انہوں نے حج کے بعد وہاں اقامت کی نیت کی تھی۔","ضعیف",{"u2":"امام زہری رضی اللہ عنہ سے مروی ہے کہ سیدنا عثمان نے منٰی میں چار رکعات اس لیے پڑھی تھیں کہ انہوں نے حج کے بعد وہیں اقامت کا عزم کر لیا تھا۔"}],[1962,"ابراہیم کہتے ہیں عثمان رضی اللہ عنہ نے چار رکعتیں پڑھیں اس لیے کہ انہوں نے منی کو وطن بنا لیا تھا۔","ضعیف",{"u2":"جناب ابراہیم نخعی رضی اللہ عنہ سے مروی ہے کہ سیدنا عثمان رضی اللہ عنہ کے چار رکعت پڑھنے کہ وجہ یہ تھی کہ انہوں نے اسے وطن بنا لیا تھا۔ (یہاں انہوں نے شادی کر لی تھی۔)"}],[1963,"زہری کہتے ہیں جب عثمان رضی اللہ عنہ نے طائف میں اپنی جائیداد بنائی اور وہاں قیام کرنے کا ارادہ کیا تو وہاں چار رکعتیں پڑھیں، وہ کہتے ہیں: پھر اس کے بعد ائمہ نے اسی کو اپنا لیا۔","ضعیف",{"u2":"امام زہری رضی اللہ عنہ سے منقول ہے کہ سیدنا عثمان رضی اللہ عنہ نے جب طائف میں اپنی جائیداد لے لی اور یہاں اقامت کا ارادہ کر لیا تو چار رکعتیں پڑھیں۔ ان کے بعد دیگر ائمہ (بنی امیہ) نے یہی عمل اختیار کر لیا۔"}],[1964,"زہری سے روایت ہے کہ عثمان بن عفان رضی اللہ عنہ نے منی میں نماز اس وجہ سے پوری پڑھی کہ اس سال بدوی لوگ بہت آئے تھے تو انہوں نے چار رکعتیں پڑھیں تاکہ ان لوگوں کو معلوم ہو کہ نماز (اصل میں) چار رکعت ہی ہے (نہ کہ دو، جو قصر کی صورت میں پڑھی جاتی ہے) ۔","حسن لغیرہ",{"u2":"امام زہری رضی اللہ عنہ سے روایت ہے کہ سیدنا عثمان رضی اللہ عنہ نے منٰی میں بدوی لوگوں کی وجہ سے پوری نماز پڑھی تھی کیونکہ وہ اس سال بہت کثیر تعداد میں آئے تھے تو انہوں نے لوگوں کو چار رکعتیں پڑھائیں تاکہ ان بدویوں کو معلوم رہے کہ نماز چار رکعات ہے۔","f2":"یہ چاروں آثار ضعیف ہے۔ اس لیے حضرت عثمان کےمنی ٰ میں پوری نماز پڑھنے کی وجہ صرف مسافر کے لیے قصر کی بجائے پوری نماز پڑھنے کا جواز ہے۔ اس کے علاوہ اور کوئی وجہ نہیں۔"}],[1965,"ابواسحاق کہتے ہیں کہ مجھ سے حارثہ بن وہب خزاعی نے بیان کیا اور ان کی والدہ عمر رضی اللہ عنہ کے نکاح میں تھیں تو ان سے عبیداللہ بن عمر کی ولادت ہوئی، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے پیچھے منی میں نماز پڑھی، اور لوگ بڑی تعداد میں تھے، تو آپ نے ہمیں حجۃ الوداع میں دو رکعتیں پڑھائیں ۱؎۔ ابوداؤد کہتے ہیں: حارثہ کا تعلق خزاعہ سے ہے اور ان کا گھر مکہ میں ہے۔\n§وضاحت\n۱؎ : محقق علماء کا قول یہ ہے کہ اہل مکہ بھی منی اور عرفات میں قصر کریں گے، یہ حج کے مسائل میں سے ہے، یہاں مسافر اور مقیم کے درمیان کوئی فرق نہیں۔","صحیح",{"u2":"سیدنا حارثہ بن وہب الخزاعی رضی اللہ عنہ کی ماں سیدنا عمر رضی اللہ عنہ کی زوجیت میں تھی اور ان سے ان کا بیٹا عبیدا اللہ بن عمر پیدا ہوا تھا۔ حارثہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں نماز پڑھی۔ لوگوں کی تعداد بہت زیادہ تھی تو آپ نے ہمیں حجتہ الوداع میں دو رکعتیں پڑھائیں۔ امام ابوداؤد رضی اللہ عنہ نے کہا: حارثہ قبیلہ خزاعہ کے فرد تھے اور ان کا گھر مکہ میں تھا۔","f2":"اس سےمعلوم ہوا کہ منی ٰ میں قصر کرنامناسک حج کا حصہ ہے اس لیے دیگر مسافرین کی طرح اہل مکہ بھی منیٰ میں نماز قصر کر کے ہی پڑھیں گے۔ البتہ فریضہ حج کی ادائیگی کے بعد اہل مکہ کامنی ٰ میں قصر کرنا جائز نہ ہوگا۔"}],[1966,"والدہ سلیمان بن عمرو بن احوص رضی اللہ عنہما کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سوار ہو کر بطن وادی سے جمرہ پر رمی کرتے دیکھا، آپ صلی اللہ علیہ وسلم ہر کنکری پر تکبیر کہتے تھے، ایک شخص آپ کے پیچھے تھا، وہ آپ پر آڑ کر رہا تھا، میں نے پوچھا: یہ کون ہے؟ تو لوگوں نے کہا: فضل بن عباس رضی اللہ عنہما ہیں، اور لوگوں کی بھیڑ ہو گئی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"لوگو! تم میں سے کوئی کسی کو قتل نہ کرے (یعنی بھیڑ کی وجہ سے ایک دوسرے کو کچل نہ ڈالے) اور جب تم رمی کرو تو ایسی چھوٹی کنکریوں سے مارو جنہیں تم دونوں انگلیوں کے بیچ رکھ سکو\"۔","حسن",{"u2":"سلیمان بن عمرو بن الاحوص کی والدہ بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو وادی کے درمیان سے جمرہ کو کنکریاں مارتے دیکھا جب کہ آپ سواری پر تھے۔ آپ ہر کنکری کے ساتھ «الله اكبر» کہتے تھے۔ ایک شخص آپ کے پیچھے سے آپ کو چھپائے ہوئے تھا۔ میں نے اس شخص کے متعلق پوچھا تو کہا: فضل بن عباس رضی اللہ عنہ ہیں۔ لوگوں نے بہت بھیڑ کر دی تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” لوگو! ایک دوسرے کو قتل مت کرو۔ اور جب تم جمرے کو کنکریاں مارو تو چھوٹی چھوٹی مارو۔ “","f2":"(1) الجمرۃ کے لغت میں کئی معنی ہیں: دہکتا ہوا کوئلہ ایسا قبیلہ جوکسی اور سے ملا نہ ہو اور تین سو یا ایک ہزار سور ماؤں کی جماعت کو جمرہ کہتے ہیں۔ ایک قبیلے کا دوسروں کے مقابلہ میں جمع ہو جانا بھی جمرہ کہلاتا ہے۔ اور اسی مناسبت سےان جگہوں کو جمرہ یا جمرات کہتے ہیں جہاں حاجی کنکریاں مارتے ہیں۔ یہ مقام اصل میں چھوٹی کنکریاں کے ڈھیرسے تھے۔ (چھوٹے چھوٹے ٹیلے تھے) جو مکہ کی جانب میں ہے اسے جمرہ کبریٰ اور جمرۂ عقبہ کہتے ہیں۔ جومنی ٰ کی طرف ہے اسے جمرۂ صغریٰ اور ان کے درمیان والے کو جمرۂ وسطی کہا جاتا ہے۔ (2)[حصى الخذف]کی توضیح کے لیے دیکھیے حدیث: 1905فائدہ:35)"}],[1967,"والدہ سلیمان بن عمرو بن احوص رضی اللہ عنہما کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو جمرہ عقبہ کے پاس سوار دیکھا اور میں نے دیکھا کہ آپ کی انگلیوں میں کنکریاں تھیں، تو آپ نے بھی رمی کی اور لوگوں نے بھی رمی کی ۱؎۔\n§وضاحت\n۱؎ : ان احادیث سے معلوم ہوا کہ جمرات کی رمی سواری پر درست ہے، لیکن موجودہ حالات میں منتظمین حج کے احکام کی روشنی میں مناسک حج، قربانی، اور رمی جمرات وغیرہ کے کام انجام دینا چاہئے۔","صحیح",{"u2":"سلیمان بن عمرو بن الاحوص کی والدہ کا بیان ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو جمرہ عقبہ کے پاس دیکھا۔ آپ صلی اللہ علیہ وسلم سواری پر تھے۔ میں نے آپ صلی اللہ علیہ وسلم کی انگلیوں میں کنکریاں دیکھیں۔ آپ صلی اللہ علیہ وسلم نے وہ ماریں تو پھر اور لوگوں نے بھی ماریں۔","f2":"لفظ حجرکا ترجمہ کنکریاں دوسری روایات کی بنا پر صحیح ہے نیز اسی روایات میں [بين اصابعه] یعنی انگلیوں کے بیچ میں کا لفظ بھی موجود ہے۔ ورنہ معروف معنوں میں پتھر مارنا تو جائز نہیں ہے۔"}],[1968,"اس سند سے بھی یزید بن ابی زیاد سے اسی طریق سے اسی حدیث کے ہم مثل مروی ہے اس میں «ولم يقم عندها» \"اور اس کے پاس نہیں ٹھہرے\" کا جملہ زائد ہے۔","صحیح",{"u2":"یزید بن ابی زیاد نے اپنی سند سے اسی کے مثل روایت کیا اور اضافہ کیا کہ آپ صلی اللہ علیہ وسلم جمرہ کے پاس رکے نہیں۔"}],[1969,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ وہ یوم النحر کے بعد تین دنوں میں جمرات کی رمی کے لیے پیدل چل کر آتے تھے اور پیدل ہی واپس جاتے اور وہ بتاتے تھے کہ خود نبی اکرم صلی اللہ علیہ وسلم ایسا ہی کرتے تھے ۱؎۔\n§وضاحت\n۱؎ : اس سے معلوم ہوا کہ رمی جمرات کے لئے پیدل چل کر آنا افضل ہے۔","صحیح",{"u2":"نافع رضی اللہ عنہ نے سیدنا ابن عمر رضی اللہ عنہ کے متعلق بتایا کہ وہ قربانی کے دن (یعنی دس ذوالحجہ) کے بعد تین دنوں میں جمرات کے پاس پیدل ہی آتے جاتے تھے اور بیان کرتے تھے کہ نبی کریم صلی اللہ علیہ وسلم ایسے ہی کیا کرتے تھے۔"}],[1970,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ اپنی سواری پر یوم النحر کو رمی کر رہے تھے، آپ صلی اللہ علیہ وسلم فرما رہے تھے: \"تم لوگ اپنے حج کے ارکان سیکھ لو کیونکہ مجھے نہیں معلوم کہ میں اپنے اس حج کے بعد کوئی حج کر سکوں گا یا نہیں\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم قربانی والے دن اپنی سواری پر سے کنکریاں مار رہے تھے اور فرماتے تھے ” مجھ سے اپنے اعمال حج سیکھ لو، میں نہیں جانتا، شاید میں اپنے اس حج کے بعد حج نہ کر سکوں۔ “"}],[1971,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنی سواری پر بیٹھ کر یوم النحر کو چاشت کے وقت رمی کرتے دیکھا پھر اس کے بعد جو رمی کی (یعنی گیارہ، بارہ اور تیرہ کو) تو وہ زوال کے بعد کی۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ صلی اللہ علیہ وسلم قربانی والے دن چاشت کے وقت اپنی سواری پر سے رمی کر رہے تھے۔ مگر اس کے بعد کے دنوں میں سورج ڈھلنے کے بعد کی۔"}],[1972,"وبرہ کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما سے پوچھا کہ کنکریاں کب ماروں؟ آپ نے کہا: جب تمہارا امام کنکریاں مارے تو تم بھی مارو، میں نے پھر یہی سوال کیا، انہوں نے کہا: ہم سورج ڈھلنے کا انتظار کرتے تھے تو جب سورج ڈھل جاتا تو ہم کنکریاں مارتے۔","صحیح",{"u2":"وبرہ(بن عبدالرحمٰن سلمی) کہتے ہیں، میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا کہ میں کس وقت جمرات کو کنکریاں ماروں؟ انہوں نے کہا: جب تمہارا امام مارے تم بھی مار لو۔ میں نے اپنا سوال دہرایا تو بولے ہم سورج ڈھلنے کا انتظار کیا کرتے تھے۔ جب سورج ڈھل جاتا تو رمی کرتے تھے(قربانی والے دن کے بعد کے ایام میں)"}],[1973,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (یوم النحر) کے آخری حصہ میں جس وقت ظہر پڑھ لی طواف افاضہ کیا، پھر منی لوٹے اور تشریق کے دنوں تک وہاں ٹھہرے رہے، جب سورج ڈھل جاتا تو ہر جمرے کو سات سات کنکریاں مارتے، ہر کنکری کے ساتھ تکبیر کہتے، اور پہلے اور دوسرے جمرے پر دیر تک ٹھہرتے، روتے، گڑگڑاتے اور دعا کرتے اور تیسرے جمرے کو کنکریاں مار کر اس کے پاس نہیں ٹھہرتے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (دس تاریخ کو قربانی والے دن) ظہر پڑھ لینے کے بعد دن کے آخری حصے میں طواف افاضہ کیا۔ پھر آپ منیٰ لوٹ آئے۔ اور ایام تشریق کی راتیں یہیں ٹھہرے رہے۔ سورج ڈھلنے کے بعد جمرات کو کنکریاں مارتے تھے۔ ہر جمرے کو سات کنکریاں مارتے اور ہر کنکری کے ساتھ «الله اكبر» کہتے۔ پہلے اور دوسرے جمرے کے پاس کافی لمبی دیر رکتے اور اپنی عاجزی اور تضرع کا اظہار کرتے (دعائیں کرتے) پھر تیسرے جمرے کو کنکریاں مارتے مگر اس کے پاس نہیں رکتے تھے۔","f2":"(1)دسویں تاریخ (یوم النحر) کو سورج نکلنے کے بعد ایک جمرۂ عقبہ کو کنکریاں ماری جاتی ہیں۔ اور باقی دنوں میں تینوں جمرات کو زوال کے بعد۔ (2) پہلے اور دوسرے جمرے کو رمی کرنے کے بعد ہاتھ اٹھاکر لمبی دعا سنت ہےتیسرے کے پاس نہیں(3)اس حدیث میں [حين صلى الظهر]ظہرپڑھ لینے کے بعد کے الفاظ منکر ہیں (شیخ البانی ‎)۔"}],[1974,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جب وہ جمرہ کبری (جمرہ عقبہ) کے پاس آئے تو بیت اللہ کو اپنے بائیں جانب اور منی کو دائیں جانب کیا اور جمرے کو سات کنکریاں ماریں، اور کہا: اسی طرح اس ذات نے بھی کنکریاں ماری تھیں جس پر سورۃ البقرہ نازل کی گئی۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ جب آپ صلی اللہ علیہ وسلم جمرہ کبریٰ (جمرہ عقبہ) کے پاس پہنچے تو آپ صلی اللہ علیہ وسلم نے بیت اللہ کو اپنے بائیں جانب اور منٰی کو دائیں جانب کیا اور پھر جمرے کو سات کنکریاں ماریں۔ سیدنا ابن مسعود رضی اللہ عنہ نے کہا: اور اس طرح سے رمی کی اس ذات نے جس پر سورۃ البقرہ نازل کی گئی تھی۔","f2":"اور یہ وہی منظر ہے جس کا ذکر دیگر احادیث میں آیا ہے کہ نبی صلی اللہ علیہ وسلم نے وادی کے دامن میں سے کنکریاں ماریں(صحیح البخاری الحج حدیث:1750)"}],[1975,"عاصم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اونٹ کے چرواہوں کو (منی میں) رات نہ گزارنے کی رخصت دی اور یہ کہ وہ یوم النحر کو رمی کریں، پھر اس کے بعد والے دن یعنی گیارہویں کو گیارہویں اور بارہویں دونوں دنوں کی رمی کریں، اور پھر روانگی کے دن(تیرہویں کو) رمی کریں گے۔","صحیح",{"u2":"ابوالبداح بن عاصم رضی اللہ عنہ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اونٹوں کے چرواہوں کو منٰی میں راتیں گزارنے سے رخصت دی تھی (کہ) یہ لوگ قربانی والے دن رمی کریں، پھر اگلے دن (گیارھویں تاریخ کو) اس کے بعد اگلا دن چھوڑ کر روانگی والے دن دو دن کی رمی کریں۔"}],[1976,"عاصم بن عدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے چرواہوں کو رخصت دی کہ ایک دن رمی کریں اور ایک دن ناغہ کریں۔","صحیح",{"u2":"ابوالبداح بن عدی اپنے والد سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے چرواہوں کو رخصت دی تھی کہ ایک دن رمی کریں اور ایک دن چھوڑ دیں۔","f2":"ابو البداح کےوالد کانام عاصم اور دادا کا نام عدی ہے۔ اس سند میں اس کو دادا کی طرف منسوب کیا گیا ہے۔"}],[1977,"ابومجلز کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما سے رمی جمرات کا حال دریافت کیا تو انہوں نے کہا: مجھے نہیں معلوم کہ رسول اللہ صلی اللہ علیہ وسلم نے چھ کنکریاں ماریں یا سات ۱؎۔\n§وضاحت\n۱؎ : عبداللہ بن عباس رضی اللہ عنہما کو معلوم نہ ہو سکا تھا ، دوسرے صحابہ کرام رضی اللہ عنہم کی روایات سے ہر جمرے کو س ات کنکریاں مارنا ثابت ہے۔","صحیح",{"u2":"ابومجلز بیان کرتے ہیں کہ میں نے سیدنا ابن عباس رضی اللہ عنہ سے رمی جمار کے بارے میں پوچھا تھا تو انہوں نے کہا: مجھے معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چھ کنکریاں ماری تھیں یا سات۔","f2":"دیگر اصحاب کرام جابر بن عبد اللہ ابن عمر اور عبداللہ بن مسعود کی صحیح احادیث میں بغیر شک کے سات کنکریاں کا ذکر ہے لہٰذا اسی پر عمل ہو گا۔"}],[1978,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے جب کوئی جمرہ عقبہ کی رمی کر لے تو اس کے لیے سوائے عورتوں کے ہر چیز حلال ہے\" ۱؎۔ ابوداؤد کہتے ہیں: یہ حدیث ضعیف ہے، حجاج نے نہ تو زہری کو دیکھا ہے اور نہ ہی ان سے سنا ہے ۲؎۔\n§وضاحت\n۱؎ : بیویوں سے صحبت یا بوس وکنار اس وقت جائز ہو گا جب حاجی طواف زیارت سے فارغ ہو جائے۔ ۲؎ : مسند احمد کی سند میں زہری کی جگہ ابوبکر بن محمد بن عمرو بن حزم ہیں حجاج بن أرطاۃ کا ان سے سماع ثابت ہے، نیز حدیث کے دیگر شواہد بھی ہیں۔","صحیح",{"u2":"سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی (دسویں تاریخ کو) جمرہ عقبہ کی رمی کر لے تو اس کے لیے بیویوں کے سوا ہر شے حلال ہو گئی۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: یہ حدیث ضعیف ہے۔ حجاج (حجاج بن ارطاۃ) نے زہری کو نہ دیکھا ہے اور نہ اس سے کچھ سنا ہے۔","f2":"اس حدیث کی صحت وضعف میں اگرچہ اختلاف ہےتاہم دیگر احادیث سے مسئلہ اسی طرح ثابت ہے کہ دسویں تاریخ کو زمی کے بعد حاجی کے لیے بیوی کے علاوہ دیگر ممنوعات حلال ہو جاتی ہیں۔ اسے اصطلاحاً حل ناقص یا حل اصغرکہتے ہیں طواف افاضہ کے بعد بیوی سے بھی مباشرت (ہم بستری) ہو سکتی ہےاوراسےحل کامل یا حل اکبر کہتے ہیں۔"}],[1979,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اللهم ارحم المحلقين» \"اے اللہ سر منڈوانے والوں پر رحم کر\"، لوگوں نے عرض کیا: اللہ کے رسول! اور کٹوانے والوں پر؟ آپ صلی اللہ علیہ وسلم نے فرمایا: «اللهم ارحم المحلقين»\"اے اللہ سر منڈوانے والوں پر رحم فرما\"، لوگوں نے عرض کیا: اللہ کے رسول! اور کٹوانے والوں پر؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"اور کٹوانے والوں پر بھی ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ بال منڈانا کتروانے سے زیادہ بہتر ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے اللہ! سر منڈوانے والوں پر رحم فر۔ “ صحابہ نے کہا: اے اللہ کے رسول! اور کتروانے والوں کے لیے بھی (دعا فرمائیں)۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے اللہ! سر منڈوانے والوں پر رحم فر ” صحابہ نے کہا: اے اللہ کے رسول! اور کتروانے والوں کے لیے بھی، تب آپ صلی اللہ علیہ وسلم نے فرمایا ” اور بال کتروانے والوں پر بھی (رحم فر)۔ “","f2":"حج کے موقع پر مردوں کے لیے استرے سے بال منڈوانے افضل ہے۔ عورتوں کے لیے یہ حکم نہیں ہے وہ معمولی سےبال کترلیں۔"}],[1980,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع میں اپنا سر منڈوایا۔","صحیح",{"u2":"سیدناابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجتہ الوداع میں اپنا سر منڈوایا تھا۔"}],[1981,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یوم النحر کو جمرہ عقبہ کی رمی کی، پھر آپ منی میں اپنی قیام گاہ لوٹ آئے، پھر قربانی کے جانور منگا کر انہیں ذبح کیا، اس کے بعد حلاق (سر مونڈنے والے کو بلایا)، اس نے آپ صلی اللہ علیہ وسلم کے سر کے داہنے حصے کو پکڑا، اور بال مونڈ دیئے ۱؎، پھر ایک ایک اور دو دو بال ان لوگوں میں تقسیم کئے جو آپ کے قریب تھے پھر بایاں جانب منڈوایا اور فرمایا: \"ابوطلحہ یہاں ہیں؟\" اور وہ سب بال ابوطلحہ کو دے دیئے۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ بال کٹوانے کے مقابلے میں منڈوانا زیادہ بہتر ہے، اور بال منڈوانے اور کتروانے میں یہ خیال رہے کہ اس کو داہنی جانب سے شروع کرے، مونڈنے والے کو بھی اس سنت کا خیال رکھنا چاہئے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی والے دن جمرہ عقبہ کو کنکریاں ماریں، پھر منیٰ میں اپنی منزل پر تشریف لائے، پھر اپنی قربانی طلب کی اور اسے ذبح کیا، پھر حجام کو بلوایا اور اس نے آپ کے سر کے دائیں جانب کو لیا اور اسے مونڈا۔ تو آپ نے اپنے پاس والوں کو ایک ایک دو دو بال تقسیم کر دیے۔ پھر اس نے بائیں جانب کو لیا اور اسے مونڈا تو آپ نے فرمایا ” ابوطلحہ یہاں ہے؟ “ چنانچہ وہ ابوطلحہ رضی اللہ عنہ کو دے دیے۔","f2":"(1) حجامت کے مسئلے میں بھی شرعی ہدایت یہی ہے کہ پہلے دائیں جانب سے بال کاٹے جائیں۔ (2) رسول اللہ صلی اللہ علیہ وسلم کےبال مبارک بال تھے جو صحابہ میں بطور تبرک متداول رہے۔ ان سے شفا بھی حاصل کی جاتی تھی۔ اور یہ صفت صرف اور صرف آپ صلی اللہ علیہ وسلم ہی کے بالوں کوحاصل رہی ہے۔ آج کل کئی مقامات پر سوئے مبارک بیان کیے جاتے ہیں چاہے کہ ان کی موثوق سند پیش کی جائے۔ مگر فی الواقع اس کا پیش کیا جانا ناممکن ہے۔ (3) حصول تبرک کوئی قیاس اور من پسند مسئلہ نہیں اس کا تعلق عقیدہ سے ہے۔ مبارک اشیا مبارک مقامات اور مبارک اوقات وہی ہیں جو احادیث صحیحہ میں بیان ہو چکے ہیں۔ اس لیے مسلمانوں کو تبرک کےمعاملے میں متنبہ اور حساس ہونا چاہے۔ یعنی جس بزرگ سمجھ لیا اس کی ہر چیز کو متبرک سمجھنا شروع کردیا یہ یکسر غلط ہے۔ حضرت ابوبکر صدیق سے بڑھ کر امتیوں میں کون بزرگ ہو سکتاہے؟کوئی نہیں۔ لیکن صحابہ نے صرف رسول اللہ صلی اللہ علیہ وسلم ہی کے بالوں وغیرہ کو متبرک سمجھا اور آپ کے علاوہ حضرت ابوبکر صدیق تک کی کسی چیز کومتبرک نہیں سمجھا۔ اور فہم دین صحابہ ہی کا معتبر ہے نہ کہ آج کل کے شرک وبدعت زدہ لوگوں کا۔ (4) رسول اللہ صلی اللہ علیہ وسلم کے موئے مبارک کی اہمیت کا اندازہ جلیل القدر مخضرم تابعی امام عبیدہ بن عمرو سلمان رحمہ اللہ کے اس قول سے بخوبی لگایا جا سکتا ہے جو امام المجدثین امیر المومنین فی الحدیث حضرت امام بخاری رحمہ اللہ نے اپنی صحیح میں نقل کیا ہے۔ وہ فرماتے ہیں: [لان تكون عندي شعرة منه احب الي من الدنيا ومافيها] (صحيح البخاري، الوضوء، حدیث170) رسول اللہ صلی اللہ علیہ وسلم کا ایک موئے مبارک میرے پاس ہو تو یہ مجھے دنیا ومافیہا سے زیادہ محبوب ہے۔ اللہ اکبرکبیرا-ہم ان پاکیزہ جذبات واحساسات کی تہہ تک پہنچ سکتے ہیں، نہ ان کی قدرو منزلت کااندازہ ہی لگا سکتے ہیں۔ یہ معیار کمال درجے کا معیار محبت ہے۔ یا اللہ نبی صلی اللہ علیہ وسلم کے ساتھ ہمیں بھی ایسی ہی کمال درجے کی محبت عطا فرما۔آمین۔امام ذہبی رحمہ اللہ نے اس خوبصورت قول پر جو عمدہ تعلیق لگائی ہے۔ وہ بھی اپنی مثال آپ ہے(تفصیل کےلیے دیکھیئے: (سیراعلام النبلاء جلد4 ص42، 43)"}],[1982,"ہشام بن حسان سے اس سند سے بھی یہی حدیث مروی ہے البتہ اس میں اس طرح ہے آپ صلی اللہ علیہ وسلم نے حلاق (سر مونڈنے والے) سے فرمایا: \"میرے دائیں جانب سے شروع کرو اور اسے مونڈو\"۔","صحیح",{"u2":"سفیان نے ہشام بن حسان سے اپنی سند سے یہ حدیث بیان کی اس میں ہے کہ آپ صلی اللہ علیہ وسلم نے حجام سے فرمایا ” میری دائیں جانب سے شروع کرو اور (پہلے) اسے مونڈو۔ “"}],[1983,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے منی کے دن پوچھا جاتا تو آپ صلی اللہ علیہ وسلم فرماتے:\"کوئی حرج نہیں\"، چنانچہ ایک شخص نے پوچھا: میں نے ذبح کرنے سے پہلے حلق کرا لیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ذبح کر لو، کوئی حرج نہیں\"، دوسرے نے کہا: مجھے شام ہو گئی اور میں نے اب تک رمی نہیں کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"رمی اب کر لو، کوئی حرج نہیں ۱؎\"۔\n§وضاحت\n۱؎ : حج میں نحر (قربانی) کے دن جمرہ کبری کو کنکری مارنا ، ہدی کا جانور ذبح کرنا، بالوں کا حلق (منڈوانا) یا قصر (کٹوانا) پھر طواف افاضہ (طواف زیارہ) (یعنی کعبۃ اللہ کا طواف اور صفا و مروہ کی سعی) میں ترتیب افضل ہے، مگر اس حدیث کی روشنی میں رمی، ذبح، حلق، اور طواف میں ترتیب باقی نہ رہ جائے تو دم لازم نہیں ہو گا، اور نہ ہی حج میں کوئی حرج واقع ہو گا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے منٰی کے دنوں میں سوالات کیے جاتے تھے اور آپ صلی اللہ علیہ وسلم فرماتے تھے ” کوئی حرج نہیں۔“ ایک شخص نے سوال کرتے ہوئے کہا: میں نے قربانی سے پہلے بال مونڈ لیے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” قربانی کرو اور کوئی حرج نہیں۔ “ ایک نے کہا: میں نے شام کر دی ہے اور رمی نہیں کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” رمی کرو اور کوئی حرج نہیں۔ “","f2":"یوم النحر(دسویں تاریخ) اعمال اگر اس ترتیب سے ہوں کہ پہلے رمی جمرہ پھرقربانی حجامت اور طواف افاضہ ہو تو بہت ہی افضل ہے۔ورنہ آگے پیچھے بھی جائز ہے۔"}],[1984,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورتوں پر حلق نہیں صرف «تقصير» (بال کٹانا)ہے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” عورتوں کے لیے سر منڈانا نہیں ہے۔ ان کے لیے صرف بال کترنا ہے۔ “"}],[1985,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورتوں پر حلق نہیں بلکہ صرف «تقصير» (بال کٹانا) ہے\"۔","صحیح",{"u2":"سیدناابن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” عورتوں کے لیے سر منڈانا نہیں ہے۔ ان کے لیے صرف بال کترنا ہے۔ “","f2":"عورتوں کے لئے بال کترنا بھی اسی حد تک ہے کہ شرعی حکم پرعمل ہوجائے۔ورنہ مردوں کی مشابہت کی حد تک پہنچنا حرام ہے۔ایسے ہی سر منڈانا بھی ناجائز ہے۔"}],[1986,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کرنے سے پہلے عمرہ کیا۔","صحیح",{"u2":"سیدناابن عمر رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے حج سے پہلے عمرہ کیا تھا۔"}],[1987,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم نے ام المؤمنین عائشہ رضی اللہ عنہا کو ذی الحجہ میں عمرہ صرف اس لیے کرایا کہ مشرکین کا خیال ختم ہو جائے اس لیے کہ قریش کے لوگ نیز وہ لوگ جو ان کے دین پر چلتے تھے، کہتے تھے: جب اونٹ کے بال بڑھ جائیں اور پیٹھ کا زخم ٹھیک ہو جائے اور صفر کا مہینہ آ جائے تو عمرہ کرنے والے کا عمرہ درست ہو گیا، چنانچہ وہ ذی الحجہ اور محرم (اشہر حرم) کے ختم ہونے تک عمرہ کرنا حرام سمجھتے تھے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ قسم ا اللہ کی! رسول اللہ صلی اللہ علیہ وسلم نے عائشہ رضی اللہ عنہا ا کو ذی الحجہ میں صرف اس لیے عمرہ کرایا تھا کہ اس سے اہل شرک کا عمل باطل کریں۔ بلاشبہ قبیلہ قریش اور ان کے اہل دین کہا کرتے تھے کہ جب اونٹوں کے بال بڑھ جائیں، ان کے زخم ٹھیک ہو جائیں اور ماہ صفر شروع ہو جائے تو عمرہ کرنے والے کے لیے عمرہ کرنا حلال ہو گیا۔ یہ لوگ ان دنوں میں عمرہ کرنے کو حرام کہتے تھے حتیٰ کہ ذوالحجہ اور محرم گزر جائے۔"}],[1988,"ابوبکر بن عبدالرحمٰن کہتے ہیں کہ مجھے مروان کے قاصد (جسے ام معقل رضی اللہ عنہا کے پاس بھیجا گیا تھا) نے خبر دی ہے کہ ام معقل کا بیان ہے کہ ابو معقل رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کو نکلنے والے تھے جب وہ آئے تو ام معقل رضی اللہ عنہا کہنے لگیں: آپ کو معلوم ہے کہ مجھ پر حج واجب ہے ۱؎، چنانچہ دونوں (ام معقل اور ابو معقل رضی اللہ عنہما) چلے اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، ام معقل نے کہا: اللہ کے رسول! ابو معقل کے پاس ایک اونٹ ہے اور مجھ پر حج واجب ہے؟ ابو معقل نے کہا: یہ سچ کہتی ہے، میں نے اس اونٹ کو اللہ کی راہ میں دے دیا ہے، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اونٹ اسے دے دو کہ وہ اس پر سوار ہو کر حج کر لے، یہ بھی اللہ کی راہ ہی میں ہے\"، ابومعقل نے ام معقل کو اونٹ دے دیا، پھر وہ کہنے لگیں: اللہ کے رسول! میں عمر رسیدہ اور بیمار عورت ہوں ۲؎ کوئی ایسا کام ہے جو حج کی جگہ میرے لیے کافی ہو، آپ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان میں عمرہ کرنا (میرے ساتھ) حج کرنے کی جگہ میں کافی ہے ۳؎\" ۔\n§وضاحت\n۱؎ : کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کرنے کا ارادہ کر رکھا تھا لیکن میرے لئے رسول اللہ صلی اللہ علیہ وسلم کی معیت مقدر نہیں تھی اور میں نہیں جا سکی۔ ۲؎ : اس لئے مجھے نہیں معلوم کہ میں حج کب کر سکوں گی۔ ۳؎ : یعنی رمضان میں عمرہ کا ثواب میرے ساتھ حج کے ثواب کے برابر ہے۔","حسن",{"u2":"ابوبکر بن عبدالرحمٰن کہتے ہیں کہ مجھے مروان کے اس پیغامبر نے خبر دی جس کو اس نے ام معقل رضی اللہ عنہا ا کے ہاں بھیجا تھا۔ ام معقل رضی اللہ عنہا ا نے کہا کہ ابو معقل رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کے لیے نکلے۔ جب وہ آئے تو ام معقل نے کہا: تم جانتے ہو کہ مجھ پر (بھی) حج (لازم) ہے۔ چنانچہ وہ دونوں چلتے آئے حتیٰ کہ رسول اللہ صلی اللہ علیہ وسلم سے ملے۔ پس ام معقل رضی اللہ عنہا ا نے کہا: اے اللہ کے رسول! بلاشبہ مجھ پر حج فرض ہے اور ابو معقل کے پاس صرف ایک اونٹ ہے۔ ابو معقل رضی اللہ عنہ کہنے لگے یہ سچ کہتی ہے اور میں نے اس اونٹ کو اللہ کی راہ میں کر دیا ہے (جہاد میں۔) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم یہ اسے دے دو، یہ اس پر حج کرے گی، یہ بھی فی سبیل اللہ ہے۔ “ چنانچہ ابو معقل رضی اللہ عنہ نے یہ اونٹ اسے دے دیا۔ تو وہ کہنے لگی: اے اللہ کے رسول! میں عورت ذات ہوں، عمر زیادہ ہو گئی ہے اور بیمار بھی ہوں، تو کیا کوئی عمل ایسا ہے جو مجھ سے میرے حج سے کفایت کر جائے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” رمضان میں عمرہ، حج سے کفایت کرتا ہے۔ “","f2":"شیخ البانی رحمۃ اللہ علیہ نےاے اللہ! رسول صلی اللہ علیہ وسلم میں عورت ذات ہوں۔سے کفایت کرجائے۔تک کے حصے کے بغیر اس روایت کو صحیح قرار دیا ہے۔لیکن پھر اس کے بعد والا حصہ یعنی رمضان میں عمرہ حج سے کفایت کرتا ہے۔یہ بھی غیر صحیح ہونا چاہیے۔کیونکہ اس کا تعلق اسی سوال سے ہے۔جسے ضعیف قرار دیا گیا ہے۔علاوہ ازیں دوسری صحیح روایات میں یہ الفاظ بیان ہوئے ہیں۔رمضان میں عمرہ حج کے برابر ہے۔ نہ کہ حج سے کفایت کرتاہے۔واللہ اعلم۔"}],[1989,"ام معقل رضی اللہ عنہا کہتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کیا تو ہمارے پاس ایک اونٹ تھا لیکن ابومعقل رضی اللہ عنہ نے اسے اللہ کی راہ میں دے دیا تھا ہم بیمار پڑ گئے، اور ابومعقل رضی اللہ عنہ چل بسے، نبی اکرم صلی اللہ علیہ وسلم حج کو تشریف لے گئے، جب اپنے حج سے واپس ہوئے تو میں آپ کی خدمت میں حاضر ہوئی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ام معقل! کس چیز نے تمہیں ہمارے ساتھ (حج کے لیے) نکلنے سے روک دیا؟\"، وہ بولیں: ہم نے تیاری تو کی تھی لیکن اتنے میں ابومعقل کی وفات ہو گئی، ہمارے پاس ایک ہی اونٹ تھا جس پر ہم حج کیا کرتے تھے، ابومعقل نے اسے اللہ کی راہ میں دے دینے کی وصیت کر دی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اسی اونٹ پر سوار ہو کر کیوں نہیں نکلیں؟ حج بھی تو اللہ کی راہ میں ہے، لیکن اب تو ہمارے ساتھ تمہارا حج جاتا رہا تم رمضان میں عمرہ کر لو، اس لیے کہ یہ بھی حج کی طرح ہے\"، ام معقل رضی اللہ عنہا کہا کرتی تھیں حج حج ہے اور عمرہ عمرہ ہے ۱؎لیکن رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے یہی فرمایا اب مجھے نہیں معلوم کہ یہ حکم میرے لیے خاص تھا (یا سب کے لیے ہے) ۔\n§وضاحت\n۱؎ : یعنی دونوں ایک مرتبہ میں نہیں ہے۔","صحیح لغیرہ",{"u2":"سیدہ ام معقل رضی اللہ عنہا ا بیان کرتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے حجتہ الوداع کیا تو ہمارے پاس ایک ہی اونٹ تھا۔ ابومعقل رضی اللہ عنہ نے اس کو جہاد فی سبیل اللہ کے لیے وقف کر دیا تھا۔ ہمیں بیماری نے آ لیا اور ابو معقل فوت ہو گئے۔ اور نبی کریم صلی اللہ علیہ وسلم تشریف لے گئے۔ جب آپ صلی اللہ علیہ وسلم اپنے حج سے فارغ ہو کر آئے تو میں حاضر خدمت ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے ام معقل! کیا مانع تھا کہ تو ہمارے ساتھ حج کے لیے نہیں گئی؟ “ اس نے کہا: ہم تو تیار تھے مگر ابو معقل فوت ہو گئے، ہمارا ایک ہی اونٹ تھا جس پر ہمیں حج کرنا تھا، تو ابومعقل نے اس کے بارے میں وصیت کر دی کہ یہ جہاد فی سبیل اللہ کے لیے وقف ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو اسی پر کیوں نہ چل دی؟ بلاشبہ حج ” فی سبیل اللہ “ ہی ہے۔ خیر جب تم سے ہمارے ساتھ یہ حج کرنا فوت ہو گیا ہے تو رمضان میں عمرہ کرنا، بلاشبہ یہ حج کی مانند ہے۔ “ چنانچہ وہ کہا کرتی تھیں کہ حج، حج ہے اور عمرہ، عمرہ ہے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے یہ فرمایا تھا، معلوم نہیں یہ بات میرے لیے خاص تھی (یا امت کے لیے عام)۔","f2":"1۔حافظ ابن حجر رحمۃ اللہ علیہ نے فتح الباری (کتاب العمرۃ باب عمرۃ فی رمضان حدیث۔1782)میں لکھا ہے کہ یہ در اصل دو واقعات ہیں۔یہ اما معقل کا ہے اور اس سے پہلے والا حدیث (1988) میں ام طلیق کا ہے۔جیسے کہ ابو علی بن سکن نے اس کو نکالا ہے اور ابن مندہ نے کتاب الصحابہ اور دو لابی نے الکنیٰ میں نقل کیا ہے۔2۔علامہ البانیرحمۃ اللہ علیہ نے پہلی حدیث (1988) میں عورت کا مقولہ (قد كبرت وسكمت۔۔۔الخ) کو غیر صحیح کہا ہے۔اوردوسری حدیث میں ام معقل کامقولہ (الحج حجة والمعرة عمرة۔۔۔الخ) کو ضعیف کہا ہے۔3۔زوجین کو دینی ودنیاوی ہر معاملے میں ایک دوسرے کا معاون بننا چاہیے۔4۔فی سبیل اللہ مال وقف کرنا انتہائی عزیمت کا عمل ہے۔اور حج بھی فی سبیل اللہ میں شمار ہے۔اس لئے حضرات ابن عباس رضی اللہ تعالیٰ عنہ اور ابن عمر رضی اللہ تعالیٰ عنہ امام احمد بن حنبل اور اسحاق راہویہ رحمۃ اللہ علیہ سفر حج میں جانے والوں کےلئے زکواۃ کی رقم س معاونت جائزسمجھتے ہیں۔ جبکہ دیگر عام علماء فی سبیل اللہ س مراد جہاد ہی لیتے ہیں۔اور اقرب یہ ہے کہ حجاج سے تعاون تبلیغی مساعی اور جہاد سبھی مواقع فی سبیل اللہ میں شامل ہیں۔واللہ اعلم۔5۔رمضان میں عمرے کا ثواب حج کے برابر ہوتاہے مگر اس کے یہ معنی نہیں کہ قرض ساقط ہوجائےگا۔ 6۔جیسے حضور قلب اور اخلاص نیت کی بنا پر عمل کا ثواب بڑھ جاتا ہے ایسے ہی مبارک وقت کی مناسبت سے عمل کاثواب بڑھ جاتا ہے۔7۔رمضان میں عمرہ کرنا از حد افضل اعمال میں سے ہے۔"}],[1990,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کا ارادہ کیا، ایک عورت نے اپنے خاوند سے کہا: مجھے بھی اپنے اونٹ پر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کرائیں، انہوں نے کہا: میرے پاس تو کوئی ایسی چیز نہیں جس پر میں تمہیں حج کراؤں، وہ کہنے لگی: مجھے اپنے فلاں اونٹ پر حج کراؤ، تو انہوں نے کہا: وہ اونٹ تو اللہ کی راہ میں وقف ہے، پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور کہنے لگے: اللہ کے رسول! میری بیوی آپ کو سلام کہتی ہے، اس نے آپ کے ساتھ حج کرنے کی مجھ سے خواہش کی ہے، اور کہا ہے: مجھے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کرائیں، میں نے اس سے کہا: میرے پاس کوئی ایسی چیز نہیں جس پر میں تمہیں حج کراؤں، اس نے کہا: مجھے اپنے فلاں اونٹ پر حج کرائیں، میں نے اس سے کہا: وہ تو اللہ کی راہ میں وقف ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"سنو اگر تم اسے اس اونٹ پر حج کرا دیتے تو وہ بھی اللہ کی راہ میں ہوتا\"۔ اس نے کہا: اس نے مجھے یہ بھی آپ سے دریافت کرنے کے لیے کہا ہے کہ کون سی چیز آپ صلی اللہ علیہ وسلم کے ساتھ حج کرنے کے برابر ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے سلام کہو اور بتاؤ کہ رمضان میں عمرہ کر لینا میرے ساتھ حج کر لینے کے برابر ہے\"۔","حسن صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کا ارادہ فرمایا تو ایک عورت نے اپنے شوہر سے کہا: مجھے بھی رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنے اونٹ پر حج کراؤ۔ اس نے کہا: میرے پاس کوئی ایسی سواری نہیں جس پر میں تمہیں حج کراؤں۔ عورت نے کہا: اپنے فلاں اونٹ پر؟ اس نے جواب دیا کہ وہ تو فی سبیل للہ (جہاد کے لیے) وقف ہے۔ پس وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا کہ میری بیوی نے آپ صلی اللہ علیہ وسلم کو السلام علیکم ورحمۃ اللہ کہا ہے، اور وہ مجھے کہتی ہے کہ میں اس کو آپ کے ساتھ حج کراؤں۔ وہ کہتی ہے، مجھے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حج کراؤ۔ تو میں نے اس سے کہا: میرے پاس کوئی سواری نہیں جس پر میں تجھے حج کراؤں۔ اس نے کہا: اپنے فلاں اونٹ پر۔ تو میں نے کہا: وہ تو فی سبیل للہ وقف ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اگر تم اسے اس پر حج کرا دو تو یہ بھی فی سبیل للہ ہی ہے۔ “ اس نے کہا کہ اس (عورت) نے مجھے کہا ہے کہ میں آپ صلی اللہ علیہ وسلم سے یہ دریافت کروں کہ کون سا عمل آپ صلی اللہ علیہ وسلم کے ساتھ حج کے برابر ہو سکتا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسے (میری طرف سے) السلام علیکم ورحمتہ اللہ وبرکاتہ کہنا اور اسے بتانا کہ رمضان میں عمرہ کرنا میرے ساتھ حج کرنے کے برابر ہے۔ “","f2":"اس حدیث سے بھی واضح ہے کہ حج کرنا بھی فی سبیل اللہ میں داخل ہے جو زکواۃ کا ایک مصرف ہے۔"}],[1991,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو عمرے کئے: ایک ذی قعدہ میں اور دوسرا شوال میں ۱؎۔\n§وضاحت\n۱؎ : کچھ لوگوں کا کہنا ہے کہ اس حدیث میں ام المومنین عائشہ رضی اللہ عنہا نے نبی اکرم صلی اللہ علیہ وسلم کے عمرے کی مجموعی تعداد کا ذکر نہیں کیا ہے بلکہ ان کی مراد یہ ہے کہ ایک سال کے اندر آپ صلی اللہ علیہ وسلم نے دو عمرے کئے : ایک ذی قعدہ میں اور ایک شوال میں، لیکن یہ قول صحیح نہیں ہے کیونکہ ایک سال کے اندر دو عمرہ نبی اکرم صلی اللہ علیہ وسلم نے کبھی نہیں کیا ہے، اور حج کے ساتھ والے عمرے کو چھوڑ کر آپ صلی اللہ علیہ وسلم کے سارے عمرے ذی قعدہ میں ہوئے ہیں، پھر ام المومنین عائشہ رضی اللہ عنہا کا «عمرۃ فی شوّال» کہنا ان کا وہم ہے، اور اگر اسے محفوظ مان لیا جائے تو اس کی تاویل یہ ہوگی اس عمرہ سے مراد عمرہ جعرانہ ہے جو اگرچہ ذی قعدہ ہی میں ہوا ہے، لیکن مکہ سے حنین کے لئے آپ شوال ہی میں نکلے تھے، اور واپسی پر جعرانہ سے احرام باندھ کر یہ عمرہ کیا تھا تو نکلنے کا لحاظ کرکے انہوں نے اس کی نسبت شوال کی طرف کر دی ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو عمرے کیے تھے ایک ذوالقعدہ میں اور ایک شوال میں۔","f2":"1۔صحیح اور درست بات یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم نے چار عمرے کیے ہیں۔جیسا کہ صحیحین میں اس کی صراحت موجود ہے۔(صحیح البخاری العمرۃ حدیث 1775۔1776 وصحیح مسلم الحج حدیث 1253)مگر حضرت عائشہ رضی اللہ تعالیٰ عنہ کا دو عمرے بتانا شاید اسی بنا پر ہے۔کہ آپ نے فعلاً اور بالا استقلال دو عمرے کئے ہیں۔عمرہ حدیبیہ میں آپ کو روک دیا گیا تھا۔اور آپ واپس چلے آئے تھے۔ اور حج والا عمرہ ضمنی عمرہ تھا۔ انہوں نے ان کو شمار نہیں فرمایا۔2۔شوال میں عمرہ اس معنی میں ہے۔کہ عمرہ جعرانہ کا سفر شوال میں شروع ہوا تھا تو انہوں نے شوال کا زکر کیا ورنہ عملا ً زوالعقدہ میں ادا کیا گیا تھا۔(بزل المجہود)"}],[1992,"مجاہد کہتے ہیں کہ ابن عمر رضی اللہ عنہما سے پوچھا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے کتنے عمرے کئے؟ انہوں نے جواب دیا: دو بار۱؎، اس پر ام المؤمنین عائشہ رضی اللہ عنہا نے کہا: ابن عمر رضی اللہ عنہما کو یہ معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس عمرے کے علاوہ جو آپ نے حجۃ الوداع کے ساتھ ملایا تھا تین عمرے کئے ہیں۔\n§وضاحت\n۱؎ : عبداللہ بن عمر رضی اللہ عنہما نے عمرہ حدیبیہ کو اور اسی طرح حج کے ساتھ والے عمرہ کو شمار نہیں کیا۔","ضعیف",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے پوچھا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے کتنے عمرے کیے؟ انہوں نے کہا: دو۔ عائشہ رضی اللہ عنہا ا نے کہا: ابن عمر رضی اللہ عنہ کو تو معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تین عمرے کیے تھے، سوائے اس کے جسے آپ صلی اللہ علیہ وسلم نے حجتہ الوداع کے ساتھ ملا کر کیا تھا۔"}],[1993,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چار عمرے کئے: ایک عمرہ حدیبیہ کا، دوسرا وہ عمرہ جسے آئندہ سال کرنے پر اتفاق کیا تھا، تیسرا عمرہ جعرانہ کا ۱؎، اور چوتھا وہ جسے آپ صلی اللہ علیہ وسلم نے اپنے حج کے ساتھ ملایا تھا۔\n§وضاحت\n۱؎ : ’’جعرانة‘‘: طائف اور مکہ کے درمیان ایک جگہ کا نام ہے، نبی اکرم صلی اللہ علیہ وسلم نے غزوہ حنین کے مال غنیمت کی تقسیم کے بعد یہیں سے عمرہ کا احرام باندھا تھا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چار عمرے کیے تھے۔ عمرہ حدیبیہ (جس سے آپ صلی اللہ علیہ وسلم کو واپس جانا پڑا تھا) دوسرا وہ جو حسب اتفاق معاہدہ اگلے سال کیا۔ تیسرا جعرانہ سے اور چوتھا جو آپ صلی اللہ علیہ وسلم نے اپنے حج کے ساتھ ملا کر کیا۔"}],[1994,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چار عمرے کئے اور وہ تمام ذی قعدہ میں تھے سوائے اس کے جسے آپ نے اپنے حج کے ساتھ ملایا تھا۔ ابوداؤد کہتے ہیں: یہاں سے آگے کے الفاظ میں نے ابوالولید سے بھی سنے لیکن انہیں یاد نہیں رکھ سکا، البتہ ہدبہ کے الفاظ اچھی طرح یاد ہیں کہ: ایک حدیبیہ کے زمانے کا، یا حدیبیہ کا عمرہ، دوسرا ذی قعدہ میں قضاء کا عمرہ، تیسرا عمرہ ذی قعدہ میں جعرانہ کا جب آپ صلی اللہ علیہ وسلم نے حنین کا مال غنیمت تقسیم فرمایا، اور چوتھا وہ عمرہ جسے آپ نے اپنے حج کے ساتھ ملایا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چار عمرے کیے تھے اور سبھی ذوالقعدہ میں کیے سوائے اس کے جو حج کے ساتھ تھا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں یہاں تک مجھے ہدبہ بن خالد سے خوب یاد ہے۔ اور ابوالولید سے بھی میں نے سنا ہے مگر اچھی طرح ضبط نہیں۔ یعنی عمرہ حدیبیہ کے زمانے میں، عمرہ القضاء ذوالقعد میں، عمرہ جعرانہ جب آپ نے ذوالقعدہ میں حنین کی غنیمتیں تقسیم کی تھیں اور حج کے ساتھ والا عمرہ۔","f2":"بعض لوگو کہتے ہیں کہ اگر آدمی حج کے مہینوں میں عمرہ کر لے تو اسے حج کرنالازمی ہوجاتاہے۔مگر اس کی کوئی حقیقت نہیں رسول اللہ صلی اللہ علیہ وسلم کے پہلے تینوں عمرے زو العقیدہ میں تھے جو حج کا مہینہ ہے۔"}],[1995,"عبدالرحمٰن بن ابی بکر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن رضی اللہ عنہ سے فرمایا: \"عبدالرحمٰن! اپنی بہن عائشہ کو بٹھا کر لے جاؤ اور انہیں تنعیم ۱؎ سے عمرہ کرا لاؤ، جب تم ٹیلوں سے تنعیم میں اترو تو چاہیئے کہ وہ احرام باندھے ہو، کیونکہ یہ مقبول عمرہ ہے\"۔\n§وضاحت\n۱؎ : ’’تنعيم‘‘ : ایک مقام ہے مکہ سے تین میل کے فاصلے پر، اب وہاں پر ایک مسجد بن گئی ہے جسے مسجد عائشہ کہتے ہیں، عمرہ کا احرام حرم سے باہر نکل کر باندھنا چاہئے، یہ مقام بہ نسبت دوسرے مقامات کے زیادہ قریب ہے اس لئے آپ صلی اللہ علیہ وسلم نے عائشہ رضی اللہ عنہا کو وہیں سے عمرہ کرانے کا حکم دیا۔","صحیح",{"u2":"سیدنا عبدالرحمٰن بن ابی بکر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا تھا ” اے عبدالرحمٰن! اپنی بہن عائشہ کو اپنے پیچھے سوار کرو اور اسے تنعیم سے عمرہ کروا لاؤ۔ تم جب اسے لے کر ٹیلے سے نیچے اترو تو اسے چاہیئے کہ احرام باندھے۔ بیشک یہ عمرہ مقبول ہو گا۔ “","f2":"1۔تنعیم مکہ سے چھ میل کے فاصلے پر قریب ترین مقام اورآجکل شہر کی آبادی کاحصہ ہے۔اور مسجد عائشہ کے نام سے معروف منزل ہے۔2۔علامہ البانی رحمۃ اللہ علیہ فرماتے ہیں۔کہ اس روایت میں (فاذا ھبطت) جب تو اسے لے کر ٹیلےسے اُترے۔ والا آخری حصہ صحیح نہیں ہے۔"}],[1996,"محرش کعبی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جعرانہ میں داخل ہوئے تو مسجد آئے اور وہاں اللہ نے جتنی چاہا نماز پڑھی، پھر احرام باندھا، پھر اپنی سواری پر جم کر بیٹھ گئے اور وادی سرف کی طرف بڑھے یہاں تک کہ مدینہ کے راستہ سے جا ملے، پھر آپ نے صبح مکہ میں اس طرح کی جیسے کوئی رات کو مکہ میں رہا ہو۔","صحیح",{"u2":"سیدنا محرش کعبی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جعرانہ میں تشریف لائے پھر مسجد میں آئے اور جو اللہ نے چاہا نماز پڑھی۔ پھر آپ صلی اللہ علیہ وسلم نے احرام باندھا، پھر اپنی سواری پر درست ہو کر بیٹھ گئے اور دامن وادی سرف کا رخ کر لیا حتیٰ کہ مدینہ کی راہ پر جا ملے اور مکہ میں صبح کی، گویا کہ آپ صلی اللہ علیہ وسلم رات ہی سے یہیں تھے۔","f2":"(فاصبح بمکۃ کبائت) اور مکہ میں صُبح کی۔گویا کہ آپ رات ہی سے یہیں تھے۔یہ جملہ کسی راوی کا وہم ہے۔جامع ترمذی سنن نسائی اور مسند احمد میں جو آیا ہے۔وہ صحیح تر ہے کہ آپ نے رات میں عمرہ کیا۔اور رات ہی کو جعرانہ واپس تشریف لے آئے۔گویا آپ نے رات یہیں گزاری تھی۔ اور اس بنا پر بعض اصحاب رضوان اللہ عنہم اجمعین پرآپ صلی اللہ علیہ وسلم کا یہ عمرہ مخفی رہا۔(بزل المجہود) یہ حدیث باب سے اس طرح مطابقت رکھتی ہے۔کہ قضا یا نفلی عمرہ ادا کرن ےوالا تنعیم سے احرام باندھے یاجعرانہ سے یہی دو مقام قریب کے میقات ہیں۔"}],[1997,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عمرہ قضاء میں تین دن قیام فرمایا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عمرہ قضاء میں (مکہ کے اندر) تین دن ٹھہرے تھے۔","f2":"مہاجرین مدینہ کے لئے پابندی تھی کہ وہ مکہ میں تین دن سے زیادہ نہ ٹھریں۔دیگر مسلمانوں کے لئے کسی طرح کوئی پابندی نہیں۔خواہ رکے رہیں یا واپس چلے جایئں۔"}],[1998,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے یوم النحر کو طواف افاضہ کیا پھر منی میں ظہر ادا کی یعنی (طواف سے) لوٹ کر۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی والے دن طواف افاضہ کیا، پھر لوٹ کر منٰی میں ظہر کی نماز پڑھی۔","f2":"عرفات اور مزدلفہ سے لوٹنے کے بعد دسویں تاریخ کو یا اس کے بعد کسی وقت بیت اللہ کاطواف کرنا فرض ہے۔قرآن مجید کا حکم ہے۔(وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ)(الحج۔29) انھیں چاہیے کہ قدیم گھر کاطواف کریں اس طواف کوطواف افاضہ طواف زیارہ اور طواف رکن بھی کہتے ہیں۔افضل یہی ہے کہ دسویں زی الحجہ کو کرلیا جائے۔یا ایام تشریق میں کسی وقت۔\nاس حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مکہ سے واپس لوٹ کر منیٰ میں ظہر کی نماز پڑھی جبکہ حضرت جابر رضی اللہ تعالیٰ عنہ اور عائشہ رضی اللہ تعالیٰ عنہا کی روایات میں ہے۔کہ آپ نے مکہ میں ظہر کی نماز پڑھی۔بعد ازاں آپ منیٰ میں تشریف لائے۔دونوں روایتیں سندا صحیح ہیں۔اور محدثین نے اپنے اپنے انداز میں ترجیح دی ہے۔شیخ الاسلام ابن تیمیہرحمۃ اللہ علیہ اور بعض دیگر نے منیٰ میں نماز پڑھنے کی روایت کو ترجیح دی ہے۔اور اس کی کوئی وجوہ ہیں۔(الف) اگر آپ مکہ میں ظہر کی نماز پڑھتے تو منیٰ میں اپنا کوئی نائب بنا کر جاتے جو انہیں ظہر کی نماز پڑھاتا اور یہ منقول نہیں ہے۔اور نائب کا نماز پڑھانا محال ہے۔ اور کسی نے اس کا ذکر بھی نہیں کیا ہے۔حالانکہ ایک سفر میں آپ نے عبدالرحمٰن بن عوف رضی اللہ تعالیٰ عنہ کو اپنا نائب بنایا تھا۔ ایک بار حضرت ابو بکر صدیق رضی اللہ تعالیٰ عنہ کو اپنا نائب بنایا تھا۔جبکہ آپ بنو عمرو بن عوف میں ان کے درمیان صلح کرانے کے لئے تشریف لے گئے تھے اسی طرح اس ایام مرض میں بھی آپ نے ان کو اپنا امام بنایا تھا۔اور یہ سوال کہ مکہ میں آپ نے نائب نہیں بنایا۔تو اس کی قطعاً ضرورت ہی نہیں تھی۔کیونکہ ان لوگوں کےلئے امام پہلے سے مقرر شدہ تھا جو انہیں نمازیں پڑھاتا تھا۔ (ب) اگرآپ مکہ میں نماز پڑھاتے۔تو اہل مکہ پوری نماز پڑھتے۔ کیونکہ ان پر اتمام واجب تھا اور نبی کریم صلی اللہ علیہ وسلم نے ان لوگوں کو حسب دستور یہ نہیں فرمایا کہ اپنی نماز پوری کرو ہم لوگ مسافر ہیں۔ جیسے کے فتح مکہ کے موقع پر کہا تھا۔ (ج) یہ ممکن ہے کہ فتح مکہ میں آپ کا نماز پڑھنا یا پڑھانا رکعات طواف سے مشتبہ ہوگیا۔بالخصوص کے لوگ آپ کے ساتھ نماز پڑھ رہے تھے۔اور آپ کی اقتداء بھی کرتے تھے۔دیکھنے والے نے اس کو نماز ظہر سمجھا ہو۔مگرآپ کا منیٰ میں نماز پڑھنا کسی طور پرمشتبہ نہیں ہوسکتا۔بالخصوص جبکہ آپ حجاج کے امام تھے۔آپ کےعلاوہ کوئی اور نماز پڑھانے کامجاز ہی نہ تھا۔اور یہ کیسے ہوسکتا ہے کہ آپ انھیں امام کے بغیر چھوڑ جایئں۔ اور وہ اکیلےاکیلے نماز پڑھیں۔یہ انتہائی بعید از قیاس بات ہے۔حضرت عائشہ رضی اللہ تعالیٰ عنہا کی حدیث سے کچھ محدثین نے یہ سمجھا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے منیٰ میں نماز ظہر ادا کی۔بعد ازاں بیت اللہ تشریف لے گئے۔جیسے کہ وہ کہتی ہیں کہ آپ نے ظہر کی نماز پڑھ کر دن کےآخری حصہ میں طواف افاضہ کیا۔ پھر منیٰ واپس آگئے۔دیکھئے۔(تہذیب ابن قیم رحمۃ اللہ علیہ)"}],[1999,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ میری وہ رات جس میں رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے یوم النحر کی شام تھی، چنانچہ آپ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، اتنے میں وہب بن زمعہ اور ان کے ساتھ ابوامیہ کی اولاد کا ایک شخص دونوں قمیص پہنے میرے یہاں آئے، رسول اللہ صلی اللہ علیہ وسلم نے وہب سے پوچھا: \"ابوعبداللہ! کیا تم نے طواف افاضہ کر لیا؟\"وہ بولے: قسم اللہ کی! نہیں اللہ کے رسول، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو پھر اپنی قمیص اتار دو\"، چنانچہ انہوں نے اپنی قمیص اپنے سر سے اتار دی اور ان کے ساتھی نے بھی اپنے سر سے اپنی قمیص اتار دی پھر بولے: اللہ کے رسول! ایسا کیوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ وہ دن ہے کہ جب تم جمرہ کو کنکریاں مار لو تو تمہارے لیے وہ تمام چیزیں حلال ہو جائیں گی جو تمہارے لیے حالت احرام میں حرام تھیں سوائے عورتوں کے، پھر جب شام کر لو اور بیت اللہ کا طواف نہ کر سکو تو تمہارا احرام باقی رہے گا، اسی طرح جیسے رمی جمرات سے پہلے تھا یہاں تک کہ تم اس کا طواف کر لو\"۔\n§وضاحت\n۱؎ : اس حدیث سے یوم النحر کو طواف زیارت کرنے کی تاکید ثابت ہوتی ہے، اور اس سے معلوم ہوتا ہے کہ اگر اس دن کسی نے طواف نہیں کیا تو وہ دوبارہ احرام میں واپس لوٹ آئے گا، جب تک وہ طواف نہ کرلے وہ احرام ہی میں رہے (ملاحظہ ہو: «صحیح ابن خزیمہ (كتاب المناسك، باب النهي عن الطيب واللباس إذا أمسى الحاج يوم النحر قبل أن يفيض وكل ما زجر الحاج عنه قبل رمي الجمرة يوم النحر، حدیث نمبر: ۲۹۵۸» )","حسن صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا نے بیان کیا کہ قربانی والے دن شام کو میری باری کی رات تھی، جس میں کہ رسول اللہ صلی اللہ علیہ وسلم کو میرے پاس تشریف لانا تھا۔ چنانچہ آپ صلی اللہ علیہ وسلم تشریف لائے اور میرے پاس وہب بن زمعہ آیا اور اس کے ساتھ آل ابی امیہ کا ایک اور آدمی بھی تھا۔ ان دونوں نے قمیصیں پہن رکھی تھیں، تو رسول اللہ صلی اللہ علیہ وسلم نے وہب سے فرمایا ” ابوعبداللہ! کیا تم نے طواف افاضہ کر لیا ہے؟ “ اس نے کہا: نہیں، قسم اللہ کی! اے اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنی یہ قمیص اتار دو۔ “ چنانچہ اس نے اپنی قمیص اتار دی اور سر کی جانب سے اتاری۔ اور اس کے ساتھی نے بھی اتار دی، اور سر کی جانب سے اتاری۔ پھر انہوں نے پوچھا، اور یہ کیوں اے اللہ کے رسول؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تمہیں اس دن میں رخصت ہے کہ جب تم جمرہ کو کنکریاں مار لو تو حلال ہو جاؤ۔ یعنی ہر اس چیز سے جو تم پر حرام کی گئی ہے، سوائے بیویوں کے۔ اگر بیت اللہ کا طواف کرنے سے پہلے شام ہو جائے تو تم پھر سے محرم ہو جاؤ گے جیسے کہ کنکریاں مارنے سے پہلے تھے حتیٰ کہ اس کا طواف کر لو۔ “","f2":"اس حدیث سے معلوم ہوا کہ اگر دسویں تاریخ کوشام تک حاجی طواف افاضہ نہ کرسکا ہو تو اسے دوبارہ احرام کی حالت میں آجانا چاہیے۔"}],[2000,"ام المؤمنین عائشہ اور ابن عباس رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے یوم النحر کا طواف رات تک مؤخر کیا۱؎۔\n§وضاحت\n۱؎ : دسویں تاریخ کے طواف کو طواف زیارہ یا طواف افاضہ کہتے ہیں۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا اور سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے قربانی کے روز طواف کو رات تک مؤخر کیا تھا۔"}],[2001,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے طواف افاضہ کے سات پھیروں میں رمل نہیں کیا ۱؎ ۔\n§وضاحت\n۱؎ : معلوم ہوا کہ دوران طواف دلکی چال جسے رمل کہتے ہیں وہ صرف طواف قدوم میں مشروع ہے طواف افاضہ وغیرہ میں مشروع نہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اپنے طواف افاضہ میں رمل نہیں کیا تھا (آہستہ آہستہ نہیں دوڑے تھے جیسے کہ طواف قدوم میں کیا تھا۔)"}],[2002,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ لوگ ہر جانب سے (مکہ سے) لوٹتے تھے تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بھی مکہ سے کوچ نہ کرے یہاں تک کہ اس کا آخری کام بیت اللہ کا طواف (طواف وداع) ہو ۱؎\"۔\n§وضاحت\n۱؎ : اسے طواف صدر یا طواف وداع کہتے ہیں، بعض اہل علم کے نزدیک یہ سنت ہے، اور بعض کے نزدیک واجب ، اگر عورت کو چلتے وقت حیض آ جائے تو وہ یہ طواف چھوڑ دے تو اس میں کوئی حرج نہیں۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں کہ لوگ (حج کے بعد) ہر جانب واپس چلے جاتے تھے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کوئی شخص ہرگز نہ جائے حتیٰ کہ اس کا آخری عمل بیت اللہ کا طواف ہو۔ “","f2":"یہ حدیث طواف وداع (آخری الوداعی طواف)کے واجب ہونے کی دلیل ہے۔الا یہ کہ کوئی خاتون حیض کے ایام میں ہو۔اور جو یہ چھوڑ دے اس پر دم (ایک جانور قربان کرنا)لازم آتا ہے۔"}],[2003,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صفیہ بنت حیي رضی اللہ عنہا کا ذکر کیا تو لوگوں نے عرض کیا: انہیں حیض آ گیا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"لگتا ہے وہ ہم کو روک لیں گی\"، لوگوں نے عرض کیا: اللہ کے رسول! وہ طواف افاضہ کر چکی ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر تو کوئی بات نہیں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ صفیہ بنت حیی کا ذکر کیا تو بتایا گیا کہ اسے حیض آ گیا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” شاید یہ ہمیں روکنے والی ہے؟ “ (گھر والوں نے) کہا: اے ا اللہ کے رسول! اس نے طواف افاضہ کر لیا ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تب نہیں۔ “"}],[2004,"حارث بن عبداللہ بن اوس کہتے ہیں کہ میں عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور آپ سے اس عورت کے متعلق پوچھا جو یوم النحر کو بیت اللہ کا طواف (افاضہ) کر چکی ہو، پھر اسے حیض آ گیا ہو؟ انہوں نے کہا: وہ آخری طواف (طواف وداع) کر کے جائے (یعنی: طواف وداع کا انتظار کرے)، حارث نے کہا: اسی طرح مجھے رسول اللہ صلی اللہ علیہ وسلم نے بھی بتایا تھا، اس پر عمر نے کہا تیرے دونوں ہاتھ گر جائیں ۱؎! تم نے مجھ سے ایسی بات پوچھی جسے تم رسول اللہ صلی اللہ علیہ وسلم سے پوچھ چکے تھے تاکہ میں اس کے خلاف بیان کروں۔\n§وضاحت\n۱؎ : بظاہر یہ بددعا ہے لیکن حقیقت میں بددعا مقصود نہیں بلکہ مقصود یہ بتانا ہے کہ ایسا کرکے تم نے غلط کام کیا ہے۔","صحیح تو ہے مگر پچھلی حدیث سے منسوخ ہے، پہلے یہ حکم تھا بعد میں منسوخ ہو گیا جو ان دونوں صحابی رضی اللہ عنہما سے مخفی رہ گیا",{"u2":"سیدنا حارث بن عبداللہ بن اوس رضی اللہ عنہ کہتے ہیں کہ میں سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس آیا اور ان سے پوچھا کہ جو عورت قربانی والے دن طواف کر چکی ہو، پھر اسے حیض آ جائے تو؟ عمر رضی اللہ عنہ نے کہا: چاہیئے کہ اس کا آخری عمل بیت اللہ کا طواف ہو۔ تب حارث نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بھی مجھ سے ایسے ہی فرمایا تھا۔ تو عمر رضی اللہ عنہ نے کہا ” تیرے ہاتھ گر جائیں۔ مجھ سے وہ بات پوچھتا ہے جو پہلے رسول اللہ صلی اللہ علیہ وسلم سے پوچھ چکا ہے تاکہ میں ان کی مخالفت کروں۔ “","f2":"1۔اس روایت میں بیان کردہ حضرت عمر رضی اللہ تعالیٰ عنہ کی رائے سابقہ حدیث کے خلاف ہے۔(ممکن ہے کہ سابقہ حدیث ان کے علم میں نہ ہو)اس لئے مسئلہ وہی صحیح ہے۔جو سابقہ حدیث سے ثابت ہے۔مگر بات واضح ہے کہ ہرگز جائز نہیں۔کہ رسول اللہ صلی اللہ علیہ وسلم کےصریح صحیح فرمان کے ہوتے ہوئے آدمی ادھر اُدھر سے فتوے مانگتا پھرے۔یہ رسول اللہ صلی اللہ علیہ وسلم پر ایمان کے منافی ہے۔2۔یہ حدیث حضرت عمر رضی اللہ تعالیٰ عنہ کے کمال وفضل اور جذبہ اتباع رسول پر دلالت کرتی ہے۔3۔شیخ البانی رحمۃ اللہ علیہ اس روایت کی بابت لکھتے ہیں۔ کہ یہ روایت منسوخ ہے اور ما قبل روایت ناسخ ہے۔"}],[2005,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے تنعیم سے عمرے کا احرام باندھا پھر میں (مکہ) گئی اور اپنا عمرہ پورا کیا، رسول اللہ صلی اللہ علیہ وسلم نے مقام ابطح ۱؎ میں میرا انتظار کیا یہاں تک کہ میں فارغ ہو کر (آپ کے پاس واپس آ گئی) تو آپ نے لوگوں کو روانگی کا حکم دیا، آپ صلی اللہ علیہ وسلم خانہ کعبہ آئے اور اس کا طواف کیا پھر روانہ ہوئے۔\n§وضاحت\n۱؎ : وہ میدان جو مکہ اور منی کے درمیان ہے اسے وادی محصب بھی کہتے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں نے تنعیم سے عمرے کا احرام باندھا، پھر حرم میں داخل ہوئی اور اپنا عمرہ پورا کیا۔ اور رسول اللہ صلی اللہ علیہ وسلم نے وادی ابطح میں میرا انتظار کیا حتیٰ کہ میں فارغ ہو گئی۔ اور آپ صلی اللہ علیہ وسلم نے لوگوں کو کوچ کرنے کا حکم دیا اور کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیت اللہ میں تشریف لائے، اس کا طواف کیا پھر روانہ ہو گئے۔"}],[2006,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ آخری دن کی روانگی میں نکلی تو آپ وادی محصب میں اترے، (ابوداؤد کہتے ہیں: ابن بشار نے اس حدیث میں ان کے تنعیم بھیجے جانے کا واقعہ ذکر نہیں کیا) پھر میں صبح کو آپ صلی اللہ علیہ وسلم کے پاس آئی، تو آپ نے لوگوں میں روانگی کی منادی کرا دی، پھر خود روانہ ہوئے تو فجر سے پہلے بیت اللہ سے گزرے اور نکلتے وقت اس کا طواف کیا، پھر مدینہ کا رخ کر کے چل پڑے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا ہے بیان کیا کہ میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ منٰی سے آخری دن میں نکلی تو آپ صلی اللہ علیہ وسلم نے وادی محصب میں پڑاؤ کیا۔ (مکہ اور منٰی کے درمیان مقبرۃ المعلاۃ سے منٰی کی طرف جانے والے راستے کا نام ابطح اور محصب ہے۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن بشار نے اس حدیث میں ان کو تنعیم کی طرف روانہ کرنے کا ذکر نہیں کیا۔ (سیدہ عائشہ رضی اللہ عنہا ا) کہتی ہیں چنانچہ میں سحر کے وقت (عمرے سے فارغ ہو کر) آپ کے پاس پہنچی تو آپ نے صحابہ کو کوچ کا حکم دیا اور خود سوار ہوئے اور نماز فجر سے پہلے بیت اللہ میں آئے، طواف کیا اور پھر مدینہ کی راہ کی طرف چل نکلے۔"}],[2007,"عبدالرحمٰن بن طارق اپنی والدہ سے روایت کرتے ہیں، وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب یعلی کے گھر کی جگہ سے آگے بڑھتے (اس جگہ کا نام عبیداللہ بھول گئے) تو بیت اللہ کی جانب رخ کرتے اور دعا مانگتے ۱؎۔\n§وضاحت\n۱؎ : نہ تو یہ حدیث صحیح ہے اور نہ ہی باب سے اس کا کوئی تعلق ہے۔","ضعیف",{"u2":"عبدالرحمٰن بن طارق اپنی والدہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب یعلیٰ کے گھر سے آگے بڑھتے تو بیت اللہ کی طرف رخ کرتے اور دعا فرماتے۔ عبیداللہ وہ جگہ بھول گئے تھے۔"}],[2008,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم محصب میں صرف اس لیے اترے تاکہ آپ کے (مکہ سے) نکلنے میں آسانی ہو، یہ کوئی سنت نہیں، لہٰذا جو چاہے وہاں اترے اور جو چاہے نہ اترے ۱؎۔\n§وضاحت\n۱؎ : محصب، ابطح، بطحاء، خیف کنانہ سب ہم معنی ہیں اور اس سے مراد مکہ اور منٰی کے درمیان کا علاقہ ہے جو منٰی سے زیادۃ قریب ہے۔ محصب میں نزول و اقامت مناسک حج میں سے نہیں ، رسول اکرم صلی اللہ علیہ وسلم زوال کے بعد آرام فرمانے کے لئے یہاں اقامت کی تھی اور یہاں پر عصر، ظہر و عصر اور مغرب و عشاء ادا فرمائیں اور چودہویں رات گزاری، لیکن چونکہ آپ صلی اللہ علیہ وسلم نے یہاں نزول فرمایا، تو آپ کی اتباع میں یہاں کی اقامت مستحب ہے، خلفاء نے آپ کے بعد اس پر عمل کیا ہے، امام شافعی ، امام مالک اور جمہور اہل علم نے رسول اکرم صلی اللہ علیہ وسلم اور خلفائے راشدین رضی اللہ عنہم کی اقتداء میں اسے مستحب قرار دیا ہے، اور اگر کسی نے وہاں نزول نہ کیا تو بالاجماع کوئی حرج کی بات نہیں، نیز ظہر، عصر اور مغرب و عشاء کی نماز پڑھنی ، نیز رات کا ایک حصہ یا پوری رات سونا رسول اکرم صلی اللہ علیہ وسلم کی اقتدا میں مستحب ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وادی محصب میں اس لیے اترے تھے تاکہ آپ صلی اللہ علیہ وسلم کو (مکہ سے) نکلنے میں آسانی رہے۔ یہ کوئی مشروع سنت نہیں ہے۔ جو چاہے یہاں اتر جائے اور جو چاہے نہ اترے۔","f2":"چونکہ نبی کریم صلی اللہ علیہ وسلم یہاں اُترے تھے۔اور بعد ازاں خلفائے راشدین رضوان اللہ عنہم اجمعین بھی یہاں اترتے رہے ہیں۔اس لئے اس کے مستحب ہونے میں کوئی شبہ نہیں۔حضرت عائشہ رضی اللہ تعالیٰ عنہا اور حضرت ابن عباس رضی اللہ تعالیٰ عنہ اسے ایک عام منزل سمجھتے تھے۔"}],[2009,"سلیمان بن یسار کہتے ہیں کہ ابورافع رضی اللہ عنہ کہتے ہیں: مجھے آپ (رسول اللہ صلی اللہ علیہ وسلم) نے یہ حکم نہیں دیا تھا کہ میں وہاں(محصب میں) اتروں، میں نے وہاں آپ صلی اللہ علیہ وسلم کا خیمہ نصب کیا تھا، آپ وہاں اترے تھے۔ مسدد کی روایت میں ہے، وہ(ابورافع) نبی اکرم صلی اللہ علیہ وسلم کے اسباب کے محافظ تھے اور عثمان رضی اللہ عنہ کی روایت میں «يعني في الأبطح» کا اضافہ ہے(مطلب یہ ہے کہ وہ ابطح میں محافظ تھے) ۔","صحیح",{"u2":"سیدنا ابورافع (مولیٰ رسول اللہ صلی اللہ علیہ وسلم) کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے یہ حکم نہیں دیا تھا کہ میں آپ صلی اللہ علیہ وسلم کے پڑاؤ کا یہاں انتظام کروں لیکن میں نے (اپنے طور پر) یہاں آپ صلی اللہ علیہ وسلم کا خیمہ لگا دیا تھا تو آپ صلی اللہ علیہ وسلم یہاں اتر پڑے تھے۔ جناب مسدد نے کہا کہ ابورافع رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کے سامان سفر کے نگران اور منتظم تھے۔ عثمان بن ابی شیبہ نے اپنی روایت میں «في الأبطح» کا لفظ ذکر کیا ہے۔"}],[2010,"اسامہ بن زید رضی اللہ عنہما کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! آپ کل حج میں کہاں اتریں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا عقیل نے کوئی گھر ہمارے لیے (مکہ میں) چھوڑا ہے؟\"، اس کے بعد آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہم خیف بنو کنانہ میں اتریں گے جہاں قریش نے کفر پر عہد کیا تھا (یعنی وادی محصب میں) ۱؎\"، اور وہ یہ کہ بنو کنانہ نے قریش سے بنی ہاشم کے خلاف قسم کھائی تھی کہ وہ ان سے نہ شادی بیاہ کریں گے، نہ خرید و فروخت، اور نہ انہیں پناہ دیں گے۔ زہری کہتے ہیں: خیف وادی کا نام ہے۔\n§وضاحت\n۱؎ : نبی اکرم صلی اللہ علیہ وسلم اس وادی میں اللہ کا شکر ادا کرنے کے لئے اترے کہ جہاں پر کفر کا دور دورہ تھا، اب وہاں اسلام کا غلبہ ہو گیا۔","صحیح",{"u2":"سیدنا اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ حج کے موقع پر میں نے پوچھا: اے اللہ کے رسول! آپ کل کہاں قیام فرمائیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بھلا عقیل نے ہمارے لیے کوئی منزل رہنے بھی دی ہے؟ “ پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” ہم خیف بنی کنانہ میں قیام کریں گے، جہاں قریشیوں نے کفر پر آپس میں معاہدہ کیا تھا۔ “ یعنی وادی محصب میں۔ اور اس کی تفصیل یہ ہے کہ بنی کنانہ نے قریشیوں کے ساتھ بنی ہاشم کے خلاف یہ قسمیں اٹھائی تھیں کہ ان سے نکاح شادی کریں گے نہ خرید و فروخت اور نہ انہیں کوئی جگہ دیں گے۔ زہری نے کہا ” خیف “ وادی ہے۔","f2":"-1رسول اللہ صلی اللہ علیہ وسلم نے اپنے والد کاترکہ ہجرت کی بنا پر چھوڑ دیا تھا۔اور ابو طالب کی جائیداد طالب اور عقیل کو ملی تھی۔حضرت جعفر رضی اللہ تعالیٰ عنہ اور حضرت علی رضی اللہ تعالیٰ عنہ بوجہ مسلمان ہونے کے اس کے وارث نہ ہوئے تھے۔اور پھر طالب بد ر کے موقع پرلا پتہ ہوگیا۔تو عقیل نے تمام گھر پر قبضہ کرلیا۔2۔وادی محصب(ابطح) میں اترنا اظہار تشکر کے طور پر تھا۔ کہ یہیں قریش نے نبی کریم صلی اللہ علیہ وسلم اور مسلمانوں کے بایئکاٹ کا فیصلہ کیا تھا۔آج اللہ نے اس کے آثار مٹا کر نتیجہ الٹ دیا تھا۔ یعنی اللہ نے ان مقامات کو اسلام کا مرکز بنادیا تھا۔اور مسلمان ان پر غالب آگئے تھے۔اسی لئے یہاں شکرانے کے طو ر پر اُترنا مستحب گردانا جاتا ہے۔"}],[2011,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جب منی سے کوچ کرنے کا قصد کیا تو فرمایا: \"ہم وہاں کل اتریں گے\"۔ پھر راوی نے ویسا ہی بیان کیا، اس روایت میں نہ تو حدیث کے شروع کے الفاظ ہیں، اور نہ ہی یہ ذکر ہے کہ خیف وادی کا نام ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب منٰی سے روانگی کا ارادہ کیا تو فرمایا ” ہم کل (خیف بنی کنانہ میں) اتریں گے۔ “ اور مذکورہ بالا کی مانند ذکر کیا۔ مگر (اوزاعی نے) روایت کا پہلا حصہ (اسامہ کا سوال جواب) ذکر نہیں کیا اور نہ ” الخیف “ کا کہ یہ وادی ہے۔"}],[2012,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما بطحاء میں نیند کی ایک جھپکی لے لیتے پھر مکہ میں داخل ہوتے اور بتاتے کہ رسول اللہ صلی اللہ علیہ وسلم بھی ایسا ہی کرتے تھے۔","صحیح",{"u2":"جناب نافع رضی اللہ عنہ کہتے ہیں کہ(منٰی سے واپسی پر) سیدنا ابن عمر رضی اللہ عنہ بطحاء (ابطح، محصب) میں ذرا دیر سوتے، پھر مکہ میں داخل ہوتے۔ اور کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم ایسے ہی کیا کرتے تھے۔ (یعنی طواف وداع کیا کرتے تھے)۔"}],[2013,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ظہر، عصر، مغرب اور عشاء بطحاء میں پڑھی پھر ایک نیند سوئے، پھر مکہ میں داخل ہوئے اور ابن عمر رضی اللہ عنہما بھی ایسا ہی کرتے تھے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے بطحاء میں ظہر، عصر، مغرب اور عشاء کی نمازیں پڑھیں، پھر کچھ دیر سوئے، پھر مکہ میں داخل ہوئے۔ اور ابن عمر رضی اللہ عنہ ایسے ہی کیا کرتے تھے۔","f2":"ایام تشریق میں رمی جمرات زوال کے بعد ہوتی ہے۔آخری دن نبی کریم صلی اللہ علیہ وسلم زوال ہوتے ہی منیٰ سے روانہ ہوگئے رمی کی اور پھر بطحا میں آکر نماز ظہر پڑھی۔"}],[2014,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع میں منی میں ٹھہرے، لوگ آپ سے سوالات کر رہے تھے، آپ صلی اللہ علیہ وسلم کے پاس ایک شخص آیا اور بولا: اللہ کے رسول! مجھے معلوم نہ تھا میں نے ذبح کرنے سے پہلے سر منڈا لیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ذبح کر لو کوئی حرج نہیں\"، پھر ایک اور شخص آیا اور بولا: اللہ کے رسول! مجھے معلوم نہ تھا میں نے رمی کرنے سے پہلے نحر کر لیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"رمی کر لو، کوئی حرج نہیں\"، اس طرح جتنی چیزوں کے بارے میں آپ صلی اللہ علیہ وسلم سے پوچھا گیا جو آگے پیچھے ہو گئیں تھیں آپ نے فرمایا: \"کر ڈالو، کوئی حرج نہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو بن العاص رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجتہ الوداع کے موقع پر منٰی میں وقوف کیا تو لوگ آپ صلی اللہ علیہ وسلم سے مسائل دریافت کرتے تھے۔ ایک شخص آیا اور کہنے لگا: اے اللہ کے رسول! مجھے معلوم نہیں ہو سکا اور میں نے ذبح کرنے سے پہلے اپنے بال منڈوا لیے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ذبح کر لو، کوئی حرج نہیں۔ “ ایک دوسرا آیا اور بولا، اے اللہ کے رسول! مجھے معلوم نہیں ہو سکا اور میں نے رمی کرنے سے پہلے قربانی کر لی؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” رمی کر لو، کوئی حرج نہیں۔ “ کہتے ہیں کہ اس دن آپ صلی اللہ علیہ وسلم سے جو سوال بھی ہوا جس میں کوئی تقدیم تاخیر ہوئی تھی۔ آپ صلی اللہ علیہ وسلم نے یہی فرمایا ” کر لو، کوئی حرج نہیں۔ “"}],[2015,"اسامہ بن شریک رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ حج کے لیے نکلا، لوگ آپ کے پاس آتے تھے جب کوئی کہتا: اللہ کے رسول! میں نے طواف سے پہلے سعی کر لی یا میں نے ایک چیز کو مقدم کر دیا یا مؤخر کر دیا تو آپ صلی اللہ علیہ وسلم فرماتے: \"کوئی حرج نہیں، کوئی حرج نہیں، حرج صرف اس پر ہے جس نے کسی مسلمان کی جان یا عزت و آبرو پامال کی اور وہ ظالم ہو، ایسا ہی شخص ہے جو حرج میں پڑ گیا اور ہلاک ہوا\"۔","صحیح",{"u2":"سیدنا اسامہ بن شریک رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ حج کے لیے روانہ ہوا۔ لوگ آپ صلی اللہ علیہ وسلم کے پاس آتے تھے، تو جس نے کہا: اے اللہ کے رسول! میں نے طواف سے پہلے سعی کر لی ہے یا کوئی کام پہلے کر لیا ہے یا کوئی مؤخر کر دیا ہے۔ تو آپ صلی اللہ علیہ وسلم فرماتے تھے ” کوئی حرج نہیں، کوئی حرج نہیں۔ مگر جو کوئی ظلم کرتے ہوئے کسی مسلمان کی عزت کو کاٹے (غیبت کرے یا طعن و تشنیع وغیرہ) تو وہ حرج میں پڑا اور ہلاک ہوا۔ “"}],[2016,"مطلب بن ابی وداعہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو باب بنی سہم کے پاس نماز پڑھتے دیکھا، لوگ آپ صلی اللہ علیہ وسلم کے سامنے سے گزر رہے تھے بیچ میں کوئی سترہ نہ تھا ۱؎۔ سفیان کے الفاظ یوں ہیں: ان کے اور کعبہ کے درمیان کوئی سترہ نہ تھا۔ سفیان کہتے ہیں: ابن جریج نے ان کے بارے میں ہمیں بتایا کہ کثیر نے اپنے والد سے روایت کی ہے، وہ کہتے ہیں: میں نے ان سے پوچھا تو انہوں نے جواب دیا میں نے اسے اپنے والد سے نہیں سنا، بلکہ گھر کے کسی فرد سے سنا اور انہوں نے میرے دادا سے روایت کی ہے۔\n§وضاحت\n۱؎ : یہ حدیث ضعیف ہے، اس لئے اس سے استدلال نہیں کیا جا سکتا، سترہ کے بارے میں وارد تمام احادیث مطلق اور عام ہیں، ان میں کسی جگہ کی کوئی قید نہیں خواہ صحراء ہو ،یا مسجد حتی کہ حرمین شریفین کی مساجد بھی اس حکم سے مستثنی نہیں ہیں، اس لئے ہر جگہ سترہ کا اہتمام کرنا چاہئے۔","ضعیف",{"u2":"کثیر بن کثیر کے دادا (سیدنا مطلب بن ابی وداعہ رضی اللہ عنہ) سے روایت ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو (مسجد الحرام میں) باب بنی سہم کے پاس نماز پڑھتے دیکھا جب کہ لوگ آپ صلی اللہ علیہ وسلم کے آگے سے گزر رہے تھے اور ان کے درمیان (رسول اللہ صلی اللہ علیہ وسلم اور کعبہ کے مابین) سترہ نہیں تھا۔ سفیان نے بصراحت کہا «ليس بينه وبين الكعبة سترة ***» سفیان کہتے ہیں کہ ابن جریج نے اس کی سند میں یوں بیان کیا تھا «أخبرنا كثير، عن أبيه» یعنی کثیر نے اپنے والد سے بیان کیا، پھر میں نے ان سے (براہ راست) پوچھا تو کہا، میں نے یہ حدیث اپنے والد سے نہیں سنی بلکہ گھر کے کسی دوسرے فرد سے سنی تھی اور اس نے میرے دادا سے روایت کی ہے۔","f2":"یہ حدیث صحیح نہیں ہے۔امام بخاری رحمۃ اللہ علیہ نے الجامع الصحیح میں (کتاب الصلواۃ باب السترہ بمکۃ حدیث 501) اور اس کے ضمن میں حضرت ابو حجیفہ رضی اللہ تعالیٰ عنہ کی صریح حدیث سے ثابت کیا ہے۔کہ سترے کے مسئلے میں مکہ اور غیر مکہ سبھی برابر ہیں۔ امام بخاری رحمۃ اللہ علیہ کا اشارہ ہے کہ مصنف عبدا لرزاق میں بابلايقطع الصلاة بمكة شي کی حدیث صحیح نہیں۔اور وہ یہی ہے جو امام ابودائود رحمۃ اللہ علیہ نے زکر کی ہے۔(عون المعبود) اس لئے مسجد نبوی صلی اللہ علیہ وسلم او ر مسجد حرام میں بھی ممکن حد تک سترے کا اہتمام کرنا چاہیے۔لوگوں کے عام تساہل اور تغافل نے وہاں اس مسئلے کی اہمیت کو ختم کردیا ہے۔جو یکسر غلط ہے۔"}],[2017,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب اللہ تعالی نے رسول اللہ صلی اللہ علیہ وسلم کو مکہ فتح کرا دیا، تو آپ لوگوں میں کھڑے ہوئے، اللہ کی حمد و ثنا بیان کی پھر فرمایا: \"اللہ نے ہی مکہ سے ہاتھیوں کو روکا، اور اس پر اپنے رسول اور مومنین کا اقتدار قائم کیا، میرے لیے دن کی صرف ایک گھڑی حلال کی گئی اور پھر اب قیامت تک کے لیے حرام کر دی گئی، نہ وہاں (مکہ) کا درخت کاٹا جائے، نہ اس کا شکار بدکایا جائے، اور نہ وہاں کا لقطہٰ (پڑی ہوئی چیز) کسی کے لیے حلال ہے، بجز اس کے جو اس کی تشہیر کرے\"، اتنے میں عباس رضی اللہ عنہ نے کہا: اللہ کے رسول! سوائے اذخر کے ۱؎ (یعنی اس کا کاٹنا درست ہونا چاہیئے) اس لیے کہ وہ ہماری قبروں اور گھروں میں استعمال ہوتی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سوائے اذخر کے\"۔ ابوداؤد کہتے ہیں: ابن مصفٰی نے ولید سے اتنا اضافہ کیا ہے: تو اہل یمن کے ایک شخص ابوشاہ کھڑے ہوئے اور عرض کیا: اللہ کے رسول! مجھے لکھ کر دے دیجئیے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابو شاہ کو لکھ کر دے دو\"، (ولید کہتے ہیں) میں نے اوزاعی سے پوچھا: «اكتبوا لأبي شاه» سے کیا مراد ہے، وہ بولے: یہی خطبہ ہے جو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔\n§وضاحت\n۱؎ : یہ ایک خوشبو دار گھاس ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ اللہ تعالیٰ نے جب اپنے رسول اللہ صلی اللہ علیہ وسلم کے لیے مکہ فتح کرا دیا تو آپ صلی اللہ علیہ وسلم ان (اہل مکہ) میں کھڑے ہوئے، اللہ تعالیٰ کی حمد و ثنا بیان کی پھر فرمایا ” بلاشبہ اللہ تعالیٰ نے مکہ سے ہاتھی کو روک لیا تھا مگر اپنے رسول اور مومنین کو اس پر غالب فر دیا ہے۔ اور یہ شہر میرے لیے دن کے ایک حصے میں (قتال کے لیے) حلال کیا گیا ہے۔ پھر اس کے بعد قیامت تک کے لیے حرام ہے۔ اس کے درخت نہ کاٹے جائیں، اس کا شکار نہ دوڑایا جائے اور نہ اس کی گری پڑی چیز کو اٹھانا ہے، الا یہ کہ کوئی اس کا اعلان کرے (تو اٹھا لے)۔ “ سیدنا ابن عباس رضی اللہ عنہ نے کہا: اے اللہ کے رسول! مگر اذخر گھاس (کی اجازت ہو) یہ ہماری قبروں اور گھروں میں استعمال ہوتی ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مگر اذخر “۔ (اس کا کاٹنا مباح ہے) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن المصفی نے ولید سے مزید بیان کیا کہ پھر ابوشاہ رضی اللہ عنہ کھڑے ہوئے، جو اہل یمن میں سے تھے، اور کہا: اے اللہ کے رسول! مجھے لکھوا دیجیئے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ابوشاہ کے لیے لکھ دو “۔ (ولید کہتے ہیں کہ) میں نے امام اوزاعی رضی اللہ عنہ سے دریافت کیا کہ ” ابوشاہ کے لیے لکھ دو “ اس سے کیا مراد ہے؟ انہوں نے کہا: یہی خطبہ جو انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا۔","f2":"1-مکہ مکرمہ کو قوت اور زور سے فتح کیا گیا تھا۔2۔حرم میں پناہ لینے والا جب تک حرم میں ہے۔اسے کچھ نہیں کہاجائےگا۔3۔احادیث نبویہ کی کتابت وتدوین اگرچہ عارضی طور پر عمومی حکومت کے تحت ممنوع تھی۔مگر بعض افراد کو ان کے لکھنے کی رخصت بھی دی گئی تھی۔ جیسے کہ حضرت عبد اللہ بن عمرو ابن العاص رضی اللہ تعالیٰ عنہ حضرت علی رضی اللہ تعالیٰ عنہ کا صحیفہ زکواۃ کی تفصیلات اور حضرت ابو شاہ رضی اللہ تعالیٰ عنہ کو یہ خطبہ لکھوا کر عنایت فرمایا گیا۔"}],[2018,"اس سند سے بھی ابن عباس رضی اللہ عنہما سے یہی واقعہ مروی ہے اس میں اتنا زائد ہے «لا يختلى خلاها» (اور اس کے پودے نہ کاٹے جائیں) ۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے اس قصہ میں مروی ہے&lsquo;فرمایا:ولا يُخْتَلَى خَلَاهَا) یعنی اس کی گھاس نہ کاٹی جائے","f2":"حدود حرم کے درخت یا گھاس کا کاٹنامنع ہے۔ جانوروں کے چرانے میں کوئی حرج نہیں ہے۔"}],[2019,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے عرض کیا: اللہ کے رسول! کیا ہم آپ کے لیے منی میں ایک گھر یا عمارت نہ بنا دیں جو آپ کو دھوپ سے سایہ دے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں یہ (منی) اس کی جائے قیام ہے جو یہاں پہلے پہنچ جائے۱؎\"۔\n§وضاحت\n۱؎ : یعنی منی کا میدان وقف ہے حاجیوں کے لئے وہ کسی کی خاص ملکیت نہیں ہے اگر کوئی وہاں پہلے پہنچے اور کسی جگہ اتر جائے تو دوسرا اس کو اٹھا نہیں سکتا چونکہ مکان بنانے میں ایک جگہ پر اپنا قبضہ اور حق جما لینا ہے اس لئے آپ نے اس سے منع فرمایا۔","ضعیف",{"u2":"سیدہ عائشہ رضی اللہ عنہا سے مروی ہے‘کہتی ہیں کہ میں نے کہا: اے اللہ کے رسول! کیا ہم آپ کے لیے منیٰ میں گھر نہ بنا دیں۔یا کہا کوئی عمارت نہ بنا دیں جو آ پکو دھوپ سے بچائے؟ تو آ پ صلی اللہ علیہ وسلم نے فرمایا:’’نہیں‘یہ ٹھہرنے کا مقام ہے اور ہر شخص کے لیے ہے جو پہلے آجائے"}],[2020,"یعلی بن امیہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حرم میں غلہ روک کر رکھنا اس میں الحاد (کج روی)ہے\"۔","ضعیف",{"u2":"سیدنا یعلیٰ بن امیہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” حرم میں غلے کا ذخیرہ کرنا (لوگوں سے روک رکھنا) الحاد (بے دینی) ہے۔ “","f2":"حدیث اگرچہ ضعیف ہے۔مگر دوسری روایات کی رو سے زخیرہ اندوزی جبکہ لوگ محتاج اور ضرورت مند ہوں۔کبائر میں سے ہے۔بالخصوص حرم میں اور بھی بد تر عمل ہے۔ (وَمَن يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُّذِقْهُ مِنْ عَذَابٍ أَلِيمٍ)(الحج۔25)"}],[2021,"بکر بن عبداللہ کہتے ہیں کہ ابن عباس رضی اللہ عنہما سے ایک شخص نے پوچھا: کیا وجہ ہے کہ اس گھر کے لوگ نبیذ (کھجور کا شربت)پلاتے ہیں اور آپ کے چچا کے بیٹے (قریش) دودھ، شہد اور ستو پلاتے ہیں؟ کیا یہ لوگ بخیل یا محتاج ہیں؟ ابن عباس نے کہا: نہ ہم بخیل ہیں اور نہ محتاج، بلکہ رسول اللہ صلی اللہ علیہ وسلم ایک روز اپنی سواری پر بیٹھ کر آئے، آپ صلی اللہ علیہ وسلم کے پیچھے اسامہ بن زید رضی اللہ عنہما تھے، آپ صلی اللہ علیہ وسلم نے پینے کو کچھ مانگا تو نبیذ پیش کیا گیا، آپ نے اس میں سے پیا اور باقی ماندہ اسامہ رضی اللہ عنہ کو دے دیا، تو انہوں نے بھی اس میں سے پیا، اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے اچھا کیا اور خوب کیا ایسے ہی کیا کرو\"، تو ہم اسی کو اختیار کئے ہوئے ہیں جسے رسول اللہ صلی اللہ علیہ وسلم نے کہا تھا، اسے ہم بدلنا نہیں چاہتے۔","صحیح",{"u2":"بکر بن عبداللہ سے روایت ہے کہ ایک شخص نے سیدنا ابن عباس رضی اللہ عنہ سے کہا: اس گھر کے خدام کو کیا ہوا ہے کہ یہ لوگ نبیذ پلاتے ہیں (کھجور یا کشمش کا شربت) جب کہ ان کے چچا زاد (قریش) دودھ، شہد اور ستو پلاتے ہیں؟ کیا یہ بخیل ہیں یا محتاج؟ تو ابن عباس رضی اللہ عنہ نے جواب دیا۔ ہم بخیل ہیں نہ محتاج۔ دراصل جب رسول اللہ صلی اللہ علیہ وسلم اپنی سواری پر تشریف لائے تھے اور ان کے پیچھے سیدنا اسامہ بن زید رضی اللہ عنہ بیٹھے ہوئے تھے تو آپ صلی اللہ علیہ وسلم نے پینے کو کچھ طلب کیا تو انہیں نبیذ پیش کی گئی تھی۔ آپ نے اس میں سے پی اور باقی اسامہ رضی اللہ عنہ کو دے دی، انہوں نے بھی اس سے پی۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم نے بہت خوب کیا، بہت اچھا کیا، سو ایسے ہی کیا کرو۔ “ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے جو فر دیا ہے اس کو ہم بدلنا نہیں چاہتے۔","f2":"دین و ایمان کا یہی تقاضا ہے۔اور ایک مومن سے اسی کا مطالبہ ہے۔کہ فرمان رسول صلی اللہ علیہ وسلم کو ہر کسی کے قول وفعل اوررائے سے مقدم رکھا جائے۔جیسا کہ صحابہ کرام رضوان اللہ عنہم اجمعین کیا کرتے تھے۔"}],[2022,"عبدالرحمٰن بن حمید سے روایت ہے کہ انہوں نے عمر بن عبدالعزیز کو سائب بن یزید سے پوچھتے سنا: کیا آپ نے مکہ میں رہائش اختیار کرنے کے سلسلے میں کچھ سنا ہے؟ انہوں نے کہا: مجھے ابن حضرمی نے خبر دی ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"مہاجرین کے لیے حج کے احکام سے فراغت کے بعد تین دن تک مکہ میں ٹھہرنے کی اجازت ہے ۱؎\"۔\n§وضاحت\n۱؎ : تاکہ وہ اس دوران اپنی ضرورتیں پوری کر لیں اس سے زیادہ انہیں رکنے کی اجازت نہیں کیونکہ وہ اللہ کے لئے اس شہر کو خیرباد کہہ چکے ہیں۔","صحیح",{"u2":"سیدنا عمر بن عبدالعزیز رضی اللہ عنہ نے سائب بن یزید سے پوچھا: کیا آپ نے مکہ میں اقامت کے بارے میں کچھ سنا ہے؟ تو انہوں نے کہا کہ سیدنا علاء بن حضرمی رضی اللہ عنہ نے مجھے بتایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا، آپ صلی اللہ علیہ وسلم فرماتے تھے &rdquo; مہاجر لوگ طواف صدر (افاضہ) کے بعد تین دن تک رک سکتے ہیں۔ &ldquo;","f2":"1۔تکمیل حج کے بعد مہاجرین مدینہ کے لئے بالخصوص پابندی تھی کہ جس شہر کو انہوں نے اللہ کی رضا کے لئے چھوڑ دیا ہے وہاں کسی طرح اقامت نہ کریں تاکہ ہجرت کے اجروثواب میں کمی نہ ہو۔2۔اامام شافعی رحمۃ اللہ علیہ اسی حدیث سے قیاس فرماتے ہیں۔کہ مسافر اگر کہیں تین دن سے زیادہ اقامت کی نیت کرلے تو وہاں کا مقیم سمجھا جائے گا۔اس لئے اسے نماز پوری پڑھنی چاہیے۔(کتاب الام للشافعی رحمۃ اللہ علیہ) گویا اس فرمان نبوی صلی اللہ علیہ وسلم سے مدت سفر کی تعین پر بھی استدلال کیا گیا ہے۔جس کی تایئد نبی کریم صلی اللہ علیہ وسلم کےعمل سے بھی ہوتی ہے۔(تفصیل کےلئے دیکھئے۔ مسنون نماز ازحافظ صلاح الدین یوسف)"}],[2023,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم، اسامہ بن زید، عثمان بن طلحہ حجبی اور بلال رضی اللہ عنہم کعبہ میں داخل ہوئے، پھر ان لوگوں نے اسے بند کر لیا، اور اس میں رکے رہے، عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: میں نے بلال رضی اللہ عنہ سے جب وہ باہر آئے تو پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا کیا؟ وہ بولے: آپ نے ایک ستون اپنے بائیں طرف اور دو ستون دائیں طرف اور تین ستون اپنے پیچھے کیا (اس وقت بیت اللہ چھ ستونوں پر قائم تھا) پھر آپ نے نماز پڑھی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم، اسامہ بن زید، عثمان بن طلحہ الحجبی اور بلال رضی اللہ عنہ کعبہ کے اندر داخل ہوئے اور بلال رضی اللہ عنہ نے دروازہ بند کر دیا۔ پس آپ صلی اللہ علیہ وسلم (کچھ دیر) اندر رہے۔ عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں کہ میں نے بلال رضی اللہ عنہ سے ان کے نکلنے پر پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے اندر کیا کیا تھا؟ انہوں نے بتایا کہ آپ صلی اللہ علیہ وسلم نے ایک ستون اپنی بائیں جانب کیا اور دو ستون دائیں جانب اور تین ستون اپنے پیچھے اور پھر نماز پڑھی۔ اور بیت اللہ ان دنوں چھ ستونوں پر قائم تھا۔"}],[2024,"اس سند سے بھی مالک سے یہی حدیث مروی ہے اس میں ستونوں کا ذکر نہیں، البتہ اتنا اضافہ ہے \"پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھی، آپ کے اور قبلے کے درمیان تین ہاتھ کا فاصلہ تھا\"۔","صحیح",{"u2":"امام مالک رضی اللہ عنہ نے یہ حدیث روایت کی مگر ستونوں کا ذکر نہیں کیا، کہا: پھر آپ صلی اللہ علیہ وسلم نے نماز پڑھی۔ آپ صلی اللہ علیہ وسلم اور قبلہ کی دیوار کے درمیان تین ہاتھ کا فاصلہ تھا۔","f2":"معلوم ہوا نمازی اور سترے کے درمیان کم از کم تین ہاتھ کا فاصلہ ہونا چاہیے۔"}],[2025,"عبداللہ بن عمر رضی اللہ عنہما نے نبی اکرم صلی اللہ علیہ وسلم سے قعنبی کی حدیث کے ہم مثل روایت کی ہے اس میں اس طرح ہے کہ ابن عمر رضی اللہ عنہما کہتے ہیں: میں ان سے یہ پوچھنا بھول گیا کہ آپ نے کتنی رکعتیں پڑھیں؟ ۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں اور قعنبی کی (مذکورہ بالا) روایت کی مانند بیان کیا۔ کہا: میں یہ پوچھنا بھول گیا کہ آپ صلی اللہ علیہ وسلم نے کتنی رکعتیں پڑھیں؟"}],[2026,"عبدالرحمٰن بن صفوان کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہما سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم جب کعبہ میں داخل ہوئے تو آپ نے کیا کیا؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھیں۔","صحیح",{"u2":"عبدالرحمٰن بن صفوان کہتے ہیں کہ میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم جب کعبہ میں داخل ہوئے تو کیا کیا تھا؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم نے دو رکعتیں پڑھی تھیں۔","f2":"جسے کعبہ کےاندر جانے کا موقع میسر آجائے۔اس کے لئے وہاں دو رکعت پڑھنامستحب ہے۔اور جسے موقع نہ ملے۔وہ حطیم کے اندر پڑھ لے۔وہ بھی کعبہ ہی کا حصہ ہے۔اور شاید اللہ عز شانہ کی یہی حکمت تھی کہ ابتدا سے یہ حصہ کھلا رہ گیا اور تعمیر نہ ہوسکا۔اس طرح ہر مسلمان کو کعبے کے اندر نماز پڑھنے کی سہولت ہر وقت میسر رہتی ہے۔والحمد للہ علی ذلک"}],[2027,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب مکہ آئے تو آپ نے کعبہ میں داخل ہونے سے انکار کیا کیونکہ اس میں بت رکھے ہوئے تھے، آپ صلی اللہ علیہ وسلم نے حکم دیا تو وہ نکال دیئے گئے، اس میں ابراہیم اور اسماعیل علیہما السلام کی تصویریں بھی تھیں، وہ اپنے ہاتھوں میں فال نکالنے کے تیر لیے ہوئے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ انہیں ہلاک کرے، اللہ کی قسم انہیں اچھی طرح معلوم ہے کہ ان دونوں (ابراہیم اور اسماعیل) نے کبھی بھی فال نہیں نکالا\"، وہ کہتے ہیں: پھر آپ صلی اللہ علیہ وسلم بیت اللہ میں داخل ہوئے تو اس کے گوشوں اور کونوں میں تکبیرات بلند کیں، پھر بغیر نماز پڑھے نکل آئے۔\n§وضاحت\n۱؎ : فال کے ان تیروں پر «’’افعل‘‘،’’لا تفعل‘‘،’’لا شيء‘‘» لکھا ہوتا تھا، ان کی عادت تھی جب وہ سفر پر نکلتے تو اس کو ایک تھیلی میں ڈال کر اس میں سے ایک کو نکالتے، اگر حسن اتفاق سے اس تیر پر «افعل» لکھا ہوتا تو سفر پر نکلتے، اور «لا تفعل»لکھا ہوتا تو سفر کو ملتوی کر دیتے اور اگر «لا شيء» لکھا رہتا تو پھر دوبارہ سب کو ڈال کر نکالتے، یہاں تک کہ «افعل» یا «لا تفعل»نکل آئے، رہی یہ بات کہ ’’ آپ نے کعبہ میں نماز نہیں پڑھی‘‘ تو یہ ابن عباس رضی اللہ عنہما نے اپنے علم کی بنیاد پر کہا ہے، ترجیح بلال رضی اللہ عنہ کے بیان کو ہے جنہوں نے قریب سے دیکھا تھا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم جب مکہ میں تشریف لائے تو کعبہ کے اندر جانے سے انکار فر دیا کیونکہ اس کے اندر بت رکھے ہوئے تھے۔ چنانچہ آپ صلی اللہ علیہ وسلم نے حکم دیا اور انہیں باہر نکال دیا گیا۔ ان میں سیدنا ابراہیم علیہ السلام اور سیدنا اسمعیل علیہ السلام کی تصویریں بھی تھیں جن کے ہاتھوں میں پانسے (قسمت معلوم کرنے کے تیر) دکھلائے گئے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ ان پر لعنت کرے، قسم اللہ کی! انہیں خوب علم تھا کہ ان حضرات نے کبھی بھی ان سے پانسے نہیں ڈالے تھے۔ “ چنانچہ اس کے بعد آپ صلی اللہ علیہ وسلم کعبہ میں داخل ہوئے اور اس کے اطراف اور کونوں میں تکبیریں کہیں۔ پھر آپ صلی اللہ علیہ وسلم نکل آئے اور اندر نماز نہیں پڑھی۔","f2":"1۔ پانسے کے تیر یوں تھے کہ لکڑیاں سی ہوتیں۔اور ان میں سے کچھ پر لکھا ہوتا تھا۔(افعل)کام کرلو۔اور کچھ پر لکھا ہوا تھا۔(لاتفعل)مت کرو۔اورکچھ خالی ہوتی تھیں۔ لوگ کسی اہم سفر یا کام کے موقع پر مجاور کعبہ کے پاس آتے۔اور اس سے اپناکام نہ کرنے یا کرنے کے متعلق پوچھتے تو وہ ان لکڑیوں کوڈبے میں ڈال کرہلاتا اور کوئی ایک نکال کر جواب دیتا۔کہ کرو یا نہ کرو۔اگر خالی تیر نکلتا تودوباہ کرتا حتیٰ کہ کوئی جواب نکل آتا۔سورۃ المائدہ میں ہے۔ (وَأَن تَسْتَقْسِمُوا بِالْأَزْلَا)(المائدہ۔3) یہ بھی حرام ہے۔کہ پانسوں سے قسمت معلوم کرو۔دوسری جگہ فرمایا۔ (يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنصَابُ وَالْأَزْلَامُ رِجْسٌ مِّنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ)(المائدہ۔90) اے ایمان والو! شراب۔جوا۔بت۔پانسے یہ سب ناپاک شیطانی عمل ہیں۔ سو ان سے بچتے رہنا تاکہ نجات پائو 2۔کعبہ کے اندر نماز پڑھنا حضر ت بلال رضی اللہ تعالیٰ عنہ کے بیان سے ثابت ہے۔حضرت ابن عباس رضی اللہ تعالیٰ عنہ نبی کریم صلی اللہ علیہ وسلم کےساتھ نہیں تھے۔حضرت اسامہ رضی اللہ تعالیٰ عنہ کی ایک روایت کی بھی نفی ہے۔مگرحضرت بلال رضی اللہ تعالیٰ عنہ کے بیان میں اثبات ہے۔ اور حضرت اسامہ رضی اللہ تعالیٰ عنہ کی نفی کی توجیہ یہ ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو دعا تکبیر میں دیکھا تو خود بھی ایک طرف اسی عمل میں لگ گئے۔ جبکہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھنے لگے۔اور انہوں نے دھیان نہیں کیا۔جبکہ بلال رضی اللہ تعالیٰ عنہ نبی کریم صلی اللہ علیہ وسلم کے تمام اعمال کا جائزہ لیتے رہے نیز کمرے میں دروازہ بند ہونے کی وجہ سے اندھیرا بھی تھا تو اس لئے بھی صورت حال مخفی رہی۔واللہ اعلم۔"}],[2028,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میری خواہش تھی کہ میں بیت اللہ میں داخل ہو کر اس میں نماز پڑھوں، تو رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور مجھے حطیم میں داخل کر دیا، اور فرمایا: \"جب تم بیت اللہ میں داخل ہونا چاہو تو حطیم کے اندر نماز پڑھ لیا کرو کیونکہ یہ بھی بیت اللہ ہی کا ایک ٹکڑا ہے، تمہاری قوم کے لوگوں نے جب کعبہ تعمیر کیا تو اسی پر اکتفا کیا تو لوگوں نے اسے بیت اللہ سے خارج ہی کر دیا ۱؎\"۔\n§وضاحت\n۱؎ : حطیم کے حصہ کو عبداللہ بن زبیر رضی اللہ عنہما نے اپنے دور خلافت میں کعبے کے اندر شامل کر دیا تھا، لیکن حجاج بن یوسف نے جب ان پر چڑھائی کی اور کعبہ کی عمارت کو نقصان پہنچا تو اس نے پھر نئے سرے سے اس کی تعمیر کروائی اور حطیم کو چھوڑ دیا اور آج تک ویسے ہی ہے۔","حسن صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں چاہتی تھی کہ کعبہ کے اندر داخل ہوں اور اس میں نماز پڑھوں، تو رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا اور حجر (یعنی حطیم) میں داخل کر دیا اور فرمایا ” جب تم کعبہ میں داخل ہونا چاہو تو حجر میں نماز پڑھ لیا کرو، یہ بھی بیت اللہ ہی کا حصہ ہے۔ حقیقت یہ ہے کہ تیری قوم نے تعمیر کعبہ کے وقت اسی قدر پر اکتفا کیا اور اسے تعمیر سے خارج کر دیا تھا۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم کی عمر مبارک کا پینتیسواں سال تھا کہ قریش نے بیت اللہ کی خستہ عمارت کو از سر نو تعمیر کرنے کا فیصلہ کیا اور عہد کیا کہ اس میں صرف حلال رقم ہی صرف کریں گے۔رنڈی کی اجرت۔سود کی دولت۔اور کسی کا ناحق لیا ہوا مال استعمال نہیں ہونے دیں گے۔مگر حلال مال کی کمی پڑ گئی۔ تو انھوں نے شمال کیطرف سے کعبہ کی لمبائی تقریباً چھ ہاتھ کم کردی۔یہی ٹکڑا حجر اور حطیم کہلاتا ہے۔(الرحیق المختوم)"}],[2029,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم میرے پاس سے نکلے اور آپ خوش تھے پھر میرے پاس آئے اور آپ غمگین تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں کعبے کے اندر گیا اگر مجھے وہ بات پہلے معلوم ہو جاتی جو بعد میں معلوم ہوئی ۱؎ تو میں اس میں داخل نہ ہوتا، مجھے اندیشہ ہے کہ میں نے اپنی امت کو زحمت میں ڈال دیا ہے ۲؎\"۔\n§وضاحت\n۱؎ : کہ لوگوں کو کعبہ کے اندر داخل ہونے میں بڑی پریشانیاں اٹھانا پڑیں گی۔ ۲؎ : آپ صلی اللہ علیہ وسلم کا یہ اندیشہ صحیح ثابت ہوا عوام نے کعبہ کے اندر جانے کو ضروری سمجھ لیا چنانچہ اس کے لئے انہیں بڑی دھکم پیل کرنی پڑتی تھی، اللہ بھلا کرے سعودی حکومت کا جس نے کعبہ کے اندر عام لوگوں کا داخلہ بند کر دیا۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم میرے ہاں سے تشریف لے گئے تو بہت مسرور اور خوش تھے۔ پھر میرے ہاں واپس لوٹے تو کسی قدر کبیدہ اور رنجیدہ سے تھے۔ اور فرمایا ” میں کعبہ میں داخل ہوا ہوں اگر مجھے اپنے اس معاملے کا پہلے علم ہوتا جو بعد میں معلوم ہوا ہے تو میں اس کے اندر داخل نہ ہوتا۔ مجھے اندیشہ ہے کہ میں نے اپنی امت پر مشقت ڈالی ہے۔ “"}],[2030,"اسلمیہ کہتی ہیں کہ میں نے عثمان رضی اللہ عنہ سے پوچھا ۱؎: جب رسول اللہ صلی اللہ علیہ وسلم نے آپ کو بلایا تو آپ سے کیا کہا؟ تو انہوں نے کہا کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہیں یہ بتانا بھول گیا کہ مینڈھے ۲؎ کی دونوں سینگوں کو چھپا دو اس لیے کہ کعبہ میں کوئی چیز ایسی رہنی مناسب نہیں ہے جو نماز پڑھنے والے کو غافل کر دے\"۔\n§وضاحت\n۱؎ : عثمان سے مراد عثمان بن طلحہ حجبی رضی اللہ عنہ ہیں۔ ۲؎ : اس دنبہ کی سینگیں جس کو اسماعیل علیہ السلام کی جگہ پر ذبح کرنے کے لئے جبریل علیہ السلام لے آئے تھے۔","صحیح",{"u2":"منصور حجبی سے مروی ہے کہ مجھے میرے ماموں (مسافع بن شیبہ) نے میری والدہ صفیہ بنت شیبہ سے روایت کیا، وہ کہتی ہیں کہ میں نے اسلمیہ سے سنا، کہتی تھیں کہ میں نے عثمان (بن طلحہ الحجبی) سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے جب تمہیں بلایا تھا تو کیا فرمایا تھا؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم نے فرمایا تھا ” میں تجھے یہ کہنا بھول گیا تھا کہ دو سینگوں کو ڈھانپ دو، بیت اللہ میں کوئی ایسی چیز نہیں ہونی چاہیئے جو نمازی کو مشغول کرنے والی ہو۔ “ ابن السرح نے اپنی سند میں «حدثني خالي» کے بعد «مسافع بن شيبة» کے نام کی تصریح کی ہے۔","f2":"دو سینگوں سے مراد حضرت ابراہیم علیہ السلام کے لئے اسماعیل علیہ السلام کے فدیہ میں آنے والے مینڈھے کے سینگ ہیں۔جو کعبہ کے اندر محفوظ تھے۔2۔عام قاعدہ ہے کہ نمازی کے آگے ایسی کوئی چیز نہیں ہونی چاہیے۔ جو اس کی نظر یا دل کو مشغول کرنے والی ہو۔جیسے کہ صحیحین میں حدیث ہے۔کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی سیاہ منقش چادرکے متعلق ف فرمایا تھا۔ میری یہ خمیصہ چادر ابوجہم کے پاس لے جائو۔اس نے تو مجھے ابھی نماز میں مشغول کردیاتھا۔انبجانیۃ۔(صاف)چادر لے آئو (صحیح بخاری الصلاۃ۔حدیث 373 وصحیح مسلم المساجد۔حدیث 556)"}],[2031,"شیبہ بن عثمان کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ اس جگہ بیٹھے جہاں تم بیٹھے ہو اور کہا: میں باہر نہیں نکلوں گا جب تک کہ کعبہ کا مال ۱؎ (محتاج مسلمانوں میں) تقسیم نہ کر دوں، میں نے کہا: آپ ایسا نہیں کر سکتے، فرمایا: کیوں نہیں، میں ضرور کروں گا، میں نے کہا: آپ ایسا نہیں کر سکتے، وہ بولے: کیوں؟ میں نے کہا: اس لیے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس مال کی جگہ دیکھی، ابوبکر رضی اللہ عنہ نے بھی دیکھ رکھی تھی، اور وہ دونوں اس مال کے آپ سے زیادہ حاجت مند تھے لیکن انہوں نے اسے نہیں نکالا، یہ سن کر عمر کھڑے ہوئے اور باہر نکل آئے۔\n§وضاحت\n۱؎ : بعض علماء کہتے ہیں کہ اللہ تعالی نے یہ مال امام مہدی کے لئے رکھ چھوڑا ہے۔","صحیح",{"u2":"سیدنا شیبہ بن عثمان رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ اسی جگہ بیٹھے ہوئے تھے جہاں تم بیٹھے ہو تو انہوں نے کہا: میں یہاں سے نہیں نکلوں گا حتیٰ کہ کعبہ کا مال تقسیم کر دوں۔ شیبہ کہتے ہیں کہ میں نے کہا: آپ یہ نہیں کر سکتے۔ انہوں نے کہا: کیوں نہیں، میں ضرور کروں گا۔ میں نے کہا: آپ نہیں کر سکتے۔ کہنے لگے: کیوں؟ میں نے کہا: بلاشبہ رسول اللہ صلی اللہ علیہ وسلم کو اس مال کی خبر تھی اور ابوبکر رضی اللہ عنہ کو بھی علم تھا اور وہ اس مال کے آپ سے زیادہ ضرورت مند تھے مگر انہوں نے اسے نہیں نکالا۔ چنانچہ وہ اٹھے اور چلے گئے۔","f2":"1۔ اس سے مراد وہ مال ہے جو کعبہ میں بطور نذر آتا اور جمع رہتاتھا۔2۔حق کے اظہار وبیان میں جراءت سے کام لینا چاہیے۔اس میں اللہ عزوجل نے قوت رکھی ہے۔اور سلیم الفطرت اس سے انکار نہیں کرسکتا۔3۔اس کے ہم معنی روایت صحیح بخاری میں ہے۔جس سے اس روایت کی تایئد ہوتی ہے۔"}],[2032,"زبیر رضی اللہ عنہ کہتے ہیں کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ لیّۃ ۱؎ سے لوٹے اور بیری کے درخت کے پاس پہنچے تو رسول اللہ صلی اللہ علیہ وسلم قرن اسود ۲؎ کے دامن میں اس کے بالمقابل کھڑے ہوئے پھر اپنی نگاہ سے نخب ۳؎ کا استقبال کیا (اور راوی نے کبھی ( «نخبا» کے بجائے «واديه» کا لفظ کہا) اور ٹھہر گئے تو سارے لوگ ٹھہر گئے تو فرمایا: \"صیدوج ۴؎ اور اس کے درخت محترم ہیں، اللہ کی طرف سے محترم قرار دیئے گئے ہیں\"، یہ آپ صلی اللہ علیہ وسلم کے طائف میں اترنے اور ثقیف کا محاصرہ کرنے سے پہلے کی بات ہے۔\n§وضاحت\n۱؎ : ایک پہاڑ کا نام ہے جو طائف سے قریب ہے۔ ۲؎ : حجاز میں ایک پہاڑ کا نام ہے۔ ۳؎ : ایک جگہ کا نام ہے۔ ۴؎ : طائف میں ایک وادی کا نام ہے۔","ضعیف",{"u2":"سیدنا زبیر رضی اللہ عنہ سے مروی ہے کہ جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مقام لیہ سے واپس لوٹے اور سدرہ (بیری) کے پاس پہنچے تو رسول اللہ صلی اللہ علیہ وسلم قرن اسود کے پاس رک گئے۔ یعنی اس پہاڑ کے پاس جو اس بیری کے سامنے ہے۔ پھر آپ نے مقام نخب کی طرف نظر اٹھائی یا اس کی وادی کی طرف دیکھا۔ آپ رکے حتیٰ کہ سب لوگ رک گئے، تب آپ صلی اللہ علیہ وسلم نے فرمایا ” وادی وج کا شکار اور اس کے خار دار درخت حرام ہیں اور اللہ کی خاطر حرام کیے گئے ہیں۔ “ آپ صلی اللہ علیہ وسلم کا یہ ارشاد آپ صلی اللہ علیہ وسلم کے طائف جانے اور ثقیف کا محاصرہ کرنے سے پہلے کا ہے۔"}],[2033,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کجاوے صرف تین ہی مسجدوں کے لیے کسے جائیں: مسجد الحرام، میری اس مسجد (یعنی مسجد نبوی) اور مسجد اقصی کے لیے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” پالان نہ کسے (یعنی سفر نہ کئے) جائیں مگر تین مساجد کی طرف، یعنی مسجد الحرام (بیت اللہ) میری یہ مسجد (مسجد نبوی) اور مسجد الاقصیٰ کی طرف۔ “","f2":"مدینہ منورہ اس دنیا میں تمام مسلمانان عالم کا محبوب ترین شہر ہے۔یہ ہمارے آقا ہمارے محبوب حضرت محمد رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضوان اللہ عنہم اجمعین کا دارلحجرت اور مستقر ہے۔تمام اہل السنہ والجماعۃ(اہلحدیث) اس مبارک شہر کی زیارت اور اس کے سفر کو اپنی آرزوں کی انتہا اور اپنے عظیم ترین اعمال صالحہ میں شمار کرتے ہیں۔ مذکورہ بالا حدیث کی شرع میں علامہ خطابی کے کلمات بہت ہی جامع ہیں۔خلاصہ یہ ہے کہ ارشاد نبوی صلی اللہ علیہ وسلم کا تعلق نذر سے ہے۔یعنی اگر انسان نے کسی عام مسجد میں نماز پڑھنے کی نذر مانی ہوتو اسے اختیار ہے کہ چاہے تو اس نذر کردہ مسجد میں نماز پڑھے یا کسی اور میں پڑھ لے۔(سبھی برابر ہیں۔)الا یہ کہ ان تین میں سے کسی کی نذر مانی ہو تو اسے یہ اپنی نذر پوری کرنی واجب ہے۔ اور ان کے خاص ہونے کی وجہ یہ ہے کہ یہ تینوں ہمارے انبیاء علیہ السلام کی مساجد ہیں۔جن کی اقتداء کا ہمیں حکمدیا گیا ہے۔ جبکہ بعض اہل علم فرماتے ہیں کہ اعتکاف صرف ان تین مسجدوں میں صحیح ہے۔انتھیٰ اس معنی کی تایئد اس روایت کے ان الفاظ سے بھی ہوتی ہے۔(لاينبغي للمطي ان يشد رحالها الي مسجد تبتغي فيه الصلاة غير مسجدي هذا والمسجد الحرام والمسجد الاقصي (نیل الاوطار 110/5) یعنی بغرض نماز کسی مسجدکی طرف سواری پر پالان نہ کسا جائے۔سوائے ان مساجد کے میری یہ مسجد مسجد حرام اور مسجد اقصیٰ۔ شاہ عبدالعزیز کی توضیح یہ ہے کہ اس حدیث میں مستثنیٰ منہ مخذوف ہے یعنی لاتشد الرحال الي موضع يتقرب به الا الي ثلاثة مساجد ان تين مساجد کے علاوہ بغرض تقرب کہیں کا سفر نہ کیا جائے۔ الفاظ حدیث کا ظاہر سیاق واضح کر رہا ہے کہ ان تین محترم معظم مساجد کے علاوہ کہیں کا سفر نہ کیا جاوے۔(یعنی بغرض عبادت وتقرب(اور اس کی تایئد حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ کی اس روایت سے ہوتی ہے۔ کہ انہوں نے بصرہ الغفاری سے پوچھا کہ کہاں سے آرہے ہو؟ کہا کوہ طور سے کہا کہ اگر تمہارے اس سفر سے پہلے میری تم سے ملاقات ہوجاتی تو تم نہ جاتے میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا۔کہ (لاتعمل المطي الا الي ثلاة مساجد)(سنن النسائي الجمعة حديث ١٤٣١) تين مساجد كے علاوہ کہیں کا سفر نہ کیا جائے۔ شاہ ولی اللہ رحمۃ اللہ علیہ نے حجۃ البالغہ میں لکھا ہے۔ کہ اہل جاہلیت اپنے زعم کے مطابق کئی متبرک مقامات کا سفر کیا کرتے تھے۔جس کا لازمی نتیجہ اللہ کے دین میں بصورت تحریف وفساد نکلتا تھا۔تو نبی کریم صلی اللہ علیہ وسلم نے اس فساد کا منبع ہی بند کردیا۔تاکہ مشروع اور غیر مشروع مشرکانہ وبدعی شعائر آپس میں خلط ملط نہ ہوں۔ اور غیر اللہ کی عبادت کادروازہ بند ہوجائے۔اور میرے نزدیک انہی میں سے کوئی قبر کسی ولی اللہ کی عبادت گاہ اور کوہ طور سبھی برابر ہیں۔(بحوالہ عون المعبود)\nشعائر اور عبادت کے علاوہ جہاد ہجرت طلب علم۔عزیز واقارب اور علماء سے ملاقات اور تجارت وغیرہ ایسے امور ہیں جن کے لئے سفر شرعا مطلوب ہے۔کسی نے بھی کبھی ان پر انکار نہیں کیا۔مگر بغرض عبادت اعتکاف اور اجر مذید کی غرض سے کسی جگہ کا سفر بفرمان رسول صلی اللہ علیہ وسلم ان تین مساجد ہی سے خاص ہے۔زیارت قبو ر کے لئے سفر کا مسئلہ امام ابن تیمیہرحمۃ اللہ علیہ او ر ابن قیم رحمۃ اللہ علیہ نے اپنی تحریروں میں خوب خوب نکھارا ہے۔اور نہایت قوی او ر واضح براہین اور گہری بصیرت سے ثابت کیا ہے۔ کہ محض زیارت قبور کےلئے سفر کہیں کا بھی ہو جائز نہیں ہے۔ نبی کریم صلی اللہ علیہ وسلم کی قبر کی بجائے وہ نیت کی جانی چاہیے جو مشروع ومرغوب فیہ ہو۔یعنی زیارت مسجد نبوی اور اس میں نماز سفر کی یہ نیت اور غرض انتہائی مبارک مشروع اور مرغوب ہے۔ اور متضمن ہے۔ دیگر سب مشروع زیارات کو یعنی رسول اللہ صلی اللہ علیہ وسلم کی قبر مبارک مسجد قباء مقابر بقیع اور شہدائے احد۔اور یہ نزاع اور اختلاف صرف ابتدائی نیت کے مسئلے میں ہے۔ مدینہ منورہ پہنچ کر مذکورہ بالا سبھی زیارات حاصل ہوتی ہیں۔اور سب کی زیار ت مستحب ہے۔ اس میں کوئی اختلاف نہیں ہے۔لہذا علمائے اہل حدیث۔۔۔كثر الله سوادهم۔۔۔اس امر کے قائل وفاعل ہیں۔کہ مدینہ منورہ میں اصلا مسجد نبوی کی زیارت کا قصہ کیا جائے۔اور بس۔دیگر زیارات بالتبع حاصل ہوں گی۔ یہ عمل اور سفر پیارے پیغمبر سیدنا محمد رسول اللہ صلی اللہ علیہ وسلم سے محبت کا مظہر ہے۔بشرط یہ کہ عقیدہ صحیح اور دیگر اطوار زندگی بھی شریعت کے مطابق ہوں۔اس سے بے رغبتی انتہائی شقاوت بدبختی۔اور رسول اللہ صلی اللہ علیہ وسلم سے محبت نہ ہونے کی دلیل ہے۔\nایک ضروری نکتہ یہ بھی ہے کہ زیارت مسجد نبوی کا اعمال حج سے قطعا ً کوئی تعلق نہیں ہے۔اعمال حج اول تا آخر مکہ مکرمہ میں ہی مکمل ہوجاتے ہیں۔ سفر مدینہ ایک علیحدہ اور مستقل عمل ہے۔اگر کوئی شخص اپنے سفر حج میں مدینہ منورہ نہ جاسکے تو اس کے حج میں کوئی نقص یا عیب نہیں ہوتا۔(اللهم الرزقنا حبك وحب عمل يقربنا الي حبك)اس باب كی مزکورہ بالا صحیح ترین حدیث کے مقابلے میں زیارت قبر نبوی کے سفر کے سلسلے میں پیش کی جانے والی روایات اصول حدیث کے معیار پر پوری نہیں اُترتی ہیں۔ اور دین محض جذبات یا تعصب کا نام نہیں بلکہ اتباع حق کا نام ہے۔ ان ضعیف روایات میں سے اہم روایات کی تخریج اور ان کے ضعف کی صراحت حافظ ابن حجر رحمۃ اللہ علیہ نے (التلخیص الجبیر 266/2۔حدیث 1075) میں کردی ہے۔مثلاً من زارني بعد موتي فكانما زارني في حياتي)جس نے میری موت کے بعد میری زیارت کی اس نے گویا میری زندگی میں میری زیارت کی۔ (من زارا قبري فله الجنة) جس نے میری قبر کی زیارت کی اس کے لئے جنت ہے۔ (من جاءني زائر الا تعمله حاجة الا زيارتي كان حقا علي ان اكون له شفيعا يوم القيامة) جو میری زیارت کے لئے آیا جبکہ اسے سوائے میری زیارت کے اور کوئی غرض نہ ہو تو مجھ پر حق ہے کہ قیامت کے روز اس کے لئے سفارشی بنوں (من حج ولم يزرني فقد جفاني) جس نے حج کیا اور میری زیارت نہیں کی اس نے بلاشبہ مجھ سے بے رخی کی (من زارني بالمدينة محتسبا كنت له شفعيا وشهيدا يوم القيامة) جس نے ثواب کی غرض سے مدینے کی زیارت کی میں ا س کے لئے قیامت کے دن شفیع اور شہید بنوں گا یہ سب روایات ناقابل حجت ہیں۔طلبہ علم اور متلاشیان حق پر واجب ہے۔ کہ سنت اور بدعت میں فرق کرنے کےلئے علماء اور راسخین فی الحدیث سے رجوع کریں۔وباللہ التوفیق"}],[2034,"علی رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے سوائے قرآن کے اور اس کے جو اس صحیفے ۱؎ میں ہے کچھ نہیں لکھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مدینہ حرام ہے عائر سے ثور تک (عائر اور ثور دو پہاڑ ہیں)، جو شخص مدینہ میں کوئی بدعت(نئی بات) نکالے، یا نئی بات نکالنے والے کو پناہ اور ٹھکانا دے تو اس پر اللہ، ملائکہ اور تمام لوگوں کی لعنت ہے، نہ اس کا فرض قبول ہو گا اور نہ کوئی نفل، مسلمانوں کا ذمہ (عہد) ایک ہے (مسلمان سب ایک ہیں اگر کوئی کسی کو امان دیدے تو وہ سب کی طرف سے ہو گی)اس (کو نبھانے) کی ادنی سے ادنی شخص بھی کوشش کرے گا، لہٰذا جو کسی مسلمان کی دی ہوئی امان کو توڑے تو اس پر اللہ، ملائکہ اور تمام لوگوں کی لعنت ہے، نہ اس کا فرض قبول ہو گا اور نہ نفل، اور جو اپنے مولی کی اجازت کے بغیر کسی قوم سے ولاء کرے ۲؎ اس پر اللہ، ملائکہ اور تمام لوگوں کی لعنت ہے، نہ اس کا فرض قبول ہو گا اور نہ نفل\"۔\n§وضاحت\n۱؎ : یہ صحیفہ ایک ورق تھا جس میں دیت کے احکام تھے ،علی رضی اللہ عنہ اسے اپنی تلوار کی نیام میں رکھتے تھے۔ ۲؎ : یعنی کوئی اپنی آزادی کی نسبت کسی دوسرے کی طرف نہ کرے۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ نے بیان کیا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم سے کچھ نہیں لکھا ہے سوائے قرآن کریم کے اور جو اس صحیفے میں ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے ” مدینہ منورہ عائر (عیر) اور ثور (دو پہاڑوں) کے مابین حرم ہے۔ تو جو یہاں کوئی بدعت نکالے یا کسی بدعتی کو جگہ دے، اس پر اللہ، فرشتوں اور سب لوگوں کی لعنت ہو۔ اس کا فرض اور نفل کچھ قبول نہیں ہو گا۔ مسلمانوں کا ذمہ (کسی کافر کو دیا ہوا عہد امان، اجتماعی طور پر) ایک ہی ہے۔ ان کا ادنیٰ فرد بھی اس کی حفاظت کے لیے کوشش کا پابند ہے۔ جس نے کسی مسلمان کے دیے ہوئے عہد امان کو توڑا تو اس پر اللہ، فرشتوں اور سب لوگوں کی لعنت ہے۔ اس کا فرض و نفل کچھ قبول نہیں ہو گا۔ اور جو (آزاد شدہ غلام) اپنے آزاد کرنے والوں کی اجازت کے بغیر کسی اور قوم کی طرف اپنے آزاد ہونے کی نسبت کرے، اس پر اللہ اور سب فرشتوں کی لعنت ہے۔ اس سے کوئی فرض اور نفل قبول نہیں ہو گا۔ “","f2":"1-حضرت علی رضی اللہ تعالیٰ عنہ کے پاس کوئی خاص باطنی علم یا وصیت نہ تھی۔ جو دیگر لوگوں سے مخفی آپ کو دی گئی ہو آپ کے پاس جو کچھ تھا آپ نے اس کا اظہار فرمادیا۔2۔مدینہ منورہ مذکورہ حدود میں اسی طرح حرم اور محترم ہے۔جیسے کہ مکہ مکرمہ ہے۔اور بدعت ہر اعتبار سے ضلالت ہے۔اور بدعتی انسان کا اکرام بہت بڑا شرعی ظلم ہے۔مدینہ منورہ میں اس عمل کی شناخت از حد زیادہ ہے۔کیونکہ یہ دین اسلام کا منبع اور مرکز ہے۔3۔کفار کے مقابلے میں مسلمان ایک ہیں۔ان کےادنیٰ فرد کی بھی وہی حیثیت ہے۔ جو ان کے اعلیٰ کی ہے۔4۔آذاد شدہ غلام (مولیٰ) اجازت لے کر بھی اپنی نسبت ولاء فروخت یا تبدیل نہیں کرسکتا۔یہ عمل حرام ہے۔حدیث میں(بغير اذن مواليه) کازکر قید اتفاقی ہے۔احترازی نہیں۔"}],[2035,"علی رضی اللہ عنہ سے اس قصے میں روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس (یعنی مدینہ) کی نہ گھاس کاٹی جائے، نہ اس کا شکار بھگایا جائے، اور نہ وہاں کی گری پڑی چیزوں کو اٹھایا جائے، سوائے اس شخص کے جو اس کی پہچان کرائے، کسی شخص کے لیے درست نہیں کہ وہ وہاں لڑائی کے لیے ہتھیار لے جائے، اور نہ یہ درست ہے کہ وہاں کا کوئی درخت کاٹا جائے سوائے اس کے کہ کوئی آدمی اپنے اونٹ کو چارہ کھلائے\"۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ نے مذکورہ بالا قصہ میں نبی کریم صلی اللہ علیہ وسلم سے بیان کیا کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کی گھاس نہ کاٹی جائے، اس کا شکار نہ بھگایا جائے اللہ، اس کی گری پڑی چیز نہ اٹھائی جائے مگر وہ جو اس کا اعلان کرے۔ کسی کو روا نہیں کہ قتال کی غرض سے اس میں اسلحہ اٹھائے۔ اور کسی کو روا نہیں کہ اس سے درخت کاٹے مگر کوئی اپنے اونٹ کو چارہ دینا چاہے تو جائز ہے۔ “"}],[2036,"عدی بن زید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ کے ہر جانب ایک ایک برید محفوظ کر دیا ہے ۱؎ نہ وہاں کا درخت کاٹا جائے گا اور نہ پتے توڑے جائیں گے مگر اونٹ کے چارے کے لیے (بہ قدر ضرورت) ۔\n§وضاحت\n۱؎ : چاروں اطراف مشرق، مغرب اور شمال جنوب کو ملا کر کل چار برید ہوئے اور ایک برید چار فرسخ کا ہوتا ہے اور ایک فرسخ تین میل کا اس طرح اس حدیث کی رو سے کل (۴۸) میل بنتا ہے جبکہ صحیح مسلم کی روایت میں (۱۲) میل کی صراحت آئی ہے۔","حسن",{"u2":"سیدنا عدی بن زید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ کی ہر طرف سے ایک ایک برید (بارہ میل) کو محفوظ علاقہ قرار دیا تھا کہ نہ اس کے درخت کاٹے جائیں اور نہ پتے توڑے جائیں، مگر اونٹ کے چارے کے بقدر جائز ہے۔"}],[2037,"سلیمان بن ابی عبداللہ کہتے ہیں کہ میں نے سعد بن ابی وقاص رضی اللہ عنہ کو دیکھا کہ انہوں نے ایک شخص کو پکڑا جو مدینہ کے حرم میں جسے رسول اللہ صلی اللہ علیہ وسلم نے حرم قرار دیا ہے شکار کر رہا تھا، سعد نے اس سے اس کے کپڑے چھین لیے تو اس کے سات(۷) لوگوں نے آ کر ان سے اس کے بارے میں گفتگو کی، آپ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے حرم قرار دیا ہے اور فرمایا ہے: \"جو کسی کو اس میں شکار کرتے پکڑے تو چاہیئے کہ وہ اس کے کپڑے چھین لے\"، لہٰذا میں تمہیں وہ سامان نہیں دوں گا جو مجھے رسول اللہ صلی اللہ علیہ وسلم نے دلایا ہے البتہ اگر تم چاہو تو میں تمہیں اس کی قیمت دے دوں گا۔","صحیح",{"u2":"سلیمان بن ابی عبداللہ بیان کرتے ہیں کہ میں نے سیدنا سعد بن ابی وقاص رضی اللہ عنہ کو دیکھا کہ انہوں نے حرم مدینہ میں، جسے کہ رسول اللہ صلی اللہ علیہ وسلم نے حرم قرار دیا ہے، ایک آدمی کو شکار کرتے پکڑ لیا اور اس کے کپڑے چھین لیے تو اس شخص (غلام) کے مالک آئے اور اس کے بارے میں بات کی تو انہوں نے کہا: بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے اس کو حرم قرار دیا ہے اور فرمایا ہے ” جو شخص کسی کو اس میں شکار کرتا پکڑ لے، تو وہ اس کے کپڑے ضبط کر لے۔ “ چنانچہ وہ غنیمت جو رسول اللہ صلی اللہ علیہ وسلم نے مجھے عنایت فرمائی ہے واپس نہیں کروں گا۔ ہاں اگر چاہو تو اس کی قیمت دے دیتا ہوں۔","f2":"اس روایت میں شکار کرنے کے الفاظ منکر ہیں۔صحیح الفاظ کاٹنے کے ہیں۔ جیسا کہ اگلی روایت میں ہے۔"}],[2038,"سعد رضی اللہ عنہ کے غلام سے روایت ہے کہ سعد نے مدینہ کے غلاموں میں سے کچھ غلاموں کو مدینہ کے درخت کاٹتے پایا تو ان کے اسباب چھین لیے اور ان کے مالکوں سے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو منع کرتے سنا ہے کہ مدینہ کا کوئی درخت نہ کاٹا جائے، آپ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جو کوئی اس میں کچھ کاٹے تو جو اسے پکڑے اس کا اسباب چھین لے ۱؎\"۔\n§وضاحت\n۱؎ : یہ جھڑکی اور ملامت کے طور پر ہے، پھر اسے واپس دیدے ، اکثر علماء کی یہی رائے ہے، اور بعض علماء نے کہا ہے کہ نہ دے۔","صحیح",{"u2":"سیدنا سعد بن ابی وقاص رضی اللہ عنہ کے ایک غلام سے مروی ہے کہ انہوں نے مدینہ کے کچھ غلاموں کو دیکھا کہ وہ (حرم) مدینہ میں درخت کاٹ رہے ہیں۔ تو انہوں نے ان کا اسباب چھین لیا اور ان غلاموں کے مالکوں سے کہا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے کہ آپ صلی اللہ علیہ وسلم نے مدینہ کے درختوں سے کچھ کاٹنے سے منع فرمایا ہے۔ اور فرمایا ہے ” جو کوئی ان سے کچھ کاٹے تو جو اسے پکڑ لے تو اس کا اسباب اسی کے لیے ہے (اس کے کپڑے، کلہاڑی اور رسی وغیرہ)۔ “"}],[2039,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رسول اللہ صلی اللہ علیہ وسلم کے حرم سے نہ درخت کاٹے جائیں اور نہ پتے توڑے جائیں البتہ نرمی سے جھاڑ لیے جائیں ۱؎\"۔\n§وضاحت\n۱؎ : اکثر علماء کے نزدیک حرم مدینہ کے درخت کاٹنے یا شکار مارنے میں کوئی سزا نہیں ہے، بعض علماء کے نزدیک سزا کا مستحق ہے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ کے رسول صلی اللہ علیہ وسلم کے محفوظ کردہ علاقے سے نہ پتے توڑے جائیں اور نہ درخت کاٹے جائیں مگر ہلکے انداز میں پتے جھاڑ لیے جائیں۔ “"}],[2040,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد قباء پیدل اور سوار (دونوں طرح سے) آتے تھے ابن نمیر کی روایت میں \"اور دو رکعت پڑھتے تھے\" (کا اضافہ ہے) ۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم قباء تشریف لے جایا کرتے تھے۔ کبھی پیدل اور کبھی سوار ہو کر۔ ابن نمیر نے مزید کہا: اور (مسجد میں) دو رکعتیں پڑھا کرتے تھے۔","f2":"مدینہ منورہ کی مشروع ومسنون زیارات میں سے اہم ترین زیارت مسجد قباء کی ہے بلکہ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی تو یہ ہے۔کہ یہاں نماز پڑھنے کا ثواب عمرے کا سا ثواب ہے۔(سنن ابن ماجہ اقامۃ الصلاۃ حدیث 1411)"}],[2041,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھ پر جب بھی کوئی سلام بھیجتا ہے تو اللہ تعالی میری روح مجھے لوٹا دیتا ہے یہاں تک کہ میں اس کے سلام کا جواب دیتا ہوں\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص بھی مجھے سلام کہتا ہے تو اللہ مجھ پر میری روح لوٹا دیتا ہے اور میں اس کے سلام کا جواب دیتا ہوں۔ “","f2":"یہ حدیث ہمارے فاضل محقق شیخ زبیر علی زئی صاحب کے نزدیک ضعیف ہے۔لیکن اکثر محدثین کے نزدیک یہ حسن درجہ کی ہے۔جو محدثین کے ہاں مقبول ہے۔اور روح لوٹانے کی کئی ایک تاویلات کی گئی ہیں مگر اول و آخر یہی ہے کہ یہ برزخی زندگی کا معاملہ ہے۔اسے دنیا کی زندگی پر قیاس کرنا بالکل غلط ہے۔ علاوہ ازیں یہ متشابہات میں سے ہے۔ہم کوئی اطمینان بخش تفصیل و توجیہ کرنے سے قاصر ہیں۔والله اعلم بحقيقة الحال (وَفَوْقَ كُلِّ ذِي عِلْمٍ عَلِيمٌ)(یوسف۔76)"}],[2042,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے گھروں کو قبرستان نہ بناؤ ۱؎ اور میری قبر کو میلا نہ بناؤ(کہ سب لوگ وہاں اکٹھا ہوں)، اور میرے اوپر درود بھیجا کرو کیونکہ تم جہاں بھی رہو گے تمہارا درود مجھے پہنچایا جائے گا\"۔\n§وضاحت\n۱؎ : یعنی اس میں نماز پڑھنا اور عبادت کرنا نہ چھوڑو کہ تم اس میں مردوں کی طرح ہو جاؤ اس سے معلوم ہوا کہ جس گھر میں نماز اور عبادت نہیں ہوتی وہ قبرستان کے مانند ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اپنے گھروں کو قبرستان مت بناؤ۔ اور نہ میری قبر کو عید (میلہ گاہ) بناؤ اور مجھ پر درود پڑھو۔ تم جہاں کہیں بھی ہو گے تمہارا درود مجھ کو پہنچ جائے گا۔ “","f2":"1۔ گھروں کو قبرستان بنانا یوں ہے کہ وہاں نماز تلاوت اور اذکار کے اعمال ترک کردیئے جایئں جیسے کہ قبرستان میں نہیں کئے جاتے۔اس میں مردوں کو بالخصوص تاکید ہے۔کہ اپنی نمازوں کا ایک حصہ یعنی سنن اور نوافل گھروں میں پڑھا کریں جو کہ نزول برکات کا باعث ہیں۔اور گھر والوں کے لئے اعمال خیر کی ترغیب وتربیت بھی۔اس کادوسرا مفہوم یہ بھی ہوسکتا ہے۔کہ اپنی میتوں کو اپنے گھروں میں مت دفن کیا کرو بلکہ قبرستان میں دفنائو۔2۔رسول اللہ صلی اللہ علیہ وسلم کی قبر مبارک کے پاس مجمع لگانا بھیڑ کرنا بہت زیادہ دیرکھڑے رہنا یا بار بار آنا اسے میلہ گاہ بنانا ہے۔جو کہ ممنوع اور انتہائی خلاف ادب ہے۔جب ر سول اللہ صلی اللہ علیہ وسلم کی قبر مبارک کاادب یہ ہے تو دیگر صالحین کی قبروں پراجتماع اور عرس بطریق اولیٰ ممنوع اور حرام ہیں۔3۔رسول اللہ صلی اللہ علیہ وسلم پر صلاۃ وسلام پڑھنے کے لئے سفر کی مشقت اٹھانے کی کوئی ضرورت نہیں انسان جہاں کہیں ہو اس کا درود آپ صلی اللہ علیہ وسلم کو پہنچادیا جاتاہے۔"}],[2043,"ربیعہ بن ہدیر کہتے ہیں کہ میں نے طلحہ بن عبیداللہ رضی اللہ عنہ کو سوائے اس ایک حدیث کے کوئی اور حدیث رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے نہیں سنا، میں نے عرض کیا: وہ کون سی حدیث ہے؟ تو انہوں نے کہا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، آپ شہداء کی قبروں کا ارادہ رکھتے تھے جب ہم حرۂ واقم (ایک ٹیلے کا نام ہے) پر چڑھے اور اس پر سے اترے تو دیکھا کہ وادی کے موڑ پر کئی قبریں ہیں، ہم نے پوچھا: اللہ کے رسول! کیا ہمارے بھائیوں کی قبریں یہی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"ہمارے صحابہ کی قبریں ہیں ۱؎\"، جب ہم شہداء کی قبروں کے پاس پہنچے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ ہمارے بھائیوں کی قبریں ہیں ۲؎\"۔\n§وضاحت\n۱؎ : جن کی موت اسلام پر ہوئی ہے اور وہ شہداء کا مقام نہیں پا سکے ہیں۔ ۲؎ : نبی اکرم صلی اللہ علیہ وسلم نے اخوت کی نسبت ان کی طرف کی یہ ان کے لئے بڑے شرف کی بات ہے۔","صحیح",{"u2":"ربیعہ بن ہدیر کہتے ہیں کہ میں نے سیدنا طلحہ بن عبیداللہ رضی اللہ عنہ کو کبھی حدیث رسول بیان کرتے نہیں سنا۔ مگر ایک حدیث۔ شاگرد نے کہا: میں نے پوچھا وہ کون سی؟ (طلحہ نے) کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، ہم شہداء کی قبروں کا قصد کیے ہوئے تھے حتیٰ کہ ہم حرہ واقم پر چڑھ گئے۔ جب اس سے نیچے اترے تو وہاں ایک جانب میں قبریں تھیں۔ ہم نے کہا: اے اللہ کے رسول! کیا ہمارے بھائیوں کی قبریں یہی ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ ہمارے اصحاب کی قبریں ہیں “ پھر جب ہم شہداء کی قبروں پر پہنچ گئے تو فرمایا ” یہ ہمارے بھائیوں کی قبریں ہیں۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم موقع بموقع شہداء کی قبروں پر جایا کرتے تھے اور ان کے لئے دعایئں فرماتے تھے آپ نے شہداء کو اپنے بھائی ہونے کے لقب سے مشرف فرمایا اور دوسروں کو اپنے اصحاب کہا۔"}],[2044,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بطحاء میں جو ذی الحلیفہ میں ہے اونٹ بٹھایا اور وہاں نماز پڑھی، چنانچہ عبداللہ بن عمر رضی اللہ عنہما بھی ایسا ہی کرتے تھے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ذوالحلیفہ کے قریب بطحاء (کھلے میدان) میں اپنی اونٹنی بٹھائی اور وہاں نماز پڑھی۔ چنانچہ عبداللہ بن عمر رضی اللہ عنہ اس پر عمل کیا کرتے تھے۔ (درج ذیل اثر میں اس کی وضاحت ہے۔)"}],[2045,"مالک کہتے ہیں جب کوئی مدینہ واپس لوٹے اور معرس پہنچے تو اس کے لیے مناسب نہیں ہے کہ وہ آگے بڑھے جب تک کہ نماز نہ پڑھ لے جتنا اس کا جی چاہے اس لیے کہ مجھے یہ بات معلوم ہوئی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے وہاں رات کو قیام کیا تھا۔ ابوداؤد کہتے ہیں: میں نے محمد بن اسحاق مدنی کو کہتے سنا: معرس مدینہ سے چھ میل کے فاصلے پر ایک مقام ہے۔","صحیح"],[2046,"علقمہ کہتے ہیں کہ میں عبداللہ بن مسعود رضی اللہ عنہ کے ساتھ منی میں چل رہا تھا کہ اچانک ان کی ملاقات عثمان رضی اللہ عنہ سے ہو گئی تو وہ ان کو لے کر خلوت میں گئے، جب عبداللہ بن مسعود رضی اللہ عنہ نے محسوس کیا کہ انہیں (شادی کی) ضرورت نہیں ہے تو مجھ سے کہا: علقمہ! آ جاؤ ۱؎ تو میں گیا تو عثمان رضی اللہ عنہ ۲؎ نے ان سے کہا: ابوعبدالرحمٰن! کیا ہم آپ کی شادی ایک کنواری لڑکی سے نہ کرا دیں، شاید آپ کی دیرینہ طاقت و نشاط واپس آ جائے۔ عبداللہ بن مسعود رضی اللہ عنہ نے کہا: اگر آپ ایسی بات کہہ رہے ہیں تو میں تو اللہ کے رسول صلی اللہ علیہ وسلم کو فرماتے ہوئے سن چکا ہوں کہ \"تم میں سے جو شخص نکاح کی طاقت رکھتا ہو اسے نکاح کر لینا چاہیئے کیونکہ یہ نگاہ کو خوب پست رکھنے والی اور شرمگاہ کی خوب حفاظت کرنے والی چیز ہے اور جو تم میں سے اس کے اخراجات کی طاقت نہ رکھتا ہو تو اس پر روزہ ہے، یہ اس کی شہوت کے لیے توڑ ہو گا ۳؎\"۔\n§وضاحت\n۱؎ : کیونکہ اب خلوت کی ضرورت نہیں رہ گئی۔ ۲؎ : ہو سکتا ہے کہ ابن مسعود رضی اللہ عنہ نے علقمہ سے وہ گفتگو بیان کی ہو جو عثمان نے خلوت میں ان سے کی تھی اور یہ بھی احتمال ہے کہ عثمان رضی اللہ عنہ نے علقمہ رضی اللہ عنہ کے آنے کے بعد اپنی بات پوری کرتے ہوئے علقمہ کی موجودگی میں اسے عبداللہ بن مسعود رضی اللہ عنہ سے کہا ہو۔ ۳؎ : آدمی جب نان و نفقہ کی طاقت رکھے تو اس کے لئے نکاح کرنا مسنون ہے، اور بعض کے نزدیک اگر گناہ میں پڑ جانے کا خطرہ ہو تو واجب یا فرض ہے، اس کے فوائد یہ ہیں کہ اس سے افزائش نسل کے علاوہ شہوانی جذبات کو تسکین ملتی ہے، اور زنا فسق و فجور سے آدمی کی حفاظت ہوتی ہے۔","صحیح",{"u2":"جناب علقمہ کا بیان ہے کہ میں منٰی میں سیدنا عبداللہ بن مسعود رضی اللہ عنہ کے ساتھ جا رہا تھا کہ انہیں سیدنا عثمان رضی اللہ عنہ ملے پس عثمان رضی اللہ عنہ نے ان کو علیحدگی میں بلایا (اور ان کو نکاح کرنے کی ترغیب دی) لیکن عبداللہ بن مسعود رضی اللہ عنہ نے بتایا کہ انہیں نکاح کی حاجت نہیں ہے۔ تب عبداللہ نے مجھ سے کہا، علقمہ! ادھر آؤ۔ میں حاضر ہو گیا (کیونکہ اب تخلیے کی ضرورت نہ رہی تھی) تو عثمان رضی اللہ عنہ نے ان سے کہا: اے ابوعبدالرحمٰن! (عبداللہ بن مسعود رضی اللہ عنہ) کیا ہم تمہاری ایک کنواری لڑکی سے شادی نہ کرا دیں؟ (اس طرح) شاید تمہاری (جوانی کی طاقت) پھر لوٹ آئے۔ تو عبداللہ رضی اللہ عنہ کہنے لگے: آپ یہ کہتے ہیں حالانکہ میں نے تو رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے “ جو تم میں سے طاقت رکھتا ہو اسے چاہیئے کہ شادی کر لے۔ بلاشبہ اس سے نظر نیچی اور شرمگاہ محفوظ ہو جاتی ہے۔ (دامن عفت پر داغ نہیں آتا) اور جو طاقت نہ رکھتا ہو تو وہ روزے رکھے، یہ اس کے (شہوانی) جذبات کو کمزور کر دیں گے۔ “","f2":"1۔اس حدیث سے بظاہر یہ معلوم ہوتا ہے۔کہ حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کی پہلی بیوی فوت ہوگئی تھی۔اور اب وہ بیوی کے بغیر زندگی گزار رہے تھے۔حضرت عثمان کے علم میں یہ بات تھی۔اس لئے انہوں نے ملاقات پر پہلے انہیں خلوت میں دوبارہ نکاح کی ترغیب دی وہ آمادہ نہ ہوئے تو پھر ان کے ساتھی کےسامنے دوبارہ یہ کوشش کی۔ بہرحال اس حدیث س کئی فوائد معلوم ہوئے مثلا جس شخص کے پاس اپناگھر آباد کرنے کے لئے نان ونفقہ اوا سکنیٰ کےلازمی مصارف موجود ہوں۔ اس کیلئے متاھل زندگی گزارنا مستحب ہے۔بالخصوص جوانوں کو تو اس کی بہت زیادہ ترغیب دی گئی ہے۔2۔نظر اور شرمگاہ کی پاکیزگی کو انسان کی دینی اور معاشرتی زندگی میں بنیادی اہمیت حاصل ہے۔ ان کی حفاظت معاشرے میں امن وامان بھائی چارے عمومی راحت خیر وبرکت اور اللہ فضل و انعامات کی ضامن ہے اور ان کا فساد معاشرتی بگاڑ فتنے عداوت اور دلوں کی بے سکونی کا باعث ہے۔ اور نتیجتاً اللہ کی ناراضگی حصے میں آتی ہے 3۔مالی اعتبار سے کمزور شخص جو شادی نہ کرسکتا ہو اسے بمقابلہ دیگر علاجوں کے روزے رکھنے چاہیں امام ابن تیمیہ رحمۃ اللہ علیہ ایسے شخص کو قرض لے کر بھی یہ بار اُٹھانے کی ترغیب دیتے ہیں۔"}],[2047,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"عورتوں سے نکاح چار چیزوں کی بنا پر کیا جاتا ہے: ان کے مال کی وجہ سے، ان کے حسب و نسب کی وجہ سے، ان کی خوبصورتی کی بنا پر، اور ان کی دین داری کے سبب، تم دیندار عورت سے نکاح کر کے کامیاب بن جاؤ، تمہارے ہاتھ خاک آلود ہوں ۱؎\"۔\n§وضاحت\n۱؎ : یعنی عام طور پر عورت سے نکاح انہیں چار چیزوں کے سبب کیا جاتا ہے، ایک دیندار مسلمان کو چاہئے کہ ان سب اسباب میں دین کو ترجیح دے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا &rdquo; عورتوں سے چار باتوں کی بنا پر نکاح کیا جاتا ہے۔ اس کے مال، حسب و نسب، حسن و جمال اور اس کے دین کی بنا پر، پس تو دیندار کو اختیار کر، تیرے ہاتھ خاک آلود ہوں۔ &ldquo;","f2":"جملہ (تربت يداك) تیرے ہاتھ خاک آلود ہوں بدعا کےلئے نہیں بلکہ عربی محاورے کے تحت دعا اور ترغیب کے مفہوم کا حامل ہے۔ کسی خاتون سے تعلق ازدواج میں اسی آخری نکتے کو اہمیت ہونی چاہیے۔دیگر امور ضمنی اور اضافی ہیں۔ اگر حاصل ہوں تو فبہا اور یہ عظیم نعمت ہیں۔ورنہ اتنی اہمیت کے حامل نہیں ہیں کہ ان کی وجہ سے اصل چیز دین داری کو نظرانداز کردیا جائے۔"}],[2048,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"کیا تم نے شادی کر لی؟\" میں نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کنواری سے یا غیر کنواری سے؟\" میں نے کہا غیر کنواری سے، آپ صلی اللہ علیہ وسلم نے فرمایا:\"کنواری سے کیوں نہیں کی تم اس سے کھیلتے اور وہ تم سے کھیلتی\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے پوچھا ” کیا تو نے شادی کر لی ہے؟ “ میں نے عرض کیا: ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا ” کنواری سے یا بیوہ سے؟ “ میں نے کہا، بیوہ سے۔ فرمانے لگے ” کنواری سے کیوں نہیں کی؟ تم اس سے کھیلتے وہ تم سے کھیلتی۔ “","f2":"کنواری لڑکی سے شادی زیادہ مرغوب ہے اور کنوارے میاں بیوی میں ہنسی کھیل فطرتاً اور بالعموم بہت زیادہ ہوتا ہے۔ بخلاف بیوہ کے یہ عمل نفسیاتی صحت کےلئے بہت عمدہ ہوتا ہے۔نیز اس سے یہ بھی معلوم ہواکہ میاں بیوی میں لہو لعب جائز اور حق ہے۔تاہم کچھ اور وجوہات سے بیوہ سے شادی کرنا بھی باعث فضیلت ہے۔جیسا کہ نبی کریم صلی اللہ علیہ وسلم کا عمل اس پر شاہد ہے۔"}],[2049,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگا کہ میری عورت کسی ہاتھ لگانے والے کو نہیں روکتی آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنے سے جدا کر دو\"، اس شخص نے کہا: مجھے ڈر ہے میرا دل اس میں لگا رہے گا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو تم اس سے فائدہ اٹھاؤ\"۔","صحیح",{"u2":"امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ حسین بن حریث مروزی نے مجھے لکھ بھیجا کہ۔ ہمیں فضل بن موسیٰ نے حسین بن واقد سے، انہوں نے عمارہ بن ابی حفصہ سے، انہوں نے عکرمہ سے، انہوں نے، سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہنے لگا: میری بیوی کسی چھونے والے کا ہاتھ رد نہیں کرتی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے دور کر دو (طلاق دے دو)۔“ اس نے کہا: مجھے اندیشہ ہے کہ میرا دل اس کے ساتھ لگا رہے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تب اس سے فائدہ اٹھاؤ۔ “","f2":"یہ حدیث صحیح ہے۔اور یہ جملہ (لاتمنع يد الامس)کامفہوم یہ ہے کہ ایک مسلمان باوقار اور با غیر ت خاتون ہونے کے ناطے اس کے اندر غیروں سے کوئی نفرت ووحشت نہیں ہے۔(مگر فعلا ً اس سے کوئی بدکاری صادرنہیں ہوئی)تو نبی صلی اللہ علیہ وسلم نے اولاً اسے طلاق دینے کا فرمایا۔مگرشوہر نے اپنی کیفیت بتائی تو رخصت دے دی جیسے کہ دین سے دور معاشروں میں ایسی کیفیات پائی جاتی ہیں۔ مگر یہ معنی کرنا کہ وہ فعلاً بدکار تھی۔ پھر نبی کریم صلی اللہ علیہ وسلم نے ا س کو گھر میں رکھنے کی اجازت دے دی۔ ایک ناقابل تصو ر معنی ہے۔ کیونکہ زانیہ سے نکاح حرام ہے۔اور ایسا انسان جو اپنے اہل میں فحش کاری پرخاموش ہو دیوث ہوتا ہے۔اسی لئے کچھ محدثین نے اس کا وہی مفہوم بیان کیا ہے۔جوہم نے شروع میں بیان کیا ہے۔ بہرحال بُری عادات کی بنا پر عورت کو طلاق دی جاسکتی ہے۔ یہ حدیث اس باب سے مطابقت نہیں رکھتی۔اگلی حدیث اس باب کے مطابق ہے۔اس حدیث پر باب سہواً رہ گیا ہے یا کسی ناسخ (نقل کرنے والے) سے کوئی سہو ہوگیا ہے۔واللہ اعلم"}],[2050,"معقل بن یسار رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک شخص آیا اور اس نے عرض کیا: مجھے ایک عورت ملی ہے جو اچھے خاندان والی ہے، خوبصورت ہے لیکن اس سے اولاد نہیں ہوتی تو کیا میں اس سے شادی کر لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں\"، پھر وہ آپ کے پاس دوسری بار آیا تو بھی آپ صلی اللہ علیہ وسلم نے اس کو منع فرمایا، پھر تیسری بار آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"خوب محبت کرنے والی اور خوب جننے والی عورت سے شادی کرو، کیونکہ (بروز قیامت) میں تمہاری کثرت کی وجہ سے دوسری امتوں پر فخر کروں گا\"۔","حسن صحیح",{"u2":"سیدنا معقل بن یسار رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا مجھے ایک عورت ملی ہے جو عمدہ حسب اور حسن و جمال والی ہے مگر اس کے اولاد نہیں ہوتی۔ تو کیا میں اس سے شادی کر لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں “ پھر وہ دوبارہ آیا، تو آپ صلی اللہ علیہ وسلم نے منع فر دیا۔ پھر وہ تیسری بار آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” ایسی عورتوں سے شادی کرو جو بہت محبت کرنے والی اور بہت بچے جننے والی ہوں۔ بلاشبہ میں تمہاری کثرت سے دیگر امتوں پر فخر کرنے والا ہوں۔ “","f2":"1۔جس عورت کے متعلق معلوم ہوجائے کہ وہ ولادت کی صلاحیت سے محروم ہے اس سے نکاح نہیں کرنا چاہیے۔کیونکہ نکاح سے اصل مقصود اولاد کا حصول ہوتا ہے۔اور ہونا چاہیے۔تو جو عورت اس وصف ہی سے محروم ہو تو اس سے نکاح کرنے کا کیا فائدہ؟ تاہم اس کا مطلب یہ بھی نہیں کہ بانجھ عورت سے مطلقاً ہی نکاح کرنا ممنوع ہے۔بلکہ بعض دفع نکاح کے کچھ اور مقاصد بھی ہوتے ہیں۔تو وہاں ان سے نکاح کرنا جائز ہوگا۔ بلکہ بعض دفعہ پسندیدہ بھی ہوسکتا ہے۔2۔بیوہ عورت کے متعلق تو معلوم ہوجاتا ہے۔کہ وہ عقیم ہے۔مگر کنواری میں حیض نہ آنا ایک امکانی سبب ہوسکتاہے۔یقینی نہیں۔3۔بہت زیادہ محبت کرنے والی اور بہت بچے جننے والی یہ صفات خاندانی عرف سے جانی جاسکتی ہیں۔ویسے کنواری لڑکیوں میں یہ اوصاف بالعموم فطرتاً پائے جاتے ہیں۔"}],[2051,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما روایت کرتے ہیں کہ مرثد بن ابی مرثد غنوی رضی اللہ عنہ قیدیوں کو مکہ سے اٹھا لایا کرتے تھے، مکہ میں عناق نامی ایک بدکار عورت تھی جو ان کی آشنا تھی، مرثد رضی اللہ عنہ کا بیان ہے کہ میں نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: اللہ کے رسول! کیا میں عناق سے شادی کر لوں؟ آپ صلی اللہ علیہ وسلم خاموش رہے تو آیت کریمہ«والزانية لا ينكحها إلا زان أو مشرك» نازل ہوئی تو آپ صلی اللہ علیہ وسلم نے مجھے بلایا اور اسے پڑھ کر سنایا اور فرمایا: \"تم اس سے شادی نہ کرنا\"۔","حسن صحیح",{"u2":"جناب عمرو بن شعیب اپنے والد (شعیب) سے اور وہ اپنے دادا (عبداللہ بن عمرو) سے روایت کرتے ہیں کہ جناب مرثد بن ابی مرثد غنوی رضی اللہ عنہ مکہ سے (مسلمان) قیدیوں کو اٹھا کر لایا کرتے تھے۔ اور مکہ میں ایک بدکار عورت تھی جس کا نام عناق تھا اور وہ (قبل از اسلام) اس کی آشنا تھی۔ وہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: اے اللہ کے رسول! کیا میں عناق سے شادی کر لوں؟ آپ صلی اللہ علیہ وسلم نے مجھے اس کا جواب نہ دیا۔ تب یہ آیت نازل ہوئی«والزانية لا ينكحها إلا زان أو مشرك» ” یعنی بدکار عورت سے کوئی بدکار مرد یا مشرک ہی نکاح کرتا ہے۔ “ آپ صلی اللہ علیہ وسلم نے مجھے بلوایا، مجھ پر یہ آیت پڑھی اور فرمایا ” اس سے نکاح مت کرو۔ “","f2":"مکمل آیت کریمہ یوں ہے۔(الزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً وَالزَّانِيَةُ لَا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ ۚ وَحُرِّمَ ذَٰلِكَ عَلَى الْمُؤْمِنِينَ)(النور۔24/3) بدکار مرد کسی بدکارعورت سے ہی نکاح کرتا ہے۔ یا کسی مشرکہ سے۔اور بدکار عورت سے کوئی بدکار مرد ہی نکاح کرتا ہے۔یا کوئی مشرم۔اور یہ مومنین پر حرام کیا گیا ہے۔ اس آیت کریمہ کی تفسیر میں راحج یہی ہے۔ کے کسی عفیف مرد کو بدکار عورت سے اور عفیفہ عورت کو بدکار مرد سے نکاح کرنا حرام ہے۔جیسے کہ اسی صورت نور میں ہے۔(وَالطَّيِّبَاتُ لِلطَّيِّبِينَ وَالطَّيِّبُونَ لِلطَّيِّبَاتِ)(النور۔26) پاکیزہ عورتیں پاکیزہ مردوں کے لئے ہیں۔اور پاکیزہ مرد پاکیزہ عورتوں کےلئے اور یہ حدیث بھی اسی مفہوم کی تایئد کرتی ہے۔"}],[2052,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوڑے کھایا ہوا زناکار اپنی جیسی عورت ہی سے شادی کرے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی زانی، جسے زنا کی حد لگی ہو، کسی اپنے جیسی عورت ہی سے نکاح کرتا ہے۔ “ ابومعمر نے اپنی سند میں یوں کہا «حدثني حبيب المعلم، عن عمرو بن شعيب»۔","f2":"1۔مسدد اور ابو معمر کی سند میں فرق یہ ہے کہ معمر کی روایت میں استاد عبد الوارث نے حبیب المعلم سے تحدیث کی تصریح کی ہے اور حبیب نے عمرو بن شعب سے عن سے روایت کی جب کہ مسدد کی روایت اس کے برعکس ہے۔2۔اس حدیث میں بھی مذکورہ بالا امر کی توضیح وتایئد ہے۔کہ جس کی شہرت بری ہوجائے اسے کسی اپنے جیسے ہی سے نکاح کرنا چاہیے۔"}],[2053,"ابوموسی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنی لونڈی کو آزاد کر کے اس سے شادی کر لے تو اس کے لیے دوہرا ثواب ہے\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اپنی لونڈی کو آزاد کر کے خود ہی اس سے نکاح کر لے، تو ایسے شخص کے لیے دہرا اجر ہے۔ “","f2":"اسلام نے انسانی حقوق کی پاسداری اور حفاظت کے لئے جو تعلیمات پیش فرمائی ہیں۔دنیا کا کوئی مذہب اس کی نظیر پیش نہیں کرسکتا۔ اس لئے اسلام نے غلاموں کے ساتھ بھی حسن سلوک کی تاکید کی ہے۔اور ایسے طریقے بھی بتلائے جس سے غلامی کا خاتمہ یا کم از کم اس کی اصلاح ہوسکے۔ اس حدیث میں بھی غلامی کی رسم کی حوصلہ شکنی کے لئے ایک نہایت مفید عمل بتلادیا گیا ہے۔"}],[2054,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ام المؤمنین صفیہ رضی اللہ عنہا کو آزاد کیا اور ان کی آزادی ہی کو ان کا مہر قرار دیا۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے صفیہ رضی اللہ عنہا ا کو آزاد فرمایا (اور پھر اپنے حرم میں داخل کرنے کا شرف بخشا) اور ان کے آزاد کرنے ہی کو ان کا حق مہر ٹھہرایا۔","f2":"حضرت صفیہ رضی اللہ تعالیٰ عنہا خیبر کے یہودی سردار حی بن اخطب کی صاحبزادی تھیں۔اورفتح خیبر کے موقع پر مسلمانوں کے ہاتھ قید ہوگئی تھی۔جب قیدی عورتیں جمع کی گیئں۔ تو حضرت وحیہ بن خلیفہ کلبی رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آکر عرض کیا۔اے اللہ کے نبی صلی اللہ علیہ وسلم مجھے قیدی عورتوں میں سے ایک لونڈی دے دیجئے۔آپ صلی اللہ علیہ وسلم نےفرمایا جائو ایک لونڈی لے لو۔ انہوں نے جا کر حضرت صفیہ رضی اللہ تعالیٰ عنہا کو منتخب کرلیا۔اس پر ایک آدمی نے آپ صلی اللہ علیہ وسلم کے پا س آکر عرض کیا۔اے اللہ کے نبی صلی اللہ علیہ وسلم آپ نے بنی قریظہ اور بنی نضیر کی سیدہ صفیہ کو وحیہ کے حوالے کردیا۔حالانکہ صرف وہ آپ صلی اللہ علیہ وسلم کے شایان شان ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا وحیہ کو صفیہ سمیت بلائو۔حضرت وحیہ ان کو ساتھ لئے ہوئے حاضر ہوئے۔ آپ صلی اللہ علیہ وسلم نے انھیں دیکھ کر حضرت وحیہ سے فرمایا قیدیوں میں سے کوئی دوسری لونڈی لےلو۔پھر آپ صلی اللہ علیہ وسلم نے حضرت صفیہ پرالسلام پیش کیا۔ انہوں نے اسلام قبول کرلیا اس کے بعد آپ نے انہیں آذاد کرکے آپ صلی اللہ علیہ وسلم نے ان سے شادی کرلی۔ اور ان کی آذادی ہی کو ان کا مہر قرار دیا۔ مدینہ و اپسی میں صد صہبا پہنچ کر وہ حیض سے پاک ہوگئیں۔اس کے بعد ام سلیم رضی اللہ تعالیٰ عنہا نے انہیں آپ صلی اللہ علیہ وسلم کےلئے آراستہ کیا۔اوررات کو آپ صلی اللہ علیہ وسلم کے پاس بھیج دیا۔آپ صلی اللہ علیہ وسلم نے دولہے کی حیثیت سے ان کے ہمراہ صُبح کی۔اور کھجور اور گھی اور ستو ملا کر ولیمہ کھلایا۔اور راستے میں تین روز شبہائے عروسی کے طور پر ان کے پاس قیام فرمایا۔اس موقع پر آپ صلی اللہ علیہ وسلم نے ان کے چہرے پر ہرانشان دیکھا دریافت فرمایا یہ کیا ہے۔ کہنے لگیں۔یا رسول اللہ صلی اللہ علیہ وسلم آپ کے خیبرآنے سے پہلے میں نے ایک خواب دیکھا تھا کہ چاند اپنی جگہ سے ٹوٹ کر میری آغوش میں آکر گرا ہے۔ بخدا مجھے آپ صلی اللہ علیہ وسلم کے معاملے کاکوئی تصور بھی نہ تھا۔لیکن میں نے یہ خواب اپنے شوہر سے بیان کیا۔ تو اس نے میرے چہرے پر تھپڑ رسیدکرتے ہوئےکہا یہ بادشاہ جو مدینہ میں ہے تم اس کی آرزو کررہی ہو (الرحیق المختوم)"}],[2055,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"دودھ پلانے سے وہ سارے رشتے حرام ہو جاتے ہیں جو پیدائش سے حرام ہوتے ہیں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” رضاعت کی بنا پر وہ تمام رشتے حرام ہو جاتے ہیں جو ولادت کے تعلق سے حرام ہیں۔ “","f2":"نکاح میں محرمات کی دو قسمیں ہیں۔ ابدی محرمات اور وقتی محرمات ابدی محرمات بسبب نسب کے سات ہیں۔1۔مایئں (اوپر تک) 2۔بیٹیاں (نیچے تک) تین حیققی بہنیں (ماں باپ دونوں کی طرف سے یا صرف باپ کی طرف سے یا ماں کی طرف سے)4۔بھانجیاں۔5بھتیجیاں۔6۔پھوپھیاں 7۔خالایئں۔بدلیل (حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ الخ)(النساء 23) اور ان کے مماثل وہ رشتے جو رضاعت سے قائم ہوتے ہیں۔سب حرام ہیں۔جیسے کہ اس باب کی حدیث میں آیا ہے۔تعلق مصاہرت (سسرال اور ازدواجی تعلق) کی بناء پر حرام ہونے والی خواتین یہ ہیں۔1۔بیویوں کی مایئں۔2۔بیویوں کی بیٹیاں بشرط یہ کہ بیوی سے دخول ہوا ہو۔3۔باپ دادا کی بیویاں 4۔بیٹوں کی بیویاں (نیچے تک)اور یہی رشتے اگر رضاعت سے قائم ہوں تو حرام ہیں۔ ایک محدود وقت تک کے لئے حرام رشتے یہ ہیں۔ بیوی کی بہن اس کی پھوپھی یا بھتیجی یا خالہ اور خالہ یا بھانجی اور آذاد آدمی کےلئے چار بیویاں موجود ہوں۔ تو پانچویں حرام ہے۔(کچھ علماء کے نزدیک) زانیہ تا آنکہ توبہ کرلے۔ اور وہ عورت جسے تین طلاقیں دی ہوں تاآنکہ کسی اور سے نکاح کرلے۔اور وہاں سے فارغ ہو۔ محرمہ اپنے احرام سے حلال ہونے تک اور کوئی مطلقہ جو اپنے ایام عدت میں ہو۔عدم ختم ہونے تک ان کے علاوہ دیگر عورتیں حلال ہیں۔(وَأُحِلَّ لَكُم مَّا وَرَاءَ ذَٰلِكُمْ)(النساء۔24)(دیکھئے۔تیسیرا العلام شرح عمدۃ الاحکام)"}],[2056,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ ام المؤمنین ام حبیبہ رضی اللہ عنہا نے عرض کیا: اللہ کے رسول! کیا آپ کو میری بہن (عزہ) میں رغبت ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو میں کیا کروں\"، انہوں نے کہا: آپ ان سے نکاح کر لیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری بہن سے؟\" انہوں نے کہا، ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم یہ (سوکن) پسند کرو گی؟\"انہوں نے کہا: میں آپ کی اکیلی بیوی تو ہوں نہیں جتنی عورتیں میرے ساتھ خیر میں شریک ہیں ان سب میں اپنی بہن کا ہونا مجھے زیادہ پسند ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ میرے لیے حلال نہیں ہے\" کہا: اللہ کی قسم مجھے تو بتایا گیا ہے کہ آپ درہ یا ذرہ بنت ابی سلمہ (یہ شک زہیر کو ہوا ہے) کو پیغام دے رہے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ام سلمہ کی بیٹی کو؟\" کہا: ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی قسم (وہ تو میری ربیبہ ہے) اگر ربیبہ نہ بھی ہوتی تو وہ میرے لیے حلال نہ ہوتی کیونکہ وہ تو میرے رضاعی بھائی کی بیٹی ہے، مجھے اور اس کے باپ کو ثویبہ نے دودھ پلایا ہے لہٰذا تم اپنی بیٹیوں اور بہنوں کو مجھ پر (نکاح کے لیے) پیش نہ کیا کرو\"۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا سے مروی ہے کہ ام المؤمنین سیدہ ام حبیبہ رضی اللہ عنہا ا نے کہا: اے اللہ کے رسول! کیا آپ میری بہن میں راغب ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو کیا کروں؟ “ کہنے لگیں کہ آپ اس سے نکاح کر لیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تیری بہن سے؟ “ بولیں: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تمہیں یہ پسند ہے؟ “ کہنے لگیں: میں کوئی آپ کے پاس اکیلی تو نہیں ہوں۔ اور اس شراکت میں مجھے یہ زیادہ پسند ہے کہ میری بہن اس خیر میں میری حصہ دار بنے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ میرے لیے حلال نہیں ہے۔ “ وہ کہنے لگیں، قسم اللہ کی! مجھے بتایا گیا ہے کہ آپ نے درہ یا ذرہ (حدیث کے راوی) زہیر کو شک ہے دختر ابوسلمہ کے لیے پیغام بھجوایا ہے۔ آپ صلی اللہ علیہ وسلم نے کہا ” ام سلمہ کی بیٹی کے لیے؟ “ کہنے لگیں: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” قسم اللہ کی! وہ اگر میری ربیبہ نہ بھی ہوتی جو کہ میری پرورش میں ہے، تو بھی میرے لیے حلال نہ ہو سکتی تھی کیونکہ وہ میرے دودھ کے بھائی کی بیٹی (رضاعی بھتیجی) ہے۔ مجھے اور اس کے والد (ابوسلمہ) کو ثوبیہ نے دودھ پلایا تھا۔ سو مجھے اپنی بیٹیوں اور بہنوں کی پیش کش مت کرو۔ “","f2":"ربیبہ بیوی کی وہ بیٹی ہے۔ جو پہلے خاوند سے ہو۔اس سے بھی نکاح حرام ہے۔بشرط یہ کہ اس کی ماں سے ہم بستری ہوگئی ہو۔"}],[2057,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میرے پاس افلح بن ابوقعیس آئے تو میں نے پردہ کر لیا، انہوں نے کہا: مجھ سے پردہ کر رہی ہو، میں تو تمہارا چچا ہوں؟ میں نے کہا: چچا کس طرح سے؟ انہوں نے کہا کہ تمہیں میرے بھائی کی بیوی نے دودھ پلایا ہے، ام المؤمنین عائشہ رضی اللہ عنہا نے کہا: مجھے عورت نے دودھ پلایا ہے نہ کہ مرد نے، پھر میرے یہاں جب رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو میں نے سارا واقعہ آپ سے بیان کر دیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ تمہارے چچا ہیں، وہ تمہارے پاس آ سکتے ہیں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ افلح بن ابی القعیس میرے ہاں آئے تو میں نے ان سے پردہ کیا۔ انہوں نے کہا: مجھ سے پردہ کرتی ہو، حالانکہ میں تمہارا چچا ہوں؟ کہتی ہیں، میں نے کہا: کہاں سے؟ انہوں نے کہا: تم کو میری بھاوج نے دودھ پلایا ہے۔ کہنے لگیں: مجھے تو عورت نے دودھ پلایا ہے، مرد نے نہیں پلایا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے تو میں نے آپ صلی اللہ علیہ وسلم کو یہ بات بتائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ وہ تمہارا چچا ہے، تمہارے پاس آ سکتا ہے۔ “","f2":"دودھ پلانے والی رضاعی ماں ہوئی تو اس کا شوہر رضاعی باپ اور اس کا بھائی ر ضائی چچا ہوا جس طرح دودھ پلانے والی سے تعلق جڑتا ہے۔ویسے ہی اس کے شوہر اور عزیزوں سے بھی جُڑ جاتا ہے۔"}],[2058,"ام المؤمنین عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، ان کے پاس ایک شخص بیٹھا ہوا تھا،(حفص کی روایت میں ہے) آپ صلی اللہ علیہ وسلم کو یہ بات ناگوار گزری، آپ کا چہرہ متغیر ہو گیا (پھر حفص اور شعبہ دونوں کی روایتیں متفق ہیں) عائشہ رضی اللہ عنہا نے کہا: اللہ کے رسول یہ تو میرا رضاعی بھائی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھی طرح دیکھ لو کون تمہارے بھائی ہیں؟ کیونکہ رضاعت تو غذا سے ثابت ہوتی ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی حرمت اس رضاعت سے ثابت ہوتی ہے جو بچپن کی ہو اور دودھ ہی اس کی غذا ہو۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ان کے ہاں آئے تو دیکھا کہ ان کے پاس ایک آدمی بیٹھا ہے۔ (بروایت حفص) آپ صلی اللہ علیہ وسلم کو یہ کیفیت ناگوار گزری اور آپ صلی اللہ علیہ وسلم کا چہرہ بدل گیا۔ (حفص اور محمد بن کثیر دونوں کی متفقہ روایت ہے کہ) سیدہ عائشہ رضی اللہ عنہا ا نے (وضاحت کرتے ہوئے) کہا: اے اللہ کے رسول! یہ میرا رضاعی بھائی ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” ذرا غور کر لیا کرو، تمہارے بھائی کون ہیں۔ رضاعت وہی معتبر ہے جو بھوک کی بنا پر ہو۔ “","f2":"یعنی رضاعت فی الحقیقت وہی معتبر ہے کہ بچے نے اپنی دودھ پینے کی عمر میں دودوھ پیا ہو، اسی سے حرمت ثابت ہوتی ہے دوسال کے بعد بچہ روٹی سالن اور دیگر خوراک سے اپنی بھوک مٹانے لگتا ہے اس لیے جمہور کے نزدیک اس وقت دودھ پینے کا اعتبار نہیں۔\nعلاوہ ازیں رضاعت وہی معتبر ہے جو بھوک کی بنا پر ہو کا مطلب ہے بچے نے دودھ اتنی مقدار میں پیا ہو کہ جس سے اس کی بھوک مٹ گئی ہو اور اس کی وضاحت دسوری حدیث میں اس طرح ہے کہ وہ پانچ مرتبہ دودھ پیے وہ یوں کہ پستان منہ میں لے کر دودھ پیتا رہے اور پھر اسے اپنی مرضی سے چھوڑے۔ یہ ایک مرتبہ پینا (ریک رضعہ) ہے۔ اس طرح پانچ رضعات سے رضاعت سے ثابت ہوگی۔ ایک دو رضعوں سے نہیں(تفصیل کےلیے دیکھیئے: ضمیمہ تفسیر احس البیان بعنوان رضاعت کے چند ضروری مسائل، از حافظ صلاح الدین یوسف)"}],[2059,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، انہوں نے کہا رضاعت وہی ہے جو ہڈی کو مضبوط کرے اور گوشت بڑھائے، تو ابوموسی اشعری رضی اللہ عنہ نے کہا: اس عالم کی موجودگی میں تم لوگ ہم سے مسئلہ نہ پوچھا کرو۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا ” رضاعت وہی معتبر ہے جو ہڈیوں کو مضبوط کرے اور گوشت پیدا کرے۔ “ ابوموسیٰ نے کہا: تم میں جب تک یہ عظیم عالم موجود ہے ہم سے مت کچھ پوچھا کرو۔","f2":"1۔ اس حدیث کا بھی وہی مطلب ہے جو اس سے پہلی حدیث کا تھا یعنی دودھ شیرخوارگی کے ایام میں پیا جائے تو اس کا اعتبار ہوگا اور اس مقدار میں پیے جس سے اس کو جسمانی فائدہ ہو\n2۔ علم میں فاض وفائق شخصیت کے ہوتے ہوئے ادنیٰ کو فتویٰ دینا ان کے اعزاز وراکرام کا یہی تقاضا ہے۔"}],[2060,"اس سند سے بھی ابن مسعود رضی اللہ عنہ سے اسی مفہوم کی حدیث مرفوعاً مروی ہے لیکن اس میں: «شد العظم» کے بجائے «أنشز العظم» کا لفظ ہے۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی بیان کیا اور لفظ «أنشز العظم» ذکر کیا۔"}],[2061,"ام المؤمنین عائشہ اور ام سلمہ رضی اللہ عنہما سے روایت ہے کہ ابوحذیفہ بن عتبہ بن ربیعہ بن عبدشمس نے سالم کو (جو کہ ایک انصاری عورت کے غلام تھے) منہ بولا بیٹا بنا لیا تھا، جس طرح کہ نبی اکرم صلی اللہ علیہ وسلم نے زید رضی اللہ عنہ کو بنایا تھا، اور اپنی بھتیجی ہند بنت ولید بن عتبہ بن ربیعہ سے ان کا نکاح کرا دیا، زمانہ جاہلیت میں منہ بولے بیٹے کو لوگ اپنی طرف منسوب کرتے تھے اور اسے ان کی میراث بھی دی جاتی تھی یہاں تک کہ اللہ تعالی نے اس سلسلہ میں آیت: «ادعوهم لآبائهم» سے «فإخوانكم في الدين ومواليكم» ۱؎ تک نازل فرمائی تو وہ اپنے اصل باپ کی طرف منسوب ہونے لگے، اور جس کے باپ کا علم نہ ہوتا اسے مولی اور دینی بھائی سمجھتے۔ پھر سہلہ بنت سہیل بن عمرو قرشی ثم عامری جو کہ ابوحذیفہ کی بیوی تھیں آئیں اور انہوں نے عرض کیا: اللہ کے رسول! ہم سالم کو اپنا بیٹا سمجھتے تھے، وہ میرے اور ابوحذیفہ کے ساتھ ایک ہی گھر میں رہتے تھے، اور مجھے گھر کے کپڑوں میں کھلا دیکھتے تھے اب اللہ نے منہ بولے بیٹوں کے بارے میں جو حکم نازل فرما دیا ہے وہ آپ کو معلوم ہی ہے لہٰذا اب اس کے بارے میں آپ کا کیا خیال ہے؟ تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"انہیں دودھ پلا دو\"، چنانچہ انہوں نے انہیں پانچ گھونٹ دودھ پلا دیا، اور وہ ان کے رضاعی بیٹے ہو گئے، اسی کے پیش نظر ام المؤمنین عائشہ رضی اللہ عنہا اپنی بھانجیوں اور بھتیجیوں کو حکم دیتیں کہ وہ اس شخص کو پانچ گھونٹ دودھ پلا دیں جسے دیکھنا یا اس کے سامنے آنا چاہتی ہوں گرچہ وہ بڑی عمر کا آدمی ہی کیوں نہ ہو پھر وہ ان کے پاس آتا جاتا، لیکن ام المؤمنین ام سلمہ رضی اللہ عنہا اور دیگر ازواج مطہرات نے اس قسم کی رضاعت کا انکار کیا جب تک کہ دودھ پلانا بچپن میں نہ ہو اور انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے کہا: اللہ کی قسم ہمیں یہ معلوم نہیں شاید یہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے صرف سالم کے لیے رخصت رہی ہو نہ کہ دیگر لوگوں کے لیے ۲؎۔\n§وضاحت\n۱؎ : سورة الأحزاب: ( ۵) ۲؎ : جمہور کی رائے یہی ہے کہ یہ سالم کے ساتھ خاص ہے، کچھ علماء یہ کہتے ہیں کہ خصوصیت کی کوئی دلیل نہ ہونے کی وجہ سے اس حکم کو برقرار مانا جائے اگر واقعی سالم جیسا معاملہ پیش آ جائے اور رضاعی ماں بننے کے لئے دودھ پلایا جائے تو رضاعت ثابت ہو جائے گی۔","صحیح",{"u2":"امہات المؤمنین سیدہ عائشہ رضی اللہ عنہا ا اور ام سلمہ رضی اللہ عنہا ا سے روایت ہے کہ ابوحذیفہ بن عتبہ بن ربیعہ بن عبدشمس نے سالم کو اپنا متبنی (منہ بولا بیٹا) بنایا ہوا تھا اور اس سے اپنی بھتیجی ہند دختر ولید بن عتبہ بن ربیعہ کا نکاح کر دیا تھا۔ وہ ایک انصاری خاتون کا آزاد کر دو غلام تھا جیسے کہ رسول اللہ صلی اللہ علیہ وسلم نے زید رضی اللہ عنہ کو اپنا متبنی بنایا تھا اور جاہلیت کا یہ دستور تھا کہ جسے کوئی اپنا متبنی بنا لیتا تو لوگ اس کو اسی کی نسبت سے پکارا کرتے تھے اور وہ (اپنے منہ بولے باپ کا) وارث بھی بنتا تھا، حتیٰ کہ اللہ عزوجل نے اس بارے میں یہ حکم نازل فرمایا کہ «ادعوهم لآبائهم إلى قوله: فإخوانكم في الدين ومواليكم» ” انہیں ان کے حقیقی باپوں کی نسبت سے پکارا کرو۔ اگر وہ معلوم نہ ہوں تو یہ تمہارے دینی بھائی اور مولیٰ ہیں۔ “ چنانچہ انہیں ان کے باپوں کی طرف لوٹا دیا گیا اور جس کا باپ معلوم نہ ہوا وہ مولیٰ اور دینی بھائی کہلانے لگا۔ الغرض! (ابوحذیفہ رضی اللہ عنہ کی بیوی) سہلہ بنت سہیل بن عمرو قرشی، عامری (رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں) آئی اور کہنے لگی: اے اللہ کے رسول! ہم سالم کو اپنا بیٹا ہی سمجھتے رہے ہیں۔ یہ میرے اور ابوحذیفہ کے ساتھ ایک ہی گھر میں رہتا رہا ہے اور مجھے (گھر میں عام حالت میں) ایک کپڑے میں دیکھتا رہا ہے۔ (کبھی سر کھلا، تو کبھی پنڈلیاں بھی کھل گئیں وغیرہ) اور اللہ عزوجل نے ایسے لوگوں کے بارے میں جو حکم نازل فرمایا ہے وہ آپ جانتے ہی ہیں۔ آپ صلی اللہ علیہ وسلم اس صورت میں کیا فرماتے ہیں؟ نبی کریم صلی اللہ علیہ وسلم نے اس سے کہا ” اس کو (اپنا) دودھ پلا دو۔ “ چنانچہ اس نے اس کو پانچ رضعے (پانچ بار) دودھ پلا دیا۔ اور وہ اس طرح اس کے رضاعی بیٹے کی طرح ہو گیا۔ سو سیدہ عائشہ رضی اللہ عنہا ا اس واقعہ کی بنا پر اپنی بھانجیوں اور بھتیجیوں سے کہا کرتی تھیں کہ فلاں کو پانچ رضعے (پانچ بار) دودھ پلا دو۔ جس کے بارے میں سیدہ عائشہ رضی اللہ عنہا ا کی خواہش ہوتی کہ وہ ان کو دیکھ سکے اور ان کے سامنے آ سکے۔ خواہ وہ بڑی عمر کا بھی ہوتا۔ چنانچہ وہ اس کے بعد ان کے سامنے آ جایا کرتا تھا۔ (اور یہ اس سے پردہ نہ کرتیں) مگر ام سلمہ رضی اللہ عنہا ا اور دیگر تمام امہات المؤمنین نے اس کو قبول نہیں کیا کہ ایسی رضاعت کی بنا پر کوئی شخص ان کے سامنے آئے (اور وہ اس سے پردہ نہ کریں) الا یہ کہ اس نے پالنے میں (دو سال کی عمر کے دوران میں) دودھ پیا ہوتا۔ انہوں نے عائشہ رضی اللہ عنہا ا سے کہا: قسم اللہ کی! ہمیں نہیں معلوم، شاید یہ نبی کریم صلی اللہ علیہ وسلم کی طرف سے سالم کے لیے بمقابلہ دوسرے لوگوں کے خاص رخصت تھی۔","f2":"1: قرآن مجید کی تعلیمات اٹل ہیں اورواجب العمل بھی۔ ان میں چون وچرا کی کوئی گنجائش نہیں مگر رسول صلی اللہ علیہ وسلم کے بیان وتوضیح کے ساتھ جو بسند صحیح ہم تک پہنچ جائے۔\n2:جمہورعلما ء کے نزدیک دو سال کی عمر کے بعد دودھ پینے پلانے سے حرمت رضاعت ثابت نہیں ہوتی،کیونکہ حرمت ثابت کرنے والی رضاعت وہ ہے جو مدت رضاعت کے اندر ہو جو کہ دوسال ہے،کم از کم پانچ رضعات ہوں،(رضعت یہ ہے کہ بچہ چھاتی کو منہ میں لے اور دودھ چوسے تو جب تک وہ پستان کو منہ میں لے کر پیتا رہے گا یہ ایک رضعت کہلائے گی،خواہ یہ مدت طویل ہو یاقلیل)اور جوآنتوں کو پھاڑے یعنی اس کی خوراک صرف دودھ ہو جس سے بچہ پلے اور بڑھے مگر حضرت عائشہ رضی اللہ لیث بن سعد،علطاءاور فقہائے اہل ظاہر دوسال کے بعد بھی حرمت رضاعت کے قائل ہیں ان کی دلیل حضرت سالم کا واقعہ ہے لیکن دوسری امہات المومنین کا بیان ہے کہ حضرت سالم کے ساتھ خاص ہے،جیسا کہ اس حدیث میں ہے۔ امام ابن تیمیہ اور شیخ شوکانی رحمہ اللہ اس حدیث کی بابت لکھتے ہیں کہ عمومی حالات میں تو نہیں مگر کہیں خاص اضطراری احوال میں اس پر عمل کی گنجائش ہے۔\n3:اس سے یہ بھی ثابت ہوا کہ چہرہ چھپانا پردے کا لازمی حصہ ہے اگر چہ چھپانا ضروری نہ تھا تو اس قدر ترددکی ضرورت ہی کیا تھی۔\n4:(رضعہ) کا معنی دیل باب میں دیکھیے۔"}],[2062,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ اللہ تعالی نے جو چیزیں نازل کی ہیں ان میں «عشر رضعات يحرمن» والی آیت بھی تھی پھر یہ آیت «خمس معلومات يحرمن» والی آیت سے منسوخ ہو گئی، اس کے بعد نبی اکرم صلی اللہ علیہ وسلم کی وفات ہو گئی اور یہ آیتیں پڑھی جا رہی تھیں (یعنی بعض لوگ پڑھتے تھے پھر وہ بھی متروک ہو گئیں) ۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے منقول ہے کہ اللہ عزوجل نے قرآن میں پہلے یہ نازل کیا تھا کہ دس رضعات سے حرمت ثابت ہوتی ہے۔ (دس بار دودھ پینے سے) پھر اسے پانچ رضعات سے منسوخ کر دیا۔ اور جب رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی تو یہ الفاظ قرآن میں قرآت کیے جاتے تھے۔","f2":"1:احادیث میں واردلفظ(الرضعہ) کا لغوی واصطلاحی معنی یہ ہے بچہ پستان کو اپنے منہ میں لےکر دودہ چوسنے لگے اور پھر اپنی خوشی سے بغیر کسی عارض کے چھوڑدے۔ تو یہ ایک رضعہ ہے۔ (المصہ) کا بھی یہی مفہوم ہے۔\n2:حضرت عائشہ رضی اللہ کے کہنے کا مقصد یہ ہے کہ نہ نسخ نبی صلی اللہ علیہ وسلم کی وفات سے تھوڑی ہی مدت پہلے نازل ہوا تھاکہ کچھ لوگ،جنہیں اطلاع نہ ملی تھی یہ الفاظتلاوت کرتے تھے مگر بعدازاں ان کی قراءت منسوخ کردی گئی مگر حکم باقی رہا۔"}],[2063,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک یا دو چوس حرمت ثابت نہیں کرتا\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایک بار چوسنا یا دو بار چوسنا حرام نہیں کرتا۔ “","f2":"بلکہ جب تک پانچ مرتبہ (مذکورہ طریقے سے) دودھ پیے،حرمت رضا عت ثابت نہیں ہو گی۔"}],[2064,"حجاج رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! دودھ پلانے کا حق مجھ سے کس طرح ادا ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"لونڈی یا غلام (دودھ پلانے والی کو خدمت کے لیے دے دینے) سے\"۔","ضعیف",{"u2":"جناب حجاج بن حجاج اپنے والد سے روایت کرتے ہیں، کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! میں دودھ پلانے کا حق کس طرح ادا کر سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ایک غلام یا لونڈی (لے کر اسے دے دے)۔ “ نفیلی نے کہا حجاج بن حجاج، بنو اسلم سے تعلق رکھتا ہے اور یہ اسی کے لفظ ہیں۔","f2":"عربوں میں یہ رواج تھا کہ اپنے بچوں کو دودھ پلانے کے لئے قرب وجوار\nکے دیہاتوں میں اجرت پر بھیج دیا کرتےتھے،علاوہ ازیں وہ مقررہ اجرت کے علاوہ دودہ چھڑانے پر (مرضبعہ) دودھ پلانے والی انا کو کو ئی انعام دینا بھی پسند کرتے تھے، اس حدیث میں اسی کا حق مرضعہ کی بابت بیان کیا گیا ہے۔"}],[2065,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پھوپھی کے نکاح میں رہتے ہوئے بھتیجی سے نکاح نہیں کیا جا سکتا، اور نہ بھتیجی کے نکاح میں رہتے ہوئے پھوپھی سے نکاح درست ہے، اسی طرح خالہ کے نکاح میں رہتے ہوئے بھانجی سے نکاح نہیں کیا جا سکتا ہے، اور نہ ہی بھانجی کے نکاح میں رہتے ہوئے خالہ سے نکاح درست ہے، غرض یہ کہ چھوٹی کے رہتے ہوئے بڑی سے اور بڑی کے رہتے ہوئے چھوٹی سے نکاح جائز نہیں ہے ۱؎\"۔\n§وضاحت\n۱؎ : ہاں اگر ایک مر جائے یا اس کو طلاق دیدے تو دوسری سے شادی کر سکتا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نہ نکاح کی جائے کوئی عورت اس کی پھوپھی پر۔ نہ پھوپھی اس کی بھتیجی پر۔ اور نہ نکاح کی جائے کوئی عورت اس کی خالہ پر۔ نہ خالہ اس کی بھانجی پر۔ نہ نکاح کی جائے بڑی چھوٹی پر اور نہ چھوٹی بڑی پر۔ “","f2":"ایک وقت میں پھوپھی بھتیجی یا خالہ بھانجی (یا ان کے برعکس) کو جمع کرنا حرام ہے اور یہ حرمت موقت(عارضی) ہے،ابدی نہیں۔ مختلف اوقات میں بعدازطلاق یا وفات نکاح کرلینے میں کوئی حرج نہیں اور آخری جملہ میں بڑی عورت سے مراد یا تو عمر میں بڑی ہے جو کہ عرفاماں،خالہ اور پھوپھی وغیر ہ کا احترام پاتی ہے جبکہ چھوٹی لڑکی بیٹی کی طرح سمجھی جاتی ہے۔ یعنی ان سے نکاح نہیں ہو سکتا۔ یارتبے کا فرق مراد ہے،پھوپھی اور خالہ بڑی ہوتی ہیں جب کہ بھتیجی اور بھانجی بالعموم چھوٹی ہوتی ہیں۔ اس صورت میں یہ پہلی بات کی بہ اندازدیگر تاکید ہے۔"}],[2066,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خالہ اور بھانجی اور اسی طرح پھوپھی اور بھتیجی کو بیک وقت نکاح میں رکھنے سے منع فرمایا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا ہے کہ عورت اور اس کی خالہ یا عورت اور اس کی پھوپھی کو جمع کیا جائے۔"}],[2067,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے پھوپھی اور خالہ کو (نکاح میں) جمع کرنے، اسی طرح دو خالاؤں اور دو پھوپھیوں کو (نکاح میں) جمع کرنے سے منع فرمایا ہے۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے حرام کیا اس بات کو کہ جمع کی جائے پھوپھی اور خالہ یا دو خالائیں اور دو پھوپھیاں۔"}],[2068,"عروہ بن زبیر نے ام المؤمنین عائشہ رضی اللہ عنہا سے اللہ تعالی کے فرمان: «وإن خفتم ألا تقسطوا في اليتامى فانكحواء ما طاب لكم من النساء سورة النساء» ۱؎ کے بارے میں دریافت کیا تو ام المؤمنین عائشہ رضی اللہ عنہا نے کہا: بھانجے! اس سے وہ یتیم لڑکی مراد ہے، جو اپنے ایسے ولی کی پرورش میں ہو جس کے مال میں وہ شریک ہو اور اس کی خوبصورتی اور اس کا مال اسے بھلا لگتا ہو اس کی وجہ سے وہ اس سے بغیر مناسب مہر ادا کئے نکاح کرنا چاہتا ہو (یعنی جتنا مہر اس کو اور کوئی دیتا اتنا بھی نہ دے رہا ہو) چنانچہ انہیں ان سے نکاح کرنے سے روک دیا گیا، اگر وہ انصاف سے کام لیں اور انہیں اونچے سے اونچا مہر ادا کریں تو نکاح کر سکتے ہیں ورنہ فرمان رسول ہے کہ ان کے علاوہ جو عورتیں انہیں پسند ہوں ان سے نکاح کر لیں۔ عروہ کا بیان ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے اس آیت کے نزول کے بعد یتیم لڑکیوں کے بارے میں حکم دریافت کیا تو یہ آیت نازل ہوئی: «ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن ما كتب لهن وترغبون أن تنكحوهن» ۲؎ ام المؤمنین عائشہ نے کہا کہ اس آیت میں اللہ تعالی نے جو یہ فرمایا ہے کہ وہ ان پر کتاب میں پڑھی جاتی ہیں اس سے مراد پہلی آیت ہے جس میں اللہ تعالی نے فرمایا ہے: «وإن خفتم أن لا تقسطوا في اليتامى فانكحواء ما طاب لكم من النساء» اور اس دوسری آیت میں اللہ تعالی کے قول: «وترغبون أن تنكحوهن» سے یہی غرض ہے کہ تم میں سے کسی کی پرورش میں کم مال والی کم حسن والی یتیم لڑکی ہو تو وہ اس کے ساتھ نکاح سے بے رغبتی نہ کرے چنانچہ انہیں منع کیا گیا کہ مال اور حسن کی بنا پر یتیم لڑکیوں سے نکاح کی رغبت کریں، ہاں انصاف کی شرط کے ساتھ درست ہے۔ یونس نے کہا کہ ربیعہ نے اللہ کے فرمان: «وإن خفتم أن لا تقسطوا في اليتامى» کا مطلب یہ بتایا ہے کہ اگر تمہیں یتیم لڑکیوں کے بارے میں انصاف نہ کر پانے کا ڈر ہو تو انہیں چھوڑ دو (کسی اور عورت سے نکاح کر لو) میں نے تمہارے لیے چار عورتوں سے نکاح جائز کر دیا ہے۔\n§وضاحت\n۱؎ : اگر تمہیں یتیم لڑکیوں کے بارے میں انصاف نہ کر پانے کا ڈر ہو تو تم ان عورتوں سے نکاح کر لو جو تمہیں اچھی لگیں (سورۃ النساء: ۳) ۲؎ : لوگ آپ سے عورتوں کے بارے میں حکم دریافت کرتے ہیں آپ کہہ دیجئے کہ خود اللہ ان کے بارے میں حکم دے رہا ہے ، اور قرآن کی وہ آیتیں جو تم پر ان یتیم لڑکیوں کے بارے میں پڑھی جاتی ہیں ، جنہیں تم ان کا مقرر حق نہیں دیتے اور انہیں اپنے نکاح میں لانے کی رغبت رکھتے ہو (سورۃ النساء: ۱۲۶)","صحیح",{"u2":"جناب عروہ بن زبیر رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ میں نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے آیت کریمہ «وإن خفتم ألا تقسطوا في اليتامى فانكحوا طاب لكم من النساء سورة النساء» کی تفسیر دریافت کی۔ تو انہوں نے کہا، بھانجے میرے! یہ اس یتیم لڑکی کے متعلق ہے جو اپنے کسی ولی کی سرپرستی میں ہو اور (مالدار غنیہ ہونے کی وجہ سے) اپنے ولی کے مال میں حصہ دار بن گئی ہو۔ پھر اس ولی کو اس لڑکی کا مال و جمال پسند آ جائے اور اس کی خواہش ہو کہ اس سے نکاح کر لے مگر حق مہر میں انصاف نہ کرے اور اس قدر نہ دینا چاہے جو کوئی غیر اسے دے، تو (ایسی صورت میں) ان لوگوں کو ان کے ساتھ نکاح سے منع کر دیا گیا الا یہ کہ ان سے عدل کریں اور مہر ان کے اعلیٰ معیار کے مطابق دیں (تو جائز ہے) انہیں یہ حکم دیا گیا کہ (اگر یہ اندیشہ ہو تو) ان کے علاوہ دیگر عورتوں سے نکاح کر لو جو تمہیں پسند آئیں۔ عروہ نے کہا: عائشہ رضی اللہ عنہا ا نے بیان کیا کہ پھر لوگوں نے اس آیت کے بعد جو ان کے بارے میں اتری تھی، رسول اللہ صلی اللہ علیہ وسلم سے سوالات کیے (اور رخصت چاہی) تو اللہ تعالیٰ نے یہ نازل فرمایا «ويستفتونك في النساء قل الله يفتيكم فيهن و يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن كتب لهن وترغبون أن تنكحوهن» ” اے پیغمبر! لوگ آپ سے (یتیم) عورتوں کے بارے میں فتویٰ طلب کرتے ہیں۔ آپ ان سے کہیں کہ ان کے بارے میں اللہ تمہیں فتویٰ دیتا ہے اور قرآن کی وہ آیتیں بھی (وضاحت کرتی ہیں) جو تم پر ان یتیم عورتوں (لڑکیوں) کے بارے میں پڑھی جاتی ہیں جن کے مقررہ حقوق (میراث وغیرہ) تم دیتے نہیں اور ان سے نکاح کرنے کی رغبت رکھتے ہو۔ “ سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ یہ جو اللہ نے ذکر کیا ہے کہ وہ تم پر کتاب میں پڑھی جاتی ہے، اس سے مراد وہ پہلے والی آیت ہے جس میں اللہ تعالیٰ نے فرمایا ہے «وإن خفتم ألا تقسطوا في اليتامى فانكحوا طاب لكم من النساء» عائشہ رضی اللہ عنہا ا نے کہا کہ دوسری آیت میں جو آیا ہے «وترغبون أن تنكحوهن» اس سے مراد ” اعراض “ ہے۔ یہ اعراض آدمی اپنی زیر سر پرستی یتیم لڑکی سے کرتا تھا جب کہ وہ قلیل المال ہوتی اور حسن و جمال میں بھی معیاری نہ ہوتی۔ تو انہیں منع کیا گیا ہے کہ یتیم لڑکیوں کے مال و جمال کے حریص بن کر ان سے نکاح مت کرو الا یہ کہ عدل و انصاف کے تقاضے پورے کرو (اور یہ تفصیل نازل ہونے کی وجہ یہی ہے کہ لوگ ان سے اعراض کرنے لگے تھے) یونس سے بیان کیا کہ جناب ربیعہ الرای نے «وإن خفتم ألا تقسطوا في اليتامى» کی توضیح میں کہا کہ اللہ فرماتا ہے ” ظلم کا اندیشہ ہو تو انہیں چھوڑ دو، میں نے تمہارے لیے چار عورتیں حلال کی ہوئی ہیں۔ “","f2":"1: حدیث کا باب سے تعلق یہ ہے کہ اگر انسان اپنی زیر تولیت کسی یتیم بچی سے شرعی عدل وانصاف کے معیار پر پورا نہ اتر سکتا ہو تو اس سے نکاح نہ کرے خواہ پہلا ہو یا کسی دوسری بیوی کے ہوتے ہوئے ہو۔ اس میں تو اور بھی اندیشہ ہے کہ یتیم بچی ہونے کی وجہ سے اسے گھر کی لونڈی اور خادمہ ہی بنا لیا جائے۔\n2:فہم قرآن کے لئے شان نزول کی ایک خاص اہمیت ہے بشرطیکہ صحیح سند سے ثابت ہو۔ اسی طرح ہر آیت کے لئےشان نزول تلاش کرنا بھی تکلف بارد ہے۔"}],[2069,"علی بن حسین کا بیان ہے وہ لوگ حسین بن علی رضی اللہ عنہ کی شہادت کے زمانے میں یزید بن معاویہ کے پاس سے مدینہ آئے تو ان سے مسور بن مخرمہ رضی اللہ عنہ ملے اور کہا: اگر میرے لائق کوئی خدمت ہو تو بتائیے تو میں نے ان سے کہا: نہیں، انہوں نے کہا: کیا آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کی تلوار دے سکتے ہیں؟ کیونکہ مجھے اندیشہ ہے کہ لوگ آپ سے اسے چھین لیں گے، اللہ کی قسم! اگر آپ اسے مجھے دیدیں گے تو اس تک کوئی ہرگز نہیں پہنچ سکے گا جب تک کہ وہ میرے نفس تک نہ پہنچ جائے ۱؎۔ علی بن ابوطالب رضی اللہ عنہ نے فاطمہ رضی اللہ عنہا کے ہوتے ہوئے ابوجہل کی بیٹی ۲؎ کو نکاح کا پیغام دیا تو میں نے اس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم کو اپنے اسی منبر پر خطبہ دیتے ہوئے سنا، اس وقت میں جوان تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"فاطمہ میرا ٹکڑا ہے، مجھے ڈر ہے کہ وہ دین کے معاملہ میں کسی آزمائش سے دو چار نہ ہو جائے\"، پھر آپ صلی اللہ علیہ وسلم نے بنی عبد شمس میں سے اپنے ایک داماد کا ذکر فرمایا، اور اس رشتہ دامادی کی خوب تعریف کی، اور فرمایا: \"جو بات بھی اس نے مجھ سے کی سچ کر دکھائی، اور جو بھی وعدہ کیا پورا کیا، میں کسی حلال کو حرام اور حرام کو حلال قطعاً نہیں کر رہا ہوں لیکن اللہ کی قسم، اللہ کے رسول کی بیٹی اور اللہ کے دشمن کی بیٹی ہرگز ایک جگہ جمع نہیں ہو سکتی\"۔\n§وضاحت\n۱؎ : جب تک میری جان میں جان رہے گی اسے کوئی مجھ سے نہیں لے سکتا۔ ۲؎ : امام ابن قیم کہتے ہیں کہ اس حدیث میں ہر طرح سے رسول اکرم صلی اللہ علیہ وسلم کو ایذاء پہنچانے کی حرمت ہے چاہے وہ کسی مباح کام کرنے سے ہو، اگر اس کام سے رسول اکرم صلی اللہ علیہ وسلم کو ایذاء پہنچے تو ناجائز ہو گا، ارشاد باری ہے: «وما كان لكم أن تؤذوا رسول الله» ۔","صحیح",{"u2":"جناب ابن شہاب زہری سے مروی ہے کہ جناب علی بن حسین (بن علی بن ابی طالب) نے بیان کیا کہ ہم لوگ سیدنا حسین بن علی رضی اللہ عنہ کی شہادت کے بعد یزید بن معاویہ کے پاس سے مدینہ منورہ پہنچے، تو مجھے مسور بن مخرمہ رضی اللہ عنہ ملے اور کہا، میرے لائق کوئی خدمت ہو تو حکم فرمائیں؟ میں نے کہا: نہیں۔ انہوں نے کہا: کیا آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کی تلوار عنایت فر سکتے ہیں؟ مجھے اندیشہ ہے کہ اس کے متعلق قوم کہیں آپ پر غالب نہ آ جائے۔ اور قسم اللہ کی! اگر آپ مجھے یہ عنایت فر دیں تو میرے جیتے جی کبھی کوئی اس تک نہ پہنچ سکے گا۔ (رسول اللہ صلی اللہ علیہ وسلم کی عزت اور آپ کی عترت کی حفاظت اور دفاع ہم پر لازم ہے۔ اس سلسلے کا ایک واقعہ یہ ہے کہ) سیدنا علی بن ابی طالب رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا ا کے ہوتے ہوئے ابوجہل کی بیٹی کو شادی کا پیغام بھیج دیا۔ میں نے اس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم کو منبر پر خطبہ دیتے ہوئے سنا جب کہ میں ان دنوں بالغ تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” فاطمہ مجھ سے ہے اور مجھے فکر ہے کہ کہیں اس کے دین میں کوئی امتحان نہ آ جائے۔ “ پھر آپ صلی اللہ علیہ وسلم نے بنی عبدشمس (بنی امیہ) میں سے اپنے داماد (سیدنا ابوالعاص بن الربیع) کا ذکر کیا اور اس کی مدح فرمائی اور خوب فرمائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس نے مجھ سے بات کی تو سچی کی، وعدہ کیا تو پورا کیا۔ میں کسی حلال کو حرام یا حرام کو حلال نہیں کرتا۔ لیکن قسم اللہ کی! اللہ کے رسول اللہ کی بیٹی اور اللہ کے دشمن کی بیٹی کبھی بھی ایک جگہ جمع نہیں ہو سکتیں۔ “","f2":"1: حضرت فاطمہ رضی اللہ کی اپنے گھر میں اذیت رسول صلی اللہ علیہ وسلم کے باعث اذیت ہوتی جوحضرت علی رضی اللہ کے لئے ہلاکت کا باعث ہوتی۔ اس لیے انہیں بطورخاص اس رشتے سے منع کر دیا گیا اور یہ واقعہ ثابت کرتا ہے کہ رسول صلی اللہ علیہ وسلم کو کسی طرح سے بھی اذیت دینا حرام ہے خواہ وہ فعل اصل میں مباح ہی ہو۔ قرآن مجید میں ہے کہ (وماکان لکم ان توذورسول اللہ)(الااحزاب 35) تمہیں کسی طرح جائز نہیں کہ اللہ کے رسول کو اذیت دو۔\n2:عترت رسول صلی اللہ علیہ وسلم کو کسی طرح سے دکھ دینا اور ان کی ہتک کرنا،رسول صلی اللہ علیہ وسلم کی ناراضی کا باعث ہے جو کہ اللہ تعالی کی ناراضی کو مستلزم ہے۔ مگر لازمی شرط ہے کہ آل رسول کہلانے والے اس کی شریعت کے حامل بھی ہوں۔\n3:حضرت فاطمہ رضی اللہ رسول صلی اللہ علیہ وسلم کی محبوب ترین صاحبزادی تھیں اور وہ اس امت کی عورتوں کی سردار ہیں۔\n4:جائز ہے کہ انسان اپنی بیٹی کی وجہ سے غیرت اور غصے میں آئے لیکن اگر کوئی شخص اپنے آپ کو رسول صلی اللہ علیہ وسلم اور حضرت فاطمہ پر قیاس کرنے لگے تو یہ ایک لغوقیاس ہے۔\n5:صاحب فضل داماد کی مدح وتوصیف کی جاسکتی ہے۔"}],[2070,"ابن ابی ملیکہ سے یہی حدیث مروی ہے اس میں ہے: تو علی رضی اللہ عنہ نے اس نکاح سے خاموشی اختیار کر لی۔","صحیح",{"u2":"معمر نے زہری سے بواسطہ عروہ روایت کیا اور دوسری سند میں ایوب سے بواسطہ ابن ابی ملیکہ (اسی طرح) بیان کیا (البتہ اس روایت میں یہ اضافہ کیا کہ) سیدنا علی رضی اللہ عنہ اس (دوسرے) نکاح سے خاموش ہو گئے۔"}],[2071,"مسور بن مخرمہ رضی اللہ عنہما کا بیان ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر فرماتے ہوئے سنا: \"ہشام بن مغیرہ کے بیٹوں نے ۱؎ اپنی بیٹی کا نکاح علی بن ابی طالب سے کرانے کی اجازت مجھ سے مانگی ہے تو میں اجازت نہیں دیتا، میں اجازت نہیں دیتا، میں اجازت نہیں دیتا، ہاں اگر علی ان کی بیٹی سے نکاح کرنا چاہتے ہیں تو میری بیٹی کو طلاق دے دیں، کیونکہ فاطمہ میرا ٹکڑا ہے جو اسے برا لگتا ہے وہ مجھے بھی برا لگتا ہے اور جس چیز سے اسے تکلیف ہوتی ہے مجھے بھی ہوتی ہے\"۔\n§وضاحت\n۱؎ : ہشام بن مغیرہ کے بیٹوں سے مراد ابوالحکم عمرو بن ہشام جسے ابوجہل کہتے ہیں کے بھائی حارث بن ہشام اور سلمہ بن ہشام ہیں جو فتح مکہ کے سال اسلام لے آئے تھے اور اس میں ابوجہل کے بیٹے عکرمہ بھی داخل ہیں جو سچے مسلمان تھے۔","صحیح",{"u2":"جناب مسور بن مخرمہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا آپ صلی اللہ علیہ وسلم منبر پر کھڑے ارشاد فر رہے تھے ” بنی ہشام بن مغیرہ نے اجازت چاہی ہے کہ علی بن ابی طالب کو اپنی بیٹی بیاہ دیں۔ تو میں اس کی اجازت نہیں دیتا ‘ پھر اجازت نہیں دیتا ‘ پھر اجازت نہیں دیتا۔ ہاں اگر ابن ابی طالب چاہے تو میری بیٹی کو طلاق دے دے اور ان کی لڑکی سے نکاح کر لے۔ بلاشبہ میری صاحبزادی میرے دل کا ٹکڑا ہے۔ مجھے برا لگتا ہے جو اسے برا لگے۔ اور مجھے اذیت ہوتی ہے اس سے ‘ جس سے اس کو اذیت ہو۔ “ احمد بن یونس کی سند میں «أخبرنا» کا صیغہ استعمال ہوا ہے۔","f2":"اس میں نبی صلی اللہ علیہ وسلم نے وہ وجہ بیان فرمادی جس کی بنا پر آپ نے حضرت علی رضی اللہ کو دوسری شادی کی اجازت نہیں دی۔ اور وہ یہ کہ دوسرا نکاح حضرت فاطمہ رضی اللہ کے لئے اذیت کا باعث ہو سکتا تھا جیسا کہ عام طور پر ہو تا ہے اگر ایساہوتا تو اس سے پھر رسول صلی اللہ علیہ وسلم کو بھی اذیت پہنچتی،جو حضرت علی کے ایمان کے لئے خطرے کا باعث ہوتی۔"}],[2072,"ابن شہاب زہری کہتے ہیں کہ ہم عمر بن عبدالعزیز کے پاس تھے تو عورتوں سے نکاح متعہ ۱؎ کا ذکر ہم میں چل پڑا، تو ان میں سے ایک آدمی نے جس کا نام ربیعہ بن سبرہ تھا کہا: میں اس بات کی گواہی دیتا ہوں کہ میرے والد نے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کے موقع پر متعہ سے منع کر دیا ہے ۲؎۔\n§وضاحت\n۱؎ : متعین مدت کے لئے نکاح کرنے کو نکاح متعہ کہتے ہیں۔ ۲؎ : یہ نکاح کئی بار حلال ہوا پھر آخر میں حرام ہو گیا، اور اب اس کی حرمت قیامت تک کے لئے ہے، ائمہ اسلام اور علماء سنت کا یہی مذہب ہے۔","",{"u2":"زہری رضی اللہ عنہ کہتے ہیں کہ ہم سیدنا عمر بن عبدالعزیز رضی اللہ عنہ کی مجلس میں تھے کہ عورتوں سے نکاح متعہ کا ذکر چل پڑا۔ تو ربیع بن سبرہ نامی ایک شخص نے کہا: میں اپنے والد (سبرہ) کے متعلق گواہی دیتا ہوں کہ انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے حجۃ الوداع میں منع فر دیا تھا۔"}],[2073,"سبرہ بن معبد جہنی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے عورتوں سے نکاح متعہ کو حرام قرار دیا ہے۔","صحیح",{"u2":"ربیع بن سبرہ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عورتوں سے متعہ کرنے کو حرام فر دیا ہے۔","f2":"جاہلیت کے نکاحوں میں سے ایک نکاح متعہ بھی تھا وہ اس طرح کہ لوگ ایک متعین وقت کے لئے نکاح کر لیتے تھے مگر اسلام آنے کے بعد غزوہ خیبر کے وقت اسے حرام کیا گیا پھر اس کی رخصت دے دی گئی مگر فتح مکہ میں ابدی طور پر حرام کر دیا گیا۔ روافض کے علاوہ دیگر ائمہ کا اس کی حرکت پر اتفاق ہے روافض نے متعہ کے جواز کو حضرت علی رضی اللہ کی جانب سے منسوب کیا ہے،جبکہ صحیح بخاری میں حضرت علی رضی اللہ سے منقول ہے کہ انہوں نے بصراحت کہا کہ نکاح متعہ منسوخ ہے۔"}],[2074,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نکاح شغار سے منع فرمایا۔ مسدد نے اپنی حدیث میں اتنا اضافہ کیا ہے: میں نے نافع سے پوچھا: شغار ۱؎ کیا ہے؟ انہوں نے کہا آدمی کسی کی بیٹی سے نکاح (بغیر مہر کے) کرے، اور اپنی بیٹی کا نکاح اس سے بغیر مہر کے کر دے اسی طرح کسی کی بہن سے (بغیر مہر کے) نکاح کرے اور اپنی بہن کا نکاح اس سے بغیر مہر کے کر دے ۲؎۔\n§وضاحت\n۱؎ : نکاح شغار ایک قسم کا نکاح تھا، جو جاہلیت میں رائج تھا، جس میں آدمی اپنی بیٹی یا بہن کی اس شرط پر دوسرے سے شادی کر دیتا کہ وہ بھی اپنی بیٹی یا بہن کی اس سے شادی کر دے، گویا اس کو مہر سمجھتے تھے، اسلام نے اس طرح کے نکاح سے منع کردیا، ہاں اگر شرط نہ ہو، اور الگ الگ مہر ہو تو جائز ہے۔ وضاحت ۲؎ : یعنی ہر ایک اپنی بیٹی یا بہن ہی کو اپنی بیوی کا مہر قرار دے۔","صحیح",{"u2":"جناب نافع رضی اللہ عنہ، سیدنا ابن عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ ” رسول اللہ صلی اللہ علیہ وسلم نے نکاح شغار سے منع فرمایا ہے۔ “ مسدد کی روایت میں یہ مزید ہے کہ میں (عبیدا اللہ) نے نافع سے پوچھا کہ ” شغار “ سے کیا مراد ہے؟ انہوں نے کہا: انسان کسی کی بیٹی سے نکاح کرے ‘ اور اس کے ساتھ اپنی بیٹی کا نکاح کر دے مگر ان کے مابین حق مہر نہ ہو یا انسان کسی کی بہن سے نکاح کرے اور اس سے اپنی بہن کا نکاح کر دے اور حق مہر نہ ہو۔","f2":"دورجاہلیت میں یہ نکاح شغار کے نام سے رائج تھا، اس صورت یہ تھی کہ ایک شخص اپنی بہن،بیٹی کی اس شرط پر دوسرے شخص سے شادی کرتا کہ وہ شخص بھی اپنی بہن یا بیٹی کی اس شخص سے شادی کرے اور ایک کا مہر دوسرے کا نکاح ہوتا،علیحدہ سے مہر ادا نہ کیا جاتا۔ گویا یہ نکاح ایسا تھا کہ جیسا کہ آج کل بٹے یا ادلے بدلے (بٹاسٹا)کے طور پر بعض جگہ نکاح کیے جاتے ہیں ایسا نکاح جس میں مہر نہ ہو تو یہ بابکل ناجائز اور حرام ہے اگر ہر لڑکی کا حق مہر الگ سے مقرر کیا گیا ہو تو نکاح کے صحیح ہونے میں کوئی شبہ نہیں مگر بدلے کی یہ شرط اور اس طرح کے نکاح بالعموم خاندانوں میں فساد کا ذریعہ بنتے ہیں اس لیے کچھ علما متشدد ہیں اور کہتے ہیں کہ خواہ حق مہر بھی کر لیا گیا ہو تو ناجائز ہے مگر یہ فتوی محل نظر ہے۔ درج ذیل حدیث کے واقعہ میں آرہاہے کہ عباس بن عبداللہ بن عباس اورعبدالرحمن بن حکم نے اس قسم کا نکاح (شغار) کیا اور اس نکاح ہی کو حق مہر قرار دیا تو حضرت معاویہ رضی اللہ نے ان میں تفریق کردوادی۔"}],[2075,"ابن اسحاق سے روایت ہے کہ عبدالرحمٰن بن ہرمزاعرج نے مجھ سے بیان کیا کہ عباس بن عبداللہ بن عباس نے اپنی بیٹی کا نکاح عبدالرحمٰن بن حکم سے کر دیا اور عبدالرحمٰن نے اپنی بیٹی کا نکاح عباس سے کر دیا اور ان دونوں میں سے ہر ایک نے دوسرے سے اپنی بیٹی کے شادی کرنے کو اپنی بیوی کا مہر قرار دیا تو معاویہ نے مروان کو ان کے درمیان جدائی کا حکم لکھ کر بھیجا اور اپنے خط میں یہ بھی لکھا کہ یہی وہ نکاح شغار ہے جس سے اللہ کے رسول صلی اللہ علیہ وسلم نے منع فرمایا ہے۔","حسن",{"u2":"عبدالرحمٰن بن ہرمزالاعرج بیان کرتے ہیں کہ عباس بن عبداللہ بن عباس نے عبدالرحمٰن بن حکم سے اپنی بیٹی کا نکاح کر دیا اور عبدالرحمٰن نے اپنی بیٹی کا نکاح ان سے کر دیا اور دونوں نے اس نکاح ہی کو حق مہر ٹھہرایا تھا۔ تو سیدنا معاویہ رضی اللہ عنہ نے مروان کو یہ حکم لکھ بھیجا کہ وہ ان کے مابین تفریق کرا دے۔ انہوں نے اپنے خط میں کہا کہ یہی وہ شغار ہے جس سے رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے۔","f2":"1(وکا نا جعلا صداقا)میں (جعلا) کا مفعول اول محذوف ہے جیسے کہ مواردالظمان الی زوئد ابن حبان کی اسی روایت کے الفاظ میں صراحت ہے (وقد کان جعلاہ صداقا) (مواردالظمان،باب ماجاءفی الشعار،حدیث1268) اس بات سے واضح ہو جاتی ہے کہ حضرت معاویہ کے حکم تفریق کی وجہ مشروط نکاح ہی کو حق مہر قرار دینا تھا،نہ کہ حق مہر مقرر کر دینے کے باوجود تبادلہ اختین یابنتین۔\n2:نکاح شغارکے ممنوع ہونے پر سب کا اتفاق ہے اگر کوئی کرے تو شافعی رحمہ اللہ اسے باطل کہتے ہیں۔ احمد اسحق اور ابو عبید رحمہ اللہ سے بھی یہی مروی ہے امام مالک رحمہ اللہ کا قول ہے کہ اسے فسخ کرا دیا جائے،خواہ دخول ہوا ہوجبکہ ان کا یاک قول یہ بھی ہے کہ قبل ازخول فسخ کرادیا جائے نہ کہ بعد از خول اور ایک جماعت علما ءکے بقول مہر مثل ادا کرنے سے صحیح ہو جائے گا۔ امام ابو حنیفہ رحمہ اللہ کا یہی مذہب ہے عطا،زہری اور لیث رحمہ اللہ سے بھی ایسے ہی منقول ہے احمد اور اسحق رحمہ اللہ کی ایک روایت اسی طرح ہے۔"}],[2076,"علی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حلالہ کرنے والے اور کرانے والے دونوں پر اللہ نے لعنت کی ہے۱؎\"۔\n§وضاحت\n۱؎ : حدیث سے معلوم ہوا کہ نکاح بہ نیت حلالہ باطل ہے اور ایسا کرنے والا اللہ کے غضب کا مستحق ہے۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” حلالہ کرنے والا اور جس کے لیے کیا گیا ہے (دونوں) ملعون ہیں۔ “"}],[2077,"حارث الاعور رضی اللہ عنہ ایک صحابی رسول سے روایت کرتے ہیں اور کہتے ہیں کہ ہمارا خیال ہے کہ وہ علی رضی اللہ عنہ ہیں جنہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے آگے راوی نے اسی مفہوم کی حدیث ذکر کی۔","صحیح",{"u2":"حارث اعور، نبی کریم صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص سے روایت کرتا ہے اور ہم سمجھتے ہیں کہ وہ علی رضی اللہ عنہ ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی روایت کیا۔","f2":"حارث بن عبداللہ الاعور الہمدانی الکونی ایک کذاب راوی ہے،تاہم یہ روایت دیگر احادیث صحیحہ کی روشنی میں صحیح ہے،شیخ الانی رحمہ اللہ نے بھی ا ن دونوں حدیثوں کو صحیح کہا ہے۔\nفائدہ:کوئی عورت جسے مختلف اوقات میں تین طلاقیں ہو چکی ہوں اور اس کے شوہر کا حق رجوع ختم ہو گیا ہو تو کوئی شخص اس کے ساتھ ا س نیت سے نکاح کرے اور مباشرت بھی کہ وہ پہلے خاوند کے لئے حلال ہو جائے،یہ قطعاحرام اور ناجائز ہے۔ یہ حلالہ کہلاتاہے اس نکاح سے عورت پہلے شوہر کے لئے حلال نہ ہ گی۔ مستدرک حاکم اور طبرانی اوسط میں جناب نافع سے روایت ہے کہ ایک شخص حضرت ابن عمر رضی اللہ کی خدمت میں آیا اور پوچھا کہ ایک شخص نے اپنی بیوی کو تین طلاقیں دے دی تھیں تو اس کے بھائی نے بغیر کسی مشورے کے اس عور ت سے نکاح کر لیا تاکہ اسے بھائی کے لئے حلال کردے۔ تو کیا وہ اس طرح سے پہلے شوہر کے لئے حلال ہو جائے گی؟انہوں نے کہا کہ نہیں،الا یہ کہ باقاعدہ رغبت سے نکاح کیا گیا ہو اس انداز کے نکاح کو ہم رسول صلی اللہ علیہ وسلم کے دور میں سفاح(زنا) شمار کرتے تھے (عون المعبود) یہ عمل انتہائی خست اور بےغیرتی کا عمل ہے، ایک دوسری روایت میں ایسے شخص کو مانگے کا سانڈ کہا گیا ہے۔"}],[2078,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو غلام اپنے مالک کی اجازت کے بغیر نکاح کر لے وہ زانی ہے\"۔","حسن",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو غلام اپنے مالک کی اجازت کے بغیر نکاح کر لے وہ زانی ہے۔ “"}],[2079,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب غلام اپنے مالک کی اجازت کے بغیر نکاح کرے تو اس کا نکاح باطل ہے\"۔ ابوداؤد کہتے ہیں: یہ حدیث ضعیف، اور موقوف ہے، یہ ابن عمر رضی اللہ عنہما کا قول ہے۔","ضعیف",{"u2":"سیدنا ابن عمر رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جب کوئی غلام اپنے آقا کی اجازت کے بغیر نکاح کر لے تو اس کا نکاح باطل ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں یہ حدیث (مرفوعاً) ضعیف ہے۔ یہ (دراصل) موقوف ہے اور سیدنا عبداللہ بن عمر رضی اللہ عنہ کا قول ہے۔","f2":"پہلی روایت صحیح ہے جس سے مسئلے کا اثبات واضح ہے۔"}],[2080,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اپنے بھائی کے پیغام پر پیغام نہ بھیجے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی شخص اپنے بھائی کے پیغام نکاح پر اپنا پیغام نہ بھیجے۔ “"}],[2081,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی نہ تو اپنے بھائی کے نکاح کے پیغام پر پیغام دے اور نہ اس کے سودے پر سودا کرے البتہ اس کی اجازت سے درست ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی جب ایک مسلمان کی کسی جگہ شادی طے ہو، تو دوسرے کے لئے وہاں پیغام دینا جائز نہیں، کیونکہ اس میں دوسرے مسلمان کی حق تلفی ہوتی ہے، اور اگر ابھی نسبت طے نہیں ہے، تو پیغام دینے میں کوئی مضائقہ و حرج نہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص اپنے بھائی کے پیغام نکاح پر اپنا پیغام نہ بھیجے اور نہ اپنے بھائی کے سودے پر سودا کرے مگر اس کی اجازت سے۔ “","f2":"کسی شخص نے کسی گھر میں نکاح کا پیغام بھیجا ہو تو دوسرے کسی شخص کو یہ جانتے ہوئے کہا کہ انہیں پیغام دیا گیا ہے اور انہوں نے ہاں یا نہ میں کوئی جواب نہیں دیا ہے،اپنا پیغام نہیں بھیجنا چاہیے۔ الا یہ کہ واضح ہو کہ ان کی خاموشی انکا ر کے معنی میں ہے۔ اگر نسبت طے ہو چکی ہو تو اپنا پیغام بھیج کر پہلی نسبت تڑوانے کی کوشش کرنا حرام ہے۔ کیو نکہ اس طرح دو مسلمان بھائیوں یا خاندانوں میں کشمکش اورعداوت کا قومی اندیشہ ہے اگر ہاں پہلا فریق اجاازت دے دے تو کوئی حرج نہیں۔"}],[2082,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی عورت کو پیغام نکاح دے تو ہو سکے تو وہ اس چیز کو دیکھ لے جو اسے اس سے نکاح کی طرف راغب کر رہی ہے ۱؎\"۔ راوی کا بیان ہے کہ میں نے ایک لڑکی کو پیغام دیا تو میں اسے چھپ چھپ کر دیکھتا تھا یہاں تک کہ میں نے وہ بات دیکھ ہی لی جس نے مجھے اس کے نکاح کی طرف راغب کیا تھا، میں نے اس سے شادی کر لی۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ جس عورت سے آدمی نکاح کرنا چاہے وہ اسے دیکھ سکتا ہے، یہ مستحب ہے، واجب نہیں ہے۔","حسن",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی شخص کسی عورت کو نکاح کا پیغام بھیجے ‘ اگر ممکن ہو تو اس کی وہ چیز دیکھ لے جو اس کے نکاح کی داعی ہے (قد و قامت اور حسن و جمال وغیرہ)۔ “ (سیدنا جابر رضی اللہ عنہ) کہتے ہیں کہ پھر میں نے ایک لڑکی کے لیے نکاح کا پیغام بھیجا تو میں اس کے لیے چھپا کرتا تھا حتیٰ کہ میں نے اسے دیکھ لیا جس سے مجھے اس کے ساتھ نکاح کرنے کی رغبت ہوئی ‘ چنانچہ میں نے اس سے شادی کر لی۔","f2":"یہ دیکھنا مستحب ہے اورا س سے مراد اتفاقا اچٹتی نظر سے دیکھنا ہے جیسے جابر رضی اللہ نے اپنے متعلق بیان کیا ہے مگر برا ہو تہذیب نو کا کہ اس بہانے دونوں نوجوان لڑکے لڑکی کا اکیلے اکیلے ملاقاتیں کرنا، سیروں کے لئے نکلنا اور خریداریاں کرنا اور نامعلوم کیا کچھ ہوتا ہے، شریعت ا ن کی قطعارواادارنہیں ہے، قبل از نکاح اس طرح کی کھلی میل ملاقاتیں حرام ہیں اور یہ دیکھنا بھی نسبت پختہ کرنے سے پہلے ہی زیادہ مفید ہے جب تک عقدنہیں ہو جاتا،منگیتر ایک دوسرے کے لئے اجنبی ہوتے ہیں۔"}],[2083,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو عورت اپنے ولی کی اجازت کے بغیر نکاح کرے اس کا نکاح باطل ہے\"، آپ صلی اللہ علیہ وسلم نے اسے تین بار فرمایا، (پھر فرمایا) \"اگر اس مرد نے ایسی عورت سے جماع کر لیا تو اس جماع کے عوض عورت کے لیے اس کا مہر ہے اور اگر ولی اختلاف کریں ۱؎ تو بادشاہ اس کا ولی ہے جس کا کوئی ولی نہ ہو ۲؎\"۔\n§وضاحت\n۱؎ : مثلاً ایک عورت کے دو بھائی ہوں ایک کسی کے ساتھ اس کا نکاح کرنا چاہے دوسرا کسی دوسرے کے ساتھ اور عورت نابالغ ہو اور یہ اختلاف نکاح ہونے میں آڑے آئے اور نکاح نہ ہونے دے تو ایسی صورت میں یہ فرض کر کے کہ گویا اس کا کوئی ولی ہی نہیں ہے سلطان اس کا ولی ہو گا ورنہ ولی کی موجودگی میں سلطان کو ولایت کا حق حاصل نہیں۔ ۲؎ : اس حدیث سے صاف معلوم ہوا کہ نکاح کے لئے ولی کا ہونا ضروری ہے ، خواہ عورت بالغ ہو یا نابالغ، یہی ائمہ حدیث کا مذہب ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس عورت نے اپنے ولی کی اجازت کے بغیر نکاح کیا ‘ اس کا نکاح باطل ہے۔ تین بار فرمایا اگر شوہر اس سے صحبت کر لے تو اس کو مہر دینا پڑے گا بسبب اس کے جو اس نے اس سے فائدہ حاصل کیا۔ اگر (ولیوں کا) جھگڑا ہو جائے تو حاکم ولی ہے اس کا جس کا کوئی ولی نہ ہو۔ “"}],[2084,"اس سند سے بھی ام المؤمنین عائشہ رضی اللہ عنہا سے اسی مفہوم کی حدیث مرفوعاً مروی ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کے ہم معنی بیان کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ جعفر بن ربیعہ نے زہری سے سنا نہیں بلکہ (یہ حدیث) انہوں نے اس کی طرف لکھ بھیجی تھی۔"}],[2085,"ابوموسی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ولی کے بغیر نکاح نہیں ہے\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ولی کے بغیر کوئی نکاح نہیں۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں اس سند میں یونس نے ابوبردہ رضی اللہ عنہ سے، اور اسرائیل نے ابواسحٰق سے اور انہوں نے ابوبردہ سے روایت کی ہے۔"}],[2086,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ وہ ابن حجش کے نکاح میں تھیں، ان کا انتقال ہو گیا اور وہ ان لوگوں میں سے تھے جنہوں نے سر زمین حبشہ کی جانب ہجرت کی تھی تو نجاشی (شاہ حبش) نے ان کا نکاح رسول اللہ صلی اللہ علیہ وسلم سے کر دیا، اور وہ انہیں لوگوں کے پاس (ملک حبش ہی میں) تھیں۔","صحیح",{"u2":"جناب عروہ بن زبیر رضی اللہ عنہ ام المؤمنین سیدہ ام حبیبہ رضی اللہ عنہا ا کے متعلق بتاتے ہیں کہ یہ پہلے ابن حجش کی زوجیت میں تھیں، وہ فوت ہو گیا اور وہ ان لوگوں میں سے تھا جو حبشہ کی جانب ہجرت کر کے گئے تھے، تو نجاشی نے ان کا نکاح رسول اللہ صلی اللہ علیہ وسلم سے کر دیا جبکہ یہ ان کے ہاں (حبشہ ہی میں) تھیں۔","f2":"1:عورت ازخو اپنا نکاح نہیں کر سکتی۔ ولی کا ہو نا صحت نکاح کے لئے لازمی شرط ہےایسی تمام آیات واحادیث جن میں نکاح کی نسبت عورتوں کی طرف ہے وہ ان صحیح احادیث کی روشنی میں ولی کے ساتھ مخصوص ہیں۔ یہ ضرور ہے کہ زندگی کے اس اہم فیصلے میں ان پر جبر نہیں کیا جا سکتا۔ ان کی رضامندی بلکہ بیوہ سے بالوضاحت مشورہ از بس ضروری ہے۔\n2:ام حبیبہ رضی اللہ کا پہلا خاوند (عبیداللہ بن حجش) مسلمان ہو کر حبشہ ہجرت کر گیا تھا مگر وہاں جا کر مرتد ہو گیا اور نصرانی بن گیا تھا۔ ام حبیبہ رضی اللہ کے معتلق آتا ہے کہ انہوں نے خواب میں دیکھا کہ ایک آنے والا اور اس نے ان کو ام المومنین کہہ کر مخاطب کیا اور کہتی ہیں کہ میں گھبراسی گئی اور اس خواب کی تعبیر یہ کی کہ ان شا ء اللہ رسول اللہ صلی اللہ علیہ وسلم مجھ سے نکاح کریں گے۔ چنانچہ جب میری عدت ختم ہو گی تو اچانک نجاشی کا پیغامبر دووازے پر آیا۔ دیکھا تو وہ اس کی خادمہ تھی جس کا نام ابر ہہ تھا جو بادشاہ کے لباس اور عطریات کا اہتمام کرتی تھی۔ اس نے کہا کہ بادشاہ نے کہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے لکھا ہے کہ وہ تمہارا نکاح رسول صلی اللہ علیہ وسلم سے کر دے۔ میں نے کہا: اللہ تمہیں جزائے خیر دے،کہنے لگی کہ اپنا وکیل بنا دیں۔ چنانچہ میں نے خالد بن سعید بن العاص کو اپنا وکیل بنایا۔ سیرت یعمری میں ہے کہ حضرت عثمان بن عفان رضی اللہ ان کے وکیل تھے۔چنانچہ نجاشی رحمہ اللہ حق مہر ادا کیا اور چار سومشقال سونا اور بعدازاں ولیمہ بھی کھلایا۔ بعدازاں حضرت شرجیل بن حسنہ کی معیت میں ان کو مدینے بھیج دیا گیا۔ (بذل المہود) اس قصے میں نجاشی رحمہ اللہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے وکیل تھے اور خالد بن سعید یا عثمان رضی اللہ حضرت ام حبیبہ رضی اللہ کے ولی اور وکیل بنے۔ نجاشی رحمہ اللہ جو سلطان وقت تھے ان کو بھی ولی سمجھاکا سکتا ہے۔ حضرت عثمان کا ذکر صحیح نہیں لگتا کیو نکہ وہ اس وقت حبشہ میں نہ تھے بلکہ پہلی ہجرت حبشہ کے بعد جلد ہی واپس آگئےتھے۔"}],[2087,"معقل بن یسار کہتے ہیں کہ میری ایک بہن تھی جس کے نکاح کا پیغام میرے پاس آیا، اتنے میں میرے چچا زاد بھائی آ گئے تو میں نے اس کا نکاح ان سے کر دیا، پھر انہوں نے اسے ایک طلاق رجعی دے دی اور اسے چھوڑے رکھا یہاں تک کہ اس کی عدت پوری ہو گئی، پھر جب اس کے لیے میرے پاس ایک اور نکاح کا پیغام آ گیا تو وہی پھر پیغام دینے آ گئے، میں نے کہا: اللہ کی قسم میں کبھی بھی ان سے اس کا نکاح نہیں کروں گا، تو میرے ہی متعلق یہ آیت نازل ہوئی: «وإذا طلقتم النساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزواجهن» \"اور جب تم عورتوں کو طلاق دے دو اور ان کی عدت پوری ہو جائے تو تم انہیں اپنے شوہروں سے نکاح کرنے سے مت روکو\" (سورۃ البقرہ: ۲۳۲) راوی کا بیان ہے کہ میں نے اپنی قسم کا کفارہ ادا کر دیا، اور ان سے اس کا نکاح کر دیا۔","صحیح",{"u2":"سیدنا معقل بن یسار رضی اللہ عنہ بیان کرتے ہیں کہ میری بہن تھی ‘ مجھے اس کے سلسلے میں پیغام آتے رہے۔ میرا چچا زاد میرے پاس آیا تو میں نے اس کا نکاح اس سے کر دیا۔ مگر اس نے طلاق دے دی رجعی طلاق ‘ پھر اسے چھوڑے رہا حتیٰ کہ اس کی عدت ختم ہو گئی۔ پھر دوبارہ جب مجھے اس کے نکاح کے پیغام آئے تو وہ پھر میرے پاس اس کا پیغام لے کر آ گیا۔ میں نے کہا: قسم ا اللہ کی! میں کبھی بھی تجھ سے اس کا نکاح نہیں کروں گا۔ بیان کرتے ہیں کہ پھر میرے ہی بارے میں یہ آیت کریمہ نازل ہوئی «وإذا طلقتم النساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزواجهن ***» ” اور جب تم عورتوں کو طلاق دو ‘ پھر دو پوری کر لیں اپنی عدت ‘ تو نہ روکو انہیں اس سے کہ نکاح کر لیں اپنے ان ہی خاوندوں سے ‘ جبکہ وہ آپس میں راضی ہوں دستور کے موافق۔ یہ نصیحت کہ جاتی ہے اسے جو تم میں سے ا اللہ پر اور قیامت کے دن پر ایمان رکھتا ہے۔ یہ تمہارے لیے بہتر اور پاکیزہ ہے۔ اور ا اللہ جانتا ہے ‘ تم نہیں جانتے۔ “ کہتے ہیں کہ پھر میں نے اپنی قسم کا کفارہ ادا کیا اور اس سے نکاح کر دیا۔","f2":"1: اگر عورت شرع واخلاق کی حدود میں رہتے ہوئے کہیں نکاح کا عندیہ دے تو اس کی رائے کا احترام کرنا چاہیے۔ شرع واخلاق سے باہر نکلنا تو کسی بھی اسلامی معاشرے میں قبول نہیں ہو سکتا۔ نیز یہ واقعہ ثابت کرتا ہے کہ ولی کے بغیر نکاح نہیں حالانکہ آیت کریمہ کے ظاہر الفاظ میں نکاح کی نسبت عورتوں کی طرف ذکر ہوئی ہے۔\n2: ہمارے معاشرے میں عورتیں بالعموم بعض اسباب کے تحت اپنی اس ضرورت (نکاح ثانی) کا اظہار نہیں کرتی ہیں اس لئے اولیا ء کے ذمے ہے کہ ان کی اس فطری اور اخلاقی ضرورت کا احساس کریں، اس طرح عورت کو مادی ومعاشرتی تحفظ ملتاہے اور ایک شرعی فریضہ ادا ہوتا ہے۔ تعجب ہے کہ اس نام نہاد ترقی یافتہ دور میں بہت سے مسلمان نکاح ثانی کو بہت برا سمجھتے ہیں۔ چاہیے کہ اس سنت کا احیاء ہو جیسے کہ سید احمد شہید اور اسمعیل شہید رضی اللہ نے کیا تھا۔\n3: جب آدمی جذبات میں آکر کوئی غلط قسم اٹھالے تو کفارہ دے اور صحیح عمل اختیار کرے۔"}],[2088,"سمرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس عورت کا نکاح دو ولی کر دیں تو وہ اس کی ہو گی جس سے پہلے نکاح ہوا ہے اور جس شخص نے ایک ہی چیز کو دو آدمیوں سے فروخت کر دیا تو وہ اس کی ہے جس سے پہلے بیچی گئی\"۔","ضعیف",{"u2":"سیدنا سمرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب دو ولی کسی عورت کا نکاح کر دیں تو یہ ان میں سے پہلے والے کے لیے ہو گی۔ اور جب کسی شخص نے ایک چیز کا دو آدمیوں سے سودا کر دیا ہو تو یہ پہلے والے کی ہو گی۔ “"}],[2089,"عبداللہ بن عباس رضی اللہ عنہما سے آیت کریمہ: «لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن» \"تمہارے لیے حلال نہیں کہ تم عورتوں کے بھی زبردستی وارث بن بیٹھو اور نہ ہی تم انہیں نکاح سے اس لیے روک رکھو کہ جو تم نے انہیں دے رکھا ہے اس میں کچھ لے لو\" (سورۃ البقرہ: ۱۹) کی تفسیر کے سلسلہ میں مروی ہے کہ جب آدمی کا انتقال ہو جاتا تو اس (آدمی) کے اولیا یہ سمجھتے تھے کہ اس عورت کے ہم زیادہ حقدار ہیں بہ نسبت اس کے ولی کے، اگر وہ چاہتے تو اس کا نکاح کر دیتے اور اگر نہ چاہتے تو نہیں کرتے، چنانچہ اسی سلسلہ میں یہ آیت نازل ہوئی ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ اگر کوئی آدمی مر جائے تو اس کی عورت کو اپنے نکاح کا اختیار ہے، میت کے رشتہ داروں کو اسے زبردستی اپنے نکاح میں لینا جائز نہیں، اور نہ انہیں یہ حق ہے کہ وہ اسے نکاح سے روکیں۔","",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے آیت کریمہ &laquo;لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن&raquo; کی تفسیر میں فرمایا: جب کوئی آدمی مر جاتا تھا تو اس کے وارث اس عورت کے اپنے ولی سے بھی زیادہ اس کے حقدار بن جاتے تھے۔ اگر ان میں سے کوئی چاہتا تو خود ہی اس سے نکاح کر لیتا یا جس سے وہ چاہتے اس کا نکاح کر دیتے تھے۔ اور اگر چاہتے تو اس کا نکاح ہی نہ کرتے تو اس سلسلے میں یہ آیت نازل ہوئی۔"}],[2090,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ آیت کریمہ: «لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما آتيتموهن إلا أن يأتين بفاحشة مبينة» \"اور جب تم عورتوں کو طلاق دے دو اور ان کی عدت پوری ہو جائے تو تم انہیں اپنے شوہروں سے نکاح کرنے سے مت روکو\" (سورۃ البقرہ: ۲۳۲) کے متعلق مروی ہے کہ ایسا ہوتا تھا کہ آدمی اپنی کسی قرابت دار عورت کا وارث ہوتا تو اسے دوسرے سے نکاح سے روکے رکھتا یہاں تک کہ وہ یا تو مر جاتی یا اسے اپنا مہر دے دیتی تو اللہ تعالی نے اس سلسلہ میں حکم نازل فرما کر ایسا کرنے سے منع کر دیا۔","حسن صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے آیت کریمہ «لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض آتيتموهن إلا أن يأتين بفاحشة مبينة» کی تفسیر میں مروی ہے کہ آدمی اپنے قریبی کہ وراثت میں اس کی بیوی کا بھی وارث بن جاتا تھا اور اسے روکے رکھتا تاآنکہ وہ مر جاتی یا اسے اپنا حق مہر واپس کرتی تو ا اللہ تبارک و تعالیٰ نے اس عمل سے منع فر دیا۔","f2":"(حکم اللہ عن ذلک) کے معنی ہیں،اللہ نے اس سے روک دیا کہتے ہیں (احکمت فلانا۔۔۔۔۔)میں نے اسے روک دیا اسی طرح حاکم کو بھی حاکم اس لئے کہا جاتا ہے کہ وہ ظلم سے روکتا ہے۔(اتھایة لابن الائير)"}],[2091,"ضحاک سے بھی اسی مفہوم کی حدیث مروی ہے اس میں ہے: تو اللہ تعالی نے اس کی نصیحت فرمائی۔","صحیح",{"u2":"عبیداللہ(عبیداللہ مولیٰ عمر)نے ضحاک سے اس کے ہم معنی بیان کیا اور لفظ یہ تھے «فوعظ الله ذلك» ” اللہ نے اس بارے میں نصیحت فرمائی۔ “","f2":"بیوہ عورت کا بالجبر نکاح نہیں کیا جا سکتا،اس کا عندیہ لینا،جس میں صراحت ہو،ضروری ہے،جیسے کہ اگلے ابواب میں آرہا ہے۔"}],[2092,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غیر کنواری عورت کا نکاح نہ کیا جائے جب تک اس سے پوچھ نہ لیا جائے، اور نہ ہی کنواری عورت کا نکاح بغیر اس کی اجازت کے کیا جائے\"، لوگوں نے عرض کیا: اللہ کے رسول! اس کی اجازت کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"(اس کی اجازت یہ ہے کہ) وہ خاموش رہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ بلاشبہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بیوہ کا نکاح نہ کیا جائے حتیٰ کہ اس سے مشورہ کر لیا جائے۔ اور کنواری کا نکاح نہ کیا جائے مگر اس کی اجازت سے۔ “ صحابہ کہنے لگے: اے ا اللہ کے رسول! اس کی اجازت کیا ہے؟ آپ نے فرمایا ” یہی کہ خاموشی رہے۔ “"}],[2093,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یتیم لڑکی سے اس کے نکاح کے لیے اجازت لی جائے گی، اگر وہ خاموشی اختیار کرے تو یہی اس کی اجازت ہے اور اگر انکار کر دے تو اس پر زبردستی نہیں\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یتیم لڑکی سے (نکاح کے سلسلے میں) اس کی اپنی ذات کے بارے میں مشورہ کیا جائے۔ اگر وہ خاموش رہے تو یہ اس کی اجازت ہے اور اگر انکار کر دے تو اس پر جبر جائز نہیں۔ “ یزید بن زریع کی سند میں «أخبرنا» کا صیغہ استعمال ہوا ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابوخالد سیلمان بن حیان اور معاذ بن معاذ نے محمد بن عمرو سے ایسے ہی روایت کیا ہے۔"}],[2094,"اس سند سے بھی محمد بن عمرو سے اسی طریق سے یہی حدیث یوں مروی ہے اس میں «فإن بكت أو سكتت» \"اگر وہ رو پڑے یا چپ رہے\" یعنی «بكت» (رو پڑے) کا اضافہ ہے، ابوداؤد کہتے ہیں «بكت» (رو پڑے) کی زیادتی محفوظ نہیں ہے یہ حدیث میں وہم ہے اور یہ وہم ابن ادریس کی طرف سے ہے یا محمد بن علاء کی طرف سے۔ ابوداؤد کہتے ہیں: اسے ابوعمرو ذکوان نے ام المؤمنین عائشہ رضی اللہ عنہا سے روایت کیا ہے اس میں ہے انہوں نے کہا اللہ کے رسول! باکرہ تو بولنے سے شرمائے گی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی خاموشی ہی اس کی رضا مندی ہے\"۔","صحیح",{"u2":"محمد بن عمرو نے یہ حدیث اپنی سند سے روایت کی اور اس نے کہا «فإن بكت أو سكتت» ” اگر وہ رو پڑے یا خاموش رہے۔ “ اس نے «بكت»کے لفظ کا اضافہ کیا (رو پڑے۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ لفظ «بكت» محفوظ نہیں ‘ وہم ہے جو ابن ادریس سے ہوا ہے یا محمد بن علاء سے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو ابوعمرو ذکوان نے سیدہ عائشہ رضی اللہ عنہا ا سے روایت کیا ‘ وہ کہتی ہیں کہ (میں نے کہا) اے ا اللہ کے رسول! کنواری لڑکی تو بات کرنے سے حیاء کرتی ہے۔ آپ نے فرمایا ” اس کا خاموشی رہنا ہی اس کا اقرار ہے۔ “"}],[2095,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورتوں سے ان کی بیٹیوں کے بارے میں مشورہ لو\"۔","ضعیف",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” لڑکیوں کے سلسلے میں عورتوں سے (ان کی ماؤں سے) مشورہ کر لیا کرو۔ “","f2":"یہ اثر سند ا کمزور ہے مگر حقیقت یہی ہے کہ مائیں اپنی بچیوں کی بہت عمدہ راز دار ہوتی ہیں اور پچیاں بالعموم اپنے دل کی بات ماوں کے سامنے پیش کردیتی ہیں اور مذکورہ بالا نبوی ارشادات اسلام میں عورتوں کے حقوق کی اہمیت کی عظیم دلیل ہیں،جو اسلام نے انہیں ڈیڑھ ہزار سال پہلے پہ عطا فر مادیے ہوئے ہیں۔ نام نہاد تہذیب نو نے ان کو کیا حقوق دینے ہیں؟یہ تو انہیں بے لباس کرنے اور بکاو مال (شوپیس) بنانے پر تلی ہوئی ہیں۔"}],[2096,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک کنواری لڑکی نبی اکرم صلی اللہ علیہ وسلم کے پاس آئی اور اس نے عرض کیا کہ اس کے والد نے اس کا نکاح اس کی مرضی کے بغیر کر دیا ہے، نبی اکرم صلی اللہ علیہ وسلم نے اسے اختیار دیا ۱؎۔\n§وضاحت\n۱؎ : کہ چاہے تو نکاح باقی رکھے اور چاہے تو فسخ کر لے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ ایک جوان کنواری لڑکی نبی کریم صلی اللہ علیہ وسلم کے پاس آئی۔ اس نے بتایا کہ اس کے باپ نے اس کی شادی کر دی ہے مگر میں اسے ناپسند کرتی ہوں۔ تو نبی کریم صلی اللہ علیہ وسلم نے اسے اختیار دے دیا۔"}],[2097,"اس سند سے عکرمہ سے یہ حدیث مرسلاً مروی ہے ابوداؤد کہتے ہیں: اس روایت میں ابن عباس رضی اللہ عنہما کا ذکر نہیں ہے، اس روایت کا اسی طرح لوگوں کا مرسلاً روایت کرنا ہی معروف ہے۔","صحیح",{"u2":"عکرمہ نبی کریم صلی اللہ علیہ وسلم سے یہی روایت بیان کرتے ہیں۔ امام ابوداؤد رضی اللہ عنہ نے کہا کہ (عکرمہ نے) ابن عباس رضی اللہ عنہ کا نام ذکر نہیں کیا، اور محدثین کے ہاں اس روایت کو اسی طرح مرسل روایت کرنا ہی معروف ہے۔","f2":"باب کو روا نہیں کہ جوان بیٹی کا عندیہ لیے بغیر اس کا نکاح کر دے، جبر کی صورت میں اسے حق حاصل ہے کہ قاضی کے سامنے اپنا مقدمہ پیش کر دے اور قاضی تحقیق احوال کے بعد شرعی تقاضوں کے مطابق فیصلہ دے۔ اگر باپ ولی کا فیصلی بے محل ہو تو قاضی ایسے نکاح کو فسخ کر سکتا ہے۔"}],[2098,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ثیبہ ۱؎ اپنے نفس کا اپنے ولی سے زیادہ حقدار ہے اور کنواری لڑکی سے اس کے بارے میں اجازت لی جائے گی اور اس کی خاموشی ہی اس کی اجازت ہے\"۔\n§وضاحت\n۱؎ : «ایّم» سے مراد ثیبہ عورت ہے اس کی تائید صحیح مسلم کی ایک روایت سے بھی ہوتی ہے، ترجمۃ الباب سے بھی یہی بات ثابت ہوتی ہے لیکن اس کے برخلاف بعض لوگوں نے «ایّم» سے مراد بیوہ عورت لیا ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بیوہ اپنی ذات کے بارے میں اپنے ولی کی بہ نسبت زیادہ حقدار ہے۔ اور کنواری سے بھی اس کے اپنے بارے میں مشورہ کیا جائے، اس کی اجازت اس کی خاموشی ہے۔ “ اور یہ لفظ قعنبی (عبداللہ بن مسلمہ) کے ہیں۔"}],[2099,"عبداللہ بن فضل سے بھی اسی طریق سے اسی مفہوم کی حدیث مروی ہے اس میں ہے: آپ صلی اللہ علیہ وسلم نے فرمایا: \"ثیبہ اپنے نفس کا اپنے ولی سے زیادہ حقدار ہے اور کنواری لڑکی سے اس کا باپ پوچھے گا\"۔ ابوداؤد کہتے ہیں: «أبوها» کا لفظ محفوظ نہیں ہے۔","صحیح",{"u2":"عبداللہ بن فضل نے اپنی سند سے اور مذکورہ بالا حدیث کے ہم معنی روایت کیا اور کہا ” بیوہ اپنے ولی کی بہ نسبت اپنے بارے میں زیادہ حقدار ہے۔ اور کنواری سے اس کا باپ مشورہ کرے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «أبوها» ” اس کا باپ “ کا لفظ محفوظ نہیں۔"}],[2100,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ولی کا ثیبہ عورت پر کچھ اختیار نہیں، اور یتیم لڑکی سے پوچھا جائے گا اس کی خاموشی ہی اس کا اقرار ہے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ولی کو بیوہ کے معاملے میں کوئی دخل حاصل نہیں ہے۔ اور یتیم لڑکی سے مشورہ کیا جائے اور اس کی خاموشی اس کا اقرار ہے۔ “","f2":"بیوہ جہاں کا عندیہ دے،ولی کے لئے وہیں نکاح کرنا زیادہ مستحسن ہے بشرطیکہ کوئی شرعی رکاوٹ نہ ہو۔"}],[2101,"خنسا بنت خذام انصاریہ رضی اللہ عنہا سے روایت ہے کہ ان کے والد نے ان کا نکاح کر دیا اور وہ ثیبہ تھیں تو انہوں نے اسے ناپسند کیا چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئیں اور آپ سے اس کا ذکر کیا تو آپ نے ان کا نکاح رد کر دیا۔","صحیح",{"u2":"سیدہ خنساء بنت خذام انصاریہ رضی اللہ عنہا ا کا بیان ہے کہ اس کے والد نے اس کی شادی کر دی جبکہ وہ بیوہ تھی۔ اس نے یہ نکاح ناپسند کیا اور پھر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی اور آپ صلی اللہ علیہ وسلم کے سامنے اس کا ذکر کیا تو رسول اللہ صلی اللہ علیہ وسلم نے اس کا نکاح رد (فسخ کر دیا) کر دیا۔"}],[2102,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ابوہند نے نبی اکرم صلی اللہ علیہ وسلم کی چندیا میں پچھنا لگایا تو آپ نے فرمایا: \"بنی بیاضہ کے لوگو! ابوہند سے تم (اپنی بچیوں کی) شادی کرو اور (ان کی بچیوں سے شادی کرنے کے لیے) تم انہیں نکاح کا پیغام دو ۱؎\"، اور فرمایا: \"تین چیزوں سے تم علاج کرتے ہو اگر ان میں کسی چیز میں خیر ہے تو وہ پچھنا لگانا ہے\"۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ کفو میں اعتبار دین کا ہو گا نہ کہ نسب اور پیشہ وغیرہ کا۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کی روایت ہے کہ ابوہند نے نبی کریم صلی اللہ علیہ وسلم کے سر میں سینگی لگائی۔ اور پھر آپ صلی اللہ علیہ وسلم نے فرمایا ” اے بنی بیاضہ! ابوہند کا (اپنے میں سے کسی کے ساتھ) نکاح کر دو۔ اور اس سے (اس کی کسی عزیزہ کا) نکاح لے لو۔ “ اور فرمایا ” اگر تمہاری دواؤں میں سے کسی میں خیر ہے تو وہ سینگی لگانے ہی میں ہے۔ “","f2":"1:اکثر علما ء کے بیانات میں زوجین (میاں،بیوی)کے آپس میں کفو (ہم پلہ)ہونے کا ذکر آیا ہے اور ان امور کو پیش نظر رکھتے ہیں۔ دین،آزادی،نسب،کسب وصناعت،عیوب سے سلامتی اور غنا وفراخی۔ مگر امام مالک رحمہ اللہ سے منقول ہے کہ بنیادی طور پر دین واسلام میں ہم پلہ ہونا ہی معتبر ہے اور یہی بات حضرت ابن عمر اور ابن مسعود رضی اللہ اور تابعین سے محمد عبدالعزیز رحمہ اللہ سے منقول ہے۔ قرآن کریم نے بڑے واضح انداز میں فرمایا کہ (انما المومنون اخوت)(الحجرات:10) مومن آپس میں بھائی بھائی ہیں اور (وجعلنکم شعوباو قبائل لتعارفون ان اکرامکم عنداللہ اتقکم)(الحجرات:13) ہم نے تمہارے قبیلے اور خاندان بنائے،تمہارے تعارف کے لئے۔ اللہ کے ہاں تم میں سب سے زیادہ عزت والا وہی ہے جو تم میں تقو میں بڑھ کر ہے بعض افراد یا خاندانوں میں کچھ خاص عادات یا خصائل معروف ہوتے ہیں وی اگر قابل قبول ہوں اور گھریلو زندگی میں اطمینان وسکنیت میں رکاوٹ کا باعث نہ ہو ں تو انہیں باہم ازدواجی تعلق کے قیام میں کسی طرح رکاوٹ نہیں بنا نا چاہیے۔\n2: ابو ہند (یسار رضی اللہ) غلام تھے۔ نبی صلی اللہ علیہ وسلم نے بنی بیاضہ جیسے عربی خاندان والوں کو فرمایا کہ اس کو رشتہ لے بھی لو اس واقعہ میں یہی ثابت ہواکہ اصل کفا ء ت دین کی کفاء ت ہے وین کو پس پشت ڈال کر خاندانی اونچ نیچ کی کوئی حیثیت نہیں۔\n1:اکثر علما ء کے بیانات میں زوجین (میاں،بیوی)کے آپس میں کفو (ہم پلہ)ہونے کا ذکر آیا ہے اور ان امور کو پیش نظر رکھتے ہیں۔ دین،آزادی،نسب،کسب وصناعت،عیوب سے سلامتی اور غنا وفراخی۔ مگر امام مالک رحمہ اللہ سے منقول ہے کہ بنیادی طور پر دین واسلام میں ہم پلہ ہونا ہی معتبر ہے اور یہی بات حضرت ابن عمر اور ابن مسعود رضی اللہ اور تابعین سے محمد عبدالعزیز رحمہ اللہ سے منقول ہے۔ قرآن کریم نے بڑے واضح انداز میں فرمایا کہ (انما المومنون اخوت)(الحجرات:10) مومن آپس میں بھائی بھائی ہیں اور (وجعلنکم شعوباو قبائل لتعارفون ان اکرامکم عنداللہ اتقکم)(الحجرات:13) ہم نے تمہارے قبیلے اور خاندان بنائے،تمہارے تعارف کے لئے۔ اللہ کے ہاں تم میں سب سے زیادہ عزت والا وہی ہے جو تم میں تقو میں بڑھ کر ہے بعض افراد یا خاندانوں میں کچھ خاص عادات یا خصائل معروف ہوتے ہیں وی اگر قابل قبول ہوں اور گھریلو زندگی میں اطمینان وسکنیت میں رکاوٹ کا باعث نہ ہو ں تو انہیں باہم ازدواجی تعلق کے قیام میں کسی طرح رکاوٹ نہیں بنا نا چاہیے۔\n2: ابو ہند (یسار رضی اللہ) غلام تھے۔ نبی صلی اللہ علیہ وسلم نے بنی بیاضہ جیسے عربی خاندان والوں کو فرمایا کہ اس کو رشتہ لے بھی لو اس واقعہ میں یہی ثابت ہواکہ اصل کفا ء ت دین کی کفاء ت ہے وین کو پس پشت ڈال کر خاندانی اونچ نیچ کی کوئی حیثیت نہیں۔"}],[2103,"سارہ بنت مقسم نے بیان کیا ہے کہ انہوں نے میمونہ بنت کردم رضی اللہ عنہا کو کہتے سنا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے حج میں اپنے والد کے ساتھ نکلی، میرے والد آپ صلی اللہ علیہ وسلم کے قریب پہنچے، آپ اپنی اونٹنی پر سوار تھے تو وہ آپ کے پاس کھڑے ہو گئے، اور آپ کی باتیں سننے لگے، آپ صلی اللہ علیہ وسلم کے پاس معلموں کے درے کی طرح ایک درہ تھا، میں نے بدوؤں نیز دیگر لوگوں کو کہتے ہوئے سنا کہ تھپتھپانے سے بچو، تھپتھپانے سے بچو تھپتھپانے سے بچو ۱؎۔ میرے والد نے آپ صلی اللہ علیہ وسلم سے قریب جا کر آپ کا پیر پکڑ لیا اور آپ کے رسول ہونے کا اقرار کیا، اور آپ صلی اللہ علیہ وسلم کے پاس ٹھہرے رہے اور آپ کی بات کو غور سے سنا، پھر کہا کہ میں لشکر عثران (یہ جاہلیت کی جنگ ہے) میں حاضر تھا، (ابن مثنی کی روایت میں جیش عثران کے بجائے جیش غثران ہے) تو طارق بن مرقع نے کہا: مجھے اس کے عوض میں نیزہ کون دیتا ہے؟ میں نے پوچھا: اس کا عوض کیا ہو گا؟ کہا: میری جو پہلی بیٹی ہو گی اس کے ساتھ اس کا نکاح کر دوں گا، چنانچہ میں نے اپنا نیزہ اسے دے دیا اور غائب ہو گیا، جب مجھے پتہ چلا کہ اس کی بیٹی ہو گئی اور جوان ہو گئی ہے تو میں اس کے پاس پہنچ گیا اور اس سے کہا کہ میری بیوی کو میرے ساتھ رخصت کرو تو وہ قسم کھا کر کہنے لگا کہ وہ ایسا نہیں کر سکتا، جب تک کہ میں اسے مہر جدید ادا نہ کر دوں اس عہد و پیمان کے علاوہ جو میرے اور اس کے درمیان ہوا تھا، میں نے بھی قسم کھا لی کہ جو میں اسے دے چکا ہوں اس کے علاوہ کوئی اور مہر نہیں دے سکتا، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: \"اب وہ کن عورتوں کی عمر میں ہے (یعنی اس کی عمر اس وقت کیا ہے)\"، اس نے کہا: وہ بڑھاپے کو پہنچ گئی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری رائے ہے کہ تم اسے جانے دو\"، تو آپ صلی اللہ علیہ وسلم کی اس بات نے مجھے گھبرا دیا میں آپ کی جانب دیکھنے لگا، آپ صلی اللہ علیہ وسلم نے میری جب یہ حالت دیکھی تو فرمایا: \"(گھبراؤ مت) نہ تم گنہگار ہو گے اور نہ ہی تمہارا ساتھی ۲؎ گنہگار ہو گا\"۔ ابوداؤد کہتے ہیں: روایت میں وارد لفظ «قتیر» کا مطلب بڑھاپا ہے۔\n§وضاحت\n۱؎ : یعنی اپنے پیروں کو زمین پر تھپتھپانے سے بچو یا تھپتھپانے سے کنایہ درہ مارنے کی طرف ہے یعنی درے مارنے سے بچو۔ ۲؎: ساتھی سے مراد طارق بن مرقع ہیں یعنی قسم کھانے کی وجہ سے تم دونوں گنہگار نہیں ہو گے۔","ضعیف",{"u2":"سیدہ میمونہ بنت کردم رضی اللہ عنہا ا بیان کرتی ہیں کہ میں اپنے والد کے ساتھ چلی ‘ اس حج کے موقع پر جب کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کیا تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ‘ میرے والد ان کے قریب ہوئے۔ آپ صلی اللہ علیہ وسلم اپنی اونٹنی پر تھے۔ آپ صلی اللہ علیہ وسلم ان کی خاطر رک گئے ‘ میرے والد نے آپ سے مفید مطلب باتیں سنیں۔ آپ کے پاس درہ تھا جیسے کہ معلم لوگوں کے پاس ہوتا ہے۔ میں نے بدویوں کو اور لوگوں کو سنا کہ وہ کہہ رہے تھے «الطبطبية الطبطبية الطبطبية» (چلتے ہوئے پاؤں پڑنے کی آواز۔ طب طب۔ یا کوڑا مارنے کی آواز) میرے والد آپ صلی اللہ علیہ وسلم کے قریب ہوئے ‘ آپ کے قدم مبارک پکڑ لیے ‘ آپ کی رسالت کا اقرار کیا ‘ آپ کے پاس کھڑے رہے اور آپ کے ارشادات سنے۔ میرے والد نے بتایا کہ میں لشکر عشران میں شریک ہوا تھا۔ ابن مثنی نے اس کو غثران کہا: (غین منقوط کے ساتھ) (یہ دور جاہلیت کی ایک جنگ کا واقعہ ہے۔) اس دوران میں طارق بن مرقع نے کہا: تھا کون ہے جو مجھے اپنا نیزہ دے اور اس کا بدلہ پائے؟ میں نے کہا: اس کا بدلہ کیا ہے؟ کہا: میں اس کے ساتھ اپنی اس بیٹی کا نکاح کر دوں گا جو سب سے پہلے پیدا ہو گی۔ چنانچہ میں نے اس کو اپنا نیزہ دے دیا ‘ پھر اس سے غائب رہا حتیٰ کہ مجھے علم ہوا کہ اس کے ہاں لڑکی پیدا ہوئی ہے اور اب بالغ ہو چکی ہے۔ پھر میں اس کے پاس گیا ‘ اور اس سے کہا کہ میرے گھر والوں (میری بننے والی بیوی) کو میری طرف تیار کر دو۔ تو اس نے قسم اٹھائی کہ وہ ایسا نہیں کرے گا حتیٰ کہ میں اسے نیا مہر پیش کروں ‘ بخلاف اس کے جو میرے اور اس کے درمیان ہو چکا تھا۔ اور میں نے بھی قسم اٹھا لی کہ جو دے چکا ہوں بس وہی ہے اور نہیں دوں گا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا ” اور اب وہ لڑکی کس عمر میں ہے؟ کہا کہ اب تو اس کے بالوں میں سفیدی آ گئی ہے۔ “ آپ نے فرمایا ” میرا خیال ہے کہ تو اسے چھوڑ دے۔ “ آپ کی یہ بات مجھے پریشان کر گئی۔ اور میں نے رسول اللہ صلی اللہ علیہ وسلم کی طرف دیکھا۔ جب آپ نے میری یہ کیفیت دیکھی تو فرمایا ” نہ تم گناہ گار بنو اور نہ تمہارا ساتھی گناہ گار بنے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «القتير» کا معنی بالوں کی سفیدی (بڑھاپا) ہے۔"}],[2104,"ابراہیم بن میسرہ کی روایت ہے کہ ایک عورت جو نہایت سچی تھی، کہتی ہے: میرے والد زمانہ جاہلیت میں ایک غزوہ میں تھے کہ (تپتی زمین سے) لوگوں کے پیر جلنے لگے، ایک شخص بولا: کوئی ہے جو مجھے اپنی جوتیاں دیدے؟ اس کے عوض میں پہلی لڑکی جو میرے یہاں ہو گی اس سے اس کا نکاح کر دوں گا، میرے والد نے جوتیاں نکالیں اور اس کے سامنے ڈال دیں، اس کے یہاں ایک لڑکی پیدا ہوئی اور پھر وہ بالغ ہو گئی، پھر اسی جیسا قصہ بیان کیا لیکن اس میں «قتیر» کا واقعہ مذکور نہیں ہے۔","ضعیف",{"u2":"ابراہیم بن میسرہ نے بیان کیا کہ اس کی خالہ نے ایک خاتون سے خبر سنائی جو کمال کی سچی عورت تھی ‘ وہ بیان کرتی تھی کہ دور جاہلیت میں میرے والد ایک جنگ میں گئے۔ ان لوگوں کو گرمی لگنے لگی تو ایک شخص نے کہا: کون ہے جو مجھے اپنے جوتے دیدے ‘ میں اس کا اپنی پہلی پیدا ہونے والی بیٹی سے نکاح کر دوں گا۔ چنانچہ میرے باپ نے اپنے جوتے اتار کر اس کی طرف پھینک دیے۔ پھر اس کے ہاں لڑکی پیدا ہوئی ‘ اور بالغ ہو گئی۔ اور گزشتہ قصہ کی مانند بیان کیا مگر سفیدی ظاہر ہونے کا ذکر نہیں کیا۔","f2":"یہ دونوں روایات ضعیف ہیں اس لئے ان سے کسی مسئلے کے اثبات میں دلیل نہیں لی کاسکتی۔"}],[2105,"ابوسلمہ بن عبدالرحمٰن بن عوف الزہری کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے نبی اکرم صلی اللہ علیہ وسلم (کی ازواج مطہرات) کے مہر کے بارے میں پوچھا تو انہوں نے بتایا کہ بارہ اوقیہ اور ایک نش تھا ۱؎، میں نے کہا: نش کیا ہے؟ فرمایا: آدھا اوقیہ ۲؎۔\n§وضاحت\n۱؎ : بارہ اوقیہ کے (۴۸۰) درہم اورنش کے (۲۰) درہم، کل پانچ سو درہم ہوئے، جو وزن سے تیرہ سو پچھتر گرام (۱۳۷۵) کے مساوی ہے (یعنی ایک کیلو تین سو پچھتر گرام چاندی)۔ ۲؎ : ایک اوقیہ چالیس درہم کا ہوتا ہے اس حساب سے ساڑھے بارہ اوقیہ کے کل پانچ سو درہم ہوئے۔","صحیح",{"u2":"ابوسلمہ کہتے ہیں کہ میں نے سیدہ عائشہ رضی اللہ عنہا ا سے رسول اللہ صلی اللہ علیہ وسلم کے حق مہر کے بارے میں پوچھا تو انہوں نے بتایا کہ بارہ اوقیہ اور نش۔ میں نے کہا: نش کیا ہے؟ انہوں نے کہا:، آدھا اوقیہ۔","f2":"ایک اوقیہ میں چالیس درہم چاندی ہوتے ہیں لہذا یہ مقدار پانچ سو درہم ہوئی اور موجودہ معیار کے مطابق ایک درہم کا وزن 975۔2 گرام اور پچھلے علما کے حساب سے 06۔3 گرام ہوتاہے۔"}],[2106,"ابوعجفاء سلمی کہتے ہیں کہ عمر رضی اللہ عنہ نے، اللہ ان پر رحم کرے، ہمیں خطاب فرمایا اور کہا: خبردار! عورتوں کے مہر بڑھا چڑھا کر مت باندھو اس لیے کہ اگر یہ (مہر کی زیادتی) دنیا میں باعث شرف اور اللہ کے یہاں تقوی اور پرہیزگاری کا ذریعہ ہوتی تو رسول اللہ صلی اللہ علیہ وسلم اس کے زیادہ حقدار تھے، آپ نے تو اپنی کسی بھی بیوی اور بیٹی کا بارہ اوقیہ (چار سو اسی درہم) سے زیادہ مہر نہیں رکھا۔","حسن صحیح",{"u2":"ابوالعجفاء السلمی کہتے ہیں کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ہمیں خطبہ دیا اور کہا: ” خبردار! عورتوں کے سلسلے میں بھاری بھاری مہر مت باندھا کرو، اگر یہ چیز دنیا میں عزت اور اللہ کے ہاں تقویٰ کا ثبوت ہوتی تو اس میں نبی کریم صلی اللہ علیہ وسلم سب سے بڑھ کر ہوتے۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنی کسی بیوی اور اپنی صاحبزادیوں میں سے کسی کو بارہ اوقیہ سے زیادہ مہر نہیں دیا۔ “"}],[2107,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ وہ عبیداللہ بن حجش کے نکاح میں تھیں، حبشہ میں ان کا انتقال ہو گیا تو نجاشی (شاہ حبشہ) نے ان کا نکاح رسول اللہ صلی اللہ علیہ وسلم سے کر دیا، اور آپ کی جانب سے انہیں چار ہزار (درہم) مہر دے کر شرحبیل بن حسنہ رضی اللہ عنہ کے ہمراہ انہیں آپ صلی اللہ علیہ وسلم کے پاس روانہ کر دیا ۱؎۔ ابوداؤد کہتے ہیں: حسنہ شرحبیل کی والدہ ۲؎ ہیں۔\n§وضاحت\n۱؎ : ازواج مطہرات رضی اللہ عنہن میں سب سے زیادہ انہیں کا مہر تھا، باقی ازاواج مطہرات اور صاحبزادیوں کا مہر حد سے حد پانچ سو درہم تک تھا، جیسا کہ حدیث نمبر (۲۱۰۵) میں گزرا۔ ۲؎ : یہ والد کے بجائے اپنی والدہ کی طرف منسوب کئے جاتے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ ام حبیبہ رضی اللہ عنہا ا (اپنے متعلق) بیان کرتی ہیں کہ یہ پہلے عبیداللہ بن حجش کی زوجیت میں تھیں اور وہ حبشہ جا کر فوت ہو گیا تو نجاشی نے ان سے شادی نبی کریم صلی اللہ علیہ وسلم کے ساتھ کر دی اور اپنی طرف سے ان کو چار ہزار (درہم) مہر ادا کیا۔ پھر انہیں شرجیل بن حسنہ رضی اللہ عنہ کی معیت میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں بھیج دیا۔ امام ابوداؤد رضی اللہ عنہ وضاحت فرماتے ہیں کہ شرجیل بن حسنہ میں ” حسنہ “ ان کی والدہ کا نام ہے۔","f2":"1: غنی اور صاحب وسعت آدمی کی حیثیت کے مطابق زیادہ مہر دے تو اچھی بات کہے کوئی ناجائز نہیں۔ تاہم محض دکھاوے کی نیت سے زیادہ سے زیادہ مہر مقرر کر لینا اور پھر اسے ادا نہ کرنا،یکسر غلط ہے اسی طرح وسعت ہونے کے باوجود برائے نام مہر مقرر کرنا بھی غلط ہے، حق مہر کم یا زیادہ،طاقت کے مطابق ہونا چاہیے اور اس کی ادائیگی بھی ضروری ہے۔\n2: علاوہ ازیں اس سلسلے میں کوئی دوسرا کفیل بن جائے تو درست تو درست ہے،کوئی حرج نہیں بلکہ نیکی میں تعاون ہے۔"}],[2108,"ابن شہاب زہری سے روایت ہے کہ نجاشی (شاہ حبشہ) نے ام حبیبہ بنت ابی سفیان رضی اللہ عنہما کا نکاح رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چار ہزار درہم کے عوض کر دیا اور یہ بات آپ کو لکھ بھیجی تو آپ نے قبول فرما لیا۔","ضعیف",{"u2":"امام زہری رضی اللہ عنہ کا بیان ہے کہ نجاشی نے ام حبیبہ بنت ابی سفیان رضی اللہ عنہا ا کا رسول اللہ صلی اللہ علیہ وسلم سے نکاح کر دیا، اور چار ہزار درہم مہر ادا کیا۔ اور یہ خبر رسول اللہ صلی اللہ علیہ وسلم کو لکھ بھیجی تو آپ صلی اللہ علیہ وسلم نے اسے قبول فر لیا۔","f2":"2086نمبر حدیث کے ہی فوائد دیکھ لیں-"}],[2109,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن بن عوف رضی اللہ عنہ کے جسم پر زعفران کا اثر دیکھا تو پوچھا: \"یہ کیا ہے؟\" انہوں نے کہا: اللہ کے رسول! میں نے ایک عورت سے شادی کر لی ہے، پوچھا: \"اسے کتنا مہر دیا ہے؟\" جواب دیا: گٹھلی (نواۃ ۱؎) کے برابر سونا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ولیمہ کرو چاہے ایک بکری سے ہی کیوں نہ ہو ۲؎\"۔\n§وضاحت\n۱؎ : نواۃ پانچ سو درہم کو کہتے ہیں، یعنی پانچ درہم (لگ بھگ پندرہ گرام) کے برابر سونا مہر مقرر کیا اور بعضوں نے کہا ہے کہ نواۃ سے کھجور کی گٹھلی مراد ہے۔ ۲؎ : یہ بات آپ صلی اللہ علیہ وسلم نے عبدالرحمن بن عوف رضی اللہ عنہ کی مالی حیثیت دیکھ کر کہی تھی کہ ولیمہ میں کم سے کم ایک بکری ضرور ہو اس سے اس بات پر استدلال درست نہیں کہ ولیمہ میں گوشت ضروری ہے کیونکہ آپ صلی اللہ علیہ وسلم نے صفیہ رضی اللہ عنہا کے ولیمہ میں ستو اور کھجور ہی پر اکتفا کیا تھا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبدالرحمٰن بن عوف رضی اللہ عنہ پر زغفران کے نشانات دیکھے۔ تو نبی کریم صلی اللہ علیہ وسلم نے پوچھا ” یہ کیا ہے؟ “ انہوں نے کہا: اے ا اللہ کے رسول! میں نے ایک عورت سے شادی کر لی ہے۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا ” مہر کتنا دیا ہے؟ “ کہا کہ گٹھلی کے وزن کے برابر سونا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ولیمہ کرو اگرچہ ایک بکری ہی کا ہو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں ایک ” نواۃ “ (گٹھلی) پانچ درہم کے برابر ہوتی ہے اور نش بیس درہم کا اور اوقیہ چالیس درہم کا۔","f2":"1: انسان کو اپنی اسطاعت کے مطابق حق مہر باندھنا چاہیے جو لینا دینا آسان ہو۔\n2: زعفران اور دیگر رنگدار چیزیں (پاوڈر) مردوں کو استعمال کر نا جائز نہیں۔\n3: شادی یا غمی کے موقع پر بھی قریب وبعید کے عزیزواقارب کو بلا کسی اہم مقصد کے جمع کرنا کوئی سنت نہیں ہے ایک چھوٹی سی بستی میں رہتے ہوئے حضرت عبدالرحمن بن عوف کی شادی ہوئی اور رسول صلی اللہ علیہ وسلم کو خبر نہیں دی گئی۔\n4:اصل سنت ولیمہ ہے حسب استطاعت جو میسر آئے بکری ہو یا کم و پیش کچھ اور جیسے کہ رسول صلی اللہ علیہ وسلم نے سیدہ صفیہ رضی اللہ کے ولیمہ میں ستو ہی پیش فرمائے تھے۔\n5: اس اعتبار سے دیکھا جائے تو ہماری شادیاں،سراسر اسلامی تعلیمات کے خلاف ہیں۔ مثلا لمبی چوڑی براتیں اور پھر ان کی پر تکلف ضیافت۔ اسی طرح ولیمے میں انواع واقسام کے کھانوں کی بھر مار اور دیگر رسومات اس اسراف وتبذیر اور فضولیات کی اسلام میں کوئی گنجائش نہیں۔(تفصیل کے لیےدیکھیں’’مسنون نکاح اور شادی بیاں کی رسومات‘مطبوعہ دار السلام‘‘تالیف..حافظ صلاح الدین یوسف صاحب.)"}],[2110,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی عورت کو مہر میں مٹھی بھر ستو یا کھجور دیا تو اس نے (اس عورت کو اپنے لیے) حلال کر لیا\"۔ ابوداؤد کہتے ہیں: اسے عبدالرحمٰن بن مہدی نے صالح بن رومان سے انہوں نے ابوزبیر سے انہوں نے جابر رضی اللہ عنہ سے موقوفاً روایت کیا ہے اور اسے ابوعاصم نے صالح بن رومان سے، صالح نے ابو الزبیر سے، ابو الزبیر نے جابر رضی اللہ عنہ سے روایت کیا ہے اس میں ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک مٹھی اناج دے کر متعہ کرتے تھے ۱؎۔ ابوداؤد کہتے ہیں: اسے ابن جریج نے ابو الزبیر سے انہوں نے جابر سے ابوعاصم کی روایت کے ہم معنی روایت کیا ہے۔\n§وضاحت\n۱؎ : یہ بات متعہ کی حرمت سے پہلے کی ہے ،جیسا کہ مؤلف کے ذکر کردہ کلام سے ظاہر ہو رہا ہے۔","ضعیف",{"u2":"موسیٰ بن مسلم بن رومان ‘ ابوالزبیر سے ‘ وہ سیدنا جابر بن عبداللہ رضی اللہ عنہ سے نقل کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس شخص نے کسی عورت کو مہر میں دو ہاتھ بھر کر ستو دے دیے یا کھجور ‘ اس نے اس کو حلال کر لیا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو عبدالرحمٰن بن مھدی نے صالح بن رومان سے ‘ انہوں نے ابو الزبیر سے ‘ انہوں نے جابر بن عبداللہ رضی اللہ عنہ سے موقوف روایت کیا ہے۔ اور ابوعاصم نے صالح بن رومان سے انہوں نے ابوالزبیر سے انہوں نے جابر رضی اللہ عنہ سے روایت میں کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں ہم ایک مٹھی طعام پر متعہ کر لیا کرتے تھے۔ امام ابوداؤد رضی اللہ عنہ نے فرمایا اس کو ابن جریج نے بواسطہ ابو الزبیر ‘ جابر رضی اللہ عنہ سے ابوعاصم کی طرح بیان کیا۔","f2":"نکاح متعہ خیبر سے پہلے حلال تھا،بعد میں بھی کچھ اوقات میں حلال رہا۔ مگر فتح مکہ کے موقع پر کلیتا حرام کر دیا گیا۔ یہ قصہ نزول حرمت سے پہلے کا ہو سکتا ہے اور اس میں اصل بات کم سے کم مہرکا ذکر ہے جو کہ شرعی حلال نکاح لازمی جزو ہے۔ متعہ کے باقی امور منسوخ کرکے حرام قراد دیے جاچکے ہیں۔(مزید دیکھے.ّفوائد حدیث نمبر2073)"}],[2111,"سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ایک عورت حاضر ہوئی اور اس نے عرض کیا: اللہ کے رسول! میں نے اپنے آپ کو آپ کے لیے ہبہ کر دیا ہے، پھر وہ کافی دیر کھڑی رہی (اور آپ صلی اللہ علیہ وسلم نے کوئی جواب نہیں دیا) تو ایک شخص کھڑا ہوا اور کہنے لگا: اللہ کے رسول! اگر آپ کو حاجت نہیں تو اس سے میرا نکاح کرا دیجئیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہارے پاس اسے مہر میں ادا کرنے کے لیے کچھ ہے؟\" وہ بولا: میرے اس تہبند کے علاوہ میرے پاس کچھ بھی نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم اپنا ازار اسے (مہر میں) دے دو گے تو تمہارے پاس تو ازار بھی نہیں رہے گا، لہٰذا کوئی اور چیز تلاش کرو\"، وہ بولا: اور تو کچھ بھی نہیں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تلاش کرو چاہے لوہے کی انگوٹھی ہی کیوں نہ ہو\"، تو اس نے تلاش کیا لیکن اسے کچھ نہ ملا تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: \"کیا تجھے کچھ قرآن یاد ہے؟\" کہنے لگا: ہاں فلاں فلاں سورتیں یاد ہیں، ان کا نام لے کر اس نے بتایا تو آپ صلی اللہ علیہ وسلم نے اس سے کہا: \"جو کچھ تجھے قرآن یاد ہے اسی کے (یاد کرانے کے) بدلے میں نے اس کے ساتھ تیرا نکاح کر دیا ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ مہر میں مال کی کوئی تحدید نہیں، خواہ قلیل ہو یا کثیر اس طرح محنت مزدوری یا تعلیم قرآن پر بھی نکاح درست ہے، جمہور علما کی یہی رائے ہے، اور بعض نے دس درہم کی تحدید کی ہے، ان کے نزدیک اس سے کم میں مہر درست نہیں، لیکن ان کے دلائل اس قابل نہیں کہ ان صحیح احادیث کا معارضہ کر سکیں۔","صحیح",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ کا بیان ہے کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی اور کہنے لگی: اے ا اللہ کے رسول! میں اپنے آپ کو آپ کی خدمت میں ہبہ کرتی ہوں ‘ اور پھر وہ بہت دیر کھڑی رہی۔ تب ایک آدمی اٹھا اور کہنے لگا: اے ا اللہ کے رسول! اگر آپ کو اس میں رغبت نہیں تو اس کی شادی مجھ سے کر دیجئیے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کیا تمہارے پاس کچھ ہے جو اسے مہر کے طور پر دے سکو؟ کہنے لگا میرے پاس تو بس یہ تہ بند ہی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم اگر اپنا تہ بند اس کو دے دو گے تو خود تہ بند کے بغیر بیٹھ رہو گے ‘ کوئی اور چیز ڈھونڈو۔ “ کہنے لگا میرے پاس تو اور کچھ نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ڈھونڈ لاؤ خواہ لوہے کا چھلہ ہی ہو۔ “ اس نے تلاش کیا مگر اسے کچھ نہ ملا۔ تب رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا ” کیا تمہیں قرآن سے کچھ یاد ہے؟ “ کہنے لگا ہاں، فلاں فلاں سورتیں۔ اس نے ان کے نام لیے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس قرآن کے عوض ‘ جو تمہیں یاد ہے ‘ میں اس کا نکاح تمہارے ساتھ کرتا ہوں۔ “"}],[2112,"ابوہریرہ رضی اللہ عنہ سے بھی اسی واقعہ کی طرح مروی ہے لیکن اس میں تہبند اور انگوٹھی کا ذکر نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا:\"تجھے قرآن میں سے کیا یاد ہے؟\" جواب دیا: سورۃ البقرہ یا اس کے بعد والی سورت تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ اسے بیس آیتیں سکھا دو اور وہ تمہاری بیوی ہے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے اسی قصہ کی مانند ذکر کیا مگر اس میں تہ بند اور چھلے کا ذکر نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے اس سے پوچھا ” تجھے قرآن کس قدر یاد ہے؟ “ اس نے کہا: سورۃ البقرہ یا اس کے ساتھ والی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” جاؤ، اسے بیس آیتیں پڑھا دو اور یہ تمہاری بیوی ہوئی۔ “"}],[2113,"مکحول سے بھی سہل کی روایت کی طرح مروی ہے، مکحول کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی کے لیے یہ درست نہیں۔","ضعیف",{"u2":"محمد بن راشد نے مکحول سے سیدنا سہل بن سعد رضی اللہ عنہ کی روایت کی مانند بیان کیا، مکحول کہا کرتے تھے کہ یہ عمل رسول اللہ صلی اللہ علیہ وسلم کے بعد کسی اور کے لیے روا نہیں ہے۔","f2":"1: پہلی حدیث (2111) میں اس محترمہ خاتون کا اپنے آپ کو رسول صلی اللہ علیہ وسلم کے لئے بطور ہبہ پیش کرنا ایک عظیم ترین شرف حاصل کرنے کی کوشش تھی جو کامیاب نہ ہو سکی مگر رسول صلی اللہ علیہ وسلم از خواس کے لئے ولی بن گئے اور ایک صاحب قرآن سے اس کا نکاح کر دیا اور مسئلہ ہبہ صرف اور صرف رسول صلی اللہ علیہ وسلم کے لئے محضوص ہے،کسی اور کے لئے نہیں۔ سورۃ احزاب میں ہے (وامراۃ مومنتہ ان وھبت نفسا اللنبی ان ارداالنبی ان یستنکحھا خالصۃ لگ من دون المومینین) (الاحزاب: 50) اور ایمان دا ر عورت جو اپنا نفس نبی کو ہیبہ کر دے،اس صورت میں کہ نبی بھی اس سے نکاح کرنا چاہے،یہ خاص طور پر صرف آپ کے لئے ہے اور مومنوں کے لئے نہیں۔\n2: حق مہر مال کی صورت میں ہونا ہی اولی ہے، کم سے کم مقدار بھی اس مقصد کو پورا کر دیتی ہے اور ایسی تمام روایات جو پانچ یا دس درہم وغیرہ کو متعین کرنے کے بارے میں آئی ہیں تا قابل حجت ہیں۔\n3: اس میں یہ بھی ہے کہ ازحد فقیر کنگال کا بھی نکاح کیا جا سکتا ہے۔\n4: اور تعلیم کو بھی حق مہر بنایا جا سکتا ہے،امام شافعی،امام احمد رحمہ اللہ اور ان کے اصحاب اسی کے قائل ہیں،متحدہ ہندوستان میں تحریک جہاد کے مو سسین نے اس سنت کو زندہ کیا تھا۔ مولانا ولایت علی رحمہ اللہ نے جنہوں نے شاہ اسماعیل شہید رحمہ اللہ کے بعد تحریک جہاد کی قیادت سنبھالی اور اس راہ میں بے مثال قربانی اور عزیمت کا نمونہ پیش کیا،متحدہ ہند میں احیائے سنت کے سلسلے میں بھی بڑے سرگرم رہے۔ نکاح بیوگان کے سلسلہ میں قابل ذکر بات یہ ہے کہ ایک شخص عبد الغنی انگر نہسوی (جو زمرہ مساکین میں سے تھے)کا عقد ایک بیوہ عورت سے تعلم قرآن مہر قراردے کر کر دیا۔ (ہندوستان کی پہلی اسلامی تحریک) امام ابو حنیفہ اور امام مالک رحمہ اللہ اس کے قائل نہیں ہیں،جیسے کہ آخری اثر میں جنات مکحول رحمہ اللہ سے منقول ہوا ہے مگر یہ قول مرجوع ہے۔\n5: کوئی خاتوناپنئ نکاح کے سلسلے میں جنبانی کرے تو کوئی عیب کی بات نہیں ہے ایسے ہی کوئی ولی اپنی زیر تولیت لڑکی کے لئے رشتے آنے کا انتظار کرنے کی بجائے از خو دکسی سے بات کرے تو یہ بھی عیب والی بات نہیں۔"}],[2114,"عبداللہ بن مسعود رضی اللہ عنہ سے اس شخص کے بارے میں مروی ہے جس نے کسی عورت سے نکاح کیا اور پھر اس سے ہمبستری کرنے سے پہلے اور اس کا مہر متعین کرنے سے پہلے وہ انتقال کر گیا تو انہوں نے کہا: اس عورت کو پورا مہر ملے گا اور اس پر عدت لازم ہو گی اور اسے میراث سے حصہ ملے گا۔ اس پر معقل بن سنان رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ نے بروع بنت واشق کے سلسلے میں اسی کا فیصلہ فرمایا۔","صحیح",{"u2":"جناب مسروق رضی اللہ عنہ سے مروی ہے کہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مسئلہ پوچھا گیا کہ ایک شخص نے کسی عورت سے شادی کی ‘ پھر وفات پا گیا جبکہ ان کا ملاپ نہ ہوا تھا اور نہ ہی حق مہر مقرر کیا تھا (تو اس صورت میں کیا حکم ہے؟) انہوں نے فرمایا اس عورت کے لیے پورا مہر ہے، اس پر عدت لازم ہے اور یہ وراثت کی بھی حقدار ہے۔ (تب) معقل بن سنان رضی اللہ عنہ نے بتایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے (ایسے ہی) سنا تھا آپ نے بروع بنت واشق کے بارے میں یہی فیصلہ فرمایا تھا۔"}],[2115,"اس سند سے بھی عبداللہ سے مروی ہے عثمان نے اسی کے مثل روایت بیان کی۔","صحیح",{"u2":"عثمان بن ابی شیبہ اپنی سند سے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے اسی طرح روایت کرتے ہیں۔"}],[2116,"عبداللہ بن عتبہ بن مسعود سے روایت ہے کہ عبداللہ بن مسعود رضی اللہ عنہ کے پاس ایک شخص کا یہی مسئلہ پیش کیا گیا، راوی کا بیان ہے کہ لوگوں کی اس سلسلہ میں مہینہ بھر یا کہا کئی بار آپ کے پاس آمدورفت رہی، انہوں نے کہا: اس سلسلے میں میرا فیصلہ یہی ہے کہ بلا کم و کاست اسے اپنی قوم کی عورتوں کی طرح مہر ملے گا، وہ میراث کی حقدار ہو گی اور اس پر عدت بھی ہو گی، اگر میرا فیصلہ درست ہے تو اللہ تعالی کی جانب سے ہے، اگر غلط ہے تو میری جانب سے اور شیطان کی طرف سے ہے، اللہ اور اللہ کے رسول اس سے بری ہیں، چنانچہ قبیلہ اشجع کے کچھ لوگ جن میں جراح و ابوسنان بھی تھے کھڑے ہوئے اور کہنے لگے: ابن مسعود! ہم گواہ ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم میں بروع بنت واشق - جن کے شوہر ہلال بن مرہ اشجعی ہیں، کے سلسلہ میں ایسا ہی فیصلہ کیا تھا جو آپ نے کیا ہے، عبداللہ بن مسعود رضی اللہ عنہ کو جب ان کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم کے فیصلہ کے موافق ہو گیا تو بڑی خوشی ہوئی۔","صحیح",{"u2":"عبداللہ بن عتبہ بن مسعود، سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کرتے ہیں کہ ایک شخص کے بارے میں سیدنا عبداللہ رضی اللہ عنہ کو یہ خبر دی گئی۔ اور پھر وہ لوگ ایک مہینہ تک ان کے پاس چکر لگاتے رہے۔ یا کہا کئی بار ان کے پاس آئے۔ تو بلآخر یہ کہا: میری رائے اس میں یہ ہے کہ یہ عورت مہر کی حقدار ہے جیسے کہ اس طرح کی عورتوں کا حق مہر ہوتا ہے (مہر مثل) بغیر کسی کمی بیشی کے۔ اور یہ میراث کی حقدار ہے اور اس پر عدت (وفات) بھی لازم ہے۔ اگر میری یہ بات حق اور درست ہے تو ا اللہ کی جانب سے ہے اور اگر غلط ہے تو میری طرف سے ہے اور شیطان کی طرف سے ‘ ا اللہ اور اس کے رسول دونوں اس سے بری ہیں۔ چنانچہ قبیلہ اشجع کے لوگ کھڑے ہوئے ان میں جراح اور ابوسنان بھی تھے ‘ انہوں نے کہا: اے ابن مسعود! ہم گواہی دیتے ہیں کہ یہی فیصلہ رسول اللہ صلی اللہ علیہ وسلم نے ہماری ایک عورت بروع بنت واشق اور اس کے شوہر ہلال بن مرہ اشجعی کے بارے میں فرمایا تھا ‘ جیسے کہ آپ نے کیا ہے۔ راوی نے بیان کیا کہ اس سے سیدنا عبداللہ بن مسعود رضی اللہ عنہ کو بےحد خوشی ہوئی کہ ان کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم کے فیصلے کے مطابق ہوا ہے۔","f2":"1.ہر مسلمان کو اپنے اہم مسائل میں باوثوق علماء کی طرف رجوع کرنا چاہیے اور عالم پر بھی لازم ہے کہ فتو دینے اور فیصلہ کرنے سے پہلے خوب غور وخوض کر لے اور جہاں تک ہوسکے اپنی رائے کا فیصلہ نہ دے اگر دے تو اس کے احتمال وصواب کا یقین رکھے۔\n2: انسان قرآن وسنت کو اپنا رہنما بنالے تو اللہ عزوجل مشکل مسائل میں اس کی رہنمائی فرماتا ہے اور حضرت عبداللہ مسعودرضی اللہ اور تمام اجلہ صحابہ کرام،فقہائے اسلام امت مسلمہ کے سلف صالح ہیں۔\n3: نکاح کے وقت اگر حق مہر مقرر نہ کیا گیا ہو تو نکاح صحیح ہے۔ مگر مہر مثل لازم آئے گا۔\n4: ایسی عورت جس سے اس کے شوہر کا ملاپ نہ ہو،شوہر کی وفات پر عدت وفات پوری کرے،شوہر کے حق واحترام میں نہ کہ حمل کے شبہ میں۔"}],[2117,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا: \"کیا تم اس بات سے راضی ہو کہ میں تمہارا نکاح فلاں عورت سے کر دوں؟\" اس نے جواب دیا: ہاں، پھر عورت سے کہا: \"کیا تم اس بات سے راضی ہو کہ فلاں مرد سے تمہارا نکاح کر دوں؟\" اس نے بھی جواب دیا: ہاں، چنانچہ آپ صلی اللہ علیہ وسلم نے ان دونوں کا نکاح کر دیا، اور آدمی نے اس سے صحبت کر لی لیکن نہ تو اس نے مہر متعین کیا اور نہ ہی اسے کوئی چیز دی، یہ شخص غزوہ حدیبیہ میں شریک تھا اور اسی بنا پر اسے خیبر سے حصہ ملتا تھا، جب اس کی وفات کا وقت ہوا تو کہنے لگا کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں عورت سے میرا نکاح کرایا تھا، لیکن میں نے نہ تو اس کا مہر مقرر کیا اور نہ اسے کچھ دیا، لہٰذا میں تمہیں گواہ بناتا ہوں کہ میں نے اپنا خیبر سے ملنے والا حصہ اس کے مہر میں دے دیا، چنانچہ اس عورت نے وہ حصہ لے کر ایک لاکھ میں فروخت کیا۔ ابوداؤد کہتے ہیں: عمر بن خطاب رضی اللہ عنہ نے حدیث کے شروع میں ان الفاظ کا اضافہ کیا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہتر نکاح وہ ہے جو سب سے آسان ہو\" اور ان کی حدیث سب سے زیادہ کامل ہے اور اس میں «إن رسول الله صلی اللہ علیہ وسلم قال للرجل» کے بجائے «قال رسول الله صلی اللہ علیہ وسلم للرجل» ہے پھر راوی نے اسی مفہوم کی حدیث ذکر کی۔ ابوداؤد کہتے ہیں: اندیشہ ہے کہ یہ حدیث الحاقی ہو کیونکہ معاملہ اس کے برعکس ہے ۱؎۔\n§وضاحت\n۱؎ : کیونکہ درحقیقت مرض الموت میں اس شخص نے مہر سے زائد کی بابت ایسا کہا تھا۔","صحیح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ایک شخص سے کہا: ” کیا تم راضی ہو کہ فلاں عورت سے تمہاری شادی کر دوں؟ اس نے کہا: جی ہاں پھر آپ نے عورت سے پوچھا ” کیا تو راضی ہے کہ فلاں مرد سے تیری شادی کر دوں؟ “ تو اس نے کہا: جی ہاں! چنانچہ آپ نے ان دونوں کی شادی کر دی۔ اور پھر اس مرد نے اس سے صحبت کی مگر حق مہر مقرر نہ کیا اور نہ اسے کچھ دیا۔ اور یہ ان لوگوں میں سے تھا جو حدیبیہ میں شریک ہو چکے تھے اور شرکائے حدیبیہ کو خیبر میں حصہ ملا تھا۔ جب اس کی وفات کا وقت آیا تو اس نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں عورت سے میری شادی کر دی تھی مگر میں نے اس کے لیے مہر مقرر نہیں کیا تھا اور نہ اسے کچھ دیا تھا ‘ اور میں تمہیں گواہ بناتا ہوں کہ میں اسے مہر میں اپنا خیبر کا حصہ دیتا ہوں۔ چنانچہ اس عورت نے وہ حصہ لیا اور پھر اسے ایک لاکھ میں فروخت کر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے ابتدائے حدیث میں اس قدر اضافہ کیا اور اس کی حدیث زیادہ کامل ہے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بہترین نکاح وہی ہے جو زیادہ آسانی والا ہو۔ “ اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس آدمی سے کہا:، اس کے بعد مذکورہ بالا حدیث کی مانند حدیث بیان کی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: اندیشہ ہے کہ حدیث ملحق ہے کیونکہ امر واقعہ اس کے خلاف ہے۔","f2":"اصل مسئلہ یہ ہے کہ حق مہر مقرر نہ ہونے کی صورت میں عورت مہر مثل کی مستحق ہوتی ہے بشرطیکہ اس سے صحبت کرلی گئی جگکہ واقعہ میں اسے مہر زیادہ دیا گیا۔ اس لئے امام صاحب اس واقعہ کے خلاف تعبیر فرمایا۔ علاوہ ازیں روایت کا یہ ٹکڑاابو داودکے اکثر نسخوں میں نہیں ہے۔"}],[2118,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ حاجت اس طرح سکھایا: «إن الحمد لله نستعينه ونستغفره ونعوذ به من شرور أنفسنا من يهد الله فلا مضل له ومن يضلل فلا هادي له وأشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله» «يا أيها الذين آمنوا اتقوا الله الذي تساءلون به والأرحام إن الله كان عليكم رقيبا» \"اے ایمان والو! اس اللہ سے ڈرو جس کے نام پر ایک دوسرے سے مانگتے ہو اور رشتے ناتے توڑنے سے بھی بچو بیشک اللہ تعالی تم پر نگہبان ہے\" (سورۃ النساء: ۱) «يا أيها الذين آمنوا اتقوا الله حق تقاته ولا تموتن إلا وأنتم مسلمون» \"اے ایمان والو! اللہ سے ڈرو جیسا کہ اس سے ڈرنے کا حق ہے اور مسلمان ہی رہ کر مرو\" (سورۃ آل عمران: ۱۰۲) ۔ «يا أيها الذين آمنوا اتقوا الله وقولوا قولا سديدا * يصلح لكم أعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما» \"اے ایمان والو! اللہ سے ڈرو اور نپی تلی بات کہو اللہ تعالی تمہارے کام سنوار دے گا اور تمہارے گناہ معاف کر دے گا اور جو بھی اللہ اور اس کے رسول کی تابعداری کرے گا اس نے بڑی مراد پالی\" (سورۃ الاحزاب: ۷۱، ۷۰)، محمد بن سلیمان کی روایت میں «إن» نہیں ہے۔","صحیح",{"u2":"سیدناعبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں خطبہ حاجت تعلیم فرمایا وہ یہ کہ «إن الحمد لله نستعينه ونستغفره ونعوذ به من شرور أنفسنا من يهد الله فلا مضل له ومن يضلل فلا هادي له وأشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله» ” تمام تعریفیں اللہ کے لیے ہیں۔ ہم اسی سے مدد چاہتے ہیں۔ اور (اپنے گناہوں کی) معافی چاہتے ہیں اور اپنے نفسوں کی شرارتوں سے اس کی پناہ چاہتے ہیں۔ جسے وہ راہ حق سجھا دے کوئی اسے گمراہ نہیں کر سکتا، اور جسے وہ گمراہ کر دے اس کے لیے کوئی راہن نہیں ہو سکتا۔ اور میں گواہی دیتا ہوں کہ اللہ عزوجل کے سوا اور کوئی معبود برحق نہیں۔ اور میں گواہی دیتا ہوں کہ محمد (صلی اللہ علیہ وسلم) اس کے بندے اور اس کے رسول ہیں۔ “ ” اے لوگو جو ایمان لائے ہو! اللہ کا تقویٰ اختیار کرو جس کے واسطے سے تم سوال کرتے ہو، اور رشتے ناتے (توڑنے) سے بچو، بلاشبہ اللہ تعالیٰ تم پر نگہبان ہے۔“ ” اے ایمان والو! اللہ کا تقویٰ اختیار کرو اور اس سے ڈرو جیسے کہ اس سے ڈرنے کا حق ہے اور تم پر موت نہ آئے مگر اس حال میں کہ تم مسلمان ہو۔ “ ” اے ایمان والو! اللہ کا تقویٰ اختیار کرو اور بات ہمیشہ صاف سیدھی کیا کرو۔ اللہ تعالیٰ تمہارے اعمال درست فر دے گا، تمہاری خطائیں معاف کر دے گا، اور جس نے اللہ اور اس کے رسول کی اطاعت کر لی بلاشبہ وہ عظیم کامیابی سے ہمکنار ہوا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ محمد بن سلیمان نے (شروع روایت میں) لفظ «أن» ذکر نہیں کیا۔","f2":"1:ا جتماعی مسائل میں گفتگو سے پہلے یہ خطبہ پڑھنا مستحب ومسنون ہے،بالخصوص عقدر نکاح کے موقع پر آداب نکاح میں شامل ہے مگر عمل نکاح کارکن نہیں ہے۔ نکاح کے لئے ایجاب وقبول ہی لازمی شرط ہے۔ اس خطبہ کی جامع اور صحیح ترین نص کو علامہ البانی رحمہ اللہ نے خطبہ الحاجۃ میں جمع فرما دیا ہے۔\n2: (شرور النفس) نفس کی شرارتوں سے مراد اخلاقی اور سفلہ پن وغیرہ کی عادات ہیں،وہ انفرادی ہوں یا اجتماعی،لہذاکسی بھی فرد یا معاشرے کو اپنے بارے میں دھوکے میں نہیں رہنا چاہیے بلکہ ہمیشہ اللہ تعالی سے استغفار کرتے رہنا چاہیے۔ شیطان کے پھندے بڑے سخت ہیں۔\n3: حدیث کے سیاق میں (یا ایھاالذین امنواتقواللہ الذی تسا ء لون بہ والا ارحام) قرآن مجید کی آیت نہیں،اس آیت کا معنی ومفہوم کہا جا سکتا ہے جو کہ سورۃ نساء کی ابتدا وارد ہے (یا ایھا الناس اتقو ربکم الذی خلقکم من نفس واحدۃ وخلق منھا زوجھا وبث منھما رجالا کثیر ونسا ء اتقواللہ الذی تساء لون بہ والارحام ان اللہ کا ن علیکم راقیبا)(النساء:1) ودیگر روایات میں یہ آیت کریمہ اسی طرح کامل طور پر آئی ہے۔"}],[2119,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب خطبہ پڑھتے، پھر راوی نے اسی طرح کی حدیث ذکر کی لیکن اس میں «ورسوله» کے بعد یہ الفاظ زائد ہیں: «أرسله بالحق بشيرا ونذيرا بين يدى الساعة من يطع الله ورسوله فقد رشد ومن يعصهما فإنه لا يضر إلا نفسه ولا يضر الله شيئا» \"اللہ نے آپ کو حق کے ساتھ قیامت سے پہلے خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا ہے، جو شخص اللہ اور اس کے رسول کی فرمابرداری کرے گا، وہ ہدایت پا چکا، اور جو ان کی نافرمانی کرے گا تو وہ اللہ کا کچھ نہ بگاڑے گا بلکہ اپنے آپ ہی کو نقصان پہنچائے گا\"۔","ضعیف",{"u2":"سیدنا ابن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب خطبہ پڑھتے، تو گزشتہ حدیث کے مثل ذکر کیا۔ اور «محمدا عبده ورسوله» کے بعد یہ کہتے «أرسله بالحق بشيرا ونذيرا بين يدي الساعة، من يطع الله ورسوله فقد رشد، ومن يعصه فإنه لا يضر إلا نفسه ولا يضر الله شيئا» ” اللہ نے ان کو حق دے کر خوشخبری دینے والا اور ڈرانے والا بنا کر بھیجا کہ قیامت سے پہلے پہلے لوگوں کو متنبہ کر دیں۔ جس نے بھی اللہ اور اس کے رسول کی اطاعت کی وہ یقیناً ہدایت پا گیا اور جس نے ان کی نافرمانی کی اس نے اپنا ہی نقصان کیا، وہ اللہ کا کوئی نقصان نہیں کر سکتا۔ “"}],[2120,"بنی سلیم کے ایک شخص کہتے ہیں میں نے امامہ بنت عبدالمطلب سے نکاح کے لیے نبی اکرم صلی اللہ علیہ وسلم کے پاس پیغام بھیجا تو آپ نے بغیر خطبہ پڑھے ان سے میرا نکاح کر دیا۔","ضعیف",{"u2":"اسمعیل بن ابراہیم، بنو سلیم کے ایک شخص روایت کرتے ہیں کہ میں نے نبی کریم صلی اللہ علیہ وسلم سے امامہ بنت عبدالمطلب کا رشتہ طلب کیا تو آپ صلی اللہ علیہ وسلم نے اس کا مجھ سے نکاح کر دیا اور خطبہ بھی نہ پڑھا۔ ہمیں ابوعیسیٰ نے بتایا کہ امام ابوداؤد رضی اللہ عنہ سے پوچھا گیا: کیا یہ جائز ہے؟ انہوں نے کہا: ہاں، اس بارے میں نبی کریم صلی اللہ علیہ وسلم سے احادیث آتی ہیں۔","f2":"یہ روایت ضعیف ہے لیکن یہ بات دوسری روایات سے ثابت ہے کہ نکاح،خطبے کے بغیر بھی جائز ہے،کیو نکہ نکاح کے لئے صرف ولی کی اجازت دو گواہوں کی موجودگی اور ایجاب وقبول ضروری ہے۔"}],[2121,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول صلی اللہ علیہ وسلم نے مجھ سے شادی کی، اس وقت سات سال کی تھی (سلیمان کی روایت میں ہے: چھ سال کی تھی) اور آپ صلی اللہ علیہ وسلم میرے پاس آئے (شب زفاف منائی) اس وقت میں نو برس کی تھی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے شادی کی تو اس وقت میری عمر سات سال تھی۔ سلیمان نے کہا: یا چھ سال۔ اور مجھ سے ملاپ ہوا (میں آپ صلی اللہ علیہ وسلم کے گھر بھیجی گئی) تو میں نو سال کی تھی۔","f2":"والد کو بالخصوص حق حاصل ہے کی کسی مصلحت کے پیش نظر چھوٹی عمر کی بچی کا نکاح کردے،مگر صحبت ومباشرت کے لئے بلوغت کا شرط ہونا عقل،نقل اور اخلاق کا لازمی تقاضاہے اور چھوٹی عمرکا ازواج کسی طرح بھی منافی عقل وشرع نہیں ہے۔ اگر کسی کے مزاج پر اپنا ذوق اور علاقائی خاندانی رواج غالب ہو تو،کیا کہا جا سکتا ہے! ان چیزوں کو اصول شریعت نہیں بنایا جا سکتا اور پھر رسول صلی اللہ علیہ وسلم اور ابو بکر صدیق رضی اللہ کے تعلقات شروع دن سے صدیقیت پر مبنی تھے،نبی صلی اللہ علیہ وسلم ان کے احسانات کا بدلہ نہیں دے سکے تو ان کو اپنےاور قریب کر لیا۔ مزید برآں یہ نکاح بطور خاص وحی منام کے نتیجے میں عمل میں آیا تھا۔ جیسا کہ حدث میں اس کی تفصیل موجود ہے۔ علمائے طب لکھتے ہیں کہ گر م علاقوں میں لڑکیاں نو سال کی عمر میں حائضہ ہو جاتی ہیں اور معتدل مناطق میں بارہ سال میں اور ٹھنڈے علاقوں میں سولہ سال میں بالغ ہوتی ہیں۔ دار قطنی اور بیہقی میں عباد بن عباد سے روایت ہت کہ ہماری ایک عورت اٹھار ہ سال کی عمر میں نانی بن گئی تھی۔ امام بخاری رحمہ اللہ نے اسی طرح ایک واقعہ اکیس سال عمر کا بیان کیا ہے۔ (ازحاشیہ بذل المجھود)"}],[2122,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب ان سے نکاح کیا تو ان کے پاس تین رات رہے، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اسے اپنے خاندان کے لیے بے عزتی مت تصور کرنا، اگر تم چاہو تو میں تمہارے پاس سات رات رہ سکتا ہوں لیکن پھر اپنی اور بیویوں کے پاس بھی سات سات رات رہوں گا\"۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ان سے شادی کی تو آپ (شروع ایام میں) ان کے ہاں تین دن ٹھہرے، پھر فرمایا ” تم اپنے گھر والوں پر کوئی بے قدر و قیمت نہیں ہو۔ اگر چاہو تو میں تمہارے لیے سات دن رک جاتا ہوں۔ لیکن اگر تمہارے ہاں سات دن ٹھہرا، تو دیگر ازواج کے ہاں بھی سات سات ہی دن ٹھہروں گا۔ “","f2":"مسئلے کی توضیح اگلی حدیث (2124) میں آرہی ہے اس حدیث میں یہ ہے کہ اگر کسی نے بیوہ کے ہاں سات دن اقامت کی تو تین دن والی خصوصیت ختم ہو جائے گی اور باقیوں کے ہاں بھی سا ت دن ہی رکنا ہو گا۔"}],[2123,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے صفیہ رضی اللہ عنہا سے نکاح کیا تو ان کے پاس تین رات گزاری، اور وہ ثیبہ تھیں ۱؎۔\n§وضاحت\n۱؎ : عثمان بن ابی شیبہ کے الفاظ ہیں «کانت ثیباً» ثیبہ وہ عورت ہے جس کی شادی پہلے ہو چکی ہو۔","صحیح",{"u2":"سیدناانس بن مالک رضی اللہ عنہ کا بیان ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے صفیہ (صفیہ بنت حیی) کو لے لیا (شادی کر لی) تو ان کے ہاں تین دن اقامت کی۔ عثمان بن ابی شیبہ نے مزید کہا کہ وہ بیوہ تھیں۔ اور (ان کی سند میں تصریح تحدیث و اخبار ہے۔) انہوں نے کہا: «حدثني هشيم، أخبرنا حميد، أخبرنا أنس»۔"}],[2124,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ جب کوئی ثیبہ کے رہتے ہوئے کنواری سے شادی کرے تو اس کے ساتھ سات رات رہے، اور جب ثیبہ سے شادی کرے تو اس کے پاس تین رات رہے۔ راوی کا بیان ہے کہ اگر میں یہ کہوں کہ انس رضی اللہ عنہ نے اسے مرفوعاً بیان کیا ہے تو سچ ہے لیکن انہوں نے کہا کہ \"سنت اسی طرح ہے\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے کہا کہ اگر کوئی شخص (اپنے ہاں) بیوہ (بیوی) کے ہوتے ہوئے کنواری سے شادی کرے تو اس کے ہاں سات دن رکے۔ اور جب بیوہ سے شادی کرے تو اس کے ہاں تین دن۔ (ابوقلابہ نے) کہا: اگر میں کہوں کہ انہوں (انس رضی اللہ عنہ) نے اسے رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب کر کے (مرفوع) بیان کیا تو میں سچ ہی کہوں گا، لیکن انہوں نے کہا تھا ” سنت یہی ہے۔ “","f2":"1: صحابی کا کسی عمل کے بارے میں سنت کہہ دینا اس کے مرفوع ہونے کی دلیل ہوتی ہے۔\n2: تین یا سات دن کی خصوصیت ابتدائی دنوں کی ہے اس کے بعد عدل سے باری مقرر کر لی جائے اور طے شدہ نظام کے مطابق عمل کیا جائے۔"}],[2125,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جب علی رضی اللہ عنہ نے فاطمہ رضی اللہ عنہا سے شادی کی تو رسول اللہ صلی اللہ علیہ وسلم نے اُن سے کہا: \"اسے کچھ دے دو\"، انہوں نے کہا: میرے پاس تو کچھ بھی نہیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"تمہاری حطمی زرہ۱؎ کہاں ہے؟\" ۲؎۔\n§وضاحت\n۱؎ : ’’حطمي‘‘: زرہ ہے جو تلوار کو توڑ دے، یا حطمہ کوئی قبیلہ تھا جو زرہ بنایا کرتا تھا۔ ۲؎ : اس سے معلوم ہوا کہ شب زفاف (سہاگ رات) میں پہلی ملاقات کے وقت بیوی کو کچھ ہدیہ تحفہ دینا مستحب ہے۔","حسن صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہجب سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا ا سے شادی کی تو رسول اللہ صلی اللہ علیہ وسلم نے علی رضی اللہ عنہ سے فرمایا ” اس کو کوئی چیز دو۔ “ انہوں نے کہا: ” میرے پاس تو کوئی چیز نہیں ہے۔ “ آپ صلی اللہ علیہ وسلم نے فرمایا ” وہ تمہاری حطمی زرہ کہاں ہے؟ “"}],[2126,"محمد بن عبدالرحمٰن بن ثوبان سے روایت ہے وہ نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص سے روایت کرتے ہیں کہ جب علی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی فاطمہ رضی اللہ عنہا سے شادی کی اور ان کے پاس جانے کا ارادہ کیا تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں منع فرما دیا جب تک کہ وہ انہیں کچھ دے نہ دیں تو انہوں نے کہا: اللہ کے رسول! میرے پاس کچھ نہیں ہے، اس پر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اسے اپنی زرہ ہی دے دو\"، چنانچہ انہیں زرہ دے دی، پھر وہ ان کے پاس گئے۔","",{"u2":"نبی کریم صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص سے روایت ہے کہ علی رضی اللہ عنہ نے جب فاطمہ رضی اللہ عنہا ا دختر رسول صلی اللہ علیہ وسلم سے شادی کی اور ان کے ہاں جانا چاہا، تو رسول اللہ صلی اللہ علیہ وسلم نے ان کو روک لیا حتیٰ کہ پہلے کوئی چیز پیش کریں۔ انہوں نے کہا: اے اللہ کے رسول! میرے پاس کوئی چیز نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنی زرہ ہی دے دو۔ “ چنانچہ انہوں نے ان کو اپنی زرہ دی، پھر ان کے ہاں گئے۔"}],[2127,"اس سند سے ابن عباس رضی اللہ عنہما سے بھی اسی کے مثل مروی ہے۔","",{"u2":"عکرمہ رضی اللہ عنہ، سیدنا ابن عباس رضی اللہ عنہ سے اس کی مثل روایت کرتے ہیں۔","f2":"ا ن روایات سے واضح ہے کہ شب زفاف میں نئی نویل دولہن کو کوئی تحفہ دینا مستحب ہے کیو نکہ اس سے محبت میں اضافہ ہوتا ہے۔"}],[2128,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے ایک عورت کو اس کے شوہر کے پاس پہنچا دینے کا حکم دیا قبل اس کے کہ وہ اسے کچھ دے۔ ابوداؤد کہتے ہیں: خیثمہ کا سماع ام المؤمنین عائشہ رضی اللہ عنہا سے نہیں ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ کسی عورت کو اس کے شوہر پر پیش نہ کروں جب تک کہ وہ اس کو کوئی چیز نہ دیدے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ خیثمہ (عبدالرحمٰن جعفی) نے سیدہ عائشہ رضی اللہ عنہا ا سے نہیں سنا ہے۔"}],[2129,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس عورت نے مہر یا عطیہ یا وعدے پر نکاح کیا تو نکاح سے قبل ملنے والی چیز عورت کی ہو گی اور جو کچھ نکاح کے بعد ملے گا وہ اسی کا ہے جس کو دیا گیا (انعام وغیرہ)، مرد جس چیز کے سبب اپنے اکرام کا مستحق ہے وہ اس کی بیٹی یا بہن ہے\"۔","ضعیف",{"u2":"عمرو بن شعیب اپنے والد (شعیب) سے، وہ (اپنے) دادا (عبداللہ بن عمرو) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس عورت کا کسی سے نکاح ہو اور عقد نکاح سے پہلے جو کوئی مہر، عطیہ یا وعدہ کیا گیا ہو تو وہ سب اس عورت کا حق ہے۔ اور جو عقد کے بعد دیا جائے تو وہ اسی کا ہے جس کو دیا جائے۔ اور کسی کا سب سے عمدہ اکرام وہ ہے جو اس کی بیٹی یا بہن کی وجہ سے کیا جائے۔ “"}],[2130,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب کسی شخص کو شادی کی مبارکباد دیتے تو فرماتے: «بارك الله لك وبارك عليك وجمع بينكما في خير» \"اللہ تعالی تم کو برکت دے اور اس برکت کو قائم و دائم رکھے، اور تم دونوں کو خیر پر جمع کر دے\"۔","صحیح",{"u2":"سيدنا ابوہريرہ رضي اللہ عنہ سے روايت ہے کہ رسول اللہ صلي اللہ عليہ وسلم جب کسي کو اس کي شادي کي مبارک باد ديتے تو فرماتے «بارك الله لك وبارك عليك وجمع بينك في خير» اللہ تمہيں برکت دے، تم پر اپني برکت فرمائے اور تم دونوں کو خير کے ساتھ اکٹھا رکھے؟","f2":"خوشي کے ان مواقع پر اس طرح کي پاکيزہ اور مسنون دعامبارکباد ديني چاہيے جو کہ الفت مودت اور اضافہ کے ظاہري وباطني تمام معاني کو محيط ہے؟"}],[2131,"بصرہ انصاری رضی اللہ عنہ کہتے ہیں کہ میں نے ایک کنواری پردہ نشین عورت سے نکاح کیا، میں اس کے پاس گیا، تو اسے حاملہ پایا تو اس کے متعلق اللہ کے رسول صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"اس کی شرمگاہ کو حلال کرنے کے عوض تمہیں مہر ادا کرنا پڑے گا، اور (پیدا ہونے والا) بچہ تمہارا غلام ہو گا، اور جب وہ بچہ جن دے - (حسن کی روایت میں) \"تو تو اسے کوڑے لگا\" (واحد کے صیغہ کے ساتھ) اور ابن السری کی روایت میں تو تم اسے کوڑے لگاؤ (جمع کے صیغہ کے ساتھ)\"، یا آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر حد جاری کرو\"۔ ابوداؤد کہتے ہیں: اس حدیث کو قتادہ نے سعید بن زید سے انہوں نے ابن مسیب سے روایت کیا ہے نیز اسے یحیی ابن ابی کثیر نے یزید بن نعیم سے، انہوں نے سعید بن مسیب سے اور عطاء خراسانی نے سعید بن مسیب سے روایت کیا ہے سبھی لوگوں نے اسے مرسلاً روایت کیا ہے۔ اور یحیی ابن ابی کثیر کی روایت میں ہے کہ بصرہ بن اکثم نے ایک عورت سے نکاح کیا اور سبھی لوگوں کی روایت میں ہے: \"آپ نے لڑکے کو ان کا غلام بنا دیا\"۔","ضعیف",{"u2":"بصرہ نامی ایک صحابی سے روایت ہے کہ اس نے کہا: میں نے ایک کنواری لڑکی سے شادی کی، جو کہ اپنے پردے میں تھی۔ میں اس پر داخل ہوا تو وہ حاملہ تھی۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اس کو حق مہر ملے گا بوجہ اس کے جو تو نے اس کی شرمگاہ کو حلال جانا اور بچہ تیرا غلام ہو گا، جب یہ بچہ جن لے۔ “ بالفاظ حسن بن علی ” تو اسے درے لگا۔ “ اور بالفاظ ابن ابی السرق ” تم لوگ اس کو درے لگاؤ یا کہا کہ اس کو حد لگاؤ۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو قتادہ نے بواسطہ سعید بن یزید، ابن مسیب سے اور یحییٰ بن ابی کثیر نے بواسطہ یزید بن نعیم، سعید بن مسیب سے اور عطاء خراسانی نے سعید بن مسیب سے روایت کی اور سب نے اسے نبی کریم صلی اللہ علیہ وسلم سے مرسل ہی روایت کیا ہے۔ یحییٰ بن ابی کثیر کی روایت میں ہے کہ بصرہ بن اکثم نے ایک عورت سے نکاح کیا اور تمام رواۃ نے کہا کہ آپ نے بچے کو اس کا غلام قرار دیا۔"}],[2132,"سعید بن مسیب سے روایت ہے کہ بصرہ بن اکثم نامی ایک شخص نے ایک عورت سے نکاح کیا پھر راوی نے اسی مفہوم کی روایت نقل کی لیکن اس میں اتنا زیادہ ہے کہ \"آپ صلی اللہ علیہ وسلم نے ان کے درمیان جدائی کرا دی\" اور ابن جریج والی روایت زیادہ کامل ہے۔","ضعیف",{"u2":"یحییٰ بن ابی کثیر نے یزید بن نعیم سے انہوں نے سعید بن مسیب رضی اللہ عنہ سے روایت کیا کہ ایک شخص نے، جسے بصرہ بن اکثم کہا جاتا تھا، ایک عورت سے نکاح کیا، اور مذکورہ بالا حدیث کے ہم معنی بیان کیا، اور اضافہ کیا کہ ان کے مابین تفریق کر دی۔ اور ابن جریج کی روایت زیادہ کامل ہے۔","f2":"یہ دونوں روایات مرسل ہیں،مرفوعاصحیح نہیں ہیں تاہم مسائل کا حل تقریبا یہی ہے۔ (الف) اس قسم کی صورت حال میں کہ انسان اپنی منکوحہ کو حاملہ پائے تو ان میں تفریق کرادی جائے گی اور شوہر نے اگراس سے مباشرت کر لئ تو اس کی وجہ سے اسے حق مہر (یا مثل) دینا پڑے گا۔ (ب) اس عورت پر حد لازم آئے گی۔ (ج)ولد الزناکو معروف معنی میں غلام(عبد)ہونے کا کسی فقیہ نے نہیں کہا۔ الا یہ اسےاس دور کی بات تسلیم کی جائے جبکہ غلامی کا دور باقی تھا،ہاں اسکے بچے کی حسن تعلیم وتربیت کی تاکید ہے اور وہ اپنے مربی کا احسان مند اور خد متگار ہو گا(واللہ اعلم)"}],[2133,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس دو بیویاں ہوں اور اس کا میلان ایک کی جانب ہو تو وہ بروز قیامت اس حال میں آئے گا، کہ اس کا ایک دھڑا جھکا ہوا ہو گا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جس شخص کی دو بیویاں ہوں اور پھر وہ کسی ایک کی طرف مائل ہو گیا تو وہ قیامت کے روز اس کیفیت میں آئے گا کہ اس کا ایک پہلو جھکا ہوا ہو گا۔ “"}],[2134,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (اپنی بیویوں کی) باری مقرر فرماتے تھے اور اس میں انصاف سے کام لیتے تھے، پھر یہ دعا فرماتے تھے: \"اے اللہ! یہ میری تقسیم ان چیزوں میں ہے جو میرے بس میں ہے، رہی وہ بات جو میرے بس سے باہر ہے اور تیرے بس میں ہے (یعنی دل کا میلان) تو تو مجھے اس کی وجہ سے ملامت نہ فرمانا\"۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (اپنی ازواج محترمات کے مابین) تقسیم کرتے اور عدل کرتے اور فرمایا کرتے ” اے اللہ! یہ میری تقسیم ہے جو میرے بس میں ہے۔ اور اس بات میں مجھے ملامت نہ فرمانا جس کا تو مالک ہے اور میرا اس پر اختیار نہیں۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: اس سے مراد دل (کا میلان) ہے۔","f2":"مطلب یہ ہے کہ معاشرتی برتاو میں میں کوتاہی نہیں کرتا،لیکن دل کا معاملہ میرے اختیار میں نہیں۔ اس لیے قلبی محبت میں کمی بیشی پر مجھے ملامت نہ کرنا۔ اس سے معلوم ہواکہ ایک سے زیادہ بیویاں رکھنےوالا اگر ظاہری برتاو میں عدل وانصاف کا اہتمام کرتا رہے گا تو قلبی میلان کی کمی پیشی پر اس کی گرفت نہیں ہو گی۔ واللہ اعلم"}],[2135,"عروہ کہتے ہیں ام المؤمنین عائشہ رضی اللہ عنہا نے کہا: میرے بھانجے! رسول اللہ صلی اللہ علیہ وسلم ہم ازواج مطہرات کے پاس رہنے کی باری میں بعض کو بعض پر فضیلت نہیں دیتے تھے اور ایسا کم ہی ہوتا تھا کہ آپ صلی اللہ علیہ وسلم ہم سب کے پاس نہ آتے ہوں، اور بغیر محبت کے آپ صلی اللہ علیہ وسلم سب کے قریب ہوتے، اس طرح آپ اپنی اس بیوی کے پاس پہنچ جاتے جس کی باری ہوتی اور اس کے ساتھ رات گزارتے، اور سودہ بنت زمعہ رضی اللہ عنہا عمر رسیدہ ہو گئیں اور انہیں اندیشہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم انہیں الگ کر دیں گے تو کہنے لگیں: اللہ کے رسول! میری باری عائشہ رضی اللہ عنہا کے لیے رہے گی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی یہ بات قبول فرما لی، عائشہ رضی اللہ عنہا کہتی تھیں کہ ہم کہتے تھے کہ اللہ تعالی نے اسی سلسلہ میں یا اور اسی جیسی چیزوں کے سلسلے میں آیت کریمہ: «وإن امرأة خافت من بعلها نشوزا» (سورۃ النساء: ۱۲۸) نازل کی: \"اگر عورت کو اپنے خاوند کی بدمزاجی کا خوف ہو\"۔","حسن صحیح",{"u2":"عروہ رضی اللہ عنہ نے بیان کیا کہ سیدہ عائشہ رضی اللہ عنہا ا نے کہا: اے میرے بھانجے! رسول اللہ صلی اللہ علیہ وسلم (ہم ازواج میں) باری مقرر کرنے کے معاملے میں، یعنی ہمارے پاس ٹھہرنے کے معاملے میں ہم میں سے کسی کو کسی پر فضیلت نہ دیا کرتے تھے۔ اور آپ تقریباً ہر روز ہم سب کے پاس چکر لگایا کرتے تھے اور ہر بیوی کے قریب ہوتے۔ یہ نہیں کہ آپ صحبت کرتے تھے۔ حتیٰ کہ اس کے پاس جا پہنچتے جس کی باری کا دن ہوتا اور رات اس کے ہاں گزارتے۔ سیدہ سودہ بنت زمعہ رضی اللہ عنہا ا جب بڑی عمر کی ہو گئیں اور انہیں اندیشہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم انہیں چھوڑ دیں گے تو انہوں نے کہا: اے اللہ کے رسول! میرا دن عائشہ کے لیے (وقف) ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اسے قبول فر لیا۔ (سیدہ عائشہ) کہتی ہیں کہ ہم کہا کرتی تھیں کہ اسی سلسلہ میں اور اسی قسم کی صورت احوال کے متعلق ہی اللہ عزوجل نے یہ آیت نازل فرمائی ہے «وإن امرأة خافت من بعلها نشوزا» ” اگر کسی عورت کو اندیشہ ہو اپنے خاوند کے بگڑنے کا۔ “"}],[2136,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ آیت کریمہ: «ترجي من تشاء منهن وتؤوي إليك من تشاء» \"آپ ان میں سے جسے آپ چاہیں دور رکھیں اور جسے آپ چاہیں اپنے پاس رکھیں\" (سورۃ الاحزاب: ۵۱) نازل ہوئی تو ہم میں سے جس کسی کی باری ہوتی تھی اس سے اللہ کے رسول صلی اللہ علیہ وسلم اجازت لیتے تھے۔ معاذہ کہتی ہیں کہ یہ سن کر میں نے عائشہ رضی اللہ عنہا سے پوچھا: آپ ایسے موقع پر کیا کہتی تھیں؟ کہنے لگیں: میں تو یہ ہی کہتی تھی کہ اگر میرا بس چلے تو میں اپنے اوپر کسی کو ترجیح نہ دوں۔","صحیح",{"u2":"معاذہ‘سیدہ عائشہ رضی اللہ عنہا ا سے روایت کرتی ہیں ان کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم سورۃ الاحزاب کی آیت کریمہ «ترجي من تشاء منهن وتؤوي إليك من تشاء» کے نازل ہو جانے کے بعد (بھی) ہم میں سے جس کی باری کا دن ہوتا اس سے اجازت لیا کرتے تھے (جب کسی دوسرے حرم میں جانے کی کوئی ضرورت ہوتی۔) معاذہ کہتی ہیں میں نے سیدہ عائشہ رضی اللہ عنہا ا سے دریافت کیا کہ آپ رسول اللہ صلی اللہ علیہ وسلم کو کیا کہا کرتی تھیں؟ انہوں نے کہا: میں کہا کرتی تھی اگر یہ فیصلہ کرنا میرے ہی ذمے ہے تو پھر میں اپنے آپ پر کسی اور کو ترجیح نہیں دے سکتی۔","f2":"سورۃ احزاب کی اس آیت نمبر 51 میں اللہ عزوجل نے اپنئ نبی صلی اللہ علیہ وسلم کو بیویوں میں باری کے مسئلے میں بصراحت رخصت عنایت فرمائی ہے مگر آپ صلی اللہ علیہ وسلم اس رخصت کے باوجود تقسیم کی وعزیمت پر قائم رہے۔ حضرت عائشہ رضی اللہ کا اپنے آپ کو ترجیح دینا کسی نفسانی حظ کی بنا پر نہ تھا بلکہ اس شرف خدمت کی بنا پر تھا جو ان کے قریب سے حاصل ہوتا تھا اور سب سے بڑھ کر نزول برکات اوراللہ کے ہاں رفع درجات کا سبب تھا۔"}],[2137,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مرض الموت کے موقع پر سب بیویوں کو بلا بھیجا، وہ جمع ہوئیں تو فرمایا: \"اب تم سب کے پاس آنے جانے کی میرے اندر طاقت نہیں، اگر تم اجازت دے دو تو میں عائشہ کے پاس رہوں\"، چنانچہ ان سب نے آپ صلی اللہ علیہ وسلم کو اس کی اجازت دے دی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ازواج مطہرات کو بلوایا۔ یعنی اپنے مرض وفات کے دنوں میں، تو وہ جمع ہو گئیں، آپ صلی اللہ علیہ وسلم نے فرمایا ” میں اب تمہارے درمیان چکر نہیں لگا سکتا اگر مناسب سمجھو اور مجھے اجازت دے دو، تو میں عائشہ کے ہاں رہ لوں۔ “ تو سب نے اجازت دے دی۔"}],[2138,"ابن شہاب زہری سے روایت ہے کہ عروہ بن زبیر رضی اللہ عنہ نے ان سے بیان کیا کہ ام المؤمنین عائشہ رضی اللہ عنہا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی سفر کا ارادہ فرماتے تو اپنی بیویوں کے درمیان قرعہ اندازی کرتے تو جس کا نام نکلتا اس کو لے کر سفر کرتے، آپ صلی اللہ علیہ وسلم نے ہر بیوی کے لیے ایک دن رات کی باری بنا رکھی تھی، سوائے سودہ بنت زمعہ رضی اللہ عنہا کے انہوں نے اپنی باری عائشہ رضی اللہ عنہا کو دے رکھی تھی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی سفر کا ارادہ فرماتے تو اپنی ازواج مطہرات میں قرعہ ڈالتے، جس کا نام نکل آتا وہ آپ صلی اللہ علیہ وسلم کے ساتھ سفر میں جاتی۔ آپ صلی اللہ علیہ وسلم ہر زوجہ کو اس کی باری کا دن اور رات دیتے، سوائے سیدہ سودہ بنت زمعہ رضی اللہ عنہا ا کے، انہوں نے اپنا دن سیدہ عائشہ رضی اللہ عنہا ا کو ہبہ کر دیا تھا۔"}],[2139,"عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پورا کئے جانے کی سب سے زیادہ مستحق شرطیں وہ ہیں جن کے ذریعہ تم نے شرمگاہوں کو حلال کیا ہے\"۔\n§وضاحت\n۱؎ : یعنی نکاح کے وقت یہ طے ہو کہ بیوی اپنے میکے ہی میں رہے گی اور شوہر اس شرط کو قبول کر لے تو ظاہر حدیث کے مطابق اب اس کو اس کے میکے سے نکالنے کا حق نہیں ہے۔","صحیح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” شرطوں میں سے اہم ترین شرط جس کا پورا کرنا تم پر واجب ہے، وہ ہے جس کی بنا پر تم نے (بیویوں کی) عصمتوں کو حلال کیا ہو۔ “","f2":"امام صاحب رحمہ اللہ کا استدال ہے کہ ایسی شرطوں کا پورا کرنا واجب ہے بشرطیکہ کسی حلال کو حرام یا حرام کو حلال نہ ٹھہرایا گیا ہو۔"}],[2140,"قیس بن سعد رضی اللہ عنہ کہتے ہیں کہ میں حیرہ آیا، تو دیکھا کہ لوگ اپنے سردار کو سجدہ کر رہے ہیں تو میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم اس کے زیادہ حقدار ہیں کہ انہیں سجدہ کیا جائے، میں جب آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تو میں نے آپ سے کہا کہ میں حیرہ شہر آیا تو میں نے وہاں لوگوں کو اپنے سردار کے لیے سجدہ کرتے ہوئے دیکھا تو اللہ کے رسول! آپ اس بات کے زیادہ مستحق ہیں کہ ہم آپ کو سجدہ کریں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بتاؤ کیا اگر تم میری قبر کے پاس سے گزرو گے، تو اسے بھی سجدہ کرو گے؟\" وہ کہتے ہیں: میں نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم ایسا نہ کرنا، اگر میں کسی کو کسی کے لیے سجدہ کرنے کا حکم دیتا تو عورتوں کو حکم دیتا کہ وہ اپنے شوہروں کو سجدہ کریں اس وجہ سے کہ شوہروں کا حق اللہ تعالی نے مقرر کیا ہے\"۔","صحیح",{"u2":"سیدنا قیس بن سعد رضی اللہ عنہ بیان کرتے ہیں کہ میں حیرہ گیا، تو میں نے دیکھا کہ وہ لوگ اپنے سردار کو سجدہ کرتے ہیں تو میں نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم اس بات کے زیادہ حقدار ہیں کہ ان کہ سجدہ کیا جائے۔ کہتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور بتایا کہ میں حیرہ گیا، تو دیکھا کہ وہ لوگ اپنے سردار کو سجدہ کرتے ہیں تو آپ اے اللہ کے رسول! اس بات کے زیادہ حقدار ہیں کہ ہم آپ کے سامنے سجدہ ریز ہوں۔ آپ نے فرمایا ” بھلا بتا کہ اگر تو میری قبر پر گزرتا تو کیا اسے سجدہ کرتا؟ “ میں نے کہا کہ نہیں۔ آپ نے فرمایا ” تو ایسا نہ کرو۔ اگر میں کسی کو سجدہ کرنے کا کہتا تو عورتوں کو حکم دیتا کہ اپنے شوہروں کو سجدہ کریں کیونکہ اللہ تعالیٰ نے بیوی پر شوہر کا بہت حق رکھا ہے۔ “","f2":"1: تعظیمی سجدہ مشرکین کا شعار ہے۔\n2: قبر پر سجدہ کرنا یا کسی زندہ مردہ کو سجدہ کرنا،فطرت سلیمہ کے بھی خلاف ہے کجایہ کہ کوئی کلمہ گو اس کا تصورکرے۔\n3: بیویوں پر واجب ہے کہ اہنے خاوندوں کی حد درجہ عزت وتو قیر اور خدمت کو اپنا شعار بنائیں مگر ظاہر ہے کہ شرعی حدود وقیود کی پا بندی لازمی ہے۔\n4: سجدہ صرف اللہ وحدہ لا شریک کا حق اور اسی کے ساتھ خاص ہے،دوسرے کسی شخص کے لئے سجدہ قطعا روا اور جائز نہیں ہے۔\n5: مردوں کو عورتوں پر فوقیت حاصل ہے، قرآن مقدس میں بھی اس کی تصریح موجود ہے۔\n6: یہ حدیث صحابہ کرامرضی اللہ کی رسول صلی اللہ علیہ وسلم کے ساتھ کمال محبت کی واضح دلیل ہے۔"}],[2141,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب آدمی اپنی بیوی کو اپنے بستر پر بلائے اور وہ انکار کرے اور اس کے پاس نہ آئے جس کی وجہ سے شوہر رات بھر ناراض رہے تو فرشتے اس عورت پر صبح تک لعنت کرتے رہتے ہیں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب شوہر بیوی کو اپنے بستر پر بلائے اور وہ نہ آئے اور شوہر غصہ میں رات گزار دے تو فرشتے اس بیوی پر صبح ہونے تک لعنت کرتے رہتے ہیں۔ “","f2":"بنیادی حقیقت تو یہی ہے جو رسول صلی اللہ علیہ وسلم بے فرمادی ہے کہ اس طرح بے شمار نفسیاتی اور اجتماعی شرورکا دروازہ بند ہو جاتا ہے اور انکار کی صورت میں بہت سے انفرادی،خاندانی اور معاشرتی فساد جنم لیتے ہیں۔ اس لئے عورت کے لئے ضروری ہے کہ وہ خاوند کے جذبات کا لحاظ رکھے تاہم اگر کوئی معقول عذرہو لیکن خاوند اسے اہمیت نے دے رہا ہو۔ مثلا بیوی بہت زیادہ بیمارہو اس کی صحت مرد کی خواہش پوری کرنے کی متحمل نہ ہو یا اور کسی قسم کا کا کوئی معقول عذر ہو تو بیوی کا انکار امید ہے کہ اللہ عزوجل کے ہاں قابل مواخذہ نہیں ہو گا۔"}],[2142,"معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہمارے اوپر ہماری بیوی کا کیا حق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کہ جب تم کھاؤ تو اسے بھی کھلاؤ، جب پہنو یا کماؤ تو اسے بھی پہناؤ، چہرے پر نہ مارو، برا بھلا نہ کہو، اور گھر کے علاوہ اس سے جدائی ۱؎ اختیار نہ کرو\"۔ ابوداؤد کہتے ہیں: «ولا تقبح» کا مطلب یہ ہے کہ تم اسے «قبحك الله» نہ کہو۔\n§وضاحت\n۱؎ : یعنی کسی بات پر ناراض ہو تو اسے گھر سے دوسری جگہ نہ بھگاؤ گھر ہی میں رکھو بطور سرزنش صرف بستر الگ کر دو۔","حسن صحیح",{"u2":"جناب حکیم بن معاویہ قشیری اپنے والد سے بیان کرتے ہیں کہ میں نے کہا: اے اللہ کے رسول! ہم پر بیوی کے کیا حقوق ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” جب تو کھائے تو اسے کھلائے، جب تو پہنے تو اسے پہنائے۔ “ یا یوں کہا: ” جب ک کر لائے (تو اسے پہنائے) اور چہرے پر نہ مار، برا نہ بول اور اس سے جدا نہ ہو مگر گھر میں۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں «ولا تقبح» کے معنی ہیں ” یوں مت کہو کہ اللہ تجھے قبیح بنا دے۔ “","f2":"بوقت ضرورت تادیب کی صورت میں چہرے پر مارنا منع ہے اگر بستر سے علیحدہ کرنا ہو تو گھر کے اندر ہی ہو اپنے گھر سے مت نکال دے اور زبانی توبیح میں بھی بد دعادینا ناجائز ہے۔ قرآن مجید نے تادیب کے آداب میں فرمایا (والتی تخافون نشوزھن فعظو ھن وا ھجروھن فی المضا جع واضر بو ھن فان اطعنکم فلا تبغو علیھن سبیلا)(النساء) اور جن عورتوں کی نافرمانی کا تمہیں ابدیشہ ہو تو انہیں نصیحت کر و،بستر وں سے الگ کر دو اور مار کر سزا دو اگر وہ تمہاری تابعداری کریں تو ان پر کوئی راستہ تلاش نہ کرو"}],[2143,"معاویہ بن حیدہ قشیری رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! ہم اپنی عورتوں کے پاس کدھر سے آئیں، اور کدھر سے نہ آئیں؟ آپ صلی اللہ علیہ وسلم نے جواب دیا: \"اپنی کھیتی ۱؎ میں جدھر سے بھی چاہو آؤ، جب خود کھاؤ تو اسے بھی کھلاؤ، اور جب خود پہنو تو اسے بھی پہناؤ، اس کے چہرہ کی برائی نہ کرو، اور نہ ہی اس کو مارو\"۔ ابوداؤد کہتے ہیں: شعبہ نے «أطعمها إذا طعمت واكسها إذا اكتسيت» کے بجائے «تطعمها إذا طعمت وتكسوها إذا اكتسيت» روایت کیا ہے۔\n§وضاحت\n۱؎ : یعنی قُبل (شرمگاہ) میں جس طرف سے بھی چاہو آؤ، نہ کہ دبر (پاخانہ کے راستہ) میں کیونکہ دبر «حرث» ’’ کھیتی‘‘ نہیں ہے۔","حسن صحیح",{"u2":"بہز بن حکیم اپنے والد (حکیم) سے، وہ (ان کے) دادا (معاویہ بن حیدہ قشیری رضی اللہ عنہ) سے روایت کرتے ہیں کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! ہم اپنی بیویوں سے کس طرح فائدہ اٹھائیں اور کیا چھوڑیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنی کھیتی کو آ جیسے تو چاہے، اسے کھلا جب تو کھائے، اسے پہنا جب تو پہنے، چہرے کے قبیح ہونے کی بد دعا (یا گالی) نہ دے اور (منہ پر) مت مار۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ شعبہ کی روایت میں ہے «طعمها إذا طعمت وتكسوها إذا اكتسيت»۔","f2":"1: سورۃ بقرہ کی آیت نمبر (223)میں ہے (نسا وکم حرث لکم فاتو احرتکم انی شئتم) تمہاری کھیتیاں ہیں،اپنی کھیتیوں میں جس طرح چاہوآو)\n2: اللہ تعالی اور اس کے رسول صلی اللہ علیہ وسلم نے میاں بیوی کے تعلق کوجس بلیغ انداز میں پیش فرما دیا اس سے بڑھ کراس کو بیان کرنا ناممکن اور محال ہے۔ دنیا کی کوئی زبان اس کا کوئی سا ادب اس کی نظر پیش کرنے سے قاصر ہے۔"}],[2144,"معاویہ قشیری رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور عرض کیا: ہماری عورتوں کے بارے میں آپ کا کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو تم خود کھاتے ہو وہی ان کو بھی کھلاؤ، اور جیسا تم پہنتے ہو ویسا ہی ان کو بھی پہناؤ، اور نہ انہیں مارو، اور نہ برا کہو\"۔","صحیح",{"u2":"سیدنا معاویہ قشیری رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: آپ (ہمیں) ہماری عورتوں کے بارے میں کیا ارشاد فرماتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” جو کھاتے ہو اس سے انہیں کھلاؤ، جو پہنتے ہو اس سے انہیں پہناؤ، انہیں مارو نہیں اور قبیح ہونے کی گالی (یا بد دعا) نہ دو۔ “"}],[2145,"ابوحرہ رقاشی اپنے چچا سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم ان کی نافرمانی سے ڈرو تو انہیں بستروں میں(تنہا) چھوڑ دو\"۔ حماد کہتے ہیں: یعنی ان سے صحبت نہ کرو۔","حسن",{"u2":"ابوحرہ رقاشی اپنے چچا سے بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اگر تمہیں ان سے نافرمانی اور عدم اطاعت کا اندیشہ ہو تو انہیں بستروں سے علیحدہ کر دو۔ “ حماد نے کہا: اس سے مراد مباشرت ہے۔ (ہمبستری نہ کرو۔)"}],[2146,"ایاس بن عبداللہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کی بندیوں کو نہ مارو\"، چنانچہ عمر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہنے لگے: (آپ کے اس فرمان کے بعد) عورتیں اپنے شوہروں پر دلیر ہو گئی ہیں، چنانچہ آپ صلی اللہ علیہ وسلم نے انہیں مارنے اور تادیب کی رخصت دے دی، پھر عورتیں اپنے شوہروں کی شکایتیں لے کر ازواج مطہرات کے پاس پہنچنے لگیں، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بہت سی عورتیں اپنے شوہروں کی شکایتیں لے کر محمد کے گھر والوں کے پاس پہنچ رہی ہیں، یہ (مار پیٹ کرنے والے) لوگ تم میں بہترین لوگ نہیں ہیں\"۔","صحیح",{"u2":"ایاس بن عبداللہ بن ابی ذباب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ کی بندیوں کو مت مارا کرو۔ “ تو سیدنا عمر رضی اللہ عنہ، رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: عورتیں اپنے شوہروں کے سر چڑھنے لگی ہیں۔ پس آپ صلی اللہ علیہ وسلم نے ان کو مارنے کی رخصت دے دی۔ تب رسول اللہ صلی اللہ علیہ وسلم کے گھر والوں کے پاس عورتیں بہت زیادہ آنے لگیں جو اپنے شوہروں کی شکایت کرتی تھیں۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” محمد (صلی اللہ علیہ وسلم) کے گھر والوں کے پاس عورتیں بہت زیادہ آئی ہیں جو اپنے شوہروں کی شکایت کرتی ہیں۔ ایسے لوگ کوئی اچھے آدمی نہیں ہیں۔ “ امام ابوداؤد رضی اللہ عنہ نے ہمیں کہا کہ زہری کے شیخ کا نام عبداللہ بن عبداللہ ہی ہے (نہ کہ عبیداللہ۔)"}],[2147,"عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آدمی سے اپنی بیوی کو مارنے کے تعلق سے پوچھ تاچھ نہ ہو گی\"۔","ضعیف",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” شوہر سے بیوی کو مارنے کے سلسلے میں سوال نہیں کیا جائے گا۔ “","f2":"اگرتادیب کی ضرورت ہو،زبانی اور بےرخی سے بیوی اپنے معاملے کوسلجھاتی نہ ہوتو مارنے کی رخصت ہےجیسے کہ سورہ نساء آیت 34 میں آیا ہے۔یہ روایت بعض ائمہ کےنزدیک ضعیف ہے۔صحیح ہونے کی صورت میں میں اس کا مطلب وہ مارہے، جس کی اجازت شریعت نےدی ہے۔یعنی ہلکی سی مار، جس کامقصد بیوی کی اصلاح اور اسے متنبہ کرنا ہو۔اگر خاوند ظلم کرے گا، حدسے تجاوز کرے گا یا اسے بلاوجہ مارے پیٹے گا تووہ ظالم ہوگا جس کا اسے حساب دینا پڑے گا۔"}],[2148,"جریر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے (اجنبی عورت پر) اچانک نظر پڑ جانے کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنی نظر پھیر لو ۱؎\"۔\n§وضاحت\n۱؎ : اگر قصداً شہوت کی نظر سے اسے دیکھے تو گنہگار ہو گا کیوں کہ اگلی حدیث میں ہے: ’’ آنکھ کا زنا غیر محرم عورت کا دیکھنا ہے ‘‘۔","صحیح",{"u2":"سیدنا جریر بن عبداللہ بجلی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اچانک نظر پڑ جانے کے متعلق پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنی نظر پھیر لو۔ “"}],[2149,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے علی رضی اللہ عنہ سے کہا: علی! (اجنبی عورت پر) نگاہ پڑنے کے بعد دوبارہ نگاہ نہ ڈالو کیونکہ پہلی نظر تو تمہارے لیے جائز ہے، دوسری جائز نہیں ۱؎۔\n§وضاحت\n۱؎ : کیوں کہ پہلی نظر بغیر قصد و اختیار کے پڑی ہے اس لئے اس پر کوئی گناہ نہیں، اور دوسری نظر چونکہ قصداً ہو گی اس لئے اس پر گناہ ہو گا۔","حسن",{"u2":"ابن بریدہ اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ نے فرمایا ” اے علی! نظر کے پیچھے نظر مت لگاؤ، پہلی تمہارے لیے معاف ہے (جو اچانک پڑ گئی) دوسری نہیں (عمدا دیکھنا)۔ “"}],[2150,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورت عورت سے بدن نہ چپکائے وہ اپنے شوہر سے اس کے بارے میں اس طرح بیان کرے گویا اس کا شوہر اسے دیکھ رہا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی عورت کسی دوسری عورت کے ساتھ بغل گیر ہو کر یا چمٹ کر نہ لیٹے اور پھر اپنے شوہر کو اس کے متعلق بتانے لگے گویا وہ اس کی طرف دیکھ رہا ہے۔ “","f2":"کوئی عورت دوسری کے ساتھ لیٹے یا سوئے اور پھر اس کے احوال اپنے شوہر کو بتائے،یا ویسے ہی کسی کی تعریفیں کرنے لگے،منع اور ناجائز ہے،یہ صورتیں دلوں میں شیطانی وساوس پیدا کرنے کا باعث ہوتی ہیں اور پھر فتنے اٹھتے ہیں اور یہی تعلیم شوہر کے لئے بھی ہے کہ کسی مردکی اپنی بیوی کے سامنے مبالغہ آمیز تعریف نہ کرے۔"}],[2151,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک عورت کو دیکھا تو (اپنی بیوی) زینب بنت حجش رضی اللہ عنہا کے پاس آئے اور ان سے اپنی ضرورت پوری کی، پھر صحابہ کرام کے پاس گئے اور ان سے عرض کیا: \"عورت شیطان کی شکل میں نمودار ہوتی ہے ۱؎، تو جس کے ساتھ اس طرح کا واقعہ پیش آئے وہ اپنی بیوی کے پاس آ جائے، کیونکہ یہ اس کے دل میں آنے والے احساسات کو ختم کر دے گا\"۔\n§وضاحت\n۱؎ : عورت کو شیطان کی شکل میں اس وجہ سے فرمایا کہ جیسے شیطان آدمی کو بہکاتا ہے ویسے بے پردہ عورت بھی بہکاتی ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ کی روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے کوئی عورت دیکھی پھر (اپنے گھر) سیدہ زینب بنت جحش رضی اللہ عنہا ا کے ہاں آئے اور ان سے اپنی حاجت پوری کی۔ پھر اپنے اصحاب کے پاس گئے اور ان سے فرمایا ” عورت شیطان کی صورت میں سامنے آتی ہے، جو شخص اس طرح کی کوئی کیفیت محسوس کرے تو اسے چاہیئے کہ اپنی بیوی کے پاس چلا جائے، بلاشبہ (بیوی کے پاس جانا) اس کے نفس میں آنے والے وسوسے اور خیال کو نکال دے گا۔ “","f2":"1: بعض قلیل الحیا ء لوگ اس صحیح حدیث کے الفاظ سے ترجمعہ میں یہ رنگ بھرنے کی کوشش کرتے ہیں کہ نعوذبااللہ،رسول صلی اللہ علیہ وسلم مغلوب الشہوت قسم کے انسان تھے اور کچھ دوسرے ہیں کہ احادیث کی حجیت کو مشکوک باور کراتے ہیں اور یہ دونوں ہی باتیں علم وذہانت کے منافی ہیں۔ رسول صلی اللہ علیہ وسلم تو اس قدر باحیا تھے کہ پردے میں بیٹھی ہوئی دو شیزہ کی حیا بھی آپ کی حیا کے سامنے ماند تھی، ایسا تر جمعہ کرنے والے مقام رسالت سے آگاہ نہیں آپ نے اپنی حاجت یا ضرورت پوری کی کا ترجمعہ عربی زبان وادب میں سوائے مباشرت کے اور ہے ہی نہیں؟آپ نے صحابہ کی مجلس میں جا کر ایک باقاعدہ کی بات بتائی کہ عورت مرد کے لئے شیطان کی طرح وسوسے پیدا کرتی اور فتنے کا باعث بنتی ہے۔ اس کا بہترین علاج انسان کی اپنی بیوی ہے۔ اس نصیحت کو پچھلے جملوں سے جوڑ کر ایک ایسا مفہوم پیدا کرنا جو ایک عام باوقار شخصیت کے لئے بھی زیب نہ دیتا ہو۔ رسول صلی اللہ علیہ وسلم کے لئے بیان کرنا از حد نا مناسب ہے۔\n2: عورت کو ایسی کسی صورت میں باہر نہیں نکلنا چاہیے کہ شیطان صفت کہلائی جانے لگے۔\n3: صنفی جذبات پورے کرنے کے لئے پاک اور حلال مقام انسان کا اپنا گھر ہے۔\n4: عورت کو بھی شوہرکا مطیع ہونا چاہیے تاکہ شوہر پاک اور چادر وصمت بے داغ رہے۔"}],[2152,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے (قرآن میں وارد لفظ) «لمم» (چھوٹے گناہ) کے مشابہ ان اعمال سے زیادہ کسی چیز کو نہیں پایا جو ابوہریرہ رضی اللہ عنہ سے حدیث میں مذکور ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے زنا کا جتنا حصہ ہر شخص کے لیے لکھ دیا ہے وہ اسے لازمی طور پر پا کر رہے گا، چنانچہ آنکھوں کا زنا (غیر محرم کو بنظر شہوت) دیکھنا ہے زبان کا زنا (غیر محرم سے شہوت کی) بات کرنی ہے، (انسان کا) نفس آرزو اور خواہش کرتا ہے اور شرمگاہ اس کی تصدیق یا تکذیب کرتی ہے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ «لمم» (چھوٹے موٹے گناہوں) کی تفسیر میں، میں نے ابوہریرہ رضی اللہ عنہ کی روایت سے بڑھ کر اور کوئی چیز نہیں دیکھی۔ سیدنا ابوہریرہ رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں ” اللہ تعالیٰ نے ابن آدم پر زنا سے اس کا حصہ لکھ دیا ہے جسے وہ پا کر رہے گا۔ تو آنکھوں کا زنا دیکھنا ہے، زبان کا زنا بولنا ہے، اور دل تمنا اور خواہش کرتا ہے اور شرمگاہ اس کی تصدیق یا تکذیب کرتی ہے۔ “"}],[2153,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر انسان کے لیے زنا کا حصہ متعین ہے، ہاتھ زنا کرتے ہیں، ان کا زنا پکڑنا ہے، پیر زنا کرتے ہیں ان کا زنا چلنا ہے، اور منہ زنا کرتا ہے اس کا زنا بوسہ لینا ہے ۱؎\"۔\n§وضاحت\n۱؎ : چوں کہ یہ امور زنا کے ذرائع ہیں، اس لئے تشدیداً انہیں بھی زنا سے تعبیر کیا گیا ہے، گو ان کا گناہ زنا کے گناہ کے برابر نہیں۔","حسن",{"u2":"سیدناابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہر آدم زاد کے لیے زنا سے اس کا حصہ (لکھا گیا) ہے۔ “ اور مذکورہ قصہ بیان کیا کہا: ” ہاتھ زنا کرتے ہیں، ان کی بدکاری پکڑنا ہے۔ پاؤں زنا کرتے ہیں، ان کی بدکاری چلنا ہے۔ منہ زنا کرتا ہے اور اس کی بدکاری بوسہ لینا ہے۔ “"}],[2154,"اس سند سے بھی ابوہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے یہ قصہ روایت کرتے ہیں اس میں ہے کہ آپ نے فرمایا: \"اور کانوں کا زنا سننا ہے\"۔","حسن صحیح",{"u2":"سیدناابوہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مذکورہ قصہ بیان کیا، فرمایا ” کان زنا کرتے ہیں اور ان کی بدکاری سننا ہے۔ “","f2":"1: گناہ دو قسم کے ہوتے ہیں،کبیرہ اور صغیرہ (بڑے اور چھوٹے) کبیرہ گناہ وہ ہیں جن پرشریعت نے کوئی حدوتعزیرمقررکردی ہے یاان پر عذاب شدید،لعنت یا کوئی سخت وعید سنائی ہے، ایسے گناہ توبہ کے بغیر معاف نہیں ہوتے۔ صغیرہ گناہ وہ ہیں جو اتفاقا ہو جاتے ہیں اور شریعت کی طرف سےان پر کوئی حدوتعزیر نہیں لگائی گئی ہے۔ انہی کو (لمم) سے تعبیر کہا گیا ہے۔ سورۃ النجم میں محسنین کے ذکر میں فرمایا ہے وہ جو بچتے ہیں بڑے گناہوں سے اور بے حیائی کے کاموں سے مگر عام قسم کے گناہوں سے صغیرہ گناہ عام نیکی کے کاموں سے معاف ہوتے رہتے ہیں لیکن کسی بھی صاحب ایمان کو ان میں جری نہیں ہو جانا چاہیے،کیو نکہ معاف کرنا یا نہ کرنا،اللہ عزوجل کی مشیت پر مبنی ہے،نیز علما نے لکھا ہے کہ اگر کوئی صغیرہ نہ جانے اور ان کو اپنی عادت بنا لے تو وہ بھی کبیرہ کے زمرہ میں آجاتے ہیں۔ اسی طرح اگر بلا ارادہ کوئی کبیرہ گناہ سرزرد ہو گیا ہو تو انسان نادم ہو اور کثرت سے توبہ کرنے لگے تو وہ ان شا ء اللہ صغیرہ کی مانند معاف کر دیا جائے گا، بہر حال انسان کو اپنے معلوم اور غیر معلوم سبھی گناہوں سے اللہ کے حضور معافی مانگتے رہنا چاہیے۔\n2: اعضائے جسم نظر،کان ہاتھ،قدم اور منہ کے گناہوں کو زنا سے تعبیر کرنا،ان کے ازحد قبیح ہونے کی طرف اشارہ ہے کہ ان کا انجام انتہائی بر اہو سکتا ہے۔"}],[2155,"ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ حنین کے دن مقام اوطاس کی طرف ایک لشکر روانہ کیا تو وہ لشکر اپنے دشمنوں سے ملے، ان سے جنگ کی، اور جنگ میں ان پر غالب رہے، اور انہیں قیدی عورتیں ہاتھ لگیں، تو ان کے شوہروں کے مشرک ہونے کی وجہ سے بعض صحابہ کرام نے ان سے جماع کرنے میں حرج جانا، تو اللہ تعالی نے اس سلسلہ میں یہ آیت نازل فرمائی: «والمحصنات من النساء إلا ما ملكت أيمانكم» \"اور (حرام کی گئیں) شوہر والی عورتیں مگر وہ جو تمہاری ملکیت میں آ جائیں\" (سورۃ النساء: ۲۴) تو وہ ان کے لیے حلال ہیں جب ان کی عدت ختم ہو جائے۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حنین کے موقع پر اوطاس کی طرف ایک مہم بھیجی، وہ اپنے دشمن سے مقابل ہوئے، ان سے جنگ کی، ان پر غالب رہے اور ان کی عورتیں ہاتھ آئیں تو کچھ اصحاب رسول صلی اللہ علیہ وسلم نے ان سے مباشرت میں حرج جانا کیونکہ مشرکین میں ان کے شوہر موجود تھے۔ تو اللہ تعالیٰ نے اس سلسلے میں یہ آیت اتاری «والمحصنات من النساء إلا ملكت أيمانكم» ” اور خاوندوں والیاں (تم پر حرام ہیں) مگر جن کے مالک بن جائیں تمہارے داہنے ہاتھ۔ “ یعنی وہ تمہارے لیے حلال ہیں جب ان کی عدت پوری ہو جائے۔","f2":"جنگی قیدی بن جانے کے بعد میاں بیوی میں جدائی پیدا ہو جاتی ہے خواہ دونوں میں سے کوئی ایک پکڑا جائے یا دونوں۔ اس لئے عورت سے استمتاع جائز ہے اور اس کی عدت ایک حیض ہے۔"}],[2156,"ابو الدرداء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی غزوہ میں تھے کہ آپ کی نظر ایک حاملہ عورت پر پڑی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے مالک نے شاید اس سے جماع کیا ہے\"، لوگوں نے کہا: ہاں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے ارادہ کیا کہ میں اس پر ایسی لعنت کروں کہ وہ اس کی قبر میں اس کے ساتھ داخل ہو جائے، بھلا کیونکر وہ اپنے لڑکے کو اپنا وارث بنائے گا حالانکہ وہ اس کے لیے حلال نہیں، وہ کیسے اس سے خدمت لے گا حالانکہ وہ اس کے لیے حلال نہیں\"۔","صحیح",{"u2":"سیدنا ابو الدرداء رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک غزوے میں ایک عورت دیکھی جس کا حمل تقریباً پورے دنوں کا تھا۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” شاید اس کے مالک نے اس سے مباشرت کی ہے؟ “ انہوں نے کہا: جی ہاں۔ آپ نے فرمایا ” میں نے ارادہ کیا ہے کہ اسے لعنت کروں ایسی لعنت جو اس کی قبر تک اس کے ساتھ جائے۔ یہ اس بچے کو کس طرح اپنا وارث بنا سکے گا جبکہ اس کے لیے یہ حلال نہیں (کہ غیر کے نطفے اور غیر کے بچے کو اپنا بچہ بنائے) اور کیونکر اس سے (غلاموں کی طرح) خدمت لے سکے گا جبکہ یہ اس کے لیے حلال نہیں۔ “ (اگر بالفرض اس کا اپنا نطفہ ہوا اور اپنے بیٹے کے نسب کا انکار کیا تو یہ حرام ہے۔ اور پھر بیٹے کو غلام اور خادم کے درجے پر اتارنا کیونکر جائز ہے)۔"}],[2157,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جنگ اوطاس کی قیدی عورتوں کے متعلق فرمایا: \"کسی بھی حاملہ سے وضع حمل سے قبل جماع نہ کیا جائے اسی طرح کسی بھی غیر حاملہ سے جماع نہ کیا جائے، یہاں تک کہ اسے ایک حیض آ جائے\"۔","صحیح",{"u2":"سیدناابو سعید خدری رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کی طرف نسبت کرتے ہوئے بیان کیا کہ آپ صلی اللہ علیہ وسلم نے اوطاس میں پکڑی جانے والی عورتوں کے بارے میں فرمایا تھا ” کسی حاملہ سے مباشرت نہ کی جائے حتیٰ کہ اس کے بچے کی ولادت ہو جائے اور غیر حاملہ سے بھی مباشرت نہ کی جائے حتیٰ کہ اسے ایک حیض آ جائے۔ “"}],[2158,"حنش صنعانی کہتے ہیں کہ رویفع بن ثابت انصاری ہم میں بحیثیت خطیب کھڑے ہوئے اور کہا: سنو! میں تم سے وہی کہوں گا جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، آپ جنگ حنین کے دن فرما رہے تھے: \"اللہ اور آخرت کے دن پر ایمان لانے والے کسی بھی شخص کے لیے حلال نہیں کہ وہ اپنے سوا کسی اور کی کھیتی کو سیراب کرے\"، (آپ صلی اللہ علیہ وسلم کا مطلب حاملہ لونڈی سے جماع کرنا تھا) اور اللہ اور آخرت کے دن پر ایمان لانے والے شخص کے لیے حلال نہیں کہ وہ کسی قیدی لونڈی سے جماع کرے یہاں تک کہ وہ استبراء رحم کر لے، (یعنی یہ جان لے کہ یہ عورت حاملہ نہیں ہے) اللہ اور آخرت کے دن پر ایمان رکھنے والے شخص کے لیے حلال نہیں کہ مال غنیمت کے سامان کو بیچے یہاں تک کہ وہ تقسیم کر دیا جائے۔","حسن",{"u2":"حنش صنعانی رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا رویفع بن ثابت انصاری رضی اللہ عنہ ہم میں خطبہ کے لیے کھڑے ہوئے تو کہا: میں تمہیں وہی بات کہوں گا جو میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہے۔ آپ نے ہمیں حنین والے دن فرمایا تھا ” جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہے اس کے لیے حلال نہیں کہ کسی دوسرے کی کھیتی کو اپنا پانی دے۔ “ آپ کی مراد تھی کہ حاملہ عورتوں سے مباشرت ” اور جو شخص اللہ اور یوم آخرت پر ایمان رکھا ہے اس کے لیے حلال نہیں کہ قید میں آنے والی کسی عورت سے استبراء (رحم صاف ہونے) سے پہلے مباشرت کرے، اور جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہے اس کے لیے حلال نہیں کہ غنیمت کو تقسیم ہو جانے سے پہلے فروخت کرے۔ “","f2":"1:مومن مسلمان کے لئے اللہ اور یوم آخرت کے حوالے سے بات کرنا انتہائی اہمیت اور تاکید کی حامل ہوتی ہے۔\n2:دوسرے کی کھیتی کو پانی دینا دوسرے کی بیوی سے مباشرت کرنا۔یعنی زنا تو حرام ہے،مگر لونڈی کو جنگ میں ہاتھ آئی ہو استبراء سے پہلے اس سے قربت جائز نہیں۔ اگر حاملہ ہو تو وضع حمل کا انتظار واجب ہے۔\n3: غنیمت میں اپنا حصہ متعین اور حاصل کرنے سے پہلے اس کو فروخت کرنا دھوکے کی ایک صورت ہے،نہ معلوم تھوڑا ملے گا یا زیادہ اور کس قیمت کا ہو گا؟"}],[2159,"اس سند سے بھی ابن اسحاق سے یہی حدیث مروی ہے اس میں ہے: \"یہاں تک کہ وہ ایک حیض کے ذریعہ استبراء رحم کر لے\"، اس میں «بحيضة» کا اضافہ ہے، اور یہ ابومعاویہ کا وہم ہے اور یہ ابوسعید رضی اللہ عنہ کی حدیث میں صحیح ہے، اور اس روایت میں یہ بھی اضافہ ہے: \"اور جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ مسلمانوں کے مال فیٔ کے جانور پر سواری نہ کرے کہ اسے دبلا کر کے واپس دے\"، اور جو اللہ اور یوم آخرت پر ایمان رکھتا ہو وہ مسلمانوں کے مال فیٔ کا کپڑا نہ پہنے کہ پرانا کر کے لوٹا دے۔ ابوداؤد کہتے ہیں کہ حیض کا لفظ محفوظ نہیں ہے یہ ابومعاویہ کا وہم ہے۔","حسن",{"u2":"سعید بن منصور، ابومعاویہ سے وہ ابن اسحٰق سے یہ حدیث بیان کرتے ہیں، کہا کہ ” حتیٰ کہ ایک حیض سے اس کا استبراء (رحم صاف) نہ کر لے۔ “ اس میں «بحيضة» کا لفظ زیادہ کیا جو کہ ابومعاویہ کا وہم ہے مگر ابوسعید کی روایت میں صحیح ہے۔ اور اس میں مزید یہ ہے ” جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہے وہ مسلمانوں کے مال غنیمت کے جانوروں میں سے کسی پر سوار نہ ہو کہ جب اسے کمزور کر دے تو اسے واپس کر دے۔ اور جو اللہ اور یوم آخرت پر ایمان رکھتا ہے وہ مسلمانوں کے مال غنیمت کے کپڑوں میں سے کوئی کپڑا نہ پہنے کہ جب اسے پرانا کر دے تو واپس کر دے۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ «الحيضة» کا لفظ محفوظ نہیں ہے اور یہ ابومعاویہ کہ وہم ہے۔"}],[2160,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی جب کسی عورت سے نکاح کرے یا کوئی خادم خریدے تو یہ دعا پڑھے: «اللهم إني أسألك خيرها وخير ما جبلتها عليه وأعوذ بك من شرها ومن شر ما جبلتها عليه» \"اے اللہ! میں تجھ سے اس کی بھلائی اور اس کی جبلت اور اس کی طبیعت کا خواستگار ہوں، جو خیر و بھلائی تو نے ودیعت کی ہے، اس کے شر اور اس کی جبلت اور طبیعت میں تیری طرف سے ودیعت شر سے تیری پناہ مانگتا ہوں اور جب کوئی اونٹ خریدے تو اس کے کوہان کی چوٹی پکڑ کر یہی دعا پڑھے\"۔ ابوداؤد کہتے ہیں: عبداللہ سعید نے اتنا اضافہ کیا ہے کہ \"پھر اس کی پیشانی پکڑے اور عورت یا خادم میں برکت کی دعا کرے\"۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد (شعیب) سے اور وہ اپنے دادا (عبداللہ بن عمرو) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی کسی عورت سے شادی کرے یا کوئی خادم خریدے تو چاہیئے کہ یہ دعا کرے «اللهم إني أسألك خيرها وخير جبلتها عليه، وأعوذ بك من شرها ومن شر جبلتها عليه» اے اللہ! میں اس کی خیر کا سوال کرتا ہوں اور اس خیر کا جس پر تو نے اس کو پیدا کیا، اور اس کے شر سے تیری پناہ مانگتا ہوں اور اس شر سے جس پر تو نے اس کو پیدا کیا ہے۔ “ اور جب کوئی اونٹ خریدے تو اس کے کوہان کی چوٹی کو پکڑے اور اسی طرح دعا کرے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابوسعید نے اضافہ کیا کہ (آپ نے فرمایا) ” بیوی اور خادم کی پیشانی کے بال پکڑے اور برکت کی دعا کرے۔ “","f2":"یقینا ہر ہر فرد اور ہرہر چیز میں خیر اور برکت اسی وقت ہو سکتی ہے جب اللہ عزوجل نے اس میں مقدرفرمائی ہو تو واجب ہے کہ اللہ عزوجل ہی سے ہمیشہ اس کا سوال کیا جائے اور کسی شخص یا چیز میں پا یا جانے والا شر بھی اللہ عزوجل کی مشیت سے ہے تو اس سے تحفظ کا سوال بھی اللہ تعالی ہی سے ہونا چاہیے بالخصوص بیو ی کا معاملہ بہت ہی اہم ہے، تقابلی اعتبار سے بیوی بھی اپنے شوہر کے متعلق اللہ تعالی سے خیر کی دعا اور اس کےشر سے پناہ مانگ سکتی ہے۔، اگر چہ نص اور صراحت نہیں ہے اوراس کے لئے پیشانی کے بال پکڑنا بھی ضروری نہیں ہے۔"}],[2161,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم میں سے کوئی اپنی بیوی کے پاس آنے کا ارادہ کرے اور یہ دعا پڑھے: «بسم الله اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا» \"اللہ کے نام سے شروع کرتا ہوں اے اللہ ہم کو شیطان سے بچا اور اس مباشرت سے جو اولاد ہو اس کو شیطان کے گزند سے محفوظ رکھ\" پھر اگر اس مباشرت سے بچہ ہونا قرار پا جائے تو اللہ تعالی اس بچے پر شیطان کا زور نہ چلنے دے گا یا شیطان اسے کبھی نقصان نہ پہنچ اس کے گا\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی جب اپنی اہلیہ سے مباشرت کا ارادہ کرے اور درج ذیل دعا پڑھ لے تو اگر ان میں اس باری میں بچہ مقدر ہوا تو اسے شیطان کبھی نقصان نہیں پہنچا سکے گا۔ (دعا یہ ہے) «بسم الله، اللهم جنبنا الشيطان وجنب الشيطان رزقتنا» اللہ کے نام سے، اے اللہ! ہم کو شیطان سے دور رکھ، اور شیطان کو اس سے دور رکھ جو تو ہمیں عنایت فرمائے۔ “","f2":"علامہ داودی نے کہا ہے کہ اس سے بچے کی کلی عصمت مراد نہیں بلکہ یہ ہے کہ شیطان اس کو دین کے معاملے میں فتنے میں نہیں ڈال سکے گا کہ کفر تک پہنچا دے۔(عون المعبود)"}],[2162,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنی بیوی کی دبر (پاخانہ کے مقام) میں صحبت کرے اس پر لعنت ہے\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ملعون ہے وہ شخص جو بیوی سے دبر میں مباشرت کرتا ہے۔ “"}],[2163,"محمد بن منکدر کہتے ہیں کہ میں نے جابر رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ یہود کہتے تھے کہ اگر آدمی اپنی بیوی کی شرمگاہ میں پیچھے سے صحبت کرے تو لڑکا بھینگا ہو گا، تو اللہ تعالی نے یہ آیت نازل فرمائی «نساؤكم حرث لكم فأتوا حرثكم أنى شئتم» (سورۃ البقرہ: ۲۲۳) تمہاری عورتیں تمہاری کھیتیاں ہیں تو تم اپنی کھیتیوں میں جدھر سے چاہو آؤ ۱؎۔\n§وضاحت\n۱؎ : یعنی کھڑے اور بیٹھے ، آگے سے اور پیچھے سے، چت لٹا کر یا کروٹ بشرطیکہ دخول فرج میں ہو نہ کہ دبر میں۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ یہودی کہا کرتے تھے کہ اگر آدمی اپنی بیوی سے اس کے پیچھے سے فرج (قبل) میں مباشرت کرے (کہ وہ پیٹ کے بل لیٹی ہوئی ہو) تو اس سے بچہ بھینگا پیدا ہوتا ہے، تو اللہ عزوجل نے یہ نازل فرمایا «نساؤكم حرث لكم فأتوا حرثكم أنى شئتم» ” تمہاری عورتیں تمہاری کھیتیاں ہیں، اپنی کھیتیوں میں جیسے چاہو آؤ۔ “","f2":"یعنی یہودیوں کا قول وہم باطل ہے اور زوجین کو باہم ہر طرح سے تلذذ کی اجازت ہے۔ صرف شرط وہی ہے جو اوپر کی حدیث میں ذکر آئی اور مزید یہ کہ ایام حیض بھی نہ ہوں۔"}],[2164,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اللہ ابن عمر رضی اللہ عنہما کو بخشے ان کو «أنى شئتم» کے لفظ سے وہم ہو گیا تھا، اصل واقعہ یوں ہے کہ انصار کے اس بت پرست قبیلے کا یہود (جو کہ اہل کتاب ہیں کے) ایک قبیلے کے ساتھ میل جول تھا اور انصار علم میں یہود کو اپنے سے برتر مانتے تھے، اور بہت سے معاملات میں ان کی پیروی کرتے تھے، اہل کتاب کا حال یہ تھا کہ وہ عورتوں سے ایک ہی آسن سے صحبت کرتے تھے، اس میں عورت کے لیے پردہ داری بھی زیادہ رہتی تھی، چنانچہ انصار نے بھی یہودیوں سے یہی طریقہ لے لیا اور قریش کے اس قبیلہ کا حال یہ تھا کہ وہ عورتوں کو طرح طرح سے ننگا کر دیتے تھے اور آگے سے، پیچھے سے، اور چت لٹا کر ہر طرح سے لطف اندوز ہوتے تھے، مہاجرین کی جب مدینہ میں آمد ہوئی تو ان میں سے ایک شخص نے انصار کی ایک عورت سے شادی کی اور اس کے ساتھ وہی طریقہ اختیار کرنے لگا اس پر عورت نے اعتراض کرتے ہوئے کہا کہ ہمارے یہاں تو ایک ہی (مشہور) آسن رائج ہے، لہٰذا یا تو اس طرح کرو، ورنہ مجھ سے دور رہو، جب اس بات کا چرچا ہوا تو رسول اللہ صلی اللہ علیہ وسلم کو بھی اس کی خبر لگ گئی چنانچہ اللہ عزوجل نے یہ آیت «نساؤكم حرث لكم فأتوا حرثكم أنى شئتم» نازل فرمائی یعنی آگے سے پیچھے سے، اور چت لٹا کر اس سے مراد لڑکا پیدا ہونے کی جگہ ہے یعنی شرمگاہ میں جماع ہے ۱؎۔\n§وضاحت\n۱؎ : کیوں کہ کھیتی اس مقام کو کہیں گے جہاں سے ولادت ہوتی ہے نہ کہ دبر کو جو نجاست کی جگہ ہے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے انہوں نے کہا کہ ابن عمر رضی اللہ عنہ کی اللہ مغفرت فرمائے۔ انہیں وہم ہوا ہے۔ دراصل قبیلہ انصار بت پرست لوگ تھے، اس یہودی قبیلے کے ساتھ رہتے تھے جو کہ اہل کتاب تھے۔ اور انصار علم کی وجہ سے ان کی فضیلت کے معترف تھے اور اپنے اکثر کاموں میں ان کی پیروی کیا کرتے تھے۔ اہل کتاب کا معاملہ یہ تھا کہ یہ لوگ اپنی بیویوں سے ایک ہی انداز میں چت لٹا کر (یا پہلو کے بل سے) مجامعت کیا کرتے تھے۔ اس طرح عورت بہت زیادہ پردے میں رہتی ہے۔ ان انصاریوں نے بھی ان جیسا یہ عمل اختیار کیا ہوا تھا۔ لیکن قبیلہ قریش والے اپنی عورتوں کو بری طرح پھیلاتے تھے اور طرح طرح سے متلذذ ہوتے تھے۔ آگے سے، پیچھے سے اور چت لٹا کر۔ جب مہاجرین مدینے میں آئے اور ان کے ایک آدمی نے انصار کی ایک عورت سے شادی کی تو اس کے ساتھ اپنے اسی انداز میں صحبت کرنے لگا تو عورت نے بہت برا جانا اور کہنے لگی ہم سے ایک ہی انداز میں (چت لٹا کر یا پہلو کے بل سے) صحبت کی جاتی تھی، سو تم بھی اسی طرح کرو ورنہ مجھ سے الگ رہو حتیٰ کہ ان کا معاملہ بہت بڑھ گیا اور رسول اللہ صلی اللہ علیہ وسلم تک جا پہنچا۔ تو اللہ تعالیٰ نے یہ نازل فرمایا «نساؤكم حرث لكم فأتوا حرثكم أنى شئتم» تمہاری عورتیں تمہاری کھیتیاں ہیں، تو اپنی کھیتی میں جس طرح سے جی چاہے آؤ۔ “ آگے سے، پیچھے سے یا چت لٹا کر، لیکن جگہ وہی بچے والی ہو۔","f2":"1:بیوی سے پاخانہ کی جگہ میں مباشرت کرنا حرا م اور لعنت کا کام ہے کیونکہ رسول صلی اللہ علیہ وسلم نے فرمایا وہ شخص ملعون ہے جو اپنی بیوی کی دبر میں مباشرت کرے۔ اسی کی بابت ایک جگہ پر یوں فرمایا: اللہ تعالی اس شخص کی طرف نہیں دیکھے گا جو کسی مرد یا عورت کی دبر میں جنسی عمل کرے۔ ان فرامین کی روشنی میں مر دکو اس قبیح عمل سے اجتناب کرنا چاہیے اور عورت کو چاہیے کہ اس منکر عظیم کے بارے میں اپنے شوہر کی بات نہ مانے اگر وہ ایسا کرنے کے لئے کہے تو انکار کردے۔\n2: شروع حدیث میں جو حضرت ابن عمررضی اللہ کی طرف اشارہ کیا گیا ہے کہ وہ آیت مذکورہ تفسیر کی بابت کچھ اختلاف ہے،گویہ یہ بات صحیح نہیں لیکن حضرت ابن عباس کو اسی طرح خبر دی گئی تھی۔حالانکہ حضرت ابن عمررضی اللہ کے قائل نہیں تھے،جیسے کہ علامہ ابن قیم رضی اللہ نے اس کی وضاحت فرمادی ہے۔(حواشی عون المعبود)"}],[2165,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ یہودیوں میں جب کوئی عورت حائضہ ہو جاتی تو اسے گھر سے نکال دیتے نہ اس کے ساتھ کھاتے پیتے اور نہ ہی اسے گھر میں رکھتے، رسول اللہ صلی اللہ علیہ وسلم سے اس سلسلہ میں دریافت کیا گیا تو اللہ تعالی نے یہ آیت نازل فرمائی «يسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض» \"لوگ آپ سے حیض کے متعلق سوال کرتے ہیں تو کہہ دیجئیے کہ وہ گندگی ہے لہٰذا تم حیض کی حالت میں عورتوں سے علیحدہ رہو\" (سورۃ البقرہ: ۲۲۲)، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ: \"انہیں گھروں میں رکھو اور جماع کے علاوہ ہر کام کرو\"، اس پر یہودیوں نے کہا کہ: یہ شخص تو ہمارے ہر کام کی مخالفت کرتا ہے، چنانچہ اسید بن حضیر اور عباد بن بشر رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور کہنے لگے: اللہ کے رسول! یہودی ایسا ایسا کہہ رہے ہیں، تو کیا ہم (ان کی مخالفت میں) عورتوں سے حالت حیض میں جماع نہ کرنے لگیں؟ یہ سن کر اللہ کے رسول صلی اللہ علیہ وسلم کا چہرہ متغیر ہو گیا، یہاں تک کہ ہمیں اپنے اوپر آپ کی ناراضگی کا گمان ہونے لگا چنانچہ دونوں آپ صلی اللہ علیہ وسلم کے پاس سے نکل آئے، اسی اثناء میں آپ کے پاس دودھ کا ہدیہ آ گیا، تو آپ صلی اللہ علیہ وسلم نے انہیں بلوا بھیجا جس سے ہمیں لگا کہ آپ ان سے ناراض نہیں ہیں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ یہودی لوگ جب ان میں کوئی عورت حیض سے ہوتی تو اس کو گھر سے نکال دیتے تھے۔ اس کے ساتھ کھاتے نہ پیتے اور نہ ایک گھر میں اکٹھے رہتے۔ رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں پوچھا گیا تو اللہ تعالیٰ نے یہ نازل فرمایا «ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض» ” لوگ آپ سے حیض کے بارے میں سوال کرتے ہیں کہہ دیجئیے کہ وہ گندگی ہے، سو حالت حیض میں عورتوں سے الگ رہو۔۔۔ “ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ان کے ساتھ گھروں میں اکٹھے رہو اور ہر فعل کر سکتے ہو سوائے نکاح (جنسی عمل) کے۔ “ یہودی کہنے لگے۔ یہ آدمی (محمد صلی اللہ علیہ وسلم) ہمارے کسی کام کو نہیں چھوڑتا مگر اس کی مخالفت ہی کرتے ہے۔ سیدنا اسید بن حضیر اور عباد بن بشر رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہنے لگے۔ اے اللہ کے رسول! یہودی اس اس طرح کہتے ہیں، تو کیا ہم حیض کے دنوں میں بھی عورتوں سے مجامعت نہ کر لیا کریں؟ اس پر رسول اللہ صلی اللہ علیہ وسلم کا چہرہ مبارک بدل گیا۔ حتیٰ کہ ہمیں یقین ہو گیا کہ آپ ان دونوں سے واقعتاً ناراض ہو گئے ہیں، چنانچہ وہ (آپ کی مجلس سے) نکل آئے۔ (ان کے جانے کے بعد) رسول اللہ صلی اللہ علیہ وسلم کے پاس دودھ کا ہدیہ آ گیا۔ تو آپ نے ان کو پیچھے سے بلوایا، تب ہمیں تسلی ہوئی کہ آپ ان پر (دلی طور سے) ناراض نہیں ہوئے تھے۔","f2":"فوائد پیچھے حدیث نمبر258 میں گزر چکے ہیں۔"}],[2166,"خلاس بن عمرو ہجری کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے ہوئے سنا: میں اور رسول اللہ صلی اللہ علیہ وسلم دونوں ایک ہی کپڑے میں رات گزارتے اور میں حالت حیض میں ہوتی، اگر کہیں آپ صلی اللہ علیہ وسلم کو کچھ لگ جاتا تو صرف اس جگہ کو دھو لیتے اس سے آگے نہ بڑھتے، اور کہیں کپڑے میں لگ جاتا تو صرف اتنی ہی جگہ دھو لیتے، اس سے آگے نہ بڑھتے اور اسی کپڑے میں نماز پڑھتے۔","صحیح",{"u2":"جناب خلاس ہجری کہتے ہیں کہ میں نے سیدہ عائشہ رضی اللہ عنہا ا کو بیان کرتے ہوئے سنا کہ میں اور رسول اللہ صلی اللہ علیہ وسلم ایک ہی چادر میں سو جاتے تھے حالانکہ میں ایام میں ہوتی۔ اگر آپ صلی اللہ علیہ وسلم کو مجھ سے کچھ (خون وغیرہ) لگ جاتا تو اس جگہ کو دھو لیتے اور اس جگہ سے مزید آگے نہ دھوتے۔ اور اگر آپ صلی اللہ علیہ وسلم کے کپڑے کو کچھ لگ جاتا تو اسی جگہ کو دھو لیتے اور اس سے تجاوز نہ کرتے اور اسی میں نماز پڑھ لیتے۔","f2":"فوائد پیچھے حدیث 269 میں گزر چکے ہیں"}],[2167,"عبداللہ بن شداد اپنی خالہ میمونہ بنت حارث رضی اللہ عنہا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی کسی بیوی سے حالت حیض میں مباشرت کرنے کا ارادہ فرماتے تو اسے تہبند باندھنے کا حکم دیتے پھر اس کے ساتھ لیٹ جاتے ۔","صحیح",{"u2":"ام المؤمنین سیدہ میمونہ رضی اللہ عنہا ا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنی کسی بیوی کے ساتھ لیٹنا چاہتے اور وہ حیض سے ہوتی، تو اسے کہتے کہ اپنی تہ بند خوب اچھی طرح باندھ لے، پھر اس کے ساتھ لیٹ جاتے۔","f2":"چونکہ نبي? کي پوري زندگي امت کے ليے اسوہ اور نمونہ ہےاس ليے آپ کے اندرون خانہ کے احوال بھي بيان کيے گئے ہيں?"}],[2168,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اس شخص کے بارے میں جو اپنی بیوی سے حالت حیض میں صحبت کر بیٹھتا ہے فرمایا: \"وہ ایک یا آدھا دینار (بطور کفارہ) صدقہ ادا کرے\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ وہ شخص جو اپنی بیوی سے اس کے ایام حیض میں مجامعت کر بیٹھے (اس کی بابت) آپ صلی اللہ علیہ وسلم نے فرمایا ” ایک دینار صدقہ دے یا آدھا دینار۔ “"}],[2169,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اگر دوران خون صحبت کی تو ایک دینار، اور خون بند ہو جانے پر صحبت کی تو آدھا دینار(کفارہ) ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کہتے ہیں کہ اگر خون کے دنوں میں مباشرت کی ہو تو ایک دینار صدقہ کرے اور اگر خون رک جانے کے دنوں میں کی ہو تو آدھا دینار۔","f2":"یہ اثر معمولی اختلاف الفاظ سے پہلے گزر چکا ہے دیکھیے حدیث نمبر:265"}],[2170,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے عزل ۱؎ کا ذکر کیا گیا تو آپ نے فرمایا: \"تم میں سے کوئی ایسا کیوں کرتا ہے؟ (یہ آپ صلی اللہ علیہ وسلم نے نہیں فرمایا کہ وہ ایسا نہ کرے)، کیونکہ اللہ تعالی جس نفس کو پیدا کرنا چاہتا ہے تو وہ اسے پیدا کر کے ہی رہے گا ۲؎\"۔ ابوداؤد کہتے ہیں: قزعہ، زیاد کے غلام ہیں۔\n§وضاحت\n۱؎ : عضو تناسل کو عورت کی شرمگاہ سے باہر نکال کر منی گرانے کا نام عزل ہے۔ ۲؎ : اس سے مطلقاً عزل کی کراہت ثابت ہوتی ہے اور بعض لوگوں نے کہا ہے کہ آزاد عورت سے بغیر اس کے اذن کے مکروہ ہے اور لونڈیوں سے بغیر اذن کے بھی درست ہے۔","صحیح",{"u2":"سیدناابوسعید رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے سامنے اس کا ذکر آیا یعنی عزل کا، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی یہ کرتا ہی کیوں ہے؟ “ آپ صلی اللہ علیہ وسلم نے یہ نہیں فرمایا ” تم میں سے کوئی بھی یہ نہ کرے۔ “ بلاشبہ جو جان پیدا ہونے والی ہے اللہ تعالیٰ اسے پیدا کر کے رہے گا۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ راوی حدیث قزعہ یہ زیاد کا مولیٰ ہے۔","f2":"مباشرت کرتے وقت مرد اپنی منی عورت کی فرج میں نکالنے کی بجائے باہر نکالےاسے عزل کہتے ہیں۔"}],[2171,"ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے کہا: اللہ کے رسول! میری ایک لونڈی ہے جس سے میں عزل کرتا ہوں، کیونکہ اس کا حاملہ ہونا مجھے پسند نہیں اور مرد ہونے کے ناطے مجھے شہوت ہوتی ہے، حالانکہ یہود کہتے ہیں کہ عزل زندہ درگور کرنے کی چھوٹی شکل ہے، یہ سن کر آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہود جھوٹ کہتے ہیں اگر اللہ تعالی کو پیدا کرنا منظور ہو گا، تو تم اسے پھیر نہیں سکتے\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے کہا: اے اللہ کے رسول! میری ایک لونڈی ہے اور میں اس سے عزل کرتا ہوں، اور اس کا حاملہ ہونا مجھے پسند نہیں ہے، اور میں وہی چاہتا ہوں جو مرد چاہتے ہیں۔ مگر یہودی کہتے ہیں کہ عزل کرنا چھوٹے انداز میں زندہ درگور کرنا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہودی غلط کہتے ہیں۔ اگر اللہ تعالیٰ اس کو پیدا کرنا چاہے گا تو، تو اسے ٹال نہیں سکتا۔ “"}],[2172,"عبداللہ بن محیریز کہتے ہیں کہ مسجد میں داخل ہوا تو میں نے ابو سعید خدری رضی اللہ عنہ کو دیکھا اور ان کے پاس بیٹھ گیا، ان سے عزل کے متعلق سوال کیا، تو آپ نے جواب دیا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ہم راہ غزوہ بنی مصطلق میں نکلے تو ہمیں کچھ عربی لونڈیاں ہاتھ لگیں، ہمیں عورتوں کی خواہش ہوئی اور عورتوں سے الگ رہنا ہم پر گراں گزرنے لگا ہم ان لونڈیوں کو فدیہ میں لینا چاہ رہے تھے اس لیے حمل کے ڈر سے ہم ان سے عزل کرنا چاہ رہے تھے، پھر ہم نے اپنے (جی میں) کہا کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان موجود ہیں تو آپ سے اس بارے میں پوچھنے سے پہلے ہم عزل کریں (تو یہ کیونکر درست ہو گا) چنانچہ ہم نے آپ سے اس بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ نہ کرو تو تمہارا کیا نقصان ہے؟ قیامت تک جو جانیں پیدا ہونے والی ہیں وہ تو ہو کر رہیں گی\"۔","صحیح",{"u2":"ابن محیریز کہتے ہیں کہ میں مسجد میں داخل ہوا اور سیدنا ابو سعید خدری رضی اللہ عنہ کو دیکھا تو ان کے پاس بیٹھ گیا۔ میں نے ان سے عزل کے بارے میں پوچھا، تو انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ بنی مصطلق میں گئے اور ہمیں اس غزوے میں لونڈیاں ہاتھ آئیں، عرب عورتیں، ہمیں عورتوں کی بہت خواہش تھی، اور عورتوں کے بغیر (مجرد) رہنا ہمیں بہت مشکل ہو رہا تھا۔ اور ہم ان لونڈیوں کو بیچنا بھی چاہتے تھے (اس لیے چاہتے تھے کہ حاملہ نہ ہوں) تو ہم نے عزل کا ارادہ کیا۔ پھر ہم نے سوچا کہ رسول اللہ صلی اللہ علیہ وسلم ہم میں موجود ہیں، ان سے پوچھے بغیر ہم یہ کام کریں (کسی طرح جائز نہیں۔) چنانچہ ہم نے آپ سے اس بارے میں پوچھا، تو آپ نے فرمایا ” اگر نہ کرو تو تم پر کوئی حرج نہیں، قیامت تک جو جان بھی پیدا ہونے والی ہے، وہ پیدا ہو کر رہے گی۔ “","f2":"1۔ عزل ایک ناپسندیدہ عمل ہے مگر مباح ہونے میں کوئی شبہ نہیں۔نبی صلی اللہ علیہ وسلم کا فرمان قابل توجہ ہے۔آپ نے فرمایا: اگر نہ کرو تو تم پر کوئی حرج نہیں۔ یہ نہیں فرمایا کہ اگر کرو تو تم پر کوئی حرج نہیں۔یعنی کراہت کے ساتھ اس کا جواز باقی رکھا تاکہ ناگزیر قسم کی صورت میں اسے اختیار کرنے کی گنجائش باقی رہے۔عزل کی یہ صورت عہد رسالت و عہد صحابہ میں رائج تھی جسے کراہت کے ساتھ جائز رکھاگیا۔لیکن آج کل اس کے متبادل کئی صورتیں نکل آئی ہیں۔جیسے ساتھی (کنڈومز) کا استعمال\n2۔بعض دوائیں یا انجکشن جن کے استعمال سے کچھ مدت تک حمل قرار نہیں پاتا\n3۔عورتوں کے رحم کا آپریشن جس کے بعد عورت حاملہ نہیں ہوتی۔\n4۔نس بندی جس میں مرد کے آلہ تناسل کا آپریشن کرکے اسے بارآور کرنے کی صلاحیت سے محروم کردیا جاتا ہے۔\nپہلی دو صورتیں عارضی ہیں(عزل حمل سے بچنے کا ایک طریقہ ہے) اس لیے یہ دونوں طریقے حسب ضرورت جائز ہوں گے۔جیسے عورت کی صحت کمزور ہو اور مزید ولادت اس کی جان کے لیے خطرے کا باعث ہو۔اس قسم کی صورت میں دونوں طریقوں میں سے کوئی سا طریقہ اختیار کیا جاسکتا ہے۔لیکن اس کا مقصد عورت کے حسن وجمال کی حفاظت ہو یا بچوں کو کھلانے پلانے اور ان کی تعلیم و تربیت کا خوف ہوتو اس قسم کے مقاصد کے لیے ان دونوں عارضی طریقوں کا بھی اختیار کرنا ناجائز ہوگا۔\nاور تیسرا اور چوتھا طریقہ جس میں مستقل طور پر حاملہ ہونے یا حاملہ کرنے کا سد باب کردیا جاتا ہے یکسر ھرام ناجائز اور اللہ کی تخلیق کو بدلنا ہے۔اس کا جواز کسی بھی صورت میں نہیں ہے۔"}],[2173,"جابر رضی اللہ عنہ کہتے ہیں کہ انصار کا ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس نے کہا کہ: میری ایک لونڈی ہے جس سے میں صحبت کرتا ہوں اور اس کا حاملہ ہونا مجھے پسند نہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"چاہو تو عزل کر لو، جو اس کے مقدر میں ہے وہ تو ہو کر رہے گا\"، ایک مدت کے بعد وہ شخص آ کر کہنے لگا، کہ لونڈی حاملہ ہو گئی، آپ صلی اللہ علیہ وسلم نے فرمایا کہ: \"میں نے تو کہا ہی تھا کہ جو اس کے مقدر میں ہے وہ ہو کر رہے گا\"۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ کا بیان ہے کہ ایک انصاری رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: میری ایک لونڈی ہے، میں اس سے صحبت کرتا ہوں اور اس کا حاملہ ہونا مجھے پسند نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر چاہو تو عزل کر لیا کرو، جو اس کے مقدر میں ہے وہ تو آ کر رہے گا۔ “ بیان کیا کہ کچھ دن گزرے، پھر وہ آدمی آپ صلی اللہ علیہ وسلم کے پاس آیا اور بتایا کہ لونڈی حاملہ ہو گئی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں نے تمہیں کہا تھا کہ جو اس کے مقدر میں ہے وہ آ کر رہے گا۔ “"}],[2174,"ابونضرہ کہتے ہیں: مجھ سے قبیلہ طفاوہ کے ایک شیخ نے بیان کیا کہ مدینہ میں میں ایک بار ابوہریرہ رضی اللہ عنہ کا مہمان ہوا میں نے صحابہ کرام رضی اللہ عنہم میں کسی کو بھی مہمانوں کے معاملے میں ان سے زیادہ چاق و چوبند اور ان کی خاطر مدارات کرنے والا نہیں دیکھا، ایک مرتبہ کا واقعہ ہے کہ میں ان کے پاس تھا، وہ اپنے تخت پر بیٹھے تھے ان کے ساتھ ایک تھیلی تھی جس میں کنکریاں یا گٹھلیاں تھیں، نیچے ایک کالی کلوٹی لونڈی تھی، آپ رضی اللہ عنہ ان کنکریوں پر تسبیح پڑھ رہے تھے، جب (پڑھتے پڑھتے) تھیلی ختم ہو جاتی تو انہیں لونڈی کی طرف ڈال دیتے، اور وہ انہیں دوبارہ تھیلی میں بھر کر دیتی ابوہریرہ رضی اللہ عنہ کہنے لگے: کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنا ایک واقعہ نہ بتاؤں؟ میں نے کہا: کیوں نہیں، ضرور بتائیے، انہوں نے کہا: میں مسجد میں تھا اور بخار میں مبتلا تھا کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے یہاں تک کہ مسجد میں داخل ہوئے اور کہنے لگے: \"کس نے دوسی جوان (ابوہریرہ) کو دیکھا ہے؟\" یہ جملہ آپ نے تین بار فرمایا، تو ایک شخص نے کہا: اللہ کے رسول! وہ یہاں مسجد کے کونے میں ہیں، انہیں بخار ہے، چنانچہ آپ صلی اللہ علیہ وسلم تشریف لائے اور اپنا دست مبارک میرے اوپر رکھا، اور مجھ سے بھلی بات کی تو میں اٹھ گیا، اور آپ چل کر اسی جگہ واپس آ گئے، جہاں نماز پڑھاتے تھے، اور لوگوں کی جانب متوجہ ہوئے، آپ صلی اللہ علیہ وسلم کے ساتھ دو صف مردوں اور ایک صف عورتوں کی تھی یا دو صف عورتوں کی اور ایک صف مردوں کی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر نماز میں شیطان مجھے کچھ بھلا دے تو مرد سبحان اللہ کہیں، اور عورتیں تالی بجائیں\"، رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی اور نماز میں کوئی چیز بھولے نہیں اور فرمایا: \"اپنی جگہوں پر بیٹھے رہو، اپنی جگہوں پر بیٹھے رہو\"، پھر آپ صلی اللہ علیہ وسلم نے اللہ تعالی کی حمد و ثنا بیان کی، پھر امابعد کہا اور پہلے مردوں کی جانب متوجہ ہوئے اور فرمایا: \"کیا تم میں کوئی ایسا ہے جو اپنی بیوی کے پاس آ کر، دروازہ بند کر لیتا ہے اور پردہ ڈال لیتا ہے اور اللہ کے پردے میں چھپ جاتا ہے؟\"، لوگوں نے جواب دیا: ہاں، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے بعد وہ لوگوں میں بیٹھتا ہے اور کہتا ہے: میں نے ایسا کیا میں نے ایسا کیا\"، یہ سن کر لوگ خاموش رہے، مردوں کے بعد آپ صلی اللہ علیہ وسلم عورتوں کی جانب متوجہ ہوئے اور ان سے بھی پوچھا کہ: \"کیا کوئی تم میں ایسی ہے، جو ایسی باتیں کرتی ہے؟\"، تو وہ بھی خاموش رہیں، لیکن ایک نوجوان عورت اپنے ایک گھٹنے کے بل کھڑی ہو کر اونچی ہو گئی تاکہ آپ صلی اللہ علیہ وسلم اسے دیکھ سکیں اور اس کی باتیں سن سکیں، اس نے کہا: اللہ کے رسول! اس قسم کی گفتگو مرد بھی کرتے ہیں اور عورتیں بھی کرتی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\"جانتے ہو ایسے شخص کی مثال کیسی ہے؟\"، پھر خود ہی فرمایا: \"اس کی مثال اس شیطان عورت کی سی ہے جو گلی میں کسی شیطان مرد سے ملے، اور اس سے اپنی خواہش پوری کرے، اور لوگ اسے دیکھ رہے ہوں۔ خبردار! مردوں کی خوشبو وہ ہے جس کی بو ظاہر ہو رنگ ظاہر نہ ہو اور خبردار! عورتوں کی خوشبو وہ ہے جس کا رنگ ظاہر ہو بو ظاہر نہ ہو\"۔ ابوداؤد کہتے ہیں: مجھے موسی اور مومل کے یہ الفاظ یاد ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"خبردار! کوئی مرد کسی مرد اور کوئی عورت کسی عورت کے ساتھ ایک بستر میں نہ لیٹے مگر اپنے باپ یا بیٹے کے ساتھ لیٹا جا سکتا ہے\"۔ راوی کا بیان ہے کہ بیٹے اور باپ کے علاوہ ایک تیسرے آدمی کا بھی ذکر آپ صلی اللہ علیہ وسلم نے کیا جو میں بھول گیا وہ مسدد والی روایت میں ہے، لیکن جیسا یاد رہنا چاہیئے وہ مجھے یاد نہیں۔","حسن لغیرہ",{"u2":"ابونضرہ بیان کرتے ہیں کہ قبیلہ طفاوہ کے ایک شیخ نے مجھ سے بیان کیا کہ میں مدینے میں سیدنا ابوہریرہ رضی اللہ عنہ کا مہمان ہوا۔ وہ اصحاب نبی کریم صلی اللہ علیہ وسلم میں سب سے بڑھ کر عبادت میں مستعد اور مہمان نواز تھے۔ ایک دن میں ان کے پاس تھا جب کہ وہ اپنے تخت پر بیٹھے تھے اور ان کے پاس ایک تھیلی تھی، اس میں کنکریاں تھیں یا گٹھلیاں، تخت سے نیچے ان کی لونڈی بیٹھی تھی سیاہ رنگ کی، آپ ان کنکریوں یا گٹھلیوں پر تسبیح پڑھ رہے تھے۔ جب وہ ختم ہو جاتی تو وہ اسے اس کی طرف پھینک دیتے اور وہ انہیں اکٹھی کر کے پھر سے تھیلی میں بھر کر ان کو دے دیتی۔ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا: کیا میں تمہیں اپنی اور رسول اللہ صلی اللہ علیہ وسلم کی بات نہ سناؤں، میں نے کہا: کیوں نہیں! کہا: ایک دفعہ میں بخار میں مبتلا مسجد میں پڑا تھا کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے حتیٰ کہ مسجد میں داخل ہوئے اور پوچھا ” کسی کو دوسی جوان کی خبر ہے؟ “ (دوس سیدنا ابوہریرہ رضی اللہ عنہ کے قبیلے کا نام ہے) آپ صلی اللہ علیہ وسلم نے تین بار پوچھا، تو ایک شخص نے کہا: اے اللہ کے رسول! وہ مسجد کے کونے میں ہے اور بخار میں پھنک رہا ہے۔ آپ صلی اللہ علیہ وسلم چلتے ہوئے ہوئے میرے پاس تشریف لائے اور اپنا ہاتھ مبارک مجھ پر رکھا اور میرے بارے میں اچھی بات فرمائی، تو میں اٹھ بیٹھا۔ اور آپ صلی اللہ علیہ وسلم چلتے ہوئے اپنی جائے نماز پر آ گئے اور نمازیوں کی طرف متوجہ ہوئے۔ آپ صلی اللہ علیہ وسلم کے ساتھ دو صفیں مردوں کی تھیں اور ایک صف عورتوں کی یا دو صفیں عورتوں کی اور ایک مردوں کی۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر شیطان مجھے میری نماز بھلوا دے تو مرد سبحان اللہ کہیں اور عورتیں تالی سے متنبہ کریں۔ “ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے نماز پڑھائی اور نماز سے کچھ نہ بھولے۔ پھر فرمایا ” اپنی اپنی جگہ بیٹھے رہو۔ اپنی اپنی جگہ بیٹھے رہو “ موسیٰ نے یہاں اضافہ کیا اور کہا: پھر آپ صلی اللہ علیہ وسلم نے اللہ تعالیٰ کی حمد و ثنا بیان فرمائی۔ پھر کہا: امابعد! اور مردوں کی طرف متوجہ ہوئے اور کہا: ” کیا تم میں کوئی ہے کہ جب اپنی بیوی کے پاس جائے، اس پر دروازہ بند کر لے، اس پر پردہ ڈال دے اور اللہ کے پردے سے چھپ جائے؟ “ سب نے کہا: جی ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا ” پھر وہ بیٹھا کہنے لگتا ہے میں نے ایسے کیا، میں نے ایسے کیا۔ “ تو سب خاموش رہے۔ پھر آپ صلی اللہ علیہ وسلم عورتوں کی طرف متوجہ ہوئے اور فرمایا ” کیا تم میں کوئی ہے جو یہ باتیں بیان کرتی ہو؟ “ تو وہ خاموش رہیں۔ مگر ایک نوجوان عورت، اپنے ایک گھٹنے پر اٹھی۔ مومل نے اپنی روایت میں کہا کہ اس کا سینہ ابھرا ہوا تھا۔ اس نے رسول اللہ صلی اللہ علیہ وسلم کی طرف گردن لمبی کی تاکہ آپ صلی اللہ علیہ وسلم اس کو دیکھ لیں اور اس کی بات سنیں۔ وہ بولی، اے اللہ کے رسول! یقیناً یہ مرد باتیں کرتے ہیں اور یہ عورتیں بھی باتیں کرتی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا جانتے ہو اس کی کیا مثال ہے؟ “ پھر فرمایا ” اس کی مثال اس شیطان عورت کی سی ہے جسے گلی میں کوئی شیطان مرد مل جائے اور وہ اس سے اپنی حاجت پوری کرے اور لوگ اس کی طرف دیکھ رہے ہوں۔ خبردار! مردوں کی خوشبو یہ ہے کہ اس کی خوشبو ظاہر ہو مگر رنگ ظاہر نہ ہو اور عورتوں کی خوشبو یہ ہے کہ اس کا رنگ نمایاں ہو مگر خوشبو ظاہر نہ ہو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں اس مقام پر مجھے مومل اور موسیٰ سے یاد ہے۔ (آپ صلی اللہ علیہ وسلم نے فرمایا) ” خبردار! کوئی مرد کسی مرد کے ساتھ نہ لیٹے یا کوئی عورت کسی عورت کے ساتھ نہ لیٹے، الا یہ کہ بیٹا ہو یا باپ۔ “ اور تیسری بات بھی ذکر کی جو مجھے بھول گئی ہے اور وہ مسدد کی روایت میں ہے مگر وہ مجھے ک حقہ یاد نہیں ہے۔ موسیٰ نے اپنی سند میں کہا: «حدثنا حماد عن الجريري عن أبي نضرة عن الطفاوي»۔","f2":"1۔روایت سنداً ضعیف ہے۔مگر مسئلہ اسی طرح ہے کہ زوجین کو اپنی مباشرت کی تفصیلات بیان کرنا حرام ہے۔اگر کہیں اشد ضرورت ہو تو صھبت کی خبر دے سکتا ہےمگر تفصیل کے بغیر\n2۔مردوں کو عطریات استعمال کرنے چاہییں ان کے لے رنگ نمایاں کرنے والے پاؤڈر نا جائز ہے گھر میں استعمال کر سکتی ہیں۔پاؤدر ایسے استعمال کریں جن میں خوشبو نہ ہوکہ اجانب کو اپنی طرف متوجہ کرنے لگیں\n3۔مردوں یا عورتوں کو اکھٹے لیٹنا نا جائز ہے الا یہ کہ کوئی خاص مجبوری ہو۔باپ بیٹے کو جائز ہے اور اسی طرح ماں بیٹی کے لیے بھی قیاس کے طور پر اس کا جواز ہوسکتا ہے۔"}],[2175,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی عورت کو اس کے شوہر سے یا غلام کو مالک سے برگشتہ کرے وہ ہم میں سے نہیں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” وہ شخص ہم میں سے نہیں ہے جو کسی عورت کو اس کے شوہر کے خلاف ابھارے یا غلام کو اس کے مالک کے خلاف کر دے۔ “"}],[2176,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عورت اپنی بہن کی طلاق کا مطالبہ نہ کرے تاکہ اس کا پیالہ خالی کرا لے (یعنی اس کا حصہ خود لے لے) اور خود نکاح کر لے، جو اس کے مقدر میں ہو گا وہ اسے ملے گا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی عورت اپنی (دینی) بہن کی طلاق کا مطالبہ نہ کرے کہ اس طرح اس کا پیالہ (اپنی خاطر) خالی کرا لے۔ اسے چاہیئے کہ نکاح کر لے، اس کو وہی کچھ ملے گا جو اس کے لیے مقدر کیا گیا ہے۔ “","f2":"یعنی کسی مسلمان بہن کو طلاق دلوانا بہت بری بات ہے بلکہ چاہیے کہ رضا بالقضاء کا مظاہرہ کرے۔اس کو طلاق دلواکریہ نہ اپنے لیے کچھ اضافہ کرسکتی ہے ادر نہ اسکا کچہ نقصان کر سکتی ہے. لہذا اگر اسی مرد کے ساتھ نکاح کرنا چاہتی ہے تو اس کی پہلی بیوی کے ہوتے ہوئے اس سے نکاح کرلے۔"}],[2177,"محارب کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے نزدیک حلال چیزوں میں طلاق سے زیادہ ناپسندیدہ کوئی چیز نہیں\"۔","ضعیف",{"u2":"محارب (محارب بن دثار) کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ نے طلاق سے بڑھ کر ناپسندیدہ کسی چیز کو حلال نہیں فرمایا۔ “"}],[2178,"عبداللہ بن عمر رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"اللہ تعالی کے نزدیک حلال چیزوں میں سب سے زیادہ ناپسندیدہ چیز طلاق ہے\"۔","ضعیف",{"u2":"محارب بن دثار، سیدنا ابن عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اللہ کے ہاں حلال کاموں میں سب سے ناپسندیدہ کام طلاق ہے۔ “","f2":"امام حاکم نے اس کو صحیح کہا ہے اور امام ذہبی نے بھی ان کی توثیق کی ہے۔(مستدرک حاکم الطلاق حدیث:2794)مگر ابو حاتم دار قطنی اور بیہقی نے اس کا مرسل ہونا راجع کہا ہے۔شیخ البانی رحمہ اللہ نے بھی غالباً اسی دجہ سے ان دونوں روایات کو ضعیف سنن ابی میں درج کیا ہے۔\n2۔اور کراہت سے مراد ان اسباب کی کراہت ہے جن کی دجہ سے طلاق ہو۔علامہ خطانی کہتے ہیں کہ نفس طلاق کو اللہ تعالی نے مباح کیا ہے ادر چابت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ازواج کو طلاق دی تھی پھر رجوع کیا تھا۔(سنن ابي داود الطلاق حديث:٢٢٨٣ّمستدرك حاكم الطلاق حديث:٢٧٩٢)\nایسے ہی ابن عمر کی ایک بیوی تھی انہیں ان سے بہت الفت تھی مگر حضرت عمر کو ان کا ان کے ساتھ رہنا پسند نہ تھا۔انہوں نے اس کی شکایت رسول اللہ صلی اللہ علیہ وسلم سے کردی تو آپ نے ان کو بلایا اور کہا: عبداللہ اپنی بیوی کو طلاق دےدو چنانچہ انہوں نے طلاق دےدی۔ (جامع الترمذي الطلاق والعان حديث;١١٨٩)اور یہ نہیں ہوسکتا کہ رسول اللہ صلی اللہ علیہ وسلم کوئی ایسا حکم ارشاد فرمائیں جو اللہ تعالی کے ہاں مکروہ ہو۔\nطلاق کی مختلف صورتیں:\n1۔طلاق سنی:اس کی دو صورتیں ہیں۔\n(الف) طلاق احسن:انسان بیوی کو حالت طہر میں قبل از جماع ایک طلاق دے پھر اسے چھوڑدے حتی کہ اس کی عدت مکمل ہوجائے۔یا عدت گزرنے سے پہلے رجوع کرلے۔\n(ب) طلاق حسن۔ایسے طہر میں طلاق دے جس میں جماع نہ کیا ہوپھر دوسرے طہر میں دوسری طلاق اور تیسرے طہر میں تیسری طلاق دے۔\n2۔طلاق بدعی:ایک لفظ یا جملے میں متعدد طلاقیں دے یا متعدد جملے استعمال کرکے متعدد طلاقیں دے مگر ایک ہی طہر میں دے یا ایسے طہر میں طلاق دے جس میں مباشرت کی ہو۔\n3۔طلاق رجعی:پہلی مرتبہ اور دوسری مرتبہ طلاق رجعی ہوتی ہے۔یعنی ان میں عدت کے دوران میں شوہر کو رجوع کا حق حاصل ہوتا ہے۔\n4۔(الف) طلاق بائن:(بینونہء صغری) یعنی ایک طلاق دے پھر خاموش رہےحتی کہ عدت پوری ہوجائے۔اب عورت بائن ہوگئی جس سے چاہے نکاح کرسکتی ہے۔پہلا شوہر بھی اس کی منظوری اور اجازت سے نکاح کرسکتا ہے۔اس صورت میں بعد از عدت نیا عقد نئے حق مہر سے ہوسکتا ہے۔\n(ب‌) طلاق بائن(بینونہ کبری) مختلف اوقات یا مختلف مجالس میں تین طلاقیں پوری کردےحتی کہ شوہر کو رجوع کا حق باقی نہ رہے ایسی صورت میں وہ عورت کسی اور سے (باقاعدہ آباد رہنے کی نیت سے) نکاح کرے اس سے فی الواقع مباشرت ہو اور پھر اتفاقیہ طلاق یا خاوند کی موت کے سبب وہ عورت وہاں سے فارغ ہوجائے تو پہلے شوہر سے نکاح کرسکتی ہے۔\n5۔ طلاق صریح: واضح اور صریح الفاظ سے طلاق دینا۔\n6۔طلاق کنایہ:ایسے الفاظ سے طلاق دینا جو طلاق اور غیر طلاق دونوں معانی کے متحمل ہوں۔ایسے میں شوہر کی نیت کا اعتبار ہوتا ہے۔\n7۔طلاق منجز:صریح اور واضح طلاق جو فوراً نافذ ہوجاتی ہے۔\n8۔طلاق معلق:کسی قول وفعل کے ساتھ مشروط کرکے طلاق دینا مثلاً اگر ایسا ہوا تو طلاق وغیرہ۔"}],[2179,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو حالت حیض میں طلاق دے دی، تو عمر بن خطاب رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کے متعلق دریافت کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے حکم دو کہ وہ اپنی بیوی سے رجوع کر لے، پھر اسے روکے رکھے یہاں تک کہ وہ حیض سے پاک ہو جائے، پھر حیض آ جائے، پھر پاک ہو جائے، پھر اس کے بعد اگر چاہے تو رکھے، ورنہ چھونے سے پہلے طلاق دیدے، یہی وہ عدت ہے جس کا اللہ تعالی نے عورتوں کو طلاق دینے کے سلسلے میں حکم دیا ہے ۱؎\"۔\n§وضاحت\n۱؎ : حدیث کا مطلب یہ ہے کہ حالت حیض میں طلاق سنت کے خلاف ہے ، سنت یہ ہے کہ اس طہر میں طلاق دی جائے جس میں ہمبستری نہ کی ہو تاکہ وہ طہر (یا حیض) عدت کے شمار کئے جا سکیں، حیض سمیت تین طہر گزر جائیں تو اس کی عدت پوری ہو جائے گی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو طلاق دے دی جبکہ وہ ایام حیض میں تھی۔ سیدنا عمر رضی اللہ عنہ نے اس کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے دریافت کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کو حکم دو کہ اس سے رجوع کرے، پھر اس کو اپنے ہاں رکھے حتیٰ کہ وہ پاک ہو، پھر اسے حیض آئے، پھر پاک ہو، پھر اگر چاہے تو اسے بیوی بنائے رکھے یا چاہے تو طلاق دیدے (مگر) مباشرت سے پہلے اور یہی وہ عدت ہے جس کے موقع پر اللہ تعالیٰ نے عورتوں کو طلاق دینے کا حکم دیا ہے۔ “"}],[2180,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما نے اپنی ایک عورت کو حالت حیض میں ایک طلاق دے دی، آگے مالک کی حدیث کے ہم معنی روایت ہے۔","صحیح",{"u2":"جناب نافع بیان کرتے ہیں کہ سیدنا ابن عمر رضی اللہ عنہ نے اپنی بیوی کو ایک طلاق دے دی جبکہ وہ ایام حیض میں تھی اور (مذکورہ بالا) حدیث مالک کی طرح روایت کی۔"}],[2181,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے اپنی بیوی کو حالت حیض میں طلاق دے دی تو عمر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے اس کا ذکر کیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے حکم دو کہ وہ رجوع کر لے پھر جب وہ پاک ہو جائے یا حاملہ ہو تو اسے طلاق دے ۱؎\"۔\n§وضاحت\n۱؎ : اگر حاملہ ہوگی تو اس کی عدت وضع حمل سے ختم ہوگی ورنہ تین حیض سے ختم ہو جائے گی۔","صحیح",{"u2":"سالم‘سیدنا ابن عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ انہوں نے اپنی بیوی کو ایام حیض میں طلاق دے دی تو سیدنا عمر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کو حکم دو کہ اس سے رجوع کرے، پھر جب پاک ہو تو طلاق دے یا جب وہ حمل سے ہو۔ “"}],[2182,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے اپنی بیوی کو حالت حیض میں طلاق دے دی، عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس کا ذکر کیا، تو رسول اللہ صلی اللہ علیہ وسلم غصہ ہو گئے پھر فرمایا: \"اسے حکم دو کہ اس سے رجوع کر لے پھر اسے روکے رکھے یہاں تک کہ وہ حیض سے پاک ہو جائے، پھر حائضہ ہو پھر پاک ہو جائے پھر چاہیئے کہ وہ پاکی کی حالت میں اسے چھوئے بغیر طلاق دے، یہی عدت کا طلاق ہے جیسا کہ اللہ نے حکم دیا ہے\"۔","صحیح",{"u2":"سالم بن عبداللہ اپنے والد (عبداللہ بن عمر رضی اللہ عنہ) سے روایت کرتے ہیں کہ انہوں نے اپنی بیوی کو طلاق دے دی جبکہ وہ حیض سے تھی۔ سیدنا عمر رضی اللہ عنہ نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا۔ رسول اللہ صلی اللہ علیہ وسلم ناراض ہوئے پھر فرمایا ” اسے حکم دو کہ اس سے رجوع کرے، پھر اسے روکے رکھے حتیٰ کہ وہ پاک ہو جائے، پھر اسے حیض آئے اور پاک ہو۔ تب اگر چاہے تو اسے طلاق دے جبکہ وہ پاک ہو، مباشرت سے پہلے۔ یہی وہ عدت کے موقع پر طلاق ہے، جس کا اللہ تعالیٰ نے حکم دیا ہے۔ “"}],[2183,"ابن سیرین کہتے ہیں کہ مجھے یونس بن جبیر نے خبر دی کہ انہوں نے ابن عمر رضی اللہ عنہما سے دریافت کیا کہ آپ نے اپنی بیوی کو کتنی طلاق دی؟ تو انہوں نے کہا: ایک۔","صحیح",{"u2":"یونس بن جبیر کہتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا تھا کہ آپ نے اپنی بیوی کو کتنی طلاقیں دی تھیں؟ انہوں نے کہا: ایک۔","f2":"1۔ یہ احادیث سورۃالطلاق کی پہلی آیت کی تفسیر ہیں۔اللہ تعالی کا ارشاد:(فطلقوهن لعدتهن) (الطلاق:١) انھیں ان کی عدت کے موقع پر طلاق دو یعنی اس طہر کے ایام میں جن کی مباشرت نہ کی گئی ہو۔\n2۔ایام حیض میں طلاق دینا خلاف سنت اوربدعت ہے۔تاہم اگر کوئی ان ایام میں طلاق دےگا تو وہ واقع ہوجائے گی۔\n3۔ایسی صورت میں صاحب طلاق کو رجوع کا حکم دیا جائے گا (تاہم اگر کوئی ان ایام میں طلاق دےگا تو وہ واقع ہوجائے گی۔\n3۔ایسی صورت میں صاحب طلاق کو رجوع کا حکم دیا جائے گا (تاہم وہ ایک طلاق شمار ہوگی)اور رجوع کا حق صرف شوہر کو حاصل ہے ولی کو نہیں اور یہ رجوع واجب ہے\n4۔حمل کے ایام میں بھی طلاق ہوسکتی ہے۔\n5۔اور طلاق ایک ہی دینی چاہیے۔اور اس کی آخری روایت میں جواب ہےاس روایت کا جودارقطنی میں آئی ہےکہ ابن عمر رضی اللہ عنہ نے تین طلاقیں دی تھیں مگر وہ بالکل ضعیف ہے۔صحیح یہی ہے کہ انہوں نے ایک طلاق دی تھی۔\n6۔اور سب کے نزدیک طلاق کا صحیح طریقہ بھی یہی ہے کہ ایک ہی طلاق دی جائے نہ کہ بیک وقت تین طلاقیں۔بہ یک وقت تین طلاقیں دینا سب کے نزدیک سخت ناپسندیدہ اور ناجائز ہے نبی صلی اللہ علیہ وسلم نے بھی اس پر سخت ناراضی اور برہمی کا اظہار فرمایا ہے۔اگر طلاق دینے والے یہ طریقہ اختیار کرلیں تو اس مسئلے میں سرے سے اختلاف ہی پیدا ہو نہ حلالہ مروجہ جیسے لعنتی فعل کے اختیار کرنے ہی کی ضرورت پیش آئے۔کیونکہ ایک طلاق کی صورت میں سب کے نزدیک عدت کے اندر رجوع کرنااور عدت گزرنے کے بعد ان کے مابین دوبارہ نکاح کرنا جائز ہے۔دوسری مرتبہ طلاق میں بھی اسی طرح دونوں باتیں جائز ہیں۔اختلاف اس وقت پیدا ہوتا ہے جب طلاق دینے کا غیر شرعی طریقہ اختیار کیا جاتا ہےادر بہیک وقت تین طلاقیں دےدی جاتی ہیں۔اس صورت میں اہلحدیث کیتے ہیں کہ یہ ایک طلاق رجعی ہے کیونکہ ان کو بہ یک وقت نافذ کردینے میںاللہ کی وہ حکمت اورمنشاء فوت ہوجاتی ہےجو اللہ نے(الطلاق مرتان)میں بیان فرمائیہے۔اور دوسرے حضرات تین ہی باور کرکے ہمیشہ کے لئے جدائی کا یا پھر حلالہ مروجہ ملعونہ کا فتوی جاری کردیتے ہیں۔اس لیے اسلامی نظریاتی کونسل کی یہ سفارش بڑی اہم ہےکہ بہ یک وقت تین طلاقوں کو قابل تعزیر جرم قرار دیا جائے۔کاش اس پر عمل کی کوئی صورت پیدا ہو۔فی الحال کم ازکم یہ صورت اختیار کی جاسکتی ہے کہ تحریری طلاق میں خاوند اور طلاق نویس (وکیل وغیرہ)کو مجرم قرار دیا جائے اور اس کی کوئی تعزیری سزا بھی تجویز کی جائے۔یہ ایک قابل عمل صورت ہے اس کے اختیار کرنے سے امید ہے کہ آہستہ آہستہ لوگ گلط طریقہ طلاق سے باز آجائیں گے۔اللہ تعالی کسی حکومت کو اس اہم مسئلے کو اس طریقے سے حل کرنے کی توفیق عطا فرمائے۔آمین۔"}],[2184,"محمد بن سیرین کہتے ہیں کہ مجھے یونس بن جبیر نے بتایا کہ میں نے عبداللہ بن عمر رضی اللہ عنہما سے مسئلہ دریافت کیا، میں نے کہا کہ جس آدمی نے اپنی بیوی کو حالت حیض میں طلاق دے دی ہے (تو اس کا کیا حکم ہے؟) کہنے لگے کہ تم عبداللہ بن عمر رضی اللہ عنہما کو پہچانتے ہو؟ میں نے کہا: ہاں، تو انہوں نے کہا: عبداللہ بن عمر رضی اللہ عنہما نے اپنی بیوی کو حالت حیض میں طلاق دے دی تو عمر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر مسئلہ دریافت کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے حکم دو کہ وہ رجوع کر لے اور عدت کے آغاز میں اسے طلاق دے\"۔ میں نے پوچھا: کیا اس طلاق کا شمار ہو گا؟ انہوں نے کہا: تم کیا سمجھتے ہو اگر وہ عاجز ہو جائے یا دیوانہ ہو جائے ۱؎۔\n§وضاحت\n۱؎ : یعنی جب رجعت سے عاجز ہو جانے یا دیوانہ ہو جانے کی صورت میں بھی وہ طلاق شمار کی جائے گی تو رجعت کے بعد بھی ضرور شمار کی جائے گی اس حدیث سے معلوم ہوا کہ حیض کی حالت میں دی گئی طلاق واقع ہو جائے گی کیونکہ اگر وہ واقع نہ ہوتی تو آپ صلی اللہ علیہ وسلم کا «مره فليراجعها» کہنا بے معنی ہو گا، جمہور کا یہی مسلک ہے کہ اگرچہ حیض کی حالت میں طلاق دینا حرام ہے لیکن اس سے طلاق واقع ہو جائے گی اور اس سے رجوع کرنے کا حکم دیا جائے گا لیکن اہل ظاہر کا مذہب ہے کہ طلاق نہیں ہوگی ابن القیم نے زادالمعاد میں اس پر لمبی بحث کی ہے اور ثابت کیا ہے کہ طلاق واقع نہیں ہو گی، کیونکہ ابوداود کی اگلی حدیث کے الفاظ ہیں «ولم يرها شيئا» ۔","صحیح",{"u2":"یونس بن جبیر کہتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا کہ ایک آدمی نے اپنی بیوی کو طلاق دے دی جبکہ وہ ایام حیض میں تھی۔ تو انہوں نے کہا: تم ابن عمر کو جانتے ہو؟ میں نے کہا: ہاں۔ انہوں نے کہا کہ عبداللہ بن عمر رضی اللہ عنہ نے اپنی بیوی کو اس کے حیض کے دنوں میں طلاق دے دی۔ تو عمر رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم کے پاس آئے اور ان سے دریافت کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے حکم دو کہ اس سے رجوع کرے، پھر عدت کے شروع میں طلاق دے۔ “ یونس کہتے ہیں: میں نے کہا: کیا یہ طلاق شمار ہو گی؟ کہا: تو اور کیا؟ بھلا اگر وہ عاجز رہے (کہ صحیح حکم نہ معلوم کر سکے) یا احمق پن کا اظہار کرے (غلط طریقے سے طلاق دیدے؟ تو کیا اس کی یہ طلاق لغو جائے گی؟)۔","f2":"حیض کے ایام میں طلاق خلاف سنت ہے مگر شمار کی جائے گی۔لغو اور باطل نہیں ہے(تفصیل کیلئے دیکھئے: ارواءالغلیل حدیث:2059)"}],[2185,"ابن جریج کہتے ہیں کہ ہمیں ابوالزبیر نے خبر دی ہے کہ انہوں نے عروہ کے غلام عبدالرحمٰن بن ایمن کو ابن عمر رضی اللہ عنہما سے پوچھتے سنا اور وہ سن رہے تھے کہ آپ اس شخص کے متعلق کیا کہتے ہیں جس نے اپنی بیوی کو حالت حیض میں طلاق دیدی ہو؟ تو انہوں نے جواب دیا کہ عبداللہ بن عمر رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو حالت حیض میں طلاق دے دی، تو عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا، اور کہا کہ عبداللہ بن عمر نے اپنی بیوی کو حالت حیض میں طلاق دے دی ہے، عبداللہ رضی اللہ عنہ کہتے ہیں: تو آپ صلی اللہ علیہ وسلم نے اس عورت کو مجھ پر لوٹا دیا اور اس طلاق کو شمار نہیں کیا اور فرمایا: \"جب وہ پاک ہو جائے تو وہ طلاق دے یا اسے روک لے\"، ابن عمر رضی اللہ عنہما کہتے ہیں: اور نبی اکرم صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی «يا أيها النبي إذا طلقتم النساء فطلقوهن» \"اے نبی! جب تم لوگ عورتوں کو طلاق دو تو تم انہیں ان کی عدت کے شروع میں طلاق دو\" (سورۃ الطلاق: ۱) ۔ ابوداؤد کہتے ہیں: اس حدیث کو ابن عمر رضی اللہ عنہما سے یونس بن جبیر، انس بن سیرین، سعید بن جبیر، زید بن اسلم، ابوالزبیر اور منصور نے ابووائل کے طریق سے روایت کیا ہے، سب کا مفہوم یہی ہے کہ \"رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ وہ رجوع کر لیں یہاں تک کہ وہ پاک ہو جائے پھر اگر چاہیں تو طلاق دیدیں اور چاہیں تو باقی رکھیں\"۔ اسی طرح اسے محمد بن عبدالرحمٰن نے سالم سے، اور سالم نے ابن عمر رضی اللہ عنہما سے روایت کیا ہے البتہ زہری کی جو روایت سالم اور نافع کے طریق سے ابن عمر سے مروی ہے، اس میں ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ اس سے رجوع کر لیں یہاں تک کہ وہ پاک ہو جائے، پھر اسے حیض آئے اور پھر پاک ہو، پھر اگر چاہیں تو طلاق دیں اور اگر چاہیں تو رکھے رہیں، اور عطاء خراسانی سے روایت کیا گیا ہے انہوں نے حسن سے انہوں نے ابن عمر سے نافع اور زہری کی طرح روایت کی ہے، اور یہ تمام حدیثیں ابوالزبیر کی بیان کردہ روایت کے مخالف ہیں ۱؎۔\n§وضاحت\n۱؎ : یعنی کسی کی روایت میں یہ لفظ نہیں ہے کہ ’’اور اس طلاق کو شمار نہیں کیا‘‘","صحیح",{"u2":"عبدالرحمٰن بن ایمن مولیٰ عروہ نے سیدنا ابن عمر رضی اللہ عنہ سے سوال کیا اور ابوالزبیر سن رہے تھے، کہا کہ آپ کا اس شخص کے بارے میں کیا خیال ہے جس نے اپنی بیوی کو حیض کے دنوں میں طلاق دی ہو؟ انہوں نے کہا کہ عبداللہ بن عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اپنی بیوی کو حیض کے دنوں میں طلاق دے دی تھی۔ تو عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے کہا کہ عبداللہ بن عمر نے اپنی بیوی کو طلاق دے دی ہے حالانکہ وہ حیض سے ہے۔ تو عبداللہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے اس بیوی کو مجھ پر لوٹا دیا اور اسے کچھ نہ سمجھا۔ اور فرمایا ” جب یہ پاک ہو جائے تو پھر طلاق دے یا روک لے۔ “ ابن عمر رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے (اس طرح) پڑھا «يا أيها النبي إذا طلقتم النساء فطلقوهن في قبل عدتهن» ” اے نبی! جب تم اپنی عورتوں کو طلاق دینا چاہو تو انہیں ان کی عدت کے شروع میں طلاق دو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو یونس بن جبیر، انس بن سیرین، سعید بن جبیر، زید بن اسلم، ابوالزبیر اور منصور بواسطہ ابووائل نے ابن عمر رضی اللہ عنہ سے روایت کیا ہے۔ اور ان سب کی روایات کا مفہوم ایک ہی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اسے حکم دیا کہ رجوع کر لو حتیٰ کہ وہ پاک ہو جائے، پھر چاہو تو طلاق دے دو چاہو تو روک لو۔ امام ابوداؤد رضی اللہ عنہ نے کہا: ایسے ہی محمد بن عبدالرحمٰن نے بواسطہ سالم، ابن عمر رضی اللہ عنہ سے روایت کیا ہے۔ لیکن زہری (بواسطہ سالم) اور نافع کی روایات جو ابن عمر رضی اللہ عنہ سے ہیں ان میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کو رجوع کرنے کا حکم دیا حتیٰ کہ پاک ہو جائے، پھر حیض آئے پھر پاک ہو، پھر چاہے تو طلاق دیدے یا رکھ لے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: عطاء خراسانی سے بھی بواسطہ «الحسن، عن ابن عمر» اسی طرح روایت کی گئی ہے جیسے کہ نافع اور زہری نے روایت کی ہے۔ اور یہ سب روایات ابوالزبیر کے بیان کے خلاف ہیں۔","f2":"1۔ایام حیض کی طلاق سنت کے صریح خلاف ہے لیکن اگر کوئی دےدے تو اس کے واقع ہونے یانہ ہونےمیں متقدمین ومتاخرین میں ود رائیں رہی ہیں اور دونوں ہی طرف اجلہ علماء فقہاء اور محدثین کی جماعتیں ہیں۔رضي الله عنهم وارضاهم۔ متاخرین میں بالخصوص امام ابن تیمیہ اور ان کے تلمیذ رشید امام ابن قیم رحمہ اللہ نہایت شدت سے اس طلاق کے باطل ہونے کے قائل ہیں جبکہ جمہور اس کے وقوع کے قائل ہیں۔امام بخاری رحمہ اللہ نے الجامع الصحیح میں باب قائم کیا ہے(اذا طلقتم الحائض تعتد بذلك الطلاق) جب حائضہ کو طلاق دےدی جائے تو اس کی وہ طلاق شمار ہوگی اس موضوع میں لمبی بحثیں ہیںاور ان کا محور سیدنا ابن عمر رضی اللہ عنہ کی طلاق کا واقعہ ہے۔وہ کہتے ہیں حسبت علي بتطليقةٍ(صحيح بخاري الطلاق حديث:٥٢٥٣) یہ مجھ پر ایک طلاق شمار کی گئی تھی۔ اور ایک دوسرا جملہ جو ہماری اس روایت میں ہے:(ولم يرها شيئا) اور اسے کچھ نہ سمجھایا کچھ شمار نہ کیا۔ لیکن یہ جملہ عدم شمار کے لئے صریح نص نہیں ہے۔جیسے کہ امام شافعی یادیگر محدثین وفقہا نے اس کو محتمل قرار دیا ہے یعنی اس کا مفہوم یہ بھی ہوسکتا ہے کہ آپ صلی اللہ علیہ وسلم نے اس عمل کو درست اور صحیح نہ سمجھا۔ یا رجوع سے مانع نہ سمجھا وغیرہ۔محدث عصر علامہ البانی رحمہ اللہ نے اس موضوع کی مختلف احادیث کے اسانید ومتون میں تقابل میں کرتے ہوئے نتیجہ یہ نکالا ہےکہ ایام حیض کی طلاق واقع ہوجاتی ہے گو اس کے خلاف سنت ہونے میں بھی کوئی شبہ نہیں ہے۔\n2۔جس حیض میں طلاق دی اور پھر رجوع کرلیا اب اس سے متصل مطہر میں طلاق دے یا اس کے بعد والے طہر میں؟ امام ابوداود رحمہ اللہ نے اس حدیث کے کئی متابعات وشواہد پیش رکے یہ ثابت کیا ہےکہ متصل طہر میں طلاق دی جاسکتی ہے\nیعنی قبل از مباشرت۔مگر امام نافع اور زہری کی روایت میں ہے کہ ابن عمر رضی اللہ عنہ کو دوسرے طہر میں طلاق یا امساک کا حکم دیا گیا تھا۔اور یہ زیادت ثقہ ہے جو کہ پہلی صورت کے منافی نہیں اس لیے قابل قبول ہے۔اور اس کی تطویل کی کئی حکمتیں تھیں:\n(الف) معلوم ہوجائے کہ یہ رجوع محض دوسری طلاق کی خاطر نہ تھا۔\n(ب)عورت کے لیے واضح ہوجائے کہ اس کو کس کیفیت میں طلاق ہوئی ہے۔طہر میں یا حمل میں۔\n(ج) اگر حمل نمایاں ہوجائےتو شاید شوہر طلاق دینے میں متامل رہے۔\n5۔اور اس تطویلمسے یہ بہی ممکن ہے کہ ذہنوں میں پیدا ہونے والینا ہمواری ہم آہنگی میں بدل جائےاور شوہر اسے باقاعدہ بیوی بنالے۔\n3۔(والاحاديث كلها علي خلاف ماقابل ابوالزبير) اور تمام روایاتابوالزبیر کے بیان کے خلاف ہیں\nصاحب عون رحمہ اللہ نے اس سے مراد (ولم يرها شيئا) کا جملہ ہے یعنی یہ جملہ روایت کرنے میں ابوالزبیر منفرد ہیں۔"}],[2186,"مطرف بن عبداللہ سے روایت ہے کہ عمران بن حصین رضی اللہ عنہما سے اس شخص کے بارے میں پوچھا گیا جو اپنی بیوی کو طلاق دیدے پھر اس کے ساتھ صحبت بھی کر لے اور اپنی طلاق اور رجعت کے لیے کسی کو گواہ نہ بنائے تو انہوں نے کہا کہ تم نے سنت کے خلاف طلاق دی اور سنت کے خلاف رجعت کی، اپنی طلاق اور رجعت دونوں کے لیے گواہ بناؤ اور پھر اس طرح نہ کرنا۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ سے سوال کیا گیا کہ ایک آدمی اپنی بیوی کو طلاق دیتا ہے اور پھر اس سے مباشرت کر لیتا ہے مگر طلاق دینے یا اس سے رجوع کرنے پر گواہ نہیں بناتا۔ انہوں نے کہا: تو نے خلاف سنت طلاق دی اور خلاف سنت ہی رجوع کیا۔ بیوی کو طلاق دیتے وقت گواہ بناؤ اور رجوع کے وقت بھی۔ اور پھر ایسے نہ کرنا۔","f2":"سورۃالطلاق میں ہے: فاذا بلغن اجلهن فامسكوهن بمعروف اوفارقوهن بمعروف واشهدوا ذوي عدل منكم)(الطلاق:2) جب یہ عورتیں اپنی عدت پوری کرنے کے قریب پہنچ جائیں تو انہیں یا تو قاعدہ کے مطابق اپنے نکاح میں رکھویا دستور کے مطابق الگ کردو۔اور آپس میں سے دو عادل شخصوں کو گواہ کرلو اور طلاق اور رجوع میں گواہ بنالینا مستحب اور افضل ہے بالخصوص جب رجوع زبانی ہو۔رجوع بالفعل میں گواہ کے کوئی معنی نہیں"}],[2187,"بنی نوفل کے غلام ابوحسن نے ابن عباس رضی اللہ عنہما سے اس غلام کے بارے میں فتوی پوچھا جس کے نکاح میں کوئی لونڈی تھی تو اس نے اسے دو طلاق دے دی اس کے بعد وہ دونوں آزاد کر دیئے گئے، تو کیا غلام کے لیے درست ہے کہ وہ اس لونڈی کو نکاح کا پیغام دے؟ ابن عباس رضی اللہ عنہما نے کہا: ہاں رسول اللہ صلی اللہ علیہ وسلم نے اسی کا فیصلہ دیا ہے۔","ضعیف",{"u2":"ابوحسن مولیٰ بنی نوفل نے سیدنا ابن عباس رضی اللہ عنہ سے پوچھا کہ غلام جس کی زوجیت میں کوئی لونڈی ہو، وہ اسے دو طلاقیں دیدے، پھر وہ دونوں اس کے بعد آزاد ہو جائیں تو کیا اس آزاد غلام کے لیے روا ہے کہ وہ اس (اپنی پہلے والی بیوی، یعنی اس آزاد لونڈی) کو شادی کا پیغام دے؟ انہوں نے کہا: ہاں۔ رسول اللہ صلی اللہ علیہ وسلم نے اسی طرح فیصلہ فرمایا تھا۔"}],[2188,"عثمان بن عمر کہتے ہیں کہ ہمیں علی نے خبر دی ہے آگے سابقہ سند سے اسی مفہوم کی روایت مذکور ہے لیکن عنعنہ کے صیغے کے ساتھ ہے نہ کہ «أخبرنا» کے صیغے کے ساتھ، اس میں ہے کہ ابن عباس رضی اللہ عنہما نے کہا: تیرے لیے ایک طلاق باقی رہ گئی ہے، اللہ کے رسول اللہ صلی اللہ علیہ وسلم نے اسی کا فیصلہ فرمایا ہے۔ ابوداؤد کہتے ہیں: میں نے احمد بن حنبل کو کہتے سنا کہ عبدالرزاق کہتے ہیں کہ ابن مبارک نے معمر سے پوچھا کہ یہ ابوالحسن کون ہیں؟ انہوں نے ایک بھاری چٹان اٹھا لی ہے؟ ۱؎۔ ابوداؤد کہتے ہیں: ابوالحسن وہی ہیں جن سے زہری نے روایت کی ہے، زہری کہتے ہیں کہ وہ فقہاء میں سے تھے، زہری نے ابوالحسن سے کئی حدیثیں روایت کی ہیں۔ ابوداؤد کہتے ہیں: ابوالحسن معروف ہیں اور اس حدیث پر عمل نہیں ہے۔\n§وضاحت\n۱؎ : اس جملہ سے اس روایت میں جو کچھ ہے اس کا انکار مقصود ہے۔","ضعیف",{"u2":"جناب علی (علی بن مبارک) نے اپنی سند سے مذکورہ بالا حدیث کی مانند بیان کیا مگر «حدثني» کا صیغہ استعمال نہیں کیا (بلکہ «عن» کہا) سیدنا ابن عباس رضی اللہ عنہ نے کہا: تیرے لیے ایک ہی (طلاق) بچ گئی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے یہی فیصلہ کیا تھا۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں کہ میں نے امام احمد بن حنبل رضی اللہ عنہ کو سنا۔ انہوں نے کہا: عبدالرزاق نے بیان کیا کہ ابن مبارک نے معمر سے پوچھا یہ ابوالحسن کون ہے؟ اس نے بہت بڑا بھاری پتھر اٹھایا ہے۔ (یہ عدم اعتماد کا اظہار ہے۔) امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ ابوالحسن وہی ہے جس سے زہری روایت کرتے ہیں۔ زہری کہتے ہیں کہ یہ فقہاء میں سے تھا۔ اور زہری نے اس سے کئی احادیث روایت کی ہیں۔ امام ابوداؤد رضی اللہ عنہ نے کہا: ابوالحسن معروف ہے مگر اس حدیث پر عمل نہیں ہے۔"}],[2189,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"لونڈی کی طلاق دو ہیں اور اس کے قروء دو حیض ہیں\"۔ ابوعاصم کہتے ہیں: مجھ سے مظاہر نے بیان کیا وہ کہتے ہیں: مجھ سے قاسم نے انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مثل روایت کیا ہے، لیکن اس میں ہے کہ اس کی عدت دو حیض ہے۔ ابوداؤد کہتے ہیں: یہ مجہول حدیث ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نبی کریم صلی اللہ علیہ وسلم سے بیان کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” لونڈی کے لیے دو طلاقیں ہیں اور اس کے «قرؤ» (عدت) دو حیض ہے۔ “\nابوعاصم نے کہا: مجھے مظاہر نے بواسطہ قاسم، سیدہ عائشہ رضی اللہ عنہا ا سے اسی کے مثل روایت کیا مگر لفظ یہ تھے &laquo;وعدتها حيضتان&raquo;۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ مجہول حدیث ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ان دونوں حدیثوں پر عمل نہیں ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اس سند میں مظاہر نامی راوی معروف راوی نہیں ہے۔"}],[2190,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"طلاق صرف انہیں میں ہے جو تمہارے نکاح میں ہوں، اور آزادی صرف انہیں میں ہے جو تمہاری ملکیت میں ہوں، اور بیع بھی صرف انہیں چیزوں میں ہے جو تمہاری ملکیت میں ہوں\"۔ ابن صباح کی روایت میں اتنا زیادہ ہے کہ (تمہارے ذمہ) صرف اسی نذر کا پورا کرنا ہے جس کے تم مالک ہو۔","حسن",{"u2":"عمرو بن شعیب اپنے والد (شعیب) سے اور وہ اپنے دادا (عبداللہ بن عمرو رضی اللہ عنہ) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مالک بنے بغیر طلاق نہیں، مالک بنے بغیر آزاد کرنا نہیں، اور مالک بنے بغیر فروخت نہیں۔ “ ابن صباح نے یہ اضافہ بھی بیان کیا ” اور مالک بنے بغیر کسی نذر کا پورا کرنا نہیں۔ “"}],[2191,"اس سند سے بھی عبداللہ بن عمرو رضی اللہ عنہما سے اسی مفہوم کی روایت مروی ہے اس میں اتنا اضافہ ہے: \"جس نے گناہ کرنے کی قسم کھا لی تو اس قسم کا کوئی اعتبار نہیں نیز جس نے رشتہ توڑنے کی قسم کھا لی اس کا بھی کوئی اعتبار نہیں\"۔","حسن",{"u2":"عبدالرحمٰن بن حارث نے بواسطہ عمرو بن شعیب اس کی سند سے (عبداللہ بن عمرو رضی اللہ عنہما سے) مذکورہ بالا حدیث کے ہم معنی روایت کیا اور مزید کہا ” جس نے کسی معصیت اور گناہ کے کام پر قسم اٹھائی ہو، اس کی قسم نہیں، اور جس نے قطع رحمی کی قسم اٹھائی ہو، اس کی قسم نہیں۔ “"}],[2192,"اس سند سے بھی عبداللہ بن عمرو رضی اللہ عنہما سے یہی روایت آئی ہے اس میں اتنا اضافہ ہے کہ \"وہی نذر ماننا درست ہے جس کے ذکر سے اللہ تعالی کی رضا مقصود ہو\"۔","حسن"],[2193,"محمد بن عبید بن ابوصالح (جو ایلیاء میں رہتے تھے) کہتے ہیں کہ میں عدی بن عدی کندی کے ساتھ نکلا یہاں تک کہ میں مکہ آیا تو انہوں نے مجھے صفیہ بنت شیبہ کے پاس بھیجا، اور انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے حدیثیں یاد کر رکھی تھیں، وہ کہتی ہیں: میں نے عائشہ رضی اللہ عنہا کو کہتے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"زبردستی کی صورت میں طلاق دینے اور آزاد کرنے کا اعتبار نہیں ہو گا\"۔ ابوداؤد کہتے ہیں: میرا خیال ہے کہ غلاق کا مطلب غصہ ہے ۱؎۔\n§وضاحت\n۱؎ : اس باب کے الفاظ کی روایت تین طرح ہے: «على غيظ» ، «على غضب» ، «على غلطٍ» اور حدیث میں «غلاق» ،«إغلاق» جس کے معنی مؤلف نے غضب کے لئے ہیں ، حالانکہ کوئی بھی آدمی بغیر غیظ و غضب کے طلاق نہیں دیتا، اس طرح تو کوئی طلاق واقع ہی نہیں ہو گی ، اس لئے «إغلاق» کا معنی ’’زبردستی‘‘ لینا بہتر ہے ، اور تحقیقی بات یہی ہے کہ زبردستی لی گئی طلاق واقع نہیں ہوتی۔","حسن",{"u2":"محمد بن عبید بن ابی صالح جو ایلیاء (بیت المقدس) میں رہتے تھے کہتے ہیں کہ میں عدی بن عدی کندی کی معیت میں روانہ ہوا حتیٰ کہ ہم مکہ پہنچ گئے۔ پس انہوں نے مجھے صفیہ بنت شیبہ کے ہاں بھیجا۔ اس نے سیدہ عائشہ رضی اللہ عنہا ا سے (بہت کچھ) یاد کیا ہوا تھا۔ اس نے کہا کہ میں نے عائشہ رضی اللہ عنہا ا کو کہتے ہوئے سنا، وہ فرماتی تھیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” اغلاق میں طلاق نہیں اور نہ غلام کو آزاد کرنا ہے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں «الغلاق» (اور «الا غلاق») میرے خیال میں غضب اور غصے کے معنی میں ہے۔","f2":"کتب غریب الحدیث میں اغلاق کے معنی جبرواکراہ اور جنون کے بھی آئے ہیں۔اس حدیث میں مراد غصے کی وہ شدید کیفیت ہے جس میں انسان کو ہوش نہیں رہتا۔ورنہ عام حالات میں کوشی سے کوئی طلاق نہیں دیتا۔جبرواکراہ سے طلاق دلوائی جائے یا کوئی جنون کی کیفیت میں طلاق دے تو نافذ نہیں ہوتی۔غصے میں دے تو ہوجاتی ہے۔"}],[2194,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین چیزیں ایسی ہیں کہ انہیں چاہے سنجیدگی سے کیا جائے یا ہنسی مذاق میں ان کا اعتبار ہو گا، وہ یہ ہیں: نکاح، طلاق اور رجعت\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تین باتیں ایسی ہیں اگر کوئی ان کو حقیقت اور سنجیدگی میں کہے، تو حقیقت ہیں اور ہنسی مزاح میں کہے، تو بھی حقیقت ہیں۔ نکاح، طلاق اور (طلاق سے) رجوع۔ “","f2":"سورۃالبقرہ میں ہے:(واذا طلقتم النساء فبلغن اجلهن فامسكوهن بمعروف اوسرحوهن بمعروف ولا تمسكوهن ضرارالتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا آيت الله هزواً) البقره;٢٣١) جب تم عورتوں کو طلاق دواور وہ اپنی عدت ختم کرنے پر آئیں تواب انہیں اچھی طرح بسالویا بھلائی کے ساتھ الگ کردو اور انہیں تکلیف پہنچانے کی غرض سے ظلم اور زیادتی کے لیے نہ روکو۔اور جو شخص ایسا کرے اس نے اپنی جان پر ظلم کیا۔تم اللہ کے احکام کو ہنسی کھیل نہ بناؤ۔۔۔۔۔۔۔ قرآن مجید کی اس آیت میں طلاق کی بابت بعض اہم ہدایات دینے کے ساتھ آخر میں احکام الہی کو استہزاء ومذاق بنانے سے منع فرمایا گیا ہے۔انہی احکام میں نکاح و طلاق وعتاق بھی ہیں۔ان کی بابت حدیث میں واضح کیا گیا ہے کہ یہ کام اگر مذاق میں بھی کئے جائیں گے تو واقعتاً ان کا انعقاد ہوجائے گا۔اس سے یہ معلو م ہوتا ہے کہ ڈراموں ادر فلموں میں فرضی طور پر میاں بیوی کا کردار ادا کرنا کیوں کر صحیح ہوگا؟ کیونکہ اس طرح اندیشہ ہے کہ وہ دونوں اللہ کے ہاں میاں بیوی ہی مقصود ہوں جب کہ وہ ایسا سمجھتے ہوں نہ اس کے مطابق باہم معاملہ ہی کرتے ہوں۔"}],[2195,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں اللہ تعالی کا فرمان ہے «والمطلقات يتربصن بأنفسهن ثلاثة قروء ولا يحل لهن أن يكتمن ما خلق الله في أرحامهن» \"اور جن عورتوں کو طلاق دے دی گئی ہے وہ تین طہر تک ٹھہری رہیں اور ان کے لیے حلال نہیں کہ اللہ تعالی نے ان کے رحم میں جو پیدا کر دیا ہے اسے چھپائیں\" (سورۃ البقرہ: ۲۲۸) یہ اس وجہ سے کہ جب آدمی اپنی بیوی کو طلاق دے دیتا تھا تو رجعت کا وہ زیادہ حقدار رہتا تھا گرچہ اس نے تین طلاقیں دے دی ہوں پھر اسے منسوخ کر دیا گیا اور ارشاد ہوا «الطلاق مرتان»یعنی طلاق کا اختیار صرف دو بار ہے۔","حسن صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ آیت کریمہ «والمطلقات يتربصن بأنفسهن ثلاثة قروء ولا يحل لهن أن يكتمن خلق الله في أرحامهن» ” طلاق والی عورتیں اپنے آپ کو تین حیض تک روکے رکھیں اور انہیں حلال نہیں کہ وہ وہ چیز چھپا لیں جو اللہ نے ان کے رحموں میں پیدا کی ہے۔ “ اس کی تفسیر میں بیان کیا کہ آدمی جب اپنی بیوی کو طلاق دیتا تھا تو وہی اس کی طرف رجوع کرنے کا زیادہ حقدار سمجھا جاتا تھا، خواہ تین طلاقیں ہی دے چکا ہوتا۔ اس کو منسوخ کر دیا گیا اور فرمایا «الطلاق مرتان» ” (قابل رجوع) طلاق دو بار ہے۔ “","f2":"طلاق کے سلسلے میں ہدایات کے نزول سے پہلے لوگ طلا ق دیتے اور رجوع کرتے رہتے تھے اور طلاقوں کی کوئی حد اور تعداد نہ تھی۔قرآن مجید نے انہیں صرف تین تک محدود کردیا ہے دو قابل رجوع ہیں اور تیسری پر رجوع نہیں ہوسکتا۔"}],[2196,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رکانہ اور اس کے بھائیوں کے والد عبد یزید نے رکانہ کی ماں کو طلاق دے دی، اور قبیلہ مزینہ کی ایک عورت سے نکاح کر لیا، وہ عورت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور اپنے سر سے ایک بال لے کر کہنے لگی کہ وہ میرے کام کا نہیں مگر اس بال برابر لہٰذا میرے اور اس کے درمیان جدائی کرا دیجئیے، یہ سن کر آپ صلی اللہ علیہ وسلم کو غصہ آ گیا، آپ نے رکانہ اور اس کے بھائیوں کو بلوا لیا، پھر پاس بیٹھے ہوئے لوگوں سے پوچھا کہ: \"کیا فلاں کی شکل اس اس طرح اور فلاں کی اس اس طرح عبد یزید سے نہیں ملتی؟\"، لوگوں نے کہا: ہاں (ملتی ہے)، نبی اکرم صلی اللہ علیہ وسلم نے عبد یزید سے فرمایا:\"اسے طلاق دے دو\"، چنانچہ انہوں نے طلاق دے دی، پھر فرمایا: \"اپنی بیوی یعنی رکانہ اور اس کے بھائیوں کی ماں سے رجوع کر لو\"، عبد یزید نے کہا: اللہ کے رسول میں تو اسے تین طلاق دے چکا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے معلوم ہے، تم اس سے رجوع کر لو\"، اور آپ صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی «يا أيها النبي إذا طلقتم النساء فطلقوهن لعدتهن» (سورۃ الطلاق: ۱) \"اے نبی! جب تم عورتوں کو طلاق دو تو ان کی عدت میں طلاق دو\"۔ ابوداؤد کہتے ہیں: نافع بن عجیر اور عبداللہ بن علی بن یزید بن رکانہ کی حدیث جسے انہوں نے اپنے والد سے انہوں نے اپنے دادا سے روایت (حدیث نمبر: ۲۲۰۶) کیا ہے کہ رکانہ نے اپنی بیوی کو طلاق بتہ دے دی، پھر بھی نبی اکرم صلی اللہ علیہ وسلم نے اس سے رجوع کرا دیا، زیادہ صحیح ہے کیونکہ رکانہ کے لڑکے اور ان کے گھر والے اس بات کو اچھی طرح جانتے تھے کہ رکانہ نے اپنی بیوی کو طلاق بتہ دی تھی تو نبی اکرم صلی اللہ علیہ وسلم نے اسے ایک ہی شمار کیا ۱؎۔\n§وضاحت\n۱؎ : یہ حدیث حسن ہے، اور مؤلف نے جس حدیث (نمبر: ۲۲۰۶) کی طرف اشارہ کیا ہے وہ ضعیف ہے، نیز اولاد رکانہ واقعہ کے بیان میں خود مضطرب ہیں، یاد رہے کہ عہد نبوی میں ’’تین طلاق‘‘ اور ’’طلاقہ بتہ ‘‘ ہم معنی الفاظ تھے، عہد نبوی و عہد صحابہ کے بعد لوگوں نے ’’طلاق بتہ‘‘ کا یہ معنی بنا دیا کہ جس میں ایک دو، تین طلاق دہندہ کی نیت کے مطابق طے کیا جائیگا (تفصیل کے لے دیکھئے تنویر الآفاق)","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہعبد یزید جو رکانہ اور اس کے بھائیوں کا والد تھا۔ اس نے ام رکانہ کو طلاق دے دی اور قبیلہ مزینہ کی ایک عورت سے نکاح کر لیا۔ پھر یہ (مزنی عورت) نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہا: یہ میرے کام کا نہیں، جیسے یہ بال، اور اس نے اپنے سر سے بال پکڑ کر اشارہ کیا (یعنی نامرد ہے)، آپ صلی اللہ علیہ وسلم میرے اور اس کے درمیان علیحدگی کرا دیں۔ اس پر نبی کریم صلی اللہ علیہ وسلم کو غصہ آیا اور پھر رکانہ اور اس کے بھائیوں کو بلوایا، اور حاضرین سے کہا: ” کیا دیکھتے ہو کہ فلاں بچہ اس سے کس قدر مشابہ ہے۔ “ یعنی عبد یزید کے ساتھ ” اور فلاں اس سے کتنا مشابہ ہے۔ “ سب نے کہا کہ جی ہاں (یعنی جب پہلے اس کی اولاد موجود ہے تو اس عورت کا دعوہ کس طرح صحیح ہو سکتا ہے) تو نبی کریم صلی اللہ علیہ وسلم نے عبد یزید سے فرمایا ” اس کو طلاق دے دو۔ “ چنانچہ اس نے (طلاق) دے دی۔ اور فرمایا ” اپنی (پہلی) بیوی سے جو رکانہ اور اس کے بھائیوں کی ماں ہے، رجوع کر لو۔ “ وہ کہنے لگا: اے اللہ کے رسول! میں نے اسے تین طلاقیں دی ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” مجھے معلوم ہے، اس لے رجوع کر لو۔ “ اور یہ آیت تلاوت فرمائی «يأيها النبي إذا طلقتم النساء فطلقوهن لعدتهن» ” اے نبی! جب تم عورتوں کو طلاق دینا چاہو تو عدت کے وقت طلاق دیا کرو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ نافع بن عجیر اور عبداللہ بن علی بن یزید بن رکانہ کی روایت ہے کہ رکانہ نے اپنی بیوی کو طلاق بتہ دی تھی تو نبی کریم صلی اللہ علیہ وسلم نے اس کی بیوی کو اس پر لوٹا دیا تھا، یہ روایت زیادہ صحیح ہے، کیونکہ یہ اس آدمی کی اولاد ہیں اور گھر والے اس کے متعلق زیادہ باخبر ہو سکتے ہیں، یعنی رکانہ نے اپنی بیوی کو طلاق بتہ دی اور رسول اللہ صلی اللہ علیہ وسلم نے اس کو ایک بنا دیا۔","f2":"1۔ یہ حدیث ضعیف ہے۔تاہم بعض محقیقین کے نزدیک یہ حسن درجہ کی ہے۔(اس کی بحث کے لیے دیکھے ارواء الغلیل 1447اوما قبلہ) اور محولہ احادیث آگے آرہی ہیں۔2208۔2206)\n2۔طلاق بتہ: یعنی ایسی طلاق جس میں رجوع کا حق کٹ جائے۔بت يبت بتاً یعنی کاٹ دینا؛ٹکرے ٹکرے کردینا۔\n3۔عہد رسالت میں طلاق بتہ کا لفظ ایک ہی مرتبہ تین طلاقیں دینے کے مفہوم میں استعمال ہوتا تھا۔اعتبار سے بیک وقت تین طلاقیں یا طلاق بتہ دونوں کا مطلب ایک ہی ہے۔یہی وجہ ہے کہ اس حدیث میں صراحت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس(طلاق بتہ)کو ایک بنادیا۔ورنہ بعد میں طلاق بتہ کا جو مفہوم رائج ہوا اس کی رو سے تو اسے کسی صورت بہی ایک طلاق نہیں بنایا جاسکتا تھا۔"}],[2197,"مجاہد کہتے ہیں: میں ابن عباس رضی اللہ عنہما کے پاس تھا کہ ایک آدمی آیا اور ان سے کہنے لگا کہ اس نے اپنی بیوی کو تین طلاق دے دی ہے، ابن عباس رضی اللہ عنہما خاموش رہے، یہاں تک کہ میں نے سمجھا کہ وہ اسے اس کی طرف لوٹا دیں گے، پھر انہوں نے کہا: تم لوگ بیوقوفی تو خود کرتے ہو پھر آ کر کہتے ہو: اے ابن عباس! اے ابن عباس! حالانکہ اللہ تعالی کا فرمان ہے «ومن يتق الله يجعل له مخرجا» ۱؎ اور تو اللہ سے نہیں ڈرا لہٰذا میں تیرے لیے کوئی راستہ بھی نہیں پاتا، تو نے اپنے پروردگار کی نافرمانی کی لہٰذا تیری بیوی تیرے لیے بائنہ ہو گئی، اللہ تعالی نے فرمایا ہے «يا أيها النبي إذا طلقتم النساء فطلقوهن» ، «في قبل عدتهن» ۲؎۔ ابوداؤد کہتے ہیں: اس حدیث کو حمید اعرج وغیرہ نے مجاہد سے، مجاہد نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔ اور اسے شعبہ نے عمرو بن مرہ سے عمرو نے سعید بن جبیر سے سعید نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔ اور ایوب و ابن جریج نے عکرمہ بن خالد سے عکرمہ نے سعید بن جبیر سے سعید نے ابن عباس رضی اللہ عنہما سے، اور ابن جریج نے عبدالحمید بن رافع سے ابن رافع نے عطاء سے عطاء نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔ نیز اسے اعمش نے مالک بن حارث سے مالک نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے اور ابن جریج نے عمرو بن دینار سے عمرو نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے۔ ان سبھوں نے تین طلاق کے بارے میں کہا ہے کہ ابن عباس رضی اللہ عنہما نے ان کو تین ہی مانا اور کہا کہ وہ تمہارے لیے بائنہ ہو گئی جیسے اسماعیل کی روایت میں ہے جسے انہوں نے ایوب سے ایوب نے عبداللہ بن کثیر سے روایت کیا ہے۔ ابوداؤد کہتے ہیں: اور حماد بن زید نے ایوب سے ایوب نے عکرمہ سے عکرمہ نے ابن عباس رضی اللہ عنہما سے روایت کی ہے کہ جب ایک ہی منہ سے (یکبارگی یوں کہے کہ تجھے تین طلاق دی) تو وہ ایک شمار ہو گی۔ اور اسے اسماعیل بن ابراہیم نے ایوب سے ایوب نے عکرمہ سے روایت کیا ہے اور یہ ان کا اپنا قول ہے البتہ انہوں نے ابن عباس کا ذکر نہیں کیا بلکہ اسے عکرمہ کا قول بتایا ہے۔\n§وضاحت\n۱؎ : جو شخص اللہ تعالی سے ڈرتا ہے ، وہ اس کے لئے راستہ نکال دیتا ہے۔ ۲؎ : اے نبی! جب تم عورتوں کو طلاق دو تو انہیں ان کی عدت کے شروع میں دو۔","صحیح",{"u2":"مجاہد کہتے ہیں کہ میں سیدنا ابن عباس رضی اللہ عنہ کے پاس بیٹھا تھا کہ ایک شخص ان کے پاس آیا اور کہنے لگا کہ میں نے اپنی بیوی کو تین طلاقیں دے دی ہیں۔ چنانچہ وہ خاموش ہو رہے حتیٰ کہ مجھے گمان ہوا کہ وہ اس عورت کو اس پر واپس کر دیں گے۔ (رجوع کرنے کا فتوی دے دیں گے۔) پھر بولے: تم میں ایک اٹھتا ہے اور حماقت کا ارتکاب کرتا ہے، پھر کہتا ہے: ابن عباس! ابن عباس! تحقیق اللہ تعالیٰ نے فرمایا ہے «ومن يتق الله يجعل له مخرجا» ” جو اللہ کا تقویٰ اختیار کرے، اللہ اس کے لیے نکلنے کی راہ بھی پیدا فر دیتا ہے۔ “ تو نے اللہ کا تقویٰ اختیار نہیں کیا، لہٰذا میں تیرے لیے کوئی راہ نہیں پاتا۔ تو نے اپنے رب کی نافرمانی کی اور بیوی تجھ سے جدا ہو گی۔ اور اللہ عزوجل نے فرمایا ہے «يأيها النبي إذا طلقتم النساء فطلقوهن سورة الطلاق آية 1 في قبل عدتهن» ” اے نبی! جب تم عورتوں کو طلاق دینا چاہو تو انہیں ان کی عدت کے شروع میں طلاق دو۔ “ (اس سند کی متابعات کا بیان) (1) امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس حدیث کو (الف) حمید اعرج وغیرہ نے بواسطہ مجاہد، ابن عباس رضی اللہ عنہ روایت کیا ہے۔ (ب) شعبہ نے عمرہ بن مرہ سے بواسطہ سعید بن جبیر، ابن عباس رضی اللہ عنہ سے روایت کیا ہے۔ (ج) ایوب اور ابن جریج نے عکرمہ بن خالد سے بواسطہ سعید بن جبیر، ابن عباس روایت کیا ہے۔ (د) ابن جریج نے عبدالحمید بن رافع سے بواسطہ عطاء، ابن عباس روایت کیا ہے۔ (ھ) اعمش نے بواسطہ مالک بن حارث، ابن عباس روایت کیا ہے (و) ابن جریج نے بواسطہ عمرو بن دینار، ابن عباس روایت کیا ہے۔ یہ سب روایت کرتے ہیں کہ ابن عباس رضی اللہ عنہ نے تین طلاق کو نافذ کیا اور کہا: عورت تجھ سے (بائنہ) جدا ہو گئی جیسے کہ «إسماعيل عن أيوب عن عبد الله بن كثير» کی سند میں آیا ہے۔ (2) امام ابوداؤد رضی اللہ عنہ نے کہا کہ حماد بن زید ایوب سے بواسطہ عکرمہ، ابن عباس روایت کرتے ہیں کہ جب کہنے والے نے ایک ہی مرتبہ کہا کہ “ تجھے تین طلاق ہے “ تو یہ ایک طلاق ہے۔ اور اسماعیل بن ابراہیم نے ایوب سے بواسطہ عکرمہ اسے نقل کیا تو ابن عباس کا نام نہیں لیا بلکہ اس کو عکرمہ کا قول بنایا ہے۔"}],[2198,"ابوداؤد کہتے ہیں: ابن عباس رضی اللہ عنہما کا قول اگلی والی حدیث میں ہے جسے محمد بن ایاس نے روایت کیا ہے کہ ابن عباس، ابوہریرہ اور عبداللہ بن عمرو بن العاص رضی اللہ عنہم سے باکرہ (کنواری) کے بارے میں جسے اس کے شوہر نے تین طلاق دے دی ہو، دریافت کیا گیا تو ان سب نے کہا کہ وہ اپنے اس شوہر کے لیے اس وقت تک حلال نہیں ہو سکتی، جب تک کہ وہ کسی اور سے نکاح نہ کر لے۔ ابوداؤد کہتے ہیں: اور مالک نے یحیی بن سعید سے یحیی نے بکیر بن اشبح سے بکیر نے معاویہ بن ابی عیاش سے روایت کیا ہے کہ وہ اس واقعہ میں موجود تھے جس وقت محمد بن ایاس بن بکیر، ابن زبیر اور عاصم بن عمر کے پاس آئے، اور ان دونوں سے اس کے بارے میں دریافت کیا تو ان دونوں نے ہی کہا کہ تم ابن عباس اور ابوہریرہ رضی اللہ عنہما کے پاس جاؤ میں انہیں ام المؤمنین عائشہ رضی اللہ عنہا کے پاس چھوڑ کر آیا ہوں، پھر انہوں نے یہ پوری حدیث بیان کی۔ ابوداؤد کہتے ہیں: اور ابن عباس رضی اللہ عنہما کا یہ قول کہ تین طلاق سے عورت اپنے شوہر کے لیے بائنہ ہو جائے گی، چاہے وہ اس کا دخول ہو چکا ہو، یا ابھی دخول نہ ہوا ہو، اور وہ اس کے لیے اس وقت تک حلال نہ ہو گی، جب تک کہ کسی اور سے نکاح نہ کر لے اس کی مثال «صَرْف» والی حدیث کی طرح ہے ۱؎ اس میں ہے کہ پھر انہوں یعنی ابن عباس نے اس سے رجوع کر لیا۔\n§وضاحت\n۱؎ : یعنی جس طرح وہ نقدی کو نقدی سے بیچنے کے متعلق کہتے تھے کہ اس میں ربا صرف ادھار کی صورت میں ہے نقد کی صورت میں نہیں پھر انہوں نے اس سے رجوع کر لیا تھا اسی طرح یہ معاملہ بھی ہے اس سے بھی انہوں نے بعد میں رجوع کر لیا تھا۔","صحیح",{"u2":"امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سیدنا ابن عباس رضی اللہ عنہ کا یہ فتویٰ بدل گیا تھا جیسے کہ ہمیں احمد بن صالح اور محمد بن یحییٰ نے بیان کیا اور یہ روایت احمد بن صالح کی ہے اور ان دونوں کی سند یوں ہے «حدثنا عبد الرزاق،‏‏‏‏ عن معمر،‏‏‏‏ عن الزهري،‏‏‏‏ عن أبي سلمة بن عبد الرحمن بن عوف» (دوسری سند) «محمد بن عبد الرحمن بن ثوبان،‏‏‏‏ عن محمد بن إياس،‏‏‏‏ أن ابن عباس،‏‏‏‏ ‏‏‏‏ وأبا،‏‏‏‏ هريرة وعبد الله بن عمرو بن العاص» محمد بن عبدالرحمٰن بن ثوبان، محمد بن ایاس سے بیان کرتے ہیں کہ حضرات ابن عباس، ابوہریرہ اور عبداللہ بن عمرو بن العاص رضی اللہ عنہ م سے سوال کیا گیا کہ کنواری لڑکی کو اگر اس کا شوہر تین طلاقیں دیدے (قبل از مباشرت) تو؟ سب نے کہا کہ یہ شوہر کے لیے حلال نہیں حتیٰ کہ کسی اور سے نکاح کرے۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ امام مالک رضی اللہ عنہ نے بہ سند «يحيى بن سعيد عن بكير بن الأشج عن معاوية بن أبي عياش» روایت کیا (معاویہ نے کہا) کہ میں اس قصے کا گواہ ہوں، محمد بن ایاس بن بکیر، ابن الزبیر اور عاصم بن عمر کے پاس آیا اور ان دونوں سے اس بارے میں سوال کیا تو انہوں نے کہا کہ ابن عباس اور ابوہریرہ رضی اللہ عنہ م کے پاس چلے جاؤ، میں نے ان کو عائشہ رضی اللہ عنہا ا کے ہاں چھوڑا ہے۔ پھر یہ قصہ بیان کیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابن عباس رضی اللہ عنہ کا یہ قول کہ عورت تین طلاق سے اپنے شوہر سے بائنہ (جدا) ہو جاتی ہے، خواہ شوہر نے اس سے مباشرت کی ہو یا نہ کی ہو، وہ اس کے لیے حلال نہیں رہتی جب تک کہ کسی اور سے نکاح نہ کر لے۔ ان کا یہ فتویٰ ایسے ہی ہے جیسے کہ انہوں نے بیع صرف (سونے چاندی کی بیع) کے بارے میں فتویٰ دیا تھا، پھر ابن عباس رضی اللہ عنہ نے اپنے اس فتویٰ سے رجوع کر لیا تھا۔","f2":"سیدنا ابن عباس رضی اللہ عنہ سے تین طلاق کے مسئلے میں دو قول وارد ہیں جیسے کہ بیع صرف(سونے چاندی کی بیع) میں پہلے وہ ایک درہم کے بدلے دو درہم اور ایک دینار کے بدلے دو دینار لینا دینا(نقد میں) جائز سمجھتے تھے پھر جب انہیں اس بیع کی نہی کی موثوق کبر مل گئی تو انہوں نے اپنا فتوی بدل لیااور اس کے ناجائز ہونے کا فتوی دینے لگے۔اسی طرح اس مسئلہ طلاق میں بھی ان کے دو قول ہیں:ایک یہ کہل تین طلاق کے لفظ سے طلاق ہوجاتی ہے(یعنی تین)\nاور اکثر روایات اسی طرح ہیں اور دوسرا یہ کہ واقع نہیں ہوتی(بلکہ ایک ہوتی ہے) جیسے کہ عکرمہ نے ان سے روایات کیا ہے۔اور یہی صحیح ہے باوجودیکہ اس کے برعکس کی اسانید زیادہ ہیں۔طاؤس کی ان سے مرفوع روایات اسی کی مؤید ہےاور اسی کو اختیار کرنا ہمارے نزدیک واجب ہےکیونکہ یہ حدیث کئی ایک اسانید سے ان سے ثابت ہےامام ابن تیمیہ اور ان کے تلمیذرشیدابن قیم رحمہ اللہ اور بعض دیگر علماءاسی کے قائل ہیں۔(ماخوذاز ارواءالغلیل:1227)"}],[2199,"طاؤس سے روایت ہے کہ ایک صاحب جنہیں ابوصہبا کہا جاتا تھا ابن عباس رضی اللہ عنہما سے کثرت سے سوال کرتے تھے انہوں نے پوچھا: کیا آپ کو معلوم ہے کہ جب آدمی اپنی بیوی کو دخول سے پہلے ہی تین طلاق دے دیتا، تو رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے زمانے نیز عمر رضی اللہ عنہ کے ابتدائی دور خلافت میں اسے ایک طلاق مانا جاتا تھا؟ ابن عباس رضی اللہ عنہما نے جواب دیا: ہاں کیوں نہیں؟ جب آدمی اپنی بیوی کو دخول سے پہلے ہی تین طلاق دے دیتا تھا، تو اسے رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے زمانے میں نیز عمر رضی اللہ عنہ کے ابتدائی دور خلافت میں ایک ہی طلاق مانا جاتا تھا، لیکن جب عمر رضی اللہ عنہ نے دیکھا کہ لوگ بہت زیادہ ایسا کرنے لگے ہیں تو کہا کہ میں انہیں تین ہی نافذ کروں گا ۱؎۔\n§وضاحت\n۱؎ : مگر عمر رضی اللہ عنہ کا یہ حکم واجب العمل نہیں ہو سکتا ، کیونکہ حدیث صحیح سے رسول اکرم صلی اللہ علیہ وسلم کے عہد مبارک میں تین طلاق کا ایک طلاق ہونا ثابت ہے۔","ضعیف",{"u2":"طاؤس کہتے ہیں کہ ابو الصہباء نامی ایک شخص سیدنا ابن عباس رضی اللہ عنہ سے بہت زیادہ سوال کیا کرتا تھا۔ اس نے کہا: کیا آپ کو علم ہے کہ جب کوئی آدمی اپنی بیوی کو مباشرت سے پہلے تین طلاقیں دے دیتا تھا تو ایسی طلاق کو رسول اللہ صلی اللہ علیہ وسلم، ابوبکر رضی اللہ عنہ اور اوائل دور عمر رضی اللہ عنہ میں ایک ہی بنایا (شمار) کرتے تھے؟ ابن عباس رضی اللہ عنہ نے کہا: ہاں! آدمی جب اپنی بیوی کو مباشرت سے پہلے تین طلاقیں دے دیتا تھا تو عہد رسالت، عہد ابی بکر اور ابتدائے عہد عمر میں اس کو ایک ہی بنا دیتے تھے۔ عمر نے جب دیکھا کہ لوگ مسلسل طلاقیں دینے لگے ہیں تو انہوں نے کہا: انہیں ان پر نافذ کر دو۔","f2":"اس روایت میں(قبل ان يدخل بها) قبل ازمباشرت کا اضافہ منکر ہے۔تفصیلی بحث کے لیے دیکھیے(سلسلہ الاحادیث الضعیفۃ ج؛11343) صحیح مسلم کی روایت کے الفاظ انتہائی صریح اور صاف ہیں (كان الطلاق علي عهد رسول الله صلی اللہ علیہ وسلم وابي بكر وسنتين من خلافة عمر طلاق الثلاث واحدة فقال عمر بن خطاب:ان الناس قداستعجلو في امر قد كانت لهم فيه اناة فلوا مضيناه عليهم فامضاه عليهم) (صحيح مسلم الطلاق حديث:١٤٧٤)\nرسول الله صلی اللہ علیہ وسلم کے زمانے میں عہد ابی بکر رضی اللہ عنہ اور خلافت عمر کے ابتدائی دو سالوں میں تین طلاقیںصایک ہی ہوا کرتی تھی تو عمر بن خطاب نے کہا:لوگ اس معاملہ (طلاق) میں جس میں انہیں مہلت حاصل تھی جلدی کرنے لگے ہیں۔اگر ہم (ان کی تین طلاقوں کو تین طلاقیں ہی) نافذ کردیں (تو بہتر رہے) چنانچہ انہوں نے اس کو نافذ کردیا۔ علامہ البانی رحمہ اللہ لکھتے ہیں:اس حدیث میں مدخولہ اور غیر مدخولہ کی کوئی قید نہیں۔یہ نص ناقابل انکار ہے انتہائی محکم اور ثابت ہے منسوخ نہیں ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کے بعد خلافت صدیق رضی اللہ عنہ کےبعد خلافت صدیق رضی اللہ عنہ اور اوائل دور عمر رضی اللہ عنہ میں اسی عمل ہوتا رہا ہے اور سیدنا عمر رضی اللہ عنہ نے اس کی مخالفت اس کے بالمقابل کسی نص سے نہیں بلکہ اپنے اجتہاد سے کی تھی اور یہی وجہ تھی کہ قبل از نفاذانہیں ترددواضطراب رہا تھا۔اور مصر اور شام وغیرہ میں جب اس حکم کو قانون کا حصہ بنایا گیا ہے تو اتباع سنت اور احیائے سنت کی غرض سے نہیں بلکہ بربنائے مصلحت اور ابن تیمیہ کی تقلید میں ایسا کیا گیاہےتو اتباع سنت اور احیائے سنت کی غرض سے نہیں بلکہ بربنائے مصلحت اور ابن تیمیہ کی تقلید میں ایسا کیا گیاہے۔ کاش کہ یہ لوگ اپنی عبادات ومعاملات میں سنت کی اتباع کو پیش نظر رکھیں۔(ملحوظہ) مترجم عرض کرتا ہے برصغیر میں بھی یہی صورت حال ہے کہ لوگ اپنی ذاتی مصالح کے پیش نظر ان احادیث کے مطابق فتوی ھاصل کرنے کے لیے کوشاں ہوتے ہیں نہ کہ اتباع سنت کی غرض سے۔فالي الله المشتكيّ"}],[2200,"طاؤس سے روایت ہے کہ ابوصہباء نے ابن عباس رضی اللہ عنہما سے پوچھا: کیا آپ کو معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ کے زمانے میں نیز عمر رضی اللہ عنہ کے دور خلافت کے ابتدائی تین سالوں میں تین طلاقوں کو ایک ہی مانا جاتا تھا؟ ابن عباس رضی اللہ عنہما نے جواب دیا: ہاں ۱؎۔","Sahih (Al-Albani); Sahih (Muhammad Muhyi Al-Din Abdul Hamid); Sahih Muslim (1472) (Zubair Ali Zai)",{"u2":"ابن طاؤس اپنے والد سے بیان کرتے ہیں کہ ابو الصہباء نے سیدنا ابن عباس رضی اللہ عنہ سے کہا: کیا آپ جانتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے زمانے میں، ابوبکر رضی اللہ عنہ کے عہد اور عمر رضی اللہ عنہ کی امارت کے ابتدائی تین سال تک تین طلاقوں کو ایک بنایا (شمار) کیا جاتا تھا؟ تو ابن عباس رضی اللہ عنہ نے کہا: ہاں!۔","f2":"امت کے لیےحجت شرعیہ صرف اور صرف نبی صلی اللہ علیہ وسلم کا دور ہے۔جبکہ شریعت نازل ہوئی اور مکمل ہوگئی۔اور امام مالک رحمہ اللہ کا یہ قول قول فیصل ہے۔(لن يصلح آخر هذه الامة الا ما صلح به اولها) اس امت کا آخری دور اسی سے اصلاح پذیر ہوگا جس ذریعے سے اس کے اول کی اصلاح ہوئی تھی۔\n2۔اس حدیث سے واضح ہے کہ عہد رسالت عہد ابی بکر اور عہد سیدنا عمر رضی اللہ عنہ کے ابتدائی دور میں ایک مجلس کی تین طلاقوں کو ایک ہی طلاق شمار کیا جاتاتھا۔اس لیے یہ مسلک صحیح ہے۔علاوہ ازیں عوام کی جہالت کا حل بھی یہی ہے؛وہ طلاق کے صحیح طریقے سے بے خبر ہونے کی وجہ سے بیک وقت تین طلاقیں دےدیتے ہیں(حالانکہ ایسا کرنا سخت منع ہے) پھر پچھتاتے ہیں۔اس کا حل یہی ہے کہ اسے ایک طلاق شمار کیا جائے اور اسے رجوع کا حق دیا جائے۔آج کل کے متعدد علمائے احناف نے بھی اس موقف کی تائید کی ہے۔جس کی تفصیل ایک مجلس کی تین طلاقیں نامی کتاب میں ملاحظہ کی جاسکتی ہے۔اسی طرح یہ مبحث عورتوں کے امتیازی مسائل وقوانین تالیف:حافظ صلاح الدین یوسف مطبوعہ دار السلام میں بھی ضروری حد تک موجود ہے۔"}],[2201,"علقمہ بن وقاص لیثی کہتے ہیں کہ میں نے عمر بن خطاب رضی اللہ عنہ کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اعمال کا دارومدار نیتوں پر ہے، ہر آدمی کو وہی ملے گا جس کی اس نے نیت کی چنانچہ جس کی ہجرت اللہ اور اس کے رسول کے لیے ہو گی تو اسی کی ہجرت اللہ اور رسول کے لیے مانی جائے گی، اور جس نے دنیا حاصل کرنے یا کسی عورت سے نکاح کرنے کی غرض سے ہجرت کی ہو گی تو اس کی ہجرت اسی چیز کے لیے مانی جائے گی جس کے لیے اس نے ہجرت کی\"۔","صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اعمال کا دارومدار نیت پر ہے۔ انسان کے لیے وہی ہے جو اس نے نیت کی ہو۔ سو جس نے ہجرت کی اللہ اور اس کے رسول کی طرف تو اس کی ہجرت اللہ اور اس کے رسول کی طرف ہے اور جس نے دنیا حاصل کرنے کے لیے ہجرت کی یا کسی عورت کے لیے کہ اس سے شادی کر لے تو اس کی ہجرت اسی کی طرف ہے جس کی طرف اس نے ہجرت کی ہے۔ “","f2":"کلمات کنایہ سے طلاق ہوجاتی ہے بشرطیکہ طلاق کی نیت ہو اگر یہ نیت نہ ہو تو نہیں ہوتی۔"}],[2202,"عبداللہ بن کعب بن مالک (جو کہ اپنے والد کعب رضی اللہ عنہ کے نابینا ہو جانے کے بعد ان کے قائد تھے) کہتے ہیں کہ میں نے (اپنے والد) کعب بن مالک سے سنا، پھر انہوں نے جنگ تبوک والا اپنا قصہ سنایا اس میں انہوں نے بیان کیا کہ جب پچاس دنوں میں سے چالیس دن گزر گئے تو رسول اللہ صلی اللہ علیہ وسلم کا قاصد آیا اور کہنے لگا کہ رسول اللہ صلی اللہ علیہ وسلم تمہیں حکم دیتے ہیں کہ تم اپنی بیوی سے علیحدہ رہو، میں نے پوچھا: کیا میں اسے طلاق دے دوں یا کیا کروں؟ اس نے کہا: نہیں بلکہ اس سے علیحدہ رہو اس کے قریب نہ جاؤ، چنانچہ میں نے اپنی بیوی سے کہہ دیا: تم اپنے میکے چلی جاؤ ۱؎ اور جب تک اللہ تعالی اس معاملہ کا فیصلہ نہ فرما دے وہیں رہنا۔\n§وضاحت\n۱؎ : یعنی انہوں نے اپنے اس قول سے طلاق کی نیت نہیں کی تو اس سے طلاق نہیں مراد لی گئی، اگر وہ طلاق کی نیت کرتے تو طلاق واقع ہو جاتی، کنائی الفاظ سے اسی وقت طلاق واقع ہوتی ہے جب اس کی نیت کی ہو۔","صحیح",{"u2":"جناب عبداللہ بن کعب اپنے والد کعب بن مالک رضی اللہ عنہ کے قائد تھے جبکہ وہ نابینا ہو چکے تھے۔ کہتے ہیں کہ میں نے کعب بن مالک رضی اللہ عنہ سے سنا اور تبوک والا واقعہ بیان کیا۔ بیان کیا کہ جب پچاس میں سے چالیس دن گزر گئے تو اچانک رسول اللہ صلی اللہ علیہ وسلم کا پیغام بر آیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم تمہیں حکم دیتے ہیں کہ اپنی بیوی سے علیحدہ ہو جاؤ۔ میں نے پوچھا: اسے طلاق دے دوں یا کیا کروں؟ کہا: نہیں، بلکہ اس سے علیحدہ رہو، اس کے قریب مت ہونا۔ چنانچہ میں نے اپنی بیوی سے کہا: اپنے گھر والوں کے پاس چلی جاؤ اور انہی کے پاس رہو، تاآنکہ اللہ تبارک و تعالیٰ اس معاملے میں کوئی فیصلہ فر دے۔","f2":"1.اگر شوہر بیوی کو یوں کہ دے کہ اپنے گھر والوں کے پاس چلی جائے۔ اور طلاق کی نیت کی ہو تو طلاق ہوجائے گی ورنہ نہیں۔\n2۔سیدنا کعب بن مالک رضی اللہ عنہ کا واقعہ ایک عظیم تاریخی واقعہ ہے۔تفسیر ابن کثیر میں سورہ توبہ کی آیت کریمہ:وعلي الثلاثة الذين خلفوا۔۔۔۔۔۔) (التوبہ:118) کے ضمن میں دیکھ لیا جائے۔"}],[2203,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں (اپنے عقد میں رہنے یا نہ رہنے کا) اختیار دیا تو ہم نے آپ صلی اللہ علیہ وسلم ہی کو اختیار کیا، پھر آپ نے اسے کچھ بھی شمار نہیں کیا ۱؎۔\n§وضاحت\n۱؎ : یعنی اسے طلاق قرار نہیں دیا، اکثر علماء کی یہی رائے ہے کہ جب شوہر بیوی کو اختیار دے اور وہ شوہر ہی کو اختیار کرلے تو کوئی طلاق واقع نہ ہوگی اور زید بن ثابت اور امام ابوحنیفہ کے نزدیک ایک طلاق پڑ جائے گی، مگر پہلی بات ہی ثابت ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو اختیار دیا تو ہم نے آپ صلی اللہ علیہ وسلم ہی کو اختیار کیا تھا، چنانچہ اس کو کچھ بھی شمار نہ کیا گیا۔","f2":"1۔اگر شوہر بیوی سے کہے مجھے اختیار کرلو یا اپنے آپ کو یا تمہیں اختیار ہے وغیرہ۔اور نیت طلاق کی ہو۔۔۔۔۔پھر اگر بیوی نے اپنے آپ کو اختیار کرلیا تو طلاق ہو جائے گی۔اور اگر شوہر کو اختیار کرلے تو نہیں ہوگی۔\n2۔فتوحات کے نتیجے میں جب مسلمانوں کی مالی حالت پہلے کی نسبت کچھ بہتر ہوگئی تو انصا رومہاجرین کی عورتوں کو دیکھ کر ازواج مطہرات نے بھی نان و نفقہ میں اضافہ کا مطالبہ کردیا۔نبی صلی اللہ علیہ وسلم چونکہ نہایت سادگی پسند تھے اس لیے ازواج مطہرات کے اس مطالبے پر سخت کبیدہ خاطر ہوئےاور بیویوں سے علیحدگی اختیار کرلی جو ایک مہینے تک جاری رہی۔بالآخر اللہ تعالی نےیہ آیت نازل فرمائی:(ياايها النبي قل لازواجك ان كنتن تردن الحيوة الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلاّ وان كنتن تردن الله ورسوله والدارالآخرة فان الله اعد للمحسنت منكن اجرا عظيما) (الاحزاب)٢٨ّ٢٩)\nاس کے بعد نبی صلی اللہ علیہ وسلم نے سیدنا عائشہ رضی اللہ عنہ کو یہ آیت سنا کر انہیں اختیار دیا۔تاہم انہیں کہا کہ اپنے طور پر فیصلہ کرنے کےکی بجائے اپنے والدین سے مشورے کے بعد کوئی اقدام کرنا۔حضرت عائشہ نے کہا:یہ کیسے ہوسکتا ہے کہ میں آپ کے بارے میں مشورہ کروں۔بلکہ میں اللہ اور اس کے رسول کو اختیار کرتی ہوں۔یہی بات دیگر ازواج مطہرات نے بھی کہی اور کسی نے بھی رسول اللہ صلی اللہ علیہ وسلم کو چھوڑ کردنیا کے عیش وآرام کو ترجیح نہیں دی۔(صحیح بخاری تفسیر سورہ احزاب۔ماخوذ از تفسیراحسن البیان)"}],[2204,"حماد بن زید کہتے ہیں کہ میں نے ایوب سے پوچھا: کیا آپ کو معلوم ہے کہ کسی اور نے بھی «أمرك بيدك» کے سلسلہ میں وہی بات کہی ہے جو حسن نے کہی تو انہوں نے کہا: نہیں، مگر وہی روایت ہے جسے ہم سے قتادہ نے بیان کیا، قتادہ نے کثیر مولی ابن سبرہ سے کثیر نے ابوسلمہ سے ابوسلمہ نے ابوہریرہ رضی اللہ عنہ سے ابوہریرہ رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے اسی طرح روایت کیا ہے۔ ایوب کہتے ہیں: تو کثیر ہمارے پاس آئے تو میں نے ان سے دریافت کیا، وہ بولے: میں نے تو کبھی یہ حدیث بیان نہیں کی، پھر میں نے قتادہ سے اس کا ذکر کیا تو انہوں نے کہا: ہاں کیوں نہیں انہوں نے اسے بیان کیا تھا لیکن وہ بھول گئے۔","ضعیف",{"u2":"حماد بن زید نے بیان کیا کہ میں نے ایوب سے پوچھا: آپ کو کسی کا علم ہے جو «أمرك بيدك» ” تیرا معاملہ تیرے ہاتھ میں ہے “ کی تفصیل میں حسن (بصری) کی طرح کہتا ہو؟ (ان کی بیان اگلی روایت میں آ رہا ہے۔) ایوب نے کہا: نہیں مگر وہی جو ہم کو قتادہ نے بہ سند کثیر مولی ابن سمرہ سے، ابوسلمہ سے، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس کی مانند بیان کیا۔ ایوب نے کہا: پھر کثیر مولی ابن سمرہ ہمارے پاس آئے تو میں نے ان سے (اس روایت کے متعلق) پوچھا۔ تو انہوں نے کہا: ” میں نے یہ کبھی بیان نہیں کیا۔ “ پھر میں نے ان کی یہ بات قتادہ سے کہی تو انہوں نے کہا کہ بیان تو کیا ہے مگر بھول گئے ہیں۔"}],[2205,"حسن سے «أمرك بيدك» کے سلسلہ میں مروی ہے کہ اس سے تین طلاق واقع ہو گی ۱؎۔\n§وضاحت\n۱؎ : «أمرك بيدك» کے معنی ہیں: تمہارا معاملہ تمہارے ہاتھ میں ہے، یعنی تمہیں اختیار ہے، بعض کے نزدیک اس سے ایک طلاق واقع ہوتی ہے، اور حسن بصری سے مروی ہے کہ اس سے تین طلاق واقع ہو گی، لیکن ام المومنین عائشہ رضی اللہ عنہا کی مذکورہ حدیث نمبر (۲۲۰۳) سے معلوم ہوا کہ کچھ واقع نہیں ہو گا۔","صحیح",{"u2":"قتادہ، جناب حسن بصری رضی اللہ عنہ سے بیان کرتے ہیں کہ «أمرك بيدك» ” تیرا معاملہ تیرے ہاتھ میں ہے “ یہ تین طلاقیں ہوتی ہیں۔","f2":"یہ تابعی کا قول ہے۔رسول اللہ صلی اللہ علیہ وسلم کا فرمان نہیں ہے علاوہ ازیں مذکورہ دونوں روایات سندا ضعیف ہیں۔بہرحال اگر شوہر نے اس جملے سے طلاق مراد لی ہو تو طلاو ہوجائے گی مگر ایک طلاق ہوگی۔"}],[2206,"نافع بن عجیر بن عبد یزید بن رکانہ سے روایت ہے کہ رکانہ بن عبد یزید نے اپنی بیوی سہیمہ کو طلاق بتہ ۱؎ (قطعی طلاق) دے دی، پھر نبی اکرم صلی اللہ علیہ وسلم کو اس کی خبر دی اور کہا: اللہ کی قسم! میں نے تو ایک ہی طلاق کی نیت کی تھی، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قسم اللہ کی تم نے صرف ایک کی نیت کی تھی؟\" رکانہ نے کہا: قسم اللہ کی میں نے صرف ایک کی نیت کی تھی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان کی بیوی انہیں واپس لوٹا دی، پھر انہوں نے اسے دوسری طلاق عمر رضی اللہ عنہ کے دور خلافت میں دی اور تیسری عثمان رضی اللہ عنہ کے دور خلافت میں۔\n§وضاحت\n۱؎ : البتہ : «بتّ» کا اسم مرہ ہے ، البتہ اور «بتات» کے معنی یقیناً اور قطعاً کے ہیں، طلاق بتہ یا البتہ ایسی طلاق جو یقینی اور قطعی طور پر پڑ چکی ہے ، اور صحیح احادیث کی روشنی میں تین طلاق سنت کے مطابق تین طہر میں دی جائے ، تو اس کے بعد یہ طلاق قطعی اور بتہ ہو گی، واضح رہے کہ یزید بن رکانہ کی یہ حدیث ضعیف ہے۔","ضعیف",{"u2":"نافع بن عجیر بن عبد یزید بن رکانہ سے مروی ہے کہ رکانہ بن عبد یزید نے اپنی بیوی سہیمہ کو بتہ طلاق دے دی۔ پھر نبی کریم صلی اللہ علیہ وسلم کو اس کی خبر دی اور کہا: قسم اللہ کی! میں نے اس سے ایک ہی کا ارادہ کیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” قسم سے! تو نے صرف ایک ہی کا ارادہ کیا تھا؟ “ رکانہ نے کہا: اللہ کی قسم! میں نے صرف ایک ہی کا ارادہ کیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کی بیوی کو اس پر لوٹا دیا۔ چنانچہ اس نے اس کو دوسری طلاق سیدنا عمر رضی اللہ عنہ کے دور میں اور تیسری طلاق سیدنا عثمان رضی اللہ عنہ کے دور میں دی۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کا ابتدائی حصہ ابراہیم بن خالد کلبی کے الفاظ ہیں اور آخری ابن السرح کے۔","f2":"’’بتۃ‘‘ بمعنی قطع (کاٹنا) ہے۔یعنی طلاق دینے والا کہے کہ میں تجھے بتہ طلاق دیتا ہوں۔یعنی ایسی طلاق جس میں رجوع نہیں اور اپنا تعلق پوری طرح کاٹتا ہوں۔اور اس کی مراد تین طلاق ہو۔"}],[2207,"اس سند سے بھی رکانہ بن عبد یزید سے یہی حدیث مرفوعاً مروی ہے۔","ضعیف",{"u2":"محمد بن یونس نسائی اپنی سند سے نافع بن عجیر سے، وہ رکانہ بن عبد یزید سے وہ نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث بیان کرتے ہیں۔"}],[2208,"رکانہ بن عبد یزید رضی اللہ عنہ سے روایت ہے کہ انہوں نے اپنی بیوی کو طلاق بتہ دے دی پھر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو آپ نے پوچھا: \"تم نے کیا نیت کی تھی؟\" انہوں نے کہا: ایک کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا اللہ کی قسم کھا کر کہہ رہے ہو؟\" انہوں نے کہا: ہاں اللہ کی قسم کھا کر کہہ رہا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس کا تم نے ارادہ کیا ہے وہی ہو گا\"۔ ابوداؤد کہتے ہیں: یہ روایت ابن جریج والی روایت سے زیادہ صحیح ہے جس میں ہے کہ رکانہ نے اپنی بیوی کو تین طلاق دی تھی کیونکہ یہ روایت ان کے اہل خانہ کی بیان کردہ ہے اور وہ حقیقت حال سے زیادہ واقف ہیں اور ابن جریج والی روایت بعض بنی رافع(جو ایک مجہول ہے) سے منقول ہے جسے وہ عکرمہ سے روایت کرتے ہیں اور وہ ابن عباس رضی اللہ عنہما سے، (دیکھئیے حدیث نمبر: ۲۰۹۶)","ضعیف",{"u2":"عبداللہ بن علی بن یزید بن رکانہ اپنے والد سے وہ اپنے دادا سے روایت کرتے ہیں کہ انہوں نے اپنی بیوی کو بتہ طلاق دے دی تھی۔ پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو آپ نے پوچھا ” تم نے کیا ارادہ کیا تھا؟ “ اس نے کہا: ایک کا۔ آپ نے کہا: ” اللہ کی قسم سے کہتے ہو؟ “ کہا: اللہ کی قسم سے کہتا ہوں۔ آپ نے فرمایا ” یہ وہی ہے جو تم نے ارادہ کیا۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ روایت ابن جریج کی (گذشتہ) روایت (2196) سے صحیح تر ہے کہ رکانہ نے اپنی بیوی کو تین طلاقیں دی تھیں کیونکہ یہ لوگ اس کے اپنے گھر والے ہیں، اور یہ اس کے متعلق بہتر جانتے ہیں۔ اور ابن جریج کی روایت ابورافع کے کسی بیٹے نے عکرمہ سے اور اس نے ابن عباس سے روایت کی ہے۔","f2":"اس روایت کی صحت میں اختلاف ہے۔ہمارے فاضل محقق شیخ زبیر علی زئی اور بعض محقیقین کے نزدیک ضعیف ہے ابوداؤد کا یہ کہنا ہے کہ یہ حدیث ابن جریج کی حدیث سے صحیح تر ہے کا یہ معنی ہے کہ یہ فی الواقع اصطلاحی تعریف کے مطابق صحیح ہے بلکہ مراد یہ ہے کہ یہ سند دوسری کے مقابلے میں قدرے بہتر ہے۔مگر حقیقتا دونوں ہی میں ضعف ہے۔(دیکھیے ارواءالغلیل:1437)"}],[2209,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے میری امت سے ان چیزوں کو معاف کر دیا ہے جنہیں وہ زبان پر نہ لائے یا ان پر عمل نہ کرے، اور ان چیزوں کو بھی جو اس کے دل میں گزرے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی دل میں طلاق کا صرف خیال کرنے سے طلاق واقع نہیں ہو گی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ اللہ عزوجل نے میری امت سے وہ امور معاف فر دیے ہیں جن کے متعلق انہوں نے گفتگو نہ کی ہو یا عمل نہ کیا ہو، اور وہ جس کے متعلق محض دل میں خیال آیا ہو۔ “","f2":"محض خیال کرنے سے یا دل میں پیچ وتاب کھاتے ہوئے طلاق دینا جبکہ زبان سے کچھ نہ بولا ہو طلاق نہیں ہوتی۔لیکن اپنے ان جذبات وخیالات کو کسی واضح تحریر میں نقل کریا ہو تو طلاق ہوجائے گی کیونکہ ہاتھ کا لکھنا عمل ہے۔خواہ بیوی کو تحریر دےیا دیے بغیر ہی ضائع کردے تو طلاق ہوجائے گی۔"}],[2210,"ابوتمیمہ ہجیمی سے روایت ہے کہ ایک شخص نے اپنی بیوی کو اے چھوٹی بہن! کہہ کر پکارا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا یہ تیری بہن ہے؟\" آپ صلی اللہ علیہ وسلم نے اسے ناپسند فرمایا اور اس سے منع کیا ۱؎۔\n§وضاحت\n۱؎ : اگرچہ اس کے کہنے سے وہ اس کی بہن نہیں ہو جائے گی مگر نامناسب بات زبان سے نکالنی مناسب نہیں، گو وہ اس کی دینی بہن ہو یا رشتہ میں بھی بہن کے مرتبہ کی ہو جیسے چچا یا پھوپھی یا خالہ کی بیٹی۔","ضعیف",{"u2":"ابو تمیمہ ھجیمی سے روایت ہے کہ ایک شخص نے اپنی بیوی کو کہا: اے بہن! تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کیا یہ تیری بہن ہے؟ “ پس آپ صلی اللہ علیہ وسلم نے اس انداز گفتگو کو ناپسند کیا اور اس سے منع فرمایا۔"}],[2211,"ابو تمیمہ سے روایت ہے، وہ اپنی قوم کے ایک شخص سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کو اپنی بیوی کو اے چھوٹی بہن! کہہ کر پکارتے ہوئے سنا تو آپ نے اس سے منع فرمایا۔ ابوداؤد کہتے ہیں: اسے عبدالعزیز بن مختار نے خالد سے خالد نے ابوعثمان سے اور ابوعثمان نے ابو تمیمہ سے اور ابوتمیمہ نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا ہے، نیز اسے شعبہ نے خالد سے خالد نے ایک شخص سے اس نے ابو تمیمہ سے اور ابو تمیمہ نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا ہے۔","ضعیف",{"u2":"ابو تمیمہ نے اپنی قوم کے ایک شخص سے روایت کیا کہ اس نے نبی کریم صلی اللہ علیہ وسلم سے سنا۔ جب کہ نبی کریم صلی اللہ علیہ وسلم نے ایک شخص کو سنا کہ وہ اپنی بیوی کہ کہہ رہا ہے: اے بہن! تو آپ نے اس کو اس سے منع فر دیا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں (کہ اس حدیث کی دو سندیں اور بھی ہیں) (1) عبدالعزیز بن مختار، خالد سے، وہ ابوعثمان سے، وہ ابو تمیمہ سے، وہ نبی کریم صلی اللہ علیہ وسلم سے۔ (2) شعبہ، خالد سے، وہ ایک شخص سے، وہ ابو تمیمہ سے، وہ نبی کریم صلی اللہ علیہ وسلم سے۔"}],[2212,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ابراہیم علیہ السلام نے صرف تین جھوٹ بولے ۱؎ جن میں سے دو اللہ تعالی کی ذات کے لیے تھے، پہلا جب انہوں نے کہا کہ میں بیمار ہوں ۲؎، دوسرا جب انہوں نے ایک سوال کے جواب میں کہا تھا: بلکہ یہ تو ان کے اس بڑے کی کارستانی ہے، تیسرا اس موقعہ پر جب کہ وہ ایک سرکش بادشاہ کے ملک سے گزر رہے تھے ایک مقام پر انہوں نے قیام فرمایا تو اس سرکش تک یہ بات پہنچی، اور اسے بتایا گیا کہ یہاں ایک شخص ٹھہرا ہوا ہے اور اس کے ساتھ ایک انتہائی خوبصورت عورت ہے، چنانچہ اس نے ابراہیم علیہ السلام کو بلوایا اور عورت کے بارے میں دریافت کیا تو انہوں نے کہا: \"یہ تو میری بہن ہے\"، جب وہ لوٹ کر بیوی کے پاس آئے تو انہوں نے بتایا کہ اس نے مجھ سے تمہارے بارے میں دریافت کیا تو میں نے اسے یہ بتایا ہے کہ تم میری بہن ہو کیونکہ آج میرے اور تمہارے علاوہ کوئی بھی مسلمان نہیں ہے لہٰذا تم میری دینی بہن ہو، تو تم اس کے پاس جا کر مجھے جھٹلا نہ دینا\"، اور پھر پوری حدیث بیان کی۔ ابوداؤد کہتے ہیں: شعیب بن ابی حمزہ نے ابوالزناد سے ابوالزناد نے اعرج سے، اعرج نے ابوہریرہ رضی اللہ عنہ سے، ابوہریرہ نے نبی اکرم صلی اللہ علیہ وسلم سے اسی طرح کی روایت کی ہے۔\n§وضاحت\n۱؎ : انہیں جھوٹ اس لئے کہا گیا ہے کہ ظاہر میں تینوں باتیں جھوٹ تھیں، لیکن حقیقت میں ابراہیم علیہ السلام نے یہ تینوں باتیں بطور تعریض و توریہ کہی تھیں، توریہ کا مطلب یہ ہے کہ آدمی ذومعنی گفتگو کرے، جس کا ایک ظاہری مفہوم ہو اور ایک باطنی، وہ اپنی گفتگو سے صحیح مقصود کی نیت کرے اور اس کی طرف نسبت کرنے میں جھوٹا نہ ہو، اگرچہ ظاہری الفاظ میں اور اس کی چیز کی طرف نسبت کرنے میں جسے مخاطب سمجھ رہا ہو جھوٹا ہو۔ ۲؎ : یہ بات ابراہیم علیہ السلام نے اس وقت کہی تھی جب ان کے شہر کے لوگ باہر میلے کے لئے جارہے تھے، ان سے بھی لوگوں نے چلنے کے لئے کہا، تو انہوں نے بہانہ کیا کہ میں بیمار ہوں، یہ بہانہ بتوں کو توڑنے کے لئے کیا تھا، پھر جب لوگ میلہ سے واپس آئے تو پوچھا بتوں کو کس نے توڑا ؟ ابراہیم وضاحت نے جواب دیا: ’’ بڑے بت نے توڑا ‘‘، اگرچہ یہ دونوں قول خلاف واقعہ تھے لیکن حکمت سے خالی نہ تھے، اللہ کی رضامندی کے واسطے تھے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ ” بلاشبہ ابراہیم علیہ السلام نے کبھی جھوٹ نہیں بولا مگر تین مواقع پر۔ دو بار اللہ عزوجل کے بارے میں۔ جبکہ آپ نے (قوم سے) کہا: تھا «إني سقيم» ” میں بیمار ہوں، یا میری طبیعت ناساز ہے۔ “ دوسری بار آپ نے کہا: تھا «بل فعله كبيرهم هذا» ” یہ تو ان کے اس بڑے نے کیا ہے۔ “ اور تیسری بار جب کہ وہ ایک جابر بادشاہ کے علاقے میں سے جا رہے تھے کہ ایک جگہ پڑاؤ کیا تو اس ظالم بادشاہ کو خبر دی گئی اور کہا گیا کہ یہاں ایک شخص اترا ہے اور اس کے ساتھ ایک عورت ہے انتہائی حسین و جمیل! تو اس نے سیدنا ابراہیم علیہ السلام کو بلا بھیجا اور خاتون کے متعلق پوچھا تو انہوں نے کہا: ” یہ میری بہن ہے۔ اور جب وہ اپنی اہلیہ کے پاس لوٹے تو اسے بتایا کہ اس نے مجھ سے تمہارے متعلق پوچھا ہے اور میں نے اس کو بتایا ہے کہ تو میری بہن ہے اور حقیقت یہ ہے کہ آج تیرے اور میرے علاوہ کوئی مسلمان نہیں ہے اور اللہ کی کتاب میں تو میری بہن ہے تو مجھے اس کے ہاں مت جھٹلانا۔ “ اور حدیث بیان کی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس حدیث کو شعیب بن ابی حمزہ نے ابو الزناد سے، انہوں نے اعرج سے، انہوں نے سیدنا ابوہریرہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مانند روایت کیا ہے۔","f2":"بیوی کو عادتایا محبت واکرام میں بہن کہنا کسی ظرح روا نہیں لیکن کہیں کسی واقعی شرعی ضرورت سے تو ریہ کے طور پر کہئ تو مباح ہے۔جیسے کہ حضرت ابراہیم علیہ السلام کے معروف قصے میں وارد ہوا ہے۔\n2۔حضرت ابراہیم علیہ السلام کے متعلق اس حدیث کو بعض متجدد ناقابل تسلیم کہتے ہیں۔بلکہ تمام ذخیرہ احادیث کو مشکوک عجمی سازش اور نہ معلوم کس کس لقب سے یاد کرتے ہیںان کا انداز تحریر وگفتگو کچھ یوں ہوتا ہے کہ قرآن مجید کے مقابلے میں اھادیچ کے راویوں کو یوں جھٹلاوینااور ضعیف کہنا زیادہ بہتر اور آسان ہےکجا یہ کہ قرآن مجید کی تغلیط کی جائے۔قرآن مجید نے حضرت ابراہیم علیہ السلام کے بارے میں بصراحت کہا ہےکہ (انه كان صديقا نبيا) (مريم:٤١) بلاشبہ وہ انتہائی سچے نبی تھے\nاس فکر کے حامل لوگوں کو ذرا غور کرنا چاہیے کہ قرآن مجید بھی تو ہمارے پاس ان راویوں کے ذریعے سے پہنچا ہے جن کے ذریعے سے احادیث پہنچی ہیں۔حق وصداقت اور دیانت کے اعلٰی ترین معیار کے عدیم المثال اصول قرآن مجید اور احادیث نبویہ کی نقل وروایت کے سلسلے میں ایک ہی ہیں۔جہاں جو فرق ہے وہ بصیرت اہل علم سے مخفی نہیں اور اس وجہ سے احادیث کو کئی درجات میں تقسیم کرکے ان کے حکم بھی الگ الگ بتائے گئے ہیں۔\nاس حدیث کو قرآن مجید کے واقعتا خلاف کہنادیانت علمی کے خلاف ہے۔تفسیر احسن البیان (از حافظ صلاح الدین یوسف رحمہ اللہ)میں سے درج ذیل اقتباس پیش کردینا مناسب ہے۔حافظ صاحب موصوف سورۃالانبیاء کی آیت 63(قال بل فعله كبيرهم هذادسئلوهم ان كانوا ينطقون) کے ذیل میں لکھتے ہیں (حضرت ابراہیم علیہ السلام کے ان اقوال کو) یقینا حقیقت کے اعتبار سے جھوٹ نہیں کہا جاسکتا۔گویہ کذب اللہ کے ہاں قابل مواخذہ نہیں ہے کیونکہ وہ اللہ ہی کے لیے بولے گئے ہیں۔درآں حالیکہ کوئی گناہ کا کام نہیں ہوسکتا۔اور یہ تب ہی ہوسکتا ہے کہ ظاہری طور پر کذب ہونے کے باوجود وہ حقیقتا کذب نہ ہو۔لیکن (چونکہ ان کا صدر وابراہیم خلیل اللہ علیہ السلام جیسے جلیل القدر جلیل القدر اور عظیم انسان سے ہوا لہذا)انہیں کذب سے تعبیر کردیا گیا ہے جیسے حضرت آدم علیہ السلام کے لیے عصي اور غوي کے الفاظ استعمال ہوئے ہیں۔حالانکہ خود قرآن ہی میں ان کے فعل اکل شجر کو نسیان اور ارادے کی کمزوری کا نتیجہ بھی بتلایا گیا ہے۔جس کا صاف مطلب یہ ہے کہ کسی کام کے دو پہلو بھی ہوسکتے ہیں۔من وجہ اس میں استحسان اور من وجہ ٰظاہری قباحت کا پہلو ہو۔حضرت ابراہیم علیہ السلام کایہ قول اس پہلو سے ظاہری طور پر کذب ہی ہے کہ واقعے کے خلاف تھا۔بتوں کو انہوں نے خود توڑا تھا۔لیکن ان کا انتساب بڑے بت کی طرف کیا۔مگر چونکہ مقصد ان کا تعریفیں اور اثبات توحید تھا اس لیے حقیقت کے اعتبار سے ہم اسے جھوٹ کے بجائے اتمام حجت کا ایک طریق اور مشرکین کی بے عقلی کے اثبات واظہار کا ایک انداز کہیں گے۔علاوہ ازیں حدیث میں ان کذبات کا ذکر جس ضمن میں آیا ہے وہ بھی قابل غور ہےاور وہ میدان حشر میں اللہ کے روبروجاکر سفارش کرنے سے اس لیے گریز کرنا کہ ان سے دنیا میں تین موقعوں پر لغزش کا صدور ہوا ہے۔درآں حالیکہ وہ لغزشیں نہیں ہیں یعنی حقیقت اور مقصد کے اعتبار سے وہ جھوٹ نہیں ہے۔مگر وہ اللہ کی عظمت وجلال کی وجہ سے اتنے خوف زدہ ہونگے کہ یہ باتیں جھوٹ کے ساتھ ظاہری مماثلت کی وجہ سے قابل گرفت نظر آئیں گی۔گویا حدیث کا مقصد حضرت ابراہیم علیہ السلام کو جھوٹا ثابت کرنا ہرگز نہیں ہے بلکہ اس کیفیت کا اظہار ہے جوقیامت والے دن خشیت الہی کی وجہ سے ان پر طاری ہوگی۔\nپھر لطف یہ ہے کہ ان تینوں باتوں میں سے دو تو خود قرآن میں مذکور ہیں حدیث میں تو صرف ان کا حوالہ ہے۔تیسری بات البتہ صرف حدیث میں مذکور ہے مگر جن حالات میں وہ بات کہی گئی ہےان حالات میں خود قرآن نے اظہار کفر تک اجازت دی ہے۔پس اگر حدیث پر اعتاب اتارناہے تو پہلے یہ حضرات قرآن پر اعتاب اتاریں۔اور اس سے اپنی براءت کا اظہار کریں۔"}],[2213,"سلمہ بن صخر بیاضی رضی اللہ عنہ کہتے ہیں کہ لوگوں کے مقابلے میں میں کچھ زیادہ ہی عورتوں کا شوقین تھا، جب ماہ رمضان آیا تو مجھے ڈر ہوا کہ اپنی بیوی کے ساتھ کوئی ایسی حرکت نہ کر بیٹھوں جس کی برائی صبح تک پیچھا نہ چھوڑے چنانچہ میں نے ماہ رمضان کے ختم ہونے تک کے لیے اس سے ظہار کر لیا۔ ایک رات کی بات ہے وہ میری خدمت کر رہی تھی کہ اچانک اس کے جسم کا کوئی حصہ نظر آ گیا تو میں اس سے صحبت کئے بغیر نہیں رہ سکا، پھر جب میں نے صبح کی تو میں اپنی قوم کے پاس آیا اور انہیں سارا ماجرا سنایا، نیز ان سے درخواست کی کہ وہ میرے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس چلیں، وہ کہنے لگے: اللہ کی قسم یہ نہیں ہو سکتا تو میں خود ہی آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، اور آپ صلی اللہ علیہ وسلم کو پوری بات بتائی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"سلمہ! تم نے ایسا کیا؟\" میں نے جواب دیا: ہاں اللہ کے رسول، مجھ سے یہ حرکت ہو گئی، دو بار اس طرح کہا، میں اللہ کا حکم بجا لانے کے لیے تیار ہوں، تو آپ میرے بارے میں حکم کیجئے جو اللہ آپ کو سجھائے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک گردن آزاد کرو\"، میں نے اپنی گردن پر ہاتھ مار کر کہا: اس ذات کی قسم جس نے آپ کو حق کے ساتھ بھیجا ہے اس کے علاوہ میرے پاس کوئی گردن نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو دو مہینے کے مسلسل روزے رکھو\"، میں نے کہا: میں تو روزے ہی کے سبب اس صورت حال سے دوچار ہوا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو پھر ساٹھ صاع کھجور ساٹھ مسکینوں کو کھلاؤ\"، میں نے جواب دیا: اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہم دونوں تو رات بھی بھوکے سوئے، ہمارے پاس کھانا ہی نہیں تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بنی زریق کے صدقے والے کے پاس جاؤ، وہ تمہیں اسے دے دیں گے اور ساٹھ صاع کھجور ساٹھ مسکینوں کو کھلا دینا اور جو بچے اسے تم خود کھا لینا، اور اپنے اہل و عیال کو کھلا دینا\"، اس کے بعد میں نے اپنی قوم کے پاس آ کر کہا: مجھے تمہارے پاس تنگی اور غلط رائے ملی جب کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گنجائش اور اچھی رائے ملی، آپ صلی اللہ علیہ وسلم نے مجھے یا میرے لیے تمہارے صدقے کا حکم فرمایا ہے۔\n§وضاحت\n۱؎ : ظہار یہ ے کہ آدمی اپنی بیوی سے کہے «أنت علي كظهر أمي» یعنی تو مجھ پر میری ماں کی پیٹھ کی طرح ہے، زمانہ جاہلیت میں ظہار کو طلاق سمجھا جاتا تھا، شریعت اسلامیہ میں ایسا کہنے والا گنہگار ہو گا اور اس پر کفارہ لازم ہو گا، جب تک کفارہ ادا نہ کر دے وہ بیوی کے قریب نہیں جا سکتا۔","حسن صحیح",{"u2":"سیدنا سلمہ بن صخر بیاضی رضی اللہ عنہ کہتے ہیں کہ میں ایسا شخص تھا جو عورتوں کو اس قدر آتا تھا کہ کوئی اور کیا آتا ہو گا۔ (بڑی جنسی قوت والا تھا۔) جب رمضان کا مہینہ آیا تو مجھے اندیشہ ہوا کہ بیوی کے ساتھ کچھ کر نہ بیٹھوں کہ صبح تک الگ ہی نہ ہو سکوں۔ سو میں نے اس سے ظہار کر لیا حتیٰ کہ رمضان گزر جائے۔ اتفاق سے ایک رات وہ میری خدمت کر رہی تھی کہ اس کے جسم کا کچھ حصہ میرے سامنے ظاہر ہوا تو میں ضبط نہ کر سکا اور اس کے اوپر چڑھ گیا۔ جب صبح ہوئی تو میں اپنی قوم کے پاس گیا اور انہیں اپنا قصہ بتایا اور انہیں کہا: میرے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس چلو، وہ کہنے لگے نہیں، قسم اللہ کی! (ہم تو نہیں جاتے) تو میں خود ہی نبی کریم صلی اللہ علیہ وسلم کے پاس حاضر ہو گیا اور آپ کو خبر دی۔ آپ نے کہا: ” سلمہ! ارے تو نے؟ “ میں نے عرض کیا: ہاں اے اللہ کے رسول! میں نے، دو بار کہا: اور میں اللہ کے حکم پر صابر (راضی) ہوں، میرے بارے میں جو اللہ آپ کو سجھائے فیصلہ فر دیجئیے۔ آپ نے فرمایا ” ایک گردن آزاد کر دو۔ “ میں نے کہا: قسم اللہ کی جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہے! میں تو بس اسی کا مالک ہوں اور میں نے اپنی گردن کی ایک جانب پر ہاتھ مارا۔ آپ نے فرمایا ” تو پھر دو مہینے متواتر روزے رکھو۔ “ میں نے کہا کہ اور یہ جو کچھ میرے ساتھ ہوا ہے، روزوں ہی کی وجہ سے تو ہوا ہے۔ آپ نے فرمایا ” تو ایک وسق (ساٹھ صاع) کھجور ساٹھ مسکینوں میں تقسیم کر دو۔ “ میں نے کہا: قسم اس ذات کی جس نے آپ کو حق کے ساتھ مبعوث فرمایا ہے! ہم نے تو بھوکے پیٹوں رات گزاری ہے، ہمارے پاس کھانے کو کچھ نہ تھا۔ آپ نے فرمایا ” تو بنی زریق کے صدقہ کرنے والے کے پاس چلے جاؤ، وہ تمہیں کچھ دے گا۔ تو اس میں سے ایک وسق کھجور ساٹھ مسکینوں کو کھلا دینا اور باقی تم اور تمہارا عیال کھا لے۔ “ چنانچہ میں اپنی قوم کے پاس واپس آیا اور انہیں کہا کہ میں نے تمہارے پاس تنگی اور بری رائے پائی، جبکہ نبی کریم صلی اللہ علیہ وسلم کے پاس سے وسعت اور بہترین رائے ملی ہے۔ آپ نے مجھے تمہارے صدقے (لینے) کا حکم فرمایا ہے۔ ابن العلاء نے کہا: ابن ادریس نے وضاحت کی کہ بیاضہ، بنی زریق کی ایک برادری کا نام ہے۔","f2":"1۔ایمان جب دل میں جاگزیں ہوجاتا ہے تومومن اللہ کی نافرمانی سے خائف رہتا ہے۔اور اگر کوئی خطا ہوجائے تو فورا اللہ کی طرف رجوع کرتا ہے۔اور یہی تفسیر ہے اس قول کی کہ ایمان خوف اور رجا(امید)کے درمیان ہے اور یہ واقعہ اس کی شاندار مثال ہے۔\n2۔ایک وسق میں ساٹھ صاع ہوتے ہیں اور ایک صاع میں چار مد اس حساب سے ایک صاع کا وزن تقریبا ڈھائی کلو اور ایک وسق کا وزن تین من اور تیس کلو اور بعض علماء کے نزدیک تین من اور چھ کلو ہوگا۔"}],[2214,"خویلہ بنت مالک بن ثعلبہ رضی اللہ عنہا کہتی ہیں کہ میرے شوہر اوس بن صامت نے مجھ سے ظہار کر لیا تو میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی، میں آپ سے شکایت کر رہی تھی اور رسول اللہ صلی اللہ علیہ وسلم مجھ سے ان کے بارے میں جھگڑ رہے تھے اور آپ صلی اللہ علیہ وسلم فرما رہے تھے: \"اللہ سے ڈر، وہ تیرا چچا زاد بھائی ہے\"، میں وہاں سے ہٹی بھی نہ تھی کہ یہ آیت نازل ہوئی: «قد سمع الله قول التي تجادلك في زوجها» \"اللہ تعالی نے اس عورت کی گفتگو سن لی ہے جو آپ سے اپنے شوہر کے متعلق جھگڑ رہی تھی\" (سورۃ المجادلہ: ۱)، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ ایک گردن آزاد کریں\"، کہنے لگیں: ان کے پاس نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر وہ دو مہینے کے پے در پے روزے رکھیں\"، کہنے لگیں: اللہ کے رسول! وہ بوڑھے کھوسٹ ہیں انہیں روزے کی طاقت نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو پھر وہ ساٹھ مسکینوں کو کھانا کھلائیں\"، کہنے لگیں: ان کے پاس صدقہ کرنے کے لیے کچھ بھی نہیں۔ کہتی ہیں: اسی وقت آپ صلی اللہ علیہ وسلم کے پاس کھجوروں کی ایک زنبیل آ گئی، میں نے کہا: اللہ کے رسول (آپ یہ دے دیجئیے) ایک اور زنبیل میں دے دوں گی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے ٹھیک ہی کہا ہے، لے جاؤ اور ان کی جانب سے ساٹھ مسکینوں کو کھلا دو، اور اپنے چچا زاد بھائی (یعنی شوہر) کے پاس لوٹ جاؤ\"۔ راوی کا بیان ہے کہ زنبیل ساٹھ صاع کی تھی۔ ابوداؤد کہتے ہیں: کہ اس عورت نے اپنے شوہر سے مشورہ کئے بغیر اس کی جانب سے کفارہ ادا کیا۔ ابوداؤد کہتے ہیں: یہ عبادہ بن صامت کے بھائی ہیں۔","حسن",{"u2":"سیدہ خویلہ بنت مالک بن ثعلبہ رضی اللہ عنہ ا بیان کرتی ہیں کہ میرے شوہر اوس بن صامت رضی اللہ عنہ نے مجھ سے ظہار کر لیا تو میں شکایت لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی۔ رسول اللہ صلی اللہ علیہ وسلم مجھ سے اس مسئلے میں بحث فرمانے لگے۔ آپ کہتے تھے ” اللہ سے ڈرو، وہ تمہارا چچا زاد ہے “ میں وہاں سے نہ ہٹی تھی کہ قرآن نازل ہو گیا «قد سمع الله قول التي تجادلك في زوجها» بیان کفارہ تک۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” وہ گردن آزاد کرے۔ “ اس نے کہا: اس کے پاس نہیں ہے۔ آپ نے فرمایا ” وہ دو مہینے متواتر روزے رکھے۔ “ اس نے کہا: اے اللہ کے رسول! وہ بہت بوڑھا ہے، روزے کہاں رکھ سکتا ہے؟ فرمایا ” تو ساٹھ مسکینوں کو کھانا کھلائے۔ “ اس نے کہا: اس کے پاس کچھ نہیں ہے کہ صدقہ کرے۔ بیان کرتی ہیں کہ اسی وقت آپ کے پاس ایک ٹوکرا کھجور کا آ گیا۔ میں نے کہا: اے اللہ کے رسول! میں ایک اور ٹوکرے (کھجور) سے اس کی مدد کر سکتی ہوں۔ آپ نے فرمایا ” بہت بہتر ہے۔ جاؤ اور اس کی طرف سے یہ ساٹھ مسکینوں کو کھلا دو اور اپنے چچا زاد کی طرف لوٹ جاؤ۔ “ (یحییٰ بن آدم نے) کہا کہ «العرق» (ٹوکرے) میں ساٹھ صاع کھجور آتی ہے۔ امام ابوداؤد رضی اللہ عنہ نے اس روایت میں کہا کہ اس (خاتون) نے اپنے شوہر کی طرف سے اس کے مشورے کے بغیر ہی کفارہ ادا کر دیا تھا۔ اور کہا کہ یہ (اوس بن صامت) عبادہ بن صامت رضی اللہ عنہ کے بھائی ہیں۔","f2":"1۔سورہ مجادلہ اور آیات کفارہ ظہار کا شان نزول یہی واقعہ ہے۔\n2۔رسول اللہ صلی اللہ علیہ وسلم اپنی مرضی سے کوئی شرعی امر نہیں فرماتے بلکہ سب اللہ عزوجل کی طرف سے وحی ہوتا ہے۔:(وما ينطق عن الهوي –ان هو الا وحي يوحي) (النجم:٣ ٤)\n3۔ کسی مسلمان کی طرف سے مالی کفارہ ادا کردیا جائے تو جائز ہے اور باعث اجر بھی۔\n4۔بیوی اپنے شوہر کو جو مالی طور پر مسکین ہو صدقہ اور زکوۃ دےدے تو جائز ہے مگر شوہر بیوی کو نہیں دے سکتا۔"}]]);
